# ----------------------------------------------------------------------
# [R9] ÍNDICE DO CÓDIGO (sumário no topo do arquivo, conferido pelo autoteste; --indice imprime, --indice-atualizar regrava)
# ----------------------------------------------------------------------

INDICE_INI = "ÍNDICE DO CÓDIGO (gerado por --indice-atualizar; conferido pelo autoteste; linha = onde começa o cabeçalho da seção)"
INDICE_FIM = "FIM DO ÍNDICE"


def indice_secoes(caminho=None):
    """[R9] Lista (linha do título, nível, título) das seções do arquivo: cabeçalhos de comentário de 3 partes ('# =====' / '# título' / '# =====' = seção; o mesmo com '# -----' = subseção)."""
    caminho = caminho or os.path.abspath(__file__)
    with open(caminho, encoding="utf-8") as f:
        L = f.read().split("\n")
    out, i = [], 0
    while i < len(L) - 2:
        for ch, nivel in (("=", 0), ("-", 1)):
            reg = "# " + ch * 5
            if L[i].startswith(reg) and L[i + 1].startswith("# ") and not L[i + 1].startswith(("# =====", "# -----")):
                j = i + 1
                while j < len(L) and L[j].startswith("# ") and not L[j].startswith(("# =====", "# -----")):
                    j += 1
                if j < len(L) and L[j].startswith(reg):
                    out.append((i + 2, nivel, L[i + 1][2:].strip()))
                    i = j
                    break
        i += 1
    return out


def indice_linhas(caminho=None):
    return [f"  {n:>6}  {'   · ' if nv else ''}{tit[:100]}" for n, nv, tit in indice_secoes(caminho)]


def _indice_do_docstring(texto: str):
    a, b = texto.find(INDICE_INI), texto.find(INDICE_FIM)
    if a < 0 or b < a:
        return None
    return [l for l in texto[a:b].split("\n")[1:] if l.strip()]


def indice_confere(caminho=None) -> bool:
    """[R9] O índice do docstring (no topo) é exatamente igual ao calculado agora a partir dos cabeçalhos de seção do arquivo."""
    caminho = caminho or os.path.abspath(__file__)
    try:
        with open(caminho, encoding="utf-8") as f:
            texto = f.read()
    except OSError:
        return True   # fonte indisponível (ex.: executável congelado): nada a conferir
    doc = _indice_do_docstring(texto)
    return doc is not None and doc == indice_linhas(caminho)


def atualizar_indice(caminho=None) -> int:
    """[R9] Regrava o índice do docstring (itera até estabilizar, pois o índice ocupa linhas fixas). Uso de desenvolvimento: --indice-atualizar."""
    caminho = caminho or os.path.abspath(__file__)
    for _ in range(4):
        with open(caminho, encoding="utf-8") as f:
            texto = f.read()
        a, b = texto.find(INDICE_INI), texto.find(INDICE_FIM)
        if a < 0 or b < a:
            print("marcadores do índice não encontrados")
            return 1
        novo = texto[:a] + INDICE_INI + "\n" + "\n".join(indice_linhas(caminho)) + "\n" + texto[b:]
        if novo == texto:
            print(f"índice em dia ({len(indice_linhas(caminho))} seções)")
            return 0
        with open(caminho, "w", encoding="utf-8") as f:
            f.write(novo)
    print("índice não estabilizou")
    return 1


