class Relatorio:
    """Acumula as linhas impressas no console para gravar em arquivo.
    Linhas 'voláteis' (tempo, data, nº de processos) ficam fora do DIGEST, que
    resume apenas os resultados numéricos e permite verificar que duas
    execuções com a mesma semente coincidem."""

    def __init__(self):
        self.linhas: list[str] = []
        self.estaveis: list[str] = []

    def log(self, txt: str = "", vol: bool = False):
        print(txt)
        self.linhas.append(txt)
        if not vol:
            self.estaveis.append(txt)

    def titulo(self, txt: str):
        self.log()
        self.log("=" * 78)
        self.log(txt)
        self.log("=" * 78)

    def sub(self, txt: str):
        self.log()
        self.log("--- " + txt)

    def digest(self) -> str:
        return hashlib.sha256("\n".join(self.estaveis).encode("utf-8")).hexdigest()[:16]

    def salvar(self, caminho: str):
        with open(caminho, "w", encoding="utf-8") as f:
            f.write("\n".join(self.linhas) + "\n")


def softmax(x, T: float = 1.0):
    z = np.asarray(x, float) / max(T, 1e-9)
    z = z - z.max()
    e = np.exp(z)
    return e / e.sum()


def sigmoide(x):
    return 1.0 / (1.0 + np.exp(-np.clip(x, -40, 40)))


def entropia(p, base: float = 2.0) -> float:
    p = np.asarray(p, float)
    p = p[p > 1e-12]
    if p.size == 0:
        return 0.0
    return float(-(p * np.log(p)).sum() / np.log(base))


def normalizar(v):
    v = np.asarray(v, float)
    return v / (np.linalg.norm(v) + 1e-12)


def cos(a, b) -> float:
    a = np.asarray(a, float).ravel()
    b = np.asarray(b, float).ravel()
    return float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b) + 1e-12))


def cos_duplo_angulo(a, b) -> float:
    """cos(2θ) = 2cos²θ − 1 (o 'cosseno duplicado')."""
    c = cos(a, b)
    return 2.0 * c * c - 1.0


def com_timeout(fn, segundos: float):
    """Executa fn numa thread daemon; devolve (valor, erro). Nunca trava o programa."""
    res: dict = {}

    def alvo():
        try:
            res["v"] = fn()
        except Exception as e:  # noqa: BLE001
            res["e"] = e

    t = threading.Thread(target=alvo, daemon=True)
    t.start()
    t.join(segundos)
    if t.is_alive():
        return None, "timeout"
    if "e" in res:
        return None, repr(res["e"])[:120]
    return res.get("v"), None


def wilson(k: int, n: int, z: float = 1.96):
    """Intervalo de Wilson (95%) para uma proporção k/n."""
    if n == 0:
        return 0.0, 1.0
    p = k / n
    d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d
    h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return max(0.0, c - h), min(1.0, c + h)


def boot_ic(d, n=4000, seed=0):
    d = np.asarray(d, float)
    rng = np.random.default_rng(seed)
    med = rng.choice(d, (n, len(d))).mean(1)
    return float(np.percentile(med, 2.5)), float(np.percentile(med, 97.5))


def p_sinal_invertido(d, n=10000, seed=0):
    """Teste de permutação pareado (inversão aleatória de sinais), bicaudal,
    para H0: média das diferenças = 0. Devolve o p-valor Monte Carlo."""
    d = np.asarray(d, float)
    rng = np.random.default_rng(seed)
    obs = abs(d.mean())
    sg = rng.choice([-1.0, 1.0], (n, len(d)))
    est = np.abs((sg * d).mean(1))
    return float((1 + np.sum(est >= obs - 1e-15)) / (n + 1))


def comparar_pareado(a, b, seed=0):
    """a − b por semente: média, IC95% bootstrap, p (permutação), vitórias/derrotas, dz."""
    d = np.asarray(a, float) - np.asarray(b, float)
    lo, hi = boot_ic(d, seed=seed)
    sd = float(d.std(ddof=1)) if len(d) > 1 else 0.0
    return {"media": float(d.mean()), "lo": lo, "hi": hi, "p": p_sinal_invertido(d, seed=seed),
            "vit": int((d > 0).sum()), "der": int((d < 0).sum()), "sd": sd,
            "dz": float(d.mean() / sd) if sd > 0 else 0.0, "n": len(d)}


def mapa_paralelo(fn, tarefas, jobs: int):
    """map ordenado, determinístico (cada tarefa só depende dos próprios
    argumentos). Usa processos 'fork' quando possível; qualquer falha cai no
    modo sequencial, com o mesmo resultado."""
    tarefas = list(tarefas)
    if jobs <= 1 or len(tarefas) <= 1:
        return [fn(t) for t in tarefas]
    try:
        import multiprocessing as mp
        with mp.get_context("fork").Pool(processes=min(jobs, len(tarefas))) as pool:
            return pool.map(fn, tarefas, chunksize=1)
    except Exception:  # noqa: BLE001
        return [fn(t) for t in tarefas]


class MetaObservador:
    """Observa o 'inobservável': registra vetores internos de cada componente
    e depois procura padrões emergentes entre componentes (PCA, k-means).
    Todos os vetores são normalizados e projetados a DIM dimensões por uma
    projeção aleatória fixa por tamanho (assim componentes de dimensões
    diferentes ficam comparáveis — com a ressalva de que isso é arbitrário,
    por isso há um controle com vetores aleatórios no BLOCO 10)."""

    DIM = 8

    def __init__(self, seed: int):
        self.reg: dict[str, list[np.ndarray]] = {}
        self._proj: dict[int, np.ndarray] = {}
        self._rng = np.random.default_rng(seed + 999)

    def registrar(self, componente: str, vetor):
        v = np.nan_to_num(np.asarray(vetor, float).ravel())
        if v.size == 0:
            return
        self.reg.setdefault(componente, []).append(v)

    def projetar(self, v):
        n = len(v)
        if n not in self._proj:
            self._proj[n] = self._rng.standard_normal((self.DIM, n)) / math.sqrt(n)
        return self._proj[n] @ normalizar(v)

    def matriz(self, max_por_comp: int = 30):
        X, rot = [], []
        for nome, lista in self.reg.items():
            if len(lista) > max_por_comp:
                idx = np.linspace(0, len(lista) - 1, max_por_comp).astype(int)
                lista = [lista[i] for i in idx]
            for v in lista:
                X.append(self.projetar(v))
                rot.append(nome)
        return np.array(X), rot


