# BLOCO 2 (a) — pré-registro, tokenização e corpus semântico
# ----------------------------------------------------------------------

def hash_prereg() -> str:
    obj = {"par": PAR_RETIDOS_R3, "sim": SIMILARIDADE_R3, "int": INTRUSO_R3, "txt": TEXTO_TESTE_R3}
    s = json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(s.encode("utf-8")).hexdigest()


