STOP_GLOSA = set("the and for that with from this which who whose has have had can one its his her their into very also used often such like other some "
                 "are was were been being not but all any more most than then them they you your our out off over under about between after before while where "
                 "when what how why she him let may make made does did".split()) | set(STOP)


def conteudo_glosa(txt: str) -> list:
    return [t for t in tokenizar(txt) if len(t) >= 3 and t not in STOP_GLOSA]


def svd_rand(M, rank: int, seed: int = 2026, over: int = 16, n_iter: int = 3):
    """SVD randomizado (Halko et al.) determinístico: devolve (U[:, :rank], S[:rank]). Ordens de grandeza mais rápido que o SVD exato em 1800×1800."""
    rng = np.random.default_rng(seed)
    Y = M @ rng.standard_normal((M.shape[1], rank + over))
    for _ in range(n_iter):
        Q, _ = np.linalg.qr(Y)
        Q2, _ = np.linalg.qr(M.T @ Q)
        Y = M @ Q2
    Q, _ = np.linalg.qr(Y)
    Ub, S, _ = np.linalg.svd(Q.T @ M, full_matrices=False)
    return (Q @ Ub)[:, :rank], S[:rank]


class EspacoR5:
    """Corpus C1 (C0 da R4 + FRASES) ou C2 (C1 + GLOSAS como frases de definição). Co-ocorrências por janela via pares pré-computados (peso 1/d)."""
    JMAX = 8

    def __init__(self, dados: dict, variante: str):
        sents = construir_corpus_semantico()
        for f in dados["frases"]:
            sents.append(tokenizar(f))
        if variante == "C2":
            for w, g in sorted(dados["glosas"].items()):
                sents.append([w] + tokenizar(g))
        self.variante, self.n_frases = variante, len(sents)
        self.vocab = sorted({w for s in sents for w in s})
        self.idx = {w: i for i, w in enumerate(self.vocab)}
        self.V = len(self.vocab)
        a_, b_, d_ = [], [], []
        for s in sents:
            ids = np.array([self.idx[w] for w in s])
            for d in range(1, self.JMAX + 1):
                if len(ids) > d:
                    a_.append(ids[:-d]); b_.append(ids[d:]); d_.append(np.full(len(ids) - d, d))
        self.pa, self.pb, self.pd = np.concatenate(a_), np.concatenate(b_), np.concatenate(d_)
        self.L = self._idioma(dados)
        self._svd: dict = {}
        self._C: dict = {}

    def _idioma(self, dados):
        cont: dict = {}
        for pt, en in list(CORPUS_PAR) + list(CORPUS_PAR2):
            for w in tokenizar(pt):
                cont.setdefault(w, [0, 0])[0] += 1
            for w in tokenizar(en):
                cont.setdefault(w, [0, 0])[1] += 1
        decl = {p: (0 if l == "pt" else 1) for p, l, _c, _d in SEMENTE}
        for p, l, _c, d in SEMENTE:
            for w in tokenizar(d):
                cont.setdefault(w, [0, 0])[0 if l == "pt" else 1] += 1
        for f in dados["frases"]:
            for w in tokenizar(f):
                cont.setdefault(w, [0, 0])[1] += 1
        if self.variante == "C2":
            for w, g in dados["glosas"].items():
                for t in [w] + tokenizar(g):
                    cont.setdefault(t, [0, 0])[1] += 1
        L = np.zeros(self.V, int)
        for w, i in self.idx.items():
            c = cont.get(w, [0, 0])
            L[i] = decl[w] if w in decl else (0 if c[0] >= c[1] else 1)
        return L

    def ppmi(self, janela: int, k: int, alpha: float = 0.75):
        key = (janela, k)
        if key not in self._C:
            m = self.pd <= janela
            a, b, w = self.pa[m], self.pb[m], 1.0 / self.pd[m]
            C = np.zeros((self.V, self.V))
            np.add.at(C, (a, b), w)
            np.add.at(C, (b, a), w)
            tot = C.sum()
            pw = C.sum(1) / tot
            pc = C.sum(0) ** alpha
            pc = pc / pc.sum()
            with np.errstate(divide="ignore", invalid="ignore"):
                pmi = np.log((C / tot) / (pw[:, None] * pc[None, :])) - math.log(k)
            self._C[key] = np.where(np.isfinite(pmi) & (pmi > 0), pmi, 0.0)
        return self._C[key]

    def svd(self, janela: int, k: int):
        key = (janela, k)
        if key not in self._svd:
            self._svd[key] = svd_rand(self.ppmi(janela, k), 72)
        return self._svd[key]

    def modelo(self, janela: int, k: int, p: float, dim: int):
        U, S = self.svd(janela, k)
        return ModeloR5(self, U[:, :dim] * S[:dim] ** p)


class ModeloR5:
    """PPMI+SVD (fatia de dim colunas) + centralização por língua + Procrustes pt→en pelos MESMOS 70 pares de ponte da R4."""

    def __init__(self, esp: EspacoR5, E):
        self.esp, self.dim = esp, E.shape[1]
        L = esp.L
        mu = [E[L == q].mean(0) for q in (0, 1)]
        pares = [(p, e) for p, e in PARES_PONTE if p in esp.idx and e in esp.idx]
        Am = np.array([E[esp.idx[p]] - mu[0] for p, _ in pares])
        Bm = np.array([E[esp.idx[e]] - mu[1] for _, e in pares])
        Uo, _, Vt = np.linalg.svd(Am.T @ Bm)
        R = Uo @ Vt
        self.E = _unitarias(np.where(L[:, None] == 0, (E - mu[0]) @ R, E - mu[1]))
        self.idx = esp.idx

    def vetor(self, w: str):
        i = self.idx.get(w)
        if i is not None:
            return self.E[i]
        return normalizar(np.random.default_rng(zlib.crc32(("oov::" + w).encode())).standard_normal(self.dim))


class ModeloGlosa:
    """v = norm((1−λ)·v_base + λ·g), g = média ponderada por idf dos vetores-base das palavras de conteúdo da glosa (glosa da tradução inglesa para palavras PT)."""

    def __init__(self, base, dados: dict, lam: float, embaralhar=None):
        self.base, self.lam = base, lam
        self.pt_en = {p: e for p, e in LEXICO_PARES}
        gl = dict(dados["glosas"])
        if embaralhar is not None:
            ks = sorted(gl)
            perm = np.random.default_rng(embaralhar).permutation(len(ks))
            gl = {ks[i]: dados["glosas"][ks[perm[i]]] for i in range(len(ks))}
        toks = {w: conteudo_glosa(g) for w, g in gl.items()}
        df: dict = {}
        for t in toks.values():
            for x in set(t):
                df[x] = df.get(x, 0) + 1
        N = len(toks)
        idf = {x: math.log((N + 1) / (c + 1)) + 1.0 for x, c in df.items()}
        self.g: dict = {}
        for w, t in toks.items():
            v, s = np.zeros(base.dim), 0.0
            for x in t:
                if x in base.idx:
                    v += idf[x] * base.vetor(x)
                    s += idf[x]
            if s > 0:
                self.g[w] = normalizar(v)
        self.dim, self.idx = base.dim, base.idx

    def vetor(self, w: str):
        v0 = self.base.vetor(w)
        k = w if w in self.g else self.pt_en.get(w)
        if k in self.g and self.lam > 0:
            return normalizar((1 - self.lam) * v0 + self.lam * self.g[k])
        return v0


class ModeloEspecializado:
    """Retrofitting (Faruqui, 10 iterações) das palavras de RELACOES + mapa linear V0→V' (cumeeira com regularização em direção à identidade),
    ajustado SÓ nessas palavras e aplicado a TODAS (generaliza para palavras não vistas)."""

    def __init__(self, base, relacoes: dict, beta: float, mu: float, embaralhar=None):
        self.base = base
        grupos = [list(v) for _, v in sorted(relacoes.items())]
        if embaralhar is not None:
            todas = [w for g in grupos for w in g]
            perm = np.random.default_rng(embaralhar).permutation(len(todas))
            novo, k = [], 0
            for g in grupos:
                novo.append([todas[perm[k + j]] for j in range(len(g))])
                k += len(g)
            grupos = novo
        pal = [w for g in grupos for w in g]
        V0 = np.array([base.vetor(w) for w in pal])
        V, pos, lim = V0.copy(), 0, []
        for g in grupos:
            lim.append((pos, pos + len(g)))
            pos += len(g)
        for _ in range(10):
            Vn = V.copy()
            for a, b in lim:
                n = b - a
                if n > 1:
                    S = V[a:b].sum(0)
                    Vn[a:b] = (V0[a:b] + beta * (S - V[a:b]) / (n - 1)) / (1 + beta)
            V = Vn
        d = V0.shape[1]
        self.W = np.eye(d) + np.linalg.solve(V0.T @ V0 + mu * np.eye(d), V0.T @ (V - V0))
        self.dim, self.idx = d, base.idx

    def vetor(self, w: str):
        return normalizar(self.base.vetor(w) @ self.W)


class ModeloSGNS:
    """word2vec skip-gram com amostragem negativa (numpy puro, minilotes, semente fixa, SEM ajuste). Só EN; teto exploratório de uma técnica diferente."""

    def __init__(self, esp: EspacoR5, dim: int = 32, janela: int = 4, neg: int = 5, epocas: int = 8, lote: int = 4096, lr: float = 0.05, seed: int = 7):
        rng = np.random.default_rng(seed)
        m = esp.pd <= janela
        a = np.concatenate([esp.pa[m], esp.pb[m]])
        b = np.concatenate([esp.pb[m], esp.pa[m]])
        V = esp.V
        freq = np.bincount(a, minlength=V).astype(float) ** 0.75
        pn = freq / freq.sum()
        W = (rng.random((V, dim)) - 0.5) / dim
        Cc = np.zeros((V, dim))
        n = len(a)
        for ep in range(epocas):
            perm = rng.permutation(n)
            lr_e = lr * (1.0 - ep / epocas) + 0.005
            for s in range(0, n, lote):
                ii = perm[s:s + lote]
                c, o = a[ii], b[ii]
                ng = rng.choice(V, size=(len(ii), neg), p=pn)
                wc = W[c]
                pos = 1.0 / (1.0 + np.exp(-np.clip((wc * Cc[o]).sum(1), -8, 8)))
                gpos = (pos - 1.0)[:, None]
                wn_ = Cc[ng]
                sn = 1.0 / (1.0 + np.exp(-np.clip(np.einsum("bd,bkd->bk", wc, wn_), -8, 8)))
                dW = gpos * Cc[o] + np.einsum("bk,bkd->bd", sn, wn_)
                np.add.at(Cc, o, -lr_e * gpos * wc)
                np.add.at(Cc, ng.ravel(), -lr_e * (sn[:, :, None] * wc[:, None, :]).reshape(-1, dim))
                np.add.at(W, c, -lr_e * dW)
        self.E = _unitarias(W - W.mean(0))
        self.idx, self.dim = esp.idx, dim

    def vetor(self, w: str):
        i = self.idx.get(w)
        return self.E[i] if i is not None else normalizar(np.random.default_rng(zlib.crc32(("oov::" + w).encode())).standard_normal(self.dim))


def pares_de(wn: dict):
    """Todos os pares de mesma classe (n–n, v–v) das palavras de um gabarito `wn` (ordem alfabética). Devolve (palavras, ij, wup, caminho, pos)."""
    pal = sorted(wn)
    ij, wu, ca, ps = [], [], [], []
    for i in range(len(pal)):
        for j in range(i + 1, len(pal)):
            if wn[pal[i]]["pos"] == wn[pal[j]]["pos"]:
                ij.append((i, j))
                wu.append(wup_wn(wn, pal[i], pal[j]))
                ca.append(caminho_wn(wn, pal[i], pal[j]))
                ps.append(wn[pal[i]]["pos"])
    return pal, np.array(ij), np.array(wu), np.array(ca), np.array(ps)


class AvaliadorRho:
    """ρ de Spearman rápido contra um ouro fixo (postos do ouro pré-computados)."""

    def __init__(self, wn: dict):
        self.pal, self.ij, self.ouro, self.ouro_c, self.ps = pares_de(wn)
        ro = ranks_medios(self.ouro)
        self.ro_c = ro - ro.mean()
        self.n = math.sqrt(float((self.ro_c ** 2).sum()))

    def rho(self, vet, palavras=None) -> float:
        pal = palavras or self.pal
        M = _unitarias(np.array([vet(w) for w in pal]))
        s = np.einsum("ij,ij->i", M[self.ij[:, 0]], M[self.ij[:, 1]])
        r = ranks_medios(s)
        r = r - r.mean()
        d = math.sqrt(float((r ** 2).sum())) * self.n
        return float((r * self.ro_c).sum() / d) if d > 0 else 0.0


GRADE_JANELA, GRADE_K, GRADE_P, GRADE_DIM = (2, 4, 8), (1, 5), (0.0, 0.5, 1.0), (8, 16, 32, 64)
GRADE_LAMBDA, GRADE_BETA, GRADE_MU = (0.0, 0.25, 0.5, 0.75, 1.0), (0.5, 1.0, 2.0), (0.1, 1.0, 10.0)


def grade_dev(esp: EspacoR5, av: AvaliadorRho):
    """Grade pré-registrada (72 configs): devolve (lista [(ρ_dev, dim, janela, k, p)], melhor). Regra: maior ρ; empate: menor dim, janela, k, p."""
    out = []
    for j in GRADE_JANELA:
        for k in GRADE_K:
            for p in GRADE_P:
                for dim in GRADE_DIM:
                    out.append((av.rho(esp.modelo(j, k, p, dim).vetor), dim, j, k, p))
    melhor = sorted(out, key=lambda t: (-round(t[0], 12), t[1], t[2], t[3], t[4]))[0]
    return out, melhor


def _job_boot_v(args):
    """Um bloco de reamostras do bootstrap por palavras: devolve {nome: array de ρ por reamostra}."""
    sims, ouro, ij, c = args
    ro = _RankPonderado(ouro)
    rms = {k: _RankPonderado(v) for k, v in sims.items()}

    def postos_lote(rk, W):
        cw = np.concatenate([np.zeros((W.shape[0], 1)), np.cumsum(W[:, rk.o], axis=1)], axis=1)
        r_ord = 0.5 * (cw[:, rk.gs] + cw[:, rk.ge + 1]) + 0.5
        return r_ord[:, rk.inv]

    W = c[:, ij[:, 0]] * c[:, ij[:, 1]]
    sw = W.sum(1)
    ror = postos_lote(ro, W)
    my = (W * ror).sum(1) / sw
    dy = ror - my[:, None]
    vy = (W * dy * dy).sum(1)
    out = {}
    for k, rm in rms.items():
        rx = postos_lote(rm, W)
        mx = (W * rx).sum(1) / sw
        dx = rx - mx[:, None]
        cxy = (W * dx * dy).sum(1)
        vx = (W * dx * dx).sum(1)
        ok = (vx > 0) & (vy > 0)
        out[k] = np.where(ok, cxy / np.sqrt(np.where(ok, vx * vy, 1.0)), 0.0)
    return out


def rho_boot_palavras_v(sims: dict, ouro, ij, n_pal: int, n_boot: int = 4000, seed: int = 4242, bloco: int = 250, jobs: int = 1):
    """[R5/perf] Mesma estatística de rho_boot_palavras (bootstrap por PALAVRAS, postos ponderados), vetorizada em blocos de reamostras e
    paralelizável por bloco (blocos de tamanho FIXO → resultado independente de `jobs`). Mesmas reamostras (mesma semente) → mesmas
    distribuições até arredondamento de ponto flutuante. Devolve {nome: (ρ, lo, hi, boot)}."""
    ouro = np.asarray(ouro, float)
    ro = _RankPonderado(ouro)
    rms = {k: _RankPonderado(v) for k, v in sims.items()}
    w1 = np.ones(len(ouro))
    obs = {k: _corr_pond(rm.postos(w1), ro.postos(w1), w1) for k, rm in rms.items()}
    rng = np.random.default_rng(seed)
    cnt = rng.multinomial(n_pal, np.full(n_pal, 1.0 / n_pal), size=n_boot).astype(float)
    tarefas = [(sims, ouro, ij, cnt[b0:b0 + bloco]) for b0 in range(0, n_boot, bloco)]
    partes = mapa_paralelo(_job_boot_v, tarefas, jobs)
    boot = {k: np.concatenate([p[k] for p in partes]) for k in sims}
    return {k: (obs[k], float(np.percentile(boot[k], 2.5)), float(np.percentile(boot[k], 97.5)), boot[k]) for k in sims}


def mcnemar_exato_unicaudal(b: int, c: int) -> float:
    """McNemar exato unicaudal: b = só o modelo A acertou, c = só o B acertou; H1: A melhor. p = P(X ≥ b), X~Bin(b+c, 1/2)."""
    return binom_cauda(b, b + c, 0.5) if b + c > 0 else 1.0


def bloco2d(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 2d — [R5] Similaridade graduada: corpus ampliado, ajuste num DEV separado, glosas, especialização por relações disjuntas (pré-registrado, avaliado UMA vez)")
    lake = ctx.lake
    dados, dev, g4 = dados_r5(), gabarito_dev_r5(), gabarito_r4()
    wn4 = g4["wn"]
    ok_d = hashlib.sha256(DADOS_R5_JSON.encode("utf-8")).hexdigest() == DADOS_R5_SHA256
    ok_v = hashlib.sha256(DEV_R5_JSON.encode("utf-8")).hexdigest() == DEV_R5_SHA256
    ok_p = hashlib.sha256(PREREG_R5_CORPO.encode("utf-8")).hexdigest() == PREREG_R5_CORPO_SHA256
    rel_pal = {w for g in dados["relacoes"].values() for w in g}
    ev_pal = {e for _, e in LEXICO_PARES}
    disj = not (rel_pal & set(dev["wn"])) and not (rel_pal & ev_pal) and not (set(dev["wn"]) & ev_pal)
    rep.log(f"Integridade (sha256): dados R5 {DADOS_R5_SHA256[:12]}… {'(CONFERE)' if ok_d else '(!! NÃO CONFERE)'} | gabarito DEV {DEV_R5_SHA256[:12]}… {'(CONFERE)' if ok_v else '(!! NÃO CONFERE)'} | "
            f"pré-registro R5 (corpo) {PREREG_R5_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r5.txt, gravado às 13:42 PT antes do código de modelo R5)' if ok_p else '(!! NÃO CONFERE)'} | "
            f"conjuntos DISJUNTOS (relações {len(rel_pal)} × DEV {len(dev['wn'])} × avaliação {len(ev_pal)} palavras): {'sim' if disj else '!! NÃO'}.")
    rep.log("Objetivo: subir o ρ de Spearman contra o gabarito WordNet da R4 (ρ_EN(R4)=+0,033) SEM treinar no gabarito de avaliação: (i) corpus maior/mais diverso (C1: +227 frases livres; C2: +261 glosas como definições), "
            "(ii) janela/SPPMI/p/dim escolhidos num gabarito DEV (67 palavras WordNet DISJUNTAS), (iii) vetores de glosa (definições escritas por mim, NÃO copiadas do WordNet), "
            "(iv) especialização (retrofitting + mapa linear) usando só relações entre 92 palavras DISJUNTAS das de avaliação e do DEV.")
    rep.sub("HIPÓTESES PRÉ-REGISTRADAS (PREREG_R5_CORPO; família F1–F7, Holm sobre p unicaudais bootstrap por palavras, α=0,05)")
    for l in PREREG_R5_CORPO.split("\n"):
        if l.startswith("  F") or l.startswith("Expectativa registrada antes de rodar: F1"):
            rep.log("  " + l.strip())
    # ---------------- DEV: grade e seleção ----------------
    t0 = time.time()
    av = AvaliadorRho(dev["wn"])
    rho_dev_m0 = av.rho(lake.emb.vetor)
    rep.sub(f"AJUSTE NO DEV (67 palavras WordNet disjuntas; {len(av.ij)} pares; só o DEV é usado para escolher hiperparâmetros)")
    esp = {v: EspacoR5(dados, v) for v in ("C1", "C2")}
    rep.log(f"Corpora: C0 (R4) = {len(construir_corpus_semantico())} frases; C1 = {esp['C1'].n_frases} frases, vocabulário {esp['C1'].V}; C2 = {esp['C2'].n_frases} frases, vocabulário {esp['C2'].V}. "
            f"ρ_DEV de M0 (embedding R4; 62 de 67 palavras DEV são OOV → subpalavras) = {rho_dev_m0:+.3f}.")
    sel = {}
    for v in ("C1", "C2"):
        out, mel = grade_dev(esp[v], av)
        sel[v] = mel
        top = sorted(out, key=lambda t: (-round(t[0], 12), t[1], t[2], t[3], t[4]))[:5]
        rep.log(f"  grade {v} (72 configs): melhor ρ_DEV={mel[0]:+.3f} com dim={mel[1]} janela={mel[2]} k={mel[3]} p={mel[4]}; top-5: " + " | ".join(f"{a:+.3f}(d{d},j{j},k{k},p{p})" for a, d, j, k, p in top)
                + f"; mediana da grade={np.median([o[0] for o in out]):+.3f}, pior={min(o[0] for o in out):+.3f}")
    m1 = esp["C1"].modelo(sel["C1"][2], sel["C1"][3], sel["C1"][4], sel["C1"][1])
    ctx.res["_r5_m1"] = m1   # usado pelo BLOCO 11 (vetores M1 escolhidos no DEV)
    m2 = esp["C2"].modelo(sel["C2"][2], sel["C2"][3], sel["C2"][4], sel["C2"][1])
    r3 = [(av.rho(ModeloGlosa(m1, dados, lam).vetor), lam) for lam in GRADE_LAMBDA]
    lam3 = sorted(r3, key=lambda t: (-round(t[0], 12), t[1]))[0]
    m3 = ModeloGlosa(m1, dados, lam3[1])
    rep.log(f"  M3 (glosa sobre M1): ρ_DEV por λ = " + ", ".join(f"λ={l}:{r:+.3f}" for r, l in r3) + f" → λ*={lam3[1]}")
    r4_ = [(av.rho(ModeloEspecializado(m1, dados["relacoes"], b, u).vetor), b, u) for b in GRADE_BETA for u in GRADE_MU]
    b4 = sorted(r4_, key=lambda t: (-round(t[0], 12), t[1], t[2]))[0]
    m4 = ModeloEspecializado(m1, dados["relacoes"], b4[1], b4[2])
    rep.log(f"  M4 (especialização sobre M1): ρ_DEV por (β,μ) = " + ", ".join(f"({b},{u}):{r:+.3f}" for r, b, u in r4_) + f" → β*={b4[1]}, μ*={b4[2]}")
    r5_ = [(av.rho(ModeloEspecializado(m3, dados["relacoes"], b, u).vetor), b, u) for b in GRADE_BETA for u in GRADE_MU]
    b5 = sorted(r5_, key=lambda t: (-round(t[0], 12), t[1], t[2]))[0]
    m5 = ModeloEspecializado(m3, dados["relacoes"], b5[1], b5[2])
    rep.log(f"  M5 (especialização sobre M3): ρ_DEV por (β,μ) = " + ", ".join(f"({b},{u}):{r:+.3f}" for r, b, u in r5_) + f" → β*={b5[1]}, μ*={b5[2]}")
    dev_rho = {"M1": sel["C1"][0], "M2": sel["C2"][0], "M3": lam3[0], "M4": b4[0], "M5": b5[0]}
    ordem = ["M1", "M2", "M3", "M4", "M5"]
    estrela = sorted(ordem, key=lambda n: (-round(dev_rho[n], 12), ordem.index(n)))[0]
    rep.log("  ρ_DEV de cada modelo com a sua configuração escolhida: " + " | ".join(f"{n}={dev_rho[n]:+.3f}" for n in ordem) + f"  →  M* (maior ρ_DEV, regra pré-registrada) = {estrela}")
    # exploratórios SÓ no DEV (não pré-registrados): M2 + glosa
    r2g = [(av.rho(ModeloGlosa(m2, dados, lam).vetor), lam) for lam in GRADE_LAMBDA]
    lam2g = sorted(r2g, key=lambda t: (-round(t[0], 12), t[1]))[0]
    m2g = ModeloGlosa(m2, dados, lam2g[1])
    rep.log(f"  [PÓS-HOC, não pré-registrado] M2g = M2 + vetores de glosa: ρ_DEV por λ = " + ", ".join(f"λ={l}:{r:+.3f}" for r, l in r2g) + f" → λ*={lam2g[1]} (entra só como EXPLORATÓRIO na avaliação).")
    rep.log(f"(tempo do ajuste no DEV: {time.time() - t0:.1f}s)", vol=True)
    mods = {"M0": lake.emb.vetor, "M1": m1.vetor, "M2": m2.vetor, "M3": m3.vetor, "M4": m4.vetor, "M5": m5.vetor}
    ctx.res["_r5_m2"], ctx.res["_r5_m2g"] = m2, m2g   # [R6] congelados: usados pelos BLOCOS 2e e 12
    ctx.res["r5_dev"] = {"sel": sel, "lam3": lam3, "b4": b4, "b5": b5, "dev_rho": dev_rho, "estrela": estrela, "rho_dev_m0": rho_dev_m0, "lam2g": lam2g}
    if os.environ.get("R5_SO_DEV"):
        rep.log("(R5_SO_DEV definido: a avaliação no gabarito congelado foi PULADA — modo de desenvolvimento.)")
        ctx.res["_r5_modelos"] = {"m1": m1, "m2": m2, "m3": m3, "m4": m4, "m5": m5}
        return
    # ---------------- AVALIAÇÃO ÚNICA no gabarito congelado da R4 ----------------
    t0 = time.time()
    pal, ij, ouro, ouro_c, ps = pares_gabarito_r4()
    pt_de = {e: p for p, e in LEXICO_PARES}
    pal_pt = [pt_de[w] for w in pal]
    rnd_vet = lambda w: normalizar(np.random.default_rng(zlib.crc32(("rnd5::" + w).encode())).standard_normal(16))
    sgns = ModeloSGNS(esp["C1"])
    en_mods = dict(mods)
    en_mods.update({"M3-glosas embaralhadas (nulo)": ModeloGlosa(m1, dados, lam3[1], embaralhar=5).vetor,
                    "M4-grupos embaralhados (nulo)": ModeloEspecializado(m1, dados["relacoes"], b4[1], b4[2], embaralhar=5).vetor,
                    "M2g (pós-hoc: M2+glosa)": m2g.vetor, "SGNS (C1, sem ajuste)": sgns.vetor, "vetores aleatórios (nulo)": rnd_vet})
    pt_mods = {k: v for k, v in en_mods.items() if k in ("M0", "M1", "M2", "M3", "M4", "M5", "M2g (pós-hoc: M2+glosa)", "vetores aleatórios (nulo)")}
    nb = 1500 if ctx.args.rapido else 4000
    res = {}
    for lang, palavras, ms in (("EN", pal, en_mods), ("PT", pal_pt, pt_mods)):
        sims = {n: _sim_modelo_vetores(f, palavras, ij) for n, f in ms.items()}
        res[lang] = (sims, rho_boot_palavras_v(sims, ouro, ij, len(pal), n_boot=nb, seed=4242, jobs=ctx.jobs))
    sims_en, R_en = res["EN"]
    sims_pt, R_pt = res["PT"]
    rep.sub("ρ de Spearman contra Wu–Palmer (gabarito WordNet R4 CONGELADO, avaliado uma vez) — IC95% por bootstrap de PALAVRAS")
    rep.log(f"{'modelo':<34}{'EN: ρ [IC95%]':>24}{'PT: ρ [IC95%]':>24}{'EN: ρ vs caminho':>18}")
    for nome in R_en:
        pt_txt = f"{R_pt[nome][0]:>+9.3f} [{R_pt[nome][1]:+.2f},{R_pt[nome][2]:+.2f}]" if nome in R_pt else f"{'—':>24}"
        rep.log(f"{nome:<34}{R_en[nome][0]:>+9.3f} [{R_en[nome][1]:+.2f},{R_en[nome][2]:+.2f}]{pt_txt}{spearman(sims_en[nome], ouro_c):>+18.3f}")
    # confirmatórias
    dpar = dif_boot_palavras
    F = {"F1": ("ρ_EN(M1) − ρ_EN(M0) > 0", dpar(R_en, "M1", "M0")), "F2": ("ρ_EN(M2) − ρ_EN(M0) > 0", dpar(R_en, "M2", "M0")),
         "F3": ("ρ_EN(M3) − ρ_EN(M0) > 0", dpar(R_en, "M3", "M0")), "F4": ("ρ_EN(M4) − ρ_EN(M0) > 0", dpar(R_en, "M4", "M0")),
         "F5": ("ρ_EN(M5) − ρ_EN(M0) > 0", dpar(R_en, "M5", "M0")),
         "F6": (f"ρ_EN(M*={estrela}) > 0", (R_en[estrela][0], R_en[estrela][1], R_en[estrela][2], p_boot_unicaudal(R_en[estrela][3]))),
         "F7": (f"ρ_PT(M*={estrela}) − ρ_PT(M0) > 0", dpar(R_pt, estrela, "M0"))}
    padj = holm([F[k][1][3] for k in F])
    rep.sub("VEREDITO PRÉ-REGISTRADO F1–F7 (Holm)")
    status = {}
    for (k, (desc, (est, lo, hi, p))), pa_ in zip(F.items(), padj):
        status[k] = "CONFIRMADA" if pa_ < 0.05 else "NÃO CONFIRMADA"
        rel = " | efeito relevante (Δρ≥0,10 e IC>0)" if (k != "F6" and est >= 0.10 and lo > 0) else ""
        rep.log(f"  {k}: {desc:<30} estimativa={est:+.3f} IC95%[{lo:+.3f},{hi:+.3f}] p unicaudal={p:.4f} p Holm={pa_:.4f} → {status[k]}{rel}")
    rep.log("  Critério (como pré-registrado): CONFIRMADA se p Holm < 0,05; o IC95% é descritivo. Nulo é nulo: nada foi reanalisado com outros recortes.")
    # controles e exploratórios
    sh3, sh4 = R_en["M3-glosas embaralhadas (nulo)"][0], R_en["M4-grupos embaralhados (nulo)"][0]
    rep.sub("Controles e exploratórios (sem Holm)")
    rep.log(f"  nulo da glosa (glosas embaralhadas): ρ_EN={sh3:+.3f} (M3 real {R_en['M3'][0]:+.3f}) | nulo da especialização (grupos embaralhados): ρ_EN={sh4:+.3f} (M4 real {R_en['M4'][0]:+.3f}); "
            f"se o controle chega perto do real, o ganho NÃO vem do conteúdo da técnica.")
    dif3 = R_en["M3"][3] - R_en["M3-glosas embaralhadas (nulo)"][3]
    dif4 = R_en["M4"][3] - R_en["M4-grupos embaralhados (nulo)"][3]
    rep.log(f"  Δρ real − nulo: glosa {R_en['M3'][0] - sh3:+.3f} IC95%[{np.percentile(dif3, 2.5):+.3f},{np.percentile(dif3, 97.5):+.3f}] | especialização {R_en['M4'][0] - sh4:+.3f} IC95%[{np.percentile(dif4, 2.5):+.3f},{np.percentile(dif4, 97.5):+.3f}]")
    rep.log("  por classe (M0 | M1 | M2 | M3 | M4 | M5 | M*), EN: " + " ; ".join(
        f"{nc}(n={int((ps == c).sum())}): " + " | ".join(f"{spearman(sims_en[m][ps == c], ouro[ps == c]):+.3f}" for m in ("M0", "M1", "M2", "M3", "M4", "M5", estrela))
        for c, nc in (("n", "substantivos"), ("v", "verbos"))))
    # intruso
    itens = g4["intrusos"]

    def fn_vet(vet):
        cache: dict = {}

        def f(a, b):
            for w in (a, b):
                if w not in cache:
                    cache[w] = normalizar(vet(w))
            return float(cache[a] @ cache[b])
        return f

    def acc_intruso(f):
        ok = []
        for it in itens:
            ws = it["membros"] + [it["intruso"]]
            S = np.array([[f(a, b) if a != b else 0.0 for b in ws] for a in ws])
            ok.append(ws[int(np.argmin(S.sum(1)))] == it["intruso"])
        return np.array(ok)

    acc = {n: acc_intruso(fn_vet(f)) for n, f in en_mods.items() if n in ("M0", "M1", "M2", "M3", "M4", "M5", "M2g (pós-hoc: M2+glosa)", "SGNS (C1, sem ajuste)", "vetores aleatórios (nulo)")}
    rep.sub(f"Intruso gerado por regra ({len(itens)} itens; acaso = 25%) — exploratório; pares/itens compartilham palavras → ICs otimistas")
    for n, a in acc.items():
        rep.log(f"  {n:<34} {_fmt_ic(int(a.sum()), len(a))}  ({int(a.sum())}/{len(a)})")
    b_ = int((acc[estrela] & ~acc["M0"]).sum())
    c_ = int((~acc[estrela] & acc["M0"]).sum())
    rep.log(f"  McNemar exato unicaudal M* vs M0: só M* acerta={b_}, só M0 acerta={c_}, p={mcnemar_exato_unicaudal(b_, c_):.4f} (exploratório)")
    ctx.res["r5_mcnemar"] = (int(b_), int(c_), float(mcnemar_exato_unicaudal(b_, c_)))
    rep.log("→ LEITURA HONESTA: ver o veredito F1–F7 acima. Pontos de cautela: (a) as glosas e as frases foram escritas por MIM, que conhecia as categorias do gabarito: o controle de glosas embaralhadas estima quanto do ganho NÃO é conteúdo; "
            "(b) as relações compartilham categorias (não palavras) com o gabarito: é supervisão fraca de categoria, não aprendizado não supervisionado; (c) o DEV tem 67 palavras e escolhe entre 72 configs: há seleção "
            "no DEV (mas nenhuma no gabarito de avaliação); (d) o gabarito mede taxonomia WordNet, não 'significado' em geral; (e) PT usa a mesma ponte de tradução e a glosa da tradução inglesa.")
    ctx.res["r5_sim"] = {"F": {k: (v[0], v[1]) for k, v in F.items()}, "padj": [float(x) for x in padj], "status": status, "estrela": estrela,
                         "rho_en": {n: R_en[n][0] for n in R_en}, "rho_pt": {n: R_pt[n][0] for n in R_pt}, "ic_en": {n: (R_en[n][1], R_en[n][2]) for n in R_en},
                         "intruso": {n: (int(a.sum()), len(a)) for n, a in acc.items()}, "n_pares": len(ij), "nulo": (sh3, sh4)}
    rep.log(f"(tempo da avaliação única: {time.time() - t0:.1f}s)", vol=True)


# ======================================================================
# BLOCO 3 — PROBABILIDADE ⊂ PROBABILIDADE ; METACOGNIÇÃO ⊂ METACOGNIÇÃO
# ======================================================================

MODOS = ["confio", "duvido", "curioso", "necessito"]


class ProbabilidadeAninhada:
    """Dirichlet-de-Dirichlet: q ~ Dir(c·p), com p ela mesma uma distribuição.
    Fato matemático: E[q] = p, logo 'tirar a esperança' é um ponto fixo — o
    resultado da probabilidade dentro da probabilidade é a própria
    probabilidade (em média); a variância (incerteza epistêmica) cresce com a
    profundidade."""

    def __init__(self, rng):
        self.rng = rng

    def nivel(self, p, conc):
        q = self.rng.dirichlet(np.maximum(conc * np.asarray(p), 1e-2))
        q = np.nan_to_num(q, nan=1.0 / len(p)) + 1e-12
        return q / q.sum()

    def aninhar(self, p, profundidade, conc):
        for _ in range(profundidade):
            p = self.nivel(p, conc)
        return p

    def amostras(self, p, profundidade, conc, n=2000):
        return np.array([self.aninhar(p, profundidade, conc) for _ in range(n)])

    @staticmethod
    def decompor(amostras):
        total = entropia(amostras.mean(0))
        aleat = float(np.mean([entropia(q) for q in amostras]))
        return {"total": total, "aleatoria": aleat, "epistemica": max(total - aleat, 0.0)}


class MetaCognicao:
    """Estado metacognitivo m = distribuição sobre MODOS. O operador
    M(m) = softmax(W m + b + e + γ·H(m)·s) inclui a auto-observação (impureza de
    Gini do próprio estado). meta^k = ponto fixo amortecido -> o resultado é de novo
    um estado metacognitivo (vetor no simplex)."""

    def __init__(self, rng, gama: float = 0.2):
        W = rng.standard_normal((4, 4))
        self.W = 0.7 * W / np.linalg.norm(W, 2)  # contrativo na prática (softmax é ½-Lipschitz em ℓ2)
        self.b = 0.2 * rng.standard_normal(4)
        self.s = np.array([-1.0, 1.0, 1.0, 0.0])
        self.gama = gama

    def operador(self, m, e):
        h = (1.0 - float(np.sum(np.asarray(m) ** 2))) / 0.75  # impureza de Gini normalizada (gradiente limitado, ao contrário da entropia)
        return softmax(self.W @ m + self.b + e + self.gama * h * self.s)

    def ponto_fixo(self, m0, e, amort=0.5, tol=1e-10, maxit=500):
        m = np.asarray(m0, float)
        for i in range(maxit):
            n = (1 - amort) * m + amort * self.operador(m, e)
            if np.abs(n - m).sum() < tol:
                return n, i + 1
            m = n
        return m, maxit

    def meta_de_meta(self, m0, e, niveis=5, lam=0.5):
        """nível k observa o resultado do nível k−1 (metacognição dentro da metacognição)."""
        estados, m = [], np.asarray(m0, float)
        for _ in range(niveis):
            ek = e + lam * (m - 0.25)  # o nível acima enxerga o resultado do abaixo
            m, _ = self.ponto_fixo(m, ek)
            estados.append(m.copy())
        return estados


def evidencia_de_incerteza(dec):
    ep, al = dec["epistemica"], dec["aleatoria"]
    return np.array([-(ep + al), al, ep, 0.5 * (ep + al)]) * 1.5


def bloco3(ctx: Contexto):
    rep, rng = ctx.rep, ctx.rng
    rep.titulo("BLOCO 3 — Probabilidade ⊂ probabilidade, metacognição ⊂ metacognição")
    pa = ProbabilidadeAninhada(rng)
    p0 = softmax(rng.standard_normal(6) * 1.2)
    rep.log("p0 (distribuição sobre 6 'significados') = " + np.array2string(p0, precision=3))
    rep.sub("Dirichlet aninhado: média é ponto fixo, incerteza epistêmica cresce")
    rep.log(f"{'prof':>4} {'|E[q]-p0|₁':>11} {'H_total':>8} {'aleat.':>8} {'epist.':>8}")
    for prof in range(1, 6):
        am = pa.amostras(p0, prof, conc=20.0, n=1500)
        d = pa.decompor(am)
        erro = np.abs(am.mean(0) - p0).sum()
        rep.log(f"{prof:>4} {erro:>11.4f} {d['total']:>8.3f} {d['aleatoria']:>8.3f} {d['epistemica']:>8.3f}")
        ctx.obs.registrar("prob_aninhada", am[0])
    rep.log("→ E[q]≈p0 em todas as profundidades (resultado = a própria probabilidade, em média); "
            "a parte epistêmica (informação mútua) aumenta.")

    mc = MetaCognicao(rng)
    m0 = np.full(4, 0.25)
    rep.sub("Metacognição dentro da metacognição (5 níveis, ponto fixo)")
    est = mc.meta_de_meta(m0, evidencia_de_incerteza(pa.decompor(pa.amostras(p0, 2, 20.0, 800))), niveis=6)
    for k, m in enumerate(est, 1):
        dist = np.abs(m - est[k - 2]).sum() if k > 1 else float("nan")
        rep.log(f"  meta^{k}: {np.array2string(m, precision=4)}  soma={m.sum():.6f}  Δ₁ vs nível anterior={dist:.2e}")
        ctx.obs.registrar("meta_estado", m)
    rep.log(f"→ saída é de novo um estado metacognitivo (simplex sobre {MODOS}).")

    rep.sub("Probabilidade dentro da metacognição E metacognição dentro da probabilidade (ciclo acoplado)")
    m = m0.copy()
    hist = []
    for it in range(40):
        conc = 5.0 + 60.0 * m[0]  # metacognição → concentração da probabilidade
        pa_fix = ProbabilidadeAninhada(np.random.default_rng(123))  # números aleatórios comuns
        dec = pa_fix.decompor(pa_fix.amostras(p0, 2, conc, n=600))
        e = evidencia_de_incerteza(dec)  # probabilidade → evidência metacognitiva
        novo, _ = mc.ponto_fixo(m, e)
        delta = np.abs(novo - m).sum()
        hist.append((it, conc, dec["epistemica"], delta))
        m = 0.5 * m + 0.5 * novo
        ctx.obs.registrar("meta_estado", m)
        if delta < 1e-4:
            break
    for it, conc, ep, delta in hist[:: max(1, len(hist) // 6)] + [hist[-1]]:
        rep.log(f"  iter {it:>2}: conc={conc:6.2f} epist={ep:.4f} Δm={delta:.2e}")
    conv = hist[-1][3] < 1e-4
    rep.log(f"→ ciclo acoplado {'CONVERGIU' if conv else 'NÃO convergiu'} em {len(hist)} iterações; "
            f"estado final = {np.array2string(m, precision=3)}")
    ctx.res["bloco3_convergiu"] = conv
    ctx.res["meta_final"] = m

    rep.sub("Incerteza → curiosidade / dúvida / necessidade → quais palavras consultar")
    texto_alvo = ["metacognição", "autopoiese", "atrator", "delírio", "entropia", "probabilidade",
                  "geometria", "dualidade", "recursão", "serendipity", "serendipidade", "chaos", "cognição"]
    lake = ctx.lake
    sig = ctx.sinal
    linhas = []
    for w in texto_alvo:
        conhecida = w in lake.entradas
        cl = lake._classe_vizinhos(w) if not conhecida else lake.entradas[w][1]
        alfa = np.full(3, 0.5)
        if conhecida:
            alfa[CLASSES.index(cl)] += 12.0  # evidência forte
        else:  # evidência fraca vinda só dos vizinhos
            alfa[CLASSES.index(cl)] += 1.0
        dirich = ProbabilidadeAninhada(np.random.default_rng(lake._semente_hash(w) % 2 ** 32))
        am = np.array([dirich.rng.dirichlet(alfa) for _ in range(400)])
        dec = pa.decompor(am)
        need = 1.0 / (1 + len(w) / 6)  # necessidade: proxy simples (palavras curtas aparecem mais)
        escore = 1.5 * dec["epistemica"] + 0.5 * dec["aleatoria"] + 0.6 * (not conhecida) + 0.3 * need
        linhas.append((escore, w, conhecida, dec))
    escores = np.array([l[0] for l in linhas])
    E = np.array([l[3]["epistemica"] for l in linhas])
    need = np.array([1.0 / (1 + len(l[1]) / 6) for l in linhas])
    E_pct, N_pct = _pct(E), _pct(need)
    limiar = float(np.median(E))
    langs = [lake._heuristica_idioma(l[1]) for l in linhas]
    arm = np.array([(0 if lg == "pt" else 1) * 3 + (0 if len(l[1]) <= 6 else (1 if len(l[1]) <= 10 else 2)) for lg, l in zip(langs, linhas)])
    elegiveis = [i for i, l in enumerate(linhas) if (not l[2]) and E[i] >= limiar]
    rep.log(f"{'palavra':<14}{'no dic.':<9}{'epist.':>8}{'aleat.':>8}{'escore':>8}{'elegível (epist ≥ mediana, fora do dic.)':>42}")
    for i, (esc, w, con, dec) in enumerate(linhas):
        rep.log(f"{w:<14}{('sim' if con else 'não'):<9}{dec['epistemica']:>8.3f}{dec['aleatoria']:>8.3f}{esc:>8.3f}{('sim' if i in elegiveis else 'não'):>42}")
    rep.log(f"(limiar de incerteza epistêmica = mediana = {limiar:.3f}; a escolha usa a PoliticaCuriosidade (necessidade × P̂ do braço + incerteza + bônus UCB), "
            "aprendida durante as consultas — o bandido do BLOCO 3b agora está LIGADO ao pipeline de consulta.)")
    rep.sub("Consultas efetivas pelo pipeline local → dictionaryapi.dev → DuckDuckGo (validador/supletivo), orçamento 12")
    if ctx.args.offline:
        orac = OraculoSimulado([l[1] for l in linhas], langs, [0.7] * len(linhas), seed=ctx.seed, tipo="A")
        rep.log("  ORÁCULO = [SIMULADO] (--offline): os desfechos abaixo vêm de sorteios do simulador, NÃO da internet.")
    else:
        orac = OraculoReal(lake)
        rep.log("  ORÁCULO = [REAL] (dictionaryapi.dev / DuckDuckGo, com disjuntor de rede).")
    grav3 = GravadorConsultas(orac, (f"bloco3-sim-semente{ctx.seed}" if ctx.args.offline else time.strftime("bloco3-real-%Y%m%dT%H%M%S")),
                              "SIMULADO" if ctx.args.offline else "REAL", {"bloco": "3", "semente": ctx.seed, "orcamento": 12})
    pipe = PipelineConsulta(grav3, set(lake.entradas))   # [R4] toda consulta (real ou simulada) é registrada no log persistente
    pc = PoliticaCuriosidade(6)
    restante, tentadas, escolhidas = 12, set(), []
    while restante >= 1:
        cand = [i for i in elegiveis if i not in tentadas]
        if not cand:
            break
        sc = pc.escore(E_pct[cand], N_pct[cand], arm[cand])
        i = cand[int(np.argmax(sc))]
        tentadas.add(i)
        w = linhas[i][1]
        r = pipe.consultar(w, langs[i], restante, valida=True)
        if r["status"] == "sem_orcamento":
            break
        restante -= r["custo"]
        pc.atualizar(arm[i], r["status"] == "aceita")
        escolhidas.append(i)
        if r["status"] == "aceita":
            cl = lake._classe_vizinhos(w)
            lake.entradas[w] = (langs[i], cl, f"{orac.rotulo} {r['definicao']}")
            lake._cache.pop(w, None)
            lake.aprendidas[w] = f"{r['fonte']} {orac.rotulo}"
        else:
            rr = lake.consultar(w, usar_api=False)
            r["fonte"] = rr["fonte"]
        rep.log(f"  {orac.rotulo} '{w}': passos={'→'.join(r['passos'])} | status={r['status']} | fonte={r['fonte']} | custo={r['custo']} (restante {restante})")
        ctx.obs.registrar("dicionario", lake.vetor(w))
    for msg in lake.log_rede:
        rep.log("  [rede] " + msg)
    if ctx.args.offline:
        rep.log("  [rede] modo --offline: nenhuma chamada externa foi feita.")
    gravou3 = ctx.qlog.gravar(grav3, idempotente=ctx.args.offline)
    rep.log(f"  [log] {len(grav3.regs)} consultas desta sessão ('{grav3.sessao}', {grav3.origem}) → {ctx.qlog.caminho or 'log desligado'}: {'gravadas' if gravou3 else 'não gravadas (sessão já existia ou log desligado)'}.", vol=True)

def bandido_consultas(seed: int, n_pal: int = 12, orcamento: int = 40, reps: int = 60):
    """Simulação (BRINQUEDO) de escolher quais palavras consultar sob orçamento de
    chamadas: cada palavra tem uma chance oculta μ de a consulta trazer informação
    nova. Compara sorteio uniforme, guloso, UCB1 e Thompson pelo arrependimento
    esperado (orçamento·max μ − Σ μ das escolhas)."""
    rng = np.random.default_rng(seed)
    pols = ["uniforme", "guloso", "UCB1", "Thompson"]
    reg = {p: [] for p in pols}
    for _ in range(reps):
        mu = rng.beta(1.2, 3.0, n_pal)
        for pol in pols:
            n, s, perda = np.zeros(n_pal), np.zeros(n_pal), 0.0
            for t in range(orcamento):
                if t < n_pal and pol in ("guloso", "UCB1"):
                    a = t
                elif pol == "uniforme":
                    a = int(rng.integers(n_pal))
                elif pol == "guloso":
                    a = int(np.argmax(s / n))
                elif pol == "UCB1":
                    a = int(np.argmax(s / n + np.sqrt(2 * math.log(t + 1) / n)))
                else:
                    a = int(np.argmax(rng.beta(1 + s, 1 + n - s)))
                x = rng.random() < mu[a]
                n[a] += 1
                s[a] += x
                perda += mu.max() - mu[a]
            reg[pol].append(perda)
    return {p: (float(np.mean(v)), float(np.std(v) / math.sqrt(len(v)))) for p, v in reg.items()}


def bloco3b(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 3b — Bandido de consultas (UCB/Thompson) sob orçamento de chamadas [melhoria #16, simulação]")
    r = bandido_consultas(ctx.seed + 77)
    rep.log("12 palavras candidatas, orçamento de 40 consultas, 60 repetições; arrependimento esperado (menor = melhor):")
    for p, (m, se) in r.items():
        rep.log(f"  {p:<9}: {m:6.2f} ± {se:.2f}")
    melhor = min(r, key=lambda p: r[p][0])
    rep.log(f"→ melhor política nesta simulação: {melhor}. Ressalva: μ foi sorteado por mim (Beta(1.2,3)); não mede o mundo real, "
            "só mostra que escolher consultas com um bandido é implementável e comparável ao sorteio.")
    ctx.res["bandido"] = (melhor, r[melhor][0], r["uniforme"][0])




