def digamma(x):
    """ψ(x) por recorrência + série assintótica (precisão ~1e-10 para x>0)."""
    x = np.array(x, float, ndmin=1)
    r = np.zeros_like(x)
    for _ in range(8):
        m = x < 6.0
        r -= np.where(m, 1.0 / x, 0.0)
        x = np.where(m, x + 1.0, x)
    f = 1.0 / (x * x)
    return r + np.log(x) - 0.5 / x - f * (1 / 12 - f * (1 / 120 - f * (1 / 252 - f * (1 / 240 - f / 132))))


def epistemica_dirichlet(alfa):
    """Informação mútua (bits) entre a classe e o parâmetro q~Dir(α): H(E[q]) − E[H(q)], em forma FECHADA.
    É a mesma 'incerteza epistêmica' que ProbabilidadeAninhada.decompor estima por amostragem (autoteste confere)."""
    a = np.atleast_2d(np.asarray(alfa, float))
    a0 = a.sum(1, keepdims=True)
    m = a / a0
    h_med = -(m * np.log(np.maximum(m, 1e-300))).sum(1)
    e_h = digamma(a0[:, 0] + 1.0) - (m * digamma((a + 1.0).ravel()).reshape(a.shape)).sum(1)
    return np.maximum(h_med - e_h, 0.0) / math.log(2.0)


def holm(ps):
    """Correção de Holm–Bonferroni: devolve p ajustados na ordem original."""
    ps = np.asarray(ps, float)
    o = np.argsort(ps)
    aj = np.empty(len(ps))
    mx = 0.0
    for r, i in enumerate(o):
        mx = max(mx, (len(ps) - r) * ps[i])
        aj[i] = min(1.0, mx)
    return aj


def ece_brier(p, y, bins=10):
    """ECE (erro de calibração esperado) e Brier de previsões probabilísticas p para desfechos binários y."""
    p, y = np.asarray(p, float), np.asarray(y, float)
    if len(p) == 0:
        return float("nan"), float("nan")
    b = np.minimum((p * bins).astype(int), bins - 1)
    ece = 0.0
    for k in range(bins):
        m = b == k
        if m.any():
            ece += m.mean() * abs(p[m].mean() - y[m].mean())
    return float(ece), float(np.mean((p - y) ** 2))


class OraculoSimulado:
    """ORÁCULO SIMULADO (rótulo [SIMULADO]): substitui dictionaryapi.dev/DuckDuckGo em --offline e nos experimentos
    multi-semente. Cada palavra tem atributos OCULTOS (língua, raridade) e sorteios fixos (números aleatórios comuns:
    a mesma palavra dá o mesmo desfecho para todas as políticas da mesma semente). Os parâmetros do 'mundo' são
    escolhas MINHAS (não medidas da API real): A=realista (raras e pt falham mais), B=nulo (acerto independe de tudo),
    C=adversário (raras são MAIS achadas)."""
    rotulo = "[SIMULADO]"
    OK_API, OK_DDG, REJ_ERRADA, REJ_CERTA = 0.92, 0.75, 0.80, 0.10

    def __init__(self, palavras, langs, raridade, seed: int, tipo: str = "A"):
        self.tipo = tipo
        rng = np.random.default_rng(seed)
        self.i = {w: k for k, w in enumerate(palavras)}
        n = len(palavras)
        self.U = rng.random((n, 5))
        r = np.asarray(raridade, float)
        en = np.array([l == "en" for l in langs])
        if tipo == "A":
            self.p_api = np.where(en, 0.92 - 0.55 * r, 0.60 - 0.45 * r)
            self.p_ddg = np.full(n, 0.65)
        elif tipo == "B":
            self.p_api = np.full(n, 0.55)
            self.p_ddg = np.full(n, 0.55)
        else:
            self.p_api = 0.2 + 0.6 * r
            self.p_ddg = np.full(n, 0.50)

    def api(self, w):
        k = self.i[w]
        return f"[SIMULADO] definição de '{w}' (dictionaryapi)" if self.U[k, 0] < self.p_api[k] else None

    def ddg(self, w):
        k = self.i[w]
        return f"[SIMULADO] trecho sobre '{w}' (DuckDuckGo)" if self.U[k, 2] < self.p_ddg[k] else None

    def correto(self, w, fonte):   # verdade oculta (só para avaliar; nenhuma política a vê)
        k = self.i[w]
        return bool(self.U[k, 1] < self.OK_API) if fonte == "api" else bool(self.U[k, 3] < self.OK_DDG)

    def validar(self, w, definicao, fonte):
        k = self.i[w]
        u = self.U[k, 4]
        if self.correto(w, fonte):
            return bool(u >= self.REJ_CERTA)      # o validador rejeita uma definição CERTA com prob. 0,10
        return bool(u >= self.REJ_ERRADA)         # ...e deixa passar uma ERRADA com prob. 0,20


class OraculoReal:
    """Oráculo REAL: usa DicionarioLake._api_dicionario (dictionaryapi.dev) e _ddg (DuckDuckGo), com os
    disjuntores de rede do lake. Rótulo [REAL]. Não foi possível testá-lo ao vivo nesta máquina (sem internet);
    o autoteste cobre o pipeline com um servidor FALSO que imita as duas funções."""
    rotulo = "[REAL]"
    aceita_lang = True

    def __init__(self, lake: "DicionarioLake"):
        self.lake = lake

    def disponivel(self, que):
        return bool(self.lake.servico_ok["dicionario" if que == "api" else "ddg"])

    def api(self, w, lang="en"):
        return self.lake._api_dicionario(w, lang) if self.lake.servico_ok["dicionario"] else None

    def ddg(self, w, lang=None):
        return self.lake._ddg(w) if self.lake.servico_ok["ddg"] else None

    def validar(self, w, definicao, fonte):
        return self.lake._ddg_validar(w, definicao) if self.lake.servico_ok["ddg"] else None

    def correto(self, w, fonte):
        return None


# ======================================================================
# [R4] LOG PERSISTENTE DE CONSULTAS (query_log.jsonl) + ORÁCULO DE REPLAY
# ======================================================================

ESQUEMA_LOG = "asi-qlog/1"
LOG_PADRAO = "/workspace/query_log.jsonl"
SERVICOS_LOG = ("api", "ddg", "ddg_valida")
STATUS_LOG = ("hit", "miss", "erro", "validou", "rejeitou", "indeterminado")
ORIGENS_LOG = ("REAL", "SIMULADO")
CAMPOS_CONSULTA = {"esquema": str, "tipo": str, "sessao": str, "seq": int, "origem": str, "servico": str, "palavra": str, "lang": str,
                   "politica": (str, type(None)), "status": str, "latencia_ms": (float, int, type(None)), "resposta": (str, type(None)),
                   "resposta_sha256": (str, type(None)), "correto_oculto": (bool, type(None)), "custo": int}
DOC_ESQUEMA_LOG = (
    "Formato JSON Lines (UTF-8), uma linha por registro, chaves ordenadas. Cada SESSÃO começa com uma linha tipo='sessao' "
    "{esquema, tipo, sessao, origem(REAL|SIMULADO), versao, ts(ISO local), n_consultas, meta{...}} seguida de n_consultas linhas tipo='consulta' "
    "{esquema, tipo, sessao, seq, origem, servico(api|ddg|ddg_valida), palavra, lang, politica|null, status(hit|miss|erro|validou|rejeitou|indeterminado), "
    "latencia_ms|null (só REAL), resposta|null (≤160 caracteres), resposta_sha256|null, correto_oculto|null (só SIMULADO: verdade do simulador; REAL: sempre null), custo}. "
    "REAL = a chamada saiu para a rede de verdade (dictionaryapi.dev/DuckDuckGo); SIMULADO = sorteio do OraculoSimulado. Sessões SIMULADAS têm id determinístico e só são gravadas se o id ainda não existir (idempotente).")


def validar_registro_log(rec: dict) -> list:
    """Devolve a lista de problemas do registro (vazia = válido). Só valida o esquema, não a semântica."""
    pr = []
    if rec.get("esquema") != ESQUEMA_LOG:
        pr.append("esquema")
    if rec.get("tipo") == "sessao":
        for k, tp in (("sessao", str), ("origem", str), ("versao", str), ("ts", str), ("n_consultas", int), ("meta", dict)):
            if not isinstance(rec.get(k), tp):
                pr.append(f"sessao.{k}")
        if rec.get("origem") not in ORIGENS_LOG:
            pr.append("sessao.origem")
        return pr
    if rec.get("tipo") != "consulta":
        return pr + ["tipo"]
    for k, tp in CAMPOS_CONSULTA.items():
        if k not in rec or not isinstance(rec[k], tp) or (tp is int and isinstance(rec[k], bool)):
            pr.append(k)
    if rec.get("servico") not in SERVICOS_LOG:
        pr.append("servico")
    if rec.get("status") not in STATUS_LOG:
        pr.append("status")
    if rec.get("origem") not in ORIGENS_LOG:
        pr.append("origem")
    if rec.get("origem") == "REAL" and rec.get("correto_oculto") is not None:
        pr.append("REAL com correto_oculto")
    return pr


class GravadorConsultas:
    """Embrulha um oráculo (OraculoSimulado, OraculoReal ou OraculoReplay) e REGISTRA toda chamada (api, ddg, validação).
    É transparente para o PipelineConsulta e para rodar_politica (mesma interface)."""
    aceita_lang = True

    def __init__(self, oraculo, sessao: str, origem: str, meta: dict | None = None, politica: str | None = None):
        self.o, self.sessao, self.origem, self.meta, self.politica = oraculo, sessao, origem, dict(meta or {}), politica
        self.regs: list[dict] = []
        self._lang = "en"
        self.rotulo = getattr(oraculo, "rotulo", "")

    def disponivel(self, que):
        return getattr(self.o, "disponivel", lambda _: True)(que)

    def _add(self, servico, w, lang, status, resp, t0, correto, custo):
        self.regs.append({"esquema": ESQUEMA_LOG, "tipo": "consulta", "sessao": self.sessao, "seq": len(self.regs), "origem": self.origem,
                          "servico": servico, "palavra": w, "lang": lang, "politica": self.politica, "status": status,
                          "latencia_ms": round(1000 * (time.perf_counter() - t0), 1) if self.origem == "REAL" else None,
                          "resposta": None if resp is None else str(resp)[:160],
                          "resposta_sha256": None if resp is None else hashlib.sha256(str(resp).encode("utf-8")).hexdigest(),
                          "correto_oculto": correto, "custo": custo})

    def _oculto(self, w, fonte):
        if self.origem == "REAL":
            return None
        try:
            v = self.o.correto(w, fonte)
        except Exception:  # noqa: BLE001
            return None
        return None if v is None else bool(v)

    def api(self, w, lang="en"):
        t0 = time.perf_counter()
        self._lang = lang
        r = self.o.api(w, lang) if isinstance(self.o, (OraculoReal, OraculoReplay)) else self.o.api(w)
        off = r is None and not self.disponivel("api")
        self._add("api", w, lang, "erro" if off else ("hit" if r else "miss"), r, t0, self._oculto(w, "api") if r else None, PipelineConsulta.C_API)
        return r

    def ddg(self, w, lang="en"):
        t0 = time.perf_counter()
        self._lang = lang
        r = self.o.ddg(w, lang) if isinstance(self.o, (OraculoReal, OraculoReplay)) else self.o.ddg(w)
        off = r is None and not self.disponivel("ddg")
        self._add("ddg", w, lang, "erro" if off else ("hit" if r else "miss"), r, t0, self._oculto(w, "ddg") if r else None, PipelineConsulta.C_DDG)
        return r

    def validar(self, w, definicao, fonte):
        t0 = time.perf_counter()
        v = self.o.validar(w, definicao, fonte)
        self._add("ddg_valida", w, getattr(self, "_lang", "en"), {True: "validou", False: "rejeitou", None: "indeterminado"}[v], None, t0, None, PipelineConsulta.C_VAL)
        return v

    def correto(self, w, fonte):
        return self.o.correto(w, fonte)


class OraculoReplay:
    """ORÁCULO DE REPLAY: responde a partir de registros GRAVADOS (sessão do query_log.jsonl) em vez de simular ou consultar a rede.
    - palavra/serviço presente no log → devolve exatamente o que foi gravado; ausente → None (conta em .ausentes; é 'miss' sem informação).
    - disponivel(serviço) = False se o log registra ERRO nesse serviço (a API fora do ar na gravação continua fora do ar no replay).
    - correto(): usa `correto_oculto` quando gravado (SIMULADO); em logs REAIS não há verdade → PROXY: hit com trecho que menciona a palavra.
    Rótulo: [REPLAY:REAL] ou [REPLAY:SIMULADO]."""
    aceita_lang = True

    def __init__(self, regs: list[dict], origem: str):
        self.rotulo = f"[REPLAY:{origem}]"
        self.origem = origem
        self.idx: dict = {}
        self.erro = {"api": False, "ddg": False}
        for r in regs:
            if r.get("tipo") != "consulta":
                continue
            self.idx.setdefault((r["servico"], r["palavra"]), r)
            if r["status"] == "erro" and r["servico"] in self.erro:
                self.erro[r["servico"]] = True
        self.ausentes = 0
        self.consultas = 0

    def palavras(self):
        return sorted({p for (s, p) in self.idx if s in ("api", "ddg")})

    def disponivel(self, que):
        return not self.erro[que]

    def _get(self, servico, w):
        self.consultas += 1
        r = self.idx.get((servico, w))
        if r is None:
            self.ausentes += 1
        return r

    def api(self, w, lang="en"):
        r = self._get("api", w)
        return r["resposta"] if r and r["status"] == "hit" else None

    def ddg(self, w, lang=None):
        r = self._get("ddg", w)
        return r["resposta"] if r and r["status"] == "hit" else None

    def validar(self, w, definicao, fonte):
        r = self.idx.get(("ddg_valida", w))
        return None if r is None else {"validou": True, "rejeitou": False}.get(r["status"])

    def correto(self, w, fonte):
        r = self.idx.get((fonte, w))
        if r is None or r["status"] != "hit":
            return False
        return bool(r["correto_oculto"]) if r["correto_oculto"] is not None else True   # PROXY em logs REAIS (trecho menciona a palavra)


class RegistroConsultas:
    """Arquivo JSONL persistente (append). `gravar` é idempotente para sessões com o mesmo id."""

    def __init__(self, caminho: str | None):
        self.caminho = caminho

    def ler(self) -> dict:
        """sessao_id → {'cab': registro da sessão ou None, 'regs': [consultas]}; linhas inválidas são contadas em '__invalidas__'."""
        out: dict = {}
        inval = 0
        if not self.caminho or not os.path.exists(self.caminho):
            return out
        with open(self.caminho, encoding="utf-8") as f:
            for linha in f:
                linha = linha.strip()
                if not linha:
                    continue
                try:
                    r = json.loads(linha)
                except ValueError:
                    inval += 1
                    continue
                if validar_registro_log(r):
                    inval += 1
                    continue
                s = out.setdefault(r["sessao"], {"cab": None, "regs": []})
                if r["tipo"] == "sessao":
                    s["cab"] = r
                else:
                    s["regs"].append(r)
        out["__invalidas__"] = inval
        return out

    def existe(self, sessao: str) -> bool:
        return sessao in self.ler()

    def gravar(self, grav: GravadorConsultas, meta_extra: dict | None = None, idempotente: bool = True) -> bool:
        """Anexa a sessão ao arquivo. Devolve True se gravou, False se pulou (id já existente / sem caminho)."""
        if not self.caminho:
            return False
        if idempotente and grav.sessao in self.ler():
            return False
        cab = {"esquema": ESQUEMA_LOG, "tipo": "sessao", "sessao": grav.sessao, "origem": grav.origem, "versao": VERSAO,
               "ts": time.strftime("%Y-%m-%dT%H:%M:%S"), "n_consultas": len(grav.regs), "meta": dict(grav.meta, **(meta_extra or {}))}
        with open(self.caminho, "a", encoding="utf-8") as f:
            for r in [cab] + grav.regs:
                f.write(json.dumps(r, ensure_ascii=False, sort_keys=True) + "\n")
        return True


def restringir_mundo(mw: dict, palavras, orac):
    """Mundo reduzido ao conjunto de palavras do log: percentis recomputados no subconjunto; o denominador da cobertura (tot_teste) NÃO muda."""
    pal = set(palavras)
    ix = [i for i, w in enumerate(mw["pool"]) if w in pal]
    if len(ix) < 8:
        return None
    sel = lambda a: np.asarray(a)[ix]
    E, obs = sel(mw["E"]), sel(mw["obs"])
    return {"pool": [mw["pool"][i] for i in ix], "langs": [mw["langs"][i] for i in ix], "rar": sel(mw["rar"]), "obs": obs, "E": E,
            "E_pct": _pct(E), "N_pct": _pct(np.log1p(obs)), "arm": sel(mw["arm"]), "n_arms": mw["n_arms"], "tok_teste": sel(mw["tok_teste"]),
            "tot_teste": mw["tot_teste"], "sinal": sel(mw["sinal"]), "orac": orac}


def gravar_sessao_simulada(ctx: Contexto, orc_budget: int = 160):
    """Sessão SIMULADA de demonstração: mundo A, semente 0, todas as políticas (≠ ninguem) com orçamento 160, tudo registrado.
    Devolve (gravador, mundo, rastros_originais por política)."""
    mw = montar_mundo(ctx.lake, 0, "A")
    rast = {}
    grav_all = GravadorConsultas(mw["orac"], f"sim-{VERSAO}-mundoA-semente0", "SIMULADO", {"semente": 0, "mundo": "A", "orcamento": orc_budget})
    for pol in ARMS_LOOKUP:
        if pol == "ninguem":
            continue
        g = GravadorConsultas(mw["orac"], grav_all.sessao, "SIMULADO", politica=pol)
        rast[pol], _ = rodar_politica(mw, pol, orc_budget, 0, orac=g)
        for r in g.regs:
            r["seq"] = len(grav_all.regs)
            grav_all.regs.append(r)
    return grav_all, mw, rast


def replay_fiel(ctx: Contexto, grav, mw, rast, orc_budget: int = 160):
    """Reexecuta cada política sobre o log (OraculoReplay) e compara o rastro com o original."""
    rp = OraculoReplay(grav.regs, "SIMULADO")
    res = {}
    for pol, r0 in rast.items():
        rastro, _ = rodar_politica(mw, pol, orc_budget, 0, orac=rp)
        res[pol] = (rastro == r0)
    return res, rp


def sessao_real_coletar(ctx: Contexto, n_palavras: int = 80, pausa: float = 0.5):
    """Coleta online uma sessão REAL (--sessao-real N): consulta o pipeline de verdade (dictionaryapi.dev → DuckDuckGo) para N palavras
    do mundo A (semente 0): primeiro todas as palavras do pool que aparecem nas frases de teste, depois um sorteio determinístico das demais."""
    lake = ctx.lake
    mw = montar_mundo(lake, 0, "A")
    rng = np.random.default_rng(20261016)
    teste = [i for i in range(len(mw["pool"])) if mw["tok_teste"][i] > 0]
    resto = [i for i in rng.permutation(len(mw["pool"])).tolist() if mw["tok_teste"][i] == 0]
    ordem = (teste + resto)[:n_palavras]
    gid = time.strftime("real-%Y%m%dT%H%M%S")
    grav = GravadorConsultas(OraculoReal(lake), gid, "REAL", {"semente": 0, "mundo": "A", "n_palavras": len(ordem), "n_teste": len(teste)})
    pipe = PipelineConsulta(grav, set(lake.entradas))
    for i in ordem:
        pipe.consultar(mw["pool"][i], mw["langs"][i], 10 ** 6, valida=False)
        time.sleep(pausa)
    return grav


# ----------------------------------------------------------------------
# BLOCO 3c (a) — pipeline de consulta, políticas de curiosidade e mundo simulado
# ----------------------------------------------------------------------

class PipelineConsulta:
    """Ordem de consulta quando a incerteza é alta: 1) dicionário LOCAL (custo 0); 2) dictionaryapi.dev (custo 1);
    3) [opcional, `valida=True`] DuckDuckGo como VALIDADOR da definição obtida (custo 2; rejeita se o validador
    discordar); 4) DuckDuckGo como fonte supletiva quando a API falha ou foi rejeitada (custo 2).
    Respeita o orçamento passo a passo: nunca gasta o que não tem."""
    C_API, C_DDG, C_VAL = 1, 2, 2

    def __init__(self, oraculo, conhecidas):
        self.o = oraculo
        self.conhecidas = conhecidas        # conjunto de palavras já no dicionário local

    def consultar(self, w, lang, restante, valida=False):
        passos, custo = [], 0
        if w in self.conhecidas:
            return {"w": w, "status": "local", "fonte": "local", "custo": 0, "passos": ["local:hit"], "definicao": None}
        passos.append("local:miss")
        d, fonte = None, None
        api_on = getattr(self.o, "disponivel", lambda _: True)("api")
        ddg_on = getattr(self.o, "disponivel", lambda _: True)("ddg")
        if not api_on:
            passos.append("api:desligado(disjuntor)")
        if restante >= self.C_API and api_on:
            custo += self.C_API
            try:
                d = self.o.api(w, lang) if getattr(self.o, "aceita_lang", False) else self.o.api(w)
            except Exception:  # noqa: BLE001
                d = None
            passos.append("api:hit" if d else "api:miss")
            if d:
                fonte = "api"
                if valida and restante - custo >= self.C_VAL:
                    custo += self.C_VAL
                    v = self.o.validar(w, d, "api")
                    passos.append({True: "ddg-valida:ok", False: "ddg-valida:rejeita", None: "ddg-valida:indeterminado"}[v])
                    if v is False:
                        d, fonte = None, None
        if not ddg_on:
            passos.append("ddg:desligado(disjuntor)")
        if d is None and ddg_on and restante - custo >= self.C_DDG:
            custo += self.C_DDG
            d = self.o.ddg(w, lang) if getattr(self.o, "aceita_lang", False) else self.o.ddg(w)
            fonte = "ddg" if d else None
            passos.append("ddg:hit" if d else "ddg:miss")
        if d is None:
            return {"w": w, "status": "falhou" if custo else ("sem_orcamento" if (api_on or ddg_on) else "falhou"), "fonte": None, "custo": custo, "passos": passos, "definicao": None}
        return {"w": w, "status": "aceita", "fonte": fonte, "custo": custo, "passos": passos, "definicao": d}


class PoliticaCuriosidade:
    """Curiosidade = valor esperado da consulta: (necessidade) × P̂(sucesso | braço) + λ_E · (incerteza epistêmica)
    + λ_B · bônus de exploração (UCB). Braços = (língua × faixa de uso); P̂ = posterior Beta(1,1) do braço,
    aprendido durante a execução. Pesos FIXOS a priori (λ_E=0,3; λ_B=0,3), nunca ajustados nos resultados."""
    LE, LB = 0.3, 0.3

    def __init__(self, n_arms: int):
        self.s = np.zeros(n_arms)
        self.n = np.zeros(n_arms)
        self.t = 0

    def p_hat(self, arm):
        return (self.s[arm] + 1.0) / (self.n[arm] + 2.0)

    def escore(self, E_pct, N_pct, arm):
        bonus = self.LB * np.sqrt(np.log(self.t + 2.0) / (self.n[arm] + 1.0))
        return N_pct * self.p_hat(arm) + self.LE * E_pct + bonus

    def atualizar(self, arm, sucesso):
        self.s[arm] += float(sucesso)
        self.n[arm] += 1.0
        self.t += 1


def _pct(x):
    """Percentil (0..1) de cada elemento dentro do vetor (empates: média)."""
    return (ranks_medios(x) - 1.0) / max(len(x) - 1, 1)


def _frases_mono():
    out = []
    for pt, en in list(CORPUS_PAR) + list(CORPUS_PAR2):
        out.append((tokenizar(pt), "pt"))
        out.append((tokenizar(en), "en"))
    return out


def montar_mundo(lake, seed: int, tipo: str, frac: float = 0.7, sinal_ret=None):
    """Mundo de uma semente: o agente 'lê' uma subamostra de 70% das frases (fluxo) e é avaliado na cobertura de
    tokens do TEXTO_TESTE_R3 (pré-registrado). Pool = palavras do fluxo fora do dicionário local e não funcionais."""
    rng = np.random.default_rng(900001 + 977 * seed)
    frases = _frases_mono()
    cont_full, cont_lang = {}, {}
    for toks, lg in frases:
        for w in toks:
            cont_full[w] = cont_full.get(w, 0) + 1
            cont_lang.setdefault(w, {"pt": 0, "en": 0})[lg] += 1
    sel = rng.random(len(frases)) < frac
    cont_obs = {}
    for (toks, _), s in zip(frases, sel):
        if s:
            for w in toks:
                cont_obs[w] = cont_obs.get(w, 0) + 1
    pool = sorted(w for w in cont_obs if w not in lake.entradas and w not in STOP and len(w) > 1)
    langs = ["pt" if cont_lang[w]["pt"] >= cont_lang[w]["en"] else "en" for w in pool]
    nmax = max(cont_full.values())
    rar = [1.0 - math.log(1 + cont_full[w]) / math.log(1 + nmax) for w in pool]   # raridade GLOBAL (oculta)
    obs = np.array([cont_obs[w] for w in pool], float)                            # uso observado no fluxo
    # incerteza epistêmica: votos dos 5 vizinhos-semente por classe, evidência ∝ uso observado (máx. 12)
    sem = lake.palavras_semente
    Vs = _unitarias(np.array([lake.vetor(q) for q in sem]))
    cls = np.array([CLASSES.index(lake.entradas[q][1]) for q in sem])
    Vp = _unitarias(np.array([lake.vetor(w) for w in pool]))
    S = Vp @ Vs.T
    viz = np.argsort(-S, axis=1)[:, :5]
    votos = np.full((len(pool), 3), 1e-3)
    for i in range(len(pool)):
        for j in viz[i]:
            votos[i, cls[j]] += max(S[i, j], 0.01)
    votos /= votos.sum(1, keepdims=True)
    alfa = 0.5 + (np.minimum(obs, 12.0) / 3.0)[:, None] * votos
    E = epistemica_dirichlet(alfa)
    terc = np.digitize(obs, np.quantile(obs, [1 / 3, 2 / 3]))
    arm = np.array([(0 if l == "pt" else 1) * 3 + t for l, t in zip(langs, terc)])
    idx = {w: i for i, w in enumerate(pool)}
    teste = {}
    for fr in TEXTO_TESTE_R3:
        for w in tokenizar(fr):
            if w not in STOP and w not in lake.entradas and len(w) > 1:
                teste[w] = teste.get(w, 0) + 1
    tok_teste = np.zeros(len(pool))
    for w, c in teste.items():
        if w in idx:
            tok_teste[idx[w]] = c
    tot_teste = float(sum(teste.values()))
    # sinal: estado a partir de uma janela de 5 retornos (real se online, senão sintético)
    if sinal_ret is not None and len(sinal_ret) > 40:
        j = int(rng.integers(0, len(sinal_ret) - 5))
        ret = np.asarray(sinal_ret[j:j + 5], float) / (np.std(sinal_ret) + 1e-12)
    else:
        vol, r = 0.01, []
        for _ in range(60):
            vol = math.sqrt(0.00001 + 0.7 * vol ** 2 + 0.25 * (rng.standard_normal() * vol) ** 2)
            r.append(vol * rng.standard_normal())
        r = np.array(r)
        ret = r[-5:] / (r.std() + 1e-12)
    estado = np.random.default_rng(5).standard_normal((DicionarioLake.DIM, 5)) @ ret
    sinal = Vp @ normalizar(estado)
    return {"pool": pool, "langs": langs, "rar": np.array(rar), "obs": obs, "E": E, "E_pct": _pct(E), "N_pct": _pct(np.log1p(obs)),
            "arm": arm, "n_arms": 6, "tok_teste": tok_teste, "tot_teste": tot_teste, "sinal": sinal,
            "orac": OraculoSimulado(pool, langs, rar, seed=500000 + 31 * seed + {"A": 1, "B": 2, "C": 3}[tipo], tipo=tipo)}


ARMS_LOOKUP = ["ninguem", "aleatorio", "frequencia", "incerteza", "sinal", "curiosidade", "curiosidade+valida"]


def rodar_politica(mw, pol: str, orcamento: int, seed: int, orac=None):
    """Executa uma política até `orcamento` unidades de custo. Devolve o rastro [(custo, n_ok, n_errada, tokens_ok)] e
    pares (P̂ prevista, sucesso) da curiosidade para calibração."""
    n = len(mw["pool"])
    rng = np.random.default_rng(777 + seed)
    orac = mw["orac"] if orac is None else orac
    pipe = PipelineConsulta(orac, set())
    tentados = np.zeros(n, bool)
    pc = PoliticaCuriosidade(mw["n_arms"])
    custo = n_ok = n_err = 0
    tok = 0.0
    rastro = [(0, 0, 0, 0.0)]
    calib = []
    ordem_fixa = None
    if pol == "frequencia":
        ordem_fixa = np.argsort(-mw["obs"] - 1e-6 * np.arange(n), kind="mergesort")
    elif pol == "incerteza":
        ordem_fixa = np.argsort(-mw["E"] - 1e-9 * np.arange(n), kind="mergesort")
    elif pol == "sinal":
        ordem_fixa = np.argsort(-mw["sinal"], kind="mergesort")
    elif pol == "aleatorio":
        ordem_fixa = rng.permutation(n)
    if pol == "ninguem":
        return rastro, calib
    ptr = 0
    while custo < orcamento:
        if ordem_fixa is not None:
            while ptr < n and tentados[ordem_fixa[ptr]]:
                ptr += 1
            if ptr >= n:
                break
            i = int(ordem_fixa[ptr])
            ptr += 1
        else:
            sc = pc.escore(mw["E_pct"], mw["N_pct"], mw["arm"])
            sc = np.where(tentados, -1e9, sc)
            i = int(np.argmax(sc))
            if tentados[i]:
                break
        tentados[i] = True
        w = mw["pool"][i]
        phat = float(pc.p_hat(mw["arm"][i]))
        r = pipe.consultar(w, mw["langs"][i], orcamento - custo, valida=(pol == "curiosidade+valida"))
        if r["status"] == "sem_orcamento":
            break
        custo += r["custo"]
        sucesso = 0.0
        if r["status"] == "aceita":
            if orac.correto(w, r["fonte"]):
                n_ok += 1
                tok += mw["tok_teste"][i]
                sucesso = 1.0
            else:
                n_err += 1
        pc.atualizar(mw["arm"][i], sucesso)
        if pol.startswith("curiosidade"):
            calib.append((phat, sucesso))
        rastro.append((custo, n_ok, n_err, tok))
    return rastro, calib


def _em_orcamento(rastro, B):
    ult = rastro[0]
    for r in rastro:
        if r[0] <= B:
            ult = r
        else:
            break
    return ult


ORCS_LOOKUP = [20, 40, 60, 100, 160]


def _job_lookup(args):
    seed, tipo, lake_tok = args
    lake = _LAKE_GLOBAL
    mw = montar_mundo(lake, seed, tipo, sinal_ret=_SINAL_GLOBAL)
    out = {"pool": len(mw["pool"]), "tot": mw["tot_teste"], "teto": float(mw["tok_teste"].sum())}
    for pol in ARMS_LOOKUP:
        rastro, calib = rodar_politica(mw, pol, max(ORCS_LOOKUP), seed)
        out[pol] = {B: _em_orcamento(rastro, B) for B in ORCS_LOOKUP}
        out[pol]["calib"] = calib
    return out


_LAKE_GLOBAL = None
_SINAL_GLOBAL = None


def bloco3c(ctx: Contexto):
    global _LAKE_GLOBAL, _SINAL_GLOBAL
    rep = ctx.rep
    rep.titulo("BLOCO 3c — Curiosidade ligada ao pipeline de consulta (local → dictionaryapi.dev → DuckDuckGo) + experimento [melhorias #16, #13, #17]")
