SEM0_AGENDA_R4 = 800     # sementes de tarefa 800–859: nunca usadas nas rodadas 1–3 (R1/R2: 0–31; autopoiese 0–60, 200–211; R3: 600–639, 700–739)


def equivalencia_boot(d, margem: float, n: int = 4000, seed: int = 0):
    """TOST por inclusão de IC: equivalente (α=0,05) se o IC90% bootstrap da média das diferenças ⊂ (−margem, +margem)."""
    d = np.asarray(d, float)
    rng = np.random.default_rng(seed)
    med = rng.choice(d, (n, len(d))).mean(1)
    lo, hi = float(np.percentile(med, 5)), float(np.percentile(med, 95))
    return lo, hi, bool(lo > -margem and hi < margem)


def bloco7b(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 7b — [R4] Variante 'só-agenda' (reinícios + contração SEM ruído): teste pré-registrado, Holm, 60 sementes NOVAS, equivalência")
