    modos = ["baseline", "so_agenda", "delirio", "cosseno"]
    rep.log(f"Sementes de tarefa {SEM0_AGENDA_R4}–{SEM0_AGENDA_R4 + n_sem - 1} ({n_sem}; NUNCA usadas antes), 400 passos Adam, teste = 600 amostras por semente, rede 8→12×6→1, pareado por semente. "
            "Motivação (honesta): na R3, so_agenda − baseline deu +0,77 pp com p=0,030 SEM correção — achado exploratório escolhido DEPOIS de ver 12 comparações; aqui ele é confirmado ou não, sem reinterpretação.")
    rep.log("baseline: Adam constante | so_agenda: agenda do delírio (lr×3 → lr↓/wd↑/contração à média móvel, 4 ciclos) SEM ruído | delirio: agenda + ruído de Lorenz | "
            "cosseno [exploratório]: reinícios SGDR sem ruído e sem contração.")
    rep.sub("HIPÓTESES PRÉ-REGISTRADAS (PREREG_R4_CORPO, sha256 conferido no BLOCO 2c e no autoteste)")
    for l in PREREG_R4_CORPO.split("\n"):
        if l.startswith("  S") or l.startswith("Equivalência (S4") or l.startswith("Expectativa registrada antes de rodar: S1") or l.startswith("Regra de interpretação"):
            rep.log("  " + l.strip())
    t0 = time.time()
    R = experimento_delirio(ctx, n_sem, sem0=SEM0_AGENDA_R4, modos=modos, registrar=False)
    rep.log(f"(tempo do experimento: {time.time() - t0:.1f}s, jobs={ctx.jobs})", vol=True)
    A = {m: np.array(R[m]["test_acc"]) for m in modos}
    rep.sub("Médias (± desvio entre sementes)")
    rep.log(f"{'condição':<12}{'test_acc':>16}{'val_acc':>14}{'ECE':>9}{'Brier':>9}")
    for m in modos:
        rep.log(f"{m:<12}{A[m].mean():>9.4f}±{A[m].std():.4f}{np.mean(R[m]['val_acc']):>14.4f}{np.mean(R[m]['ece']):>9.3f}{np.mean(R[m]['brier']):>9.3f}")
    rep.sub("CONFIRMATÓRIAS S1–S3 (bicaudais; IC95% bootstrap de sementes; p por permutação de sinais, 10000; Holm sobre as 3)")
    comps = [("S1", "so_agenda", "baseline"), ("S2", "delirio", "baseline"), ("S3", "so_agenda", "delirio")]
    cm = {k: comparar_pareado(A[a], A[b], seed=ctx.seed) for k, a, b in comps}
    ps = holm([cm[k]["p"] for k, _, _ in comps])
    status = {}
    for (k, a, b), pa_ in zip(comps, ps):
        c = cm[k]
        relevante = c["lo"] > 0 and c["media"] >= 0.01
        if pa_ < 0.05 and c["media"] > 0:
            st = "CONFIRMADA (efeito RELEVANTE ≥ +1 pp)" if relevante else "CONFIRMADA, mas efeito PEQUENO (< +1 pp ou IC inclui < 1)"
        elif pa_ < 0.05:
            st = "REFUTADA no sentido pré-registrado (Δ < 0, p Holm < 0,05)"
        else:
            st = "NÃO CONFIRMADA (nula/inconclusiva)"
        status[k] = st
        rep.log(f"  {k}: {a} − {b}: Δacc = {100 * c['media']:+.2f} pp IC95%=[{100 * c['lo']:+.2f},{100 * c['hi']:+.2f}] p={c['p']:.4f} p Holm={pa_:.4f} dz={c['dz']:+.2f} v/d={c['vit']}/{c['der']} → {st}")
    lo90, hi90, equiv = equivalencia_boot(A["so_agenda"] - A["delirio"], 0.01, seed=ctx.seed)
    rep.log(f"  S4 (equivalência, margem ±1,0 pp): so_agenda − delirio, IC90%=[{100 * lo90:+.2f},{100 * hi90:+.2f}] pp → {'EQUIVALENTES (dentro da margem)' if equiv else 'equivalência NÃO demonstrada (o IC90% não cabe na margem)'}")
