    for a, b in (("so_agenda", "baseline"), ("delirio", "baseline")):
        ce = comparar_pareado(R[a]["ece"], R[b]["ece"], seed=ctx.seed)
        cb = comparar_pareado(R[a]["brier"], R[b]["brier"], seed=ctx.seed)
        cl = comparar_pareado(R[a]["test_loss"], R[b]["test_loss"], seed=ctx.seed)
        rep.log(f"  {a} − {b}: ΔECE={ce['media']:+.4f} IC95%[{ce['lo']:+.4f},{ce['hi']:+.4f}] | ΔBrier={cb['media']:+.4f} IC95%[{cb['lo']:+.4f},{cb['hi']:+.4f}] | Δloss de teste={cl['media']:+.3f} IC95%[{cl['lo']:+.3f},{cl['hi']:+.3f}]")
    # replicação em escala: R3 (600–639) + R4 (800–859) agrupados — SÓ DESCRITIVO (a R3 já foi vista; não confirma nada)
    rep.log(f"  Expectativa pré-registrada: S1 em 0 a +0,8 pp. Observado: {100 * cm['S1']['media']:+.2f} pp "
            f"({'dentro' if 0 <= cm['S1']['media'] <= 0.008 else 'fora'} do intervalo previsto) — o +0,77 pp da R3 {'se manteve' if cm['S1']['lo'] > 0 else 'NÃO se sustentou como efeito confirmado'} nas sementes novas.")
    rep.log("→ LEITURA HONESTA: a pergunta 'o que sobra do delírio quando se tira o ruído?' é respondida só para ESTA tarefa sintética e rede pequena. "
            "Se S1 não foi confirmada, o +0,77 pp da R3 era compatível com sorte de seleção (maldição do vencedor entre 12 comparações); se foi, o efeito é pequeno e vem da agenda, não do delírio.")
    ctx.res["r4_sched"] = {"S": {k: (cm[k]["media"], cm[k]["lo"], cm[k]["hi"], cm[k]["p"]) for k in cm}, "holm": [float(x) for x in ps], "status": status,
                           "equiv": (lo90, hi90, equiv), "n": n_sem, "medias": {m: float(A[m].mean()) for m in modos}, "mde": mde}


