# BLOCO 8 — LÓGICA CRIATIVA REVERSA, PILHA DE 10 NÍVEIS, RAZÃO LÓGICO-DUAL
# ======================================================================


class DialogoCriativo:
    """Pergunta com lógica criativa, resposta com criatividade lógica; depois
    os papéis se INVERTEM (e, nas rodadas ímpares, a pergunta é construída ao
    contrário: parte-se da resposta e acha-se a pergunta que a produziria).
    Estado compartilhado s_{t+1} = (1−λ_t) s_t + λ_t f(s_t), λ_t = 1/(t+2)
    (Robbins–Monro) até cos(s_t, s_{t−1}) ≥ 0.999 por 3 inversões seguidas."""

    def __init__(self, lake: DicionarioLake, rng, obs):
        self.lake, self.rng, self.obs = lake, rng, obs
        self.pal = list(lake.palavras_semente)
        self.M = np.array([lake.vetor(p) for p in self.pal])

    def _nn(self, v, excl=()):
        sims = self.M @ normalizar(v)
        for i in np.argsort(-sims):
            if self.pal[i] not in excl:
                return self.pal[i]
        return self.pal[0]

    def perguntar(self, s):  # lógica criativa: a − b + c com b, c sorteados
        a = self._nn(s)
        b, c = self.rng.choice(self.pal, 2, replace=False)
        q = normalizar(0.6 * s + 0.4 * (self.lake.vetor(a) - self.lake.vetor(b) + self.lake.vetor(c)))
        return q, f"O que resulta de '{a}' menos '{b}' mais '{c}'?"

    def perguntar_reverso(self, s):  # lógica criativa REVERSA: resposta → pergunta
        w = self._nn(s)
        b, c = self.rng.choice(self.pal, 2, replace=False)
        a = self._nn(self.lake.vetor(w) + self.lake.vetor(b) - self.lake.vetor(c), excl=(b, c))
        q = normalizar(0.6 * s + 0.4 * (self.lake.vetor(a) - self.lake.vetor(b) + self.lake.vetor(c)))
        return q, f"Que pergunta tem '{w}' como resposta? Tente '{a}' − '{b}' + '{c}'."

    def responder(self, q, beta, t):  # criatividade lógica: atenção suave + salto criativo decrescente
        pesos = softmax(self.M @ normalizar(q), 1.0 / beta)
        r = pesos @ self.M + (0.5 / (t + 1)) * self.rng.standard_normal(self.M.shape[1])
        r = normalizar(r)
        return r, self._nn(r)

    def rodar(self, maxit=60):
        s = normalizar(self.rng.standard_normal(self.M.shape[1]))
        agentes = {"A": 8.0, "B": 2.0}  # A = rigoroso (β alto), B = criativo (β baixo)
        perguntador, seq, texto, ok_seq = "A", 0, [], 0
        for t in range(maxit):
            respondedor = "B" if perguntador == "A" else "A"
            q, txtq = (self.perguntar_reverso(s) if t % 2 else self.perguntar(s))
            r, pal = self.responder(q, agentes[respondedor], t)
            lam = 1.0 / (t + 2)
            novo = normalizar((1 - lam) * s + lam * r)
            c = cos(novo, s)
            if t < 4 or t % 10 == 0:
                texto.append(f"  rodada {t:>2} [{perguntador} pergunta → {respondedor} responde] {txtq}  ⇒ '{pal}'  (cos Δs={c:.5f})")
            self.obs.registrar("dialogo", novo)
            s = novo
            ok_seq = ok_seq + 1 if c >= 0.999 else 0
            if ok_seq >= 3:
                texto.append(f"  CONVERGIU na rodada {t} (3 inversões seguidas com cos≥0.999). Resposta estável: '{self._nn(s)}'")
                return True, t, texto, self._nn(s)
            perguntador = respondedor  # INVERSÃO de papéis
        texto.append("  limite de rodadas atingido sem critério completo.")
        return False, maxit, texto, self._nn(s)


class PilhaMeta10:
    """Dez níveis de cognição recursiva sobre estados metacognitivos. Cada
    nível k tem seu próprio operador F_k; o nível k observa o resultado do k−1.
    Direta: 1→10; reversa: 10→1. 'Imersão': a saída realimenta a entrada até o
    ponto fixo (auto-observável).
    diversidade ε ∈ [0,1]: ε=1 → operadores independentes; ε→0 → todos iguais
    (W_k = (1−ε)W₀ + εW_k′; combinação convexa preserva a contração)."""

    def __init__(self, rng, niveis=10, eps: float = 1.0):
        if eps >= 1.0:
            self.ops = [MetaCognicao(rng) for _ in range(niveis)]
        else:
            base = MetaCognicao(rng)
            self.ops = []
            for _ in range(niveis):
                op = MetaCognicao(rng)
                op.W = (1 - eps) * base.W + eps * op.W
                op.b = (1 - eps) * base.b + eps * op.b
                self.ops.append(op)

    def F(self, k, m, e):
        return self.ops[k].operador(m, e + 0.3 * (m - 0.25))

    def passada(self, m, e, ordem):
        for k in ordem:
            m = self.F(k, m, e)
        return m

    def ponto_fixo_ordem(self, m0, e, ordem, tol=1e-12, maxit=400):
        m = np.asarray(m0, float)
        trilha = [m.copy()]
        for i in range(maxit):
            n = 0.5 * m + 0.5 * self.passada(m, e, ordem)
            trilha.append(n.copy())
            if np.abs(n - m).sum() < tol:
                return n, i + 1, trilha
            m = n
        return m, maxit, trilha

    def ponto_fixo(self, m0, e, reverso, tol=1e-12, maxit=400):
        ordem = list(range(len(self.ops)))
        return self.ponto_fixo_ordem(m0, e, ordem[::-1] if reverso else ordem, tol, maxit)

    def ponto_fixo_medio(self, m0, e, tol=1e-12, maxit=600):
        """Operador MÉDIO F̄(m)=(1/K)ΣF_k(m): independe da ordem por construção."""
        m = np.asarray(m0, float)
        for i in range(maxit):
            n = 0.5 * m + 0.5 * np.mean([self.F(k, m, e) for k in range(len(self.ops))], axis=0)
            if np.abs(n - m).sum() < tol:
                return n, i + 1
            m = n
        return m, maxit

    def comutador_medio(self, e, rng, n_est=10):
        """média de ‖F_i(F_j m) − F_j(F_i m)‖₁ sobre pares i<j e estados m aleatórios do simplex."""
        v = []
        K = len(self.ops)
        for _ in range(n_est):
            m = rng.dirichlet(np.ones(4))
            for i in range(K):
                for j in range(i + 1, K):
                    v.append(np.abs(self.F(i, self.F(j, m, e), e) - self.F(j, self.F(i, m, e), e)).sum())
        return float(np.mean(v))
    def contracao(self, e, ordem, rng, n=30):
        """fator médio de contração ‖P(a)−P(b)‖₁/‖a−b‖₁ da passada P sobre pares a,b do simplex
        (quão pouco a saída 'lembra' da entrada, isto é, dos primeiros níveis)."""
        r = []
        for _ in range(n):
            a, b = rng.dirichlet(np.ones(4)), rng.dirichlet(np.ones(4))
            r.append(np.abs(self.passada(a, e, ordem) - self.passada(b, e, ordem)).sum() / (np.abs(a - b).sum() + 1e-12))
        return float(np.mean(r))


def razao_logico_dual(passos=12):
    """Investiga o que não é decidível por uma razão dual: cada proposição
    recebe um par (grau de verdade t, grau de falsidade f) — como na lógica
    paraconsistente de Belnap. Em vez de forçar V/F, observa-se a dinâmica."""
    out = {}
    # 1) Mentiroso: "esta frase é falsa": t' = f, f' = t (oscila) -> média de Cesàro = (0.5,0.5)
    t, f = 0.9, 0.1
    serie = []
    for _ in range(passos):
        t, f = f, t
        serie.append(t)
    out["mentiroso"] = (float(np.mean(serie)), 1 - float(np.mean(serie)), f"oscila {serie[:4]}... média de Cesàro")
    # 2) Veraz: "esta frase é verdadeira": t'=t -> ponto fixo depende do prior (indecidível, 2 pontos fixos)
    out["veraz"] = (0.9, 0.1, "qualquer valor é ponto fixo; o prior decide (não-cognoscível pela lógica sozinha)")
    # 3) Goldbach: evidência empírica -> probabilidade (regra de sucessão de Laplace) com incerteza epistêmica
    def primo(n):
        return n > 1 and all(n % d for d in range(2, int(n ** 0.5) + 1))
    N = 4000
    ok = sum(any(primo(p) and primo(n - p) for p in range(2, n // 2 + 1)) for n in range(4, N, 2))
    tot = len(range(4, N, 2))
    p = (ok + 1) / (tot + 2)
    out["goldbach"] = (p, 1 - p, f"{ok}/{tot} pares testados; Laplace; prova formal AUSENTE (evidência ≠ demonstração)")
    return out


def bloco8(ctx: Contexto):
    rep, rng = ctx.rep, ctx.rng
    rep.titulo("BLOCO 8 — Lógica criativa reversa, pilha de 10 níveis (análise + reconciliação), razão lógico-dual")
    rep.sub("Diálogo pergunta/resposta com inversão de papéis até convergir")
    d = DialogoCriativo(ctx.lake, rng, ctx.obs)
    ok, it, linhas, resp = d.rodar()
    for l in linhas:
        rep.log(l)
    ctx.res["dialogo"] = (ok, it, resp)
    rep.log("→ convergência é garantida por construção (passo 1/(t+2)); o que se mede é QUANTAS inversões foram necessárias.")

    rep.sub("Pilha de 10 níveis (direta 1→10 e reversa 10→1, com realimentação) e por que NÃO comutam")
    pil = PilhaMeta10(rng)
    pa = ProbabilidadeAninhada(np.random.default_rng(5))
    e = evidencia_de_incerteza(pa.decompor(pa.amostras(softmax(np.arange(6.0) * 0.4), 2, 20.0, 600)))
    m0 = np.full(4, 0.25)
    fd, itd, trd = pil.ponto_fixo(m0, e, reverso=False)
    fr, itr, trr = pil.ponto_fixo(m0, e, reverso=True)
    rep.log(f"direta : ponto fixo {np.array2string(fd, precision=5)} em {itd} realimentações")
    rep.log(f"reversa: ponto fixo {np.array2string(fr, precision=5)} em {itr} realimentações")
    rep.log(f"‖direta − reversa‖₁ = {np.abs(fd - fr).sum():.2e} | cos 2θ(direta, reversa) = {cos_duplo_angulo(fd, fr):.8f}")
    m = m0
    for k in range(10):
        m = pil.F(k, m, e)
        ctx.obs.registrar("pilha10", m)
    com = np.abs(fd - fr).sum() < 1e-6
    rep.log(f"→ as duas ordens {'COMUTAM' if com else 'NÃO comutam exatamente'}.")
    ctx.res["pilha_comuta"] = bool(com)
    ctx.res["pilha_dif"] = float(np.abs(fd - fr).sum())

    rep.sub("ANÁLISE: a diferença vem dos comutadores [F_i,F_j]≠0 — varredura da diversidade ε entre os operadores")
    rep.log("Teoria: F_dir = F_10∘…∘F_1 e F_rev = F_1∘…∘F_10 só coincidem se os F_k comutarem. Se F_k = F₀ + ε·δ_k, a "
            "diferença entre os pontos fixos deve ser O(ε) (primeira ordem no comutador) e zero em ε=0.")
    rep.log(f"{'ε':>6}{'‖dir−rev‖₁ (média de 6 pilhas)':>32}{'comutador médio ‖[F_i,F_j]m‖₁':>32}")
    eps_l = [0.0, 0.05, 0.1, 0.25, 0.5, 1.0]
    difs, coms = [], []
    for eps in eps_l:
        dd, cc = [], []
        for r in range(6):
            p = PilhaMeta10(np.random.default_rng(ctx.seed * 100 + r), eps=eps)
            a, _, _ = p.ponto_fixo(m0, e, False)
            b, _, _ = p.ponto_fixo(m0, e, True)
            dd.append(np.abs(a - b).sum())
            cc.append(p.comutador_medio(e, np.random.default_rng(r), n_est=5))
        difs.append(float(np.mean(dd)))
        coms.append(float(np.mean(cc)))
        rep.log(f"{eps:>6.2f}{difs[-1]:>32.3e}{coms[-1]:>32.3e}")
    pos = [(x, y) for x, y in zip(eps_l, difs) if x > 0 and y > 0]
    expo = float(np.polyfit(np.log([x for x, _ in pos]), np.log([y for _, y in pos]), 1)[0])
    rho = float(np.corrcoef(coms[1:], difs[1:])[0, 1])
    rep.log(f"→ ε=0 dá diferença ≈ {difs[0]:.1e} (comutam: operadores iguais). Para ε>0, ‖dir−rev‖ ∝ ε^{expo:.2f} "
            f"(ajuste log-log; 1.0 = linear) e correlaciona com o comutador médio (r={rho:+.2f}). "
            "CONCLUSÃO: a não comutação NÃO é bug nem 'dois atratores profundos'; é a assimetria entre operadores distintos, "
            "e some quando eles se parecem.")

    c1 = pil.contracao(e, [0], np.random.default_rng(11))
    c10 = pil.contracao(e, list(range(10)), np.random.default_rng(12))
    rep.log(f"Memória efetiva: um nível contrai distâncias por ≈{c1:.3f}; a passada de 10 níveis por ≈{c10:.1e}. "
            "Isto é, a saída quase não 'lembra' dos primeiros níveis — domina a CAUDA da sequência (últimos níveis aplicados). "
            "É por isso que a ordem importa tanto: a ordem decide quais operadores ficam na cauda.")
    rep.sub("RECONCILIAÇÃO: três pontos canônicos independentes da ordem")
    pal_ord = list(range(10)) + list(range(9, -1, -1))
    fp, itp, _ = pil.ponto_fixo_ordem(m0, e, pal_ord)
    fm, itm = pil.ponto_fixo_medio(m0, e)
    fmid = 0.5 * (fd + fr)
    cand = [("palíndromo 1→10→1", fp), ("média dos dois pontos fixos", fmid), ("operador médio F̄", fm)]
    ordem_d, ordem_r = list(range(10)), list(range(10))[::-1]
    rep.log(f"{'candidato':<30}{'‖−dir‖₁':>10}{'‖−rev‖₁':>10}{'resíduo sob dir':>17}{'resíduo sob rev':>17}")
    for nome, x in cand:
        rd = np.abs(0.5 * x + 0.5 * pil.passada(x, e, ordem_d) - x).sum()
        rr = np.abs(0.5 * x + 0.5 * pil.passada(x, e, ordem_r) - x).sum()
        rep.log(f"{nome:<30}{np.abs(x - fd).sum():>10.2e}{np.abs(x - fr).sum():>10.2e}{rd:>17.2e}{rr:>17.2e}")
    rep.log(f"{'(direta / reversa)':<30}{'':>10}{'':>10}"
            f"{np.abs(0.5 * fd + 0.5 * pil.passada(fd, e, ordem_r) - fd).sum():>17.2e}"
            f"{np.abs(0.5 * fr + 0.5 * pil.passada(fr, e, ordem_d) - fr).sum():>17.2e}   ← cada uma NÃO é ponto fixo da ordem oposta")
    dpal = (np.abs(fp - fd).sum(), np.abs(fp - fr).sum())
    viés = ("ATENÇÃO: o palíndromo (…,9,…,1 | 1,…) termina com a mesma sequência de níveis da " + ("reversa" if dpal[1] < dpal[0] else "direta") +
            f" e, como a passada é muito contrativa, seu ponto fixo quase coincide com o dela (‖Δ‖={min(dpal):.1e}): é invariante à inversão "
            "por construção, mas NÃO é um compromisso neutro. ") if min(dpal) < 0.1 * max(dpal) else ""
    rep.log(f"→ {viés}O operador médio é invariante à ordem e é o candidato mais neutro; "
            f"a 'média' dos dois pontos fixos é só um compromisso (resíduo pequeno sob ambas as ordens, mas não zero). "
            "Reconciliar = ESCOLHER um ponto canônico; isso não prova que os dois atratores originais sejam 'o mesmo'. "
            f"[palíndromo em {itp} it., operador médio em {itm} it.]")
    ctx.res["pilha_recon"] = (float(np.abs(fp - fd).sum()), float(np.abs(fp - fr).sum()), float(np.abs(fm - fd).sum()), expo)

    rep.sub("Razão lógico-dual aplicada ao que não é cognoscível")
    for nome, (t, f, nota) in razao_logico_dual().items():
        estado = "indeterminado estável" if abs(t - f) < 0.2 else ("tende a V" if t > f else "tende a F")
        rep.log(f"  {nome:<10} (verdade={t:.3f}, falsidade={f:.3f}) → {estado} | {nota}")
        ctx.obs.registrar("logica_dual", np.array([t, f]))


