class MiniPoker:
    """Mão de 3 cartas; cada carta = (número 2..14, palavra do dicionário).
    O 'naipe' de uma carta é (idioma, classe gramatical) da palavra — assim
    as palavras importam nas combinações ('flush linguístico').
    Categorias: trinca 5 > sequência 4 > flush 3 > par 2 > carta alta 1.
    Política: P(apostar)=σ(θ·f + média dos valores aprendidos v[palavra]);
    os v[palavra] são o 'treino do dicionário' por auto-jogo (REINFORCE)."""

    def __init__(self, lake: DicionarioLake, rng):
        self.rng = rng
        self.pal = lake.palavras_semente
        self.naipe = np.array([IDIOMAS.index(lake.entradas[p][0]) * 3 + CLASSES.index(lake.entradas[p][1]) for p in self.pal])

    def mao(self):
        r = self.rng.integers(2, 15, 3)
        w = self.rng.integers(0, len(self.pal), 3)
        return r, w

    def feats_cat(self, r, w):
        rs = sorted(r.tolist())
        trinca = rs[0] == rs[2]
        par = (not trinca) and (rs[0] == rs[1] or rs[1] == rs[2])
        seq = rs[1] == rs[0] + 1 and rs[2] == rs[1] + 1
        flush = len(set(self.naipe[w].tolist())) == 1
        cat = 5 if trinca else 4 if seq else 3 if flush else 2 if par else 1
        f = np.array([1.0, sum(rs) / 42.0, float(par), float(trinca), float(seq), float(flush)])
        return cat, f

    def jogar(self, pol1, pol2):
        """pol = (theta, v) ou None (aleatório 50%). Devolve recompensa do jogador 1 e dados p/ gradiente."""
        r1, w1 = self.mao()
        r2, w2 = self.mao()
        c1, f1 = self.feats_cat(r1, w1)
        c2, f2 = self.feats_cat(r2, w2)
        def agir(pol, f, w):
            if pol is None:
                return int(self.rng.random() < 0.5), 0.5
            th, v = pol
            p = float(sigmoide(th @ f + v[w].mean()))
            return int(self.rng.random() < p), p
        a1, p1 = agir(pol1, f1, w1)
        a2, _ = agir(pol2, f2, w2)
        forca1, forca2 = (c1, sum(r1)), (c2, sum(r2))
        cmp_ = int(forca1 > forca2) - int(forca1 < forca2)
        if a1 and a2:
            rew = 2 * cmp_
        elif a1 and not a2:
            rew = 1
        elif a2 and not a1:
            rew = -1
        else:
            rew = 0
        return rew, (a1, p1, f1, w1)


def avaliar_poker(jogo, pol, n=3000):
    return float(np.mean([jogo.jogar(pol, None)[0] for _ in range(n)]))


def bloco9(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 9 — Mini-poker (números+palavras), auto-jogo por reforço, autopoiese")
    jogo = MiniPoker(ctx.lake, np.random.default_rng(ctx.seed + 11))
    nw = len(jogo.pal)
    theta, v = np.zeros(6), np.zeros(nw)
    antes = avaliar_poker(jogo, (theta.copy(), v.copy()))
    adversario = (theta.copy(), v.copy())
    base, lr = 0.0, 0.05
    maos = 2500 if ctx.args.rapido else 6000
    for h in range(maos):
        rew, (a, p, f, w) = jogo.jogar((theta, v), adversario)
        adv = rew - base
        base += 0.01 * (rew - base)
        g = (a - p)
        theta += lr * adv * g * f
        np.add.at(v, w, lr * adv * g / 3.0)
        if (h + 1) % 250 == 0:
            adversario = (theta.copy(), v.copy())  # auto-jogo: o oponente é o "eu" de 250 mãos atrás
        if (h + 1) % 600 == 0:
            ctx.obs.registrar("poker", np.r_[theta, v[:6]])
    depois = avaliar_poker(jogo, (theta, v))
    rep.log(f"Treino por auto-jogo: {maos} mãos, REINFORCE com baseline.")
    rep.log(f"Recompensa média/mão vs. oponente aleatório (3000 mãos): antes={antes:+.3f} | depois={depois:+.3f}")
    nomes = ["viés", "soma ranks", "par", "trinca", "sequência", "flush linguístico"]
    rep.log("θ aprendido: " + ", ".join(f"{n}={x:+.2f}" for n, x in zip(nomes, theta)))
    ordem = np.argsort(-v)
    rep.log("palavras com maior valor aprendido: " + ", ".join(f"{jogo.pal[i]}({v[i]:+.2f})" for i in ordem[:4]))
    rep.log("palavras com menor valor aprendido: " + ", ".join(f"{jogo.pal[i]}({v[i]:+.2f})" for i in ordem[-4:]))
    rep.log("→ honestidade: o aprendizado útil está em θ (força da mão); o valor por palavra só importa via 'flush linguístico' "
            "e o resto é em boa parte ruído de amostragem.")
    ctx.res["poker"] = (antes, depois)

    # ---------------- Autopoiese ----------------
    rep.sub("Autopoiese: genoma que se clona, muta (inclusive a própria taxa de mutação) e sofre seleção")
    rep.log("Dois procedimentos de seleção, avaliados nas MESMAS sementes de teste novas (nunca vistas na seleção):")
    rep.log("  INGÊNUA (rodada 1): fitness em 2 sementes FIXAS (0,1), 4 gerações → o vencedor se ajusta ao ruído dessas sementes.")
    rep.log("  CV/FRESCAS (rodada 2): cada geração re-avalia TODOS os candidatos em 3 sementes NOVAS (média acumulada = 'racing'); "
            "ao final, os 3 melhores + o padrão disputam 5 sementes de SELEÇÃO separadas; o evoluído só substitui o padrão se vencer lá.")
    rep.log("  (ambas usam acurácia de validação como fitness, igual à métrica de teste; a rodada 1 usava a perda de validação)")
    jobs = ctx.jobs
    geracoes = 3 if ctx.args.rapido else 4
    cache_tk: dict = {}

    def tk(s):
        if s not in cache_tk:
            cache_tk[s] = gerar_tarefa(ctx.lake, s)
        return cache_tk[s]

    chave = lambda g: json.dumps(g, sort_keys=True)
    GP = GENOMA_PADRAO

    # --- braço A: ingênuo
    rngA = np.random.default_rng(ctx.seed + 21)
    fitA: dict[str, list[float]] = {}

    def avaliar_pop_A(pop):
        novos = [g for g in pop if chave(g) not in fitA]
        res = mapa_paralelo(_job_fit, [(g, tk(s), 300 + s, 250) for g in novos for s in (0, 1)], jobs)
        for i, g in enumerate(novos):
            fitA[chave(g)] = [res[2 * i][0], res[2 * i + 1][0]]

    popA = [GP] + [mutar_genoma(GP, rngA) for _ in range(5)]
    for ger in range(geracoes):
        avaliar_pop_A(popA)
        popA.sort(key=lambda g: -np.mean(fitA[chave(g)]))
        if ger < geracoes - 1:
            elite = popA[:3]
            popA = elite + [mutar_genoma(g, rngA) for g in elite]
    melhorA = popA[0]
    avaliar_pop_A([GP])
    insA = float(np.mean(fitA[chave(melhorA)]) - np.mean(fitA[chave(GP)]))

    # --- braço B: sementes frescas + racing + seleção separada
    rngB = np.random.default_rng(ctx.seed + 22)
    fitB: dict[str, list[float]] = {}
    popB = [GP] + [mutar_genoma(GP, rngB) for _ in range(5)]
    for ger in range(geracoes):
        sem = [10 + 3 * ger + k for k in range(3)]
        res = mapa_paralelo(_job_fit, [(g, tk(s), 300 + s, 250) for g in popB for s in sem], jobs)
        for i, g in enumerate(popB):
            fitB.setdefault(chave(g), []).extend(r[0] for r in res[3 * i:3 * i + 3])
        popB.sort(key=lambda g: -np.mean(fitB[chave(g)]))
        b = popB[0]
        rep.log(f"  [CV] geração {ger}: melhor fitness acumulado={np.mean(fitB[chave(b)]):.4f} (n={len(fitB[chave(b)])} avaliações) | "
                f"lr={b['lr']:.4f} T0={b['T0']:.2f} ciclos={b['ciclos']} larg={b['largura']} σ_mut={b['sigma_mut']:.2f}")
        ctx.obs.registrar("genoma", np.array([b["lr"] * 50, b["T0"], b["ciclos"], b["frac"], b["largura"] / 10, b["sigma_mut"]]))
        if ger < geracoes - 1:
            elite = popB[:3]
            popB = elite + [mutar_genoma(g, rngB) for g in elite]
    cands, vistos = [], set()
    for g in popB[:3] + [GP]:
        if chave(g) not in vistos:
            vistos.add(chave(g))
            cands.append(g)
    sel_seeds = [50, 51, 52, 53, 54]
    res = mapa_paralelo(_job_fit, [(g, tk(s), 400 + s, 250) for g in cands for s in sel_seeds], jobs)
    sel = [float(np.mean([r[0] for r in res[5 * i:5 * i + 5]])) for i in range(len(cands))]
    ip = [chave(g) for g in cands].index(chave(GP))
    ib = int(np.argmax(sel))
    melhorB = cands[ib] if sel[ib] > sel[ip] else GP
    rep.log(f"  [CV] seleção em 5 sementes separadas: " + " | ".join(
        f"{'padrão' if chave(g) == chave(GP) else 'cand' + str(i)}={sel[i]:.4f}" for i, g in enumerate(cands)) +
            f" → {'EVOLUÍDO substitui o padrão' if melhorB is not GP else 'mantém o PADRÃO (nenhum candidato venceu na seleção)'}")
    # in-sample do braço B = fitness acumulado do vencedor (racing) menos o do padrão
    insB = float(np.mean(fitB[chave(melhorB)]) - np.mean(fitB[chave(GP)]))

    # --- braço C [R3, melhoria R2-#10 parcial]: BUSCA ALEATÓRIA com o MESMO orçamento e as MESMAS sementes do braço B
    rngC = np.random.default_rng(ctx.seed + 23)

    def genoma_aleatorio(rg):
        g = dict(GP)
        g["lr"] = float(math.exp(rg.uniform(math.log(0.002), math.log(0.05))))
        g["T0"] = float(math.exp(rg.uniform(math.log(0.1), math.log(4.0))))
        g["frac"] = float(rg.uniform(0.2, 0.8))
        g["ciclos"] = int(rg.integers(2, 9))
        g["largura"] = int(8 + 2 * rg.integers(0, 7))
        return g

    fitC: dict[str, list[float]] = {}
    popC = [GP] + [genoma_aleatorio(rngC) for _ in range(5)]
    for ger in range(geracoes):
        sem = [10 + 3 * ger + k for k in range(3)]
        res = mapa_paralelo(_job_fit, [(g, tk(s), 300 + s, 250) for g in popC for s in sem], jobs)
        for i, g in enumerate(popC):
            fitC.setdefault(chave(g), []).extend(r[0] for r in res[3 * i:3 * i + 3])
        popC.sort(key=lambda g: -np.mean(fitC[chave(g)]))
        if ger < geracoes - 1:
            popC = popC[:1] + [genoma_aleatorio(rngC) for _ in range(5)]   # sem herança: só descarta e sorteia de novo (mantém o melhor)
    candsC, vistosC = [], set()
    for g in popC[:3] + [GP]:
        if chave(g) not in vistosC:
            vistosC.add(chave(g))
            candsC.append(g)
    resC = mapa_paralelo(_job_fit, [(g, tk(s), 400 + s, 250) for g in candsC for s in sel_seeds], jobs)
    selC = [float(np.mean([r[0] for r in resC[5 * i:5 * i + 5]])) for i in range(len(candsC))]
    ipC = [chave(g) for g in candsC].index(chave(GP))
    ibC = int(np.argmax(selC))
    melhorC = candsC[ibC] if selC[ibC] > selC[ipC] else GP
    rep.log(f"  [ALEATÓRIA] mesma seleção em 5 sementes separadas → {'candidato aleatório substitui o padrão' if melhorC is not GP else 'mantém o PADRÃO'} "
            f"(sel. do melhor={max(selC):.4f} vs padrão={selC[ipC]:.4f}).")
    # --- teste final (sementes nunca vistas)
    n_te = 6 if ctx.args.rapido else 12
    te_seeds = list(range(200, 200 + n_te))
    cfgs = {"padrão": GP, "ingênuo": melhorA, "CV/frescas": melhorB, "busca aleatória": melhorC}
    acc_te = {}
    for nome, g in cfgs.items():
        r = mapa_paralelo(_job_fit, [(g, tk(s), 500 + s, 250) for s in te_seeds], jobs)
        acc_te[nome] = np.array([x[1] for x in r])
    rep.log(f"Teste em {n_te} sementes novas (600 amostras cada): " + " | ".join(
        f"{n}={a.mean():.4f}±{a.std():.4f}" for n, a in acc_te.items()))
    for nome in ("ingênuo", "CV/frescas"):
        c = comparar_pareado(acc_te[nome], acc_te["padrão"], seed=ctx.seed)
        if nome == "CV/frescas" and melhorB is GP:
            rep.log(f"  {nome} − padrão: idêntico por construção (seleção manteve o padrão).")
        else:
            rep.log(f"  {nome:<11} − padrão: Δacc teste = {100 * c['media']:+.2f} pp IC95%=[{100 * c['lo']:+.2f},{100 * c['hi']:+.2f}] "
                    f"p={c['p']:.3f} vitórias/derrotas={c['vit']}/{c['der']}")
    if melhorB is not GP and melhorC is not GP:
        cx = comparar_pareado(acc_te["CV/frescas"], acc_te["busca aleatória"], seed=ctx.seed)
        rep.log(f"  CV/frescas (evolução) − busca aleatória (mesmo orçamento de {len(fitB)} genomas): Δacc teste = {100 * cx['media']:+.2f} pp "
                f"IC95%=[{100 * cx['lo']:+.2f},{100 * cx['hi']:+.2f}] p={cx['p']:.3f} v/d={cx['vit']}/{cx['der']}")
    elif melhorC is GP:
        rep.log("  busca aleatória: mantém o padrão (idêntica a ele por construção neste teste).")
    cr = comparar_pareado(acc_te["busca aleatória"], acc_te["padrão"], seed=ctx.seed)
    if melhorC is not GP:
        rep.log(f"  busca aleatória − padrão: Δacc teste = {100 * cr['media']:+.2f} pp IC95%=[{100 * cr['lo']:+.2f},{100 * cr['hi']:+.2f}] p={cr['p']:.3f} v/d={cr['vit']}/{cr['der']}")
    ganho_ing = float(acc_te["ingênuo"].mean() - acc_te["padrão"].mean())
    ganho_cv = float(acc_te["CV/frescas"].mean() - acc_te["padrão"].mean())
    rep.log(f"SOBREAJUSTE (otimismo = ganho visto na seleção − ganho em teste): ingênuo = {100 * insA:+.2f} pp visto vs {100 * ganho_ing:+.2f} pp em teste "
            f"→ otimismo {100 * (insA - ganho_ing):+.2f} pp | CV/frescas = {100 * insB:+.2f} pp visto vs {100 * ganho_cv:+.2f} pp em teste "
            f"→ otimismo {100 * (insB - ganho_cv):+.2f} pp")
    rep.log("→ leitura: o que importa é se o evoluído bate o padrão em sementes NOVAS; com a validação ruidosa, 'ganho' na seleção é "
            "em boa parte maldição do vencedor (winner's curse). A defesa aqui é re-avaliar em dados frescos e deixar o padrão ganhar na dúvida.")
    caminho = os.path.join(os.path.dirname(os.path.abspath(ctx.args.saida)), "genoma_final.json")
    try:
        with open(caminho, "w", encoding="utf-8") as f:
            json.dump(melhorB, f, indent=2)
        rep.log(f"Genoma escolhido (CV/frescas) gravado em {caminho} (autocontido, sem dependências externas).", vol=True)
    except OSError as e:
        rep.log(f"(não foi possível gravar o genoma: {e})", vol=True)
    ctx.res["auto_obj"] = {"padrão": GP, "ingênuo": melhorA, "CV/frescas": melhorB, "busca aleatória": melhorC}   # [R9] genomas para o laudo de escrutínio (BLOCO 16)
    ctx.res["genoma"] = (float(acc_te["padrão"].mean()), float(acc_te["ingênuo"].mean()), float(acc_te["CV/frescas"].mean()),
                         100 * (insA - ganho_ing), 100 * (insB - ganho_cv), melhorB is not GP,
                         float(acc_te["busca aleatória"].mean()), melhorC is not GP)


