CORPUS = ("a mente observa o caos e o caos observa a mente . o padrão nasce da dúvida e a dúvida nasce do limite . "
          "pensar é criar uma forma no tempo . o sonho reflete a luz e a sombra no espelho da palavra . "
          "a rede aprende e esquece e aprende de novo . a ordem é um atrator e o delírio é a sua sombra . "
          "o número conta a vida e a vida conta o número . a verdade é um limite que a curiosidade persegue .").split()


# ----------------------------------------------------------------------
# BLOCO 10 (a) — padrões textuais × caóticos (autocorrelação, entropias, espectro)
# ----------------------------------------------------------------------

def autocorr(x, lag):
    x = x - x.mean()
    return float((x[:-lag] @ x[lag:]) / (x @ x + 1e-12))


def entropia_serie(x, bins=8):
    h, _ = np.histogram(x, bins=bins)
    return entropia(h / h.sum())


def info_mutua(x, lag=1, bins=6):
    a, b = x[:-lag], x[lag:]
    H, _, _ = np.histogram2d(a, b, bins=bins)
    P = H / H.sum()
    pa, pb = P.sum(1, keepdims=True), P.sum(0, keepdims=True)
    nz = P > 0
    return float((P[nz] * np.log2(P[nz] / (pa @ pb)[nz])).sum())


def espectro(x):
    S = np.abs(np.fft.rfft(x - x.mean())) ** 2
    S = S[1:]
    f = np.arange(1, len(S) + 1)
    S = S + 1e-12
    plano = float(np.exp(np.mean(np.log(S))) / np.mean(S))  # planura espectral (1 = ruído branco)
    ent = entropia(S / S.sum()) / math.log2(len(S))
    inc = float(np.polyfit(np.log(f), np.log(S), 1)[0])
    return plano, ent, inc, int(f[np.argmax(S)])


def entropia_permutacao(x, ordem=3):
    from itertools import permutations
    cont = {p: 0 for p in permutations(range(ordem))}
    for i in range(len(x) - ordem + 1):
        cont[tuple(np.argsort(x[i:i + ordem]))] += 1
    c = np.array(list(cont.values()), float)
    return entropia(c / c.sum()) / math.log2(math.factorial(ordem))


def gerar_series(ctx: Contexto, n=512):
    rng = np.random.default_rng(ctx.seed + 31)
    bi: dict[str, list[str]] = {}
    for a, b in zip(CORPUS[:-1], CORPUS[1:]):
        bi.setdefault(a, []).append(b)
    w, toks = CORPUS[0], []
    for _ in range(n):
        toks.append(w)
        w = rng.choice(bi.get(w, CORPUS))
    texto = np.array([len(t) for t in toks], float)  # "ritmo" do texto: comprimento das palavras
    embaralhado = rng.permutation(texto)
    lor = fluxo_caos(n * 5, ctx.seed + 33)[::5, 0]
    x, log_ = 0.37, []
    for _ in range(n):
        x = 3.9 * x * (1 - x)
        log_.append(x)
    return {"texto(Markov)": texto, "texto embaralhado": embaralhado, "Lorenz x": lor,
            "logístico r=3.9": np.array(log_), "ruído branco": rng.standard_normal(n)}, toks


def bloco10a_padroes(ctx: Contexto):
    rep = ctx.rep
    rep.sub("Padrões textuais x caóticos (correlação, entropia, informação mútua, FFT, entropia de permutação)")
    S, toks = gerar_series(ctx)
    rep.log("amostra do texto gerado por cadeia de Markov: " + " ".join(toks[:18]) + " ...")
    rep.log(f"{'série':<18}{'ac(1)':>7}{'ac(5)':>7}{'H':>6}{'MI(1)':>7}{'planura':>8}{'H_esp':>7}{'inclin.':>8}{'f_dom':>6}{'PE(3)':>7}")
    for nome, x in S.items():
        pl, he, inc, fd = espectro(x)
        rep.log(f"{nome:<18}{autocorr(x, 1):>7.3f}{autocorr(x, 5):>7.3f}{entropia_serie(x):>6.2f}{info_mutua(x):>7.3f}"
                f"{pl:>8.3f}{he:>7.3f}{inc:>8.2f}{fd:>6d}{entropia_permutacao(x):>7.3f}")
        ctx.obs.registrar("padroes", np.array([autocorr(x, 1), autocorr(x, 5), entropia_serie(x) / 3, info_mutua(x), pl, he, entropia_permutacao(x)]))

    def xcorr(a, b, L=20):
        a, b = (a - a.mean()) / a.std(), (b - b.mean()) / b.std()
        return max(abs(float(np.mean(a[:len(a) - k] * b[k:]))) for k in range(L))
    t, lor, rb = S["texto(Markov)"], S["Lorenz x"], S["ruído branco"]
    rep.log(f"correlação cruzada máx. (lags≤20): texto×Lorenz={xcorr(t, lor):.3f} | texto×ruído={xcorr(t, rb):.3f} | "
            f"Lorenz×logístico={xcorr(lor, S['logístico r=3.9']):.3f}")
    mi_t, mi_s = info_mutua(t), info_mutua(S["texto embaralhado"])
    rep.log(f"Padrão sistêmico: MI(1) do texto={mi_t:.3f} vs. embaralhado (controle)={mi_s:.3f}; "
            f"PE(3) Lorenz={entropia_permutacao(lor):.3f} vs ruído={entropia_permutacao(rb):.3f}.")
    rep.log("→ Leitura: o texto tem estrutura de curto alcance (MI > controle) mas espectro mais 'plano' que o caos determinístico; "
            "Lorenz/logístico têm baixa entropia de permutação (determinismo) e espectro concentrado em baixas frequências; "
            "a correlação cruzada texto×caos é do mesmo nível do texto×ruído → NENHUM acoplamento sistêmico real entre os dois "
            "(como esperado: são processos independentes).")


def pensar_sobre_pensar(ctx: Contexto, profundidade=4):
    flux = fluxo_caos(60, ctx.seed + 41)
    verbos = ["penso", "observo", "suspeito", "sinto", "intuo"]
    alvos = ["que", "como", "se"]
    def rec(n, i):
        if n == 0:
            return "nada"
        v = verbos[int(abs(flux[i, 0]) * 2) % len(verbos)]
        a = alvos[int(abs(flux[i, 1]) * 2) % len(alvos)]
        if n == 1:
            return f"{v} {a} não penso em {rec(0, i)}"
        return f"{v} {a} {rec(n - 1, i + 1)}"
    return ("Eu " + rec(profundidade, 0) + " — e o nada, ao ser pensado, deixa de ser nada; "
            "pensar o não-pensar é o pensamento olhando para o próprio espelho em silêncio.")


# ----------------------------------------------------------------------
# BLOCO 10 (b) — meta-observador: k-means e estatísticas dos vetores internos
# ----------------------------------------------------------------------

def kmeans(X, k, rng, it=30):
    C = [X[rng.integers(len(X))]]
    for _ in range(k - 1):
        d = np.min([((X - c) ** 2).sum(1) for c in C], axis=0)
        C.append(X[rng.choice(len(X), p=d / d.sum())] if d.sum() > 0 else X[rng.integers(len(X))])
    C = np.array(C)
    for _ in range(it):
        lab = np.argmin(((X[:, None] - C[None]) ** 2).sum(2), axis=1)
        for j in range(k):
            if (lab == j).any():
                C[j] = X[lab == j].mean(0)
    return lab, C


def estatisticas_observador(X, rot, rng):
    Xc = X - X.mean(0)
    _, S, _ = np.linalg.svd(Xc, full_matrices=False)
    var = S ** 2 / (S ** 2).sum()
    lab, C = kmeans(Xc, 4, rng)
    nomes = sorted(set(rot))
    pur, coer = {}, {}
    for n in nomes:
        idx = [i for i, r in enumerate(rot) if r == n]
        cont = np.bincount(lab[idx], minlength=4)
        pur[n] = cont.max() / len(idx)
        sub = Xc[idx]
        if len(idx) > 1:
            sims = [cos(sub[i], sub[j]) for i in range(len(idx)) for j in range(i + 1, len(idx))]
            coer[n] = float(np.mean(sims))
        else:
            coer[n] = float("nan")
    return var, lab, pur, coer, nomes


def bloco10b_observador(ctx: Contexto):
    rep, obs = ctx.rep, ctx.obs
    rep.sub("Meta-observador: vetores internos de todos os componentes → padrões emergentes (PCA + k-means)")
    X, rot = obs.matriz()
    comps = sorted(set(rot))
    rep.log(f"{len(rot)} vetores de {len(comps)} componentes projetados em {obs.DIM} dimensões: {', '.join(comps)}")
    rng = np.random.default_rng(ctx.seed + 51)
    var, lab, pur, coer, nomes = estatisticas_observador(X, rot, rng)
    # controle: mesma estrutura de rótulos com trajetórias de passeio aleatório
    ctrl = MetaObservador(ctx.seed + 7)
    for n, lista in obs.reg.items():
        passeio = np.zeros(len(lista[0]))
        for v in lista[:30]:  # controle = passeio aleatório (trajetória suave sem estrutura), não ruído independente
            passeio = passeio + rng.standard_normal(len(v))
            ctrl.registrar(n, passeio)
    Xc, rc = ctrl.matriz()
    var_c, _, pur_c, coer_c, _ = estatisticas_observador(Xc, rc, rng)
    rep.log(f"variância explicada PC1/PC2/PC3: real = {var[0]:.2f}/{var[1]:.2f}/{var[2]:.2f} | controle passeio-aleatório = "
            f"{var_c[0]:.2f}/{var_c[1]:.2f}/{var_c[2]:.2f}")
    rep.log(f"{'componente':<20}{'n':>4}{'pureza cluster':>16}{'(controle)':>11}{'coerência cos':>15}{'(controle)':>11}")
    for n in nomes:
        rep.log(f"{n:<20}{len(obs.reg[n]):>4}{pur[n]:>16.2f}{pur_c[n]:>11.2f}{coer[n]:>15.2f}{coer_c[n]:>11.2f}")
    cent = {n: normalizar(X[[i for i, r in enumerate(rot) if r == n]].mean(0)) for n in nomes}
    pares = sorted(((cos(cent[a], cent[b]), a, b) for i, a in enumerate(nomes) for b in nomes[i + 1:]), reverse=True)
    rep.log("pares de componentes com centróides mais alinhados: " +
            "; ".join(f"{a}~{b} ({c:+.2f})" for c, a, b in pares[:3]))
    mais_coerentes = [n for n in nomes if coer[n] > coer_c[n] + 0.2][:6]
    rep.log(f"componentes cujos estados são mais auto-consistentes que o aleatório: {mais_coerentes}")
    rep.log("→ honestidade: a projeção aleatória entre dimensões diferentes é arbitrária; só interprete diferenças "
            "contra o controle (passeio aleatório; ainda é um nulo simples). Pureza alta em componentes com poucas amostras pode ser acaso.")
    ctx.res["obs_pc1"] = (float(var[0]), float(var_c[0]))


