SEM0_ABLACAO = 1000   # R5: sementes NOVAS 1000–1039 (R1/R2 0–31, autopoiese 0–60 e 200–211, R3 600–639 e 700–739, R4 800–859)
CAT_ORDEM = [("animal", ("animal.n.01",)), ("pessoa", ("person.n.01",)), ("corpo", ("body_part.n.01",)), ("planta", ("plant.n.02",)),
             ("comida", ("food.n.01", "food.n.02")), ("fenomeno", ("natural_phenomenon.n.01",)), ("tempo", ("time_period.n.01",)),
             ("sentimento", ("feeling.n.01",)), ("comunicacao", ("communication.n.02",)), ("agua", ("body_of_water.n.01",)),
             ("cognicao", ("cognition.n.01",)), ("estrutura", ("structure.n.01",)), ("artefato", ("artifact.n.01",))]
COMPONENTES = ("D", "L", "A", "M")
BITS = {"D": 3, "L": 2, "A": 1, "M": 0}
NOME_COMP = {"D": "vetores do dicionário (D)", "L": "cronograma de delírio/caos (L)", "A": "redes adversárias/GAN (A)", "M": "laço metacognitivo de incerteza (M)"}


# ----------------------------------------------------------------------
# BLOCO 11 (a) — tarefa de ponta a ponta, Shapley exata, alpha-spending e meta-análise
# ----------------------------------------------------------------------

def vocab_e2e(wns, minimo: int = 6):
    """Palavras (substantivos) dos gabaritos cujo rótulo = 1ª categoria (na ordem fixa CAT_ORDEM) da qual descendem; categorias com ≥ `minimo` palavras."""
    pal: dict = {}
    for wn in wns:
        for w, d in wn.items():
            if d["pos"] != "n":
                continue
            for nome, nos in CAT_ORDEM:
                if any(n in d["anc"] for n in nos):
                    pal[w] = nome
                    break
    cont: dict = {}
    for c in pal.values():
        cont[c] = cont.get(c, 0) + 1
    ok = [c for c, _ in CAT_ORDEM if cont.get(c, 0) >= minimo]
    palavras = sorted(w for w, c in pal.items() if c in ok)
    return palavras, np.array([ok.index(pal[w]) for w in palavras]), ok


def softmax_np(z, T: float = 1.0):
    z = z / T
    z = z - z.max(-1, keepdims=True)
    e = np.exp(z)
    return e / e.sum(-1, keepdims=True)


def comite_ridge(X, y, K: int, n_memb: int, rng, lamb: float = 1.0):
    """Comitê de classificadores de cumeeira (alvo one-hot) em reamostras bootstrap: lista de matrizes (d+1, K). [melhoria: incerteza epistêmica por COMITÊ]"""
    n = len(X)
    Xb, Y = np.c_[X, np.ones(n)], np.eye(K)[y]
    out = []
    for _ in range(n_memb):
        ii = rng.integers(0, n, n)
        Xi, Yi = Xb[ii], Y[ii]
        out.append(np.linalg.solve(Xi.T @ Xi + lamb * np.eye(Xb.shape[1]), Xi.T @ Yi))
    return out


def incerteza_epistemica(Ws, Xu):
    """Informação mútua do comitê: H(média das previsões) − média das H(previsões); previsão do membro = softmax(4·escore)."""
    Xb = np.c_[Xu, np.ones(len(Xu))]
    P = np.array([softmax_np(4.0 * (Xb @ W)) for W in Ws])
    pm = P.mean(0)
    H = lambda p: -(p * np.log(p + 1e-12)).sum(-1)
    return H(pm) - H(P).mean(0)


def laco_consulta(X, y, K: int, pool, ini, rodadas: int, por_rodada: int, usar_incerteza: bool, rng):
    """Laço metacognitivo: a cada rodada consulta o oráculo de rótulos nas `por_rodada` palavras de maior incerteza epistêmica (ou aleatórias, se desligado)."""
    rot, pool = list(ini), list(pool)
    for _ in range(rodadas):
        if usar_incerteza:
            Ws = comite_ridge(X[rot], y[rot], K, 5, rng)
            u = incerteza_epistemica(Ws, X[pool])
            ordem = np.lexsort((np.arange(len(pool)), -np.round(u, 12)))[:por_rodada]
        else:
            ordem = rng.permutation(len(pool))[:por_rodada]
        for i in sorted(ordem, reverse=True):
            rot.append(pool.pop(int(i)))
    return rot


def gan_condicional(X, y, K: int, seed: int, passos: int = 100, zd: int = 4, h: int = 16, por_classe: int = 4):
    """GAN condicional pequena (discriminador com norma espectral): gera 4 exemplos sintéticos por classe a partir dos exemplos rotulados."""
    rng = np.random.default_rng(seed)
    n, d = X.shape
    G = MLP([zd + K, h, h, d], rng)
    D = MLP([d + K, h, h, 1], rng, sn=True)
    oh = np.eye(K)[y]
    for _ in range(passos):
        z = rng.standard_normal((n, zd))
        fake = G.forward(np.c_[z, oh])
        xd = np.r_[np.c_[X, oh], np.c_[fake, oh]]
        lab = np.r_[np.ones(n), np.zeros(n)]
        p = sigmoide(D.forward(xd).ravel())
        gW, gb, _ = D.backward(((p - lab) / (2 * n))[:, None])
        D.adam(gW, gb, 2e-3)
        z = rng.standard_normal((n, zd))
        fake = G.forward(np.c_[z, oh])
        p = sigmoide(D.forward(np.c_[fake, oh]).ravel())
        _, _, dx = D.backward(((p - 1.0) / n)[:, None])
        gW, gb, _ = G.backward(dx[:, :d])
        G.adam(gW, gb, 2e-3)
    ys = np.repeat(np.arange(K), por_classe)
    z = rng.standard_normal((len(ys), zd))
    return G.forward(np.c_[z, np.eye(K)[ys]]), ys


def preparar_features(X, dmax: int = 16):
    """PCA global NÃO supervisionado (≤dmax componentes) + padronização + preenchimento com zeros até dmax colunas."""
    Xc = X - X.mean(0)
    _, _, Vt = np.linalg.svd(Xc, full_matrices=False)
    Z = Xc @ Vt[:dmax].T
    Z = Z / (Z.std(0) + 1e-9)
    return np.c_[Z, np.zeros((len(Z), dmax - Z.shape[1]))]


GRUPO_E2E = 5   # sementes por lote (fixo, independe de --jobs)


def job_e2e_grupo(args):
    """Um grupo de sementes: laços de consulta e GANs por semente; depois TODOS os braços (16 por semente) treinados num único lote.
    Devolve (acc[n_sem_grupo, 16] com índice = D<<3|L<<2|A<<1|M, diag[n_sem_grupo, 4] = acurácia de cumeeira (D,M) como diagnóstico de sinal)."""
    sems, Xon, Xoff, y, K, rodadas, por_rodada, passos = args
    specs, meta = [], []
    diag = np.zeros((len(sems), 4))
    testes = []
    for q, s in enumerate(sems):
        rng = np.random.default_rng(7000 + s)
        teste, pool = [], []
        for c in range(K):
            idx = np.flatnonzero(y == c)
            idx = idx[rng.permutation(len(idx))]
            nt = min(int(round(0.35 * len(idx))), len(idx) - 2)
            teste += list(idx[:nt])
            pool += list(idx[nt:])
        teste, pool = np.array(sorted(teste)), sorted(pool)
        testes.append(teste)
        ini = []
        for c in range(K):
            cand = [i for i in pool if y[i] == c]
            ini.append(int(cand[rng.integers(0, len(cand))]))
        pool_q = [i for i in pool if i not in ini]
        for D, X in ((1, Xon), (0, Xoff)):
            for M in (1, 0):
                r2 = np.random.default_rng(9000 + s * 13 + (0 if M else 1))
                rot = laco_consulta(X, y, K, pool_q, ini, rodadas, por_rodada, bool(M), r2)
                Xl, yl = X[rot], y[rot]
                Wr = comite_ridge(Xl, yl, K, 1, np.random.default_rng(1), lamb=1.0)[0]
                diag[q, (1 - D) * 2 + (1 - M)] = float(np.mean(np.argmax(np.c_[X[teste], np.ones(len(teste))] @ Wr, 1) == y[teste]))
                Xs, ys = gan_condicional(Xl, yl, K, 3000 + s * 17 + D * 2 + M)
                for L in (1, 0):
                    for Aa in (1, 0):
                        Xt = np.r_[Xl, Xs] if Aa else Xl
                        yt = np.r_[yl, ys] if Aa else yl
                        specs.append(dict(X=Xt, y=yt.astype(float), seed=100 + s, modo="delirio" if L else "baseline", nsaida=K))
                        meta.append((q, D, L, Aa, M))
    out = treinar_lote(specs, passos=passos)
    acc = np.zeros((len(sems), 16))
    for (q, D, L, Aa, M), (params, _) in zip(meta, out):
        X = Xon if D else Xoff
        te = testes[q]
        acc[q, (D << 3) | (L << 2) | (Aa << 1) | M] = float(np.mean(np.argmax(MLPleve(params).forward(X[te]), 1) == y[te]))
    return acc, diag


def shapley_exato(v, n: int = 4):
    """Valores de Shapley exatos para n=4 componentes. v[..., 16] (índice = máscara de bits; bit ligado = componente presente).
    Devolve φ[..., 4] na ordem COMPONENTES (D,L,A,M). Soma de φ = v(todos) − v(nenhum)."""
    fat = math.factorial
    phi = np.zeros(v.shape[:-1] + (n,))
    for ci, c in enumerate(COMPONENTES):
        b = BITS[c]
        for S in range(16):
            if (S >> b) & 1:
                continue
            k = bin(S).count("1")
            w = fat(k) * fat(n - k - 1) / fat(n)
            phi[..., ci] += w * (v[..., S | (1 << b)] - v[..., S])
    return phi


def interacao_2a(v, a: str, b: str):
    """Contraste de interação de 2ª ordem de (a,b) médio sobre os níveis dos outros dois componentes: v(ab) − v(a) − v(b) + v(∅)."""
    ba, bb = 1 << BITS[a], 1 << BITS[b]
    outros = [1 << BITS[c] for c in COMPONENTES if c not in (a, b)]
    vals = []
    for o1 in (0, outros[0]):
        for o2 in (0, outros[1]):
            r = o1 | o2
            vals.append(v[..., r | ba | bb] - v[..., r | ba] - v[..., r | bb] + v[..., r])
    return np.mean(vals, axis=0)


def limites_obf_mc(K: int = 4, alpha: float = 0.05, nsim: int = 200000, seed: int = 77):
    """Limites bicaudais de um teste sequencial em K olhadas equidistantes com gasto de alfa de Lan–DeMets tipo O'Brien–Fleming
    α*(t) = 2 − 2Φ(z_{α/2}/√t), calculados por simulação Monte Carlo (semente fixa) do processo Z_k = S_k/√k sob H0."""
    Phi = lambda x: 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))
    z = 1.959963984540054 if abs(alpha - 0.05) < 1e-12 else 2.0
    gasto = [2.0 - 2.0 * Phi(z / math.sqrt((k + 1) / K)) for k in range(K)]
    rng = np.random.default_rng(seed)
    Z = np.cumsum(rng.standard_normal((nsim, K)), axis=1) / np.sqrt(np.arange(1, K + 1))
    viv = np.ones(nsim, bool)
    lim, antes = [], 0.0
    for k in range(K):
        inc = gasto[k] - antes
        antes = gasto[k]
        az = np.abs(Z[:, k])
        c = float(np.quantile(az[viv], 1.0 - inc * nsim / max(viv.sum(), 1)))
        lim.append(c)
        viv &= az < c
    return lim, gasto


def meta_dl(est, se):
    """Meta-análise de efeitos fixos e aleatórios (DerSimonian–Laird). Devolve dict com estimativas, τ², Q, I²."""
    est, se = np.asarray(est, float), np.asarray(se, float)
    w = 1.0 / se ** 2
    fe = float((w * est).sum() / w.sum())
    Q = float((w * (est - fe) ** 2).sum())
    k = len(est)
    c = float(w.sum() - (w ** 2).sum() / w.sum())
    tau2 = max(0.0, (Q - (k - 1)) / c) if c > 0 and k > 1 else 0.0
    wr = 1.0 / (se ** 2 + tau2)
    re = float((wr * est).sum() / wr.sum())
    se_re, se_fe = math.sqrt(1.0 / wr.sum()), math.sqrt(1.0 / w.sum())
    i2 = max(0.0, (Q - (k - 1)) / Q) if Q > 0 and k > 1 else 0.0
    return {"fe": fe, "se_fe": se_fe, "re": re, "se_re": se_re, "tau2": tau2, "Q": Q, "I2": i2, "k": k}


def bh(ps, q: float = 0.05):
    """Benjamini–Hochberg: devolve (p ajustados 'q-valores', rejeições) na ordem original."""
    ps = np.asarray(ps, float)
    m = len(ps)
    o = np.argsort(ps)
    adj = np.empty(m)
    mn = 1.0
    for r in range(m - 1, -1, -1):
        i = o[r]
        mn = min(mn, ps[i] * m / (r + 1))
        adj[i] = mn
    return adj, adj <= q


def bloco11(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 11 — [R5] Ablação leave-one-component-out (fatorial 2⁴) de uma tarefa de ponta a ponta + Shapley + alpha-spending")
    lake = ctx.lake
    dados, dev, g4 = dados_r5(), gabarito_dev_r5(), gabarito_r4()
    ok_p = hashlib.sha256(PREREG_R5_CORPO.encode("utf-8")).hexdigest() == PREREG_R5_CORPO_SHA256
    palavras, y, cats = vocab_e2e([g4["wn"], dev["wn"]])
    K = len(cats)
    m1 = ctx.res.get("_r5_m1")
    if m1 is None:
        esp = EspacoR5(dados, "C1")
        m1 = esp.modelo(4, 5, 0.0, 8)
    Xon = preparar_features(np.array([m1.vetor(w) for w in palavras]))
    Xoff = preparar_features(np.array([lake.vetor_hash(w) for w in palavras]))
    n_sem = 12 if ctx.args.rapido else 40
    rodadas, por_rodada, passos = 6, 3, 400
    rep.log(f"Pré-registro R5 (PARTE B) conferido: {'sim (sha256 do corpo confere)' if ok_p else '!! NÃO CONFERE'}. Tarefa: classificar {len(palavras)} palavras desconhecidas em {K} categorias semânticas "
            f"({', '.join(f'{c}={int((y == i).sum())}' for i, c in enumerate(cats))}; rótulos = categorias do WordNet pela ordem fixa do extrator, NÃO meu julgamento), com orçamento de {rodadas * por_rodada} consultas ao oráculo de rótulos "
            f"({rodadas} rodadas de {por_rodada}) a partir de 1 palavra rotulada por classe; teste fixo de 35% por semente (igual em todos os braços); acaso ≈ {100 / K:.1f}%.")
    rep.log("Componentes (cada um LIGADO/DESLIGADO; fatorial completo = 16 braços × " + f"{n_sem} sementes NOVAS {SEM0_ABLACAO}–{SEM0_ABLACAO + n_sem - 1}): " + " | ".join(
        f"{c}={NOME_COMP[c]}" for c in COMPONENTES))
    rep.log("  D: vetores M1 (PPMI+SVD, corpus C1) via PCA global ≤16 dims | OFF: vetores por HASH (R1), mesma dimensão.  L: modo 'delirio' (agenda+ruído de Lorenz) | OFF: Adam constante.  "
            "A: GAN condicional treinada nos exemplos rotulados → 4 sintéticos por classe | OFF: nenhum.  M: comitê de 5 cumeeiras bootstrap, consulta as 3 de maior informação mútua por rodada | OFF: consultas aleatórias.  "
            "Classificador final: MLP de 7 camadas de pesos (16→12×6→K), softmax, 400 passos, mesma semente de inicialização em todos os braços.")
    rep.sub("HIPÓTESES PRÉ-REGISTRADAS (PARTE B do PREREG_R5_CORPO; família B_D, B_L, B_A, B_M com Holm, bicaudais por permutação de sinais, α=0,05)")
    for l in PREREG_R5_CORPO.split("\n"):
        if l.startswith("Confirmatórias (família de 4") or l.startswith("Expectativa registrada antes de rodar: B_D"):
            rep.log("  " + l.strip())
    t0 = time.time()
    sems = [SEM0_ABLACAO + i for i in range(n_sem)]
    grupos = _fatiar(sems, GRUPO_E2E)
    out = mapa_paralelo(job_e2e_grupo, [(g, Xon, Xoff, y, K, rodadas, por_rodada, passos) for g in grupos], ctx.jobs)
    acc = np.concatenate([o[0] for o in out])
    diag = np.concatenate([o[1] for o in out])
    rep.log(f"(tempo do experimento: {time.time() - t0:.1f}s, jobs={ctx.jobs})", vol=True)
    nome_braco = lambda i: "".join(c if (i >> BITS[c]) & 1 else "-" for c in COMPONENTES)
    rep.sub("Acurácia no teste fixo por braço (média ± dp entre sementes; 'DLAM' = tudo ligado, '-' = desligado)")
    linhas = []
    for i in range(16):
        linhas.append(f"{nome_braco(i)} {100 * acc[:, i].mean():5.1f}±{100 * acc[:, i].std():.1f}")
    for r in range(0, 16, 4):
        rep.log("  " + "   |   ".join(linhas[r:r + 4]))
    ch = 100.0 / K
    rep.log(f"  acaso por classe uniforme ≈ {ch:.1f}%. Diagnóstico de SINAL (classificador linear de cumeeira, mesmas palavras rotuladas; D ligado/desligado × M ligado/desligado): "
            f"D+M={100 * diag[:, 0].mean():.1f}% | D, consulta aleatória={100 * diag[:, 1].mean():.1f}% | hash+M={100 * diag[:, 2].mean():.1f}% | hash, aleatória={100 * diag[:, 3].mean():.1f}%.")
    full = 15
    rep.sub("CONFIRMATÓRIAS — leave-one-component-out: acc(completo) − acc(sem o componente), pareado por semente (Holm sobre os 4)")
    comps = []
    for c in COMPONENTES:
        comps.append((c, comparar_pareado(acc[:, full], acc[:, full ^ (1 << BITS[c])], seed=ctx.seed)))
    padj = holm([cm["p"] for _, cm in comps])
    status = {}
    for (c, cm), pa_ in zip(comps, padj):
        rel = abs(cm["media"]) >= 0.01 and (cm["lo"] > 0 or cm["hi"] < 0)
        sig = pa_ < 0.05
        sentido = "ajuda" if cm["media"] > 0 else ("atrapalha" if cm["media"] < 0 else "neutro")
        status[c] = ("CONFIRMADO: componente " + sentido) if sig else "NÃO CONFIRMADO (efeito indistinguível de 0 após Holm)"
        rep.log(f"  B_{c} {NOME_COMP[c]:<42} Δ = {100 * cm['media']:+.2f} pp IC95%[{100 * cm['lo']:+.2f},{100 * cm['hi']:+.2f}] p={cm['p']:.4f} p Holm={pa_:.4f} "
                f"vitórias/derrotas={cm['vit']}/{cm['der']} → {status[c]}{' | efeito relevante (≥1 pp, IC exclui 0)' if rel else ''}")
    _dD = comps[0][1]["media"]
    rep.log(f"  EXPECTATIVA PRÉ-REGISTRADA × RESULTADO: previ B_D grande e confirmado (+15 a +40 pp); observado Δ_D={100 * _dD:+.2f} pp, p Holm={padj[0]:.3f} → "
            + ("ATENDIDA." if (padj[0] < 0.05 and _dD >= 0.15) else "NÃO ATENDIDA (previsão errada: o efeito de D, se existe, é bem menor e/ou não confirmado nesta tarefa)."))
    rep.sub("Exploratório: atribuição de Shapley exata (sobre o fatorial 2⁴; soma = completo − nada) e interações de 2ª ordem")
    phi = shapley_exato(acc)
    total = acc[:, full] - acc[:, 0]
    rng_b = np.random.default_rng(ctx.seed + 55)
    idx_b = rng_b.integers(0, len(acc), (4000, len(acc)))
    phim = phi.mean(0)
    rep.log(f"  completo − nada = {100 * total.mean():+.2f} pp IC95%[{100 * np.percentile(total[idx_b].mean(1), 2.5):+.2f},{100 * np.percentile(total[idx_b].mean(1), 97.5):+.2f}]; "
            f"Σφ = {100 * phim.sum():+.2f} pp (confere com a diferença acima: {abs(phim.sum() - total.mean()) < 1e-9})")
    shap = {}
    for ci, c in enumerate(COMPONENTES):
        bm = phi[:, ci][idx_b].mean(1)
        shap[c] = (float(phim[ci]), float(np.percentile(bm, 2.5)), float(np.percentile(bm, 97.5)))
        rep.log(f"  Shapley {c}: {100 * phim[ci]:+.2f} pp IC95%[{100 * shap[c][1]:+.2f},{100 * shap[c][2]:+.2f}] ({100 * phim[ci] / total.mean() if abs(total.mean()) > 1e-9 else float('nan'):+.0f}% do ganho completo−nada; IC por bootstrap de sementes, instável quando o total é ≈ 0)")
    inter = {}
    for a_, b_ in itertools.combinations(COMPONENTES, 2):
        iv = interacao_2a(acc, a_, b_)
        bm = iv[idx_b].mean(1)
        inter[a_ + b_] = (float(iv.mean()), float(np.percentile(bm, 2.5)), float(np.percentile(bm, 97.5)))
    rep.log("  interações de 2ª ordem (pp, IC95%): " + " | ".join(f"{k}: {100 * v[0]:+.2f} [{100 * v[1]:+.2f},{100 * v[2]:+.2f}]" for k, v in inter.items()))
    # sequencial
    rep.sub("Exploratório/diagnóstico: análise sequencial (alpha-spending tipo O'Brien–Fleming, 4 olhadas equidistantes, bicaudal α=0,05; limites por Monte Carlo)")
    lim, gasto = limites_obf_mc(4)
    looks = [max(2, int(round(n_sem * (k + 1) / 4))) for k in range(4)]
    rep.log(f"  limites |z| nas olhadas n={looks}: " + ", ".join(f"{c:.3f}" for c in lim) + f" (gasto acumulado de alfa: " + ", ".join(f"{g:.4f}" for g in gasto) + "; aproximação normal para z — com n pequeno a razão t é mais conservadora)")
    seq = {}
    for c, _ in comps:
        d = acc[:, full] - acc[:, full ^ (1 << BITS[c])]
        zs = [float(d[:n].mean() / (d[:n].std(ddof=1) / math.sqrt(n) + 1e-12)) for n in looks]
        parou = next((looks[k] for k in range(4) if abs(zs[k]) >= lim[k]), None)
        seq[c] = (zs, parou)
        rep.log(f"  {c}: z nas olhadas = " + ", ".join(f"{z:+.2f}" for z in zs) + f" → {'teria PARADO na olhada com n=' + str(parou) if parou else 'não cruzaria o limite em nenhuma olhada'}")
    rep.log("→ LEITURA HONESTA: (i) o 'completo' vs 'sem componente' mede a contribuição NESTA tarefa, com ESTE classificador pequeno (poucas dezenas de exemplos rotulados): "
            "conclusões sobre 'ASI' não decorrem daí; (ii) se o sinal do dicionário (diagnóstico linear) já é fraco, a contribuição de D fica limitada pelo teto da qualidade dos vetores (ver BLOCO 2d); "
            "(iii) A (GAN com 3–5 exemplos por classe) e M (comitê com pouquíssimos exemplos) operam num regime onde qualquer ganho é pequeno; (iv) Shapley reparte também as interações e não é causal; "
            "(v) o vocabulário usa palavras que também estão nos gabaritos de similaridade (ressalva: o config. de M1 foi escolhido no DEV, que contém 33% dessas palavras).")
    ctx.res["r5_abl"] = {"comps": {c: (cm["media"], cm["lo"], cm["hi"], cm["p"]) for c, cm in comps}, "holm": [float(x) for x in padj], "status": status, "n": n_sem,
                         "acc": acc.mean(0).tolist(), "shap": shap, "total": float(total.mean()), "chance": ch, "diag": diag.mean(0).tolist(), "seq": seq, "K": K, "nw": len(palavras), "inter": inter}


