_R6_CACHE: dict = {}


# ----------------------------------------------------------------------
# BLOCO 12 (a) — dados congelados e estatística da R6 (JZS, maxT, MDE, helpers de pré-registro)
# ----------------------------------------------------------------------

def _json_r6(chave: str, txt: str) -> dict:
    if chave not in _R6_CACHE:
        _R6_CACHE[chave] = json.loads(txt)
    return _R6_CACHE[chave]


def dados_e2e_r6() -> dict:
    return _json_r6("e2e", DADOS_E2E_R6_JSON)


def fresco_r6() -> dict:
    return _json_r6("fresco", FRESCO_R6_JSON)


def glosas_fresco_r6() -> dict:
    return _json_r6("glosas", GLOSAS_FRESCO_R6_JSON)["glosas"]


def sha_ok(txt: str, esperado: str) -> bool:
    return hashlib.sha256(txt.encode("utf-8")).hexdigest() == esperado


def bf10_jzs(d, r: float = 0.7071067811865476) -> float:
    """[R6] Fator de Bayes JZS (Rouder et al. 2009) para H1: μ≠0 contra H0: μ=0 numa amostra/diferença pareada (t de 1 amostra), prior de Cauchy r no tamanho de efeito.
    Integral sobre g~Inv-Gama(1/2, r²/2) por quadratura em log-g (4001 pontos). BF10 < 1/3 = evidência moderada a favor do nulo; > 3 a favor do efeito."""
    d = np.asarray(d, float)
    n = len(d)
    sd = float(d.std(ddof=1)) if n > 1 else 0.0
    if n < 2 or sd == 0.0:
        return float("nan")
    t = float(d.mean() / (sd / math.sqrt(n)))
    nu = n - 1
    lg = np.linspace(-14.0, 14.0, 4001)
    g = np.exp(lg)
    logver = -0.5 * np.log1p(n * g) - 0.5 * (nu + 1) * np.log1p(t * t / (nu * (1.0 + n * g)))
    prior = r / math.sqrt(2.0 * math.pi) * g ** -1.5 * np.exp(-r * r / (2.0 * g))
    integrando = np.exp(logver) * prior * g          # g·dlog g = dg
    num = float(np.sum(0.5 * (integrando[1:] + integrando[:-1]) * np.diff(lg)))
    den = float((1.0 + t * t / nu) ** (-0.5 * (nu + 1)))
    return num / den


def maxt_westfall_young(D, nperm: int = 10000, seed: int = 0):
    """[R6] p ajustados de Westfall–Young (maxT, passo único) para m contrastes pareados por semente: D[n_sementes, m]. Estatística |t| de 1 amostra;
    inversões de sinal CONJUNTAS por semente (preserva a correlação entre contrastes). Menos conservador que Holm quando os contrastes são correlacionados."""
    D = np.asarray(D, float)
    n, m = D.shape
    se = D.std(0, ddof=1) / math.sqrt(n)
    se = np.where(se > 0, se, 1e-12)
    tobs = np.abs(D.mean(0) / se)
    rng = np.random.default_rng(seed)
    cont = np.zeros(m)
    lote = 1000
    for _ in range(max(nperm // lote, 1)):
        sg = rng.choice([-1.0, 1.0], (lote, n, 1))
        Ds = sg * D[None]
        mu = Ds.mean(1)
        s = Ds.std(1, ddof=1) / math.sqrt(n)
        mx = np.abs(mu / np.where(s > 0, s, 1e-12)).max(1)
        cont += (mx[:, None] >= tobs[None, :] - 1e-12).sum(0)
    return (cont + 1.0) / (max(nperm // lote, 1) * lote + 1.0)


def mde80(d) -> float:
    """[R6] Efeito mínimo detectável (bicaudal α=0,05, poder 80%) para a média de diferenças pareadas, a partir do desvio observado: 2,8·dp/√n."""
    d = np.asarray(d, float)
    return float(2.8 * d.std(ddof=1) / math.sqrt(len(d))) if len(d) > 1 else float("nan")


# ---- tarefa E2E 'carta-palavra' (desenho CONGELADO no Adendo 1: EXT-D) ----
SEM0_E2E6, SEM_DEV_E2E6 = 1100, 5000          # confirmatório 1100–1139 (40); DEV 5000–5023 (24)
SEM0_TOY6, SEM_DEV_TOY6 = 1200, 5100          # toy: confirmatório 1200–1247 (48); DEV 5100–5123 (24)
GRUPO_E2E6 = 5
CFG_E2E6 = dict(rodadas=20, por_rodada=4, ini=12, cartas_pool=6, cartas_teste=3, passos=400, por_classe_gan=6, lam_glosa=0.75)
CONCRETO_E2E6 = ("animal", "corpo", "planta", "comida", "artefato", "estrutura", "agua", "pessoa")
BASELINES_E2E6 = ("T1 maioria", "T2 só-número", "T3 só-palavra", "T4 linear [v,r]", "T5 nada")


# ----------------------------------------------------------------------
# BLOCO 12 (b) — tarefa 'carta-palavra' e ablação fatorial
# ----------------------------------------------------------------------

def palavras_e2e6(split: str):
    """Palavras do split ('dev'|'aval') em ordem alfabética e o grupo binário g(w) (1 = concreto, 0 = abstrato)."""
    pal = dados_e2e_r6()["palavras"]
    ws = sorted(w for w, v in pal.items() if v["split"] == split)
    return ws, np.array([1 if pal[w]["cat"] in CONCRETO_E2E6 else 0 for w in ws])


def regra_y6(g, r):
    """y = g(w) XOR [r ≥ 8] (carta 'alta' inverte o grupo)."""
    return int(g) ^ (1 if r >= 8 else 0)


def feat_poly6(F):
    """[v, r, v·r] a partir de F = [v, r_escalado] (características do comitê da incerteza epistêmica)."""
    return np.c_[F, F[:, :-1] * F[:, -1:]]


def laco_cartas6(F, y, K: int, pool, ini, rodadas: int, por_rodada: int, usar_inc: bool, rng):
    rot, pool = list(ini), list(pool)
    P = feat_poly6(F)
    for _ in range(rodadas):
        if usar_inc:
            Ws = comite_ridge(P[rot], y[rot], K, 5, rng)
            u = incerteza_epistemica(Ws, P[pool])
            ordem = np.lexsort((np.arange(len(pool)), -np.round(u, 12)))[:por_rodada]
        else:
            ordem = rng.permutation(len(pool))[:por_rodada]
        for i in sorted(ordem, reverse=True):
            rot.append(pool.pop(int(i)))
    return rot


def mixup_cartas6(X, y, K: int, por_classe: int, rng):
    """Controle do componente A: mixup (Beta(0,4; 0,4)) entre pares de cartas rotuladas da MESMA classe."""
    Xs, ys = [], []
    for c in range(K):
        idx = np.flatnonzero(y == c)
        if len(idx) == 0:
            continue
        for _ in range(por_classe):
            a, b = rng.choice(idx, 2, replace=True)
            lam = rng.beta(0.4, 0.4)
            Xs.append(lam * X[a] + (1 - lam) * X[b])
            ys.append(c)
    return np.array(Xs), np.array(ys)


def montar_semente6(s: int, g, cfg):
    """Divide palavras (65% pool / 35% teste, estratificado por grupo) e monta as cartas; cartas do grupo minoritário escaladas por n_maior/n_menor (máx. 13)."""
    rng = np.random.default_rng(7000 + s)
    pool_w, test_w = [], []
    for gr in (0, 1):
        idx = np.flatnonzero(g == gr)
        idx = idx[rng.permutation(len(idx))]
        nt = int(round(0.35 * len(idx)))
        test_w += list(idx[:nt])
        pool_w += list(idx[nt:])

    def n_cartas(ws, base):
        cnt = np.bincount([int(g[w]) for w in ws], minlength=2).astype(float)
        mx = cnt.max()
        return {w: int(min(13, round(base * mx / cnt[int(g[w])]))) for w in ws}
    ncp, nct = n_cartas(pool_w, cfg["cartas_pool"]), n_cartas(test_w, cfg["cartas_teste"])
    pool_c, test_c = [], []
    for w in sorted(pool_w):
        for r in rng.permutation(13)[:ncp[w]] + 1:
            pool_c.append((int(w), int(r)))
    for w in sorted(test_w):
        for r in rng.permutation(13)[:nct[w]] + 1:
            test_c.append((int(w), int(r)))
    return pool_c, test_c, rng


def job_e2e6_grupo(args):
    """Um grupo de sementes: laços de consulta e GANs por semente; depois TODOS os braços (16 por semente + 1 de controle mixup, se extras) em UM lote.
    Devolve (acc[n, 17] com índice = D<<3|L<<2|A<<1|M e coluna 16 = controle mixup, triv[n, 4] = T1..T4)."""
    sems, Von, Voff, g, cfg, extras = args[:6]
    gate = len(args) > 6 and bool(args[6])   # só os braços 'completo' (15) e 'nada' (0): usado na porta de sanidade do DEV
    K = 2
    specs, meta, tests = [], [], []
    triv = np.zeros((len(sems), 4))
    for q, s in enumerate(sems):
        pool_c, test_c, rng = montar_semente6(s, g, cfg)
        yp = np.array([regra_y6(g[w], r) for w, r in pool_c])
        yt = np.array([regra_y6(g[w], r) for w, r in test_c])
        rp, rt = np.array([r for _, r in pool_c], float), np.array([r for _, r in test_c], float)
        wp, wt = [w for w, _ in pool_c], [w for w, _ in test_c]
        ini = []
        for c in range(K):
            cand = np.flatnonzero(yp == c)
            ini += [int(x) for x in rng.choice(cand, min(cfg["ini"] // K, len(cand)), replace=False)]
        ini_set = set(ini)
        pool_q = [i for i in range(len(pool_c)) if i not in ini_set]
        tests.append((wt, rt, yt))
        for D, V in ((1, Von), (0, Voff)):
            Fp = np.c_[V[wp], (rp - 7.0) / 3.74]
            Ft = np.c_[V[wt], (rt - 7.0) / 3.74]
            for M in (1, 0):
                if gate and D != M:
                    continue
                r2 = np.random.default_rng(9000 + s * 13 + (0 if M else 1) + 5 * D)
                rot = laco_cartas6(Fp, yp, K, pool_q, ini, cfg["rodadas"], cfg["por_rodada"], bool(M), r2)
                Xl, yl = Fp[rot], yp[rot]
                if D == 1 and M == 1:
                    maj = int(np.bincount(yl, minlength=K).argmax())
                    triv[q, 0] = float(np.mean(yt == maj))
                    W2 = comite_ridge((rp[rot] >= 8).astype(float)[:, None], yl, K, 1, np.random.default_rng(1))[0]
                    triv[q, 1] = float(np.mean(np.argmax(np.c_[(rt >= 8).astype(float)[:, None], np.ones(len(rt))] @ W2, 1) == yt))
                    W3 = comite_ridge(Xl[:, :-1], yl, K, 1, np.random.default_rng(1))[0]
                    triv[q, 2] = float(np.mean(np.argmax(np.c_[Ft[:, :-1], np.ones(len(Ft))] @ W3, 1) == yt))
                    W4 = comite_ridge(Xl, yl, K, 1, np.random.default_rng(1))[0]
                    triv[q, 3] = float(np.mean(np.argmax(np.c_[Ft, np.ones(len(Ft))] @ W4, 1) == yt))
                Xs, ys = gan_condicional(Xl, yl, K, 3000 + s * 17 + D * 2 + M, por_classe=cfg["por_classe_gan"]) if (not gate or D == 1) else (None, None)
                for L in (1, 0):
                    for Aa in (1, 0):
                        if gate and (L != D or Aa != D):
                            continue
                        Xt = np.r_[Xl, Xs] if Aa else Xl
                        yt_ = np.r_[yl, ys] if Aa else yl
                        specs.append(dict(X=Xt, y=yt_.astype(float), seed=100 + s, modo="delirio" if L else "baseline", nsaida=K))
                        meta.append((q, D, L, Aa, M, False))
                if extras and D == 1 and M == 1:
                    Xm, ym = mixup_cartas6(Xl, yl, K, cfg["por_classe_gan"], np.random.default_rng(4000 + s))
                    specs.append(dict(X=np.r_[Xl, Xm], y=np.r_[yl, ym].astype(float), seed=100 + s, modo="delirio", nsaida=K))
                    meta.append((q, D, 1, 1, M, True))
    out = treinar_lote(specs, passos=cfg["passos"])
    acc = np.zeros((len(sems), 17))
    for (q, D, L, Aa, M, mix), (params, _) in zip(meta, out):
        wt, rt, yt = tests[q]
        V = Von if D else Voff
        Ft = np.c_[V[wt], (rt - 7.0) / 3.74]
        acc[q, 16 if mix else (D << 3) | (L << 2) | (Aa << 1) | M] = float(np.mean(np.argmax(MLPleve(params).forward(Ft), 1) == yt))
    return acc, triv


def rodar_e2e6(sems, Von, Voff, g, jobs: int, extras: bool = False, gate: bool = False):
    grupos = _fatiar(list(sems), GRUPO_E2E6)
    out = mapa_paralelo(job_e2e6_grupo, [(gr, Von, Voff, g, CFG_E2E6, extras, gate) for gr in grupos], jobs)
    return np.concatenate([o[0] for o in out]), np.concatenate([o[1] for o in out])


def vetores_e2e6(ctx: Contexto, split: str):
    ws, g = palavras_e2e6(split)
    m2g = ctx.res["_r5_m2g"]
    Von = preparar_features(np.array([m2g.vetor(w) for w in ws]))
    Voff = preparar_features(np.array([ctx.lake.vetor_hash(w) for w in ws]))
    return ws, g, Von, Voff


def porta_sanidade6(acc, triv, seed: int = 0):
    """Porta de sanidade pré-registrada: S1 = completo − melhor baseline trivial ≥ +8 pp com IC95% inferior > 0; S2' = completo ≥ acaso + 8 pp (K=2 → 58%)."""
    full, nada = acc[:, 15], acc[:, 0]
    bl = {BASELINES_E2E6[0]: triv[:, 0], BASELINES_E2E6[1]: triv[:, 1], BASELINES_E2E6[2]: triv[:, 2], BASELINES_E2E6[3]: triv[:, 3], BASELINES_E2E6[4]: nada}
    melhor = max(bl, key=lambda k: bl[k].mean())
    dif = full - bl[melhor]
    lo, hi = boot_ic(dif, seed=seed)
    s1 = bool(dif.mean() >= 0.08 and lo > 0)
    s2 = bool(full.mean() >= 0.5 + 0.08)
    return {"full": float(full.mean()), "bl": {k: float(v.mean()) for k, v in bl.items()}, "melhor": melhor, "dif": float(dif.mean()), "lo": lo, "hi": hi, "S1": s1, "S2": s2, "n": len(full)}


