# BLOCO 2e — [R6] GABARITO FRESCO (amostra estratificada POR REGRA do WordNet) e avaliação ÚNICA dos modelos CONGELADOS M2 e M2g da R5
# ======================================================================

class ModeloGlosaExt(ModeloGlosa):
    """M2g congelado da R5 (idf das 261 glosas da R5) + glosas EXTRAS só para o vetor g das palavras frescas (df=0 para tokens ausentes). Não altera o espaço base M2."""

    def __init__(self, base, dados: dict, lam: float, extras: dict, embaralhar=None):
        super().__init__(base, dados, lam)
        toks = {w: conteudo_glosa(g) for w, g in dados["glosas"].items()}
        df: dict = {}
        for t in toks.values():
            for x in set(t):
                df[x] = df.get(x, 0) + 1
        N = len(toks)
        ex = dict(extras)
        if embaralhar is not None:
            ks = sorted(ex)
            perm = np.random.default_rng(embaralhar).permutation(len(ks))
            ex = {ks[i]: extras[ks[perm[i]]] for i in range(len(ks))}
        for w, gtxt in ex.items():
            v, s = np.zeros(base.dim), 0.0
            for x in conteudo_glosa(gtxt):
                if x in base.idx:
                    idf = math.log((N + 1) / (df.get(x, 0) + 1)) + 1.0
                    v += idf * base.vetor(x)
                    s += idf
            if s > 0:
                self.g[w] = normalizar(v)


M2_CONGELADO = (8, 8, 1, 1.0)    # (dim, janela, k, p) escolhidos no DEV da R5 para C2; λ da glosa do M2g = 0,75


def bloco2e(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 2e — [R6] Gabarito WordNet FRESCO (amostra estratificada por regra): avaliação ÚNICA dos modelos CONGELADOS M2 e M2g da R5")
    lake, dados, g4, dev = ctx.lake, dados_r5(), gabarito_r4(), gabarito_dev_r5()
    fr = fresco_r6()
    gl = glosas_fresco_r6()
    ok_f = sha_ok(FRESCO_R6_JSON, FRESCO_R6_SHA256)
    ok_g = sha_ok(GLOSAS_FRESCO_R6_JSON, GLOSAS_FRESCO_R6_SHA256)
    wn = fr["wn"]
    ex = set(g4["wn"]) | set(g4["excluidas"]) | set(dev["wn"]) | set(dev["excluidas"]) | {x for g in dados["relacoes"].values() for x in g} | set(dados["glosas"]) | {e for _, e in LEXICO_PARES}
    disj = not (set(wn) & ex)
    rep.log(f"Integridade (sha256): gabarito fresco {FRESCO_R6_SHA256[:12]}… {'(CONFERE)' if ok_f else '(!! NÃO CONFERE)'} | glosas frescas {GLOSAS_FRESCO_R6_SHA256[:12]}… {'(CONFERE)' if ok_g else '(!! NÃO CONFERE)'} | "
            f"DISJUNTO do gabarito R4 (+excluídas), léxico de 102, DEV R5, RELACOES R5 e glosas R5: {'sim' if disj else '!! NÃO'} ({len(wn)} palavras, {len(wn) * (len(wn) - 1) // 2} pares n–n).")
    rep.log(f"Regra (DIFERENTE da lista manual da R4/R5-DEV): amostra estratificada por lexname do WordNet (rodízio entre {len(fr['estratos'])} estratos, ordem por sha256) das {fr['n_candidatas']} palavras candidatas do vocabulário do corpus "
            f"(freq≥2, substantivo dominante, lema exato, SemCor≥2, profundidade≥4, sem plurais); estratos: " + ", ".join(f"{k.replace('noun.', '')}={v}" for k, v in fr["estratos"].items()) + ".")
    rep.sub("HIPÓTESES PRÉ-REGISTRADAS (PARTE 2 do PREREG_R6_CORPO; família Q1–Q5, Holm sobre p unicaudais bootstrap por palavras, α=0,05)")
    for l in PREREG_R6_CORPO.split("\n"):
        if l.startswith("Confirmatórias (família de 5") or l.startswith("Expectativa registrada antes de rodar: ρ(M2)"):
            rep.log("  " + l.strip())
    sel, m1, m2, m2g_r5 = ctx.res.get("r5_dev"), ctx.res.get("_r5_m1"), ctx.res.get("_r5_m2"), ctx.res.get("_r5_m2g")
    cong = tuple(sel["sel"]["C2"][1:]) == M2_CONGELADO and abs(sel["lam2g"][1] - 0.75) < 1e-12
    rep.log(f"Modelos CONGELADOS da R5 (conferência: configuração escolhida no DEV da R5 = dim {M2_CONGELADO[0]}, janela {M2_CONGELADO[1]}, k {M2_CONGELADO[2]}, p {M2_CONGELADO[3]}, λ_glosa=0,75 → {'CONFERE' if cong else '!! DIFERE'}); "
            "nenhum hiperparâmetro foi ajustado nas 80 palavras frescas; M2g usa as 80 glosas frescas SÓ para o vetor g das palavras frescas (idf da tabela das 261 glosas da R5; df=0 p/ tokens ausentes); M2 NÃO é retreinado.")
    if os.environ.get("R6_SO_DEV"):
        rep.log("(R6_SO_DEV definido: a avaliação no gabarito fresco foi PULADA — modo de desenvolvimento.)")
        return
    teste = os.environ.get("R6_TESTE_GOLD")
    if teste:   # só para depurar o código (usa o DEV R5 como gabarito); NUNCA usado nos resultados oficiais
        wn, gl = dev["wn"], {}
        rep.log("(R6_TESTE_GOLD definido: DEPURAÇÃO com o gabarito DEV da R5 — resultado NÃO oficial.)")
    t0 = time.time()
    pal, ij, ouro, ouro_c, ps = pares_de(wn)
    m2g = ModeloGlosaExt(m2, dados, 0.75, gl)
    m2g_emb = ModeloGlosaExt(m2, dados, 0.75, gl, embaralhar=6)
    rnd_vet = lambda w: normalizar(np.random.default_rng(zlib.crc32(("rnd6::" + w).encode())).standard_normal(16))
    mods = {"M0 (embedding R4)": lake.emb.vetor, "M1 (R5, congelado)": m1.vetor, "M2 (R5, congelado)": m2.vetor, "M2g (R5, M2+glosa)": m2g.vetor,
            "M2g glosas EMBARALHADAS (nulo)": m2g_emb.vetor, "hash (R1)": lake.vetor_hash, "vetores aleatórios (nulo)": rnd_vet}
    sims = {n: _sim_modelo_vetores(f, pal, ij) for n, f in mods.items()}
    nb = 1500 if ctx.args.rapido else 4000
    R = rho_boot_palavras_v(sims, ouro, ij, len(pal), n_boot=nb, seed=4242, jobs=ctx.jobs)
    rep.sub("ρ de Spearman contra Wu–Palmer (gabarito FRESCO, avaliado UMA vez) — IC95% por bootstrap de PALAVRAS")
    rep.log(f"{'modelo':<34}{'ρ [IC95%]':>24}{'ρ vs caminho':>16}")
    for n in R:
        rep.log(f"{n:<34}{R[n][0]:>+9.3f} [{R[n][1]:+.2f},{R[n][2]:+.2f}]{spearman(sims[n], ouro_c):>+16.3f}")
    nglos = sum(1 for w in pal if w in m2g.g)
    rep.log(f"  (palavras frescas com vetor de glosa em M2g: {nglos}/{len(pal)}; sem glosa, M2g ≡ M2 naquela palavra)")

    def dpar(a, b):
        d = R[a][3] - R[b][3]
        return (R[a][0] - R[b][0], float(np.percentile(d, 2.5)), float(np.percentile(d, 97.5)), p_boot_unicaudal(d))
    Q = {"Q1": ("ρ(M2) − ρ(M0) > 0", dpar("M2 (R5, congelado)", "M0 (embedding R4)")),
         "Q2": ("ρ(M2g) − ρ(M0) > 0", dpar("M2g (R5, M2+glosa)", "M0 (embedding R4)")),
         "Q3": ("ρ(M2g) − ρ(M2) > 0", dpar("M2g (R5, M2+glosa)", "M2 (R5, congelado)")),
         "Q4": ("ρ(M2) > 0", (R["M2 (R5, congelado)"][0], R["M2 (R5, congelado)"][1], R["M2 (R5, congelado)"][2], p_boot_unicaudal(R["M2 (R5, congelado)"][3]))),
         "Q5": ("ρ(M2g) > 0", (R["M2g (R5, M2+glosa)"][0], R["M2g (R5, M2+glosa)"][1], R["M2g (R5, M2+glosa)"][2], p_boot_unicaudal(R["M2g (R5, M2+glosa)"][3])))}
    padj = holm([Q[k][1][3] for k in Q])
    rep.sub("VEREDITO PRÉ-REGISTRADO Q1–Q5 (Holm)")
    status = {}
    for (k, (desc, (est, lo, hi, p))), pa_ in zip(Q.items(), padj):
        status[k] = "CONFIRMADA" if pa_ < 0.05 else "NÃO CONFIRMADA"
        rel = " | efeito relevante (Δρ≥0,10 e IC>0)" if (k in ("Q1", "Q2", "Q3") and est >= 0.10 and lo > 0) else ""
        rep.log(f"  {k}: {desc:<22} estimativa={est:+.3f} IC95%[{lo:+.3f},{hi:+.3f}] p unicaudal={p:.4f} p Holm={pa_:.4f} → {status[k]}{rel}")
    rep.log("  Critério (como pré-registrado): CONFIRMADA se p Holm < 0,05; o IC95% é descritivo. Nada foi reanalisado com outros recortes.")
    dsh = R["M2g (R5, M2+glosa)"][3] - R["M2g glosas EMBARALHADAS (nulo)"][3]
    rep.sub("Controles exploratórios (sem Holm)")
    rep.log(f"  glosas reais − glosas embaralhadas (M2g): Δρ = {R['M2g (R5, M2+glosa)'][0] - R['M2g glosas EMBARALHADAS (nulo)'][0]:+.3f} IC95%[{np.percentile(dsh, 2.5):+.3f},{np.percentile(dsh, 97.5):+.3f}]; "
            f"M2g sobre M2: {R['M2g (R5, M2+glosa)'][0] - R['M2 (R5, congelado)'][0]:+.3f}. Se o controle embaralhado chega perto do real, o conteúdo da glosa NÃO é a fonte do ganho.")
    r5_ref = ctx.res.get("r5_sim", {}).get("rho_en", {})
    if r5_ref:
        rep.log(f"  REPLICAÇÃO (descritiva): no gabarito R4 (R5) ρ_EN = M0 {r5_ref.get('M0', float('nan')):+.3f}, M2 {r5_ref.get('M2', float('nan')):+.3f}, M2g {r5_ref.get('M2g (pós-hoc: M2+glosa)', float('nan')):+.3f}; no gabarito FRESCO: "
                f"M0 {R['M0 (embedding R4)'][0]:+.3f}, M2 {R['M2 (R5, congelado)'][0]:+.3f}, M2g {R['M2g (R5, M2+glosa)'][0]:+.3f}.")
    rep.log("→ LEITURA HONESTA: ver Q1–Q5. Cautelas: (a) as 80 glosas frescas foram escritas por MIM conhecendo as categorias (risco de vazamento; o controle embaralhado mede quanto do ganho não é conteúdo); "
            "(b) a amostra fresca é dominada por substantivos gerais/abstratos do vocabulário (a regra não escolhe palavras 'bonitas'); (c) o corpus de treino é meu; (d) 80 palavras = IC largos; "
            "(e) 'fresco' = disjunto das listas da R4/R5, mas o autor viu a lista de palavras ao escrever as glosas e já conhecia os resultados da R4/R5.")
    ctx.res["r6_fresco"] = {"Q": {k: (v[0], v[1]) for k, v in Q.items()}, "padj": [float(x) for x in padj], "status": status, "rho": {n: R[n][0] for n in R}, "ic": {n: (R[n][1], R[n][2]) for n in R},
                            "n_pal": len(pal), "n_pares": len(ij), "nglos": nglos, "cong": cong}
    rep.log(f"(tempo da avaliação única: {time.time() - t0:.1f}s)", vol=True)



