# ----------------------------------------------------------------------
# [R8/perf] SEGUNDO PLANO: um pool 'fork' recebe, logo após o BLOCO 2, as tarefas pesadas dos blocos novos (e o autoteste), que rodam enquanto os blocos
# anteriores usam os núcleos ociosos. As tarefas são funções PURAS dos argumentos: o resultado (e o DIGEST) não depende de haver ou não segundo plano.
# ----------------------------------------------------------------------

class SegundoPlano:
    def __init__(self, n: int):
        import multiprocessing as mp
        self.pool = mp.get_context("fork").Pool(processes=max(1, n))
        self.fut: dict = {}

    def enviar(self, chave, fn, tarefas):
        self.fut[chave] = self.pool.map_async(fn, list(tarefas), chunksize=1)

    def tem(self, chave) -> bool:
        return chave in self.fut

    def obter(self, chave):
        return self.fut.pop(chave).get()

    def fechar(self):
        try:
            self.pool.terminate()
            self.pool.join()
        except Exception:  # noqa: BLE001
            pass


def mapa_ou_fundo(ctx, chave, fn, tarefas):
    """Resultado de uma lista de tarefas: do segundo plano, se foi enviada para lá; senão (ou se falhou) calculada na hora com mapa_paralelo (mesmo resultado)."""
    bg = getattr(ctx, "bg", None)
    if bg is not None and bg.tem(chave):
        try:
            return bg.obter(chave)
        except Exception:  # noqa: BLE001
            pass
    return mapa_paralelo(fn, tarefas, ctx.jobs)


def r8_tarefas(ctx):
    """Listas de tarefas dos blocos novos (mesma função para enviar ao segundo plano e para consumir)."""
    if "r8_tar" in ctx.res_cache:
        return ctx.res_cache["r8_tar"]
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R8_DEV") else 0
    n_dev, n_sem = (8, 16) if rapido else (16, 48)
    n_g = 8 if rapido else G_NSEM_GAN
    _nc, _nt, sem = espelho_sementes(rapido)
    lk = LakeLeve(ctx.lake)
    Z = ctx.lake.pca_semente(2)
    tar = {"orc": (c8_celula, [(p, d, n_dev, n_sem, desloc) for d in reversed(P7_D) for p in P7_PAIS]),
           "gan": (_job_gan_regra, [(Z, G_GAN_PASSOS, G_SEM_GAN + desloc + s, r, 0) for s in range(n_g) for r in G_REGRAS_GAN]),
           "esp": (_job_espelho, [(lk, s) for s in sem])}
    ctx.res_cache["r8_tar"] = tar
    return tar


def _job_autoteste(_x):
    return autoteste()

# ======================================================================
# BLOCO 14 — [R8] TEORIA DOS JOGOS DO GRADIENTE: motor Prolog (SLD) próprio, jogos quadráticos de n jogadores, controlador de regra de atualização, GAN por regra
# ======================================================================

# ----------------------------------------------------------------------
# BLOCO 14 (a) — motor Prolog SLD (unificação, retrocesso, negação por falha)
# ----------------------------------------------------------------------

class VarP:
    """Variável lógica do motor Prolog da R8."""
    __slots__ = ("nome",)

    def __init__(self, nome):
        self.nome = nome

    def __repr__(self):
        return "_" + self.nome


def _pl_walk(t, sub):
    while isinstance(t, VarP) and t in sub:
        t = sub[t]
    return t


def _pl_unif(a, b, sub):
    """Unificação (sem occurs-check, como o Prolog padrão). Termos: átomo=str, número, composto=tuple(functor, *args), variável=VarP."""
    a, b = _pl_walk(a, sub), _pl_walk(b, sub)
    if a is b:
        return sub
    if isinstance(a, VarP):
        s = dict(sub)
        s[a] = b
        return s
    if isinstance(b, VarP):
        s = dict(sub)
        s[b] = a
        return s
    if isinstance(a, tuple) and isinstance(b, tuple):
        if len(a) != len(b) or a[0] != b[0]:
            return None
        for x, y in zip(a[1:], b[1:]):
            sub = _pl_unif(x, y, sub)
            if sub is None:
                return None
        return sub
    return sub if (not isinstance(a, tuple) and not isinstance(b, tuple) and a == b) else None


def _pl_resolve(t, sub):
    t = _pl_walk(t, sub)
    if isinstance(t, tuple):
        return (t[0],) + tuple(_pl_resolve(x, sub) for x in t[1:])
    return t


def _pl_tokens(txt):
    import re
    return re.findall(r"\\\+|:-|[A-Za-z_][A-Za-z0-9_]*|\d+(?:\.\d+)?|[(),.]", txt)


class MotorProlog:
    """[R8] Motor de resolução SLD em Python puro (NÃO é SWI-Prolog): fatos, regras com corpo, unificação, retrocesso (geradores), negação por falha (\\+),
    meta-predicado assert/retract de fatos DINÂMICOS (usado pelo controlador para instalar as observações da janela) e limite de profundidade."""

    def __init__(self, programa: str = "", prof_max: int = 60):
        self.clausulas: list = []     # (cabeça, [metas], dinâmica?)
        self.prof_max = prof_max
        self._n = 0
        if programa:
            self.carregar(programa)

    def _parse_termo(self, tk, i, vs):
        t = tk[i]
        i += 1
        if t[0].isupper() or t[0] == "_":
            if t not in vs:
                vs[t] = VarP(t)
            return vs[t], i
        if t[0].isdigit():
            return float(t) if "." in t else int(t), i
        if i < len(tk) and tk[i] == "(":
            args, i = [], i + 1
            while True:
                a, i = self._parse_termo(tk, i, vs)
                args.append(a)
                if tk[i] == ",":
                    i += 1
                    continue
                if tk[i] == ")":
                    i += 1
                    break
                raise ValueError("esperava , ou )")
            return (t,) + tuple(args), i
        return t, i

    def _parse_meta(self, tk, i, vs):
        if tk[i] == "\\+":
            m, i = self._parse_meta(tk, i + 1, vs)
            return ("\\+", m), i
        return self._parse_termo(tk, i, vs)

    def carregar(self, texto: str, dinamica: bool = False):
        tk = _pl_tokens(texto)
        i = 0
        while i < len(tk):
            vs: dict = {}
            cab, i = self._parse_termo(tk, i, vs)
            corpo = []
            if i < len(tk) and tk[i] == ":-":
                i += 1
                while True:
                    m, i = self._parse_meta(tk, i, vs)
                    corpo.append(m)
                    if tk[i] == ",":
                        i += 1
                        continue
                    break
            if tk[i] != ".":
                raise ValueError("esperava '.' na cláusula")
            i += 1
            self.clausulas.append((cab, corpo, dinamica))

    def assertz(self, fato: str):
        self.carregar(fato if fato.rstrip().endswith(".") else fato + ".", dinamica=True)

    def retract_dinamicos(self):
        self.clausulas = [c for c in self.clausulas if not c[2]]

    def _renomear(self, t, m):
        if isinstance(t, VarP):
            if t not in m:
                self._n += 1
                m[t] = VarP(f"{t.nome}#{self._n}")
            return m[t]
        if isinstance(t, tuple):
            return (t[0],) + tuple(self._renomear(x, m) for x in t[1:])
        return t

    def _solve(self, metas, sub, prof):
        if not metas:
            yield sub
            return
        if prof > self.prof_max:
            return
        meta, resto = metas[0], metas[1:]
        meta = _pl_walk(meta, sub)
        if isinstance(meta, tuple) and meta[0] == "\\+":
            ok = next(self._solve([meta[1]], sub, prof + 1), None)
            if ok is None:
                yield from self._solve(resto, sub, prof + 1)
            return
        for cab, corpo, _d in list(self.clausulas):
            m: dict = {}
            c2, b2 = self._renomear(cab, m), [self._renomear(x, m) for x in corpo]
            s2 = _pl_unif(meta, c2, sub)
            if s2 is not None:
                yield from self._solve(b2 + list(resto), s2, prof + 1)

    def consulta(self, meta: str, max_sol: int = 1) -> list:
        """Devolve até max_sol soluções como dicts {variável: termo}."""
        tk = _pl_tokens(meta.rstrip(". "))
        vs: dict = {}
        g, _ = self._parse_meta(tk, 0, vs)
        out = []
        for s in self._solve([g], {}, 0):
            out.append({k: _pl_resolve(v, s) for k, v in vs.items()})
            if len(out) >= max_sol:
                break
        return out

    def prova(self, meta: str) -> bool:
        tk = _pl_tokens(meta.rstrip(". "))
        g, _ = self._parse_meta(tk, 0, {})
        return next(self._solve([g], {}, 0), None) is not None


PROLOG_REGRAS_R8 = """
usar(otimista) :- gira, \\+ decai.
usar(alternado) :- gira, decai.
usar(alternado) :- cresce, \\+ gira.
usar(manter) :- \\+ gira, \\+ cresce.
usar(alternado).
"""
PROLOG_REGRAS_H = """
usar(otimista) :- gira, \\+ decai.
usar(manter) :- gira, decai.
usar(alternado) :- cresce, \\+ gira.
usar(manter) :- \\+ gira, \\+ cresce.
usar(alternado).
"""
G_REGRAS = ("simultaneo", "alternado", "otimista")
G_ETA, G_T, G_L, G_SNAP, G_LIM_VOLTAS, G_LIM_CONS, G_CRESCE, G_DECAI = 0.3, 400, 16, 2, 0.6, 0.6, 1.15, 0.85
G_SEM_J, G_SEM_MIX, G_SEM_GAN = 3000, 3500, 3100
G_NSEM_J, G_NSEM_GAN = 48, 40
_MOTOR_R8: dict = {}


def fatos_janela(O):
    """Fatos observáveis de uma janela O (L×k) de instantâneos: gira / cresce / decai (+ números). Usa SÓ a janela (nunca o equilíbrio)."""
    O = np.nan_to_num(np.asarray(O, float), nan=0.0, posinf=1e30, neginf=-1e30)
    X = O - O.mean(0)
    L = len(X)
    if np.abs(X).max() < 1e-300:
        return {"gira": False, "cresce": False, "decai": True, "voltas": 0.0, "consist": 0.0, "rho": 0.0}
    esc = float(np.abs(X).max())
    Xn = X / esc
    _u, _s, Vt = np.linalg.svd(Xn, full_matrices=False)
    P = Xn @ Vt[:2].T
    if P.shape[1] < 2:
        P = np.c_[P, np.zeros(len(P))]
    th = np.arctan2(P[:, 1], P[:, 0])
    dl = (np.diff(th) + math.pi) % (2 * math.pi) - math.pi
    voltas = abs(float(dl.sum())) / (2 * math.pi)
    consist = abs(float(dl.sum())) / (float(np.abs(dl).sum()) + 1e-12)
    r = np.sqrt((X * X).sum(1))
    rho = float(r[-5:].mean() / (r[:5].mean() + 1e-12 * esc))
    return {"gira": voltas >= G_LIM_VOLTAS and consist >= G_LIM_CONS, "cresce": rho > G_CRESCE, "decai": rho < G_DECAI, "voltas": voltas, "consist": consist, "rho": rho}


def escolher_regra_prolog(fatos: dict, atual: str, variante: str = "R8") -> str:
    """Instala os fatos da janela como cláusulas dinâmicas e consulta usar(R) no motor Prolog (1ª solução, por prioridade). variante 'H' = programa exploratório com histerese (pós-hoc)."""
    mt = _MOTOR_R8.get(variante)
    if mt is None:
        mt = _MOTOR_R8[variante] = MotorProlog(PROLOG_REGRAS_H if variante == "H" else PROLOG_REGRAS_R8)
    mt.retract_dinamicos()
    for k in ("gira", "cresce", "decai"):
        if fatos[k]:
            mt.assertz(k)
    r = mt.consulta("usar(R)")[0]["R"]
    return atual if r == "manter" else r


# ---------------------------------------------------------------- jogos quadráticos de n jogadores
def _ortog(rng, d):
    Q, R = np.linalg.qr(rng.standard_normal((d, d)))
    return Q * np.sign(np.diag(R))


# ----------------------------------------------------------------------
# BLOCO 14 (b) — jogos quadráticos de n jogadores, regras de atualização e GAN por regra
# ----------------------------------------------------------------------

def jogo_instancias(fam: str, seeds):
    """Para cada semente: (M, Hinv, z0, blocos). M é N×N; Hinv são os inversos dos blocos diagonais (n jogadores × m=2)."""
    out = []
    for s in seeds:
        rng = np.random.default_rng([int(s), {"ZS2": 1, "COOP2": 2, "RPS3": 3}[fam], 88])
        if fam == "ZS2":
            mu, A = 0.03, rng.uniform(0.8, 1.5) * _ortog(rng, 2)
            M = np.block([[mu * np.eye(2), A], [-A.T, mu * np.eye(2)]])
            n = 2
        elif fam == "COOP2":
            U = _ortog(rng, 4)
            M = U @ np.diag(rng.uniform(0.3, 3.4, 4)) @ U.T
            M = 0.5 * (M + M.T)
            n = 2
        else:
            mu, A = 0.05, rng.uniform(0.5, 1.2) * _ortog(rng, 2)
            M = np.zeros((6, 6))
            for i in range(3):
                M[2 * i:2 * i + 2, 2 * i:2 * i + 2] = mu * np.eye(2)
                M[2 * i:2 * i + 2, 2 * ((i + 1) % 3):2 * ((i + 1) % 3) + 2] = A
                M[2 * i:2 * i + 2, 2 * ((i - 1) % 3):2 * ((i - 1) % 3) + 2] = -A.T
            n = 3
        z0 = rng.standard_normal(M.shape[0])
        z0 /= np.linalg.norm(z0)
        Hinv = np.array([np.linalg.inv(M[2 * i:2 * i + 2, 2 * i:2 * i + 2]) for i in range(n)])
        out.append((M, Hinv, z0, n))
    return out


def nash_gap(M, Hinv, Z):
    """Exploitability exata: Σ_i ½ g_iᵀ H_ii⁻¹ g_i, g = M z (para todas as linhas de Z, forma (S,N)). M (S,N,N), Hinv (S,n,2,2)."""
    G = np.einsum("sij,sj->si", M, Z)
    n = Hinv.shape[1]
    tot = np.zeros(len(Z))
    for i in range(n):
        g = G[:, 2 * i:2 * i + 2]
        tot += 0.5 * np.einsum("si,sij,sj->s", g, Hinv[:, i], g)
    return tot


def jogo_rodar(fam: str, seeds, regra: str, eta: float = G_ETA, T: int = G_T, aleat_sem: int = 0):
    """Roda `regra` ∈ {SIM, ALT, OPT, EG, CTRL, CTRL_H, ALEAT} em todas as sementes de uma família (vetorizado). Devolve dict de arrays por semente."""
    inst = jogo_instancias(fam, seeds)
    return _jogo_rodar_inst(inst, regra, eta, T, aleat_sem, seeds)


def _jogo_rodar_inst(inst, regra, eta, T, aleat_sem, seeds):
    S = len(inst)
    M = np.array([i[0] for i in inst])
    Hinv = np.array([i[1] for i in inst])
    Z = np.array([i[2] for i in inst])
    n = inst[0][3]
    E0 = nash_gap(M, Hinv, Z)
    cod = {"SIM": 0, "ALT": 1, "OPT": 2}
    rl = np.full(S, 1)                                   # CTRL/ALEAT começam em ALT
    if regra in cod:
        rl = np.full(S, cod[regra])
    rngs = [np.random.default_rng([int(s), 5, 8, aleat_sem]) for s in seeds]
    Gp = np.einsum("sij,sj->si", M, Z)
    snaps, n_gira, n_jan, uso = [], np.zeros(S), 0, np.zeros((S, 3))
    L, SN = G_L, G_SNAP
    for t in range(T):
        G = np.einsum("sij,sj->si", M, Z)
        if regra == "EG":
            Zh = Z - eta * G
            Z = Z - eta * np.einsum("sij,sj->si", M, Zh)
        else:
            Zs = Z - eta * G
            Zo = Z - 2 * eta * G + eta * Gp
            Za = Z.copy()
            for i in range(n):
                gi = np.einsum("sij,sj->si", M[:, 2 * i:2 * i + 2, :], Za)
                Za[:, 2 * i:2 * i + 2] -= eta * gi
            Z = np.where((rl == 0)[:, None], Zs, np.where((rl == 1)[:, None], Za, Zo))
        np.clip(Z, -1e60, 1e60, out=Z)
        Gp = G
        if (t + 1) % SN == 0:
            snaps.append(Z.copy())
            if len(snaps) == L:
                n_jan += 1
                uso[np.arange(S), rl] += 1
                for s in range(S):
                    if regra in ("CTRL", "CTRL_H"):
                        f = fatos_janela(np.array([x[s] for x in snaps]))
                        n_gira[s] += f["gira"]
                        rl[s] = {"simultaneo": 0, "alternado": 1, "otimista": 2}[escolher_regra_prolog(f, ("simultaneo", "alternado", "otimista")[rl[s]], "H" if regra == "CTRL_H" else "R8")]
                    elif regra != "EG":
                        n_gira[s] += fatos_janela(np.array([x[s] for x in snaps]))["gira"]       # descritivo: o fato 'gira' observado sob a regra fixa
                    elif regra == "ALEAT":
                        rl[s] = int(rngs[s].integers(0, 3))
                snaps = []
    ET = nash_gap(M, Hinv, Z)
    Y = np.clip(np.log10(np.maximum(ET, 1e-300) / np.maximum(E0, 1e-300)), -6.0, 3.0)
    return {"Y": Y, "ET": ET, "div": Y > 0, "gira": n_gira / max(n_jan, 1), "uso": uso / max(n_jan, 1)}


# ---------------------------------------------------------------- GAN real com regra de atualização
G_GAN_PASSOS, G_GAN_SNAP, G_GAN_L, G_GAN_EXPL = 600, 5, 16, 150
G_REGRAS_GAN = ("SIM", "ALT", "OPT", "CTRL", "ALEAT")


def _comb_opt(g, gp):
    return [2.0 * a - b for a, b in zip(g, gp)]


def gan_regra(Z, passos: int, seed: int, regra: str, lr: float = 1e-3, aleat_sem: int = 0):
    """[R8] GAN de numpy (mesma arquitetura/hiperparâmetros do BLOCO 5, SEM estabilização) com regra de atualização SIM/ALT/OPT/CTRL/ALEAT.
    Devolve (G, D, info). Os gradientes anteriores são sempre guardados (troca de regra a qualquer momento)."""
    rng = np.random.default_rng(seed)
    G = MLP([4, 16, 16, 2], rng)
    D = MLP([2, 16, 16, 1], rng)
    zt = np.random.default_rng(2).standard_normal((600, 4))
    rl = {"SIM": 0, "ALT": 1, "OPT": 2}.get(regra, 1)
    nomes = ("simultaneo", "alternado", "otimista")
    rg_aleat = np.random.default_rng([int(seed), 6, 8, aleat_sem])
    gDp = gGp = None
    snaps, n_jan, n_gira, uso = [], 0, 0, np.zeros(3)
    for t in range(passos):
        idx = rng.integers(0, len(Z), 64)
        real = Z[idx] + 0.1 * rng.standard_normal((64, 2))
        fake = G.forward(rng.standard_normal((64, 4)))
        X = np.vstack([real, fake])
        y = np.r_[np.ones(64), np.zeros(64)][:, None]
        lg = D.forward(X)
        gWd, gbd, _ = D.backward((sigmoide(lg) - y) / len(X))
        gD = (gWd, gbd)
        if rl == 1:                                   # ALT: D primeiro, G vê o D atualizado (forward novo, como na 'sync' do BLOCO 5)
            D.adam(gWd, gbd, lr, b1=0.5)
            fake2 = G.forward(rng.standard_normal((64, 4)))
            _, _, dfake = D.backward((sigmoide(D.forward(fake2)) - 1.0) / 64)
            gWg, gbg, _ = G.backward(dfake)
            G.adam(gWg, gbg, lr, b1=0.5)
        else:                                         # SIM / OPT: os dois gradientes no MESMO ponto (mesmo lote); OPT usa 2g_t − g_{t−1}
            _, _, dfake = D.backward((sigmoide(D.forward(fake)) - 1.0) / 64)
            gWg, gbg, _ = G.backward(dfake)
            if rl == 2 and gDp is not None:
                D.adam(_comb_opt(gWd, gDp[0]), _comb_opt(gbd, gDp[1]), lr, b1=0.5)
                G.adam(_comb_opt(gWg, gGp[0]), _comb_opt(gbg, gGp[1]), lr, b1=0.5)
            else:
                D.adam(gWd, gbd, lr, b1=0.5)
                G.adam(gWg, gbg, lr, b1=0.5)
        gDp, gGp = (gWd, gbd), (gWg, gbg)
        if (t + 1) % G_GAN_SNAP == 0:
            f = G.forward(zt)
            snaps.append(np.r_[f.mean(0), f.std(0)])
            if len(snaps) == G_GAN_L:
                n_jan += 1
                uso[rl] += 1
                fj = fatos_janela(np.array(snaps))
                n_gira += fj["gira"]
                if regra == "CTRL":
                    rl = nomes.index(escolher_regra_prolog(fj, nomes[rl]))
                elif regra == "ALEAT":
                    rl = int(rg_aleat.integers(0, 3))
                snaps = []
    return G, D, {"gira": n_gira / max(n_jan, 1), "uso": uso / max(n_jan, 1)}


def _job_gan_regra(args):
    Z, passos, sd, regra, aleat_sem = args
    real = Z + 0.1 * np.random.default_rng(1).standard_normal(Z.shape)
    zt = np.random.default_rng(2).standard_normal((600, 4))
    G, _D, info = gan_regra(Z, passos, sd, regra, aleat_sem=aleat_sem)
    f = G.forward(zt)
    dist = metricas_gan(real, f)
    # exploitability (proxy) do gerador final: um D NOVO treinado 150 passos contra G congelado
    r2 = np.random.default_rng(sd + 777)
    D2 = MLP([2, 16, 16, 1], r2)
    for _ in range(G_GAN_EXPL):
        idx = r2.integers(0, len(Z), 64)
        rl_ = Z[idx] + 0.1 * r2.standard_normal((64, 2))
        fk = G.forward(r2.standard_normal((64, 4)))
        Xb = np.vstack([rl_, fk])
        yb = np.r_[np.ones(64), np.zeros(64)][:, None]
        gW, gb, _ = D2.backward((sigmoide(D2.forward(Xb)) - yb) / len(Xb))
        D2.adam(gW, gb, 3e-3, b1=0.5)
    acc = 0.5 * (np.mean(D2.forward(real) > 0) + np.mean(D2.forward(f) < 0))
    return {"dist": float(dist), "expl": float(acc - 0.5), "gira": float(info["gira"]), "uso": info["uso"]}

# ======================================================================
# BLOCO 7e — [R8] ORÇAMENTO DE AJUSTE IGUAL: controladores × Langevin nas paisagens enganosas da R7
# ======================================================================

C8_NTUNE_G, C8_NTUNE_P = 48, 12
C8_SEM_DEV, C8_SEM_C = 6200, 2200
C8_META2 = {"Tg": 0.2, "Tp": 0.01, "Tu": 0.3, "Dmax": 40.0}
C8_METODOS = ("langevin12", "langevin48", "delirio48", "meta2_12", "meta_fixas48")


def c8_escores(metodo, pais, d, sorte, R, x0, ten, S):
    """Score médio no DEV de cada uma das configurações de `sorte` (vetor de comprimento C)."""
    C = len(sorte["lr"])
    sid = np.tile(np.arange(S), C)
    return p7_rodar(metodo, pais, d, {k: np.repeat(v, S) for k, v in sorte.items()}, sid, R, x0, ten)[0].reshape(C, S).mean(1)


def c8_celula(args):
    """Uma célula (paisagem × d): ajuste no DEV (48 sorteios; langevin12 = melhor dos 12 primeiros; meta2 com 2 hiperparâmetros) → avaliação única em n_sem sementes novas."""
    pais, d, n_dev, n_sem, desloc = args
    so48 = p7_sorteios(C8_NTUNE_G)
    so12 = {k: v[:C8_NTUNE_P] for k, v in so48.items()}
    sd = [C8_SEM_DEV + desloc + i for i in range(n_dev)]
    Rd, xd = p7_instancias(sd, d)
    td = p7_tensores(sd, d, P7_PASSOS)
    esc = {"langevin": c8_escores("langevin", pais, d, so48, Rd, xd, td, n_dev),
           "delirio": c8_escores("delirio", pais, d, so48, Rd, xd, td, n_dev),
           "meta_fixas": c8_escores("meta_fixas", pais, d, so48, Rd, xd, td, n_dev)}
    so_m2 = dict(so12)
    for k, v in C8_META2.items():
        so_m2[k] = np.full(C8_NTUNE_P, v)
    esc["meta2"] = c8_escores("meta_fixas", pais, d, so_m2, Rd, xd, td, n_dev)
    pick = lambda so, e, n=None: {k: float(v[int(np.argmax(e[:n] if n else e))]) for k, v in so.items()}
    cfg = {"langevin12": pick(so48, esc["langevin"], C8_NTUNE_P), "langevin48": pick(so48, esc["langevin"]), "delirio48": pick(so48, esc["delirio"]),
           "meta2_12": pick(so_m2, esc["meta2"]), "meta_fixas48": pick(so48, esc["meta_fixas"])}
    base = {"langevin12": "langevin", "langevin48": "langevin", "delirio48": "delirio", "meta2_12": "meta_fixas", "meta_fixas48": "meta_fixas"}
    sc = [C8_SEM_C + desloc + i for i in range(n_sem)]
    Rc, xc = p7_instancias(sc, d)
    tc = p7_tensores(sc, d, P7_PASSOS)
    S = {m: p7_avaliar(base[m], pais, d, cfg[m], n_sem, Rc, xc, tc)[0] for m in C8_METODOS}
    return {"pais": pais, "d": d, "cfg": cfg, "S": S, "dev": {"langevin12": float(np.max(esc["langevin"][:C8_NTUNE_P])), "langevin48": float(np.max(esc["langevin"])), "delirio48": float(np.max(esc["delirio"])),
                                                              "meta2_12": float(np.max(esc["meta2"])), "meta_fixas48": float(np.max(esc["meta_fixas"]))}}



G_FAMS = ("ZS2", "COOP2", "RPS3")
G_NOMES_F = {"ZS2": "F1 ZS2 (soma zero, rotacional)", "COOP2": "F2 COOP2 (cooperativo)", "RPS3": "F3 RPS3 (3 jogadores cíclico)", "MIX": "F4 MIX (tipo desconhecido)"}
G_REGRAS_TOY = ("SIM", "ALT", "OPT", "EG", "CTRL", "ALEAT", "CTRL_H")


def jogo_familia(fam: str, desloc: int, n: int, regra: str):
    """Resultado de uma regra numa família (F4 MIX: cada semente 3500+ sorteia o tipo de jogo)."""
    if fam != "MIX":
        return jogo_rodar(fam, [G_SEM_J + desloc + i for i in range(n)], regra)
    sd = [G_SEM_MIX + desloc + i for i in range(n)]
    tipo = np.array([int(np.random.default_rng([s, 9, 8]).integers(0, 3)) for s in sd])
    out = {k: (np.zeros(n) if k != "uso" else np.zeros((n, 3))) for k in ("Y", "ET", "gira", "uso")}
    out["div"] = np.zeros(n, bool)
    for j, f in enumerate(G_FAMS):
        ix = np.where(tipo == j)[0]
        if len(ix):
            r = jogo_rodar(f, [sd[i] for i in ix], regra)
            for k in ("Y", "ET", "gira", "uso", "div"):
                out[k][ix] = r[k]
    out["tipo"] = tipo
    return out


def _job_jogo_fam(args):
    fam, desloc, n, regra = args
    r = jogo_familia(fam, desloc, n, regra)
    return {k: v for k, v in r.items()}


def bloco14(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 14 — [R8] Teoria dos jogos do gradiente: jogos de n jogadores, simultâneo × alternado × otimista, controlador Prolog pelo CICLO observado, GAN real")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R8_DEV") else 0
    n_j = 16 if rapido else G_NSEM_J
    n_g = 8 if rapido else G_NSEM_GAN
    ok_p = sha_ok(PREREG_R8_CORPO, PREREG_R8_CORPO_SHA256)
    rep.log(f"Integridade: pré-registro R8 (corpo) {PREREG_R8_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r8.txt, carimbado 15:24 PT, ANTES de qualquer código de jogo/controlador/GAN-por-regra/ajuste-igual da R8)' if ok_p else '(!! NÃO CONFERE)'}.")
    ok_a = sha_ok(ADENDO1_R8_CORPO, ADENDO1_R8_CORPO_SHA256)
    rep.log(f"Adendo 1 ao pré-registro R8 (desvios, escrito ANTES das sementes confirmatórias): {ADENDO1_R8_CORPO_SHA256[:12]}… {'(CONFERE)' if ok_a else '(!! NÃO CONFERE)'}.")
    for l in ADENDO1_R8_CORPO.split("\n")[1:]:
        if l.startswith("D"):
            rep.log("  " + l.strip()[:230] + ("…" if len(l.strip()) > 230 else ""))
    if rapido:
        rep.log("(--rapido: 16 sementes por família de jogo e 8 sementes de GAN — NÃO é a análise pré-registrada de 48/40.)")
    rep.sub("Jogo de n jogadores (quadrático): z ← regra(z), campo de pseudo-gradiente F(z) = M·z; Nash em 0; EXPLOITABILITY exata E(z) = Σ_i ½ g_iᵀ H_ii⁻¹ g_i")
    rep.log("Regras: SIM = todos usam o mesmo z | ALT = Gauss–Seidel (cada jogador vê os blocos já atualizados) | OPT = otimista z⁺ = z − 2ηMz + ηMz_prev | EG = extragradiente (2 gradientes por passo; referência, fora da família confirmatória) | "
            "CTRL = controlador Prolog pelo ciclo observado | ALEAT = escolhe a regra ao acaso por janela (sem sinal) | CTRL_H = variante EXPLORATÓRIA com histerese (pós-hoc). η=0,3; 400 passos; desfecho Y = log₁₀[E(z_T)/E(z₀)] (truncado em [−6,+3]; menor é melhor).")
    rep.log("Programa Prolog do controlador (motor SLD próprio, fatos 'gira', 'cresce', 'decai' derivados da janela de 16 instantâneos — PCA 2D, ângulo acumulado e razão de raios — consultados por usar(R)):")
    for l in PROLOG_REGRAS_R8.strip().split("\n"):
        rep.log("    " + l.replace("\\\\+", "\\+"))
    ex = {"gira": True, "cresce": True, "decai": False}
    rep.log(f"    exemplo: fatos {{gira, cresce}} → ?- usar(R). → R = {escolher_regra_prolog(ex, 'alternado')} | fatos {{decai}} → R = {escolher_regra_prolog({'gira': False, 'cresce': False, 'decai': True}, 'otimista')} (manter a regra atual) | fatos {{cresce}} → R = {escolher_regra_prolog({'gira': False, 'cresce': True, 'decai': False}, 'otimista')}")
    fams = list(G_FAMS) + ["MIX"]
    tar = [(f, desloc, n_j, r) for f in fams for r in G_REGRAS_TOY]
    outs = mapa_paralelo(_job_jogo_fam, tar, ctx.jobs)
    R = {(t[0], t[3]): o for t, o in zip(tar, outs)}
    rep.sub(f"Resultados nos jogos ({n_j} sementes novas por família, {G_SEM_J + desloc}+ e MIX {G_SEM_MIX + desloc}+): Y médio ± erro-padrão | divergem (Y>0) | fração de janelas com o fato 'gira' | uso das regras pelo CTRL (SIM/ALT/OPT)")
    rep.log(f"{'família':<34}" + "".join(f"{r:>16}" for r in G_REGRAS_TOY))
    for f in fams:
        rep.log(f"{G_NOMES_F[f]:<34}" + "".join(f"{R[(f, r)]['Y'].mean():>+9.2f}±{R[(f, r)]['Y'].std(ddof=1) / math.sqrt(n_j):<5.2f}" for r in G_REGRAS_TOY))
        rep.log(f"{'   divergem | gira':<34}" + "".join(f"{int(R[(f, r)]['div'].sum()):>9}|{R[(f, r)]['gira'].mean():<5.2f}" for r in G_REGRAS_TOY) +
                "   CTRL usa: " + "/".join(f"{x:.2f}" for x in R[(f, 'CTRL')]['uso'].mean(0)))
    if "MIX" in fams:
        tp = R[("MIX", "SIM")]["tipo"]
        rep.log(f"(F4 MIX sorteou: {', '.join(f'{G_FAMS[j]}={int((tp == j).sum())}' for j in range(3))})")
    # ---- confirmatórias J1–J4
    rep.sub("CONFIRMATÓRIAS G1 (J1–J4 × 4 famílias = 16) + G2 (5, GAN) — Holm sobre 21; Δ = Y_regra_fixa − Y_CTRL (>0 favorece o CTRL); bicaudal por permutação de sinais (10000)")
    contr = {"J1": ("SIM", "vs SIM"), "J2": ("ALT", "vs ALT"), "J3": ("OPT", "vs OPT"), "J4": ("ALEAT", "vs ALEAT (sem sinal)")}
    PJ, i_ = {}, 0
    for f in fams:
        for k, (r, _d) in contr.items():
            i_ += 1
            cm = comparar_pareado(R[(f, r)]["Y"], R[(f, "CTRL")]["Y"], seed=ctx.seed + 8000 + i_)
            cm["mde"] = mde80(R[(f, r)]["Y"] - R[(f, "CTRL")]["Y"])
            PJ[(k, f)] = cm
    # ---- GAN real
    Z = ctx.lake.pca_semente(2)
    passos = G_GAN_PASSOS
    rep.sub(f"GAN real ({passos} passos, {n_g} sementes novas {G_SEM_GAN + desloc}+, sem estabilização): SIM × ALT × OPT × CTRL × ALEAT")
    t1 = time.time()
    fn_g, tg = r8_tarefas(ctx)["gan"]
    rg = mapa_ou_fundo(ctx, "gan", fn_g, tg)
    rep.log(f"(tempo da GAN por regra: {time.time() - t1:.1f}s, jobs={ctx.jobs})", vol=True)
    GR = {r: [rg[s * len(G_REGRAS_GAN) + k] for s in range(n_g)] for k, r in enumerate(G_REGRAS_GAN)}
    ms = lambda v: f"{np.mean(v):.3f}±{np.std(v, ddof=1) / math.sqrt(len(v)):.3f}"
    rep.log(f"{'regra':<8}{'dist→real (±EP)':>18}{'mediana':>9}{'pior':>8}{'expl. do D (±EP)':>19}{'janelas com gira':>18}{'uso SIM/ALT/OPT':>20}")
    for r in G_REGRAS_GAN:
        d_ = np.array([x["dist"] for x in GR[r]])
        rep.log(f"{r:<8}{ms(d_):>18}{np.median(d_):>9.3f}{d_.max():>8.3f}{ms([x['expl'] for x in GR[r]]):>19}{np.mean([x['gira'] for x in GR[r]]):>18.2f}{'/'.join(f'{x:.2f}' for x in np.mean([x['uso'] for x in GR[r]], 0)):>20}")
    dist = {r: np.array([x["dist"] for x in GR[r]]) for r in G_REGRAS_GAN}
    expl = {r: np.array([x["expl"] for x in GR[r]]) for r in G_REGRAS_GAN}
    contrG = {"G1": ("ALT", "CTRL", "CTRL vs ALT"), "G2": ("SIM", "CTRL", "CTRL vs SIM"), "G3": ("OPT", "CTRL", "CTRL vs OPT"), "G4": ("ALEAT", "CTRL", "CTRL vs ALEAT"), "G5": ("ALT", "OPT", "OPT vs ALT (a correção otimista ajuda?)")}
    PG = {}
    for i_, (k, (a_, b_, _d)) in enumerate(contrG.items(), 1):
        cm = comparar_pareado(dist[a_], dist[b_], seed=ctx.seed + 8100 + i_)
        cm["mde"] = mde80(dist[a_] - dist[b_])
        PG[(k, "GAN")] = cm
    todos = list(PJ) + list(PG)
    P_ALL = {**PJ, **PG}
    ph = dict(zip(todos, holm([P_ALL[k]["p"] for k in todos])))
    st = {k: _status7(P_ALL[k]["media"], ph[k]) for k in todos}
    rep.log(f"{'id':<12}{'contraste':<42}{'Δ':>9}{'IC95%':>20}{'p':>9}{'p Holm':>9}{'MDE':>8}  veredito")
    for k in todos:
        cm = P_ALL[k]
        if k[1] == "GAN":
            nm = contrG[k[0]][2] + " [dist→real]"
        else:
            nm = f"CTRL {contr[k[0]][1]} [{k[1]}]"
        rep.log(f"{k[0]}({k[1]:<5}) {nm:<42}{cm['media']:>+9.3f}{_ic7(cm):>20}{cm['p']:>9.4f}{ph[k]:>9.4f}{cm['mde']:>8.3f}  {st[k]}")
    # ---- descritivos / exploratórios
    rep.sub("Descritivo (sem confirmação): exploitability do discriminador (GAN) e referências dos jogos")
    for a_, b_ in (("ALT", "CTRL"), ("SIM", "CTRL"), ("OPT", "CTRL"), ("ALEAT", "CTRL"), ("ALT", "OPT")):
        cm = comparar_pareado(expl[a_], expl[b_], seed=ctx.seed + 8200)
        rep.log(f"  expl. do D: {a_:<6} − {b_:<5}: Δ={cm['media']:+.3f} IC95%[{cm['lo']:+.3f},{cm['hi']:+.3f}] p={cm['p']:.3f}  (>0: {b_} deixa o gerador MENOS explorável)")
    orac = {}
    for f in fams:
        fixos = {r: R[(f, r)]["Y"].mean() for r in ("SIM", "ALT", "OPT")}
        mel = min(fixos, key=fixos.get)
        orac[f] = (mel, fixos[mel], R[(f, "CTRL")]["Y"].mean(), R[(f, "EG")]["Y"].mean())
        rep.log(f"  {G_NOMES_F[f]:<34} melhor regra fixa EX-POST = {mel} (Y={fixos[mel]:+.2f}) | CTRL Y={orac[f][2]:+.2f} | EG (2 gradientes) Y={orac[f][3]:+.2f}")
    sx = {}
    for f in fams:
        cm = comparar_pareado(R[(f, "CTRL")]["Y"], R[(f, "CTRL_H")]["Y"], seed=ctx.seed + 8300)
        sx[f] = cm
    rep.log("  EXPLORATÓRIO (pós-hoc, CTRL_H com histerese vs CTRL pré-registrado; Δ = Y_CTRL − Y_CTRL_H, >0 favorece CTRL_H): " + "; ".join(f"{f}: {sx[f]['media']:+.3f} (p={sx[f]['p']:.3f})" for f in fams))
    # ---- leitura honesta
    nJ = {k: [f for f in fams if st[(k, f)] == "confirmada"] for k in contr}
    pJ = {k: [f for f in fams if st[(k, f)].startswith("refutada")] for k in contr}
    rep.sub("LEITURA HONESTA")
    rep.log("(1) Jogos: " + " | ".join(f"{k} {contr[k][1]}: CTRL melhor em {','.join(nJ[k]) or 'nenhuma'}; pior em {','.join(pJ[k]) or 'nenhuma'}" for k in contr) + ".")
    f4 = {k: st[(k, 'MIX')] for k in contr}
    rep.log(f"(2) Mistura F4 (tipo de jogo desconhecido): CTRL vs SIM = {f4['J1']}, vs ALT = {f4['J2']}, vs OPT = {f4['J3']}, vs ALEAT = {f4['J4']}. A mistura foi desenhada por mim com um nicho para cada regra fixa (SIM diverge em F1/F3, OPT diverge em F2): "
            "a vantagem do controlador sobre SIM e OPT em F4 vale POR CONSTRUÇÃO; o teste informativo é CTRL vs ALT (a regra fixa mais robusta) e vs a melhor regra fixa de cada família (descrito acima), não esses.")
    gj = [k for k in ("G1", "G2", "G3", "G4", "G5") if st[(k, "GAN")] != "nula"]
    rep.log(f"(3) GAN real: testes confirmados/refutados após Holm (21): {', '.join(f'{k}={st[(k, 'GAN')]}' for k in gj) if gj else 'nenhum — G1–G5 nulos'}. "
            f"Médias de dist→real: " + ", ".join(f"{r}={dist[r].mean():.3f}" for r in G_REGRAS_GAN) + f". Com {n_g} sementes o MDE80 de G1–G5 é {np.mean([PG[(k, 'GAN')]['mde'] for k in ('G1', 'G2', 'G3', 'G4', 'G5')]):.3f} (média): diferenças menores não são detectáveis. "
            f"Fração média de janelas com 'gira' na GAN: ALT={np.mean([x['gira'] for x in GR['ALT']]):.2f}, SIM={np.mean([x['gira'] for x in GR['SIM']]):.2f}, OPT={np.mean([x['gira'] for x in GR['OPT']]):.2f} — o detector de ciclo dispara com frequência na GAN mesmo quando não há ciclo limpo (ruído de minibatch), então a escolha de regra do CTRL é parcialmente ruído.")
    rep.log("Limites: (i) jogos quadráticos são os melhores casos para a teoria clássica (rotação pura é onde SIM diverge); a GAN real é não convexa e ruidosa; (ii) 'exploitability' da GAN é um proxy (D novo, 150 passos); (iii) os limiares do detector de ciclo e o programa Prolog foram fixados antes de rodar e não foram ajustados "
            "(o CTRL_H pós-hoc é só descritivo); (iv) o motor Prolog é próprio (não é SWI-Prolog); (v) CTRL gasta a 1ª janela em ALT; (vi) 40 sementes de GAN dão pouco poder; (vii) EG usa 2 gradientes por passo e está fora da família confirmatória.")
    rep.log(f"(tempo do bloco 14: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r8_game"] = {"n_j": n_j, "n_g": n_g, "P": {k: (P_ALL[k]["media"], P_ALL[k]["lo"], P_ALL[k]["hi"], P_ALL[k]["p"], float(ph[k]), P_ALL[k]["mde"]) for k in todos}, "st": st,
                          "Ymed": {f: {r: float(R[(f, r)]["Y"].mean()) for r in G_REGRAS_TOY} for f in fams}, "div": {f: {r: int(R[(f, r)]["div"].sum()) for r in G_REGRAS_TOY} for f in fams},
                          "gan": {r: (float(dist[r].mean()), float(expl[r].mean())) for r in G_REGRAS_GAN}, "orac": orac, "ctrlh": {f: (sx[f]["media"], sx[f]["p"]) for f in fams},
                          "gira_gan": {r: float(np.mean([x["gira"] for x in GR[r]])) for r in G_REGRAS_GAN}}


def bloco7e(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 7e — [R8] ORÇAMENTO DE AJUSTE IGUAL: controladores × Langevin nas paisagens enganosas (limite declarado da R7)")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R8_DEV") else 0
    n_dev, n_sem = (8, 16) if rapido else (16, 48)
    rep.log(f"Na R7 cada método recebeu N_TUNE = 12 configurações, mas o Langevin tem 2 hiperparâmetros e o controlador 7 (declarado, não corrigido). Aqui há DUAS equalizações: (E1) mesmo Nº DE HIPERPARÂMETROS — meta2_12 ajusta só lr e A (12 sorteios) com "
            f"Tg={C8_META2['Tg']}, Tp={C8_META2['Tp']}, Tu={C8_META2['Tu']}, Dmax={int(C8_META2['Dmax'])} fixados antes de ver dados; (E2) mesmo Nº TOTAL de avaliações de ajuste — langevin48, delirio48 e meta_fixas48 com 48 sorteios cada (a lista de 12 é prefixo da de 48). "
            f"DEV de {n_dev} sementes novas ({C8_SEM_DEV + desloc}+); confirmatório em {n_sem} sementes novas ({C8_SEM_C + desloc}+); unidade = score médio nas 4 dimensões; Holm sobre 12.")
    if rapido:
        rep.log("(--rapido: DEV 8 e confirmatório 16 sementes — NÃO é a análise pré-registrada.)")
    fn_o, tar_o = r8_tarefas(ctx)["orc"]
    cel = {(r["pais"], r["d"]): r for r in mapa_ou_fundo(ctx, "orc", fn_o, tar_o)}
    dims = list(P7_D)
    pool = {p: {m: np.mean([cel[(p, d)]["S"][m] for d in dims], axis=0) for m in C8_METODOS} for p in P7_PAIS}
    devm = {p: {m: float(np.mean([cel[(p, d)]["dev"][m] for d in dims])) for m in C8_METODOS} for p in P7_PAIS}
    rep.sub(f"SCORE médio confirmatório ({n_sem} sementes novas) por método, agrupado nas 4 dimensões | [melhor score no DEV do ajuste = otimismo da seleção]")
    rep.log(f"{'paisagem':<9}" + "".join(f"{m:>22}" for m in C8_METODOS))
    for p in P7_PAIS:
        rep.log(f"{p:<9}" + "".join(f"{pool[p][m].mean():>10.3f} [{devm[p][m]:.3f}]   " for m in C8_METODOS))
    contr = {"C1": ("meta2_12", "langevin12", "igual nº de hiperparâmetros (2)"), "C2": ("meta_fixas48", "langevin48", "igual nº total de avaliações de ajuste (48)"), "C3": ("delirio48", "langevin48", "agenda fixa vs Langevin, 48 sorteios"),
             "C4": ("langevin48", "langevin12", "o ajuste maior ajudou o Langevin?")}
    PC, i_ = {}, 0
    for p in P7_PAIS:
        for k, (a_, b_, _d) in contr.items():
            i_ += 1
            cm = comparar_pareado(pool[p][a_], pool[p][b_], seed=ctx.seed + 8500 + i_)
            cm["mde"] = mde80(pool[p][a_] - pool[p][b_])
            PC[(k, p)] = cm
    ch = list(PC)
    pa = dict(zip(ch, holm([PC[k]["p"] for k in ch])))
    stC = {k: _status7(PC[k]["media"], pa[k]) for k in ch}
    rep.sub("CONFIRMATÓRIAS C1–C4 por paisagem (Δ SCORE = primeiro − segundo; Holm sobre 12; bicaudal por permutação de sinais)")
    rep.log(f"{'id':<12}{'contraste':<56}{'Δscore':>9}{'IC95%':>20}{'p':>9}{'p Holm':>9}{'MDE':>8}  veredito")
    for k in ch:
        cm = PC[k]
        a_, b_, d_ = contr[k[0]]
        rep.log(f"{k[0]}({k[1]:<6}) {a_ + ' − ' + b_ + ' [' + d_ + ']':<56}{cm['media']:>+9.3f}{_ic7(cm):>20}{cm['p']:>9.4f}{pa[k]:>9.4f}{cm['mde']:>8.3f}  {stC[k]}")
    rep.sub("Por dimensão (descritivo): meta_fixas48 − langevin48 e meta2_12 − langevin12")
    for p in P7_PAIS:
        rep.log(f"  {p:<7} meta_fixas48 − langevin48 por d: " + ", ".join(f"d={d}: {cel[(p, d)]['S']['meta_fixas48'].mean() - cel[(p, d)]['S']['langevin48'].mean():+.3f}" for d in dims) +
                " | meta2_12 − langevin12 por d: " + ", ".join(f"d={d}: {cel[(p, d)]['S']['meta2_12'].mean() - cel[(p, d)]['S']['langevin12'].mean():+.3f}" for d in dims))
    ajuda = [p for p in P7_PAIS if any(stC[(k, p)] == "confirmada" for k in ("C1", "C2"))]
    pior = [p for p in P7_PAIS if any(stC[(k, p)].startswith("refutada") for k in ("C1", "C2"))]
    rep.sub("LEITURA HONESTA")
    rep.log("(1) Critério pré-registrado 'o controle metacognitivo ajuda com orçamento igual' (C1 ou C2 confirmada com sinal positivo em ≥ 1 paisagem): " + (f"ATENDIDO em {', '.join(ajuda)}." if ajuda else "NÃO atendido.") +
            (f" Controlador PIOR que o Langevin com orçamento igual (C1 ou C2 refutada) em: {', '.join(pior)}." if pior else " Nenhuma refutação (controlador pior) com orçamento igual."))
    rep.log("(2) Efeito do orçamento sobre o limite da R7: C4 mostra se mais sorteios ajudaram o Langevin; compare os scores DEV [entre colchetes] com os confirmatórios: a diferença é o otimismo da seleção (maior com 48 sorteios por haver mais candidatos). "
            "Mais sorteios dão mais chance ao controlador (7 dimensões de busca) do que ao Langevin (2): se C2 melhora em relação ao B5 da R7 (12 sorteios), parte do limite da R7 era de orçamento.")
    rep.log("Limites: (i) sorteio aleatório puro (não CMA-ES/halving); 'igual orçamento' = igual nº de avaliações, não igual dimensão de busca; (ii) as constantes do controlador em meta2_12 foram fixadas por mim (não ajustadas); (iii) sementes compartilhadas entre d; (iv) paisagens e o desfecho 'score' são escolhas minhas; (v) ACKLEY satura e FUNIL é armadilha: a informação está em RAST.")
    rep.log(f"(tempo do bloco 7e: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r8_orc"] = {"n": n_sem, "C": {k: (PC[k]["media"], PC[k]["lo"], PC[k]["hi"], PC[k]["p"], float(pa[k]), PC[k]["mde"]) for k in ch}, "stC": stC, "ajuda": ajuda, "pior": pior,
                         "pool": {p: {m: float(v.mean()) for m, v in pool[p].items()} for p in P7_PAIS}, "dev": devm}

# ======================================================================
# BLOCO 13 — [R8] COMPONENTES DE UMA IA E O SEU ESPELHO METACOGNITIVO (registro explícito: monitor · controle · crença calibrada)
# ======================================================================

M8_SEM_CAL, M8_SEM_TESTE, M8_N_CAL, M8_N_TESTE = 3300, 3324, 24, 40


# ----------------------------------------------------------------------
# BLOCO 13 (a) — visão leve do dicionário, calibração de Platt e experimentos por componente de IA
# ----------------------------------------------------------------------

class LakeLeve:
    """[R8/perf] Visão mínima e picklável do DicionarioLake usada pelos espelhos (pca_semente, entradas, palavras_semente): evita serializar o dicionário inteiro a cada tarefa."""

    def __init__(self, lake):
        self.entradas = dict(lake.entradas)
        self.palavras_semente = list(lake.palavras_semente)
        self._pca = {d: np.array(lake.pca_semente(d)) for d in (2, 3, 4, 6, 8, 12)}

    def pca_semente(self, dim: int):
        return self._pca[dim]


def espelho_sementes(rapido: bool):
    n_cal, n_te = (12, 16) if rapido else (M8_N_CAL, M8_N_TESTE)
    return n_cal, n_te, [M8_SEM_CAL + i for i in range(n_cal)] + [M8_SEM_TESTE + i for i in range(n_te)]


def platt_ajustar(s, y, l2: float = 1e-3, it: int = 60):
    """Calibração de Platt 1-D (regressão logística com intercepto NÃO penalizado, Newton): p = σ(a·z + b), z = (s − μ)/σ. Com intercepto livre,
    a média das previsões = taxa-base nos dados de ajuste (calibração 'em grande')."""
    s, y = np.asarray(s, float), np.asarray(y, float)
    mu, sd = float(s.mean()), float(s.std() + 1e-9)
    z = (s - mu) / sd
    a, b = 0.0, float(np.log((y.mean() + 1e-3) / (1 - y.mean() + 1e-3)))
    for _ in range(it):
        p = 1.0 / (1.0 + np.exp(-np.clip(a * z + b, -30, 30)))
        w = p * (1 - p) + 1e-9
        ga, gb = ((p - y) * z).sum() + l2 * a, (p - y).sum()
        haa, hab, hbb = (w * z * z).sum() + l2, (w * z).sum(), w.sum()
        det = haa * hbb - hab * hab
        da, db = (hbb * ga - hab * gb) / det, (-hab * ga + haa * gb) / det
        a, b = a - da, b - db
        if abs(da) + abs(db) < 1e-10:
            break
    return {"a": float(a), "b": float(b), "mu": mu, "sd": sd}


def platt_prever(par, s):
    z = (np.asarray(s, float) - par["mu"]) / par["sd"]
    return 1.0 / (1.0 + np.exp(-np.clip(par["a"] * z + par["b"], -30, 30)))


def auc_rank(s, y):
    s, y = np.asarray(s, float), np.asarray(y, float)
    n1, n0 = int((y > 0.5).sum()), int((y <= 0.5).sum())
    if n1 == 0 or n0 == 0:
        return float("nan")
    r = ranks_medios(s)
    return float((r[y > 0.5].sum() - n1 * (n1 + 1) / 2) / (n1 * n0))


def _tarefa8(lake, rng, n_tr: int, flip: float, n_te: int = 300, dim: int = 8):
    """Tarefa de classificação (professor oculto, como gerar_tarefa) com rótulos de TREINO ruidosos (taxa flip) e teste LIMPO."""
    Z = lake.pca_semente(dim)
    tot = n_tr + 100 + n_te
    X = Z[rng.integers(0, len(Z), tot)] + 0.35 * rng.standard_normal((tot, dim))
    w1 = np.random.default_rng(7).standard_normal(dim) / math.sqrt(dim)
    s = np.sin(2.0 * X @ w1) + 0.8 * X[:, 0] * X[:, 1] - 0.5 * X[:, 2] ** 2 + 0.3 * X[:, 3] * X[:, 4]
    y = (s > np.median(s)).astype(float)
    ytr = y[:n_tr].copy()
    fl = rng.random(n_tr) < flip
    ytr[fl] = 1 - ytr[fl]
    return (X[:n_tr], ytr), (X[n_tr:n_tr + 100], y[n_tr:n_tr + 100]), (X[n_tr + 100:], y[n_tr + 100:])


def m8_treinar(Xtr, ytr, Xva, yva, seed, h=12, passos=150, lr=0.02, loss="bce", wd=0.0, ckpt=10, snap=9):
    """Treino de um MLP pequeno com rastro para os monitores: perda por passo, (perda de treino, erro de validação) em checkpoints e instantâneos dos pesos."""
    rng = np.random.default_rng(seed)
    net = MLP([Xtr.shape[1], h, 1], rng)
    perdas, ck_l, ck_e, snaps = [], [], [], []
    n = len(Xtr)
    for t in range(passos):
        p = sigmoide(net.forward(Xtr).ravel())
        perdas.append(float(np.mean(-np.log(np.where(ytr > 0.5, p, 1 - p) + 1e-9))))
        dl = (p - ytr) / n if loss == "bce" else (p - ytr) * p * (1 - p) * 2.0 / n
        gW, gb, _ = net.backward(dl[:, None])
        net.adam(gW, gb, lr, wd=wd)
        if (t + 1) % ckpt == 0:
            pv = sigmoide(net.forward(Xva).ravel())
            ck_l.append(perdas[-1])
            ck_e.append(float(np.mean((pv > 0.5) != (yva > 0.5))))
        if (t + 1) % snap == 0:
            snaps.append(net.plano())
    return net, {"perdas": np.array(perdas), "ck_l": np.array(ck_l), "ck_e": np.array(ck_e), "snaps": np.array(snaps)}


def _acc(net, X, y):
    return float(np.mean((net.forward(X).ravel() > 0) == (y > 0.5)))


def _knn_ruido(X, y, k=5):
    D = ((X[:, None, :] - X[None, :, :]) ** 2).sum(-1)
    np.fill_diagonal(D, np.inf)
    nn = np.argsort(D, 1)[:, :k]
    maj = (y[nn].mean(1) > 0.5).astype(float)
    return maj, float(np.mean(maj != y))


# ---- 10 experimentos-espelho: cada um devolve (monitores:dict, saude:float, desfecho:float, ação:str|None, desfecho_após_controle:float|None)
def exp_dados(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 1])
    n_tr, flip = int(rng.integers(60, 301)), float(rng.uniform(0.02, 0.35))
    (Xtr, ytr), (Xva, yva), (Xte, yte) = _tarefa8(lake, rng, n_tr, flip)
    maj, ruido = _knn_ruido(Xtr, ytr)
    oov = int(rng.integers(0, 13))
    cob = float(1.0 - oov / 32.0)                                   # 32 consultas, `oov` palavras ausentes do dicionário (fração conhecida)
    net, _ = m8_treinar(Xtr, ytr, Xva, yva, seed)
    mon = {"ruido_knn": ruido, "n_treino": float(n_tr), "cobertura_lexical": cob, "classe_positiva": float(ytr.mean())}
    saude = float(np.clip(1.0 - 2.0 * ruido, 0, 1) * min(1.0, n_tr / 150.0))
    y0 = _acc(net, Xte, yte)
    ac, y1 = None, None
    if controlar and ruido > 0.18:                                  # controle: edição por vizinhos (remove pontos que discordam da maioria dos 5-NN) e reconsulta
        keep = maj == ytr
        if keep.sum() >= 20:
            ac = "limpar_rotulos_knn"
            net2, _ = m8_treinar(Xtr[keep], ytr[keep], Xva, yva, seed)
            y1 = _acc(net2, Xte, yte)
    return mon, saude, y0, ac, y1


def exp_representacao(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 2])
    kd = int(rng.choice([2, 3, 4, 6, 8, 12]))
    E = lake.pca_semente(min(kd, 16))
    classe = np.array([CLASSES.index(lake.entradas[p][1]) for p in lake.palavras_semente])
    idi = np.array([float(CLASSES.index(lake.entradas[p][1]) == 0) for p in lake.palavras_semente])   # alvo da sonda: 'é substantivo?' (palavras retidas)
    C = np.cov(E.T) if kd > 1 else np.array([[1.0]])
    ev = np.maximum(np.linalg.eigvalsh(C), 1e-12)
    pr = float(ev.sum() ** 2 / (ev ** 2).sum())
    En = E / (np.linalg.norm(E, axis=1, keepdims=True) + 1e-12)
    Sm = En @ En.T
    aniso = float((Sm.sum() - len(E)) / (len(E) * (len(E) - 1)))
    S2 = Sm.copy()
    np.fill_diagonal(S2, -9)
    coer = float(np.mean(classe[S2.argmax(1)] == classe))

    def sonda(Em):                                                    # desfecho: sonda linear (ridge) de 'substantivo?' em palavras RETIDAS (metade/metade, sorteio da semente); o monitor (1-NN de classe) usa todas as palavras
        perm = rng.permutation(len(Em))
        tr, te = perm[: len(Em) // 2], perm[len(Em) // 2:]
        A = np.c_[Em[tr], np.ones(len(tr))]
        w = np.linalg.solve(A.T @ A + 1.0 * np.eye(A.shape[1]), A.T @ (2 * idi[tr] - 1))
        return float(np.mean((np.c_[Em[te], np.ones(len(te))] @ w > 0) == (idi[te] > 0.5)))
    st = rng.bit_generator.state
    y0 = sonda(E)
    mon = {"rank_efetivo": pr, "rank_efetivo/dim": pr / kd, "anisotropia": aniso, "coerencia_classe_1nn": coer}
    ac, y1 = None, None
    if controlar and pr / kd < 0.9 and kd > 2:                        # controle: truncar à dimensão efetiva
        ac = "truncar_na_dim_efetiva"
        rng.bit_generator.state = st
        y1 = sonda(E[:, :max(2, int(round(pr)))])
    return mon, float(coer), y0, ac, y1


def exp_modelo(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 3])
    h = int(rng.choice([2, 4, 8, 16, 32]))
    (Xtr, ytr), (Xva, yva), (Xte, yte) = _tarefa8(lake, rng, int(rng.integers(80, 241)), 0.05)
    net, _ = m8_treinar(Xtr, ytr, Xva, yva, seed, h=h, passos=120)
    a_tr, a_va = _acc(net, Xtr, ytr), _acc(net, Xva, yva)
    gap = a_tr - a_va
    pv = sigmoide(net.forward(Xva).ravel())
    conf = float(np.mean(np.maximum(pv, 1 - pv)))
    mon = {"acc_treino": a_tr, "acc_validacao": a_va, "lacuna_treino_val": gap, "confianca_media": conf}
    saude = float(np.clip(a_va - 0.5 * max(gap, 0.0), 0, 1))
    y0 = _acc(net, Xte, yte)
    ac, y1 = None, None
    if controlar and (a_tr < 0.8 or gap > 0.08):
        ac = "dobrar_largura" if a_tr < 0.8 else "weight_decay"
        net2, _ = m8_treinar(Xtr, ytr, Xva, yva, seed, h=min(2 * h, 32) if a_tr < 0.8 else h, passos=120, wd=0.0 if a_tr < 0.8 else 5e-3)
        y1 = _acc(net2, Xte, yte)
    return mon, saude, y0, ac, y1


def exp_perda(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 4])
    perda = "bce" if rng.random() < 0.5 else "mse"
    (Xtr, ytr), (Xva, yva), (Xte, yte) = _tarefa8(lake, rng, 160, 0.08)
    net, h = m8_treinar(Xtr, ytr, Xva, yva, seed, passos=120, loss=perda, lr=0.02)
    rho = spearman(h["ck_l"], h["ck_e"]) if h["ck_l"].std() > 0 and h["ck_e"].std() > 0 else 0.0
    mon = {"corr_perda_vs_erro_val": float(rho), "queda_perda_relativa": float((h["perdas"][0] - h["perdas"][-1]) / (h["perdas"][0] + 1e-9)), "erro_val_final": float(h["ck_e"][-1])}
    y0 = _acc(net, Xte, yte)
    ac, y1 = None, None
    if controlar and perda != "bce" and rho < 0.6:                    # controle: a perda NÃO acompanha a métrica que importa → trocar para BCE
        ac = "trocar_para_bce"
        net2, _ = m8_treinar(Xtr, ytr, Xva, yva, seed, passos=120, loss="bce", lr=0.02)
        y1 = _acc(net2, Xte, yte)
    return mon, float((rho + 1) / 2), y0, ac, y1


def exp_otimizador(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 5])
    lr = float(np.exp(rng.uniform(math.log(2e-3), math.log(0.5))))
    (Xtr, ytr), (Xva, yva), (Xte, yte) = _tarefa8(lake, rng, 160, 0.05)
    net, h = m8_treinar(Xtr, ytr, Xva, yva, seed, passos=120, lr=lr)
    ps = h["perdas"]
    dl = np.diff(ps[-40:])
    osc = float(np.mean(np.sign(dl[1:]) != np.sign(dl[:-1])))
    plato = float(ps[-30] - ps[-1] < 0.002 * max(ps[-30], 1e-9) and ps[-1] > 0.45)
    fj = fatos_janela(h["snaps"][-16:])                                   # os MESMOS fatos (gira/cresce/decai) que o controlador Prolog do BLOCO 14 consome
    mon = {"oscilacao": osc, "platô": plato, "razao_atualizacao": float(np.linalg.norm(h["snaps"][-1] - h["snaps"][-2]) / (np.linalg.norm(h["snaps"][-1]) + 1e-9)),
           "gira(pesos)": float(fj["gira"]), "perda_final": float(ps[-1])}
    saude = float(np.clip(1.0 - osc, 0, 1) * (1.0 - 0.5 * plato))
    y0 = _acc(net, Xte, yte)
    ac, y1 = None, None
    if controlar and (osc > 0.4 or plato > 0):
        ac = "lr_x0.3" if osc > 0.4 else "lr_x3"
        net2, _ = m8_treinar(Xtr, ytr, Xva, yva, seed, passos=120, lr=lr * (0.3 if osc > 0.4 else 3.0))
        y1 = _acc(net2, Xte, yte)
    return mon, saude, y0, ac, y1


def _memoria_knn(X, y, cap, politica, rng):
    mem_x, mem_y = [], []
    for i in range(len(X)):
        if len(mem_x) < cap:
            mem_x.append(X[i]), mem_y.append(y[i])
        elif politica == "fifo":
            mem_x.pop(0), mem_y.pop(0), mem_x.append(X[i]), mem_y.append(y[i])
        else:                                                          # 'diverso': descarta o item mais redundante (maior similaridade ao vizinho mais próximo)
            M = np.array(mem_x + [X[i]])
            Dm = ((M[:, None] - M[None]) ** 2).sum(-1)
            np.fill_diagonal(Dm, np.inf)
            k = int(np.argmin(Dm.min(1)))
            if k < len(mem_x):
                mem_x[k], mem_y[k] = X[i], y[i]
    return np.array(mem_x), np.array(mem_y)


def exp_memoria(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 6])
    cap = int(rng.choice([8, 16, 32, 64]))
    (Xtr, ytr), _va, (Xte, yte) = _tarefa8(lake, rng, 240, 0.03)
    ordem = np.argsort(Xtr[:, 0] + 0.3 * rng.standard_normal(len(Xtr)))        # fluxo NÃO i.i.d.: chega ordenado (grosso modo) por uma coordenada → FIFO esquece regiões
    Xs, ys = Xtr[ordem], ytr[ordem]
    mx, my = _memoria_knn(Xs, ys, cap, "fifo", rng)

    def acc_mem(mx, my):
        D = ((Xte[:, None] - mx[None]) ** 2).sum(-1)
        return float(np.mean(my[np.argmin(D, 1)] == yte))
    Xn = mx / (np.linalg.norm(mx, axis=1, keepdims=True) + 1e-12)
    Sm = Xn @ Xn.T
    np.fill_diagonal(Sm, -9)
    red = float(np.mean(Sm.max(1)))
    Dq = ((Xs[::4][:, None] - mx[None]) ** 2).sum(-1).min(1)
    cob = float(np.mean(Dq < np.median(((Xs[::4][:, None] - Xs[::4][None]) ** 2).sum(-1)) * 0.25))
    mon = {"ocupacao": float(len(mx) / cap), "redundancia_cos": red, "cobertura_fluxo": cob, "capacidade": float(cap)}
    saude = float(np.clip(cob - 0.3 * max(red - 0.5, 0), 0, 1))
    y0 = acc_mem(mx, my)
    ac, y1 = None, None
    if controlar and (cob < 0.5 or red > 0.8):
        ac = "evicao_por_diversidade"
        mx2, my2 = _memoria_knn(Xs, ys, cap, "diverso", rng)
        y1 = acc_mem(mx2, my2)
    return mon, saude, y0, ac, y1


def _ece_amostral(p, y, bins=10):
    return ece_brier(p, y, bins)[0]


def exp_incerteza(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 7])
    Tsim = float(np.exp(rng.uniform(math.log(0.3), math.log(5.0))))   # desajuste de temperatura (sobre/sub-confiança) injetado
    (Xtr, ytr), (Xva, yva), (Xte, yte) = _tarefa8(lake, rng, 160, 0.08)
    net, _ = m8_treinar(Xtr, ytr, Xva, yva, seed, passos=120)
    lgv, lgt = net.forward(Xva).ravel() / Tsim, net.forward(Xte).ravel() / Tsim
    pv, pt = sigmoide(lgv), sigmoide(lgt)
    conf = float(np.mean(np.maximum(pv, 1 - pv)))
    acc = float(np.mean((pv > 0.5) == (yva > 0.5)))
    outs = [sigmoide((net_w(net, Xva, rng, 0.05)) / Tsim) for _ in range(6)]     # comitê por perturbação de pesos → incerteza epistêmica (informação mútua)
    pm = np.mean(outs, 0)
    hb = lambda p: -(p * np.log2(np.maximum(p, 1e-12)) + (1 - p) * np.log2(np.maximum(1 - p, 1e-12)))
    epi = float(np.mean(hb(pm) - np.mean([hb(o) for o in outs], 0)))
    ece_v = _ece_amostral(pv, (yva > 0.5).astype(float))
    mon = {"confianca_media": conf, "acc_validacao": acc, "super_confianca": conf - acc, "incerteza_epistemica_bits": epi, "ECE_validacao": ece_v}
    saude = float(np.clip(1.0 - 4.0 * abs(conf - acc), 0, 1))
    y0 = _ece_amostral(pt, (yte > 0.5).astype(float))                    # desfecho: ECE no TESTE (menor é melhor)
    ac, y1 = None, None
    if controlar and abs(conf - acc) > 0.05:                             # controle: escala de temperatura ajustada na validação
        ac = "escala_de_temperatura"
        Ts = np.exp(np.linspace(math.log(0.2), math.log(6.0), 40))
        T = Ts[int(np.argmin([_ece_amostral(sigmoide(lgv * Tsim / t), (yva > 0.5).astype(float)) for t in Ts]))]
        y1 = _ece_amostral(sigmoide(lgt * Tsim / T), (yte > 0.5).astype(float))
    return mon, saude, y0, ac, y1


def net_w(net, X, rng, s):
    n2 = net.clonar()
    n2.W = [w + s * rng.standard_normal(w.shape) for w in n2.W]
    return n2.forward(X).ravel()


def exp_politica(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 8])
    K, tau0 = 5, float(np.exp(rng.uniform(math.log(0.02), math.log(5.0))))
    mu = rng.standard_normal(K)

    def corre(tau):
        r2 = np.random.default_rng([seed, 8, 80])
        q, cnt, tot, Hs = np.zeros(K), np.zeros(K), 0.0, []
        for t in range(200):
            p = softmax(q, tau)
            a = int(r2.choice(K, p=p))
            r = mu[a] + r2.standard_normal()
            cnt[a] += 1
            q[a] += (r - q[a]) / cnt[a]
            tot += mu[a]
            Hs.append(entropia(p, 2.0) / math.log2(K))
        return tot / 200.0, float(np.mean(Hs[-50:])), float(np.mean(Hs[:50]))
    reg0, Hf, Hi = corre(tau0)
    mon = {"entropia_politica_final": Hf, "entropia_politica_inicial": Hi, "temperatura": tau0}
    saude = float(np.clip(1.0 - abs(Hf - 0.35) * 2.0, 0, 1))
    y0 = float(mu.max() - reg0)                                            # desfecho: arrependimento médio por passo (menor é melhor)
    ac, y1 = None, None
    if controlar and (Hf > 0.7 or Hf < 0.1):
        ac = "temperatura_x0.2" if Hf > 0.7 else "temperatura_x5"
        y1 = float(mu.max() - corre(tau0 * (0.2 if Hf > 0.7 else 5.0))[0])
    return mon, saude, y0, ac, y1


def exp_avaliacao(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 9])
    n = int(rng.integers(8, 61))
    delta = 0.0 if rng.random() < 0.5 else 0.5                              # efeito verdadeiro (em desvios-padrão): 0 ou 0,5
    sg = 1.0

    def veredito(m):
        d = delta + sg * np.random.default_rng([seed, 8, 90]).standard_normal(m)
        c = comparar_pareado(d, np.zeros(m), seed=seed)
        return float((c["p"] < 0.05) == (delta > 0)), c, float(mde80(d))
    ok0, c0, mde = veredito(n)
    mon = {"n_sementes": float(n), "MDE80/dp": mde / sg, "largura_IC": c0["hi"] - c0["lo"], "p": c0["p"]}
    saude = float(np.clip(1.0 - (mde / sg) / 1.0, 0, 1))
    ac, y1 = None, None
    if controlar and mde / sg > 0.5:                                        # controle: mais sementes até MDE ≤ 0,5 dp (n ≈ (2,8/0,5)²)
        ac = "adicionar_sementes"
        y1 = veredito(int(math.ceil((2.8 / 0.5) ** 2)))[0]
    return mon, saude, ok0, ac, y1


def exp_autoevolucao(lake, seed, controlar):
    rng = np.random.default_rng([seed, 8, 10])
    ksel = int(rng.choice([1, 2, 4, 8]))
    alvo = np.array([0.01, 0.8, 0.5])                                       # ótimo oculto (lr, T0, frac) do toy; fitness = −dist² + ruído N(0, 0,6²) por avaliação

    def fit_verd(g):
        v = np.array([math.log(g["lr"] / 0.01), g["T0"] - 0.8, g["frac"] - 0.5])
        return -float((v ** 2).sum())

    def evoluir(k):
        r2 = np.random.default_rng([seed, 8, 100])
        g = dict(GENOMA_PADRAO)
        ruido = lambda: 0.6 * r2.standard_normal(k).mean()
        f_g = fit_verd(g) + ruido()
        for _ in range(25):
            c = [mutar_genoma(g, r2) for _ in range(4)]
            fs = [fit_verd(x) + ruido() for x in c]
            i = int(np.argmax(fs))
            if fs[i] > f_g:
                g, f_g = c[i], fs[i]
        val = fit_verd(g) + 0.6 * r2.standard_normal(16).mean()
        return fit_verd(g), f_g - val, g
    verd, gap, g = evoluir(ksel)
    mon = {"lacuna_otimismo": gap, "k_selecao": float(ksel), "sigma_mut": float(g["sigma_mut"])}
    saude = float(np.clip(1.0 - max(gap, 0) / 1.0, 0, 1))
    ac, y1 = None, None
    if controlar and gap > 0.25:
        ac = "dobrar_avaliacoes_de_selecao"
        y1 = evoluir(min(2 * ksel, 16))[0]
    return mon, saude, verd, ac, y1


# ---- REGISTRO EXPLÍCITO DOS COMPONENTES (cada um: monitor, controle, crença calibrada)
