    {"id": "politica", "nome": "política / agente", "onde": "MiniPoker/REINFORCE, PoliticaCuriosidade, bandido_consultas", "monitor": "entropia da política (inicial/final), temperatura", "controle": "temperatura × 0,2 (entropia alta) / × 5 (colapso)", "desfecho": "arrependimento médio por passo ≤ 0,30", "limiar": 0.30, "sentido": -1, "exp": exp_politica},
    {"id": "avaliacao", "nome": "avaliação", "onde": "comparar_pareado, holm/bh, mde80, pré-registros", "monitor": "n de sementes, MDE80/dp, largura do IC", "controle": "adicionar sementes até MDE80 ≤ 0,5 dp", "desfecho": "veredito correto (significativo ⇔ efeito verdadeiro)", "limiar": 0.5, "sentido": +1, "exp": exp_avaliacao},
