def r9_dados(tarefa: str, seed: int, lk=None):
    """((Xtr, ytr), (Xte, yte)) de uma tarefa para uma semente (dados e inicialização: a mesma semente em todos os métodos). Ver PRÉ-REGISTRO R9 (T1–T4)."""
    rng = np.random.default_rng([seed, 9, 1])
    if tarefa == "espirais":
        n, nte = 80, 400

        def gen(m):
            t = rng.uniform(0.15, 1.0, m)
            ang = 5.0 * math.pi * t
            return np.c_[t * np.cos(ang), t * np.sin(ang)] + 0.03 * rng.standard_normal((m, 2))
        a, b = gen(n), gen(n)
        Xtr, ytr = np.r_[a, -b], np.r_[np.zeros(n), np.ones(n)]
        a, b = gen(nte), gen(nte)
        Xte, yte = np.r_[a, -b], np.r_[np.zeros(nte), np.ones(nte)]
        return (Xtr * 2, ytr), (Xte * 2, yte)
    if tarefa == "paridade":
        d, k, ntr = 10, 5, 400
        allb = ((np.arange(1024)[:, None] >> np.arange(d)) & 1) * 2.0 - 1.0
        p = rng.permutation(1024)
        y = (np.prod(allb[:, :k], axis=1) > 0).astype(float)
        return (allb[p[:ntr]], y[p[:ntr]]), (allb[p[ntr:]], y[p[ntr:]])
    if tarefa == "texto":
        Z = lk.pca_semente(8)
        # o dicionário semente só tem 3 classes gramaticais; os 4 tópicos são 4 agrupamentos (Lloyd, init. farthest-point, determinístico) dos vetores PCA-8
        cen = [Z[0]]
        for _ in range(3):
            cen.append(Z[np.argmax(np.min([((Z - c) ** 2).sum(1) for c in cen], axis=0))])
        cen = np.array(cen)
        for _ in range(25):
            lab = np.argmin(((Z[:, None, :] - cen[None]) ** 2).sum(2), axis=1)
            cen = np.array([Z[lab == j].mean(0) if np.any(lab == j) else cen[j] for j in range(4)])
        top = [np.where(lab == j)[0] for j in np.argsort([-np.sum(lab == j) for j in range(4)], kind="stable")]
        top = [t for t in top if len(t) >= 3]
        K = len(top)
        allw = np.arange(len(Z))

        def gen(m):
            pr = rng.integers(0, K, m)
            X = np.zeros((m, 8))
            for i in range(m):
                ws = [top[pr[i]][rng.integers(0, len(top[pr[i]]))] if rng.random() < 0.40 else allw[rng.integers(0, len(allw))] for _ in range(5)]
                X[i] = Z[ws].mean(0)
            return X * 1.5, (((pr & 1) ^ (pr >> 1)) == 1).astype(float)
        Xtr, ytr = gen(150)
        Xte, yte = gen(500)
        return (Xtr, ytr), (Xte, yte)
    if tarefa == "estreita":
        def gen(m):
            x = rng.uniform(-1, 1, (m, 2))
            r = np.sqrt((x ** 2).sum(1))
            return x * 1.5, (np.floor(r * 3.2) % 2 == 0).astype(float)
        Xtr, ytr = gen(240)
        Xte, yte = gen(600)
        return (Xtr, ytr), (Xte, yte)
    raise ValueError(tarefa)


def r9_sorteios(metodo: str, tarefa: str, n: int):
    """n configurações de hiperparâmetros sorteadas (semente = crc32 de método|tarefa) nas faixas de R9_ESPACO; a lista de n' < n sorteios é prefixo da de n."""
    rng = np.random.default_rng([zlib.crc32((metodo + "|" + tarefa).encode("utf-8")), 9, 3])
    out = []
    for _ in range(n):
        c = {}
        for nome, lo, hi, tipo in R9_ESPACO[metodo]:
            u = rng.random()
            if tipo == "log":
                c[nome] = float(math.exp(math.log(lo) + u * (math.log(hi) - math.log(lo))))
            elif tipo == "int":
                c[nome] = int(lo + int(u * (hi - lo + 1)))
            else:
                c[nome] = float(lo + u * (hi - lo))
        out.append(c)
    return out


R9_F32_TAREFAS = () if os.environ.get("R9_F64") else ("espirais", "paridade", "texto")      # [R11/perf] tarefas da R9 treinadas em float32 (R9_F64=1: nenhuma; a 'estreita' fica em float64 porque o float32 mudou o seu veredito D de nula para refutada)


def r9_fb(Wf, B, X, Y, keep=None, rng=None, perda=True):
    """Passo para frente e para trás em LOTE de K redes (pesos Wf[i]:(K,a,b), vieses B[i]:(K,1,b)); perda BCE média por rede; dropout inverso nas ocultas se keep (K,1,1) ≠ None.
    Devolve (gW, gb, perda (K,), logits (K,n,1))."""
    nl = len(Wf)
    n = X.shape[1]
    um = np.ones((1, 1, n), X.dtype)       # [R11/perf] bias do gradiente por produto matricial com a linha de uns
    hin, ativ, mask = [X], [], []
    h = X
    for i in range(nl):
        z = np.matmul(h, Wf[i]) + B[i]
        if i < nl - 1:
            a = np.tanh(z)
            ativ.append(a)
            h = a
            if keep is not None:
                mk = (rng.random(h.shape) < keep) / keep
                h = h * mk
                mask.append(mk)
            hin.append(h)
        else:
            lg = z
    p = 1.0 / (1.0 + np.exp(-np.clip(lg, -30, 30)))
    dz = (p - Y) / n
    gW, gb = [None] * nl, [None] * nl
    for i in reversed(range(nl)):
        gW[i] = np.matmul(hin[i].transpose(0, 2, 1), dz)
        gb[i] = np.matmul(um, dz) if um.dtype == np.float32 else dz.sum(1, keepdims=True)   # (float64 = soma original, resultado idêntico ao da R10)
        if i > 0:
            dh = np.matmul(dz, Wf[i].transpose(0, 2, 1))
            if keep is not None:
                dh = dh * mask[i - 1]
            dz = dh * (1.0 - ativ[i - 1] ** 2)
    loss = -(Y * np.log(p + 1e-12) + (1 - Y) * np.log(1 - p + 1e-12)).mean((1, 2)) if perda else None   # [R11/perf] o treinador não usa a perda
    return gW, gb, loss, lg


def r9_treinar_lote(metodo: str, tarefa: str, X, y, cfgs, seeds, passos: int, ruido_seed: int, f32=None):
    """Treina K redes em paralelo (matmul em lote) com o método dado. X:(K,n,d), y:(K,n); cfgs: K dicts de hiperparâmetros; seeds: K sementes (init, caos); ruido_seed: semente do RNG de ruído do LOTE.
    Cada rede é independente das outras, exceto pelo fluxo do RNG de ruído (que depende da composição do lote — fixa, independente de --jobs). Devolve (W, B) empilhados."""
    dt = np.float32 if (tarefa in R9_F32_TAREFAS if f32 is None else f32) else np.float64     # [R11/perf] float32 nas 3 tarefas rasas; R9_F64=1 e a tarefa 'estreita' (7 camadas) ficam em float64 (float32 mudou o veredito D dela)
    ocultas = R9_ARQ[tarefa]
    K, n, d = X.shape
    X = X.astype(dt)
    dims = [d] + list(ocultas) + [1]
    nl = len(dims) - 1
    W = [np.empty((K, a, b), dt) for a, b in zip(dims[:-1], dims[1:])]
    B = [np.zeros((K, 1, b), dt) for b in dims[1:]]
    for k, s in enumerate(seeds):
        r = np.random.default_rng([s, 9, 2])
        for i, (a, b) in enumerate(zip(dims[:-1], dims[1:])):
            W[i][k] = r.standard_normal((a, b)) * math.sqrt(1.0 / a)
    rng = np.random.default_rng([ruido_seed, 9, 4])
    gc = lambda nome, pad=0.0: np.array([c.get(nome, pad) for c in cfgs], float)
    lr, wd0 = gc("lr"), gc("wd", 1e-4)
    deli = metodo in ("delirio", "delirio_emb", "sem_saida", "so_agenda")
    frac = np.ones(K) if metodo == "sem_saida" else gc("frac", 0.5)
    T0 = np.zeros(K) if metodo == "so_agenda" else gc("T")
    usa_adam = metodo not in ("sgdm", "sgdr")
    b2, mom, sig, pdrop = gc("b2", 0.999), gc("mom", 0.9), gc("sig"), gc("p")
    ciclos = gc("ciclos", 4).astype(int)
    CAOS = None
    if metodo in ("delirio", "delirio_emb", "sem_saida"):
        lst = [fluxo_caos(passos, s + 17) for s in seeds]
        if metodo == "delirio_emb":
            lst = [c[np.random.default_rng(s + 99).permutation(len(c))] for c, s in zip(lst, seeds)]
        CAOS = np.stack(lst)
    P = W + B
    M = [np.zeros_like(p) for p in P]
    V = [np.zeros_like(p) for p in P]
    EMA = [p.copy() for p in P]
    Y = y[:, :, None].astype(dt)
    L = max(passos // R9_CICLOS_DEL, 1)
    Lc = np.maximum(passos // ciclos, 1)
    sh3 = lambda v: np.asarray(v, dt)[:, None, None]
    desvio = lambda w: w.reshape(K, -1).std(1) + 1e-3
    keep = sh3(1.0 - pdrop) if metodo == "dropout" else None
    with np.errstate(all="ignore"):
        for t in range(passos):
            env = 0.05 + 0.95 * 0.5 * (1.0 + math.cos(math.pi * t / passos))
            lr_t, wd = lr * env, wd0
            em_del, ci = None, 0
            if deli:
                ci, pos = divmod(t, L)
                em_del = pos < frac * L
                prog = np.clip((pos - frac * L) / np.maximum((1 - frac) * L, 1), 0, 1)
                lr_t = np.where(em_del, 3 * lr, lr * (1.0 - 0.7 * prog))
                wd = np.where(em_del, 1e-4, 1e-3)
            elif metodo == "sgdr":
                lr_t = lr * (0.05 + 0.95 * 0.5 * (1.0 + np.cos(np.pi * (t % Lc) / Lc)))
            Wf = W
            if metodo == "ruido_pesos":
                Wf = [w + sh3(sig * env) * sh3(desvio(w)) * rng.standard_normal(w.shape).astype(dt) for w in W]
            gW, gb, _, _ = r9_fb(Wf, B, X, Y, keep, rng, perda=False)
            gW = [g + sh3(wd) * w for g, w in zip(gW, W)]
            G = gW + gb
            nrm = np.sqrt(sum((g * g).reshape(K, -1).sum(1) for g in G))
            esc = sh3(np.minimum(1.0, 5.0 / (nrm + 1e-12)))
            if usa_adam:
                bc1, bc2 = 1 - 0.9 ** (t + 1), 1 - b2 ** (t + 1)
                for j, (pp, g) in enumerate(zip(P, G)):
                    g = g * esc
                    M[j] *= 0.9
                    M[j] += 0.1 * g
                    V[j] *= sh3(b2)
                    V[j] += sh3(1 - b2) * g * g
                    pp -= sh3(lr_t) * (M[j] / bc1) / (np.sqrt(V[j] / sh3(bc2)) + 1e-8)
            else:
                for j, (pp, g) in enumerate(zip(P, G)):
                    M[j] *= sh3(mom)
                    M[j] += g * esc
                    pp -= sh3(lr_t) * M[j]
            if metodo == "langevin":
                for w in W:
                    w += sh3(T0 * R9_GANHO * env) * sh3(desvio(w)) * rng.standard_normal(w.shape).astype(dt)
            elif deli:
                if CAOS is not None:
                    for li, w in enumerate(W):
                        amp = T0 * (0.7 ** ci) * R9_GANHO * np.abs(CAOS[:, t, li % 3]) * desvio(w) * em_del
                        w += sh3(amp) * rng.standard_normal(w.shape).astype(dt)
                ex = (~em_del) & (frac < 1.0)
                if ex.any():
                    for pp, E in zip(P, EMA):
                        pp += sh3(0.15 * ex) * (E - pp)
                for pp, E in zip(P, EMA):
                    E *= 0.9
                    E += 0.1 * pp
    return W, B


def r9_avaliar_lote(W, B, X, y):
    """Acurácia, perda BCE, ECE (10 faixas de confiança) e finitude de cada rede em (X:(K,m,d), y:(K,m)). Rede não finita conta como acurácia 0,5, ECE 0,5 e perda ln 2 (pior caso/acaso)."""
    nl = len(W)
    h = X
    with np.errstate(all="ignore"):
        for i in range(nl):
            z = np.matmul(h, W[i]) + B[i]
            h = np.tanh(z) if i < nl - 1 else z
        lg = h[:, :, 0]
        p = 1.0 / (1.0 + np.exp(-np.clip(lg, -30, 30)))
        ok = ((p > 0.5) == (y > 0.5)).astype(float)
        acc = ok.mean(1)
        loss = -(np.where(y > 0.5, np.log(p + 1e-9), np.log(1 - p + 1e-9))).mean(1)
        conf = np.where(p > 0.5, p, 1 - p)
        bins = np.minimum(np.nan_to_num((conf - 0.5) * 20, nan=0.0), 9.999).astype(int)
    ece = np.zeros(len(acc))
    for b in range(10):
        m = (bins == b)
        cnt = m.sum(1)
        ece += np.where(cnt > 0, np.abs((conf * m).sum(1) - (ok * m).sum(1)), 0.0) / y.shape[1]
    fin = np.isfinite(lg).all(1) & np.isfinite(loss)
    acc = np.where(fin, acc, 0.5)
    return {"acc": acc, "loss": np.where(fin, loss, math.log(2)), "ece": np.where(fin, ece, 0.5), "fin": fin}


def r9_dados_lote(tarefa: str, seeds, lk=None, embaralhar: bool = False):
    """Empilha (Xtr, ytr, Xte, yte) das sementes; embaralhar=True permuta os rótulos de TREINO (por semente, rng [semente, 9, 7]); o teste mantém os rótulos verdadeiros."""
    cache, A = {}, ([], [], [], [])
    for s in seeds:
        if s not in cache:
            (a, b), (c, d) = r9_dados(tarefa, s, lk)
            if embaralhar:
                b = b[np.random.default_rng([s, 9, 7]).permutation(len(b))]
            cache[s] = (a, b, c, d)
        for lst, v in zip(A, cache[s]):
            lst.append(v)
    return tuple(np.stack(x) for x in A)


def r9_rodar(metodo, tarefa, cfgs, seeds, lk, ruido_seed, embaralhar=False, passos=R9_PASSOS):
    Xtr, ytr, Xte, yte = r9_dados_lote(tarefa, seeds, lk, embaralhar)
    W, B = r9_treinar_lote(metodo, tarefa, Xtr, ytr, cfgs, seeds, passos, ruido_seed)
    return r9_avaliar_lote(W, B, Xte, yte)


def _r9_rs(metodo, tarefa, fase, desloc):
    return zlib.crc32(f"{metodo}|{tarefa}|{fase}".encode("utf-8")) + desloc


def _job_r9_celula(args):
    """Uma célula (método × tarefa): ajuste (n_sort sorteios × n_dev sementes DEV; vence a maior acurácia média de teste nas sementes DEV) → avaliação ÚNICA da config vencedora em n_c sementes novas."""
    metodo, tarefa, lk, n_sort, n_dev, n_c, desloc = args
    sorts = r9_sorteios(metodo, tarefa, n_sort)
    cfgs = [c for c in sorts for _ in range(n_dev)]
    seeds = [R9_SEM_DEV + desloc + j for _ in sorts for j in range(n_dev)]
    d = r9_rodar(metodo, tarefa, cfgs, seeds, lk, _r9_rs(metodo, tarefa, 1, desloc))
    sc = d["acc"].reshape(n_sort, n_dev).mean(1)
    best = int(np.argmax(sc))
    sc_c = [R9_SEM_C + desloc + j for j in range(n_c)]
    c = r9_rodar(metodo, tarefa, [sorts[best]] * n_c, sc_c, lk, _r9_rs(metodo, tarefa, 2, desloc))
    return {"metodo": metodo, "tarefa": tarefa, "cfg": sorts[best], "dev": sc, "dev_best": float(sc[best]), "dev_med": float(np.median(sc)), "dev_nfin": int((~d["fin"]).sum()),
            "acc": c["acc"], "loss": c["loss"], "ece": c["ece"], "nfin": int((~c["fin"]).sum())}


def _job_r9_laudo(args):
    """Medidas do laudo em n_f sementes FRESCAS (9300+): acurácia/ECE/perda de uma config, com rótulos de treino verdadeiros ou embaralhados."""
    metodo, tarefa, cfg, embaralhar, lk, n_f, desloc = args
    seeds = [R9_SEM_F + desloc + j for j in range(n_f)]
    d = r9_rodar(metodo, tarefa, [cfg] * n_f, seeds, lk, _r9_rs(metodo, tarefa, 3 + int(embaralhar), desloc), embaralhar)
    return {"acc": d["acc"], "ece": d["ece"], "loss": d["loss"], "nfin": int((~d["fin"]).sum())}


def r9_tarefas(ctx):
    """Lista das células do BLOCO 15 (40 = 4 tarefas × 10 métodos; as mais pesadas primeiro). Mesma função para enviar ao segundo plano e para consumir."""
    if "r9_tar" in ctx.res_cache:
        return ctx.res_cache["r9_tar"]
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R9_DEV") else 0
    n_sort, n_dev, n_c = (6, 2, 16) if rapido else (R9_NSORT, R9_NDEV, R9_NC)
    lk = LakeLeve(ctx.lake)
    ordem_t = ("estreita", "paridade", "texto", "espirais")
    tar = [(m, t, lk if t == "texto" else None, n_sort, n_dev, n_c, desloc) for t in ordem_t for m in R9_METODOS]
    ctx.res_cache["r9_tar"] = (_job_r9_celula, tar)
    return ctx.res_cache["r9_tar"]


# ----------------------------------------------------------------------
# LAUDO DE ESCRUTÍNIO (generalização da validade pedida pelo usuário): auditoria independente de um resultado evoluído pelo delírio
# ----------------------------------------------------------------------

def laudo_escrutinio(res, base, semsaida, shuf, ece_res, ece_base, seed: int = 0, chance: float = 0.5, m_chance: float = R9_MARGEM_CHANCE, m_ece: float = R9_MARGEM_ECE):
    """Laudo (PRÉ-REGISTRO R9, parte L). Entradas = vetores por SEMENTE FRESCA (pareados entre res/base/semsaida/ece_*; shuf = acurácia de teste do mesmo método treinado com rótulos permutados).
    V1 efeito: res − base com média > 0 e IC95% inferior > 0 | V2 rótulos embaralhados: IC95% superior da acurácia < chance + m_chance | V3 ablação da saída forçada: res − semsaida com IC95% inferior > 0 |
    V4 calibração: ECE(res) − ECE(base) com IC95% superior < m_ece. VALIDO ⇔ todos; INVALIDO + motivos caso contrário."""
    c1 = comparar_pareado(res, base, seed=seed)
    ok1 = c1["media"] > 0 and c1["lo"] > 0
    lo2, hi2 = boot_ic(np.asarray(shuf, float), seed=seed + 1)
    ok2 = hi2 < chance + m_chance
    c3 = comparar_pareado(res, semsaida, seed=seed + 2)
    ok3 = c3["media"] > 0 and c3["lo"] > 0
    c4 = comparar_pareado(ece_res, ece_base, seed=seed + 3)
    ok4 = c4["hi"] < m_ece
    crit = {"V1": (ok1, f"Δ acc vs baseline = {100 * c1['media']:+.2f} pp IC95%[{100 * c1['lo']:+.2f},{100 * c1['hi']:+.2f}] (exige IC inferior > 0)"),
            "V2": (ok2, f"acc com rótulos embaralhados = {100 * float(np.mean(shuf)):.2f}% IC95%[{100 * lo2:.2f},{100 * hi2:.2f}] (exige limite superior < {100 * (chance + m_chance):.0f}%)"),
            "V3": (ok3, f"Δ acc vs sem saída forçada = {100 * c3['media']:+.2f} pp IC95%[{100 * c3['lo']:+.2f},{100 * c3['hi']:+.2f}] (exige IC inferior > 0)"),
            "V4": (ok4, f"Δ ECE vs baseline = {c4['media']:+.4f} IC95%[{c4['lo']:+.4f},{c4['hi']:+.4f}] (exige limite superior < +{m_ece:.2f})")}
    motivos = [f"{k} FALHOU: {txt}" for k, (ok, txt) in crit.items() if not ok]
    return {"veredito": "VALIDO" if all(ok for ok, _ in crit.values()) else "INVALIDO", "crit": crit, "motivos": motivos, "c1": c1, "c3": c3, "c4": c4, "shuf": (float(np.mean(shuf)), lo2, hi2)}


def imprimir_laudo(rep, rot: str, L: dict):
    rep.log(f"  LAUDO [{rot}]: {L['veredito']}")
    for k, (ok, txt) in L["crit"].items():
        rep.log(f"     {k} {'ok   ' if ok else 'FALHA'} {txt}")
    if L["motivos"]:
        rep.log("     motivos: " + " | ".join(m.split(":")[0] for m in L["motivos"]))


# ----------------------------------------------------------------------
# BLOCO 15 — análise: tabelas, 36 confirmatórias (Holm), exploratórias, laudos
# ----------------------------------------------------------------------

def bloco15(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 15 — [R9] DELÍRIO COM SAÍDA FORÇADA EM REDES NEURAIS REAIS (MLPs numpy): 4 tarefas × 10 métodos, ajuste com orçamento IGUAL, ≥ 40 sementes novas, Holm sobre 36 + LAUDO DE ESCRUTÍNIO")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R9_DEV") else 0
    n_sort, n_dev, n_c = (6, 2, 16) if rapido else (R9_NSORT, R9_NDEV, R9_NC)
    n_f = 16 if rapido else R9_NF
    ok_p = sha_ok(PREREG_R9_CORPO, PREREG_R9_CORPO_SHA256)
    rep.log(f"Integridade: pré-registro R9 (corpo) {PREREG_R9_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r9.txt, carimbado 16:16 PT, ANTES do código integrado da R9 e de qualquer semente confirmatória/de laudo; o PILOTO de calibração de dificuldade nas sementes DEV é desvio declarado)' if ok_p else '(!! NÃO CONFERE)'}.")
    ok_a = sha_ok(ADENDO1_R9_CORPO, ADENDO1_R9_CORPO_SHA256)
    rep.log(f"Adendo 1 ao pré-registro R9 (desvios D1–…, escrito DEPOIS do código e ANTES das sementes confirmatórias): {ADENDO1_R9_CORPO_SHA256[:12]}… {'(CONFERE)' if ok_a else '(!! NÃO CONFERE)'}.")
    for l in ADENDO1_R9_CORPO.split("\n")[1:]:
        if l.startswith("D"):
            rep.log("  " + l.strip()[:250] + ("…" if len(l.strip()) > 250 else ""))
    if rapido:
        rep.log(f"(--rapido: {n_sort} sorteios × {n_dev} sementes DEV, {n_c} confirmatórias e {n_f} frescas — NÃO é a análise pré-registrada de {R9_NSORT}×{R9_NDEV}/{R9_NC}/{R9_NF}.)")
    rep.sub("Desenho (resumo do pré-registro): 4 tarefas, 10 métodos, 400 passos em lote completo, perda BCE, envelope de lr cosseno até 5%, corte de gradiente em 5; cada método × tarefa recebe "
            f"{n_sort} sorteios de hiperparâmetros × {n_dev} sementes DEV ({R9_SEM_DEV + desloc}+) → config vencedora → UMA avaliação em {n_c} sementes novas ({R9_SEM_C + desloc}+); mesmos dados e inicializações em todos os métodos (pareado)")
    rep.log("Baselines (3 hiperparâmetros ajustados cada): sgdm (lr, momento, wd) | adam (lr, wd, β₂) | sgdr (SGD+momento com reinícios cosseno: lr, wd, nº de ciclos) | langevin (Adam + ruído gaussiano iid anelado: lr, T, wd) | ruido_pesos (gradiente em pesos perturbados: lr, σ, wd) | dropout (lr, p, wd).")
    rep.log("Delírio (3 hiperparâmetros: lr, T, f): 4 ciclos; delírio = lr×3 + ruído por camada modulado por |Lorenz| (fração f do ciclo) → SAÍDA FORÇADA = lr decrescente + wd 10× + contração 0,15 para a média móvel. Controles com o MESMO orçamento: delirio_emb (caos embaralhado) | sem_saida (f=1: nunca sai) | so_agenda (sem ruído).")
    fn_c, tar_c = r9_tarefas(ctx)
    t1 = time.time()
    cel = mapa_ou_fundo(ctx, "r9a", fn_c, tar_c)
    rep.log(f"(tempo de espera pelas células: {time.time() - t1:.1f}s, jobs={ctx.jobs})", vol=True)
    R = {(c["metodo"], c["tarefa"]): c for c in cel}
    nfin = sum(c["nfin"] + c["dev_nfin"] for c in cel)
    rep.log(f"Redes com pesos/perdas não finitos (contadas como acaso, 50%): {nfin} de {len(cel) * (n_c + n_sort * n_dev)} treinos.")
    ms = lambda v: f"{100 * np.mean(v):5.1f}±{100 * np.std(v, ddof=1) / math.sqrt(len(v)):<4.1f}"
    rep.sub(f"ACURÁCIA DE TESTE (%) das {n_c} sementes confirmatórias, média ± erro-padrão [melhor score DEV entre colchetes = otimismo da seleção]")
    rep.log(f"{'método':<13}" + "".join(f"{t:>22}" for t in R9_TAREFAS) + f"{'rank médio':>12}")
    rank = {m: [] for m in R9_METODOS}
    for t in R9_TAREFAS:
        ordem = np.argsort([-R[(m, t)]["acc"].mean() for m in R9_METODOS], kind="stable")
        for r_, i in enumerate(ordem, 1):
            rank[R9_METODOS[i]].append(r_)
    for m in R9_METODOS:
        rep.log(f"{m:<13}" + "".join(f"{ms(R[(m, t)]['acc']):>13} [{100 * R[(m, t)]['dev_best']:4.1f}]  " for t in R9_TAREFAS) + f"{np.mean(rank[m]):>12.1f}")
    rep.sub("Configurações vencedoras no DEV (hiperparâmetros ajustados)")
    for t in R9_TAREFAS:
        rep.log(f"  {R9_NOME_T[t]}")
        for m in R9_METODOS:
            rep.log(f"    {m:<12} " + ", ".join(f"{k}={v:.4g}" if isinstance(v, float) else f"{k}={v}" for k, v in R[(m, t)]["cfg"].items()) +
                    f" | DEV: melhor {100 * R[(m, t)]['dev_best']:.1f}% mediana dos sorteios {100 * R[(m, t)]['dev_med']:.1f}%")
    # ---- confirmatórias A, B, C, D
    melhor_base = {t: max(R9_BASES, key=lambda m: (R[(m, t)]["dev_best"], -R9_BASES.index(m))) for t in R9_TAREFAS}
    PA, i_ = {}, 0
    for t in R9_TAREFAS:
        for m in R9_BASES:
            i_ += 1
            PA[(f"A_{m}", t)] = (R[("delirio", t)]["acc"], R[(m, t)]["acc"], i_)
        i_ += 1
        PA[("B", t)] = (R[("delirio", t)]["acc"], R[("sem_saida", t)]["acc"], i_)
        i_ += 1
        PA[("C", t)] = (R[("delirio", t)]["acc"], R[("delirio_emb", t)]["acc"], i_)
        i_ += 1
        PA[("D", t)] = (R[("delirio", t)]["acc"], R[(melhor_base[t], t)]["acc"], i_)
    P = {}
    for k, (a_, b_, ii) in PA.items():
        cm = comparar_pareado(a_, b_, seed=ctx.seed + 9000 + ii)
        cm["mde"] = mde80(a_ - b_)
        P[k] = cm
    chaves = list(P)
    ph = dict(zip(chaves, holm([P[k]["p"] for k in chaves])))
    st = {k: _status7(P[k]["media"], ph[k]) for k in chaves}
    rep.sub(f"CONFIRMATÓRIAS ({len(chaves)} = 24 A + 4 B + 4 C + 4 D; Holm sobre {len(chaves)}; Δ = acc(delirio) − acc(comparado) em pontos percentuais, >0 favorece o delírio; bicaudal por permutação de sinais, 10000)")
    rep.log(f"{'id':<22}{'comparação':<40}{'Δ (pp)':>9}{'IC95% (pp)':>20}{'p':>9}{'p Holm':>9}{'MDE (pp)':>10}{'v/d':>8}  veredito")
    nome_c = {"B": "sem_saida (a saída forçada ajuda?)", "C": "delirio_emb (o caos importa?)"}
    for k in chaves:
        cm = P[k]
        t = k[1]
        nm = nome_c.get(k[0]) or (f"melhor baseline por DEV = {melhor_base[t]}" if k[0] == "D" else k[0][2:])
        rep.log(f"{k[0] + '(' + t + ')':<22}{nm:<40}{100 * cm['media']:>+9.2f}{'[' + format(100 * cm['lo'], '+.2f') + ',' + format(100 * cm['hi'], '+.2f') + ']':>20}{cm['p']:>9.4f}{ph[k]:>9.4f}{100 * cm['mde']:>10.2f}{str(cm['vit']) + '/' + str(cm['der']):>8}  {st[k]}")
    # ---- exploratórias
    rep.sub("EXPLORATÓRIAS (fora do Holm; sem correção) e descritivos")
    E1 = {t: comparar_pareado(R[("delirio", t)]["acc"], R[("so_agenda", t)]["acc"], seed=ctx.seed + 9500) for t in R9_TAREFAS}
    rep.log("E1 delirio − so_agenda (o RUÍDO importa, ou só a agenda de reinícios+contração?): " + "; ".join(f"{t}: {100 * E1[t]['media']:+.2f} pp (p={E1[t]['p']:.3f})" for t in R9_TAREFAS))
    est = np.array([P[("D", t)]["media"] for t in R9_TAREFAS])
    se = np.array([P[("D", t)]["sd"] / math.sqrt(P[("D", t)]["n"]) for t in R9_TAREFAS])
    md = meta_dl(est, np.maximum(se, 1e-9))
    rep.log(f"E2 meta-análise (DerSimonian–Laird) do efeito D (delirio − melhor baseline por DEV) entre as 4 tarefas: efeito aleatório = {100 * md['re']:+.2f} pp IC95%[{100 * (md['re'] - 1.96 * md['se_re']):+.2f},{100 * (md['re'] + 1.96 * md['se_re']):+.2f}], "
            f"I²={100 * md['I2']:.0f}% (k=4: leia como descrição; as tarefas são desenhadas por mim)")
    for t in R9_TAREFAS:
        mb = melhor_base[t]
        el = comparar_pareado(R[("delirio", t)]["ece"], R[(mb, t)]["ece"], seed=ctx.seed + 9600)
        ll = comparar_pareado(R[("delirio", t)]["loss"], R[(mb, t)]["loss"], seed=ctx.seed + 9601)
        rep.log(f"E3 {t:<9} ECE do delirio − ECE de {mb} = {el['media']:+.4f} (p={el['p']:.3f}) | perda BCE de teste do delirio − de {mb} = {ll['media']:+.3f} (p={ll['p']:.3f}) [ECE/perda menores são melhores]")
    # ---- laudos
    rep.sub(f"LAUDO DE ESCRUTÍNIO do delírio ajustado em cada tarefa ({n_f} sementes FRESCAS {R9_SEM_F + desloc}+, nunca usadas; baseline = melhor por DEV; ablação = sem_saida ajustado; rótulos embaralhados)")
    lk = LakeLeve(ctx.lake)
    jl = []
    for t in R9_TAREFAS:
        lkt = lk if t == "texto" else None
        mb = melhor_base[t]
        jl += [("delirio", t, R[("delirio", t)]["cfg"], False, lkt, n_f, desloc), (mb, t, R[(mb, t)]["cfg"], False, lkt, n_f, desloc), ("sem_saida", t, R[("sem_saida", t)]["cfg"], False, lkt, n_f, desloc),
               ("delirio", t, R[("delirio", t)]["cfg"], True, lkt, n_f, desloc)]
    t2 = time.time()
    rl = mapa_paralelo(_job_r9_laudo, jl, ctx.jobs)
    rep.log(f"(tempo do laudo: {time.time() - t2:.1f}s)", vol=True)
    LD = {}
    for j, t in enumerate(R9_TAREFAS):
        a, b_, c, s_ = rl[4 * j:4 * j + 4]
        LD[t] = laudo_escrutinio(a["acc"], b_["acc"], c["acc"], s_["acc"], a["ece"], b_["ece"], seed=ctx.seed + 9700 + j)
        LD[t]["media"] = (float(a["acc"].mean()), float(b_["acc"].mean()), float(c["acc"].mean()))
        imprimir_laudo(rep, f"{t}: delirio × {melhor_base[t]}", LD[t])
        rep.log(f"     médias frescas: delirio={100 * a['acc'].mean():.1f}% | {melhor_base[t]}={100 * b_['acc'].mean():.1f}% | sem_saida={100 * c['acc'].mean():.1f}% | delirio c/ rótulos embaralhados={100 * s_['acc'].mean():.1f}%")
    n_val = [t for t in R9_TAREFAS if LD[t]["veredito"] == "VALIDO"]
    rep.log(f"→ Laudos VÁLIDOS: {len(n_val)} de {len(R9_TAREFAS)}" + (f" ({', '.join(n_val)})" if n_val else "") + ". Como são 4 decisões sem correção de multiplicidade, ≥ 1 'valido' espúrio não é controlado formalmente.")
    # ---- leitura honesta
    D_conf = [t for t in R9_TAREFAS if st[("D", t)] == "confirmada"]
    D_pior = [t for t in R9_TAREFAS if st[("D", t)].startswith("refutada")]
    A_conf = [(k, t) for (k, t) in chaves if k.startswith("A_") and st[(k, t)] == "confirmada"]
    A_pior = [(k, t) for (k, t) in chaves if k.startswith("A_") and st[(k, t)].startswith("refutada")]
    B_conf = [t for t in R9_TAREFAS if st[("B", t)] == "confirmada"]
    C_conf = [t for t in R9_TAREFAS if st[("C", t)] == "confirmada"]
    C_pior = [t for t in R9_TAREFAS if st[("C", t)].startswith("refutada")]
    suporte = [t for t in D_conf if LD[t]["veredito"] == "VALIDO"]
    rep.sub("LEITURA HONESTA")
    rep.log(f"(1) vs o MELHOR baseline por DEV (D): delírio melhor em {', '.join(D_conf) or 'nenhuma tarefa'}; PIOR em {', '.join(D_pior) or 'nenhuma'} (Holm sobre {len(chaves)}). Contra cada baseline (A, 24 testes): delírio melhor em {len(A_conf)} "
            f"({', '.join(f'{k[2:]}/{t}' for k, t in A_conf) or '—'}); pior em {len(A_pior)} ({', '.join(f'{k[2:]}/{t}' for k, t in A_pior) or '—'}).")
    rep.log(f"(2) Saída forçada (B): tirar a saída PIORA o delírio em {', '.join(B_conf) or 'nenhuma tarefa'} — lembrar que sem_saida remove JUNTAS lr decrescente, wd e contração (não separa qual importa; ver limites). Caos (C): delírio com caos estruturado MELHOR que com caos embaralhado em {', '.join(C_conf) or 'nenhuma tarefa'}; "
            f"PIOR em {', '.join(C_pior) or 'nenhuma'}.")
    rep.log("(3) CRITÉRIO PRÉ-REGISTRADO da tese 'o delírio com saída forçada ajuda redes reais': D confirmada com Δ > 0 em ≥ 1 tarefa E laudo VALIDO nessa tarefa → " + (f"ATENDIDO em {', '.join(suporte)} (leia com a ressalva de que são 4 tarefas minhas e redes minúsculas)." if suporte else
            ("NÃO ATENDIDO" + (f" (D confirmada em {', '.join(D_conf)}, mas o laudo as INVALIDOU: {'; '.join(t + ': ' + ','.join(m.split(' ')[0] for m in LD[t]['motivos']) for t in D_conf)})" if D_conf else " (nenhuma D confirmada com Δ > 0)") + ". A teoria central do usuário continua SEM suporte neste teste.")))
    rep.log("Limites: (i) redes minúsculas, lote completo, 400 passos, 4 tarefas escolhidas por mim; (ii) 12 sorteios × 3 sementes DEV é ajuste modesto (maldição do vencedor e faixas que podem excluir o melhor ponto de cada método); (iii) sem_saida remove todas as componentes da saída juntas; "
            "(iv) o envelope cosseno foi dado aos baselines (conservador contra o delírio); (v) dropout/ruído nos pesos gastam FLOPs extras não contados; (vi) as tarefas foram calibradas olhando sementes DEV (desvio declarado); (vii) 'valido' do laudo é uma regra de decisão com limiares meus, sem correção de multiplicidade; (viii) pré-registro auto-atestado.")
    rep.log(f"(tempo do bloco 15: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r9_nn"] = {"n_c": n_c, "n_f": n_f, "P": {k: (P[k]["media"], P[k]["lo"], P[k]["hi"], P[k]["p"], float(ph[k]), P[k]["mde"]) for k in chaves}, "st": st, "melhor_base": melhor_base,
                        "acc": {(m, t): float(R[(m, t)]["acc"].mean()) for m in R9_METODOS for t in R9_TAREFAS}, "rank": {m: float(np.mean(v)) for m, v in rank.items()},
                        "E1": {t: (E1[t]["media"], E1[t]["p"]) for t in R9_TAREFAS}, "E2": (md["re"], md["se_re"], md["I2"]), "laudo": {t: {k: LD[t][k] for k in ("veredito", "motivos", "media", "shuf")} for t in R9_TAREFAS},
                        "D_conf": D_conf, "suporte": suporte, "A_conf": A_conf, "B_conf": B_conf, "C_conf": C_conf}


# ----------------------------------------------------------------------
# LAUDO DA AUTOPOIESE (BLOCO 9) — mesmo laudo, aplicado aos genomas evoluídos
# ----------------------------------------------------------------------

def _job_r9_auto(args):
    """Treina em lote (treinar_lote do BLOCO 7) o genoma `g` no modo `modo` em n sementes de tarefa FRESCAS (gerar_tarefa), com ou sem rótulos de treino embaralhados; devolve acc/ECE de teste."""
    g, modo, embaralhar, lk, n, desloc = args
    specs, tks = [], []
    for j in range(n):
        s = R9_SEM_AUTO + desloc + j
        (Xtr, ytr), _, te = gerar_tarefa(lk, s)
        if embaralhar:
            ytr = ytr[np.random.default_rng([s, 9, 7]).permutation(len(ytr))]
        specs.append(dict(X=Xtr, y=ytr, seed=100 + s, modo=modo, largura=g["largura"], T0=g["T0"], lr=g["lr"], ciclos=g["ciclos"], frac=g["frac"]))
        tks.append(te)
    out = treinar_lote(specs, passos=R9_PASSOS_AUTO)
    acc, ece = [], []
    for (params, _), (Xte, yte) in zip(out, tks):
        m = MLPleve(params)
        acc.append(avaliar(m, Xte, yte, np.random.default_rng(0))[1])
        ece.append(calibracao(m, Xte, yte)[0])
    return {"acc": np.array(acc), "ece": np.array(ece)}


def r9_auto_tarefas(ctx):
    """Tarefas do laudo da autopoiese (depende dos genomas guardados pelo BLOCO 9). Cada genoma ≠ padrão: delírio normal, delírio com rótulos embaralhados, so_delirio (sem saída); + o padrão (delírio normal)."""
    ob = ctx.res.get("auto_obj")
    if not ob:
        return None
    desloc = 10000 if os.environ.get("R9_DEV") else 0
    n = 16 if ctx.args.rapido else R9_NF_AUTO
    lk = LakeLeve(ctx.lake)
    GP_ = ob["padrão"]
    chave = lambda g: json.dumps(g, sort_keys=True)
    tar, rot = [(GP_, "delirio", False, lk, n, desloc)], [("padrão", "delirio", False)]
    evol = [(nome, g) for nome, g in ob.items() if nome != "padrão" and chave(g) != chave(GP_)]
    for nome, g in evol:
        tar += [(g, "delirio", False, lk, n, desloc), (g, "delirio", True, lk, n, desloc), (g, "so_delirio", False, lk, n, desloc)]
        rot += [(nome, "delirio", False), (nome, "delirio", True), (nome, "so_delirio", False)]
    return tar, rot, [nome for nome, _ in evol]


def bloco16(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 16 — [R9] LAUDO DE ESCRUTÍNIO DA AUTOPOIESE: os genomas evoluídos do BLOCO 9 passam pela mesma auditoria independente (sementes frescas, rótulos embaralhados, ablação da saída forçada, calibração)")
    t0 = time.time()
    desloc = 10000 if os.environ.get("R9_DEV") else 0
    rep.log(f"Critérios idênticos aos do BLOCO 15 (pré-registro R9, parte L, aplicação 2): sementes de tarefa frescas {R9_SEM_AUTO + desloc}+ (gerar_tarefa), {R9_PASSOS_AUTO} passos; V1 = genoma evoluído − genoma padrão (IC95% inferior > 0); V2 = rótulos de treino embaralhados "
            f"(limite superior da acurácia < {100 * (0.5 + R9_MARGEM_CHANCE):.0f}%); V3 = evoluído − o mesmo genoma no modo so_delirio (sem saída forçada); V4 = ΔECE (limite superior < +{R9_MARGEM_ECE:.2f}).")
    pre = r9_auto_tarefas(ctx)
    if pre is None:
        rep.log("(BLOCO 9 não rodou nesta execução: nada a auditar.)")
        return
    tar, rot, evol = pre
    ob = ctx.res["auto_obj"]
    if not evol:
        rep.log("Todos os genomas evoluídos (ingênuo, CV/frescas, busca aleatória) são IGUAIS ao padrão: sem resultado evoluído a auditar (padrão mantido). O laudo ainda mede o padrão como referência.")
    rs = mapa_ou_fundo(ctx, "r9auto", _job_r9_auto, tar)
    base = rs[0]
    rep.log(f"genoma padrão (delírio, {len(base['acc'])} sementes frescas): acurácia de teste = {100 * base['acc'].mean():.2f}% | ECE = {base['ece'].mean():.4f}")
    LA = {}
    for i, nome in enumerate(evol):
        a, sh, ab = rs[1 + 3 * i:4 + 3 * i]
        g = ob[nome]
        rep.log(f"{nome}: lr={g['lr']:.4f} T0={g['T0']:.2f} ciclos={g['ciclos']} frac={g['frac']:.2f} largura={g['largura']} | acurácia fresca = {100 * a['acc'].mean():.2f}% (padrão {100 * base['acc'].mean():.2f}%; sem saída forçada {100 * ab['acc'].mean():.2f}%; rótulos embaralhados {100 * sh['acc'].mean():.2f}%)")
        LA[nome] = laudo_escrutinio(a["acc"], base["acc"], ab["acc"], sh["acc"], a["ece"], base["ece"], seed=ctx.seed + 9800 + i)
        imprimir_laudo(rep, f"autopoiese/{nome}", LA[nome])
    if evol:
        n_ok = sum(LA[n]["veredito"] == "VALIDO" for n in evol)
        rep.log(f"→ genomas evoluídos com laudo VALIDO: {n_ok} de {len(evol)}. Leitura: o laudo é mais exigente que a seleção do BLOCO 9 (que só pedia vencer o padrão em 5 sementes de seleção) — um genoma 'bom na seleção' que falha em V1/V3 é maldição do vencedor ou efeito não atribuível à saída forçada.")
    rep.log(f"(tempo do bloco 16: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r9_auto"] = {"evol": evol, "laudo": {n: {k: LA[n][k] for k in ("veredito", "motivos", "shuf")} for n in evol}, "padrao_acc": float(base["acc"].mean()),
                          "acc": {n: float(rs[1 + 3 * i]["acc"].mean()) for i, n in enumerate(evol)}}

