def r11_sorteios(metodo: str, tarefa: str, n: int):
    """n configurações sorteadas (semente = crc32 de método|tarefa, tag 11) nas faixas de R11_ESPACO; a lista de n' < n sorteios é prefixo da de n."""
    rng = np.random.default_rng([zlib.crc32((metodo + "|" + tarefa).encode("utf-8")), 11, 3])
    out = []
    for _ in range(n):
        c = {}
        for nome, lo, hi, tipo in R11_ESPACO[metodo]:
            u = rng.random()
            c[nome] = float(math.exp(math.log(lo) + u * (math.log(hi) - math.log(lo)))) if tipo == "log" else float(lo + u * (hi - lo))
        out.append(c)
    return out


def r11_texto_gerador(lk):
    """Gerador do 'texto do dicionário' (mesma construção de `r9_dados`, tarefa 'texto'): devolve gen(m, rng) → (X, y). Usado pelo lago de T3 (itens compostos de vetores do dicionário)."""
    Z = lk.pca_semente(8)
    cen = [Z[0]]
    for _ in range(3):
        cen.append(Z[np.argmax(np.min([((Z - c) ** 2).sum(1) for c in cen], axis=0))])
    cen = np.array(cen)
    for _ in range(25):
        lab = np.argmin(((Z[:, None, :] - cen[None]) ** 2).sum(2), axis=1)
        cen = np.array([Z[lab == j].mean(0) if np.any(lab == j) else cen[j] for j in range(4)])
    top = [np.where(lab == j)[0] for j in np.argsort([-np.sum(lab == j) for j in range(4)], kind="stable")]
    top = [t for t in top if len(t) >= 3]
    K = len(top)
    allw = np.arange(len(Z))

    def gen(m, rng):
        pr = rng.integers(0, K, m)
        X = np.zeros((m, 8))
        for i in range(m):
            ws = [top[pr[i]][rng.integers(0, len(top[pr[i]]))] if rng.random() < 0.40 else allw[rng.integers(0, len(allw))] for _ in range(5)]
            X[i] = Z[ws].mean(0)
        return X * 1.5, (((pr & 1) ^ (pr >> 1)) == 1).astype(float)
    return gen


def r11_lago(tarefa: str, seed: int, n: int, lk=None):
    """Lago NÃO ROTULADO de 6n pontos da distribuição da tarefa (RNG [semente,11,1]); devolve (X, y_oculto). Os rótulos ocultos servem só ao diagnóstico de pureza (nunca ao treino)."""
    if tarefa in R14_TAREFAS_NOVAS:      # [R14]
        return r14_lago(tarefa, seed, n)
    if tarefa in R13_TAREFAS_NOVAS:      # [R13]
        return r13_lago(tarefa, seed, n)
    rng = np.random.default_rng([seed, 11, 1])
    m = R11_LAGO * n
    if tarefa == "espirais":
        t = rng.uniform(0.15, 1.0, (2, m // 2))
        ang = 5.0 * math.pi * t
        a = np.c_[t[0] * np.cos(ang[0]), t[0] * np.sin(ang[0])] + 0.03 * rng.standard_normal((m // 2, 2))
        b = np.c_[t[1] * np.cos(ang[1]), t[1] * np.sin(ang[1])] + 0.03 * rng.standard_normal((m // 2, 2))
        return np.r_[a, -b] * 2, np.r_[np.zeros(m // 2), np.ones(m // 2)]
    if tarefa == "paridade":
        X = rng.integers(0, 2, (m, 10)) * 2.0 - 1.0
        return X, (np.prod(X[:, :5], axis=1) > 0).astype(float)
    if tarefa == "texto":
        return r11_texto_gerador(lk)(m, rng)
    if tarefa == "estreita":
        x = rng.uniform(-1, 1, (m, 2))
        r = np.sqrt((x ** 2).sum(1))
        return x * 1.5, (np.floor(r * 3.2) % 2 == 0).astype(float)
    if tarefa == "poucos":
        h = m // 2
        t = rng.uniform(0, math.pi, (2, h))
        a = np.c_[np.cos(t[0]), np.sin(t[0])]
        b = np.c_[1 - np.cos(t[1]), 0.5 - np.sin(t[1])]
        X = np.r_[a, b] + 0.22 * rng.standard_normal((2 * h, 2))
        return X * 1.5, np.r_[np.zeros(h), np.ones(h)]
    raise ValueError(tarefa)


def r11_lago_lote(tarefa: str, seeds, nks, lk=None):
    """Empilha os lagos das sementes: (Xl (K,Nl,d), yl (K,Nl), ml (K,Nl)) com Nl = 6·n_máx e máscara por rede (n variável em T5)."""
    L = [r11_lago(tarefa, int(s), int(n), lk) for s, n in zip(seeds, nks)]
    Nl = max(len(x[0]) for x in L)
    K, d = len(L), L[0][0].shape[1]
    Xl, yl, ml = np.zeros((K, Nl, d), np.float32), np.zeros((K, Nl), np.float32), np.zeros((K, Nl), np.float32)
    for k, (a, b) in enumerate(L):
        Xl[k, :len(a)], yl[k, :len(a)], ml[k, :len(a)] = a, b, 1.0
    return Xl, yl, ml


def r11_knn(Q, X, mr, k: int, bloco: int = 8, excluir_si: bool = False, excl=None):
    """Como `r10_knn`, com `excl` (K,M) opcional: índice de uma linha de X a IGNORAR por consulta (a base do candidato no conjunto de verificação). Devolve (índices (K,M,k), distâncias (K,M,k)), k vizinhos SEM ordem."""
    K, M, _ = Q.shape
    N = X.shape[1]
    idx = np.empty((K, M, k), np.int32)
    dst = np.empty((K, M, k), np.float32)
    for a in range(0, K, bloco):
        q, x = Q[a:a + bloco], X[a:a + bloco]
        d2 = (q * q).sum(2)[:, :, None] + (x * x).sum(2)[:, None, :] - 2.0 * np.matmul(q, x.transpose(0, 2, 1))
        d2 = np.where(mr[a:a + bloco, None, :] > 0, d2, np.float32(np.inf))
        if excluir_si:
            ii = np.arange(N)
            d2[:, ii, ii] = np.inf
        if excl is not None:
            e = excl[a:a + bloco]
            d2[np.arange(len(q))[:, None], np.arange(M)[None, :], e] = np.inf
        j = np.argpartition(d2, k - 1, axis=2)[:, :, :k]
        idx[a:a + bloco] = j
        dst[a:a + bloco] = np.sqrt(np.maximum(np.take_along_axis(d2, j, axis=2), 0.0))
    return idx, dst


def r11_gens(ruido_seed, seeds, tag):
    """Um gerador por rede, semeado por (ruido_seed, semente da rede, 11, tag): os sorteios de uma rede NÃO dependem de quem está no lote nem do preenchimento (n variável em T5)."""
    return [np.random.default_rng([int(ruido_seed), int(s), 11, int(tag)]) for s in seeds]


def r11_dirs(gens, nval, M, d):
    """Direções aleatórias de norma 1 (K,M,d) float32: a rede k usa `nval[k]` direções do seu próprio gerador (o resto = 0)."""
    K = len(gens)
    g = np.zeros((K, M, d), np.float32)
    for k, r in enumerate(gens):
        v = r.standard_normal((int(nval[k]), d)).astype(np.float32)
        g[k, :len(v)] = v / (np.sqrt((v * v).sum(1, keepdims=True)) + np.float32(1e-9))
    return g


def _r11_logit(p):
    p = np.clip(p, 0.02, 0.98)
    return np.log(p / (1.0 - p))


def r11_evidencias(snaps, W, B, xc, yc, X, y, mr, nnmed, ref_d5, rg, nval, excl=None):
    """Evidências do verificador para candidatos (xc:(K,M,d), rótulo yc:(K,M)) de K redes. snaps = lista de 3 (W,B) (instantâneos S−60, S−30, S). W,B = pesos atuais (= S). ref_d5:(K,N) = distância ao 5º vizinho (excluindo a si) dos reais.
    Devolve (F:(K,M,5) com [E_média, E_mín, P, D, V] em probabilidade, viz = (índice do vizinho real mais próximo (K,M), distância a ele (K,M)), conf_E (K,M) = E_média). `rg` = lista de geradores por rede, nval = nº de candidatos válidos por rede; `excl` = índice da base a ignorar (conjunto de verificação)."""
    f32 = np.float32
    K, M, d = xc.shape
    kk = np.arange(K)
    sinal = np.where(yc > 0.5, f32(1), f32(-1))
    pl = lambda p: np.where(yc > 0.5, p, 1.0 - p)
    ps = np.stack([pl(r10_prever(Wi, Bi, xc)) for (Wi, Bi) in snaps])                          # (3,K,M)
    E_med, E_min = ps.mean(0), ps.min(0)
    # P: perturbações de norma 0,3·nnmed na direção aleatória
    acc_p = np.zeros((K, M), f32)
    esc = (R11_PERT * nnmed)[:, None, None].astype(f32)
    for _ in range(R11_J):
        acc_p += pl(r10_prever(W, B, xc + esc * r11_dirs(rg, nval, M, d)))
    Pm = acc_p / f32(R11_J)
    ii, dd = r11_knn(xc, X, mr, 5, excl=excl)
    d5 = dd.max(2)
    cont = np.empty((K, M), f32)
    for a in range(0, K, 8):
        cont[a:a + 8] = ((ref_d5[a:a + 8, None, :] >= d5[a:a + 8, :, None]) & (mr[a:a + 8, None, :] > 0)).sum(2)
    nk = mr.sum(1)
    Dp = (1.0 + cont) / (nk[:, None] + 1.0)
    yk = y[kk[:, None, None], ii]
    wv = 1.0 / (dd + f32(1e-6))
    V = (wv * (np.where(yc > 0.5, 1.0, 0.0)[:, :, None] == yk)).sum(2) / wv.sum(2)
    j1 = dd.argmin(2)
    viz_i = np.take_along_axis(ii, j1[:, :, None], 2)[:, :, 0]
    viz_d = dd.min(2)
    F = np.stack([E_med, E_min, Pm, Dp, V.astype(f32)], axis=2).astype(f32)
    return F, (viz_i, viz_d), E_med


def r11_vetos(xc, yc, valido, y, viz, conf_E, nnmed):
    """Regras de veto (estilo Prolog): contradiz_fato(C) :- vizinho_real_mais_proximo(C,R), dist(C,R) ≤ 1,0·nnmed, rotulo(R) ≠ rotulo(C).
    conflito(C) :- outro_candidato(C2), dist(C,C2) ≤ 0,5·nnmed, rotulo(C2) ≠ rotulo(C), conf(C2) > conf(C). Devolve (contradiz, conflito) booleanos (K,M)."""
    K, M, _ = xc.shape
    kk = np.arange(K)
    viz_i, viz_d = viz
    yr = y[kk[:, None], viz_i]
    contradiz = (viz_d <= R11_RCONTRA * nnmed[:, None]) & ((yr > 0.5) != (yc > 0.5))
    conflito = np.zeros((K, M), bool)
    r2 = ((R11_RCONF * nnmed) ** 2).astype(np.float32)
    for a in range(0, K, 4):
        q = xc[a:a + 4]
        d2 = (q * q).sum(2)[:, :, None] + (q * q).sum(2)[:, None, :] - 2.0 * np.matmul(q, q.transpose(0, 2, 1))
        v = valido[a:a + 4]
        m = (d2 <= r2[a:a + 4, None, None]) & ((yc[a:a + 4, :, None] > 0.5) != (yc[a:a + 4, None, :] > 0.5)) & (conf_E[a:a + 4, None, :] > conf_E[a:a + 4, :, None]) & v[:, None, :]
        conflito[a:a + 4] = m.any(2) & v
    return contradiz, conflito


def r11_ajustar_calibracao(Z, t, wm, lam=R11_L2, it: int = 8):
    """Regressão logística ponderada por rede (Newton, L2 = lam nos pesos exceto o viés). Z:(K,n,F) com a última coluna = 1; t:(K,n) alvo; wm:(K,n) máscara (1 = linha válida). Devolve w:(K,F) (float64)."""
    K, n, F = Z.shape
    Z = Z.astype(np.float64)
    w = np.zeros((K, F))
    R = lam * np.eye(F)
    R[F - 1, F - 1] = 0.0
    for _ in range(it):
        p = 1.0 / (1.0 + np.exp(-np.clip(np.einsum("knf,kf->kn", Z, w), -30, 30)))
        s = wm * p * (1 - p)
        H = np.einsum("knf,kn,kng->kfg", Z, s, Z) + R[None] + 1e-6 * np.eye(F)[None]
        g = np.einsum("knf,kn->kf", Z, wm * (p - t)) + w @ R
        w = w - np.linalg.solve(H, g[:, :, None])[:, :, 0]
    return w


def r11_pcal(F, w, abl):
    """Probabilidade calibrada de rótulo correto a partir das evidências F:(K,M,5) e dos pesos w:(K,6) da calibração (ou, sem calibração, a média simples das 5 evidências)."""
    if "C" in abl:
        return F.mean(2)
    Z = _r11_zmat(F, abl)
    return 1.0 / (1.0 + np.exp(-np.clip(np.einsum("kmf,kf->km", Z, w), -30, 30)))


def _r11_zmat(F, abl):
    Z = np.concatenate([_r11_logit(F.astype(np.float64)), np.ones(F.shape[:2] + (1,))], axis=2)
    for comp, cols in (("E", (0, 1)), ("P", (2,)), ("D", (3,)), ("V", (4,))):
        if comp in abl:
            for c in cols:
                Z[:, :, c] = 0.0
    return Z


def r11_verificar(snaps, W, B, xc, yc, valido, X, y, mr, nk, nnmed, ref_d5, ruido_seed, seeds, ciclo, abl=()):
    """O VERIFICADOR completo (PRÉ-REGISTRO R11): evidências → calibração por regressão logística num conjunto de verificação feito só de reais (base excluída dos vizinhos/da referência) → P_cal, mais vetos de regras.
    Devolve (P_cal (K,M), veto (K,M) bool, F (K,M,5), info). Os sorteios dependem só de (ruido_seed, ciclo): ablações com a mesma config compartilham perturbações e conjunto de verificação."""
    f32 = np.float32
    K, N, d = X.shape
    F, viz, conf_E = r11_evidencias(snaps, W, B, xc, yc, X, y, mr, nnmed, ref_d5, r11_gens(ruido_seed, seeds, 80 + ciclo), valido.sum(1))
    contradiz, conflito = r11_vetos(xc, yc, valido, y, viz, conf_E, nnmed)
    veto = np.zeros_like(contradiz) if "R" in abl else (contradiz | conflito)
    w = None
    if "C" not in abl:
        rv = r11_gens(ruido_seed, seeds, 70 + ciclo)
        g = r11_dirs(rv, nk, N, d)
        s_, u_ = np.zeros((K, N), f32), np.zeros((K, N))
        for k_, r_ in enumerate(rv):
            s_[k_, :nk[k_]] = r_.uniform(0.2, 1.5, nk[k_])
            u_[k_, :nk[k_]] = r_.random(nk[k_])
        xv = X + (s_ * nnmed[:, None])[:, :, None] * g
        yv = np.where(u_ < 0.5, y, 1.0 - y).astype(f32)
        tv = (yv == y).astype(np.float64)
        Fv, _, _ = r11_evidencias(snaps, W, B, xv, yv, X, y, mr, nnmed, ref_d5, r11_gens(ruido_seed, seeds, 90 + ciclo), nk, excl=np.broadcast_to(np.arange(N)[None, :], (K, N)))
        w = r11_ajustar_calibracao(_r11_zmat(Fv, abl), tv, mr.astype(np.float64))
    P = r11_pcal(F, w, abl)
    return P.astype(f32), veto, F, {"w": w, "contradiz": contradiz, "conflito": conflito}


def r11_auc(score, ok, valido):
    """AUROC (por rede, por postos; empates = postos ordinais) do escore para 'candidato correto' entre os candidatos válidos; NaN se faltar uma classe."""
    K = score.shape[0]
    out = np.full(K, np.nan)
    for k in range(K):
        v = valido[k]
        s, o = score[k][v], ok[k][v]
        npos, nneg = int(o.sum()), int((~o).sum())
        if npos == 0 or nneg == 0:
            continue
        r = np.empty(len(s))
        r[np.argsort(s, kind="stable")] = np.arange(1, len(s) + 1)
        out[k] = (r[o].sum() - npos * (npos + 1) / 2) / (npos * nneg)
    return out


def r11_ece_p(p, ok, valido, bins: int = 10):
    """ECE de probabilidades p de 'correto' vs desfecho ok, empilhando as redes (candidatos válidos)."""
    p, o = p[valido], ok[valido].astype(float)
    if len(p) == 0:
        return float("nan")
    b = np.minimum((p * bins).astype(int), bins - 1)
    e = 0.0
    for i in range(bins):
        m = b == i
        if m.any():
            e += m.sum() / len(p) * abs(p[m].mean() - o[m].mean())
    return float(e)


def r11_candidatos(app, ciclo, W, B, X, y, mr, nk, sdx, cfg, seeds, ruido_seed, d, lago, gate=None, fluxo=None):
    """Gera os m = 2n candidatos de UM ciclo para o lote, SEM filtrar (PRÉ-REGISTRO R11). app ∈ {a (alucinado), b (pseudo-rótulo), c (recuperação), s (as três, cotas ⌈2n/3⌉ com `gate` (K,) desligando a e b)}.
    Devolve (xc (K,M,d) float32, yc (K,M) float32, valido (K,M) bool, src (K,M) int 0=a 1=b 2=c, pt (K,M) = probabilidade do professor em xc, ytrue_c (K,M)|None = rótulo oculto do ponto do lago (fonte c)).
    O RNG depende só de (ruido_seed, ciclo): todos os filtros (e ablações com a mesma config) veem os MESMOS candidatos."""
    f32 = np.float32
    K, N, _ = X.shape
    M = 2 * N
    rg = r11_gens(ruido_seed, seeds, 50 + ciclo)
    jj = np.arange(M)
    kk = np.arange(K)
    mk = 2 * nk
    valido = jj[None, :] < mk[:, None]
    b = np.zeros((K, M), int)
    eps = np.zeros((K, M, d), f32)
    u_alu, u_lab, u_viz = np.zeros((K, M)), np.zeros((K, M)), np.zeros((K, M))
    for k, r in enumerate(rg):                 # sorteios POR REDE (independentes do lote e do preenchimento)
        m_ = int(mk[k])
        b[k, :m_] = np.minimum((r.random(m_) * nk[k]).astype(int), nk[k] - 1)
        eps[k, :m_] = r.standard_normal((m_, d))
        u_alu[k, :m_], u_lab[k, :m_], u_viz[k, :m_] = r.random(m_), r.random(m_), r.random(m_)
    xb = np.take_along_axis(X, b[:, :, None], axis=1)
    yb = np.take_along_axis(y, b, axis=1)
    gc = lambda nome, pad=0.0: np.array([c.get(nome, pad) for c in cfg], float)
    if app == "m":                             # [R12] sistema MÍNIMO: n pseudo-rótulos (b) + n recuperados do lago (c); sem alucinação
        src = np.where(jj[None, :] < nk[:, None], 1, 2)
    elif app == "s":
        q = np.ceil(mk / 3.0).astype(int)
        qa = np.where(gate, q, 0)
        src = np.where(jj[None, :] < qa[:, None], 0, np.where(jj[None, :] < (qa + qa)[:, None], 1, 2))
    else:
        src = np.full((K, M), {"a": 0, "b": 1, "c": 2}[app])
    xc = np.empty((K, M, d), f32)
    yc = np.empty((K, M), f32)
    ytc = None
    if app in ("a", "s"):                      # (a) ALUCINADO (gerador 'del' da R10, caos de Lorenz, saída forçada)
        w = np.zeros((K, M, d), f32)
        ix = jj[:, None] + R10_LAG * np.arange(d)[None, :]
        for m_ in sorted(set(mk.tolist())):    # fluxo de Lorenz com comprimento próprio de cada rede (a padronização depende do comprimento)
            ks = np.where(mk == m_)[0]
            flow = (fluxo or r10_lorenz_lote)(int(m_) + R10_LAG * (d - 1) + 1, [seeds[k] + 1717 + 1000 * ciclo for k in ks])      # [R13] `fluxo`: controle caótico (embaralhado) do interruptor K
            w[ks] = flow[:, np.minimum(ix, flow.shape[1] - 1)].astype(f32)    # (índices além do comprimento só ocorrem em slots inválidos, preenchimento)
        Tc = gc("T") * (R10_COOL ** ciclo)
        xa = xb + Tc[:, None, None].astype(f32) * sdx * w
        if gc("gam").max() > 0:
            ii, _ = r10_knn(xa, X, mr, R10_FK)
            mu = X[kk[:, None, None], ii].mean(2)
            xa = xa + gc("gam")[:, None, None].astype(f32) * (mu - xa)
        pa = r10_prever(W, B, xa)
        lg = np.log((pa + 1e-6) / (1.0 - pa + 1e-6)) / R10_TH
        ys = u_lab < 1.0 / (1.0 + np.exp(-lg))
        ya = np.where(u_alu < gc("rho")[:, None], ys, yb > 0.5).astype(f32)
        sel = (src == 0)
        xc[:] = np.where(sel[:, :, None], xa, xc)
        yc[:] = np.where(sel, ya, yc)
    if app in ("b", "s", "m"):                 # (b) PSEUDO-RÓTULO
        xp_ = xb + (gc("sig")[:, None, None].astype(f32)) * sdx * eps
        pp_ = r10_prever(W, B, xp_)
        yp_ = (pp_ > 0.5).astype(f32)
        sel = (src == 1)
        xc[:] = np.where(sel[:, :, None], xp_, xc)
        yc[:] = np.where(sel, yp_, yc)
    if app in ("c", "s", "m"):                 # (c) RECUPERAÇÃO de vizinhos do lago não rotulado; rótulo = o da âncora
        Xl, yl, ml = lago
        ii, _ = r11_knn(xb, Xl, ml, R11_KLAGO)
        pick = np.minimum((u_viz * R11_KLAGO).astype(int), R11_KLAGO - 1)
        li = np.take_along_axis(ii, pick[:, :, None], 2)[:, :, 0]
        xcc = Xl[kk[:, None], li]
        ytc = yl[kk[:, None], li]
        sel = (src == 2)
        xc[:] = np.where(sel[:, :, None], xcc, xc)
        yc[:] = np.where(sel, yb, yc)
    xc = xc.astype(f32)
    pt = r10_prever(W, B, xc)
    return xc, yc, valido, src, pt, ytc


def r11_aceitar(spec, ciclo, cfg, W, B, snaps, xc, yc, valido, src, pt, X, y, mr, nk, nnmed, ref_d5, ruido_seed, seeds, thv=None):
    """Aplica o FILTRO do spec aos candidatos. Devolve (aceito (K,M) bool, peso (K,M) float32, escore (K,M)|None, info). filtro ∈ sem | conf | f10 | verif | azar (azar: verificador só para contar)."""
    f32 = np.float32
    K = X.shape[0]
    kk = np.arange(K)
    flt = spec["filtro"]
    gc = lambda nome, pad=0.0: np.array([c.get(nome, pad) for c in cfg], float)
    pl = np.where(yc > 0.5, pt, 1.0 - pt)
    info = {}
    escore = None
    if flt == "sem":
        acc = valido.copy()
    elif flt == "conf":
        acc = valido & (pl >= gc("theta")[:, None])
        escore = pl
    elif flt == "ens":     # [R12] comitê de 3 instantâneos da própria rede: aceita sse o MÍNIMO da probabilidade do rótulo do candidato ≥ θ_e
        emin = np.minimum.reduce([np.where(yc > 0.5, r10_prever(Wi, Bi, xc), 1.0 - r10_prever(Wi, Bi, xc)) for (Wi, Bi) in snaps])
        acc = valido & (emin >= gc("the")[:, None])
        escore = emin
    elif flt == "f10":
        ii, dd = r10_knn(xc, X, mr, R10_FK)
        f1 = dd.min(2) <= R10_FSUP * nnmed[:, None]
        yk = y[kk[:, None, None], ii]
        wv = 1.0 / (dd + 1e-6)
        voto = (wv * ((yk > 0.5) == (yc[:, :, None] > 0.5))).sum(2) / wv.sum(2)
        acc = valido & f1 & (voto >= R10_FLOC) & (pl >= R10_FPROF)
    else:   # verif / azar
        P, veto, F, vi = r11_verificar(snaps, W, B, xc, yc, valido, X, y, mr, nk, nnmed, ref_d5, ruido_seed, seeds, ciclo, spec.get("abl", ()))
        th = (gc("thv") if thv is None else thv)[:, None]
        acc = valido & (P >= th) & ~veto
        escore = P
        info = {"P": P, "veto": veto, "w": vi["w"]}
        if flt == "azar":
            r2 = np.full(valido.shape, 2.0)
            for k_, r_ in enumerate(r11_gens(ruido_seed, seeds, 60 + ciclo)):
                nv_ = int(valido[k_].sum())
                r2[k_, :nv_] = r_.random(nv_)
            acc = valido & (np.argsort(np.argsort(r2, axis=1), axis=1) < acc.sum(1)[:, None])
            escore = None
    peso = f32(R10_WSYN) * acc
    if spec.get("app") == "s" and flt == "verif":
        peso = (f32(R10_WSYN) * acc * info["P"]).astype(f32)
    return acc, peso.astype(f32), escore, info


def r11_ciclo_est(tarefa, app, xc, yc, valido, acc, src, ytc, escore):
    """Estatísticas exploratórias de um ciclo: nº de candidatos/aceitos, pureza (aceitos/rejeitados/todos) quando a verdade é conhecida (T2, T4 por regra; fonte c por rótulo oculto do lago), AUROC e ECE do escore."""
    est = {"n": valido.sum(1), "acc": acc.sum(1)}
    reg = r10_regra(tarefa, xc)
    ok = None
    if reg is not None:
        ok = (reg == (yc > 0.5))
    elif app == "c" and ytc is not None:
        ok = ((ytc > 0.5) == (yc > 0.5))
    if ok is not None:
        est["pur_acc"] = np.where(acc.sum(1) > 0, (ok & acc).sum(1) / np.maximum(acc.sum(1), 1), np.nan)
        rej = valido & ~acc
        est["pur_rej"] = np.where(rej.sum(1) > 0, (ok & rej).sum(1) / np.maximum(rej.sum(1), 1), np.nan)
        est["pur_todos"] = (ok & valido).sum(1) / np.maximum(valido.sum(1), 1)
        if escore is not None:
            est["auc"] = r11_auc(escore, ok, valido)
            est["ece_p"] = r11_ece_p(escore, ok, valido)
    return est


def r11_treinar_lote(spec, tarefa, X, y, mr, cfgs, seeds, passos: int, ruido_seed: int, lago=None):
    """Treina K redes em paralelo (float32; MESMO treino da R10) com candidatos de uma das origens a/b/c/s e um filtro (sem | conf | f10 | verif | azar). Guarda instantâneos S−60, S−30 de cada ciclo para o comitê do verificador.
    Devolve (W, B, info). Os métodos sem candidatos próprios (real, aug_mixup, self_train) são delegados a `r10_treinar_lote`."""
    if "r10" in spec:
        return r10_treinar_lote(R10_SPEC[spec["r10"]], tarefa, X, y, mr, cfgs, seeds, passos, ruido_seed)
    f32 = np.float32
    ocultas = R10_ARQ[tarefa]
    K, N, d = X.shape
    dims = [d] + list(ocultas) + [1]
    nl = len(dims) - 1
    W = [np.empty((K, a, b), f32) for a, b in zip(dims[:-1], dims[1:])]
    B = [np.zeros((K, 1, b), f32) for b in dims[1:]]
    for k, s in enumerate(seeds):
        r = np.random.default_rng([s, 10, 2])
        for i, (a, b) in enumerate(zip(dims[:-1], dims[1:])):
            W[i][k] = (r.standard_normal((a, b)) * math.sqrt(1.0 / a)).astype(f32)
    X, y, mr = X.astype(f32), y.astype(f32), mr.astype(f32)
    nk = mr.sum(1).astype(int)
    gc = lambda nome, pad=0.0: np.array([c.get(nome, pad) for c in cfgs], float)
    lr, wd = gc("lr").astype(f32), gc("wd").astype(f32)
    app = spec["app"]
    M = 2 * N
    mu_x = (X * mr[:, :, None]).sum(1, keepdims=True) / nk[:, None, None]
    sdx = (np.sqrt((((X - mu_x) ** 2) * mr[:, :, None]).sum(1, keepdims=True) / nk[:, None, None]) + f32(1e-3)).astype(f32)
    _, dnn = r10_knn(X, X, mr, 1, excluir_si=True)
    nnmed = np.nanmedian(np.where(mr > 0, dnn[:, :, 0], np.nan), axis=1).astype(f32)
    usa_verif = spec["filtro"] in ("verif", "azar")
    ref_d5 = None
    if usa_verif:
        _, d5r = r11_knn(X, X, mr, 5, excluir_si=True)
        ref_d5 = d5r.max(2)
    Xall = np.zeros((K, N + M, d), f32)
    Yall = np.zeros((K, N + M, 1), f32)
    Wall = np.zeros((K, N + M, 1), f32)
    Xall[:, :N], Yall[:, :N, 0], Wall[:, :N, 0] = X, y, mr
    P = W + B
    Mm = [np.zeros_like(p) for p in P]
    Vv = [np.zeros_like(p) for p in P]
    sh3 = lambda v: v[:, None, None]
    pool_on = False
    info = {"est": [], "mon": []}
    snaps_t = {}
    ciclos = {R10_S1: 0, R10_S2: 1}
    guardar = {s - 60: s for s in ciclos} | {s - 30: s for s in ciclos}
    tx0 = None
    with np.errstate(all="ignore"):
        for t in range(passos):
            if t in guardar:
                snaps_t[t] = ([w.copy() for w in W], [b.copy() for b in B])
            if t in ciclos:
                c = ciclos[t]
                snaps = [snaps_t[t - 60], snaps_t[t - 30], (W, B)] if c >= 0 else None
                gate, thv = None, gc("thv") if "thv" in cfgs[0] else None
                mon = {}
                if app == "s":
                    pr = r10_prever(W, B, X)
                    acc_tr = (((pr > 0.5) == (y > 0.5)) * mr).sum(1) / nk
                    gate = (acc_tr >= R11_GATE) if spec.get("monitor") else np.ones(K, bool)
                    mon["gate"] = gate.mean()
                    if spec.get("monitor") and c == 1 and tx0 is not None:
                        thv = np.clip(thv - R11_RELAX * (tx0 < R11_TX_BAIXA) + R11_APERTA * (tx0 > R11_TX_ALTA), 0.5, 0.99)
                        mon["relaxar"], mon["apertar"] = float((tx0 < R11_TX_BAIXA).mean()), float((tx0 > R11_TX_ALTA).mean())
                xc, yc, valido, src, pt, ytc = r11_candidatos(app, c, W, B, X, y, mr, nk, sdx, cfgs, seeds, ruido_seed, d, lago, gate)
                acc, peso, escore, vi = r11_aceitar(spec, c, cfgs, W, B, snaps, xc, yc, valido, src, pt, X, y, mr, nk, nnmed, ref_d5, ruido_seed, seeds, thv)
                Xall[:, N:], Yall[:, N:, 0], Wall[:, N:, 0] = xc, yc, peso
                tx0 = acc.sum(1) / np.maximum(valido.sum(1), 1)
                est = r11_ciclo_est(tarefa, app, xc, yc, valido, acc, src, ytc, escore)
                if app == "s":
                    est["frac_c"] = ((src == 2) & acc).sum(1) / np.maximum(acc.sum(1), 1)
                info["est"].append(est)
                info["mon"].append(mon)
                pool_on = True
            n_use = N + (M if pool_on else 0)
            Wt = Wall[:, :n_use]
            Wt = Wt / Wt.sum(1, keepdims=True)
            env = 0.05 + 0.95 * 0.5 * (1.0 + math.cos(math.pi * t / passos))
            gW, gb = r10_fb(W, B, Xall[:, :n_use], Yall[:, :n_use], Wt)
            gW = [g + sh3(wd) * w for g, w in zip(gW, W)]
            G = gW + gb
            nrm = np.sqrt(sum((g * g).reshape(K, -1).sum(1) for g in G))
            esc = sh3(np.minimum(f32(1.0), f32(5.0) / (nrm + f32(1e-12))))
            bc1, bc2 = 1 - 0.9 ** (t + 1), 1 - 0.999 ** (t + 1)
            lrt = sh3((lr * f32(env)).astype(f32))
            for j, (pp, g) in enumerate(zip(P, G)):
                g = g * esc
                Mm[j] *= f32(0.9)
                Mm[j] += f32(0.1) * g
                Vv[j] *= f32(0.999)
                Vv[j] += f32(0.001) * g * g
                pp -= lrt * (Mm[j] / f32(bc1)) / (np.sqrt(Vv[j] / f32(bc2)) + f32(1e-8))
    return W, B, info


def r11_rodar(spec, tarefa, cfgs, seeds, lk, ruido_seed, embaralhar=False, passos=R11_PASSOS):
    Xtr, ytr, mr, Xte, yte = r10_dados_lote(tarefa, seeds, lk, embaralhar)
    lago = None
    if spec.get("app") in ("c", "s", "m"):
        lago = r11_lago_lote(tarefa, seeds, mr.sum(1).astype(int), lk)
    W, B, info = r11_treinar_lote(spec, tarefa, Xtr, ytr, mr, cfgs, seeds, passos, ruido_seed, lago)
    d = r9_avaliar_lote([w.astype(np.float64) for w in W], [b.astype(np.float64) for b in B], Xte, yte)
    d["info"] = info
    return d


def _r11_rs(nome, tarefa, fase, desloc):
    return zlib.crc32(f"R11|{nome}|{tarefa}|{fase}".encode("utf-8")) + desloc


def _r11_cand_stats(est):
    """Estatísticas por rede (média sobre os ciclos) dos candidatos de uma execução."""
    ci = {}
    if not est:
        return ci
    ci["taxa"] = np.mean([e["acc"] / np.maximum(e["n"], 1) for e in est], axis=0)
    for k_ in ("pur_acc", "pur_rej", "pur_todos", "auc"):
        if k_ in est[0]:
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", RuntimeWarning)
                ci[k_] = np.nanmean(np.stack([e[k_] for e in est]), axis=0) if k_ != "pur_todos" else np.mean([e["pur_todos"] for e in est], axis=0)
    if "ece_p" in est[0]:
        ci["ece_p"] = float(np.nanmean([e["ece_p"] for e in est]))
    if "frac_c" in est[0]:
        ci["frac_c"] = np.mean([e["frac_c"] for e in est], axis=0)
    return ci


def _job_r11_celula(args):
    """Uma célula (método × tarefa): ajuste (n_sort sorteios × n_dev sementes DEV; vence a maior acurácia média de teste) → avaliação ÚNICA da config vencedora em n_c sementes novas.
    Nos 3 verificadores (a/b/c_verif) a mesma config roda ainda: o PLACEBO (aceitação aleatória com o mesmo nº de aceitos) em n_c sementes e as 6 ABLAÇÕES de componente em n_abl sementes (as primeiras)."""
    metodo, tarefa, lk, n_sort, n_c, desloc, n_abl = args
    t_cpu = time.process_time()
    n_dev = r10_ndev(tarefa)
    spec = R11_SPEC[metodo]
    sorts = r11_sorteios(metodo, tarefa, n_sort)
    cfgs = [c for c in sorts for _ in range(n_dev)]
    seeds = [R11_SEM_DEV + desloc + j for _ in sorts for j in range(n_dev)]
    d = r11_rodar(spec, tarefa, cfgs, seeds, lk, _r11_rs(metodo, tarefa, 1, desloc))
    sc = d["acc"].reshape(n_sort, n_dev).mean(1)
    best = int(np.argmax(sc))
    sc_c = [R11_SEM_C + desloc + j for j in range(n_c)]
    rs2 = _r11_rs(metodo, tarefa, 2, desloc)
    c = r11_rodar(spec, tarefa, [sorts[best]] * n_c, sc_c, lk, rs2)
    out = {"metodo": metodo, "tarefa": tarefa, "cfg": sorts[best], "dev": sc, "dev_best": float(sc[best]), "dev_med": float(np.median(sc)), "dev_nfin": int((~d["fin"]).sum()),
           "acc": c["acc"], "loss": c["loss"], "ece": c["ece"], "nfin": int((~c["fin"]).sum()), "cand": _r11_cand_stats(c["info"]["est"]), "seeds": sc_c, "mon": c["info"].get("mon", [])}
    if metodo.endswith("_verif"):
        pl = r11_rodar(dict(spec, filtro="azar"), tarefa, [sorts[best]] * n_c, sc_c, lk, rs2)
        out["azar"] = {"acc": pl["acc"], "ece": pl["ece"], "cand": _r11_cand_stats(pl["info"]["est"])}
        out["abl"] = {}
        for comp in R11_COMPS:
            ab = r11_rodar(dict(spec, abl=(comp,)), tarefa, [sorts[best]] * n_abl, sc_c[:n_abl], lk, rs2)
            out["abl"][comp] = {"acc": ab["acc"], "cand": _r11_cand_stats(ab["info"]["est"])}
        out["abl_cheio"] = c["acc"][:n_abl]
    out["cpu"] = time.process_time() - t_cpu
    return out


def _job_r11_laudo(args):
    """Medidas do laudo em n_f sementes FRESCAS (11300+) de uma config e variante do método (spec), com rótulos verdadeiros ou embaralhados. `nome_rs` deriva o RNG de ruído (variantes com a MESMA config compartilham candidatos)."""
    spec, tarefa, cfg, embaralhar, lk, n_f, desloc, nome_rs = args
    seeds = [R11_SEM_F + desloc + j for j in range(n_f)]
    d = r11_rodar(spec, tarefa, [cfg] * n_f, seeds, lk, _r11_rs(nome_rs, tarefa, 3 + int(embaralhar), desloc), embaralhar)
    return {"acc": d["acc"], "ece": d["ece"], "loss": d["loss"], "nfin": int((~d["fin"]).sum())}


def r11_tarefas(ctx):
    """Lista das células do BLOCO 18 (75 = 5 tarefas × 15 métodos; as mais pesadas primeiro). Mesma função para enviar ao segundo plano e para consumir."""
    if "r11_tar" in ctx.res_cache:
        return ctx.res_cache["r11_tar"]
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R11_DEV") else 0
    n_sort, n_c, n_abl = (3, 16, 8) if rapido else (R11_NSORT, R11_NC, R11_NABL)
    lk = LakeLeve(ctx.lake)
    ordem_m = ("a_verif", "b_verif", "c_verif", "sistema", "aug_mixup", "self_train", "a_f10", "a_conf", "a_sem", "b_f10", "b_sem", "c_f10", "c_conf", "c_sem", "real")
    tar = [(m, t, lk if t == "texto" else None, n_sort, n_c, desloc, n_abl) for t in ("paridade", "estreita", "espirais", "texto", "poucos") for m in ordem_m]
    ctx.res_cache["r11_tar"] = (_job_r11_celula, tar)
    return ctx.res_cache["r11_tar"]


R11_LAUDOS = ("L1", "L2")
R11_NOME_L = {"L1": "L1 sistema (V3 = SEM verificador: aceita todos, peso 0,5, MESMA config)", "L2": "L2 sistema (V3 = SEM monitores: três fontes sempre ligadas, θ_v fixo, MESMA config)"}


def r11_jobs_laudo(R, melhor_pad, lk, n_f, desloc):
    """5 jobs de laudo por tarefa (ordem fixa): sistema, padrão, sistema com rótulos embaralhados, L1 (sem verificador), L2 (sem monitores)."""
    jl = []
    for t in R11_TAREFAS:
        lkt = lk if t == "texto" else None
        cs, mp = R[("sistema", t)]["cfg"], melhor_pad[t]
        sp = R11_SPEC["sistema"]
        jl += [(sp, t, cs, False, lkt, n_f, desloc, "sistema"), (R11_SPEC[mp], t, R[(mp, t)]["cfg"], False, lkt, n_f, desloc, mp), (sp, t, cs, True, lkt, n_f, desloc, "sistema"),
               (dict(sp, filtro="sem"), t, cs, False, lkt, n_f, desloc, "sistema"), (dict(sp, monitor=False), t, cs, False, lkt, n_f, desloc, "sistema")]
    return jl


def r11_laudos_de(rl, seed):
    """Dos 5 resultados de laudo de UMA tarefa: os 2 laudos (função `laudo_escrutinio` da R9, sem alteração)."""
    sis, pad, sshuf, ab_v, ab_m = rl
    out = {"L1": laudo_escrutinio(sis["acc"], pad["acc"], ab_v["acc"], sshuf["acc"], sis["ece"], pad["ece"], seed=seed),
           "L2": laudo_escrutinio(sis["acc"], pad["acc"], ab_m["acc"], sshuf["acc"], sis["ece"], pad["ece"], seed=seed + 10)}
    med = {k: float(v["acc"].mean()) for k, v in zip(("sis", "pad", "sis_shuf", "ab_verif", "ab_monitor"), rl)}
    return out, med


def r11_conf_de(app):
    return "self_train" if app == "b" else f"{app}_conf"


def r11_hipoteses(R, melhor_pad):
    """Pares (id, tarefa) → (acc_a, acc_b, descrição, índice) das 80 confirmatórias: H1–H5 (3 origens × 5 tarefas) e H6 (5 tarefas)."""
    PA, i_ = {}, 0
    for t in R11_TAREFAS:
        for a in R11_APPS:
            v = R[(f"{a}_verif", t)]["acc"]
            for k, outro in (("H1", R[(f"{a}_sem", t)]["acc"]), ("H2", R[(r11_conf_de(a), t)]["acc"]), ("H3", R[(f"{a}_f10", t)]["acc"]),
                             ("H4", R[(f"{a}_verif", t)]["azar"]["acc"]), ("H5", R[(melhor_pad[t], t)]["acc"])):
                i_ += 1
                PA[(f"{k}_{a}", t)] = (v, outro, i_)
        i_ += 1
        PA[("H6", t)] = (R[("sistema", t)]["acc"], R[(melhor_pad[t], t)]["acc"], i_)
    return PA


R11_DESC = {"H1": "{a}_verif − {a}_sem (o verificador ajuda vs não filtrar?)", "H2": "{a}_verif − {c} (vs confiança simples do professor)", "H3": "{a}_verif − {a}_f10 (vs filtro F1∧F2∧F3 da R10)",
            "H4": "{a}_verif − {a}_azar (importam QUAIS aceitos, além de quantos?)", "H5": "{a}_verif − melhor PADRÃO por DEV = {mp}", "H6": "sistema − melhor PADRÃO por DEV = {mp}"}


def bloco18(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 18 — [R11] O VERIFICADOR COMO FILTRO: comitê + perturbação + novidade conforme + vizinhança + regras estilo Prolog + confiança calibrada, filtrando (a) alucinados, (b) pseudo-rótulos, (c) vizinhos recuperados; SISTEMA INTEGRADO + LAUDO; 5 tarefas × 15 métodos, ajuste igual, 40 sementes novas, Holm sobre 80")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R11_DEV") else 0
    n_sort, n_c, n_abl = (3, 16, 8) if rapido else (R11_NSORT, R11_NC, R11_NABL)
    n_f = 16 if rapido else R11_NF
    ok_p = sha_ok(PREREG_R11_CORPO, PREREG_R11_CORPO_SHA256)
    rep.log(f"Integridade: pré-registro R11 (corpo) {PREREG_R11_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r11.txt, carimbado 18:03 PT, ANTES de qualquer código do verificador, das origens a/b/c, do lago e do sistema; nenhuma semente R11 usada antes)' if ok_p else '(!! NÃO CONFERE)'}.")
    ok_a = sha_ok(ADENDO1_R11_CORPO, ADENDO1_R11_CORPO_SHA256)
    rep.log(f"Adendo 1 ao pré-registro R11 (desvios e detalhes não especificados; escrito DEPOIS do código e ANTES da primeira execução com as sementes registradas): {ADENDO1_R11_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r11_adendo1.txt)' if ok_a else '(!! NÃO CONFERE)'}.")
    for l in ADENDO1_R11_CORPO.split("\n")[1:]:
        if l.startswith("D"):
            rep.log("  " + l.strip()[:260] + ("…" if len(l.strip()) > 260 else ""))
    if rapido:
        rep.log(f"(--rapido: {n_sort} sorteios, {n_c} confirmatórias, {n_abl} nas ablações e {n_f} frescas — NÃO é a análise pré-registrada de {R11_NSORT}/{R11_NC}/{R11_NABL}/{R11_NF}.)")
    if desloc:
        rep.log("!! R11_DEV=1: sementes DESLOCADAS em +10000 (depuração). ESTES NÚMEROS NÃO SÃO A ANÁLISE REGISTRADA.")
    rep.sub("Desenho (resumo do pré-registro): na R10 o útil parecia ser o FILTRO, não a alucinação. Um VERIFICADOR forte avalia cada candidato (x, ŷ) com 5 evidências — E comitê de 3 instantâneos da rede (S−60, S−30, S), "
            "P consistência do professor sob 4 perturbações de 0,3·nnmed, D novidade/densidade conforme (p-valor da distância ao 5º real), V voto dos 5 reais mais próximos, R vetos de regras em estilo Prolog (contradiz um fato real próximo; conflita com candidato mais confiável) — "
            "e uma CONFIANÇA CALIBRADA P_cal (regressão logística ajustada num conjunto de verificação feito só de reais; a base é excluída dos vizinhos). Aceita sse P_cal ≥ θ_v ∧ sem veto. Três origens de candidatos (a alucinado, b pseudo-rótulo, c vizinhos de um lago não rotulado) × filtros "
            "(sem | conf | f10 = F1∧F2∧F3 da R10 | verif | azar = mesmo nº de aceitos ao acaso) e o SISTEMA integrado (as 3 origens + verificador + 2 monitores) contra o melhor padrão ajustado.")
    rep.log(f"Métodos (15 células + 3 placebos): PADRÃO = real | aug_mixup | self_train (= b_conf) ; (a) a_sem | a_conf | a_f10 (= delir_gen da R10) | a_verif ; (b) b_sem | b_f10 | b_verif ; (c) c_sem | c_conf | c_f10 | c_verif ; sistema ; placebos a_azar, b_azar, c_azar (config do verificador, sem ajuste próprio). "
            f"Cada célula: {n_sort} sorteios × {r10_ndev('espirais')} sementes DEV (T5: {r10_ndev('poucos')}) → config vencedora → UMA avaliação em {n_c} sementes novas ({R11_SEM_C + desloc}+); mesmos dados e inicializações em todos os métodos (pareado).")
    fn_c, tar_c = r11_tarefas(ctx)
    t1 = time.time()
    cel = mapa_ou_fundo(ctx, "r11a", fn_c, tar_c)
    rep.log(f"(tempo de espera pelas células: {time.time() - t1:.1f}s, jobs={ctx.jobs})", vol=True)
    R = {(c["metodo"], c["tarefa"]): c for c in cel}
    nfin = sum(c["nfin"] + c["dev_nfin"] for c in cel)
    rep.log(f"Redes com pesos/perdas não finitos nos treinos principais (contadas como acaso, 50%): {nfin} de {sum(n_c + n_sort * r10_ndev(c['tarefa']) for c in cel)}.")
    ms = lambda v: f"{100 * np.mean(v):5.1f}±{100 * np.std(v, ddof=1) / math.sqrt(len(v)):<4.1f}"
    rep.sub(f"ACURÁCIA DE TESTE (%) das {n_c} sementes confirmatórias, média ± erro-padrão [melhor score DEV entre colchetes = otimismo da seleção]")
    rep.log(f"{'método':<14}" + "".join(f"{t:>20}" for t in R11_TAREFAS) + f"{'rank médio':>12}")
    rank = {m: [] for m in R11_METODOS}
    for t in R11_TAREFAS:
        ordem = np.argsort([-R[(m, t)]["acc"].mean() for m in R11_METODOS], kind="stable")
        for r_, i in enumerate(ordem, 1):
            rank[R11_METODOS[i]].append(r_)
    for m in R11_METODOS:
        rep.log(f"{m:<14}" + "".join(f"{ms(R[(m, t)]['acc']):>12} [{100 * R[(m, t)]['dev_best']:4.1f}]" for t in R11_TAREFAS) + f"{np.mean(rank[m]):>12.1f}")
    for a in R11_APPS:
        rep.log(f"{a + '_azar':<14}" + "".join(f"{ms(R[(a + '_verif', t)]['azar']['acc']):>12} [  —  ]" for t in R11_TAREFAS) + f"{'(placebo)':>12}")
    rep.sub("Configurações vencedoras no DEV (hiperparâmetros ajustados)")
    for t in R11_TAREFAS:
        rep.log(f"  {R10_NOME_T[t]}")
        for m in R11_METODOS:
            rep.log(f"    {m:<12} " + ", ".join(f"{k}={v:.4g}" for k, v in R[(m, t)]["cfg"].items()) + f" | DEV: melhor {100 * R[(m, t)]['dev_best']:.1f}% mediana dos sorteios {100 * R[(m, t)]['dev_med']:.1f}%")
    melhor_pad = {t: max(R11_PADRAO, key=lambda m: (R[(m, t)]["dev_best"], -R11_PADRAO.index(m))) for t in R11_TAREFAS}
    PA = r11_hipoteses(R, melhor_pad)
    P = {}
    for k, (a_, b_, ii) in PA.items():
        cm = comparar_pareado(a_, b_, seed=ctx.seed + 11000 + ii)
        cm["mde"] = mde80(a_ - b_)
        P[k] = cm
    chaves = list(P)
    ph = dict(zip(chaves, holm([P[k]["p"] for k in chaves])))
    st = {k: _status7(P[k]["media"], ph[k]) for k in chaves}
    rep.sub(f"CONFIRMATÓRIAS ({len(chaves)} = 5 × 15 [H1–H5: 3 origens × 5 tarefas] + 5 H6; Holm sobre {len(chaves)}; Δ = acc(primeiro) − acc(segundo) em pontos percentuais, >0 favorece o primeiro; bicaudal por permutação de sinais, 10000)")
    rep.log(f"{'id':<14}{'comparação':<54}{'Δ (pp)':>9}{'IC95% (pp)':>20}{'p':>9}{'p Holm':>9}{'MDE (pp)':>10}{'v/d':>8}  veredito")
    for k in chaves:
        cm, (h, t) = P[k], (k[0].split("_")[0], k[1])
        a = k[0].split("_")[1] if "_" in k[0] else None
        nm = R11_DESC[h].format(a=a, c=r11_conf_de(a) if a else "", mp=melhor_pad[t])
        rep.log(f"{k[0] + '(' + t + ')':<14}{nm:<54}{100 * cm['media']:>+9.2f}{'[' + format(100 * cm['lo'], '+.2f') + ',' + format(100 * cm['hi'], '+.2f') + ']':>20}{cm['p']:>9.4f}{ph[k]:>9.4f}{100 * cm['mde']:>10.2f}{str(cm['vit']) + '/' + str(cm['der']):>8}  {st[k]}")
    # ---- exploratórias
    rep.sub("EXPLORATÓRIAS (fora do Holm; sem correção) e descritivos")
    rep.log("E1 candidatos: taxa de ACEITAÇÃO média (por método e tarefa); PUREZA = fração de candidatos cujo rótulo bate com a verdade (T2/T4: regra; origem c: rótulo oculto do lago) — aceitos | rejeitados | todos; AUROC do escore para 'rótulo correto'.")
    rep.log(f"{'método':<14}" + "".join(f"{t:>11}" for t in R11_TAREFAS) + "   pureza T2 (acc|rej|todos)  AUROC T2     pureza T4 (acc|rej|todos)  AUROC T4")
    E1 = {}
    mets_e1 = [m for m in R11_METODOS if m not in ("real", "aug_mixup")] + [a + "_azar" for a in R11_APPS]
    getc = lambda m, t: (R[(m[0] + "_verif", t)]["azar"]["cand"] if m.endswith("_azar") else R[(m, t)]["cand"])
    for m in mets_e1:
        lin = f"{m:<14}"
        for t in R11_TAREFAS:
            c_ = getc(m, t)
            tx = float(np.mean(c_["taxa"])) if c_ else float("nan")
            E1[(m, t)] = tx
            lin += f"{100 * tx:>10.1f}%"
        for t in ("paridade", "estreita"):
            c_ = getc(m, t)
            if c_ and "pur_acc" in c_:
                with np.errstate(all="ignore"):
                    pa, pr, pt_ = (float(np.nanmean(c_[k])) if np.isfinite(c_[k]).any() else float("nan") for k in ("pur_acc", "pur_rej", "pur_todos"))
                    au = float(np.nanmean(c_["auc"])) if "auc" in c_ and np.isfinite(c_["auc"]).any() else float("nan")
                E1[(m, t, "pur")] = (pa, pr, pt_, au)
                lin += f"   {100 * pa:5.1f}|{100 * pr:5.1f}|{100 * pt_:5.1f}   {au:7.3f}   "
        rep.log(lin)
    rep.log("   Origem c (rótulo oculto do lago, todas as tarefas) — pureza dos aceitos | todos / AUROC: " + "; ".join(
        f"{m}: " + ", ".join(f"{t[:4]} {100 * np.nanmean(R[(m, t)]['cand']['pur_acc']):.0f}|{100 * np.nanmean(R[(m, t)]['cand']['pur_todos']):.0f}" + (f"/{np.nanmean(R[(m, t)]['cand']['auc']):.2f}" if "auc" in R[(m, t)]["cand"] else "") for t in R11_TAREFAS) for m in ("c_sem", "c_conf", "c_f10", "c_verif")))
    ece_p = {t: [R[(a + "_verif", t)]["cand"].get("ece_p", float("nan")) for a in R11_APPS] for t in ("paridade", "estreita")}
    rep.log("   ECE da P_cal (candidatos com verdade conhecida; T2 e T4; origens a, b, c): " + "; ".join(f"{t}: " + ", ".join(f"{v:.3f}" for v in ece_p[t]) for t in ece_p) + " — uma P_cal calibrada daria ECE ≈ 0 (a calibração usa um conjunto de verificação sintético: ver limites).")
    # E2 ablações
    rep.log(f"E2 ABLAÇÕES do verificador completo ({n_abl} sementes, config e candidatos IGUAIS, sem reajuste): Δ = completo − ablado em pp (>0 = o componente ajuda), média ± EP por origem × tarefa; última coluna = média das 15 células.")
    rep.log(f"{'origem/comp.':<26}" + "".join(f"{t[:9]:>14}" for t in R11_TAREFAS) + f"{'média 15':>12}")
    E2 = {}
    for comp in R11_COMPS:
        gm = []
        for a in R11_APPS:
            lin = f"{a + ' −' + comp + ' ' + R11_NOME_COMP[comp][:14]:<26}"
            for t in R11_TAREFAS:
                c_ = R[(a + "_verif", t)]
                dd = c_["abl_cheio"] - c_["abl"][comp]["acc"]
                E2[(a, comp, t)] = (float(dd.mean()), float(dd.std(ddof=1) / math.sqrt(len(dd))))
                gm.append(dd.mean())
                lin += f"{100 * dd.mean():>+8.2f}±{100 * dd.std(ddof=1) / math.sqrt(len(dd)):<4.1f}"
            rep.log(lin + f"{100 * np.mean(gm[-5:]):>+11.2f}")
        E2[("todas", comp)] = float(np.mean(gm))
        rep.log(f"   → −{comp} ({R11_NOME_COMP[comp]}): média geral {100 * np.mean(gm):+.2f} pp (15 células; descritivo, sem correção, MDE alto com {n_abl} sementes)")
    d_m = {}
    for a in R11_APPS:
        for nome in ("H2", "H3", "H5"):
            est = np.array([P[(f"{nome}_{a}", t)]["media"] for t in R11_TAREFAS])
            se = np.array([P[(f"{nome}_{a}", t)]["sd"] / math.sqrt(P[(f"{nome}_{a}", t)]["n"]) for t in R11_TAREFAS])
            md = meta_dl(est, np.maximum(se, 1e-9))
            d_m[(nome, a)] = (md["re"], md["se_re"], md["I2"])
            rep.log(f"E3 meta-análise (DerSimonian–Laird) de {nome} origem {a} entre as 5 tarefas: efeito aleatório = {100 * md['re']:+.2f} pp IC95%[{100 * (md['re'] - 1.96 * md['se_re']):+.2f},{100 * (md['re'] + 1.96 * md['se_re']):+.2f}], I²={100 * md['I2']:.0f}% (k=5: descrição)")
    sp = np.array(R[("real", "poucos")]["seeds"])
    nn_ = np.array([r10_nlab(s) for s in sp])
    E4 = {}
    lin = "E4 T5 (poucos dados), Δ vs real por nº de rotulados n (8 sementes por n; média pp ± EP): "
    for m in ("aug_mixup", "self_train", "a_verif", "b_verif", "c_verif", "sistema"):
        d_ = R[(m, "poucos")]["acc"] - R[("real", "poucos")]["acc"]
        E4[m] = {int(n): (float(d_[nn_ == n].mean()), float(d_[nn_ == n].std(ddof=1) / math.sqrt(max((nn_ == n).sum(), 1)))) for n in sorted(set(nn_.tolist()))}
        lin += f"\n   {m:<12}" + " | ".join(f"n={n}: {100 * v[0]:+.1f}±{100 * v[1]:.1f}" for n, v in E4[m].items())
    rep.log(lin)
    for t in R11_TAREFAS:
        mp = melhor_pad[t]
        el = comparar_pareado(R[("sistema", t)]["ece"], R[(mp, t)]["ece"], seed=ctx.seed + 11600)
        ll = comparar_pareado(R[("sistema", t)]["loss"], R[(mp, t)]["loss"], seed=ctx.seed + 11601)
        rep.log(f"E5 {t:<9} ECE(sistema) − ECE({mp}) = {el['media']:+.4f} (p={el['p']:.3f}) | perda de teste {ll['media']:+.3f} (p={ll['p']:.3f})")
    rep.log("E6 ranking médio (1 = melhor acurácia média por tarefa) dos 15 métodos: " + ", ".join(f"{m}={np.mean(rank[m]):.1f}" for m in sorted(R11_METODOS, key=lambda m: np.mean(rank[m]))))
    cpu_m = {m: float(np.mean([R[(m, t)]["cpu"] for t in R11_TAREFAS])) for m in R11_METODOS}
    rep.log("E7 CPU média por célula (s; inclui ajuste, avaliação e, nos verif, placebo + ablações; muda com a carga da máquina): " + ", ".join(f"{m}={v:.1f}" for m, v in cpu_m.items()), vol=True)
    E8 = {}
    for t in R11_TAREFAS:
        mo = R[("sistema", t)]["mon"]
        fc = R[("sistema", t)]["cand"].get("frac_c")
        E8[t] = {"gate": float(np.mean([m_.get("gate", np.nan) for m_ in mo])) if mo else float("nan"), "relaxar": float(mo[1].get("relaxar", 0.0)) if len(mo) > 1 else float("nan"),
                 "apertar": float(mo[1].get("apertar", 0.0)) if len(mo) > 1 else float("nan"), "frac_c": float(np.mean(fc)) if fc is not None else float("nan")}
    rep.log("E8 monitores do sistema (nas sementes confirmatórias): " + "; ".join(f"{t}: fontes a/b ligadas em {100 * E8[t]['gate']:.0f}% das redes, relaxar θ em {100 * E8[t]['relaxar']:.0f}%, apertar em {100 * E8[t]['apertar']:.0f}%, fração dos aceitos vinda de c {100 * E8[t]['frac_c']:.0f}%" for t in R11_TAREFAS))
    # ---- laudos
    rep.sub(f"LAUDO DE ESCRUTÍNIO (função `laudo_escrutinio` da R9, sem alteração) — {n_f} sementes FRESCAS {R11_SEM_F + desloc}+, nunca usadas; baseline = melhor PADRÃO por DEV; 2 variantes que só diferem no braço de ablação da V3")
    lk = LakeLeve(ctx.lake)
    jl = r11_jobs_laudo(R, melhor_pad, lk, n_f, desloc)
    t2 = time.time()
    rl = mapa_paralelo(_job_r11_laudo, jl, ctx.jobs)
    rep.log(f"(tempo do laudo: {time.time() - t2:.1f}s)", vol=True)
    LD, MED = {}, {}
    for j, t in enumerate(R11_TAREFAS):
        LD[t], MED[t] = r11_laudos_de(rl[5 * j:5 * j + 5], ctx.seed + 11700 + 100 * j)
        rep.log(f"  {t}: médias frescas — sistema={100 * MED[t]['sis']:.1f}% | {melhor_pad[t]}={100 * MED[t]['pad']:.1f}% | sem verificador (mesma config)={100 * MED[t]['ab_verif']:.1f}% | sem monitores (mesma config)={100 * MED[t]['ab_monitor']:.1f}% | rótulos embaralhados: sistema={100 * MED[t]['sis_shuf']:.1f}%")
        for k in R11_LAUDOS:
            imprimir_laudo(rep, f"{t}: {R11_NOME_L[k]}", LD[t][k])
    nval = {k: [t for t in R11_TAREFAS if LD[t][k]["veredito"] == "VALIDO"] for k in R11_LAUDOS}
    rep.log("→ Laudos VÁLIDOS: " + "; ".join(f"{k}: {len(nval[k])} de 5" + (f" ({', '.join(nval[k])})" if nval[k] else "") for k in R11_LAUDOS) + ". São 10 decisões sem correção de multiplicidade.")
    # ---- regras de decisão
    def contagem(h):
        pos = [(a, t) for a in R11_APPS for t in R11_TAREFAS if st[(f"{h}_{a}", t)] == "confirmada"]
        neg = [(a, t) for a in R11_APPS for t in R11_TAREFAS if st[(f"{h}_{a}", t)].startswith("refutada")]
        return pos, neg
    CT = {h: contagem(h) for h in R11_PROTO_HIPOTESES}
    regra = {"R1": "H2", "R2": "H3", "R3": "H1", "R4": "H4"}
    RR = {r_: (len(CT[h][0]) >= 3 and len(CT[h][0]) > len(CT[h][1])) for r_, h in regra.items()}
    RR["R5"] = len(CT["H5"][0]) >= 1
    H6_pos = [t for t in R11_TAREFAS if st[("H6", t)] == "confirmada"]
    H6_neg = [t for t in R11_TAREFAS if st[("H6", t)].startswith("refutada")]
    r6 = [t for t in H6_pos if LD[t]["L1"]["veredito"] == "VALIDO"]
    RR["R6"] = bool(r6)
    f_ = lambda lst: ", ".join(f"{a}/{t}" for a, t in lst) or "—"
    rep.sub("LEITURA HONESTA E REGRAS DE DECISÃO PRÉ-REGISTRADAS")
    for h, txt in (("H1", "O verificador vs NÃO filtrar"), ("H2", "O verificador vs CONFIANÇA simples do professor"), ("H3", "O verificador vs filtro F1∧F2∧F3 da R10"), ("H4", "O verificador vs aceitação ALEATÓRIA com o mesmo nº (placebo)"), ("H5", "Aumentação filtrada pelo verificador vs o melhor PADRÃO por DEV")):
        pos, neg = CT[h]
        rep.log(f"({h}) {txt}: melhor (confirmada) em {len(pos)} de 15 células [{f_(pos)}]; PIOR em {len(neg)} [{f_(neg)}] (Holm sobre {len(chaves)}).")
    rep.log(f"(H6) SISTEMA vs o melhor padrão por DEV: melhor em {', '.join(H6_pos) or 'nenhuma tarefa'}; PIOR em {', '.join(H6_neg) or 'nenhuma'}. Acurácia média (%) sistema / melhor padrão: " + "; ".join(f"{t}: {100 * np.mean(R[('sistema', t)]['acc']):.1f} / {100 * np.mean(R[(melhor_pad[t], t)]['acc']):.1f} ({melhor_pad[t]})" for t in R11_TAREFAS) + ".")
    rep.log("REGRAS: R1 'o verificador é um filtro melhor que a confiança simples' (H2: ≥ 3 células confirmadas com Δ>0 e mais Δ>0 do que Δ<0) → " + ("ATENDIDA" if RR["R1"] else "NÃO atendida") + " | R2 'melhor que o filtro da R10' (H3) → " + ("ATENDIDA" if RR["R2"] else "NÃO atendida") +
            " | R3 'filtrar candidatos ajuda' (H1) → " + ("ATENDIDA" if RR["R3"] else "NÃO atendida") + " | R4 'o conteúdo do aceito importa, não só a contagem' (H4) → " + ("ATENDIDA" if RR["R4"] else "NÃO atendida") +
            " | R5 'a aumentação filtrada supera o melhor padrão' (H5 em ≥ 1 célula) → " + ("ATENDIDA" if RR["R5"] else "NÃO atendida") + " | R6 'o sistema integrado supera o baseline ajustado' (H6 confirmada E laudo L1 válido na tarefa) → " +
            (f"ATENDIDA em {', '.join(r6)} (leia com as ressalvas dos limites)" if r6 else "NÃO atendida" + (f" (H6 confirmada em {', '.join(H6_pos)}, barrada por laudo: " + "; ".join(f"{t}: L1={LD[t]['L1']['veredito']}" for t in H6_pos) + ")" if H6_pos else " (nenhuma H6 confirmada com Δ>0)")) + ".")
    rep.log("Limites: (i) redes minúsculas, lote completo, 300 passos, 5 tarefas escolhidas por mim; T2 no teto e T3 no limite do rótulo; (ii) 6 sorteios × 3 sementes DEV é ajuste modesto e o verificador/sistema têm 6–7 hiperparâmetros contra 2–4 dos baselines; "
            "(iii) o professor é a própria rede (auto-consistência, não oráculo) e o conjunto de verificação da calibração tem o professor memorizando a base: a P_cal herda esse viés; (iv) o lago não rotulado vem da MESMA distribuição da tarefa (otimista para a recuperação) e em T2 inclui entradas que coincidem com as do teste (só entradas, nunca rótulos); "
            "(v) 'vetores do dicionário' atuam só em T3; (vi) os 'monitores metacognitivos' do sistema são duas regras vetorizadas, não o registro completo da R8; (vii) as 80 hipóteses têm Holm rígido com n=40 e MDE de ~1–3 pp: nulas NÃO provam ausência; "
            "(viii) o placebo (azar) e as ablações herdam a config ajustada do verificador (não são ajustados separadamente): o sentido do viés é INCERTO (a config foi escolhida para o verificador completo, o que pode desfavorecer placebo e ablações; ou ser neutra), logo H4 e as ablações são lidos com essa ressalva; (ix) laudo sem correção de multiplicidade; (x) pré-registro auto-atestado; nada se transfere a redes grandes ou a ASI.")
    rep.log(f"(tempo do bloco 18: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r11_ver"] = {"n_c": n_c, "n_f": n_f, "n_abl": n_abl, "P": {k: (P[k]["media"], P[k]["lo"], P[k]["hi"], P[k]["p"], float(ph[k]), P[k]["mde"]) for k in chaves}, "st": st, "melhor_pad": melhor_pad,
                          "acc": {(m, t): float(R[(m, t)]["acc"].mean()) for m in R11_METODOS for t in R11_TAREFAS}, "rank": {m: float(np.mean(v)) for m, v in rank.items()}, "E1": E1, "E2": E2, "E3": d_m, "E4": E4, "E8": E8,
                          "laudo": {t: {k: {kk: LD[t][k][kk] for kk in ("veredito", "motivos", "shuf")} for k in R11_LAUDOS} for t in R11_TAREFAS}, "laudo_med": MED, "CT": {h: (len(CT[h][0]), len(CT[h][1])) for h in CT},
                          "RR": RR, "H6_pos": H6_pos, "H6_neg": H6_neg, "r6": r6, "nval": nval, "abl_geral": {c: E2[("todas", c)] for c in R11_COMPS},
                          "azar_acc": {(a, t): float(np.mean(R[(a + "_verif", t)]["azar"]["acc"])) for a in R11_APPS for t in R11_TAREFAS}}




