def r12_sorteios(metodo: str, tarefa: str, n: int):
    """n configurações sorteadas (semente = crc32 de método|tarefa, tag 12 — distinta da R11) nas faixas de R12_ESPACO; a lista de n' < n sorteios é prefixo da de n."""
    rng = np.random.default_rng([zlib.crc32((metodo + "|" + tarefa).encode("utf-8")), 12, 3])
    out = []
    for _ in range(n):
        c = {}
        for nome, lo, hi, tipo in R12_ESPACO[metodo]:
            u = rng.random()
            c[nome] = float(math.exp(math.log(lo) + u * (math.log(hi) - math.log(lo)))) if tipo == "log" else float(lo + u * (hi - lo))
        out.append(c)
    return out


def _r12_rs(nome, tarefa, fase, desloc):
    return zlib.crc32(f"R12|{nome}|{tarefa}|{fase}".encode("utf-8")) + desloc


def r12_tost(d, delta, seed: int = 0, n: int = 10000):
    """TOST por permutação de sinais (pareado): H0a: média ≤ −δ e H0b: média ≥ +δ, cada uma testada com as diferenças deslocadas (d+δ e d−δ) e inversão aleatória de sinais; p_TOST = máx dos dois p unicaudais.
    Devolve (p_tost, p_inferior, p_superior). 'Equivalentes' ⇔ p_tost pequeno (rejeita as duas hipóteses de diferença ≥ δ)."""
    d = np.asarray(d, float)
    rng = np.random.default_rng(seed)
    sg = rng.choice([-1.0, 1.0], (n, len(d)))
    obs_lo, obs_hi = (d + delta).mean(), (d - delta).mean()
    p_lo = float((1 + np.sum((sg * (d + delta)).mean(1) >= obs_lo - 1e-15)) / (n + 1))
    p_hi = float((1 + np.sum((sg * (d - delta)).mean(1) <= obs_hi + 1e-15)) / (n + 1))
    return max(p_lo, p_hi), p_lo, p_hi


def _job_r12_celula(args):
    """Uma célula (método × tarefa): ajuste (n_sort sorteios × n_dev sementes DEV; vence a maior acurácia média de teste) → avaliação ÚNICA da config vencedora em n_c sementes novas. Sem placebo nem ablações."""
    metodo, tarefa, lk, n_sort, n_c, desloc = args
    t_cpu = time.process_time()
    n_dev = r10_ndev(tarefa)
    spec = R12_SPEC[metodo]
    sorts = r12_sorteios(metodo, tarefa, n_sort)
    cfgs = [c for c in sorts for _ in range(n_dev)]
    seeds = [R12_SEM_DEV + desloc + j for _ in sorts for j in range(n_dev)]
    d = r11_rodar(spec, tarefa, cfgs, seeds, lk, _r12_rs(metodo, tarefa, 1, desloc))
    sc = d["acc"].reshape(n_sort, n_dev).mean(1)
    best = int(np.argmax(sc))
    sc_c = [R12_SEM_C + desloc + j for j in range(n_c)]
    c = r11_rodar(spec, tarefa, [sorts[best]] * n_c, sc_c, lk, _r12_rs(metodo, tarefa, 2, desloc))
    return {"metodo": metodo, "tarefa": tarefa, "cfg": sorts[best], "dev": sc, "dev_best": float(sc[best]), "dev_med": float(np.median(sc)), "dev_nfin": int((~d["fin"]).sum()),
            "acc": c["acc"], "loss": c["loss"], "ece": c["ece"], "nfin": int((~c["fin"]).sum()), "cand": _r11_cand_stats(c["info"]["est"]), "seeds": sc_c, "cpu": time.process_time() - t_cpu}


def r12_tarefas(ctx):
    """Lista das células do BLOCO 19 (25 = 5 tarefas × 5 métodos; as mais pesadas primeiro). Mesma função para enviar ao segundo plano e para consumir."""
    if "r12_tar" in ctx.res_cache:
        return ctx.res_cache["r12_tar"]
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R12_DEV") else 0
    n_sort, n_c = (3, 16) if rapido else (R12_NSORT, R12_NC)
    lk = LakeLeve(ctx.lake)
    tar = [(m, t, lk if t == "texto" else None, n_sort, n_c, desloc) for t in ("paridade", "estreita", "espirais", "texto", "poucos") for m in ("sistema", "minimo", "aug_mixup", "self_train", "real")]
    ctx.res_cache["r12_tar"] = (_job_r12_celula, tar)
    return ctx.res_cache["r12_tar"]


def r12_hipoteses(R, melhor_pad):
    """(id, tarefa) → (acc_a, acc_b, índice) das 20 confirmatórias: Q1 sistema−minimo, Q2 TOST sistema≈minimo, Q3 minimo−melhor padrão, Q4 sistema−melhor padrão."""
    PA, i_ = {}, 0
    for t in R12_TAREFAS:
        S, Mn, Pd = R[("sistema", t)]["acc"], R[("minimo", t)]["acc"], R[(melhor_pad[t], t)]["acc"]
        for k, a_, b_ in (("Q1", S, Mn), ("Q2", S, Mn), ("Q3", Mn, Pd), ("Q4", S, Pd)):
            i_ += 1
            PA[(k, t)] = (a_, b_, i_)
    return PA


def r12_status(k, media, padj):
    """Veredito de uma confirmatória R12: Q2 = equivalência (TOST); as demais como as das rodadas anteriores (confirmada / refutada (piora) / nula)."""
    if k == "Q2":
        return "equivalentes (TOST ±2 pp)" if padj < 0.05 else "nula (equivalência não demonstrada)"
    return _status7(media, padj)


def r12_regras(st, h6_r11=None):
    """Regras de decisão pré-registradas (P1–P5) e o VEREDITO DE PARCIMÔNIA (mutuamente exclusivo, avaliado nesta ordem), a partir dos vereditos por (hipótese, tarefa)."""
    T = R12_TAREFAS
    pos = lambda k: [t for t in T if st[(k, t)] == "confirmada"]
    neg = lambda k: [t for t in T if st[(k, t)].startswith("refutada")]
    q2 = [t for t in T if st[("Q2", t)].startswith("equivalentes")]
    q1p, q1n, q3p, q4p, q4n = pos("Q1"), neg("Q1"), pos("Q3"), pos("Q4"), neg("Q4")
    h6 = h6_r11 or R12_H6_R11
    rep_t = {t: ((h6[t] == "confirmada" and st[("Q4", t)] == "confirmada") or (h6[t].startswith("refutada") and st[("Q4", t)].startswith("refutada"))) for t in T if h6.get(t, "nula") != "nula"}
    R = {"P1": len(q2) >= 3, "P2_local": len(q1p) >= 1, "P2_geral": len(q1p) >= 3 and not q1n, "P3": len(q1n) >= 1, "P4": len(q3p) >= 1, "P5": rep_t}
    if not q1p and R["P1"]:
        v = "PARCIMÔNIA VENCE"
    elif len(q1p) >= 2 and not q1n:
        v = "O SISTEMA COMPLETO GANHA O LUGAR"
    else:
        v = "MISTO"
    R.update({"veredito": v, "q1p": q1p, "q1n": q1n, "q2": q2, "q3p": q3p, "q3n": neg("Q3"), "q4p": q4p, "q4n": q4n})
    return R


