    ok_p = sha_ok(PREREG_R12_CORPO, PREREG_R12_CORPO_SHA256)
    rep.log(f"Integridade: pré-registro R12 (corpo) {PREREG_R12_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r12.txt, carimbado 19:00 PT, ANTES de qualquer código do método mínimo/BLOCO 19 e de qualquer execução com sementes R12; ' if ok_p else '(NÃO CONFERE!) ('}"
            "carimbo auto-atestado pelo relógio da máquina).")
    if ADENDO1_R12_CORPO_SHA256:
        ok_a = sha_ok(ADENDO1_R12_CORPO, ADENDO1_R12_CORPO_SHA256)
        rep.log(f"Adendo 1 ao pré-registro R12 (grupos do guia, detalhes de implementação e divulgação do que vi nas sementes deslocadas; escrito DEPOIS do código e ANTES da primeira execução com as sementes registradas 12100–12239): {ADENDO1_R12_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r12_adendo1.txt)' if ok_a else '(NÃO CONFERE!)'}")
        for l in ADENDO1_R12_CORPO.split("\n")[1:]:
            if l.startswith("D"):
                rep.log("  " + l.strip()[:260] + ("…" if len(l.strip()) > 260 else ""))
    else:
        rep.log("(Adendo 1 ainda não embutido: execução de desenvolvimento.)")
    if ADENDO2_R12_CORPO_SHA256:
        ok_a2 = sha_ok(ADENDO2_R12_CORPO, ADENDO2_R12_CORPO_SHA256)
        rep.log(f"Adendo 2 ao pré-registro R12 (declaração RETROATIVA do que já rodou com as sementes registradas e do que mudou depois): {ADENDO2_R12_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r12_adendo2.txt)' if ok_a2 else '(NÃO CONFERE!)'}")
        for l in ADENDO2_R12_CORPO.split("\n")[1:]:
            if l.startswith("D"):
                rep.log("  " + l.strip()[:260] + ("…" if len(l.strip()) > 260 else ""))
    if rapido:
        rep.log(f"(--rapido: {n_sort} sorteios e {n_c} confirmatórias — NÃO é a análise pré-registrada de {R12_NSORT}/{R12_NC}.)")
    if desloc:
        rep.log("!! R12_DEV=1: sementes DESLOCADAS em +10000 (depuração). ESTES NÚMEROS NÃO SÃO A ANÁLISE REGISTRADA.")
    rep.sub("Desenho (resumo do pré-registro): o que resistiu à correção de multiplicidade foi quase sempre o FILTRO, não o delírio nem o caos. O sistema INTEGRADO da R11 (3 origens + verificador forte + 2 monitores; 7 hiperparâmetros) é comparado com um sistema MÍNIMO "
            "(n pseudo-rótulos + n recuperados do lago; aceita sse o MÍNIMO da probabilidade do rótulo sobre 3 instantâneos da própria rede ≥ θ_e; peso 0,5; 4 hiperparâmetros) e com o melhor padrão ajustado (real | aug_mixup | self_train), todos com o MESMO orçamento de ajuste. "
            "Q1 sistema−minimo (bicaudal), Q2 equivalência por TOST ±2 pp, Q3 minimo−padrão, Q4 sistema−padrão (replica o R11-H6).")
    fn_c, tar_c = r12_tarefas(ctx)
    t1 = time.time()
    cel = mapa_ou_fundo(ctx, "r12a", fn_c, tar_c)
    rep.log(f"(tempo de espera pelas células: {time.time() - t1:.1f}s, jobs={ctx.jobs})", vol=True)
    R = {(c["metodo"], c["tarefa"]): c for c in cel}
    nfin = sum(c["nfin"] + c["dev_nfin"] for c in cel)
    rep.log(f"Redes com pesos/perdas não finitos nos treinos principais (contadas como acaso, 50%): {nfin} de {sum(n_c + n_sort * r10_ndev(c['tarefa']) for c in cel)}.")
    ms = lambda v: f"{100 * np.mean(v):5.1f}±{100 * np.std(v, ddof=1) / math.sqrt(len(v)):<4.1f}"
    rep.sub(f"ACURÁCIA DE TESTE (%) das {n_c} sementes confirmatórias, média ± erro-padrão [melhor score DEV entre colchetes = otimismo da seleção]")
    rep.log(f"{'método':<12}" + "".join(f"{t:>20}" for t in R12_TAREFAS) + f"{'rank médio':>12}")
    rank = {m: [] for m in R12_METODOS}
    for t in R12_TAREFAS:
        for r_, i in enumerate(np.argsort([-R[(m, t)]["acc"].mean() for m in R12_METODOS], kind="stable"), 1):
            rank[R12_METODOS[i]].append(r_)
    for m in R12_METODOS:
        rep.log(f"{m:<12}" + "".join(f"{ms(R[(m, t)]['acc']):>12} [{100 * R[(m, t)]['dev_best']:4.1f}]" for t in R12_TAREFAS) + f"{np.mean(rank[m]):>12.1f}")
    rep.sub("Configurações vencedoras no DEV (hiperparâmetros ajustados)")
    for t in R12_TAREFAS:
        rep.log(f"  {R10_NOME_T[t]}")
        for m in R12_METODOS:
            rep.log(f"    {m:<12} " + ", ".join(f"{k}={v:.4g}" for k, v in R[(m, t)]["cfg"].items()) + f" | DEV: melhor {100 * R[(m, t)]['dev_best']:.1f}% mediana dos sorteios {100 * R[(m, t)]['dev_med']:.1f}%")
    melhor_pad = {t: max(R12_PADRAO, key=lambda m: (R[(m, t)]["dev_best"], -R12_PADRAO.index(m))) for t in R12_TAREFAS}
    PA = r12_hipoteses(R, melhor_pad)
    P = {}
    for k, (a_, b_, ii) in PA.items():
        cm = comparar_pareado(a_, b_, seed=ctx.seed + 12000 + ii)
        cm["mde"] = mde80(a_ - b_)
        if k[0] == "Q2":
            cm["p"], cm["p_lo"], cm["p_hi"] = r12_tost(a_ - b_, R12_MARGEM, seed=ctx.seed + 12000 + ii)
        P[k] = cm
    chaves = list(P)
    ph = dict(zip(chaves, holm([P[k]["p"] for k in chaves])))
    st = {k: r12_status(k[0], P[k]["media"], ph[k]) for k in chaves}
    rep.sub(f"CONFIRMATÓRIAS ({len(chaves)} = 4 × 5 tarefas; Holm sobre {len(chaves)}; Δ = acc(primeiro) − acc(segundo) em pontos percentuais, >0 favorece o primeiro; bicaudal por permutação de sinais, 10000; Q2 = TOST ±{100 * R12_MARGEM:.1f} pp: p = máx dos dois unicaudais)")
    rep.log(f"{'id':<14}{'comparação':<58}{'Δ (pp)':>9}{'IC95% (pp)':>20}{'p':>9}{'p Holm':>9}{'MDE (pp)':>10}{'v/d':>8}  veredito")
    for k in chaves:
        cm, (h, t) = P[k], k
        nm = R12_DESC[h].format(mp=melhor_pad[t])
        rep.log(f"{h + '(' + t + ')':<14}{nm[:57]:<58}{100 * cm['media']:>+9.2f}{'[' + format(100 * cm['lo'], '+.2f') + ',' + format(100 * cm['hi'], '+.2f') + ']':>20}{cm['p']:>9.4f}{ph[k]:>9.4f}{100 * cm['mde']:>10.2f}{str(cm['vit']) + '/' + str(cm['der']):>8}  {st[k]}")
    # ---- exploratórias
    rep.sub("EXPLORATÓRIAS (fora do Holm; sem correção) e descritivos")
    d_pool = np.mean([R[("sistema", t)]["acc"] - R[("minimo", t)]["acc"] for t in R12_TAREFAS], axis=0)
    E1 = {}
    lin = f"E1 TOST AGREGADO sistema×minimo (média das 5 tarefas por semente pareada; Δ médio {100 * d_pool.mean():+.2f} pp, EP {100 * d_pool.std(ddof=1) / math.sqrt(len(d_pool)):.2f}): "
    for mg in (0.01, 0.02, 0.03):
        pt_, _, _ = r12_tost(d_pool, mg, seed=ctx.seed + 12500)
        E1[mg] = pt_
        lin += f"margem ±{100 * mg:.0f} pp p_TOST={pt_:.4f} ({'equivalentes' if pt_ < 0.05 else 'não demonstrada'}); "
    rep.log(lin + "(3 testes sem correção; descritivo)")
    rank_t = ", ".join(f"{m}={np.mean(rank[m]):.1f}" for m in sorted(R12_METODOS, key=lambda m: np.mean(rank[m])))
    rep.log("E2 ranking médio (1 = melhor acurácia média por tarefa) dos 5 métodos: " + rank_t)
    E3 = {}
    for m in ("self_train", "minimo", "sistema"):
        tx = [float(np.mean(R[(m, t)]["cand"]["taxa"])) if R[(m, t)]["cand"] else float("nan") for t in R12_TAREFAS]
        E3[m] = tx
    rep.log("E3 taxa de ACEITAÇÃO de candidatos (média sobre redes e ciclos), por tarefa (" + ", ".join(R12_TAREFAS) + "): " + " | ".join(f"{m}: " + " ".join(f"{100 * x:.0f}%" for x in v) for m, v in E3.items()))
    sp = np.array(R[("real", "poucos")]["seeds"])
    nn_ = np.array([r10_nlab(s) for s in sp])
    E4 = {}
    lin = "E4 T5 (poucos dados), Δ vs real por nº de rotulados n (média pp ± EP): "
    for m in ("aug_mixup", "self_train", "minimo", "sistema"):
        d_ = R[(m, "poucos")]["acc"] - R[("real", "poucos")]["acc"]
        E4[m] = {int(n): (float(d_[nn_ == n].mean()), float(d_[nn_ == n].std(ddof=1) / math.sqrt(max((nn_ == n).sum(), 1)))) for n in sorted(set(nn_.tolist()))}
        lin += f"\n   {m:<12}" + " | ".join(f"n={n}: {100 * v[0]:+.1f}±{100 * v[1]:.1f}" for n, v in E4[m].items())
    rep.log(lin)
    cpu_m = {m: float(np.sum([R[(m, t)]["cpu"] for t in R12_TAREFAS])) for m in R12_METODOS}
    rep.log("E5 CPU por método (s; soma das 5 tarefas = ajuste + avaliação; volátil, muda com a carga da máquina): " + ", ".join(f"{m}={v:.1f}" for m, v in cpu_m.items()), vol=True)
    mdes = {k: P[k]["mde"] for k in chaves}
    rep.log("E6 poder: MDE80 por teste (pp): " + "; ".join(f"{h}: " + ", ".join(f"{100 * mdes[(h, t)]:.2f}" for t in R12_TAREFAS) for h in R12_HIPOT) + f" (ordem das tarefas: {', '.join(R12_TAREFAS)}; a margem de equivalência é {100 * R12_MARGEM:.1f} pp)")
    dev_vs = {m: float(np.mean([R[(m, t)]["dev_best"] - R[(m, t)]["acc"].mean() for t in R12_TAREFAS])) for m in R12_METODOS}
    rep.log("E7 otimismo da seleção no DEV (score DEV do vencedor − acurácia confirmatória, média das 5 tarefas, pp): " + ", ".join(f"{m}={100 * v:+.2f}" for m, v in dev_vs.items()))
    # ---- regras de decisão
    h6 = None
    nn11 = ctx.res.get("r11_ver")
    if nn11 and "st" in nn11:
        h6 = {t: nn11["st"][("H6", t)] for t in R12_TAREFAS}
    RG = r12_regras(st, h6)
    f_ = lambda lst: ", ".join(lst) or "nenhuma tarefa"
    rep.sub("LEITURA HONESTA E REGRAS DE DECISÃO PRÉ-REGISTRADAS")
    rep.log(f"(Q1) sistema vs mínimo: sistema MELHOR em {f_(RG['q1p'])}; sistema PIOR em {f_(RG['q1n'])}. Acurácia média (%) sistema / mínimo: " + "; ".join(f"{t}: {100 * np.mean(R[('sistema', t)]['acc']):.1f} / {100 * np.mean(R[('minimo', t)]['acc']):.1f}" for t in R12_TAREFAS) + ".")
    rep.log(f"(Q2) EQUIVALÊNCIA sistema ≈ mínimo (±{100 * R12_MARGEM:.1f} pp) demonstrada em {f_(RG['q2'])} ({len(RG['q2'])} de 5).")
    rep.log(f"(Q3) mínimo vs melhor padrão por DEV: mínimo MELHOR em {f_(RG['q3p'])}; PIOR em {f_(RG['q3n'])}. Acurácia média (%) mínimo / melhor padrão: " + "; ".join(f"{t}: {100 * np.mean(R[('minimo', t)]['acc']):.1f} / {100 * np.mean(R[(melhor_pad[t], t)]['acc']):.1f} ({melhor_pad[t]})" for t in R12_TAREFAS) + ".")
    rep.log(f"(Q4) sistema vs melhor padrão (replicação do R11-H6): sistema MELHOR em {f_(RG['q4p'])}; PIOR em {f_(RG['q4n'])}. Replicação por tarefa (mesmo veredito do R11-H6, onde ele foi confirmado/refutado): " + (", ".join(f"{t}: {'REPLICOU' if v else 'NÃO replicou'}" for t, v in RG["P5"].items()) or "n/d") + ".")
    rep.log(f"REGRAS: P1 'equivalência na maioria' (Q2 em ≥ 3 tarefas) → {'ATENDIDA' if RG['P1'] else 'NÃO atendida'} | P2 'o sistema integrado tem vantagem sobre o mínimo' → localizada {'SIM' if RG['P2_local'] else 'NÃO'} / geral {'SIM' if RG['P2_geral'] else 'NÃO'} | "
            f"P3 'o mínimo supera o sistema' (Q1 com Δ<0 em ≥ 1 tarefa) → {'ATENDIDA' if RG['P3'] else 'NÃO atendida'} | P4 'o filtro de comitê + fontes simples ganha o lugar sobre o padrão' (Q3 Δ>0 em ≥ 1 tarefa) → {'ATENDIDA' if RG['P4'] else 'NÃO atendida'} | "
            f"P5 replicação → {sum(RG['P5'].values())} de {len(RG['P5'])} tarefas.")
    rep.log(f"VEREDITO DE PARCIMÔNIA (pré-registrado, mutuamente exclusivo): {RG['veredito']}.")
    rep.log("Limites: (i) o 'mínimo' é UM sistema mínimo entre muitos (comitê de instantâneos da própria rede; fontes b+c); outro mínimo poderia dar outro resultado; (ii) 6 sorteios × 3 sementes DEV é ajuste modesto e favorece métodos com poucos hiperparâmetros (mínimo 4, sistema 7); "
            "(iii) a margem ±2 pp é escolha minha e T2 (paridade) está no teto de 100% com 'real', o que torna Q2 trivial ali; (iv) mesmas 5 tarefas minúsculas escolhidas por mim; (v) o professor é a própria rede; (vi) nada disto se transfere a redes grandes ou dados reais; "
            "(vii) 20 confirmatórias com n=40: o MDE80 por teste está em E6 — 'nula' nunca prova ausência de efeito.")
    rep.log(f"(tempo do bloco 19: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r12_par"] = {"n_c": n_c, "P": {k: (P[k]["media"], P[k]["lo"], P[k]["hi"], P[k]["p"], float(ph[k]), P[k]["mde"]) for k in chaves}, "st": st, "melhor_pad": melhor_pad,
                          "acc": {(m, t): float(R[(m, t)]["acc"].mean()) for m in R12_METODOS for t in R12_TAREFAS}, "cpu": {(m, t): float(R[(m, t)]["cpu"]) for m in R12_METODOS for t in R12_TAREFAS},
                          "rank": {m: float(np.mean(v)) for m, v in rank.items()}, "E1": E1, "E3": E3, "E4": E4, "RG": RG, "cpu_m": cpu_m, "dev_vs": dev_vs,
                          "d_pool": (float(d_pool.mean()), float(d_pool.std(ddof=1) / math.sqrt(len(d_pool))))}


