# grupos cujo componente está DENTRO do sistema integrado e, portanto, tem um braço correspondente no teste de parcimônia (Q1: o sistema supera o mínimo, que não os tem)
R12_BRACO = ("sistema", "delirio_generativo", "caos", "verificador")


def r12_grupo_de(i: str) -> str:
    for gid, _, pref in GRUPOS_R12:
        if i.startswith(pref):
            return gid
    return "outros"


def r12_classificar(linhas, tabela):
    """Classifica cada confirmatória com p bruto (regra pré-registrada): a_favor (Holm global < 0,05 e veredito 'confirmada'), contra (Holm global < 0,05 e 'refutada'), equivalência (Holm global < 0,05 e TOST), so_local_favor/so_local_contra
    (veredito 'confirmada'/'refutada' do registro, mas Holm global ≥ 0,05), outro_sobrevive (Holm global < 0,05 sem direção) e aberta (o resto). `tabela` = [(id, p, p Holm global, q BH global)]. Devolve {id: dict}."""
    reg = {x[1]: x for x in linhas if x[2] == "CONF"}
    out = {}
    for i, p, h, q in tabela:
        x = reg.get(i)
        stt = x[5] if x else "n/d"
        cl = _classe_status(stt)
        if stt.startswith("equivalentes") and h < 0.05:
            cat = "equivalencia"
        elif cl == "confirmada" and h < 0.05:
            cat = "a_favor"
        elif cl == "refutada" and h < 0.05:
            cat = "contra"
        elif cl == "confirmada":
            cat = "so_local_favor"
        elif cl == "refutada":
            cat = "so_local_contra"
        elif h < 0.05:
            cat = "outro_sobrevive"
        else:
            cat = "aberta"
        out[i] = {"cat": cat, "p": p, "holm": h, "bh": q, "status": stt, "grupo": r12_grupo_de(i)}
    return out


CATS_R12 = ("a_favor", "contra", "equivalencia", "so_local_favor", "so_local_contra", "outro_sobrevive", "aberta")


def r12_contar(cl):
    """{grupo: {cat: n, 'n': total, 'bh_favor': nº a favor também no BH, ids por categoria}}."""
    G = {}
    for i, d in cl.items():
        g = G.setdefault(d["grupo"], {**{c: 0 for c in CATS_R12}, "n": 0, "bh_favor": 0, "ids": {c: [] for c in CATS_R12}})
        g[d["cat"]] += 1
        g["n"] += 1
        g["ids"][d["cat"]].append(i)
        if d["cat"] == "a_favor" and d["bh"] < 0.05:
            g["bh_favor"] += 1
    return G


def r12_decisao(g, falha_parcimonia=None):
    """Regra do guia (pré-registrada): MANTER = ≥ 1 sobrevivente a favor e a favor > contra; CANDIDATO À REMOÇÃO = 0 a favor e ≥ 1 contra E (sem braço de parcimônia correspondente OU o grupo falha no teste de parcimônia);
    DORMENTE = os demais casos com testes; SEM EVIDÊNCIA = nenhum teste confirmatório. `falha_parcimonia`: None = sem braço correspondente; True/False = o grupo falha/passa no teste."""
    if g is None or g["n"] == 0:
        return "SEM EVIDÊNCIA (não decidido)"
    if g["a_favor"] >= 1 and g["a_favor"] > g["contra"]:
        return "MANTER"
    if g["a_favor"] == 0 and g["contra"] >= 1 and falha_parcimonia is not False:
        return "CANDIDATO À REMOÇÃO (dormente)"
    return "DORMENTE"


_AST_CACHE_R35 = {}


def _ast_fonte_r35(src):
    """[R35] ast.parse com cache por conteúdo (o autoteste analisa o próprio arquivo mais de uma vez)."""
    k_ = (len(src), hash(src))
    if k_ not in _AST_CACHE_R35:
        _AST_CACHE_R35[k_] = ast.parse(src)
    return _AST_CACHE_R35[k_]


def r12_loc_funcoes(nomes):
    """Linhas de código (não vazias e fora de comentários puros) das funções/classes de nível superior NOMEADAS no próprio arquivo-fonte. Devolve (total, nomes ausentes) ou (None, nomes) se a fonte não estiver disponível."""
    try:
        with open(os.path.abspath(__file__), encoding="utf-8") as f:
            src = f.read()
    except OSError:
        return None, list(nomes)
    L = src.split("\n")
    tot, falt = 0, []
    achados = {n.name: n for n in _ast_fonte_r35(src).body if isinstance(n, (ast.FunctionDef, ast.ClassDef))}
    for nome in nomes:
        n = achados.get(nome)
        if n is None:
            falt.append(nome)
            continue
        tot += sum(1 for l in L[n.lineno - 1:n.end_lineno] if l.strip() and not l.strip().startswith("#"))
    return tot, falt


