_R12_CONG_CACHE: dict = {}


def r12_congelado():
    """Decodifica (uma vez) os resultados congelados {bloco: {'res': {...}, 'linhas': [(texto, volátil)]}}; None se o sha256 do conteúdo não conferir."""
    if "v" in _R12_CONG_CACHE:
        return _R12_CONG_CACHE["v"]
    try:
        raw = zlib.decompress(base64.b64decode(R12_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R12_CONGELADO_SHA256 else None
    except Exception:  # noqa: BLE001
        v = None
    _R12_CONG_CACHE["v"] = v
    return v


def r12_dormente_ativo(args, nome: str) -> bool:
    """True se o bloco deve ser REPRODUZIDO do congelado: execução padrão (semente 42, --offline, embedding semântico, sem --rapido, sem modos/deslocamentos de desenvolvimento) e sem pedido de reativação."""
    if os.environ.get("R12_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if any(os.environ.get(v) for v in R12_ENV_VIVO):
        return False
    cg = r12_congelado()
    return cg is not None and nome in cg


def _dormente(nome, vivo):
    def w(ctx):
        rot = R12_DORMENTES[nome]
        est = ctx.res.setdefault("r12_dorm", {})
        if r12_dormente_ativo(ctx.args, nome):
            cg = r12_congelado()[nome]
            ctx.rep.log(f"[R12 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R11 inalterado (--offline --jobs 8, semente 42, DIGEST R11 {R12_CONGELADO_ORIGEM}); sha256 do conteúdo {R12_CONGELADO_SHA256[:12]}… CONFERE. "
                        "As linhas abaixo são a reprodução fiel do relatório daquela execução (tempos = daquela execução). Para recalcular e conferir: --reativar-dormentes ou R12_REATIVAR=1.")
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r12_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R12 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    return w


bloco15 = _dormente("bloco15", bloco15)
bloco16 = _dormente("bloco16", bloco16)
bloco17 = _dormente("bloco17", bloco17)


def _t_registro_r12_sintetico() -> bool:
    """Autoteste: o registro da R12 tem 20 confirmatórias com ids únicos e formato certo, com resultados sintéticos."""
    class _C:
        pass
    c = _C()
    ks = [(h, t) for t in R12_TAREFAS for h in R12_HIPOT]
    P = {k: (0.01, -0.01, 0.03, 0.2, 0.9, 0.02) for k in ks}
    st = {k: ("nula (equivalência não demonstrada)" if k[0] == "Q2" else "nula") for k in ks}
    RG = r12_regras(st)
    c.res = {"r12_par": {"n_c": 40, "P": P, "st": st, "melhor_pad": {t: "real" for t in R12_TAREFAS}, "E1": {0.01: 0.5, 0.02: 0.3, 0.03: 0.1}, "RG": RG}, "r12_dorm": {"x": "dormente"}}
    rows = registro_r12(c)
    conf = [x for x in rows if x[2] == "CONF"]
    return len(conf) == 20 and len({x[1] for x in rows}) == len(rows) and all(len(x) == 6 for x in rows) and all(x[1].startswith("R12-") for x in rows)


def _autoteste_r12(t, lk, ant):
    """[R12] Invariantes do BLOCO 19 (método mínimo, filtro de comitê, TOST, regras de parcimônia, síntese/guia, Pareto, dormência verificada, registro, melhorias). `t(nome, cond)` registra; `ant` = sementes de rodadas anteriores."""
    t("R12: pré-registro (corpo) confere com o sha256 embutido" + ("; adendo 1 idem" if ADENDO1_R12_CORPO_SHA256 else "") + ("; adendo 2 idem" if ADENDO2_R12_CORPO_SHA256 else ""), sha_ok(PREREG_R12_CORPO, PREREG_R12_CORPO_SHA256)and (not ADENDO2_R12_CORPO_SHA256 or sha_ok(ADENDO2_R12_CORPO, ADENDO2_R12_CORPO_SHA256)) and (not ADENDO1_R12_CORPO_SHA256 or sha_ok(ADENDO1_R12_CORPO, ADENDO1_R12_CORPO_SHA256)))
    try:
        _ft = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "versoes", "prereg_r12.txt"), encoding="utf-8").read()
        t("R12: versoes/prereg_r12.txt contém o corpo embutido e o seu sha256 no rodapé", PREREG_R12_CORPO in _ft and PREREG_R12_CORPO_SHA256 in _ft)
    except OSError:
        t("R12: versoes/prereg_r12.txt contém o corpo embutido e o seu sha256 no rodapé", True)
    t("R12: versão = R12 (ou posterior)", VERSAO in ("R12", "R13", "R14", "R15", "R16", "R17", "R18", "R19", "R20", "R21", "R22", "R23", "R24", "R25", "R26", "R27", "R28", "R29", "R30", "R31", "R32", "R33", "R34", "R35", "R36", "R37"))
    _s = [set(range(R12_SEM_DEV, R12_SEM_DEV + 5)), set(range(R12_SEM_C, R12_SEM_C + R12_NC))]
    _u = set().union(*_s)
    _r11 = set(range(R11_SEM_DEV, R11_SEM_DEV + 5)) | set(range(R11_SEM_C, R11_SEM_C + R11_NC)) | set(range(R11_SEM_F, R11_SEM_F + R11_NF))
    _ant = ant | _r11 | {x + 10000 for x in _r11}
    t("R12: sementes DEV/confirmatórias disjuntas entre si e de TODAS as rodadas anteriores (inclusive deslocamentos de depuração); ≥ 40 novas no confirmatório; o deslocamento de depuração (+10000) não colide",
      sum(len(x) for x in _s) == len(_u) and not (_u & _ant) and R12_NC >= 40 and not ({x + 10000 for x in _u} & (_u | _ant)))
    t("R12: família confirmatória = 4 hipóteses × 5 tarefas = 20; 5 métodos com espaço de busca e especificação; o mínimo tem 4 hiperparâmetros e o sistema 7; sorteios R12 independentes dos da R11 (tag distinta)",
      len(R12_HIPOT) * len(R12_TAREFAS) == 20 and set(R12_METODOS) == set(R12_SPEC) == set(R12_ESPACO) and len(R12_ESPACO["minimo"]) == 4 and len(R12_ESPACO["sistema"]) == 7
      and r12_sorteios("real", "espirais", 3)[0] != r11_sorteios("real", "espirais", 3)[0] and r12_sorteios("minimo", "texto", 2) == r12_sorteios("minimo", "texto", 6)[:2])
    _sm = r12_sorteios("minimo", "espirais", 50)
    t("R12: sorteios do mínimo dentro das faixas (lr, wd, σ em log; θ_e linear em [0,55; 0,95])", all(1e-3 <= c["lr"] <= 5e-2 and 1e-6 <= c["wd"] <= 1e-2 and 0.02 <= c["sig"] <= 0.6 and 0.55 <= c["the"] <= 0.95 for c in _sm))
    # --- TOST
    _g = np.random.default_rng(3)
    _z0 = _g.standard_normal(40); _d0 = 0.002 + 0.004 * (_z0 - _z0.mean())
    _z1 = _g.standard_normal(40); _d1 = 0.02 + 0.004 * (_z1 - _z1.mean())
    _z2 = _g.standard_normal(40); _d2 = 0.15 * (_z2 - _z2.mean())
    _a, _b, _c = r12_tost(_d0, 0.02, 1), r12_tost(_d1, 0.02, 1), r12_tost(_d2, 0.02, 1)
    t("R12: TOST por permutação — diferenças minúsculas ⇒ equivalentes (p<0,001); diferença igual à margem ⇒ NÃO equivalentes (p_sup alto); ruído grande ⇒ não demonstrada; p_TOST = máx dos dois unicaudais; simétrico em d → −d",
      _a[0] < 0.001 and _b[0] > 0.3 and _c[0] > 0.05 and abs(_a[0] - max(_a[1], _a[2])) < 1e-12 and abs(r12_tost(-_d0, 0.02, 1)[0] - _a[0]) < 0.02)
    # --- candidatos 'm', filtro 'ens' (mini-lote real, como no autoteste da R11)
    _Xt, _yt, _mt, _, _ = r10_dados_lote("poucos", [10200, 10204, 10201], None)
    _Xt32, _yt32, _mt32 = _Xt.astype(np.float32), _yt.astype(np.float32), _mt.astype(np.float32)
    _nkt = _mt32.sum(1).astype(int)
    _Kt, _Nt, _dt = _Xt32.shape
    _dims = [_dt, 8, 1]
    _rw = np.random.default_rng(2)
    _Wq = [(_rw.standard_normal((_Kt, a, b)) * 0.6).astype(np.float32) for a, b in zip(_dims[:-1], _dims[1:])]
