def r13_fatorial():
    """16 braços do fatorial fracionado 2^(7−3), resolução IV: A, N, V, W em todas as combinações; K = A·N·V, M = N·V·W, E = A·V·W (produtos de ±1). Devolve [(índice, braço (str de letras ligadas), {comp: ±1})]."""
    out = []
    for i in range(16):
        a, n, v, w = (1 if (i >> b) & 1 else -1 for b in range(4))
        niv = {"A": a, "N": n, "V": v, "W": w, "K": a * n * v, "M": n * v * w, "E": a * v * w}
        out.append((i, "".join(c for c in R13_COMP if niv[c] > 0), niv))
    return out


R13_FATORIAL = r13_fatorial()


def r13_canonico(arm: str) -> str:
    """Braço CANÔNICO: interruptores inertes desligados (V, M, E sem A nem N; K sem A nem W), letras na ordem de R13_COMP."""
    s = set(arm)
    if not (("A" in s) or ("N" in s)):
        s -= {"V", "M", "E"}
    if not (("A" in s) or ("W" in s)):
        s -= {"K"}
    return "".join(c for c in R13_COMP if c in s)


# ----------------------------------------------------------------------
# Tarefas NOVAS do meta-teste do guia (definidas no pré-registro ANTES de qualquer resultado)
# ----------------------------------------------------------------------
def r13_gerar(tarefa: str, rng, m: int, ruido: bool):
    if tarefa == "xor3":
        X = rng.standard_normal((m, 6))
        y = (X[:, 0] * X[:, 1] * X[:, 2] > 0).astype(float)
    elif tarefa == "tabuleiro":
        X = rng.uniform(-1, 1, (m, 2)) * 1.5
        c = np.floor((X / 1.5 + 1.0) / 0.4).astype(int)
        y = ((c[:, 0] + c[:, 1]) % 2 == 0).astype(float)
    else:
        raise ValueError(tarefa)
    if ruido:
        y = np.where(rng.random(m) < 0.05, 1.0 - y, y)
    return X, y


def r13_dados(tarefa: str, seed: int):
    """((Xtr, ytr), (Xte, yte)) das tarefas novas: xor3 (n=150) e tabuleiro (n=200); 5% dos rótulos de TREINO invertidos; teste (600) limpo. RNG [semente, 13, 1]."""
    rng = np.random.default_rng([seed, 13, 1])
    n = 150 if tarefa == "xor3" else 200
    Xtr, ytr = r13_gerar(tarefa, rng, n, True)
    Xte, yte = r13_gerar(tarefa, rng, 600, False)
    return (Xtr, ytr), (Xte, yte)


def r13_lago(tarefa: str, seed: int, n: int):
    """Lago NÃO ROTULADO (6n pontos da mesma distribuição; rótulo oculto sem ruído) das tarefas novas. RNG [semente, 13, 2]."""
    rng = np.random.default_rng([seed, 13, 2])
    return r13_gerar(tarefa, rng, R11_LAGO * n, False)


# ----------------------------------------------------------------------
# Controle caótico (K) e treinador configurável por interruptores (A N V W K M E)
# ----------------------------------------------------------------------
def r13_lorenz_embaralhado(L: int, seeds):
    """Mesmo fluxo de Lorenz de `r10_lorenz_lote`, EMBARALHADO no tempo (permutação por semente): mesma distribuição marginal, estrutura caótica destruída (controle da R9/R10)."""
    base = r10_lorenz_lote(L, seeds)
    return np.stack([base[i][np.random.default_rng(int(s) + 777).permutation(L)] for i, s in enumerate(seeds)])


def r13_treinar_lote(arm, tarefa, X, y, mr, cfgs, seeds, passos: int, ruido_seed: int, lago=None):
    """Treina K redes em paralelo com os componentes do braço `arm` ligados (ver o pré-registro R13). Sem interruptores = treino 'real' (R10); {N} ≡ R12 'minimo'; {A,N,V,K,M} ≡ R11 'sistema' (BIT A BIT, conferido no autoteste).
    Cópia fiel de `r11_treinar_lote` com: fonte nenhuma/A/N/A+N, filtro verif|ens, K (fluxo embaralhado), W (delírio nos pesos com saída forçada, adaptado da R9), M (monitores em qualquer fonte; o limiar relaxado é θ_v ou θ_e) e E (memória do ciclo 0 no ciclo 1)."""
    arm = r13_canonico(arm)
    if arm == "":
        return r10_treinar_lote(R10_SPEC["real"], tarefa, X, y, mr, cfgs, seeds, passos, ruido_seed)
    A_, N_, V_, W_, K_, M_, E_ = (c in arm for c in R13_COMP)
    app = "s" if (A_ and N_) else ("a" if A_ else ("m" if N_ else None))
    fonte = app is not None
    f32 = np.float32
    ocultas = R10_ARQ[tarefa]
    K, N, d = X.shape
    dims = [d] + list(ocultas) + [1]
    W = [np.empty((K, a, b), f32) for a, b in zip(dims[:-1], dims[1:])]
    B = [np.zeros((K, 1, b), f32) for b in dims[1:]]
    for k, s in enumerate(seeds):
        r = np.random.default_rng([s, 10, 2])
        for i, (a, b) in enumerate(zip(dims[:-1], dims[1:])):
            W[i][k] = (r.standard_normal((a, b)) * math.sqrt(1.0 / a)).astype(f32)
    X, y, mr = X.astype(f32), y.astype(f32), mr.astype(f32)
    nk = mr.sum(1).astype(int)
    gc = lambda nome, pad=0.0: np.array([c.get(nome, pad) for c in cfgs], float)
    lr, wd = gc("lr").astype(f32), gc("wd").astype(f32)
    M = 2 * N
    mu_x = (X * mr[:, :, None]).sum(1, keepdims=True) / nk[:, None, None]
    sdx = (np.sqrt((((X - mu_x) ** 2) * mr[:, :, None]).sum(1, keepdims=True) / nk[:, None, None]) + f32(1e-3)).astype(f32)
    _, dnn = r10_knn(X, X, mr, 1, excluir_si=True)
    nnmed = np.nanmedian(np.where(mr > 0, dnn[:, :, 0], np.nan), axis=1).astype(f32)
    usa_verif = bool(V_ and fonte)
    spec = dict(app=app, filtro=("verif" if usa_verif else "ens"), abl=())
    ref_d5 = None
    if usa_verif:
        _, d5r = r11_knn(X, X, mr, 5, excluir_si=True)
        ref_d5 = d5r.max(2)
    nmem = 2 if E_ else 1
    Xall = np.zeros((K, N + nmem * M, d), f32)
    Yall = np.zeros((K, N + nmem * M, 1), f32)
    Wall = np.zeros((K, N + nmem * M, 1), f32)
    Xall[:, :N], Yall[:, :N, 0], Wall[:, :N, 0] = X, y, mr
    P = W + B
    Mm = [np.zeros_like(p) for p in P]
    Vv = [np.zeros_like(p) for p in P]
    sh3 = lambda v: v[:, None, None]
    pool_on, mem_on = False, False
    info = {"est": [], "mon": []}
    snaps_t = {}
    ciclos = {R10_S1: 0, R10_S2: 1} if fonte else {}
    guardar = {s - 60: s for s in ciclos} | {s - 30: s for s in ciclos}
    tx0 = None
    fluxo = r10_lorenz_lote if K_ else r13_lorenz_embaralhado
    if W_:
        caos = [fluxo_caos(passos, int(s) + 17) for s in seeds]
        if not K_:
            caos = [c[np.random.default_rng(int(s) + 99).permutation(len(c))] for c, s in zip(caos, seeds)]
        CAOS = np.stack(caos)
        Tw, frac = gc("Tw"), gc("frac", 0.5)
        Lc = max(passos // R9_CICLOS_DEL, 1)
        rngw = np.random.default_rng([ruido_seed, 13, 4])
        EMA = [p.copy() for p in P]
        desvio = lambda w: w.reshape(K, -1).std(1) + f32(1e-3)
    with np.errstate(all="ignore"):
        for t in range(passos):
            if t in guardar:
                snaps_t[t] = ([w.copy() for w in W], [b.copy() for b in B])
            if t in ciclos:
                c = ciclos[t]
                snaps = [snaps_t[t - 60], snaps_t[t - 30], (W, B)]
                gate = None
                thv = gc("thv") if (usa_verif and "thv" in cfgs[0]) else None
                the_ = gc("the") if ((not usa_verif) and "the" in cfgs[0]) else None
                mon = {}
                if M_ or app == "s":
                    pr = r10_prever(W, B, X)
                    acc_tr = (((pr > 0.5) == (y > 0.5)) * mr).sum(1) / nk
                    gate = (acc_tr >= R11_GATE) if M_ else np.ones(K, bool)
                    mon["gate"] = gate.mean()
                    if M_ and c == 1 and tx0 is not None:
                        if usa_verif:
                            thv = np.clip(thv - R11_RELAX * (tx0 < R11_TX_BAIXA) + R11_APERTA * (tx0 > R11_TX_ALTA), 0.5, 0.99)
                        else:
                            the_ = np.clip(the_ - R11_RELAX * (tx0 < R11_TX_BAIXA) + R11_APERTA * (tx0 > R11_TX_ALTA), 0.5, 0.99)
                        mon["relaxar"], mon["apertar"] = float((tx0 < R11_TX_BAIXA).mean()), float((tx0 > R11_TX_ALTA).mean())
                xc, yc, valido, src, pt, ytc = r11_candidatos(app, c, W, B, X, y, mr, nk, sdx, cfgs, seeds, ruido_seed, d, lago, gate if app == "s" else None, fluxo=fluxo)
                if gate is not None and app == "a":
                    valido = valido & gate[:, None]
                elif gate is not None and app == "m":
                    valido = valido & ~((src == 1) & ~gate[:, None])
                cfg_ac = cfgs if (usa_verif or the_ is None or not (M_ and c == 1 and tx0 is not None)) else [dict(c_, the=float(v)) for c_, v in zip(cfgs, the_)]
                acc, peso, escore, vi = r11_aceitar(spec, c, cfg_ac, W, B, snaps, xc, yc, valido, src, pt, X, y, mr, nk, nnmed, ref_d5, ruido_seed, seeds, thv)
                if E_ and c == 1:
                    Xall[:, N + M:], Yall[:, N + M:], Wall[:, N + M:] = Xall[:, N:N + M].copy(), Yall[:, N:N + M].copy(), Wall[:, N:N + M].copy()
                    mem_on = True
                Xall[:, N:N + M], Yall[:, N:N + M, 0], Wall[:, N:N + M, 0] = xc, yc, peso
                tx0 = acc.sum(1) / np.maximum(valido.sum(1), 1)
                est = r11_ciclo_est(tarefa, app, xc, yc, valido, acc, src, ytc, escore)
                if app == "s":
                    est["frac_c"] = ((src == 2) & acc).sum(1) / np.maximum(acc.sum(1), 1)
                info["est"].append(est)
                info["mon"].append(mon)
                pool_on = True
            n_use = N + (M if pool_on else 0) + (M if mem_on else 0)
            Wt = Wall[:, :n_use]
            Wt = Wt / Wt.sum(1, keepdims=True)
            env = 0.05 + 0.95 * 0.5 * (1.0 + math.cos(math.pi * t / passos))
            gW, gb = r10_fb(W, B, Xall[:, :n_use], Yall[:, :n_use], Wt)
            gW = [g + sh3(wd) * w for g, w in zip(gW, W)]
            G = gW + gb
            nrm = np.sqrt(sum((g * g).reshape(K, -1).sum(1) for g in G))
            esc = sh3(np.minimum(f32(1.0), f32(5.0) / (nrm + f32(1e-12))))
            bc1, bc2 = 1 - 0.9 ** (t + 1), 1 - 0.999 ** (t + 1)
            if W_:
                ci, pos = divmod(t, Lc)
                em_del = pos < frac * Lc
                prog = np.clip((pos - frac * Lc) / np.maximum((1 - frac) * Lc, 1), 0, 1)
                mult = np.where(em_del, 3.0, 1.0 - 0.7 * prog).astype(f32)
                lrt = sh3((lr * f32(env) * mult).astype(f32))
            else:
                lrt = sh3((lr * f32(env)).astype(f32))
            for j, (pp, g) in enumerate(zip(P, G)):
                g = g * esc
                Mm[j] *= f32(0.9)
                Mm[j] += f32(0.1) * g
                Vv[j] *= f32(0.999)
                Vv[j] += f32(0.001) * g * g
                pp -= lrt * (Mm[j] / f32(bc1)) / (np.sqrt(Vv[j] / f32(bc2)) + f32(1e-8))
            if W_:
                for li, w in enumerate(W):
                    amp = Tw * (0.7 ** ci) * R9_GANHO * np.abs(CAOS[:, t, li % 3]) * desvio(w) * em_del
                    w += sh3(amp.astype(f32)) * rngw.standard_normal(w.shape, dtype=f32)
                ex = (~em_del) & (frac < 1.0)
                if ex.any():
                    for pp, E in zip(P, EMA):
                        pp += sh3((f32(0.15) * ex).astype(f32)) * (E - pp)
                for pp, E in zip(P, EMA):
                    E *= f32(0.9)
                    E += f32(0.1) * pp
    return W, B, info


def r13_rodar(arm, tarefa, cfgs, seeds, lk, ruido_seed, passos=R11_PASSOS):
    """Treina e avalia (acurácia de teste, perda, ECE, finitude) um lote de redes do braço `arm` (mesmos dados/lago da R10–R12)."""
    arm = r13_canonico(arm)
    Xtr, ytr, mr, Xte, yte = r10_dados_lote(tarefa, seeds, lk)
    lago = r11_lago_lote(tarefa, seeds, mr.sum(1).astype(int), lk) if "N" in arm else None
    W, B, info = r13_treinar_lote(arm, tarefa, Xtr, ytr, mr, cfgs, seeds, passos, ruido_seed, lago)
    d = r9_avaliar_lote([w.astype(np.float64) for w in W], [b.astype(np.float64) for b in B], Xte, yte)
    d["info"] = info
    return d


# ----------------------------------------------------------------------
# Camada de regras (Prolog) com o GUIA como priors e a poda de interruptores inertes
# ----------------------------------------------------------------------
R13_PROLOG_REGRAS = """
prior(C, alto) :- grupo(C, G), decisao(G, manter).
prior(C, medio) :- grupo(C, G), decisao(G, dormente).
prior(C, baixo) :- grupo(C, G), decisao(G, candidato).
suporte(C) :- requer(C, X), ativo(X).
inerte(C) :- ativo(C), requer(C, Z), \\+ suporte(C).
"""


def r13_motor() -> "MotorProlog":
    """Motor Prolog (R8) com os fatos do guia congelado de R1–R12, o mapa componente→grupo e os requisitos de cada interruptor condicional (K: A ou W; M, E, V: A ou N)."""
    fatos = [f"grupo({c.lower()}, {g})." for c, g in R13_COMP_GRUPO.items()]
    fatos += [f"decisao({g}, {d})." for g, d in R13_GUIA_R12.items()]
    fatos += [f"requer({c.lower()}, {x.lower()})." for c, xs in R13_REQUER.items() for x in xs]
    return MotorProlog("\n".join(fatos) + "\n" + R13_PROLOG_REGRAS)


def r13_priors(motor) -> dict:
    """{componente: prob. de ligar} inferida pelo motor Prolog a partir do guia (alto 0,75 / medio 0,30 / baixo 0,10)."""
    out = {}
    for c in R13_COMP:
        s = motor.consulta(f"prior({c.lower()}, X)", 1)
        out[c] = R13_PRIOR[s[0]["X"]] if s else R13_PRIOR["medio"]
    return out


def r13_inertes(motor, ligados) -> list:
    """Componentes de `ligados` que o motor Prolog prova INERTES (nenhum dos suportes exigidos está ligado)."""
    motor.retract_dinamicos()
    for c in ligados:
        motor.assertz(f"ativo({c.lower()})")
    ine = [c for c in ligados if motor.prova(f"inerte({c.lower()})")]
    motor.retract_dinamicos()
    return ine


def r13_nomes_hip(arm: str) -> list:
    """Hiperparâmetros ajustáveis do braço (canônico): lr, wd; σ (N); T, ρ, γ (A); θ_v (V) ou θ_e (filtro de comitê) se houver fontes; T_w, frac (W)."""
    arm = r13_canonico(arm)
    n = ["lr", "wd"]
    if "N" in arm:
        n.append("sig")
    if "A" in arm:
        n += ["T", "rho", "gam"]
    if "A" in arm or "N" in arm:
        n.append("thv" if "V" in arm else "the")
    if "W" in arm:
        n += ["Tw", "frac"]
    return n


def r13_sorteio_cfg(arm: str, rng) -> dict:
    c = {}
    for nome in r13_nomes_hip(arm):
        lo, hi, tipo = R13_FAIXAS[nome]
        u = rng.random()
        c[nome] = float(math.exp(math.log(lo) + u * (math.log(hi) - math.log(lo)))) if tipo == "log" else float(lo + u * (hi - lo))
    return c


def r13_sorteios_fixo(arm: str, tarefa: str, n: int):
    """n configs sorteadas (semente = crc32 de braço|tarefa, tag 13) para um braço FIXO; prefixo estável."""
    rng = np.random.default_rng([zlib.crc32(("R13fixo|" + arm + "|" + tarefa).encode("utf-8")), 13, 3])
    return [r13_sorteio_cfg(arm, rng) for _ in range(n)]


def r13_sorteios_padrao(metodo: str, tarefa: str, n: int):
    """n configs sorteadas dos métodos-padrão nas faixas de R11_ESPACO (semente com tag 13)."""
    rng = np.random.default_rng([zlib.crc32(("R13pad|" + metodo + "|" + tarefa).encode("utf-8")), 13, 3])
    out = []
    for _ in range(n):
        c = {}
        for nome, lo, hi, tipo in R11_ESPACO[metodo]:
            u = rng.random()
            c[nome] = float(math.exp(math.log(lo) + u * (math.log(hi) - math.log(lo)))) if tipo == "log" else float(lo + u * (hi - lo))
        out.append(c)
    return out


def r13_sortear_pool(tarefa: str, P: int, regras: bool, motor=None) -> list:
    """Pool de P candidatos {arm, cfg}. COM regras: cada interruptor liga com o prior do guia (inferido pelo Prolog), inertes podados (canônico) e braços distintos (≤ 200 tentativas); SEM regras: prob. 0,5, sem poda e sem remoção de duplicatas."""
    rng = np.random.default_rng([zlib.crc32(f"R13|pool|{tarefa}|{'regras' if regras else 'livre'}".encode("utf-8")), 13, 5])
    pri = r13_priors(motor) if regras else {c: 0.5 for c in R13_COMP}
    pool, vistos = [], set()
    for _ in range(P):
        for _t in range(200):
            lig = [c for c in R13_COMP if rng.random() < pri[c]]
            if regras:
                ine = r13_inertes(motor, lig)
                lig = [c for c in lig if c not in ine]
            arm = "".join(lig)
            if (not regras) or arm not in vistos:
                break
        vistos.add(arm)
        pool.append({"arm": arm, "cfg": r13_sorteio_cfg(arm, rng)})
    return pool


def _r13_rs(rot: str, tarefa: str, desloc: int) -> int:
    return zlib.crc32(f"R13|{rot}|{tarefa}".encode("utf-8")) + desloc


def r13_avaliar_grupos(itens, tarefa, lk, rs_base: int):
    """itens = [(chave, arm, cfg, [sementes])] → {chave: [acurácia por semente, na ordem]}. Um lote por braço CANÔNICO (a composição do lote é determinística)."""
    grupos = {}
    for chave, arm, cfg, ss in itens:
        g = grupos.setdefault(r13_canonico(arm), [])
        for s in ss:
            g.append((chave, cfg, s))
    out = {it[0]: [] for it in itens}
    for arm in sorted(grupos):
        g = grupos[arm]
        d = r13_rodar(arm, tarefa, [x[1] for x in g], [x[2] for x in g], lk, rs_base + zlib.crc32(("g" + arm).encode("utf-8")))
        for (chave, _c, _s), a in zip(g, d["acc"]):
            out[chave].append(float(a))
    return out


def r13_sh(pool, tarefa, lk, desloc: int, modo: str):
    """SUCCESSIVE HALVING sobre o pool (estágios de R13_ESTAGIOS; sementes DEV 13100+: cumulativas). Devolve (índice escolhido, scores DEV por candidato, execuções gastas, histórico). A seleção usa SÓ acurácia DEV."""
    dev = [R13_SEM_DEV + desloc + j for j in range(sum(e[1] for e in R13_ESTAGIOS))]
    sc = {i: [] for i in range(len(pool))}
    vivos, cur, runs, hist = list(range(len(pool))), 0, 0, []
    for est, (manter, novos) in enumerate(R13_ESTAGIOS):
        if est > 0:
            vivos = sorted(vivos, key=lambda i: (-float(np.mean(sc[i])), i))[:manter]
        ss = dev[cur:cur + novos]
        cur += novos
        res = r13_avaliar_grupos([(i, pool[i]["arm"], pool[i]["cfg"], ss) for i in vivos], tarefa, lk, _r13_rs(f"sh{modo}{est}", tarefa, desloc))
        for i in vivos:
            sc[i] += res[i]
            runs += len(ss)
        hist.append((len(vivos), len(ss)))
    esc = min(vivos, key=lambda i: (-float(np.mean(sc[i])), i))
    return esc, sc, runs, hist


def _job_r13_celula(args):
    """Uma célula do BLOCO 20 (função de nível superior: roda em processo de segundo plano). kind ∈ sh | tab | fixo | g."""
    kind = args[0]
    t_cpu = time.process_time()
    if kind == "sh":                         # configurador (regras ou livre): SH no DEV; o 'livre' avalia também o escolhido no teste
        _, tarefa, modo, pool, lk, desloc, nc = args
        esc, sc, runs, hist = r13_sh(pool, tarefa, lk, desloc, modo)
        out = {"kind": kind, "tarefa": tarefa, "modo": modo, "esc": esc, "sc": {i: list(v) for i, v in sc.items()}, "runs": runs, "hist": hist}
        if modo == "livre":
            tst = [R13_SEM_C + desloc + j for j in range(nc)]
            d = r13_rodar(pool[esc]["arm"], tarefa, [pool[esc]["cfg"]] * nc, tst, lk, _r13_rs("testelivre", tarefa, desloc))
            out.update(acc=d["acc"], nfin=int((~d["fin"]).sum()))
        out["cpu"] = time.process_time() - t_cpu
        return out
    if kind == "tab":                        # um candidato do pool das regras nas sementes de TESTE (tabela do oráculo)
        _, tarefa, idx, cand, lk, desloc, nc = args
        tst = [R13_SEM_C + desloc + j for j in range(nc)]
        d = r13_rodar(cand["arm"], tarefa, [cand["cfg"]] * nc, tst, lk, _r13_rs(f"tab{idx}", tarefa, desloc))
        return {"kind": kind, "tarefa": tarefa, "idx": idx, "acc": d["acc"], "nfin": int((~d["fin"]).sum()), "cpu": time.process_time() - t_cpu}
    if kind == "fixo":                       # métodos de config fixa: ajuste (36 execuções DEV) → avaliação única da vencedora em 40 sementes
        _, tarefa, metodo, lk, desloc, nc = args
        dev3 = [R13_SEM_DEV + desloc + j for j in range(R13_NDEV_FIXO)]
        tst = [R13_SEM_C + desloc + j for j in range(nc)]
        if metodo in ("minimo", "completo"):
            arm = R13_ARM_MINIMO if metodo == "minimo" else R13_ARM_COMPLETO
            sorts = r13_sorteios_fixo(arm, tarefa, R13_NSORT_FIXO)
            cfgs = [c for c in sorts for _ in dev3]
            sds = [s for _ in sorts for s in dev3]
            d = r13_rodar(arm, tarefa, cfgs, sds, lk, _r13_rs(f"dev{metodo}", tarefa, desloc))
            sc = d["acc"].reshape(len(sorts), len(dev3)).mean(1)
            b = int(np.argmax(sc))
            dv = d["acc"]
            c = r13_rodar(arm, tarefa, [sorts[b]] * nc, tst, lk, _r13_rs(f"teste{metodo}", tarefa, desloc))
            out = {"arm": arm, "cfg": sorts[b], "dev_best": float(sc[b]), "dev_med": float(np.median(sc)), "runs": len(dv)}
        else:                                # padrão: 3 métodos × 4 sorteios × 3 sementes DEV; vence o de maior média DEV
            melhor = None
            runs = 0
            for m in R11_PADRAO:
                sorts = r13_sorteios_padrao(m, tarefa, R13_NSORT_PAD)
                cfgs = [c for c in sorts for _ in dev3]
                sds = [s for _ in sorts for s in dev3]
                d = r11_rodar(R11_SPEC[m], tarefa, cfgs, sds, lk, _r13_rs(f"devpad{m}", tarefa, desloc))
                runs += len(sds)
                sc = d["acc"].reshape(len(sorts), len(dev3)).mean(1)
                b = int(np.argmax(sc))
                if melhor is None or sc[b] > melhor[0]:
                    melhor = (float(sc[b]), m, sorts[b], float(np.median(sc)))
            c = r11_rodar(R11_SPEC[melhor[1]], tarefa, [melhor[2]] * nc, tst, lk, _r13_rs(f"testepad{melhor[1]}", tarefa, desloc))
            out = {"arm": melhor[1], "cfg": melhor[2], "dev_best": melhor[0], "dev_med": melhor[3], "runs": runs}
        out.update(kind=kind, tarefa=tarefa, metodo=metodo, acc=c["acc"], nfin=int((~c["fin"]).sum()), cpu=time.process_time() - t_cpu)
        return out
    if kind == "g":                          # meta-teste: um braço do fatorial fracionado, hiperparâmetros FIXOS, em 40 sementes NOVAS de uma tarefa nova
        _, tarefa, i, arm, lk, desloc, ng = args
        sds = [R13_SEM_G + desloc + j for j in range(ng)]
        d = r13_rodar(arm, tarefa, [dict(R13_G_CFG)] * ng, sds, lk, _r13_rs(f"g{i}", tarefa, desloc))
        return {"kind": kind, "tarefa": tarefa, "i": i, "arm": arm, "acc": d["acc"], "nfin": int((~d["fin"]).sum()), "cpu": time.process_time() - t_cpu}
    raise ValueError(kind)


def r13_tarefas(ctx):
    """Lista de células do BLOCO 20 (mais pesadas primeiro). Mesma função para enviar ao segundo plano e para consumir."""
    if "r13_tar" in ctx.res_cache:
        return ctx.res_cache["r13_tar"]
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R13_DEV") else 0
    nc = ng = 16 if rapido else R13_NC          # --rapido: 16 sementes de teste (o orçamento de ajuste e o pool não mudam)
    lk = LakeLeve(ctx.lake)
    motor = r13_motor()
    tar = []
    pools = {}
    for t in R13_TAREFAS:
        pools[t] = (r13_sortear_pool(t, R13_P, True, motor), r13_sortear_pool(t, R13_P, False))
    ctx.res_cache["r13_pools"] = pools
    for t in ("paridade", "estreita", "espirais", "texto", "poucos"):
        lkt = lk if t == "texto" else None
        pr, pl = pools[t]
        for i, c in enumerate(pr):
            tar.append(("tab", t, i, c, lkt, desloc, nc))
        tar.append(("sh", t, "regras", pr, lkt, desloc, nc))
        tar.append(("sh", t, "livre", pl, lkt, desloc, nc))
        for m in ("completo", "minimo", "padrao"):
            tar.append(("fixo", t, m, lkt, desloc, nc))
    for t in R13_TAREFAS_NOVAS:
        for i, arm, _niv in R13_FATORIAL:
            tar.append(("g", t, i, arm, None, desloc, ng))
    ctx.res_cache["r13_tar"] = (_job_r13_celula, tar)
    return ctx.res_cache["r13_tar"]



# ----------------------------------------------------------------------
# BLOCO 20: análises (confirmatórias Z1–Z5, regret, meta-teste do guia) e relatório
# ----------------------------------------------------------------------
def r13_hipoteses(R):
    """(id, tarefa) → (acc_a, acc_b, índice) das 25 confirmatórias: Z1 configurador−completo, Z2 −minimo, Z3 −padrao, Z4 −config_sem_regras (bicaudais), Z5 TOST configurador≈minimo."""
    PA, i_ = {}, 0
    for t in R13_TAREFAS:
        C = R[("configurador", t)]
        for k, b_ in (("Z1", "completo"), ("Z2", "minimo"), ("Z3", "padrao"), ("Z4", "config_sem_regras"), ("Z5", "minimo")):
            i_ += 1
            PA[(k, t)] = (C, R[(b_, t)], i_)
    return PA


def r13_status(k, media, padj):
    if k == "Z5":
        return "equivalentes (TOST ±2 pp)" if padj < 0.05 else "nula (equivalência não demonstrada)"
    return _status7(media, padj)


def r13_regras(st):
    """Vereditos pré-registrados a partir dos vereditos por (hipótese, tarefa): do CONFIGURADOR (Z1–Z3) e das REGRAS do guia (Z4)."""
    T = R13_TAREFAS
    pos = lambda k: [t for t in T if st[(k, t)] == "confirmada"]
    neg = lambda k: [t for t in T if st[(k, t)].startswith("refutada")]
    n_pos = sum(len(pos(k)) for k in ("Z1", "Z2", "Z3"))
    n_neg = sum(len(neg(k)) for k in ("Z1", "Z2", "Z3"))
    if n_neg == 0 and any(len(pos(k)) >= 2 for k in ("Z1", "Z2", "Z3")):
        v = "CONFIGURAR COMPENSA"
    elif n_pos == 0:
        v = "CONFIGURAR NÃO COMPENSA"
    else:
        v = "MISTO"
    z4p, z4n = pos("Z4"), neg("Z4")
    if len(z4p) >= 2 and not z4n:
        vr = "AS REGRAS DO GUIA AJUDAM"
    elif z4n and not z4p:
        vr = "AS REGRAS ATRAPALHAM"
    else:
        vr = "REGRAS INDECIDIDAS"
    return {"veredito": v, "veredito_regras": vr, "z": {k: (pos(k), neg(k)) for k in R13_HIPOT}, "n_pos": n_pos, "n_neg": n_neg}


def r13_efeitos(acc16, niv=None):
    """Efeito principal de cada componente numa tarefa: média dos 8 braços com o componente LIGADO menos a média dos 8 DESLIGADOS, por semente (ng,). `acc16`: (16, ng) na ordem de R13_FATORIAL."""
    niv = niv or [x[2] for x in R13_FATORIAL]
    acc16 = np.asarray(acc16, float)
    out = {}
    for c in R13_COMP:
        on = np.array([n[c] > 0 for n in niv])
        out[c] = acc16[on].mean(0) - acc16[~on].mean(0)
    return out


def r13_efeitos_cond(acc16, niv=None):
    """Efeito CONDICIONAL (descritivo): só entre os braços em que o suporte do componente está presente (K: A ou W; M, E, V: A ou N); A, N, W = efeito principal. Devolve {comp: (ng,)}."""
    niv = niv or [x[2] for x in R13_FATORIAL]
    acc16 = np.asarray(acc16, float)
    out = {}
    for c in R13_COMP:
        sup = np.ones(len(niv), bool)
        if c in R13_REQUER:
            sup = np.array([any(n[x] > 0 for x in R13_REQUER[c]) for n in niv])
        on = np.array([n[c] > 0 for n in niv]) & sup
        off = np.array([n[c] < 0 for n in niv]) & sup
        out[c] = acc16[on].mean(0) - acc16[off].mean(0)
    return out


def r13_predicao(obs, rotulos=None):
    """Meta-teste do guia. `obs`: {(comp, tarefa): 'ajuda'|'prejudica'|'nulo'}; `rotulos`: {comp: decisão do grupo} (padrão: guia congelado de R1–R12). Predição: MANTER ⇒ ajuda; dormente/candidato ⇒ não ajuda.
    Devolve acurácia, preditor trivial ('ninguém ajuda'), p exato do nulo de permutação dos rótulos (C(7,3) = 35 atribuições), sensibilidade, especificidade e kappa."""
    rot = rotulos or {c: R13_GUIA_R12[g] for c, g in R13_COMP_GRUPO.items()}
    comps = list(R13_COMP)
    tarefas = sorted({t for (_, t) in obs})
    pred = {c: (rot[c] == "manter") for c in comps}
    ajuda = {(c, t): obs[(c, t)] == "ajuda" for c in comps for t in tarefas}
    acerto = lambda p: float(np.mean([p[c] == ajuda[(c, t)] for c in comps for t in tarefas]))
    acc = acerto(pred)
    triv = float(np.mean([not ajuda[(c, t)] for c in comps for t in tarefas]))
    n_man = sum(pred.values())
    import itertools
    accs = []
    for comb in itertools.combinations(range(len(comps)), n_man):
        pp = {c: (i in comb) for i, c in enumerate(comps)}
        accs.append(acerto(pp))
    p_perm = float(np.mean([a >= acc - 1e-12 for a in accs]))
    tp = sum(pred[c] and ajuda[(c, t)] for c in comps for t in tarefas)
    fn = sum((not pred[c]) and ajuda[(c, t)] for c in comps for t in tarefas)
    tn = sum((not pred[c]) and (not ajuda[(c, t)]) for c in comps for t in tarefas)
    fp = sum(pred[c] and (not ajuda[(c, t)]) for c in comps for t in tarefas)
    n = tp + fn + tn + fp
    po = (tp + tn) / n
    pe = ((tp + fp) * (tp + fn) + (fn + tn) * (fp + tn)) / (n * n)
    kappa = (po - pe) / (1 - pe) if abs(1 - pe) > 1e-12 else float("nan")
    if acc > triv + 1e-12 and p_perm <= 0.05:
        v = "O GUIA PREDIZ"
    elif acc < triv - 1e-12:
        v = "O GUIA É PIOR QUE O TRIVIAL"
    else:
        v = "O GUIA NÃO SE DEMONSTROU"
    return {"acc": acc, "trivial": triv, "p_perm": p_perm, "n_atrib": len(accs), "sens": tp / (tp + fn) if (tp + fn) else float("nan"), "espec": tn / (tn + fp) if (tn + fp) else float("nan"),
            "kappa": kappa, "tp": tp, "fp": fp, "tn": tn, "fn": fn, "veredito": v, "pred": pred, "n": n}


def _r13_postos(v):
    v = np.asarray(v, float)
    o = np.argsort(v, kind="stable")
    r = np.empty(len(v))
    i = 0
    while i < len(v):
        j = i
        while j + 1 < len(v) and v[o[j + 1]] == v[o[i]]:
            j += 1
        r[o[i:j + 1]] = (i + j) / 2.0 + 1
        i = j + 1
    return r


def r13_spearman(x, y):
    rx, ry = _r13_postos(x), _r13_postos(y)
    if rx.std() == 0 or ry.std() == 0:
        return float("nan")
    return float(np.corrcoef(rx, ry)[0, 1])


R13_GUIA_SALDO = {"A": 0, "N": 0, "V": 5, "W": 3, "K": 1, "M": -1, "E": -1}      # saldo do guia R12 (a favor − contra por grupo, congelado do relatório R12): A=delirio_generativo 7−7, N=minimo 1−1, V=verificador 11−6, W=delirio_pesos 10−7, K=caos 2−1, M=sistema 3−4, E=gan_mem 0−1


def bloco20(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 20 — [R13] AUTOCONFIGURAÇÃO GUIADA POR EVIDÊNCIA: configurador (successive halving sobre subconjuntos de componentes + camada Prolog com o guia como priors) contra o sistema completo, o mínimo e o melhor padrão, com ORÇAMENTO de ajuste igual; "
               "META-TESTE do guia em 2 tarefas NOVAS (5 tarefas × 5 métodos + oráculo; 40 sementes novas; Holm sobre 25; fatorial fracionado 2^(7−3) × 2 tarefas novas, Holm sobre 14)")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R13_DEV") else 0
    nc = ng = 16 if rapido else R13_NC
    ok_p = sha_ok(PREREG_R13_CORPO, PREREG_R13_CORPO_SHA256)
    rep.log(f"Integridade: pré-registro R13 (corpo) {PREREG_R13_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r13.txt, carimbado 20:20 PT, ANTES de qualquer código de modelo da R13 e de qualquer execução com sementes R13; ' if ok_p else '(NÃO CONFERE!) ('}carimbo auto-atestado pelo relógio da máquina).")
