    sp = r13_spearman([R13_GUIA_SALDO[c] for c in R13_COMP], dmean)
    rep.sub("Exploratórios do meta-teste (fora do Holm)")
    rep.log("G1 Spearman entre o saldo do guia R12 do grupo (a favor − contra: " + ", ".join(f"{c}={R13_GUIA_SALDO[c]:+d}" for c in R13_COMP) + ") e o efeito principal médio (pp) nas 2 tarefas (" + ", ".join(f"{c}={d:+.2f}" for c, d in zip(R13_COMP, dmean)) + f"): ρ = {sp:+.2f} (n=7 componentes: sem poder).")
    cond = {}
    for t in R13_TAREFAS_NOVAS:
        ec = r13_efeitos_cond(accg[t])
        cond[t] = {c: float(ec[c].mean()) for c in R13_COMP}
    rep.log("G2 efeito CONDICIONAL (só nos braços em que o suporte do componente existe; K: A ou W; M, E, V: A ou N; descritivo, sem teste), pp: " + " | ".join(f"{t}: " + ", ".join(f"{c}={100 * cond[t][c]:+.2f}" for c in R13_COMP) for t in R13_TAREFAS_NOVAS))
    ef_all = {t: {c: float(EFG[(c, t)].mean()) for c in R13_COMP} for t in R13_TAREFAS_NOVAS}
    best = {t: max(range(16), key=lambda i: accg[t][i].mean()) for t in R13_TAREFAS_NOVAS}
    rep.log("G3 melhor braço do fatorial por tarefa (acurácia média; descritivo, otimista) e o braço 'nada ligado' ({}): " + "; ".join(f"{t}: {R13_FATORIAL[best[t]][1] or '{}'} {100 * accg[t][best[t]].mean():.1f}% vs {{}} {100 * accg[t][0].mean():.1f}%" for t in R13_TAREFAS_NOVAS))
    cpu_g = float(np.sum([c["cpu"] for c in GG.values()]))
    rep.log(f"G4 CPU do meta-teste (s; volátil): {cpu_g:.1f}", vol=True)
    rep.log("Limites do meta-teste: (i) 2 tarefas minúsculas de uma só família (classificação binária em MLP [16,16]); (ii) hiperparâmetros FIXOS nos pontos médios, sem ajuste — componentes que dependem de ajuste fino (W, A) podem parecer piores do que seriam ajustados; "
            "(iii) K, M, E e V são condicionais: o efeito principal médio é diluído (G2 dá o condicional, descritivo); (iv) os rótulos do guia são por GRUPO de hipóteses de R1–R12 (que misturam tarefas e desfechos diferentes) e foram mapeados para componentes por mim; "
            "(v) 14 células correlacionadas (as 2 tarefas e os efeitos dos 7 componentes vêm dos mesmos 16 braços): a acurácia tem incerteza alta; (vi) dicionário/jogos/curiosidade não são testáveis aqui.")
    rep.log(f"(tempo do bloco 20: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r13_cfg"] = {"nc": nc, "P": {k: (P[k]["media"], P[k]["lo"], P[k]["hi"], P[k]["p"], float(ph[k]), P[k]["mde"]) for k in chaves}, "st": st, "RG": RG,
                          "acc": {(m, t): float(R[(m, t)].mean()) for m in MET for t in R13_TAREFAS}, "E1": E1, "cpu": cpu, "runs": runs, "opt": opt, "rank": {m: float(np.mean(v)) for m, v in rank.items()},
                          "esc": {t: pools[t][0][info[t]["esc"]]["arm"] for t in R13_TAREFAS}, "orac": {t: pools[t][0][info[t]["orac"]]["arm"] for t in R13_TAREFAS}, "freq_w": freq_w, "info": info}
    ctx.res["r13_guia"] = {"ng": ng, "P": {k: (PG[k]["media"], PG[k]["lo"], PG[k]["hi"], PG[k]["p"], float(phg[k]), PG[k]["mde"]) for k in keys_g}, "obs": obs, "PR": PR, "cpu": cpu_g, "sp": sp,
                           "ef": ef_all, "cond": cond, "keys": keys_g}



