R14_NOMES_HIP = ("natural", "reversa") + tuple(f"trunfo{''.join(map(str, p))}" for p in __import__("itertools").permutations(range(3))) + ("ciclica+", "ciclica-")
R14_PERMS = list(__import__("itertools").permutations(range(3)))


def r14_vitoria_hip(h: int, rk, cl):
    """Matriz P[..., a, b] ∈ {0, 0,5, 1}: probabilidade prevista de que a palavra `a` vença `b` sob a hipótese h (0 natural, 1 reversa, 2–7 trunfo de classe com a permutação R14_PERMS[h−2] (prioridade[c] = perm[c]), 8 cíclica+ (classe c vence c+1), 9 cíclica−), dados postos rk e classes cl (..., 12) (0,5 se empatar)."""
    ra, rb = rk[..., :, None], rk[..., None, :]
    ca, cb = cl[..., :, None], cl[..., None, :]
    cmp_ = np.where(ra > rb, 1.0, np.where(ra < rb, 0.0, 0.5))
    if h == 0:
        return cmp_
    if h == 1:
        return 1.0 - cmp_
    if 2 <= h <= 7:
        pr = np.array(R14_PERMS[h - 2])
        pa, pb = pr[ca], pr[cb]
        return np.where(pa > pb, 1.0, np.where(pa < pb, 0.0, cmp_))
    d = (cb - ca) % 3
    base = np.where(d == 1, 1.0, np.where(d == 2, 0.0, cmp_))
    return base if h == 8 else np.where(d == 0, cmp_, 1.0 - base)


def r14_mundo(seed: int, variante: str):
    """Mundo de uma semente: posto (12,), classe (12,), vetor de dicionário SINTÉTICO (12,6), hipótese verdadeira, matriz de vitória W (12,12) ∈ {+1,−1} (+1: linha vence coluna; diagonal 0)."""
    rng = np.random.default_rng([int(seed), 14, 1])
    rk = rng.permutation(R14_K)
    cl = rng.permutation(np.repeat(np.arange(3), R14_K // 3))
    e = rng.standard_normal((R14_K, 6))
    ang = 2 * math.pi * cl / 3
    vec = np.stack([2 * rk / (R14_K - 1) - 1 + 0.3 * e[:, 0], np.cos(ang) + 0.3 * e[:, 1], np.sin(ang) + 0.3 * e[:, 2], 0.5 * e[:, 3], 0.5 * e[:, 4], 0.5 * e[:, 5]], axis=1)
    rng2 = np.random.default_rng([int(seed), 14, 2])
    perm_i = int(rng2.integers(0, 6))
    if variante == "visivel":
        h = 0
    else:
        h = (1, 2 + perm_i, 8)[int(seed) % 3]
    P = r14_vitoria_hip(h, rk.astype(float), cl)
    W = np.where(np.eye(R14_K, dtype=bool), 0.0, 2.0 * P - 1.0)
    return {"rk": rk, "cl": cl, "vec": vec, "h": h, "W": W}


def r14_tabelas(p):
    """p (S,4,12) → (po, pf, qc, qb): P(J1 aposta | carta), P(J1 paga após passar e J2 apostar), P(J2 paga após aposta), P(J2 aposta após passe)."""
    return p[:, 0], p[:, 1], p[:, 2], p[:, 3]


def r14_valor(pol1, pol2, W):
    """Pagamento ESPERADO EXATO de J1 (enumeração das 132 distribuições): pol1 = (po, pf) (S,12), pol2 = (qc, qb)."""
    po, pf = pol1
    qc, qb = pol2
    M = 1.0 - np.eye(R14_K)
    A = po[:, :, None] * ((1 - qc)[:, None, :] + qc[:, None, :] * 2 * W)
    B = (1 - po)[:, :, None] * ((1 - qb)[:, None, :] * W + qb[:, None, :] * (-(1 - pf)[:, :, None] + pf[:, :, None] * 2 * W))
    return ((A + B) * M).sum((1, 2)) / (R14_K * (R14_K - 1))


def r14_expl(p, W):
    """EXPLOITABILITY exata (S,): valor da melhor resposta de J2 contra J1 + valor da melhor resposta de J1 contra J2 (≥ 0; 0 = Nash). p (S,4,12); W (S,12,12) (+1: linha vence coluna)."""
    po, pf, qc, qb = r14_tabelas(p)
    M = (1.0 - np.eye(R14_K))[None]
    n = R14_K * (R14_K - 1)
    # melhor resposta de J2 (carta j; W[j,i] = +1 se j vence i)
    ev_call = 2 * (M * po[:, None, :] * W).sum(2)
    ev_fold = -(M * po[:, None, :]).sum(2)
    ev_pass = (M * (1 - po)[:, None, :] * W).sum(2)
    ev_bet = (M * (1 - po)[:, None, :] * ((1 - pf)[:, None, :] + pf[:, None, :] * 2 * W)).sum(2)
    v2 = (np.maximum(ev_call, ev_fold) + np.maximum(ev_pass, ev_bet)).sum(1) / n
    # melhor resposta de J1 (carta i)
    eb = (M * ((1 - qc)[:, None, :] + qc[:, None, :] * 2 * W)).sum(2)
    ep = (M * (1 - qb)[:, None, :] * W).sum(2) + np.maximum(-(M * qb[:, None, :]).sum(2), 2 * (M * qb[:, None, :] * W).sum(2))
    v1 = np.maximum(eb, ep).sum(1) / n
    return v1 + v2


def r14_fixa(nome: str, W):
    """Tabelas (po, pf, qc, qb) (S,12) da estratégia FIXA: aleatória (0,5), maníaca (1) ou honesta (1 se a força VERDADEIRA da carta está no 50% superior)."""
    S = W.shape[0]
    if nome == "aleatoria":
        t = np.full((S, 12), 0.5)
    elif nome == "maniaca":
        t = np.ones((S, 12))
    else:
        f = W.sum(2)
        t = (f > np.median(f, axis=1, keepdims=True)).astype(float)
    return t, t, t, t


def r14_payoff_fixa(p, W, nome: str):
    """Pagamento esperado exato do aprendiz (média das duas posições) contra a estratégia fixa `nome`."""
    po, pf, qc, qb = r14_tabelas(p)
    fo, ff, fc, fb = r14_fixa(nome, W)
    a = r14_valor((po, pf), (fc, fb), W)
    b = -r14_valor((fo, ff), (qc, qb), W)
    return 0.5 * (a + b)


def r14_sorteios(metodo: str, variante: str, n: int):
    """n configurações sorteadas (semente = crc32 de método|variante, tag 14) nas faixas R14_FAIXAS, para os hiperparâmetros do método; prefixo estável."""
    nomes = r14_nomes_hip(metodo)
    rng = np.random.default_rng([zlib.crc32(("R14|" + metodo + "|" + variante).encode("utf-8")), 14, 5])
    out = []
    for _ in range(n):
        c = {}
        for nome in nomes:
            lo, hi, tipo = R14_FAIXAS[nome]
            u = rng.random()
            c[nome] = float(math.exp(math.log(lo) + u * (math.log(hi) - math.log(lo)))) if tipo == "log" else float(lo + u * (hi - lo))
        out.append(c)
    return out


def r14_nomes_hip(metodo: str):
    f = R14_FLAGS[metodo]
    n = ["lr", "beta"]
    if f["X"]:
        n.append("eps")
    if f["F"]:
        n.append("delta")
    if f["E"]:
        n += ["Tw", "frac"]
    if f["L"]:
        n.append("Tw")
    return n


def _r14_sig(z):
    return 1.0 / (1.0 + np.exp(-np.clip(z, -30, 30)))


def r14_treinar(metodo: str, cfgs, seeds, variante: str, T: int = None, B: int = None):
    """Envoltório: execuções que divergem (ex.: ruído Langevin multiplicativo com Tw alto) geram overflow esperado; viram 'não finitas' (fin=False) sem poluir a saída."""
    with np.errstate(all="ignore"):
        return _r14_treinar(metodo, cfgs, seeds, variante, T, B)


def _r14_treinar(metodo: str, cfgs, seeds, variante: str, T: int = None, B: int = None):
    """Treina len(seeds) execuções INDEPENDENTES do método (cfgs[k], seeds[k]) em auto-jogo REINFORCE. A aleatoriedade de cada execução depende só da semente (mãos pré-geradas por [semente,14,4]; ruído por [semente,14,5]), logo
    o resultado não depende da composição do lote. Devolve dict: expl (S,) da política média dos últimos 25%, curva (S, n_ck), pagamentos (S,3) contra aleatória/maníaca/honesta, regra_ok (S,), consultas (S,), fin (S,)."""
    T = T or R14_T
    B = B or R14_B
    S = len(seeds)
    f = R14_FLAGS[metodo]
    seeds = [int(s) for s in seeds]
    useen, inv = np.unique(seeds, return_inverse=True)
    mundos = {s: r14_mundo(s, variante) for s in useen}
    W = np.stack([mundos[s]["W"] for s in seeds]).astype(np.float32)
    vec = np.stack([mundos[s]["vec"] for s in seeds]).astype(np.float32)
    htrue = np.array([mundos[s]["h"] for s in seeds])
    F_ = R14_NF
    g = lambda nome, pad=0.0: np.array([c.get(nome, pad) for c in cfgs], np.float32)
    lr0, beta0, eps0, delta, Tw, frac = g("lr"), g("beta"), g("eps"), g("delta"), g("Tw"), g("frac", 0.5)
    X_ = bool(f["X"])
    # aleatoriedade pré-gerada por semente única
    UR = np.stack([np.random.default_rng([s, 14, 4]).random((T, B, 14), dtype=np.float32) for s in useen])      # (U,T,B,14)
    usa_ruido = bool(f["E"] or f["L"])
    XI = np.stack([np.random.default_rng([s, 14, 5]).standard_normal((T, 4, F_)).astype(np.float32) for s in useen]) if usa_ruido else None
    ordem = np.stack([np.random.default_rng([s, 14, 3]).permutation(R14_K) for s in seeds])                      # (S,12) ordem aleatória de consultas / desempate
    if usa_ruido:
        flux = (r10_lorenz_lote if f["K"] else r13_lorenz_embaralhado)(T, [s + 1414 for s in seeds]).astype(np.float32)   # (S,T)
    ar = np.arange(S)
    # ---- dicionário, regra
    known = np.zeros((S, R14_K), bool)
    if f["D"] == "todas":
        known[:] = True
    nconsultas = np.zeros(S, int)
    useR = bool(f["R"] and f["D"] != "nenhum")
    if useR:
        rk_hat = np.clip(np.rint((vec[:, :, 0] + 1) / 2 * (R14_K - 1)), 0, R14_K - 1)
        ang = np.arctan2(vec[:, :, 2], vec[:, :, 1])
        cl_hat = np.rint(ang / (2 * math.pi / 3)).astype(int) % 3
        Ph = np.stack([r14_vitoria_hip(h, rk_hat, cl_hat) for h in range(10)], axis=1).astype(np.float32)           # (S,10,12,12)
        LL = np.zeros((S, 10), np.float32)
    shat = np.zeros((S, R14_K), np.float32)
    ver = np.zeros(S, bool)
    post = np.full((S, 10), 0.1, np.float32)

    def atualiza_forca():
        nonlocal shat
        if not useR:
            return
        mk = known[:, None, :] * (1.0 - np.eye(R14_K))[None]                                  # (S,12(a),12(b)) b conhecido, b≠a
        den = np.maximum(mk.sum(2), 1.0)                                                      # (S,12)
        stg = np.einsum("shab,sab->sha", Ph, mk.astype(np.float32)) / den[:, None, :]          # (S,10,12): força de a sob h
        shat = (2.0 * np.einsum("sh,sha->sa", post, stg) - 1.0).astype(np.float32) * (ver[:, None] & known)

    if useR:
        atualiza_forca()
    # ---- política
    theta = np.zeros((S, 4, F_), np.float32)
    mA = np.zeros_like(theta)
    vA = np.zeros_like(theta)
    ema = np.zeros_like(theta)
    acc25, n25 = np.zeros_like(theta), 0
    acc60, n60 = np.zeros_like(theta), 0
    eye12 = np.eye(R14_K, dtype=np.float32)

    def feats():
        Phi = np.zeros((S, R14_K, F_), np.float32)
        Phi[:, :, 0] = 1.0
        Phi[:, :, 1:1 + R14_K] = eye12
        Phi[:, :, 1 + R14_K:7 + R14_K] = vec * known[:, :, None]
        Phi[:, :, 7 + R14_K] = shat
        return Phi

    Phi = feats()
    Qh = np.zeros((S, 4, R14_K, 2), np.float32)
    Cn = np.zeros((S, 4, R14_K, 2), np.float32)
    surpresa = np.zeros((S, R14_K), np.float32)
    visitas = np.zeros((S, R14_K), np.float32)
    lr_mult = np.ones(S, np.float32)
    beta_mult = np.ones(S, np.float32)
    eps_add = np.zeros(S, np.float32)
    gn_hist, gn_ema = [], np.zeros(S, np.float32)
    L_ = max(T // 4, 1)
    curva, pol_ck = [], []
    ck_pts = list(range(R14_CK, T + 1, R14_CK))
    if ck_pts[-1] != T:
        ck_pts.append(T)
    t60 = int(T * 0.75)
    cfg_eps = eps0
    W_np = W
    # checkpoint 0 (política inicial 0,5)
    def pol_de(th, Ph_):
        return _r14_sig(np.einsum("sdf,swf->sdw", th, Ph_))
    curva.append(r14_expl(pol_de(theta, Phi).astype(np.float64), W_np.astype(np.float64)))
    orange = np.arange(R14_K)
    for t in range(T):
        # ---- consulta ao dicionário (orçamentada)
        if f["D"] == "orc" and t % R14_PER_CONSULTA == 0 and t // R14_PER_CONSULTA < R14_Q:
            pos_ = np.argsort(ordem, axis=1)                                # posição de cada palavra na ordem sorteada da semente
            if f["C"]:
                score = surpresa + 0.5 / np.sqrt(1.0 + visitas) + 1e-6 * (R14_K - pos_)      # curiosidade; desempate pela ordem sorteada
            else:
                score = (R14_K - pos_).astype(np.float32)                   # sem C: a ordem sorteada
            score = np.where(known, -1e9, score)
            w_ = np.argmax(score, axis=1)
            known[ar, w_] = True
            nconsultas += 1
            atualiza_forca()
            Phi = feats()
        U = UR[inv, t]                                                           # (S,B,14)
        p = pol_de(theta, Phi)                                                   # (S,4,12)
        i_ = np.minimum((U[:, :, 0] * R14_K).astype(int), R14_K - 1)
        j_ = np.minimum((U[:, :, 1] * (R14_K - 1)).astype(int), R14_K - 2)
        j_ = j_ + (j_ >= i_)
        sb = ar[:, None]
        eps_t = np.where(X_, np.clip(cfg_eps + eps_add, 0, 0.5), 0.0).astype(np.float32)[:, None]

        def decide(d, w_arr):
            pd = p[sb, d, w_arr]                                                  # (S,B)
            a_pi = (U[:, :, 2 + d] < pd)
            if not X_:
                return a_pi.astype(np.int8), pd, np.ones_like(pd), np.zeros_like(pd, dtype=bool)
            prop = (U[:, :, 10 + d] < 0.5)
            quer = U[:, :, 6 + d] < eps_t
            if f["F"]:
                gul = (pd > 0.5).astype(int)
                q0, q1 = Qh[sb, d, w_arr, 0], Qh[sb, d, w_arr, 1]
                qg = np.where(gul == 1, q1, q0)
                c0, c1 = Cn[sb, d, w_arr, 0], Cn[sb, d, w_arr, 1]
                dl = delta[:, None]
                ok0 = (c0 < 3) | (q0 >= qg - dl)
                ok1 = (c1 < 3) | (q1 >= qg - dl)
            else:
                ok0 = ok1 = np.ones_like(pd, dtype=bool)
            ok_prop = np.where(prop, ok1, ok0)
            a = np.where(quer & ok_prop, prop, a_pi).astype(np.int8)
            pa = np.where(a == 1, pd, 1 - pd)
            nb = 0.5 * ((~ok0).astype(np.float32) + (~ok1).astype(np.float32))
            ok_a = np.where(a == 1, ok1, ok0).astype(np.float32)
            mu = pa * (1 - eps_t + eps_t * nb) + 0.5 * eps_t * ok_a
            rho = np.minimum(pa / np.maximum(mu, 1e-6), 3.0)
            return a, pd, rho.astype(np.float32), quer & ok_prop

        a1, p1, r1, _ = decide(0, i_)
        # J2 paga/desiste após aposta (d=2) ; J2 aposta/passa após passe (d=3); J1 paga/desiste (d=1)
        a2, p2, r2, _ = decide(2, j_)
        a3, p3, r3, _ = decide(3, j_)
        a4, p4, r4, _ = decide(1, i_)
        w1 = W[sb, i_, j_]
        bet = a1 == 1
        v2 = bet                                   # d2 visitado
        v3 = ~bet                                  # d3 visitado
        v4 = (~bet) & (a3 == 1)                    # d1 visitado
        G1 = np.where(bet, np.where(a2 == 0, 1.0, 2 * w1), np.where(a3 == 0, w1, np.where(a4 == 0, -1.0, 2 * w1))).astype(np.float32)
        show = (bet & (a2 == 1)) | ((~bet) & (a3 == 0)) | v4 & (a4 == 1)
        # ---- gradiente REINFORCE (linha de base: média por execução e tipo de decisão)
        vis = (np.ones_like(G1, bool), v4, v2, v3)
        ret = (G1, G1, -G1, -G1)
        act = (a1, a4, a2, a3)
        pds = (p1, p4, p2, p3)
        rho = (r1, r4, r2, r3)
        wds = (i_, i_, j_, j_)
        OHi = (i_[:, :, None] == orange).astype(np.float32)
        OHj = (j_[:, :, None] == orange).astype(np.float32)
        OH = (OHi, OHi, OHj, OHj)
        Cw = np.zeros((S, 4, R14_K), np.float32)
        sabs = np.zeros((S, R14_K), np.float32)
        cabs = np.zeros((S, R14_K), np.float32)
        for d in range(4):
            m = vis[d].astype(np.float32)
            nm = np.maximum(m.sum(1, keepdims=True), 1.0)
            bl = (m * ret[d]).sum(1, keepdims=True) / nm
            adv = ret[d] - bl
            c = m * rho[d] * adv * (act[d].astype(np.float32) - pds[d]) / B
            Cw[:, d] = np.einsum("sbw,sb->sw", OH[d], c)
            sabs += np.einsum("sbw,sb->sw", OH[d], m * np.abs(adv))
            cabs += np.einsum("sbw,sb->sw", OH[d], m)
            # tabelas Q̂ (para o verificador F) e contagens
            if f["F"]:
                for a_ in (0, 1):
                    ma = m * (act[d] == a_)
                    sg = np.einsum("sbw,sb->sw", OH[d], ma * ret[d])
                    cn = np.einsum("sbw,sb->sw", OH[d], ma)
                    c_old = Cn[:, d, :, a_]
                    alfa = np.where(cn > 0, np.maximum(cn / (c_old + cn + 1e-9), 0.05), 0.0).astype(np.float32)
                    Qh[:, d, :, a_] += alfa * (sg / np.maximum(cn, 1) - Qh[:, d, :, a_])
                    Cn[:, d, :, a_] = c_old + cn
        surpresa = np.where(cabs > 0, 0.9 * surpresa + 0.1 * sabs / np.maximum(cabs, 1), surpresa).astype(np.float32)
        visitas = visitas + cabs
        grad = np.einsum("sdw,swf->sdf", Cw, Phi)
        # bônus de entropia (gradiente de H em relação ao logit: −p(1−p)·z), média sobre as 12 palavras
        z = np.log(np.clip(p, 1e-6, 1 - 1e-6) / np.clip(1 - p, 1e-6, 1))
        eg = np.einsum("sdw,swf->sdf", -p * (1 - p) * z, Phi) / R14_K
        grad = grad + (beta0 * beta_mult)[:, None, None] * eg
        gn = np.sqrt((grad ** 2).sum((1, 2)))
        # ---- Adam
        mA = 0.9 * mA + 0.1 * grad
        vA = 0.99 * vA + 0.01 * grad * grad
        mh = mA / (1 - 0.9 ** (t + 1))
        vh = vA / (1 - 0.99 ** (t + 1))
        env = (0.05 + 0.95 * 0.5 * (1 + math.cos(math.pi * t / T)))
        lr = lr0 * np.float32(env) * lr_mult
        pull = np.zeros(S, np.float32)
        if f["E"]:
            ph = (t % L_) / L_
            ciclo = t // L_
            del_ = ph < frac
            prog = np.clip((ph - frac) / np.maximum(1 - frac, 1e-6), 0, 1)
            lr = lr * np.where(del_, 3.0, 1 - 0.7 * prog).astype(np.float32)
            pull = np.where(del_, 0.0, 0.15).astype(np.float32)
        theta = theta + lr[:, None, None] * mh / (np.sqrt(vh) + 1e-8)
        if f["E"]:
            sd = theta.std((1, 2)) + 0.1
            amp = (Tw * (0.7 ** ciclo) * 0.08 * np.abs(flux[:, t]) * sd * del_).astype(np.float32)
            theta = theta + amp[:, None, None] * XI[inv, t]
            theta = theta + pull[:, None, None] * (ema - theta)
        elif f["L"]:
            sd = theta.std((1, 2)) + 0.1
            theta = theta + (Tw * 0.08 * sd)[:, None, None].astype(np.float32) * XI[inv, t]
        ema = 0.9 * ema + 0.1 * theta
        acc25 += theta
        n25 += 1
        if t >= t60:
            acc60 += theta
            n60 += 1
        # ---- regra: observa os showdowns
        if useR:
            ok_ = show & known[sb, i_] & known[sb, j_]
            pw = Ph[sb, :, i_, j_]                                              # (S,B,10) prob. prevista de i vencer j
            pw = 0.7 * pw + 0.15
            o1 = (w1 > 0)[:, :, None]
            lik = np.where(o1, pw, 1 - pw)
            LL = LL + (np.log(lik) * ok_[:, :, None]).sum(1)
            e_ = np.exp(LL - LL.max(1, keepdims=True))
            post = e_ / e_.sum(1, keepdims=True)
            ver = post.max(1) >= 0.6
            atualiza_forca()
            Phi = feats()
        # ---- monitores (a cada 10 iterações)
        gn_ema = np.where(gn_ema == 0, gn, 0.8 * gn_ema + 0.2 * gn)
        if f["M"] and t % 10 == 9:
            gn_hist.append(gn_ema.copy())
            Hm = -(p * np.log(np.clip(p, 1e-6, 1)) + (1 - p) * np.log(np.clip(1 - p, 1e-6, 1))).mean((1, 2))
            colapso = (Hm < 0.12) & (t < 0.7 * T)
            beta_mult = np.where(colapso, np.minimum(beta_mult * 1.5, 4.0), beta_mult).astype(np.float32)
            eps_add = np.where(colapso & X_, np.minimum(eps_add + 0.02, 0.2), eps_add).astype(np.float32)
            if len(gn_hist) >= 3:
                med = np.median(np.stack(gn_hist[:-1]), axis=0)
                inst = gn_ema > 3.0 * np.maximum(med, 1e-9)
                lr_mult = np.where(inst, np.maximum(lr_mult * 0.7, 0.1), lr_mult).astype(np.float32)
        # ---- checkpoints da curva (política média da janela)
        if (t + 1) in ck_pts:
            Pc = pol_de(acc25 / max(n25, 1), Phi)
            curva.append(r14_expl(Pc.astype(np.float64), W_np.astype(np.float64)))
            acc25, n25 = np.zeros_like(theta), 0
    th_f = acc60 / max(n60, 1)
    pf = pol_de(th_f, Phi).astype(np.float64)
    W64 = W_np.astype(np.float64)
    fin = np.isfinite(theta).all((1, 2)) & np.isfinite(pf).all((1, 2))
    pf = np.where(fin[:, None, None], pf, 0.5)
    expl = r14_expl(pf, W64)
    pay = np.stack([r14_payoff_fixa(pf, W64, n) for n in R14_ESTRAT], axis=1)
    return {"expl": expl, "curva": np.stack(curva, axis=1), "pay": pay, "regra_ok": (post.argmax(1) == htrue) if useR else np.full(S, np.nan), "post_max": post.max(1) if useR else np.full(S, np.nan),
            "consultas": nconsultas + (R14_K if f["D"] == "todas" else 0), "fin": fin, "ver": ver}


def _job_r14_rl(args):
    """Uma célula do BLOCO 21: (variante, método) → ajuste no DEV (12 sorteios × 3 sementes = 36 execuções) e avaliação ÚNICA da configuração escolhida em nc sementes de teste. Função de nível superior (roda em segundo plano)."""
    variante, metodo, desloc, nc = args[:4]
    T_, B_ = (args[4], args[5]) if len(args) > 4 else (None, None)
    t_cpu = time.process_time()
    sorts = r14_sorteios(metodo, variante, R14_NSORT)
    dev = [R14_SEM_DEV + desloc + j for j in range(R14_NDEV)]
    cfgs = [c for c in sorts for _ in dev]
    sds = [s for _ in sorts for s in dev]
    d = r14_treinar(metodo, cfgs, sds, variante, T_, B_)
    sc = (-d["expl"]).reshape(len(sorts), len(dev)).mean(1)
    b = int(np.argmax(sc))
    tst = [R14_SEM_C + desloc + j for j in range(nc)]
    r = r14_treinar(metodo, [sorts[b]] * nc, tst, variante, T_, B_)
    return {"variante": variante, "metodo": metodo, "cfg": sorts[b], "dev_best": float(-sc[b]), "dev_med": float(-np.median(sc)), "expl": r["expl"], "curva": r["curva"], "pay": r["pay"], "regra_ok": r["regra_ok"],
            "post_max": r["post_max"], "consultas": r["consultas"], "nfin": int((~r["fin"]).sum()), "dev_nfin": int((~d["fin"]).sum()), "cpu": time.process_time() - t_cpu}



# ----------------------------------------------------------------------
# BLOCO 22 — REPLICAÇÃO: tarefas NOVAS (variantes de espirais) e métodos do registro de replicação
# ----------------------------------------------------------------------
R14_TAREFAS_NOVAS = ("espirais_b", "espirais4")
R14_NOME_TN = {"espirais_b": "T8 espirais_b (duas espirais, giro 4π, ruído 0,06, 70 pontos/braço, 3% de ruído de rótulo; 2-16-16-1)", "espirais4": "T9 espirais4 (quatro braços, giro 3π, classe = braço mod 2, ruído 0,04, 40 pontos/braço; 2-16-16-1)"}
R10_ARQ.update({"espirais_b": [16, 16], "espirais4": [16, 16]})
R14_SEM_RDEV, R14_SEM_RC = 15300, 15400
R14_RMET = ("sistema", "minimo", "padrao", "sem_V")
R14_RARM = {"sistema": "ANVKM", "minimo": "N", "sem_V": "ANKM"}
R14_RNSORT, R14_RNDEV, R14_RNSORT_PAD = 12, 3, 4
R14_RHIPOT = ("Q1", "Q3", "Q4", "Q5")
R14_RDESC = {"Q1": ("sistema", "minimo", "sistema − minimo (original R12 espirais: +18,2 pp)"), "Q3": ("minimo", "padrao", "minimo − melhor padrão (original R12 espirais: −12,6 pp)"),
             "Q4": ("sistema", "padrao", "sistema − melhor padrão (original R12 espirais: +5,6 pp)"), "Q5": ("sistema", "sem_V", "sistema − sem_V (o verificador ajuda? sem original: não conta como replicação)")}
R14_ORIGINAL = {"Q1": +18.20, "Q3": -12.64, "Q4": +5.56}       # pp, R12 (relatório R12, bloco 19, espirais, 40 sementes, Holm confirmadas)


def r14_gerar_esp(tarefa: str, rng, por_braco: int, ruido_rot: float):
    if tarefa == "espirais_b":
        def gen(m):
            t = rng.uniform(0.15, 1.0, m)
            ang = 4.0 * math.pi * t
            return np.c_[t * np.cos(ang), t * np.sin(ang)] + 0.06 * rng.standard_normal((m, 2))
        a, b = gen(por_braco), gen(por_braco)
        X, y = np.r_[a, -b] * 2, np.r_[np.zeros(por_braco), np.ones(por_braco)]
    elif tarefa == "espirais4":
        Xs, ys = [], []
        for k in range(4):
            t = rng.uniform(0.15, 1.0, por_braco)
            ang = 3.0 * math.pi * t + k * math.pi / 2
            Xs.append(np.c_[t * np.cos(ang), t * np.sin(ang)] + 0.04 * rng.standard_normal((por_braco, 2)))
            ys.append(np.full(por_braco, float(k % 2)))
        X, y = np.concatenate(Xs) * 2, np.concatenate(ys)
    else:
        raise ValueError(tarefa)
    if ruido_rot > 0:
        y = np.where(rng.random(len(y)) < ruido_rot, 1.0 - y, y)
    return X, y


def r14_dados(tarefa: str, seed: int):
    """((Xtr, ytr), (Xte, yte)) das tarefas novas T8/T9 (pré-registro R14). RNG [semente, 14, 11]."""
    rng = np.random.default_rng([seed, 14, 11])
    if tarefa == "espirais_b":
        Xtr, ytr = r14_gerar_esp(tarefa, rng, 70, 0.03)
        Xte, yte = r14_gerar_esp(tarefa, rng, 400, 0.0)
    else:
        Xtr, ytr = r14_gerar_esp(tarefa, rng, 40, 0.0)
        Xte, yte = r14_gerar_esp(tarefa, rng, 300, 0.0)
    return (Xtr, ytr), (Xte, yte)


def r14_lago(tarefa: str, seed: int, n: int):
    """Lago NÃO ROTULADO (6n pontos da mesma distribuição; rótulo oculto sem ruído). RNG [semente, 14, 12]."""
    rng = np.random.default_rng([seed, 14, 12])
    m = R11_LAGO * n
    return r14_gerar_esp(tarefa, rng, m // 2 if tarefa == "espirais_b" else m // 4, 0.0)


def _r14_rs(rot: str, tarefa: str, desloc: int) -> int:
    return zlib.crc32(f"R14|{rot}|{tarefa}".encode("utf-8")) + desloc


def _job_r14_rep(args):
    """Uma célula do BLOCO 22: (tarefa, método) → ajuste com orçamento IGUAL (36 execuções DEV) e avaliação ÚNICA da vencedora em nc sementes novas."""
    tarefa, metodo, desloc, nc = args
    t_cpu = time.process_time()
    dev3 = [R14_SEM_RDEV + desloc + j for j in range(R14_RNDEV)]
    tst = [R14_SEM_RC + desloc + j for j in range(nc)]
    if metodo != "padrao":
        arm = R14_RARM[metodo]
        sorts = r13_sorteios_fixo(arm, tarefa, R14_RNSORT)
        cfgs = [c for c in sorts for _ in dev3]
        sds = [s for _ in sorts for s in dev3]
        d = r13_rodar(arm, tarefa, cfgs, sds, None, _r14_rs(f"dev{metodo}", tarefa, desloc))
        sc = d["acc"].reshape(len(sorts), len(dev3)).mean(1)
        b = int(np.argmax(sc))
        c = r13_rodar(arm, tarefa, [sorts[b]] * nc, tst, None, _r14_rs(f"teste{metodo}", tarefa, desloc))
        out = {"arm": arm, "cfg": sorts[b], "dev_best": float(sc[b]), "dev_med": float(np.median(sc)), "runs": len(sds)}
    else:
        melhor, runs = None, 0
        for m_ in R11_PADRAO:
            sorts = r13_sorteios_padrao(m_, tarefa, R14_RNSORT_PAD)
            cfgs = [c for c in sorts for _ in dev3]
            sds = [s for _ in sorts for s in dev3]
            d = r11_rodar(R11_SPEC[m_], tarefa, cfgs, sds, None, _r14_rs(f"devpad{m_}", tarefa, desloc))
            runs += len(sds)
            sc = d["acc"].reshape(len(sorts), len(dev3)).mean(1)
            b = int(np.argmax(sc))
            if melhor is None or sc[b] > melhor[0]:
                melhor = (float(sc[b]), m_, sorts[b], float(np.median(sc)))
        c = r11_rodar(R11_SPEC[melhor[1]], tarefa, [melhor[2]] * nc, tst, None, _r14_rs(f"testepad{melhor[1]}", tarefa, desloc))
        out = {"arm": melhor[1], "cfg": melhor[2], "dev_best": melhor[0], "dev_med": melhor[3], "runs": runs}
    out.update(tarefa=tarefa, metodo=metodo, acc=c["acc"], nfin=int((~c["fin"]).sum()), cpu=time.process_time() - t_cpu)
    return out


def _job_r14(args):
    """Despacho das células dos BLOCOS 21 e 22 (função de nível superior: roda em segundo plano). kind ∈ rl | longo | rep."""
    kind = args[0]
    if kind == "rl":
        return dict(_job_r14_rl(args[1:]), kind="rl")
    if kind == "longo":
        v, m_, desloc, nc = args[1:]
        return dict(_job_r14_rl((v, m_, desloc, nc, R14_LONGO[0], R14_LONGO[1])), kind="longo")
    if kind == "rep":
        return dict(_job_r14_rep(args[1:]), kind="rep")
    raise ValueError(kind)


def r14_tarefas(ctx):
    """Células dos BLOCOS 21 e 22 (mais pesadas primeiro). Mesma função para enviar ao segundo plano e para consumir."""
    if "r14_tar" in ctx.res_cache:
        return ctx.res_cache["r14_tar"]
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R14_DEV") else 0
    nc = 16 if rapido else R14_NC
    tar = []
    for v in R14_VARIANTES:
        for m_ in R14_METODOS:
            tar.append(("longo", v, m_, desloc, nc))
    for t in R14_TAREFAS_NOVAS:
        for m_ in R14_RMET:
            tar.append(("rep", t, m_, desloc, nc))
    for v in R14_VARIANTES:
        for m_ in R14_METODOS:
            tar.append(("rl", v, m_, desloc, nc))
    ctx.res_cache["r14_tar"] = (_job_r14, tar)
    return ctx.res_cache["r14_tar"]


def r14_celulas(ctx):
    """Resultados de todas as células (do segundo plano ou calculados na hora), memoizados no contexto."""
    if "r14_cel" not in ctx.res_cache:
        fn, tar = r14_tarefas(ctx)
        ctx.res_cache["r14_cel"] = mapa_ou_fundo(ctx, "r14a", fn, tar)
    return ctx.res_cache["r14_cel"]



# ----------------------------------------------------------------------
# BLOCO 21: análises (confirmatórias S1–S10 × 2 variantes, exploratórias, curvas) e relatório
# ----------------------------------------------------------------------
def r14_status(media, padj):
    return _status7(media, padj)


def r14_vereditos(st):
    """Vereditos pré-registrados (Parte S) a partir de st[(Sk, variante)] ∈ {'confirmada', 'refutada (piora)', 'nula'}."""
    V = R14_VARIANTES
    pos = lambda k: [v for v in V if st[(k, v)] == "confirmada"]
    neg = lambda k: [v for v in V if st[(k, v)].startswith("refutada")]
    s1p, s1n = pos("S1"), neg("S1")
    if s1p and not s1n:
        v1 = "O SISTEMA COMPLETO AJUDA"
    elif s1n and not s1p:
        v1 = "O SISTEMA COMPLETO PREJUDICA"
    else:
        v1 = "NULO/MISTO"
    comp = {k: (pos(k), neg(k)) for k in ("S4", "S5", "S6", "S7", "S8")}
    ajuda = [k for k, (p_, n_) in comp.items() if p_]
    prej = [k for k, (p_, n_) in comp.items() if n_]
    return {"v_sistema": v1, "componentes_ajudam": ajuda, "componentes_prejudicam": prej, "delirio_ajuda": bool(pos("S7")), "caos_especifico": bool(pos("S9")), "dic_ajuda": bool(pos("S3")),
            "s2": (pos("S2"), neg("S2")), "s10": (pos("S10"), neg("S10"))}


def r14_hipoteses_rl(R):
    """(Sk, variante) → (expl_a, expl_b, índice): Δ = expl(a) − expl(b)."""
    PA, i_ = {}, 0
    for v in R14_VARIANTES:
        for k in R14_HIPOT:
            i_ += 1
            a, b = R14_PAR[k]
            PA[(k, v)] = (R[(v, a)], R[(v, b)], i_)
    return PA


def r14_replica(sinal_orig: int, media: float, p_bruto: float, p_holm: float) -> str:
    """Regra de replicação pré-registrada (Parte Rp): 'replica' (mesmo sinal e Holm < 0,05), 'replica na direção (fraca)' (mesmo sinal, p bruto < 0,05, sem Holm), 'inverte' (sinal oposto com Holm < 0,05), senão 'não replica'."""
    mesmo = (media > 0) == (sinal_orig > 0)
    if mesmo and p_holm < 0.05:
        return "replica"
    if mesmo and p_bruto < 0.05:
        return "replica na direção (fraca)"
    if (not mesmo) and p_holm < 0.05:
        return "inverte"
    return "não replica"


def bloco21(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 21 — [R14] PROBLEMA ESTRUTURADO: jogo de cartas-PALAVRA (Kuhn generalizado, K=12 palavras, dicionário sintético, regra visível × OCULTA) com auto-jogo REINFORCE em numpy; baseline simples × sistema metacognitivo × ablações "
               "(12 métodos × 2 variantes, ajuste com orçamento IGUAL de 36 execuções DEV, 40 sementes novas, Holm sobre 20)")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R14_DEV") else 0
    nc = 16 if rapido else R14_NC
    ok_p = sha_ok(PREREG_R14_CORPO, PREREG_R14_CORPO_SHA256)
    rep.log(f"Integridade: pré-registro R14 (corpo) {PREREG_R14_CORPO_SHA256[:12]}… {'(CONFERE com versoes/prereg_r14.txt, carimbado 21:39 PT, ANTES de qualquer código de modelo da R14 e de qualquer execução com sementes R14; ' if ok_p else '(NÃO CONFERE!) ('}carimbo auto-atestado pelo relógio da máquina).")
    for nome, corpo, sh_, arq in (("Adendo 1", ADENDO1_R14_CORPO, ADENDO1_R14_CORPO_SHA256, "prereg_r14_adendo1.txt"), ("Adendo 2", ADENDO2_R14_CORPO, ADENDO2_R14_CORPO_SHA256, "prereg_r14_adendo2.txt")):
        if sh_:
            rep.log(f"{nome} ao pré-registro R14 ({'escrito DEPOIS do código e ANTES da primeira execução com as sementes registradas' if nome == 'Adendo 1' else 'declaração RETROATIVA das execuções registradas'}): {sh_[:12]}… "
                    f"{'(CONFERE com versoes/' + arq + ')' if sha_ok(corpo, sh_) else '(NÃO CONFERE!)'}")
            for l in corpo.split("\n")[1:]:
                if l.startswith("D"):
                    rep.log("  " + l.strip()[:300] + ("…" if len(l.strip()) > 300 else ""))
        else:
            rep.log(f"({nome} ainda não embutido: execução de desenvolvimento.)")
    if desloc:
        rep.log("!! R14_DEV=1: sementes DESLOCADAS em +10000 (execução de DEPURAÇÃO; NÃO é o resultado registrado).")
    if rapido:
        rep.log(f"(--rapido: {nc} sementes de teste em vez de {R14_NC}; o orçamento de ajuste não muda; resultados NÃO são os registrados.)")
    rep.log(f"Desenho (resumo do pré-registro): jogo de Kuhn generalizado com K={R14_K} cartas-PALAVRA ({', '.join(R14_PALAVRAS)}); cada palavra tem posto, classe (3) e um vetor de 'dicionário' SINTÉTICO de 6 números (posto e classe codificados com ruído 0,3). "
            "Variante VISÍVEL: maior posto vence. Variante OCULTA: a regra (reversa, trunfo de classe ou cíclica, por semente) NÃO é informada: tem de ser descoberta pelos showdowns. Política log-linear, REINFORCE em auto-jogo (T="
            f"{R14_T} iterações × B={R14_B} jogos), política avaliada = média dos últimos 25%. Medida primária: EXPLOITABILITY EXATA (menor = melhor; 0 = Nash), por enumeração das 132 distribuições de cartas. "
            f"Componentes: D dicionário com consulta orçamentada (Q={R14_Q} de {R14_K} palavras), C curiosidade na escolha, R descoberta de regra com verificador de hipóteses (10 hipóteses), F exploração ε filtrada por verificador, E delírio com saída forçada nos pesos, "
            "K caos estruturado (vs embaralhado), M monitores, L ruído Langevin (controle). 12 métodos; cada um recebe o MESMO orçamento de ajuste (12 sorteios × 3 sementes DEV = 36 execuções) e é avaliado UMA vez em "
            f"{nc} sementes NOVAS ({R14_SEM_C}–{R14_SEM_C + nc - 1}) em cada variante (ajustadas separadamente).")
    t1 = time.time()
    cel = r14_celulas(ctx)
    rep.log(f"(tempo de espera pelas células: {time.time() - t1:.1f}s, jobs={ctx.jobs})", vol=True)
    RL = {(c["variante"], c["metodo"]): c for c in cel if c["kind"] == "rl"}
    LG = {(c["variante"], c["metodo"]): c for c in cel if c["kind"] == "longo"}
    R = {k: c["expl"] for k, c in RL.items()}
    nfin = sum(c["nfin"] + c["dev_nfin"] for c in RL.values())
    rep.log(f"Execuções com política/pesos não finitos (contadas como política 0,5): {nfin} (de {sum(len(c['expl']) + 36 for c in RL.values())}).")
    rep.log(f"   (treino longo exploratório: {sum(c['nfin'] + c['dev_nfin'] for c in LG.values())} execuções não finitas de {sum(len(c['expl']) + 36 for c in LG.values())}; a divergência vem do ruído multiplicativo (delírio/Langevin) com Tw alto; execuções não finitas contam como política 0,5, o que as penaliza no ajuste DEV.)")
    ms = lambda v: f"{np.mean(v):.3f}±{np.std(v, ddof=1) / math.sqrt(len(v)):.3f}"
    for v in R14_VARIANTES:
        rep.sub(f"EXPLOITABILITY FINAL (chips; menor = melhor) — variante {R14_NOME_VAR[v]}; {nc} sementes; média ± erro-padrão")
        c0 = np.mean(RL[(v, "tab")]["curva"][:, 0])
        rep.log(f"(referência: a política inicial 0,5 em tudo tem exploitability {c0:.3f})")
        rep.log(f"{'método':<14}{'expl final':>14}{'AUC (curva)':>13}{'pay aleat.':>11}{'pay maníaca':>12}{'pay honesta':>12}{'consultas':>10}{'regra ok':>9}   hiperparâmetros escolhidos (DEV melhor / mediana dos sorteios)")
        for m_ in R14_METODOS:
            c = RL[(v, m_)]
            auc = c["curva"][:, 1:].mean(1)
            pay = c["pay"].mean(0)
            ro = np.nanmean(c["regra_ok"]) if np.isfinite(c["regra_ok"]).any() else float("nan")
            rep.log(f"{m_:<14}{ms(c['expl']):>14}{ms(auc):>13}{pay[0]:>11.3f}{pay[1]:>12.3f}{pay[2]:>12.3f}{np.mean(c['consultas']):>10.1f}{('%.2f' % ro) if np.isfinite(ro) else '   –':>9}   "
                    + ", ".join(f"{k}={x:.3g}" for k, x in c["cfg"].items()) + f" | DEV {c['dev_best']:.3f} / {c['dev_med']:.3f}")
    rep.sub("CURVAS DE APRENDIZADO (exploitability média da política média da janela, a cada 25 iterações; 0 = política inicial)")
    ck = [0] + list(range(R14_CK, R14_T + 1, R14_CK)) + ([R14_T] if R14_T % R14_CK else [])
    for v in R14_VARIANTES:
        rep.log(f"  variante {v}: iterações " + " ".join(f"{x:>5d}" for x in ck))
        for m_ in R14_METODOS:
            cm = RL[(v, m_)]["curva"].mean(0)
            rep.log(f"    {m_:<14}" + " ".join(f"{x:>5.2f}" for x in cm))
    # ---- confirmatórias
    PA = r14_hipoteses_rl(R)
    P = {}
    for k, (a_, b_, ii) in PA.items():
        cm = comparar_pareado(a_, b_, seed=ctx.seed + 14000 + ii)
        cm["mde"] = mde80(a_ - b_)
        P[k] = cm
    chaves = list(P)
    ph = dict(zip(chaves, holm([P[k]["p"] for k in chaves])))
    st = {k: r14_status(P[k]["media"], ph[k]) for k in chaves}
    rep.sub(f"CONFIRMATÓRIAS ({len(chaves)} = 10 × 2 variantes; Holm sobre {len(chaves)}; Δ = expl(primeiro) − expl(segundo) em chips, >0 favorece o SEGUNDO (S1–S3) / o componente AJUDA (S4–S10); permutação de sinais bicaudal, 10000; IC95% bootstrap pareado)")
    rep.log(f"{'id':<14}{'comparação':<86}{'Δ (chips)':>10}{'IC95%':>20}{'p':>9}{'p Holm':>9}{'MDE':>8}{'v/d':>8}  veredito")
    for k in chaves:
        cm, (h, v) = P[k], k
        rep.log(f"{h + '(' + v[:3] + ')':<14}{R14_DESC[h][:85]:<86}{cm['media']:>+10.4f}{'[' + format(cm['lo'], '+.4f') + ',' + format(cm['hi'], '+.4f') + ']':>20}{cm['p']:>9.4f}{ph[k]:>9.4f}{cm['mde']:>8.4f}{str(cm['vit']) + '/' + str(cm['der']):>8}  {st[k]}")
    VD = r14_vereditos(st)
    f_ = lambda ks: ", ".join(ks) if ks else "nenhum"
    rep.sub("EXPLORATÓRIAS (fora do Holm; p bruto sem correção) e descritivos")
    EX = {}
    for rot, (a, b) in (("E1 sis vs eps (o resto do sistema além da exploração ε?)", ("eps", "sis")), ("E2 lin vs lin_todas (o que valeria consultar TODAS as palavras?)", ("lin", "lin_todas")), ("E3 tab vs lin_todas", ("tab", "lin_todas"))):
        for v in R14_VARIANTES:
            cm = comparar_pareado(R[(v, a)], R[(v, b)], seed=ctx.seed + 14500 + len(EX))
            EX[(rot[:2], v)] = (cm["media"], cm["lo"], cm["hi"], cm["p"])
            rep.log(f"  {rot[:60]:<62}{v:<9} Δ={cm['media']:+.4f} IC[{cm['lo']:+.4f},{cm['hi']:+.4f}] p bruto={cm['p']:.4f} (expl(primeiro) − expl(segundo); >0 favorece o segundo)")
    auc = {(v, m_): RL[(v, m_)]["curva"][:, 1:].mean(1) for v in R14_VARIANTES for m_ in R14_METODOS}
    for v in R14_VARIANTES:
        d = auc[(v, "lin")] - auc[(v, "sis")]
        rep.log(f"  E4 AUC da curva, lin − sis ({v}): Δ={d.mean():+.4f} (>0 = o sistema aprende mais depressa em média) | sis vs melhor ablação por AUC: " + min(((m_, auc[(v, m_)].mean()) for m_ in R14_METODOS if m_.startswith("sis")), key=lambda x: x[1])[0])
    ro = {v: float(np.nanmean(RL[(v, "sis")]["regra_ok"])) for v in R14_VARIANTES}
    pm = {v: float(np.nanmean(RL[(v, "sis")]["post_max"])) for v in R14_VARIANTES}
    rep.log(f"  E5 descoberta de regra (sis): hipótese MAP = verdadeira ao final em {100 * ro['visivel']:.0f}% (visível) e {100 * ro['oculta']:.0f}% (oculta) das execuções; posterior máximo médio {pm['visivel']:.2f} / {pm['oculta']:.2f}; consultas usadas {np.mean(RL[('oculta', 'sis')]['consultas']):.1f} de {R14_K}.")
    rep.sub("Sensibilidade ao orçamento de treino (EXPLORATÓRIO, acrescentado depois do carimbo: ver Adendo 1): a mesma bateria com T=%d, B=%d (ajuste de novo no DEV; mesmo orçamento de 36 execuções)" % R14_LONGO)
    LGR = {k: c["expl"] for k, c in LG.items()}
    for v in R14_VARIANTES:
        rep.log(f"  variante {v}: expl final média ± EP — " + "; ".join(f"{m_} {ms(LGR[(v, m_)])}" for m_ in R14_METODOS))
    PL = {}
    for j, (k, (a, b)) in enumerate(R14_PAR.items()):
        for v in R14_VARIANTES:
            cm = comparar_pareado(LGR[(v, a)], LGR[(v, b)], seed=ctx.seed + 14700 + len(PL))
            PL[(k, v)] = (cm["media"], cm["lo"], cm["hi"], cm["p"])
    ph_l = dict(zip(PL, holm([x[3] for x in PL.values()])))
    rep.log("  Δ (chips) no treino longo, com p bruto e Holm sobre 20 (EXPLORATÓRIO; não entra no registro): " + "; ".join(f"{k}({v[:3]}) {PL[(k, v)][0]:+.4f} p={PL[(k, v)][3]:.3f}/H{ph_l[(k, v)]:.2f}" for v in R14_VARIANTES for k in R14_HIPOT))
    n_l = sum(ph_l[x] < 0.05 and PL[x][0] > 0 for x in PL)
    n_ln = sum(ph_l[x] < 0.05 and PL[x][0] < 0 for x in PL)
    rep.log(f"  No treino longo: {n_l} das 20 comparações ficam 'a favor' (Holm < 0,05) e {n_ln} 'contra'; no treino registrado: {sum(s == 'confirmada' for s in st.values())} a favor e {sum(s.startswith('refutada') for s in st.values())} contra.")
    best = {v: min(R14_METODOS, key=lambda m_: float(np.mean(R[(v, m_)]))) for v in R14_VARIANTES}
    rep.sub("VEREDITOS PRÉ-REGISTRADOS")
    rep.log(f"V-S1 (o sistema completo vs o baseline simples com dicionário, S1): {VD['v_sistema']} (S1 a favor em {f_([v for v in R14_VARIANTES if st[('S1', v)] == 'confirmada'])}; contra em {f_([v for v in R14_VARIANTES if st[('S1', v)].startswith('refutada')])}).")
    rep.log(f"V-S2 componentes que AJUDAM (S4–S8 confirmadas): {f_([k + ' (' + R14_NOME_S[k] + ')' for k in VD['componentes_ajudam']])}; que PREJUDICAM (refutadas): {f_([k + ' (' + R14_NOME_S[k] + ')' for k in VD['componentes_prejudicam']])}.")
    rep.log(f"V-S3 o delírio com saída forçada (E, S7) ajuda no RL: {'SIM' if VD['delirio_ajuda'] else 'NÃO'}; o caos ESTRUTURADO importa (S9): {'SIM' if VD['caos_especifico'] else 'NÃO'}; o canal do dicionário (S3) ajuda: {'SIM' if VD['dic_ajuda'] else 'NÃO'}.")
    rep.log(f"Menor exploitability média: " + "; ".join(f"{v}: {best[v]} ({np.mean(R[(v, best[v])]):.3f})" for v in R14_VARIANTES) + " (descritivo; escolhido no teste, otimista).")
    rep.log("Limites: (i) o jogo, o 'dicionário' sintético, os vetores e as regras ocultas são escolha minha (o canal foi desenhado para ser informativo); (ii) K=12 é pequeno e o aprendiz tabular (one-hot) já tem tudo o que os outros têm; (iii) REINFORCE em auto-jogo cicla e é ruidoso: o piso de exploitability fica "
            "perto de 0,1–0,2 chips; (iv) 12 métodos × 36 execuções DEV ruidosas: o sistema tem 6 hiperparâmetros contra 2 do baseline, o que favorece o baseline com ajuste de orçamento igual; (v) a 'descoberta de regra' é seleção entre 10 hipóteses que contêm a verdade por construção; "
            "(vi) 'nula' nunca prova ausência de efeito (MDE na tabela); (vi-b) cada método é ajustado por SUA PRÓPRIA busca aleatória ruidosa (12 sorteios × 3 sementes DEV), então as 'refutadas' de S2–S10 comparam duas configurações escolhidas com sorte diferente (o score DEV do vencedor é bem mais otimista que o do teste: maldição do vencedor), e parte da 'piora' é ruído de ajuste, não efeito do componente — o treino longo exploratório (T=500, B=64) dá outro conjunto de vencedores e perdedores; (vii) o treino longo é exploratório, acrescentado depois do carimbo.")
    rep.log(f"(tempo do bloco 21: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r14_rl"] = {"nc": nc, "P": {k: (P[k]["media"], P[k]["lo"], P[k]["hi"], P[k]["p"], float(ph[k]), P[k]["mde"]) for k in chaves}, "st": st, "VD": VD,
                         "expl": {k: float(np.mean(x)) for k, x in R.items()}, "auc": {k: float(np.mean(x)) for k, x in auc.items()}, "ro": ro, "EX": EX,
                         "pay": {k: [float(x) for x in c["pay"].mean(0)] for k, c in RL.items()}, "nl_pos": int(n_l), "nl_neg": int(n_ln), "melhor": best,
                         "cpu": float(sum(c["cpu"] for c in cel)), "longo": {k: float(np.mean(x)) for k, x in LGR.items()}}



# ----------------------------------------------------------------------
# BLOCO 22: replicação (Q1, Q3, Q4, Q5 × 2 tarefas novas) e REGISTRO DE REPLICAÇÃO
