def bloco22(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 22 — [R14] REPLICAÇÃO do efeito mais promissor das rodadas anteriores (R12: o sistema integrado em ESPIRAIS) em 2 variantes NOVAS da tarefa + REGISTRO DE REPLICAÇÃO "
               "(4 métodos × 2 tarefas, ajuste com orçamento IGUAL, 40 sementes novas, Holm sobre 8)")
    t0 = time.time()
    rapido = ctx.args.rapido
    desloc = 10000 if os.environ.get("R14_DEV") else 0
    nc = 16 if rapido else R14_NC
    if desloc:
        rep.log("!! R14_DEV=1: sementes DESLOCADAS em +10000 (execução de DEPURAÇÃO; NÃO é o resultado registrado).")
    rep.log("Tarefas NOVAS (definidas no pré-registro ANTES de qualquer resultado): " + "; ".join(R14_NOME_TN[t] for t in R14_TAREFAS_NOVAS) + ". Maquinaria: treinador configurável da R13 (sistema = ANVKM ≡ R11 'sistema', minimo = N ≡ R12 'mínimo', padrao = melhor de {real, aug_mixup, self_train} por DEV, sem_V = ANKM). "
            f"Ajuste: 36 execuções DEV por método (12 sorteios × 3 sementes {R14_SEM_RDEV}–{R14_SEM_RDEV + 2}; padrão: 3 métodos × 4 sorteios × 3 sementes); avaliação ÚNICA em {nc} sementes novas {R14_SEM_RC}–{R14_SEM_RC + nc - 1}.")
    cel = r14_celulas(ctx)
    RP = {(c["tarefa"], c["metodo"]): c for c in cel if c["kind"] == "rep"}
    R = {k: c["acc"] for k, c in RP.items()}
    ms = lambda v: f"{100 * np.mean(v):5.1f}±{100 * np.std(v, ddof=1) / math.sqrt(len(v)):<4.1f}"
    rep.sub(f"ACURÁCIA DE TESTE (%) das {nc} sementes confirmatórias, média ± erro-padrão")
    rep.log(f"{'método':<10}" + "".join(f"{t:>16}" for t in R14_TAREFAS_NOVAS))
    for m_ in R14_RMET:
        rep.log(f"{m_:<10}" + "".join(f"{ms(R[(t, m_)]):>16}" for t in R14_TAREFAS_NOVAS))
    rep.sub("O que cada método escolheu (braço = componentes ligados da R13; hiperparâmetros) e custo do ajuste")
    for t in R14_TAREFAS_NOVAS:
        for m_ in R14_RMET:
            c = RP[(t, m_)]
            rep.log(f"  {t:<11}{m_:<9} braço/método {str(c['arm']):<11}" + ", ".join(f"{k}={v:.3g}" for k, v in c["cfg"].items()) + f" | DEV melhor {100 * c['dev_best']:.1f}% (mediana dos sorteios {100 * c['dev_med']:.1f}%, {c['runs']} execuções) | teste {100 * R[(t, m_)].mean():.1f}% | não finitos {c['nfin']}")
    P, i_ = {}, 0
    for t in R14_TAREFAS_NOVAS:
        for k in R14_RHIPOT:
            i_ += 1
            a, b, _ = R14_RDESC[k]
            d = R[(t, a)] - R[(t, b)]
            cm = comparar_pareado(R[(t, a)], R[(t, b)], seed=ctx.seed + 14800 + i_)
            cm["mde"] = mde80(d)
            P[(k, t)] = cm
    chaves = list(P)
    ph = dict(zip(chaves, holm([P[k]["p"] for k in chaves])))
    st = {k: _status7(P[k]["media"], ph[k]) for k in chaves}
    rep.sub(f"CONFIRMATÓRIAS ({len(chaves)} = 4 × 2 tarefas; Holm sobre {len(chaves)}; Δ = acc(primeiro) − acc(segundo) em pp; permutação de sinais bicaudal, 10000)")
    rep.log(f"{'id':<16}{'comparação':<88}{'Δ (pp)':>9}{'IC95% (pp)':>20}{'p':>9}{'p Holm':>9}{'MDE':>7}{'v/d':>8}  veredito")
    for k in chaves:
        cm, (h, t) = P[k], k
        rep.log(f"{h + '(' + t + ')':<16}{R14_RDESC[h][2][:87]:<88}{100 * cm['media']:>+9.2f}{'[' + format(100 * cm['lo'], '+.2f') + ',' + format(100 * cm['hi'], '+.2f') + ']':>20}{cm['p']:>9.4f}{ph[k]:>9.4f}{100 * cm['mde']:>7.2f}{str(cm['vit']) + '/' + str(cm['der']):>8}  {st[k]}")
    rep.sub("REGISTRO DE REPLICAÇÃO (regra pré-registrada: 'replica' = mesmo sinal do original e Holm < 0,05; 'na direção' = mesmo sinal e p bruto < 0,05 sem Holm; 'inverte' = sinal oposto com Holm < 0,05)")
    rep.log(f"{'alvo (original R12, espirais)':<62}{'tarefa':<12}{'Δ novo (pp)':>12}{'IC95% (pp)':>20}{'original':>10}{'IC contém o original':>22}  classificação")
    CL = {}
    n_mag = 0
    for k in ("Q1", "Q3", "Q4"):
        for t in R14_TAREFAS_NOVAS:
            cm = P[(k, t)]
            CL[(k, t)] = r14_replica(R14_ORIGINAL[k], cm["media"], cm["p"], ph[(k, t)])
            dentro = 100 * cm["lo"] <= R14_ORIGINAL[k] <= 100 * cm["hi"]
            n_mag += int(dentro)
            rep.log(f"{R14_RDESC[k][2][:61]:<62}{t:<12}{100 * cm['media']:>+12.2f}{'[' + format(100 * cm['lo'], '+.2f') + ',' + format(100 * cm['hi'], '+.2f') + ']':>20}{R14_ORIGINAL[k]:>+10.2f}{('sim' if dentro else 'não'):>22}  {CL[(k, t)]}")
    n_rep = sum(v == "replica" for v in CL.values())
    n_dir = sum(v.startswith("replica na direção") for v in CL.values())
    n_inv = sum(v == "inverte" for v in CL.values())
    taxa = n_rep / len(CL)
    rep.log(f"MAGNITUDE: o IC95% do efeito novo contém o tamanho do efeito original em {n_mag} das {len(CL)} tentativas (a regra pré-registrada de replicação olha SINAL + Holm, não o tamanho: 'replica' pode significar 'mesmo sentido, efeito muito menor').")
    rep.log(f"TAXA DE REPLICAÇÃO (pré-registrada): {n_rep} replicações plenas de {len(CL)} tentativas = {100 * taxa:.0f}%; {n_dir} só na direção (fraca); {n_inv} invertidas; {len(CL) - n_rep - n_dir - n_inv} não replicam. "
            f"Q5 (verificador, sem original): " + ", ".join(f"{t}: {st[('Q5', t)]}" for t in R14_TAREFAS_NOVAS) + ".")
    rep.log("Tentativas de replicação ANTERIORES (copiadas do registro/relatórios das rodadas indicadas; descritivas; a classificação é minha):")
    for orig, rod, desc, res in R14_HISTORICO:
        rep.log(f"  • original: {orig} → replicação em {rod}: {desc} → {res}.")
    hist_ok = sum(r.startswith("replica") for _, _, _, r in R14_HISTORICO)
    rep.log(f"  Entre as {len(R14_HISTORICO)} tentativas históricas, {hist_ok} replicam (inclusive em parte); somando as 6 desta rodada: {hist_ok + n_rep} de {len(R14_HISTORICO) + len(CL)} (a mistura de critérios torna isto só uma ilustração).")
    veredito = ("O EFEITO REPLICA" if taxa >= 2 / 3 else "O EFEITO REPLICA EM PARTE" if n_rep >= 1 else "O EFEITO NÃO REPLICA")
    rep.log(f"VEREDITO DA REPLICAÇÃO (regra: ≥ 4 de 6 → replica; 1–3 → em parte; 0 → não replica): {veredito}.")
    rep.log("Limites: (i) as duas tarefas novas são variantes próximas (espirais), então 'replica' vale para vizinhança da tarefa original, não para outros domínios; (ii) 36 execuções DEV com 3 sementes são ruidosas e o sistema tem 7 hiperparâmetros contra 4 do mínimo; "
            "(iii) o original (R12) também foi obtido com este mesmo treinador e ajuste, então não é uma replicação independente de código; (iv) tarefas T8/T9 e a regra de replicação foram escolhidas por mim antes de rodar; (v) com 40 sementes o MDE80 está na tabela: 'não replica' pode ser falta de poder.")
    rep.log(f"(tempo do bloco 22: {time.time() - t0:.1f}s)", vol=True)
    ctx.res["r14_rep"] = {"nc": nc, "P": {k: (P[k]["media"], P[k]["lo"], P[k]["hi"], P[k]["p"], float(ph[k]), P[k]["mde"]) for k in chaves}, "st": st, "CL": CL, "n_rep": n_rep, "n_dir": n_dir, "n_inv": n_inv, "taxa": taxa, "veredito": veredito, "n_mag": n_mag,
                          "acc": {k: float(np.mean(x)) for k, x in R.items()}, "hist_ok": hist_ok, "hist_n": len(R14_HISTORICO), "cpu": float(sum(c["cpu"] for c in RP.values()))}



