    _comp_ok = np.allclose((_Phs[0] + _Phs[1])[_off], 1.0) and np.allclose((_Phs[8] + _Phs[8].T)[_off], 1.0) and np.allclose((_Phs[2] + _Phs[2].T)[_off], 1.0)
    _same_ok = all(np.array_equal(_Phs[h_][a, b], _Phs[0][a, b]) for h_ in (2, 3, 4, 5, 6, 7) for a in range(12) for b in range(12) if a != b and _cl0[a] == _cl0[b])
    _wk = all(np.array_equal(_mu[k]["W"][_off], (2 * r14_vitoria_hip(_mu[k]["h"], _mu[k]["rk"].astype(float), _mu[k]["cl"]) - 1)[_off]) for k in _mu)
    t("R14: as 10 hipóteses do agente são matrizes de vitória distintas; natural/reversa e cíclica/trunfo são antissimétricas e completas (P(a>b) + P(b>a) = 1); trunfo de classe respeita 'mesma classe → maior posto'; a hipótese verdadeira da semente reproduz W exatamente",
      _dist and _comp_ok and _same_ok and _wk)
    # --- pagamento exato × Monte Carlo; exploitability exata × força bruta
    _rg = np.random.default_rng(11)
    _p = _rg.random((3, 4, 12))
    _Wm = np.stack([_mu[(25200, "oculta")]["W"], _mu[(25201, "visivel")]["W"], _mu[(25202, "oculta")]["W"]])
    _val = r14_valor((_p[:, 0], _p[:, 1]), (_p[:, 2], _p[:, 3]), _Wm)
    _mc = np.array([_t14_mc_valor(_p[k, 0], _p[k, 1], _p[k, 2], _p[k, 3], _Wm[k], 300000, np.random.default_rng(100 + k)) for k in range(3)])
    _half = np.full((1, 12), 0.5)
    t("R14: pagamento esperado EXATO de J1 (enumeração das 132 mãos) coincide com a simulação direta das regras (300 mil jogos, tolerância 0,02); com todas as probabilidades 0,5 o valor de J1 é o analítico 0,125 (0,5·(0,5·1) − 0,5·0,5·0,5)",
      float(np.abs(_val - _mc).max()) < 0.02 and abs(float(r14_valor((_half, _half), (_half, _half), _Wm[:1])[0]) - 0.125) < 1e-9)
    z1 = np.zeros((1, 12))

    def _melhor_j1(k):
        base = r14_valor((z1, z1), (_p[k:k + 1, 2], _p[k:k + 1, 3]), _Wm[k:k + 1])[0]
        tot = base
        for c in range(12):
            vs = []
            for ao in (0.0, 1.0):
                for af in (0.0, 1.0):
                    po, pf = z1.copy(), z1.copy()
                    po[0, c], pf[0, c] = ao, af
                    vs.append(r14_valor((po, pf), (_p[k:k + 1, 2], _p[k:k + 1, 3]), _Wm[k:k + 1])[0] - base)
            tot += max(vs)
        return tot

    def _melhor_j2(k):
        base = r14_valor((_p[k:k + 1, 0], _p[k:k + 1, 1]), (z1, z1), _Wm[k:k + 1])[0]
