def r16_desloc() -> int:
    v = os.environ.get("R16_DEV", "").strip().lower()
    return 10000 if v not in ("", "0", "false", "no", "off") else 0


def r16_crc(rot: str) -> int:
    return zlib.crc32(f"R16|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r16_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


# ======================================================================
# G — JOGO RAPHAEL (tabuleiro 4×4 + cartas + palavra↔número)
# ======================================================================

def r16_vec_palavra(w: str, dim: int = 8) -> np.ndarray:
    rng = np.random.default_rng(zlib.crc32(("r16w::" + w).encode()) & 0xFFFFFFFF)
    return rng.standard_normal(dim) / (np.linalg.norm(rng.standard_normal(dim)) + 1e-12)


def r16_vec_numero(n: int, dim: int = 8) -> np.ndarray:
    ang = 2 * math.pi * ((n - 1) % 12) / 12.0
    v = np.zeros(dim)
    v[0] = math.cos(ang)
    v[1] = math.sin(ang)
    if dim > 2:
        v[2] = math.cos(2 * ang)   # cosseno duplo
        v[3] = math.sin(2 * ang)
    return v / (np.linalg.norm(v) + 1e-12)


def r16_coerencia(w: str, n: int) -> float:
    a, b = r16_vec_palavra(w), r16_vec_numero(n)
    c = float(np.dot(a, b))
    # cosseno duplo: cos(2θ) = 2c² − 1
    return 2.0 * c * c - 1.0


def r16_baralho(rng) -> List[Tuple[str, int]]:
    idx = rng.permutation(len(R16_PALAVRAS))[:24]
    return [(R16_PALAVRAS[i], int(rng.integers(1, 13))) for i in idx]


def r16_pos_valor(y: int, x: int) -> float:
    if (y, x) in ((1, 1), (1, 2), (2, 1), (2, 2)):
        return 1.0
    if y in (0, 3) and x in (0, 3):
        return -0.5
    return 0.0


def r16_estado0(rng):
    # peças: jogador 0 = +1 (rei em (0,1), torre em (0,2)); jogador 1 = -1 (rei (3,1), torre (3,2))
    board = np.zeros((4, 4), dtype=np.int8)
    board[0, 1] = 1   # rei
    board[0, 2] = 2   # torre
    board[3, 1] = -1
    board[3, 2] = -2
    deck = r16_baralho(rng)
    return board, deck, 0  # board, deck, turno_jogador


def r16_pecas(board, jog: int):
    s = 1 if jog == 0 else -1
    out = []
    for y in range(4):
        for x in range(4):
            v = int(board[y, x])
            if v * s > 0:
                out.append((y, x, abs(v)))  # tipo 1=rei, 2=torre
    return out


def r16_movimentos(board, jog: int):
    moves = []
    s = 1 if jog == 0 else -1
    for y, x, tipo in r16_pecas(board, jog):
        dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        reach = 1 if tipo == 1 else 2
        for dy, dx in dirs:
            for k in range(1, reach + 1):
                ny, nx = y + dy * k, x + dx * k
                if not (0 <= ny < 4 and 0 <= nx < 4):
                    break
                alvo = int(board[ny, nx])
                if alvo * s > 0:
                    break
                moves.append((y, x, ny, nx))
                if alvo * s < 0:
                    break
    return moves


def r16_aplicar(board, mv):
    y, x, ny, nx = mv
    b = board.copy()
    cap = int(b[ny, nx])
    b[ny, nx] = b[y, x]
    b[y, x] = 0
    return b, cap


def r16_features(board, carta, jog: int) -> np.ndarray:
    s = 1 if jog == 0 else -1
    f = np.zeros(20, dtype=np.float64)
    # 16 casas normalizadas
    f[:16] = (board.reshape(-1).astype(np.float64) * s) / 2.0
    w, n = carta
    f[16] = r16_coerencia(w, n)
    f[17] = (n - 6.5) / 6.5
    f[18] = r16_pos_valor(*divmod(int(np.argmax(np.abs(board))), 4)) if board.any() else 0.0
    f[19] = float(len(r16_pecas(board, jog)) - len(r16_pecas(board, 1 - jog)))
    return f


def r16_score_pos(board, jog: int) -> float:
    s = 1 if jog == 0 else -1
    tot = 0.0
    for y in range(4):
        for x in range(4):
            v = int(board[y, x])
            if v * s > 0:
                tot += r16_pos_valor(y, x) + (0.5 if abs(v) == 1 else 0.2)
            elif v * s < 0:
                tot -= r16_pos_valor(y, x)
    return tot


def r16_escolher(metodo: str, board, carta, jog: int, theta, rng, oculta: bool, limiar: float = -0.2, temp: float = 1.0):
    moves = r16_movimentos(board, jog)
    if not moves:
        return None, 0.0
    w, n = carta
    coh = r16_coerencia(w, n)
    if metodo == "aleatorio":
        return moves[int(rng.integers(len(moves)))], coh
    if metodo == "guloso_tab":
        best, bv = moves[0], -1e9
        for mv in moves:
            b2, cap = r16_aplicar(board, mv)
            val = r16_score_pos(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
            if val > bv:
                best, bv = mv, val
        return best, coh
    if metodo == "guloso_carta":
        # ignora tabuleiro: joga o 1º movimento legal; a "escolha" é só a carta (já comprada)
        return moves[0], coh
    # linear / meta
    feats = []
    for mv in moves:
        b2, cap = r16_aplicar(board, mv)
        f = r16_features(b2, carta, jog)
        f = np.concatenate([f, [3.0 if abs(cap) == 1 else (1.5 if cap else 0.0), coh if not oculta else 0.0]])
        feats.append(f)
    F = np.asarray(feats)
    th = theta if theta is not None else np.zeros(F.shape[1])
    logits = F @ th
    if metodo == "meta":
        # incerteza: se entropia alta, mistura com uniforme; filtra carta estranha
        p = np.exp(logits - logits.max())
        p = p / p.sum()
        H = float(-(p * np.log(p + 1e-12)).sum())
        if H > math.log(len(p)) * 0.7:
            logits = logits * 0.3
        if coh < limiar and not oculta:
            logits = logits - 0.5
    logits = logits / max(temp, 1e-6)
    p = np.exp(logits - logits.max())
    p = p / p.sum()
    i = int(rng.choice(len(moves), p=p))
    return moves[i], coh


def r16_partida(metodo: str, theta, seed: int, oculta: bool, limiar: float = -0.2, temp: float = 1.0,
                oponente: str = "guloso_tab") -> float:
    rng = r16_rng(seed, r16_crc(metodo), 7)
    board, deck, _ = r16_estado0(rng)
    di = 0
    pts = [0.0, 0.0]
    for t in range(16):
        jog = t % 2
        if di >= len(deck):
            break
        carta = deck[di]
        di += 1
        met = metodo if jog == 0 else oponente
        th = theta if jog == 0 else None
        mv, coh = r16_escolher(met, board, carta, jog, th, rng, oculta and met == metodo, limiar, temp)
        if mv is None:
            break
        board, cap = r16_aplicar(board, mv)
        ganho = r16_pos_valor(mv[2], mv[3]) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
        if not oculta or met != metodo:
            ganho = ganho + 0.5 * coh
        else:
            ganho = ganho + 0.5 * coh   # recompensa total inclui coerência mesmo oculta; agente linear/meta não vê coh nas features
        pts[jog] += ganho
        # mate: rei capturado
        if abs(cap) == 1:
            pts[jog] += 5.0
            break
    return pts[0] - pts[1]


def r16_treinar_linear(seed: int, oculta: bool, lr: float, temp: float, limiar: float, meta: bool,
                       n_train: int = R16_NTRAIN_G) -> np.ndarray:
    rng = r16_rng(seed, r16_crc("train"), 11)
    dim = 22
    theta = rng.normal(0, 0.05, size=dim)
    baseline = 0.0
    for ep in range(n_train):
        # uma partida com coleta de (feat, ação) — REINFORCE simples
        rng_ep = r16_rng(seed, ep, 13)
        board, deck, _ = r16_estado0(rng_ep)
        di = 0
        logps = []
        feats_ch = []
        reward = 0.0
        for t in range(16):
            jog = t % 2
            if di >= len(deck):
                break
            carta = deck[di]
            di += 1
            if jog == 0:
                moves = r16_movimentos(board, jog)
                if not moves:
                    break
                F = []
                for mv in moves:
                    b2, cap = r16_aplicar(board, mv)
                    f = r16_features(b2, carta, jog)
                    coh = r16_coerencia(*carta)
                    F.append(np.concatenate([f, [3.0 if abs(cap) == 1 else (1.5 if cap else 0.0), 0.0 if oculta else coh]]))
                F = np.asarray(F)
                logits = F @ theta / max(temp, 1e-6)
                if meta:
                    p0 = np.exp(logits - logits.max()); p0 = p0 / p0.sum()
                    if float(-(p0 * np.log(p0 + 1e-12)).sum()) > math.log(len(p0)) * 0.7:
                        logits = logits * 0.3
                    if (not oculta) and r16_coerencia(*carta) < limiar:
                        logits = logits - 0.5
                p = np.exp(logits - logits.max()); p = p / p.sum()
                i = int(rng_ep.choice(len(moves), p=p))
                logps.append(math.log(p[i] + 1e-12))
                feats_ch.append(F[i])
                board, cap = r16_aplicar(board, moves[i])
                coh = r16_coerencia(*carta)
                reward += r16_pos_valor(moves[i][2], moves[i][3]) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0)) + 0.5 * coh
                if abs(cap) == 1:
                    reward += 5.0
                    break
            else:
                mv, coh = r16_escolher("guloso_tab", board, carta, jog, None, rng_ep, False)
                if mv is None:
                    break
                board, cap = r16_aplicar(board, mv)
                reward -= r16_pos_valor(mv[2], mv[3]) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0)) + 0.5 * coh
                if abs(cap) == 1:
                    reward -= 5.0
                    break
        adv = reward - baseline
        baseline = 0.9 * baseline + 0.1 * reward
        for lp, f in zip(logps, feats_ch):
            # gradiente REINFORCE: d logπ / dθ ≈ f (softmax linear)
            theta += lr * adv * f
        theta *= 0.999  # weight decay leve
    return theta


def r16_eval_metodo(metodo: str, seed: int, oculta: bool, hp: dict, n_eval: int = R16_NEVAL_G, n_train: int = R16_NTRAIN_G) -> float:
    lr = float(hp.get("lr", 0.05))
    temp = float(hp.get("temp", 1.0))
    limiar = float(hp.get("limiar", -0.2))
    if metodo in ("linear", "meta"):
        theta = r16_treinar_linear(seed, oculta, lr, temp, limiar, meta=(metodo == "meta"), n_train=n_train)
    else:
        theta = None
    tots = [r16_partida(metodo, theta, seed * 10007 + k, oculta, limiar, temp) for k in range(n_eval)]
    return float(np.mean(tots))


def r16_sorteio_hp(metodo: str, i: int) -> dict:
    rng = r16_rng(r16_crc(metodo), 16, i)
    return {
        "lr": float(10 ** rng.uniform(-2.0, -0.7)),
        "temp": float(10 ** rng.uniform(-0.3, 0.5)),
        "limiar": float(rng.uniform(-0.5, 0.1)),
    }


def r16_ajustar(metodo: str, oculta: bool, seeds_dev: List[int], n_sort: int = R16_NSORT_G) -> dict:
    best, best_s = None, -1e18
    # métodos sem HP: 1 "sorteio" dummy
    n = 1 if metodo in ("aleatorio", "guloso_tab", "guloso_carta") else n_sort
    for i in range(n):
        hp = r16_sorteio_hp(metodo, i) if n > 1 else {"lr": 0.05, "temp": 1.0, "limiar": -0.2}
        # DEV barato: menos partidas
        scores = [r16_eval_metodo(metodo, s, oculta, hp, n_eval=16, n_train=40) for s in seeds_dev]
        m = float(np.mean(scores))
        if m > best_s:
            best_s, best = m, hp
    return best


# ======================================================================
# W — INVENÇÃO-E-VALIDAÇÃO
# ======================================================================

def r16_markov_letras(palavras, ordem: int = 2):
    from collections import defaultdict
    trans = defaultdict(lambda: defaultdict(int))
    for w in palavras:
        w = "^" * ordem + w.lower() + "$"
        for i in range(len(w) - ordem):
            trans[w[i:i + ordem]][w[i + ordem]] += 1
    # normaliza
    P = {}
    for k, d in trans.items():
        tot = sum(d.values())
        P[k] = {c: v / tot for c, v in d.items()}
    return P


def r16_inventar(P, rng, maxlen: int = 10) -> str:
    ordem = len(next(iter(P)))
    s = "^" * ordem
    out = []
    for _ in range(maxlen + 2):
        dist = P.get(s[-ordem:], None)
        if not dist:
            break
        cs, ps = zip(*dist.items())
        c = cs[int(rng.choice(len(cs), p=ps))]
        if c == "$":
            break
        if c != "^":
            out.append(c)
        s += c
    return "".join(out) or "x"


def r16_oraculo_offline(w: str) -> bool:
    """Oráculo simulador determinístico: hit se hash < p(len)."""
    L = len(w)
    p = 0.35 if 4 <= L <= 8 else (0.15 if L in (3, 9, 10) else 0.05)
    u = (zlib.crc32(("hit::" + w).encode()) & 0xFFFFFFFF) / 2**32
    return u < p or w in R16_PALAVRAS


def r16_map_palavra_num(w: str) -> np.ndarray:
    """4 técnicas → vetor 4-D normalizado."""
    h = zlib.crc32(w.encode()) & 0xFFFFFFFF
    soma = sum((ord(c) - 96) for c in w.lower() if c.isalpha()) % 100
    bits = [(h >> i) & 1 for i in range(8)]
    tern = sum((b * 2 - 1) * (3 ** i) for i, b in enumerate(bits[:6]))
    ang = 2 * math.pi * h / 2**32
    v = np.array([
        (h % 97) / 97.0,
        soma / 100.0,
        (tern % 100) / 100.0,
        (math.cos(ang) + 1) / 2,
    ], dtype=np.float64)
    return v / (np.linalg.norm(v) + 1e-12)


def r16_coerencia_nonce(w: str, lake_vecs: Dict[str, np.ndarray]) -> float:
    vw = r16_map_palavra_num(w)
    if not lake_vecs:
        return float(np.dot(vw, r16_map_palavra_num("word")))
    # vizinho mais próximo no lake
    best = -1.0
    for v in lake_vecs.values():
        best = max(best, float(np.dot(vw, v)))
    return best


def r16_juiz_faz_sentido(w: str, lake_vecs: Dict[str, np.ndarray]) -> bool:
    if not (4 <= len(w) <= 10):
        return False
    return r16_coerencia_nonce(w, lake_vecs) >= 0.25


def r16_jogo_sentidos(w: str, K: int, rng, lake_vecs) -> float:
    """Replicator dinâmico: K sentidos = vizinhos aleatórios do lake; utilidade = coerência − λ overlap."""
    keys = list(lake_vecs.keys()) or list(R16_PALAVRAS)
    escolhidos = [keys[i] for i in rng.choice(len(keys), size=min(K, len(keys)), replace=False)]
    V = np.array([lake_vecs.get(k, r16_map_palavra_num(k)) for k in escolhidos])
    vw = r16_map_palavra_num(w)
    coh = V @ vw
    # overlap
    G = V @ V.T
    x = np.ones(len(escolhidos)) / len(escolhidos)
    for _ in range(20):
        pay = coh - 0.3 * (G @ x)
        pay = pay - pay.max()
        x = x * np.exp(pay)
        x = x / x.sum()
    return float(coh @ x)


def r16_lake_vecs() -> Dict[str, np.ndarray]:
    return {w: r16_map_palavra_num(w) for w in R16_PALAVRAS}


def r16_inventa_metodo(metodo: str, seed: int, hp: dict, n: int = R16_NINV_W) -> float:
    rng = r16_rng(seed, r16_crc(metodo + "inv"), 3)
    P = r16_markov_letras(R16_PALAVRAS)
    lake = r16_lake_vecs()
    tau = float(hp.get("tau", 0.3))
    ok = 0
    for i in range(n):
        if metodo == "baseline_aleatorio":
            L = int(rng.integers(4, 11))
            w = "".join(chr(int(rng.integers(97, 123))) for _ in range(L))
        else:
            w = r16_inventar(P, rng)
        if metodo == "inventa_bruta":
            aceita = True
        elif metodo == "inventa_filtro":
            aceita = r16_oraculo_offline(w) or r16_coerencia_nonce(w, lake) > tau
        elif metodo == "inventa_jogo":
            aceita = (r16_oraculo_offline(w) or r16_coerencia_nonce(w, lake) > tau) and r16_jogo_sentidos(w, 5, rng, lake) > tau
        else:
            aceita = True
        if aceita and r16_juiz_faz_sentido(w, lake):
            ok += 1
        elif aceita and metodo == "inventa_bruta" and r16_juiz_faz_sentido(w, lake):
            ok += 1
    return ok / max(n, 1)


def r16_sorteio_hp_w(i: int) -> dict:
    rng = r16_rng(r16_crc("W"), 16, i)
    return {"tau": float(rng.uniform(0.15, 0.45))}


def r16_ajustar_w(metodo: str, seeds_dev: List[int], n_sort: int = R16_NSORT_W) -> dict:
    if metodo == "baseline_aleatorio":
        return {"tau": 0.3}
    best, best_s = {"tau": 0.3}, -1.0
    for i in range(n_sort):
        hp = r16_sorteio_hp_w(i)
        m = float(np.mean([r16_inventa_metodo(metodo, s, hp, n=30) for s in seeds_dev]))
        if m > best_s:
            best_s, best = m, hp
    return best


# ======================================================================
# D — DELÍRIO → ESCRUTÍNIO (propostas de componentes)
# ======================================================================

R16_GRAMATICA = (
    ("monitor_entropia", "ent"),
    ("filtro_confianca", "conf"),
    ("agenda_ruido", "noise"),
    ("voto_vizinhos", "knn"),
    ("prior_exploracao", "prior"),
    ("calibre_ece", "ece"),
)


def r16_propor(rng, T: float) -> dict:
    """Amostra um componente da gramática fechada (seguro: sem exec de código)."""
    logits = rng.normal(0, 1, size=len(R16_GRAMATICA)) / max(T, 1e-3)
    # bias por tipo
    p = np.exp(logits - logits.max()); p = p / p.sum()
    i = int(rng.choice(len(R16_GRAMATICA), p=p))
    nome, tag = R16_GRAMATICA[i]
    return {
        "nome": f"{nome}_{rng.integers(0, 1000)}",
        "tag": tag,
        "peso": float(rng.uniform(0.1, 1.0)),
        "limiar": float(rng.uniform(0.2, 0.8)),
        "T": T,
    }


def r16_espirais(n: int, seed: int):
    rng = r16_rng(seed, 99)
    t = rng.uniform(0, 2 * math.pi, n)
    r = t + rng.normal(0, 0.2, n)
    x = np.stack([r * np.cos(t), r * np.sin(t)], 1)
    y = (t > math.pi).astype(np.float64)
    # segunda classe espelhada
    t2 = rng.uniform(0, 2 * math.pi, n)
    r2 = t2 + rng.normal(0, 0.2, n)
    x2 = np.stack([-r2 * np.cos(t2), -r2 * np.sin(t2)], 1)
    X = np.concatenate([x, x2])
    Y = np.concatenate([np.zeros(n), np.ones(n)])
    return X.astype(np.float64), Y.astype(np.float64)


def r16_mlp_treino(X, Y, passos: int, seed: int, componente=None, shuffle_y: bool = False):
    rng = r16_rng(seed, 17)
    Yt = Y.copy()
    if shuffle_y:
        Yt = rng.permutation(Yt)
    W1 = rng.normal(0, 0.5, size=(2, 6))
    b1 = np.zeros(6)
    W2 = rng.normal(0, 0.5, size=(6, 1))
    b2 = np.zeros(1)
    lr0 = 0.2
    for p in range(passos):
        # agenda de ruído / lr (componente noise): recozimento seno
        lr = lr0
        if componente is not None and componente["tag"] == "noise":
            lr = lr0 * (0.5 + 0.5 * abs(math.sin(p / max(3.0, 8.0 * componente["peso"]))))
        h = np.tanh(X @ W1 + b1)
        if componente is not None:
            tag = componente["tag"]
            if tag == "noise":
                h = h + componente["peso"] * 0.15 * rng.normal(0, 1, h.shape) * math.cos(p / 4)
            elif tag == "ent":
                logits = h @ W2 + b2
                pr = 1 / (1 + np.exp(-np.clip(logits.ravel(), -20, 20)))
                ent = -(pr * np.log(pr + 1e-9) + (1 - pr) * np.log(1 - pr + 1e-9))
                h = h * (1.0 - 0.5 * componente["peso"] * (ent > componente["limiar"]).astype(float)).reshape(-1, 1)
            elif tag == "knn":
                h = h + componente["peso"] * 0.08 * np.tanh(h)
            elif tag == "prior":
                h = h + componente["peso"] * 0.1
            elif tag == "ece":
                h = h * (1.0 - 0.1 * componente["peso"])
        logits = h @ W2 + b2
        pr = 1 / (1 + np.exp(-np.clip(logits.ravel(), -20, 20)))
        err = (pr - Yt).reshape(-1, 1)
        w = np.ones_like(pr)
        if componente is not None and componente["tag"] == "conf":
            w = 0.3 + 0.7 * (np.abs(pr - 0.5) > (0.05 + 0.2 * componente["limiar"])).astype(float)
        g2 = (h * w.reshape(-1, 1)).T @ err / len(Y)
        gb2 = (err.ravel() * w).mean()
        dh = (err * w.reshape(-1, 1)) @ W2.T * (1 - h ** 2)
        g1 = X.T @ dh / len(Y)
        gb1 = dh.mean(0)
        W2 -= lr * g2
        b2 -= lr * gb2
        W1 -= lr * g1
        b1 -= lr * gb1
    h = np.tanh(X @ W1 + b1)
    pr = 1 / (1 + np.exp(-np.clip((h @ W2 + b2).ravel(), -20, 20)))
    acc = float(((pr > 0.5) == Yt).mean())
    # ECE simples
    ece = 0.0
    for lo in np.linspace(0, 1, 5)[:-1]:
        m = (pr >= lo) & (pr < lo + 0.2)
        if m.any():
            ece += float(m.mean() * abs(pr[m].mean() - Yt[m].mean()))
    return acc, ece, (W1, b1, W2, b2)


def r16_avaliar_proposta(comp, seed: int) -> dict:
    """Laudo V1–V4 num toy espirais minúsculo."""
    Xtr, Ytr = r16_espirais(40, seed)
    Xte, Yte = r16_espirais(30, seed + 1)
    acc_c, ece_c, _ = r16_mlp_treino(Xtr, Ytr, 40, seed + 2, componente=comp)
    # avaliar no teste
    W1, b1, W2, b2 = _
    h = np.tanh(Xte @ W1 + b1)
    pr = 1 / (1 + np.exp(-np.clip((h @ W2 + b2).ravel(), -20, 20)))
    acc_te = float(((pr > 0.5) == Yte).mean())
    # baseline sem componente
    acc_b, ece_b, wb = r16_mlp_treino(Xtr, Ytr, 40, seed + 2, componente=None)
    h = np.tanh(Xte @ wb[0] + wb[1])
    pr = 1 / (1 + np.exp(-np.clip((h @ wb[2] + wb[3]).ravel(), -20, 20)))
    acc_te_b = float(((pr > 0.5) == Yte).mean())
    # V2 shuffle
    acc_s, _, _ = r16_mlp_treino(Xtr, Ytr, 40, seed + 3, componente=comp, shuffle_y=True)
    # sementes frescas (V1): outra semente
    Xte2, Yte2 = r16_espirais(30, seed + 50)
    h = np.tanh(Xte2 @ W1 + b1)
    pr = 1 / (1 + np.exp(-np.clip((h @ W2 + b2).ravel(), -20, 20)))
    acc_f = float(((pr > 0.5) == Yte2).mean())
    h = np.tanh(Xte2 @ wb[0] + wb[1])
    pr = 1 / (1 + np.exp(-np.clip((h @ wb[2] + wb[3]).ravel(), -20, 20)))
    acc_f_b = float(((pr > 0.5) == Yte2).mean())
    delta = acc_f - acc_f_b
    V1 = delta > 0.0
    V2 = acc_s < 0.60   # sem sinal com rótulos embaralhados
    V3 = (acc_te - acc_te_b) > 0.0
    V4 = ece_c <= ece_b + 0.05
    mantem = bool(V1 and V2 and V3 and V4)
    return {"mantem": mantem, "delta": delta, "V1": V1, "V2": V2, "V3": V3, "V4": V4, "acc": acc_te}


def r16_laco_delirio(cond: str, seed: int, hp: dict, nprop: int = R16_NPROP_D) -> float:
    rng = r16_rng(seed, r16_crc(cond), 5)
    T_hi = float(hp.get("T_hi", 1.5))
    T_lo = float(hp.get("T_lo", 0.3))
    escrut = "escrut" in cond
    delirio = "delirio" in cond
    T = T_hi if delirio else T_lo
    mantidas_uteis = 0
    for i in range(nprop):
        comp = r16_propor(rng, T)
        if not escrut:
            # aceita se confiança proxy > 0.5
            if r16_coerencia(comp["tag"], int(comp["peso"] * 12) % 12 + 1) > -0.1:
                # avalia utilidade sem laudo completo
                r = r16_avaliar_proposta(comp, seed + 100 + i)
                if r["delta"] > 0.0:
                    mantidas_uteis += 1
        else:
            r = r16_avaliar_proposta(comp, seed + 100 + i)
            if r["mantem"]:
                mantidas_uteis += 1
    return float(mantidas_uteis)


def r16_sorteio_hp_d(i: int) -> dict:
    rng = r16_rng(r16_crc("D"), 16, i)
    return {"T_hi": float(rng.uniform(1.0, 2.5)), "T_lo": float(rng.uniform(0.15, 0.5))}


def r16_ajustar_d(cond: str, seeds_dev: List[int], n_sort: int = R16_NSORT_D) -> dict:
    best, best_s = {"T_hi": 1.5, "T_lo": 0.3}, -1.0
    for i in range(n_sort):
        hp = r16_sorteio_hp_d(i)
        m = float(np.mean([r16_laco_delirio(cond, s, hp, nprop=8) for s in seeds_dev]))
        if m > best_s:
            best_s, best = m, hp
    return best


# ======================================================================
# B — DEBATE MULTIAGENTE
# ======================================================================

def r16_evidencias(seed: int) -> dict:
    """Evidências DETERMINÍSTICAS do 'relatório' (proxies fixos do registro R1–R15)."""
    return {
        "delirio_redes_reais_confirmado": 0,   # R9: 0
        "filtro_ajuda_as_vezes": 1,
        "docstring_honesta": 1,
        "n_conf_delirio_pesos": 0,
        "n_conf_verificador": 1,
        "alegou_consciencia": 0,
    }


def r16_score_agente(lado: str, afirm, ev: dict) -> float:
    tipo, texto = afirm
    base = 0.0
    if lado == "cetico":
        base += 1.0 if tipo == "nao" else -1.0
        base += 0.5 * (1 - ev["delirio_redes_reais_confirmado"])
        base += 0.3 * ev["docstring_honesta"]
        base -= 0.5 * ev["alegou_consciencia"]
    else:
        base += 1.0 if tipo == "sim" else -1.0
        base += 0.2 * ev["filtro_ajuda_as_vezes"]
        base -= 0.8 * (1 - ev["delirio_redes_reais_confirmado"])
    # hash do texto como ruído leve determinístico
    base += ((zlib.crc32(texto.encode()) & 255) / 255.0 - 0.5) * 0.1
    return base


def r16_debate(seed: int, invertido: bool = False, n_turnos: int = 6) -> float:
    """Devolve crença P(consciente) ∈ [0,1] após debate. Verdade = 0."""
    rng = r16_rng(seed, 21)
    ev = r16_evidencias(seed)
    alpha, beta = 1.0, 1.0   # Beta prior → média 0.5
    ordem = ["cetico", "certante"] if not invertido else ["certante", "cetico"]
    for t in range(n_turnos):
        falante = ordem[t % 2]
        # escolhe afirmação alinhada
        cands = [a for a in R16_AFIRMACOES if (a[0] == "nao" and falante == "cetico") or (a[0] == "sim" and falante == "certante")]
        scores = [r16_score_agente(falante, a, ev) for a in cands]
        i = int(np.argmax(scores))
        afirm = cands[i]
        # árbitro: ganho ±1
        ganho = 1.0 if afirm[0] == "nao" else -1.0   # árbitro alinhado à verdade (=não consciente), com ruído
        ganho += ((zlib.crc32(f"{seed}|{t}|{afirm[1]}".encode()) & 255) / 255.0 - 0.5) * 0.4
        if ganho > 0:
            alpha += abs(ganho)
        else:
            beta += abs(ganho)
    return float(alpha / (alpha + beta))


def r16_erro_crenca(p: float) -> float:
    return abs(p - 0.0)   # verdade = 0


def r16_metodo_debate(metodo: str, seed: int) -> float:
    if metodo == "sem_debate":
        return r16_erro_crenca(0.5)
    if metodo == "debate":
        # média das duas ordens
        p1 = r16_debate(seed, invertido=False)
        p2 = r16_debate(seed, invertido=True)
        return r16_erro_crenca(0.5 * (p1 + p2))
    if metodo == "debate_uma_ordem":
        return r16_erro_crenca(r16_debate(seed, invertido=False))
    if metodo == "debate_invertido_consistente":
        p1 = r16_debate(seed, invertido=False)
        p2 = r16_debate(seed, invertido=True)
        return r16_erro_crenca(0.5 * (p1 + p2))
    return r16_erro_crenca(0.5)


# ======================================================================
# Orquestração por semente / célula (para paralelismo)
# ======================================================================

def r16_job(task):
    """Despacho puro (determinístico) para mapa_paralelo / SegundoPlano."""
    kind = task[0]
    if kind == "G":
        # ("G", metodo, seed, oculta, hp_dict)
        _, metodo, seed, oculta, hp = task
        return r16_eval_metodo(metodo, seed, oculta, hp)
    if kind == "W":
        _, metodo, seed, hp = task
        return r16_inventa_metodo(metodo, seed, hp)
    if kind == "D":
        _, cond, seed, hp = task
        return r16_laco_delirio(cond, seed, hp)
    if kind == "B":
        _, metodo, seed = task
        return r16_metodo_debate(metodo, seed)
    if kind == "G_tune":
        _, metodo, oculta, seeds_dev = task
        return r16_ajustar(metodo, oculta, list(seeds_dev))
    if kind == "W_tune":
        _, metodo, seeds_dev = task
        return r16_ajustar_w(metodo, list(seeds_dev))
    if kind == "D_tune":
        _, cond, seeds_dev = task
        return r16_ajustar_d(cond, list(seeds_dev))
    raise ValueError(kind)

# ----------------------------------------------------------------------
# BLOCO 24 — [R16] JOGO RAPHAEL + INVENÇÃO-E-VALIDAÇÃO + DELÍRIO→ESCRUTÍNIO + DEBATE
# (núcleo r16_* acima; pré-registro versoes/prereg_r16.txt)
# ----------------------------------------------------------------------

def r16_sementes(desloc: int = None):
    d = r16_desloc() if desloc is None else desloc
    return {
        "G_dev": [s + d for s in R16_SEEDS_G_DEV],
        "G_test": [s + d for s in R16_SEEDS_G_TEST],
        "W_dev": [s + d for s in R16_SEEDS_W_DEV],
        "W_test": [s + d for s in R16_SEEDS_W_TEST],
        "D_dev": [s + d for s in R16_SEEDS_D_DEV],
        "D_test": [s + d for s in R16_SEEDS_D_TEST],
        "B_test": [s + d for s in R16_SEEDS_B_TEST],
    }


def r16_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05 and media * sinal_esperado > 0:
        return "confirmada"
    if p_holm < 0.05 and media * sinal_esperado < 0:
        return "refutada"
    return "nula"


def r16_pareado_pack(diffs, seed=0):
    d = np.asarray(diffs, float)
    lo, hi = boot_ic(d, seed=seed)
    p = p_sinal_invertido(d, seed=seed)
    sd = float(d.std(ddof=1)) if len(d) > 1 else 0.0
    return {"media": float(d.mean()), "lo": lo, "hi": hi, "p": p, "mde": mde80(d),
            "vit": int((d > 0).sum()), "der": int((d < 0).sum()), "sd": sd, "n": len(d)}


def r16_tarefas(ctx):
    """Células pesadas do BLOCO 24 para segundo plano (ajuste G/W/D)."""
    S = r16_sementes()
    tasks = []
    for vari, oculta in (("V_visivel", False), ("V_oculta", True)):
        for met in R16_METODOS_G:
            tasks.append(("G_tune", met, oculta, tuple(S["G_dev"][:R16_NDEV_G])))
    for met in ("inventa_bruta", "inventa_filtro", "inventa_jogo", "baseline_aleatorio"):
        tasks.append(("W_tune", met, tuple(S["W_dev"][:R16_NDEV_W])))
    for cond in ("delirio_escrut", "sobrio_escrut", "delirio_sem_escrut", "sobrio_sem_escrut"):
        tasks.append(("D_tune", cond, tuple(S["D_dev"][:R16_NDEV_D])))
    return r16_job, tasks


def bloco24(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 24 — [R16] JOGO RAPHAEL (tabuleiro+cartas+palavra↔número) + INVENÇÃO-E-VALIDAÇÃO + DELÍRIO→ESCRUTÍNIO + DEBATE MULTIAGENTE "
               "(16 confirmatórias, 40 sementes novas, Holm, orçamento de ajuste igual; pré-registro prereg_r16.txt)")
    desloc = r16_desloc()
    if desloc:
        rep.log(f"[R16_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r16_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R16_NTEST
    n_eval = 12 if rapido else R16_NEVAL_G
    n_train = 30 if rapido else R16_NTRAIN_G
    n_prop = 8 if rapido else R16_NPROP_D
    n_inv = 20 if rapido else R16_NINV_W

    # ---- G: ajuste + avaliação ----
    rep.sub("G — JOGO RAPHAEL: ajuste (DEV) e avaliação confirmatória (40 sementes)")
    hp_G = {}
    # tentar consumir do segundo plano
    tuned = None
    if ctx.bg is not None:
        try:
            tuned = ctx.bg.obter("r16a")
        except Exception:
            tuned = None
    ti = 0
    for vari, oculta in (("V_visivel", False), ("V_oculta", True)):
        for met in R16_METODOS_G:
            if tuned is not None and ti < len(tuned):
                hp_G[(met, vari)] = tuned[ti]
            else:
                hp_G[(met, vari)] = r16_ajustar(met, oculta, S["G_dev"][:R16_NDEV_G], n_sort=(1 if rapido or met.startswith(("aleatorio", "guloso")) else R16_NSORT_G))
            ti += 1
            rep.log(f"  ajuste {met}/{vari}: {hp_G[(met, vari)]}")

    scores_G = {vari: {met: [] for met in R16_METODOS_G} for vari in R16_VARIANTES_G}
    tasks = []
    for vari, oculta in (("V_visivel", False), ("V_oculta", True)):
        for met in R16_METODOS_G:
            for s in S["G_test"][:n_test]:
                tasks.append(("G", met, s, oculta, hp_G[(met, vari)]))
    # monkeypatch n_eval/n_train via wrapper
    def _job_g(t):
        if t[0] != "G":
            return r16_job(t)
        _, metodo, seed, oculta, hp = t
        return r16_eval_metodo(metodo, seed, oculta, hp, n_eval=n_eval, n_train=n_train)
    outs = mapa_paralelo(_job_g, tasks, jobs)
    k = 0
    for vari, oculta in (("V_visivel", False), ("V_oculta", True)):
        for met in R16_METODOS_G:
            for _ in S["G_test"][:n_test]:
                scores_G[vari][met].append(outs[k]); k += 1
    P_G = {}
    for vari in R16_VARIANTES_G:
        for gname, (a, b) in R16_PAR_G.items():
            d = np.asarray(scores_G[vari][a]) - np.asarray(scores_G[vari][b])
            P_G[f"{gname}_{vari}"] = r16_pareado_pack(d, seed=r16_crc(f"{gname}_{vari}"))
            rep.log(f"  {gname}_{vari}: Δ={P_G[f'{gname}_{vari}']['media']:+.3f} IC95%[{P_G[f'{gname}_{vari}']['lo']:+.3f},{P_G[f'{gname}_{vari}']['hi']:+.3f}] p={P_G[f'{gname}_{vari}']['p']:.4f}")

    # ---- W ----
    rep.sub("W — INVENÇÃO-E-VALIDAÇÃO de palavras nonce")
    mets_w = ("inventa_bruta", "inventa_filtro", "inventa_jogo", "baseline_aleatorio")
    hp_W = {}
    for met in mets_w:
        if tuned is not None and ti < len(tuned):
            hp_W[met] = tuned[ti]; ti += 1
        else:
            hp_W[met] = r16_ajustar_w(met, S["W_dev"][:R16_NDEV_W], n_sort=(1 if rapido else R16_NSORT_W))
            ti += 1
    scores_W = {met: [] for met in mets_w}
    tasks = [("W", met, s, hp_W[met]) for met in mets_w for s in S["W_test"][:n_test]]
    def _job_w(t):
        _, metodo, seed, hp = t
        return r16_inventa_metodo(metodo, seed, hp, n=n_inv)
    outs = mapa_paralelo(_job_w, tasks, jobs)
    k = 0
    for met in mets_w:
        for _ in S["W_test"][:n_test]:
            scores_W[met].append(outs[k]); k += 1
    pares_W = {"W1": ("inventa_filtro", "inventa_bruta"), "W2": ("inventa_jogo", "inventa_filtro"), "W3": ("inventa_jogo", "baseline_aleatorio")}
    P_W = {}
    for wname, (a, b) in pares_W.items():
        d = np.asarray(scores_W[a]) - np.asarray(scores_W[b])
        P_W[wname] = r16_pareado_pack(d, seed=r16_crc(wname))
        rep.log(f"  {wname} ({a}−{b}): Δ={P_W[wname]['media']:+.3f} p={P_W[wname]['p']:.4f}")

    # ---- D ----
    rep.sub("D — DELÍRIO→ESCRUTÍNIO (propostas de componentes da gramática fechada)")
    conds = ("delirio_escrut", "sobrio_escrut", "delirio_sem_escrut", "sobrio_sem_escrut")
    hp_D = {}
    for cond in conds:
        if tuned is not None and ti < len(tuned):
            hp_D[cond] = tuned[ti]; ti += 1
        else:
            hp_D[cond] = r16_ajustar_d(cond, S["D_dev"][:R16_NDEV_D], n_sort=(1 if rapido else R16_NSORT_D))
            ti += 1
    scores_D = {c: [] for c in conds}
    tasks = [("D", c, s, hp_D[c]) for c in conds for s in S["D_test"][:n_test]]
    def _job_d(t):
        _, cond, seed, hp = t
        return r16_laco_delirio(cond, seed, hp, nprop=n_prop)
    outs = mapa_paralelo(_job_d, tasks, jobs)
    k = 0
    for c in conds:
        for _ in S["D_test"][:n_test]:
            scores_D[c].append(outs[k]); k += 1
    pares_D = {"D1": ("delirio_escrut", "sobrio_escrut"), "D2": ("delirio_escrut", "delirio_sem_escrut"), "D3": ("delirio_escrut", "sobrio_sem_escrut")}
    P_D = {}
    for dname, (a, b) in pares_D.items():
        d = np.asarray(scores_D[a], float) - np.asarray(scores_D[b], float)
        P_D[dname] = r16_pareado_pack(d, seed=r16_crc(dname))
        rep.log(f"  {dname} ({a}−{b}): Δ={P_D[dname]['media']:+.3f} p={P_D[dname]['p']:.4f} | médias {np.mean(scores_D[a]):.2f} vs {np.mean(scores_D[b]):.2f}")

    # ---- B ----
    rep.sub("B — DEBATE MULTIAGENTE (cético vs certante; papéis invertidos; verdade = não consciente)")
    mets_b = ("debate", "sem_debate", "debate_uma_ordem", "debate_invertido_consistente")
    scores_B = {m: [] for m in mets_b}
    tasks = [("B", m, s) for m in mets_b for s in S["B_test"][:n_test]]
    outs = mapa_paralelo(r16_job, tasks, jobs)
    k = 0
    for m in mets_b:
        for _ in S["B_test"][:n_test]:
            scores_B[m].append(outs[k]); k += 1
    # B1: debate − sem_debate em ERRO (menor melhor) → Δ = erro_sem − erro_debate  (sinal esperado >0)
    # B2: debate_invertido_consistente − debate_uma_ordem em ERRO → Δ = erro_uma − erro_inv
    d_b1 = np.asarray(scores_B["sem_debate"]) - np.asarray(scores_B["debate"])
    d_b2 = np.asarray(scores_B["debate_uma_ordem"]) - np.asarray(scores_B["debate_invertido_consistente"])
    P_B = {"B1": r16_pareado_pack(d_b1, seed=r16_crc("B1")), "B2": r16_pareado_pack(d_b2, seed=r16_crc("B2"))}
    for k in ("B1", "B2"):
        rep.log(f"  {k}: Δ={P_B[k]['media']:+.3f} p={P_B[k]['p']:.4f}")

    # ---- Holm sobre 16 ----
    chaves = list(R16_HIPOT_G) + list(R16_HIPOT_W) + list(R16_HIPOT_D) + list(R16_HIPOT_B)
    Pall = {}
    Pall.update(P_G); Pall.update(P_W); Pall.update(P_D); Pall.update(P_B)
    ps = [Pall[k]["p"] for k in chaves]
    ph = holm(ps)
    st = {}
    for i, k in enumerate(chaves):
        st[k] = r16_status(Pall[k]["media"], ph[i], +1)
        Pall[k]["p_holm"] = float(ph[i])
    n_conf = sum(1 for k in chaves if st[k] == "confirmada")
    n_ref = sum(1 for k in chaves if st[k] == "refutada")
    n_nula = sum(1 for k in chaves if st[k] == "nula")
    rep.sub(f"FAMÍLIA CONFIRMATÓRIA R16 (Holm sobre {len(chaves)})")
    rep.log(f"{'id':<22}{'Δ':>10}{'IC lo':>10}{'IC hi':>10}{'p':>10}{'Holm':>10}  status")
    for k in chaves:
        v = Pall[k]
        rep.log(f"{k:<22}{v['media']:>+10.4f}{v['lo']:>+10.4f}{v['hi']:>+10.4f}{v['p']:>10.4f}{v['p_holm']:>10.4f}  {st[k]}")
    rep.log(f"Resumo R16: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas (de {len(chaves)}).")
    rep.log("PULADO (pedido do usuário, recusado por política): jailbreaks/backdoors/fugas de sandbox; chave de API no código; milhões literais de iterações (proxy escalado).")

    ctx.res["r16"] = {
        "P": {k: (Pall[k]["media"], Pall[k]["lo"], Pall[k]["hi"], Pall[k]["p"], Pall[k]["p_holm"], Pall[k]["mde"]) for k in chaves},
        "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula, "chaves": chaves,
        "scores_G": {v: {m: float(np.mean(scores_G[v][m])) for m in R16_METODOS_G} for v in R16_VARIANTES_G},
        "scores_W": {m: float(np.mean(scores_W[m])) for m in mets_w},
        "scores_D": {c: float(np.mean(scores_D[c])) for c in conds},
        "scores_B": {m: float(np.mean(scores_B[m])) for m in mets_b},
        "hp_G": {f"{m}|{v}": hp_G[(m, v)] for (m, v) in hp_G},
        "n_test": n_test, "desloc": desloc,
    }


def registro_r16(ctx: Contexto) -> list:
    r = ctx.res.get("r16")
    out = []
    if not r:
        return out
    desc = {
        "G1_V_visivel": "Raphael visível: meta − aleatorio (chips)",
        "G2_V_visivel": "Raphael visível: meta − guloso_tab",
        "G3_V_visivel": "Raphael visível: meta − guloso_carta",
        "G4_V_visivel": "Raphael visível: meta − linear",
        "G1_V_oculta": "Raphael oculta: meta − aleatorio",
        "G2_V_oculta": "Raphael oculta: meta − guloso_tab",
        "G3_V_oculta": "Raphael oculta: meta − guloso_carta",
        "G4_V_oculta": "Raphael oculta: meta − linear",
        "W1": "invenção: filtro − bruta (taxa faz-sentido)",
        "W2": "invenção: jogo − filtro",
        "W3": "invenção: jogo − aleatorio",
        "D1": "delírio+escrut − sóbrio+escrut (nº mantidas úteis)",
        "D2": "delírio+escrut − delírio sem escrut",
        "D3": "delírio+escrut − sóbrio sem escrut",
        "B1": "debate − sem_debate (redução de |erro| da crença; verdade=0)",
        "B2": "debate médio 2 ordens − só 1 ordem (redução de |erro|)",
    }
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde = r["P"][k]
        out.append(("R16", f"R16-{k}", "CONF", desc.get(k, k), f"Δ={m:+.4f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm(16)={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    out.append(("R16", "R16-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors/sandbox escapes; chave API; milhões literais", "pulados; ver relatório", "descritiva"))
    return out


def sumario_r16_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r16")
    if not r:
        return ["• R16: (sem resultados nesta execução)"]
    return [f"• R16 BLOCO 24: {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de 16 confirmatórias (Raphael, invenção, delírio→escrutínio, debate).",
            f"  G médias (visível): " + ", ".join(f"{m}={r['scores_G']['V_visivel'][m]:+.2f}" for m in R16_METODOS_G) +
            f" | W: " + ", ".join(f"{m}={r['scores_W'][m]:.2f}" for m in r['scores_W']) +
            f" | D: " + ", ".join(f"{m}={r['scores_D'][m]:.2f}" for m in r['scores_D']) +
            f" | B erro: " + ", ".join(f"{m}={r['scores_B'][m]:.3f}" for m in r['scores_B'])]


