def _t16_registro_sintetico() -> bool:
    import types
    P = {k: (0.01, -0.01, 0.03, 0.03, 0.2, 0.02) for k in R16_HIPOT}
    st = {k: "nula" for k in R16_HIPOT}
    ctx = types.SimpleNamespace(res={"r16": {"P": P, "st": st, "n_conf": 0, "n_ref": 0, "n_nula": 16, "chaves": list(R16_HIPOT),
                                            "scores_G": {v: {m: 0.0 for m in R16_METODOS_G} for v in R16_VARIANTES_G},
                                            "scores_W": {"inventa_bruta": 0.1, "inventa_filtro": 0.2, "inventa_jogo": 0.2, "baseline_aleatorio": 0.05},
                                            "scores_D": {"delirio_escrut": 0.0, "sobrio_escrut": 0.0, "delirio_sem_escrut": 0.0, "sobrio_sem_escrut": 0.0},
                                            "scores_B": {"debate": 0.5, "sem_debate": 0.5, "debate_uma_ordem": 0.5, "debate_invertido_consistente": 0.5}}})
    L = registro_r16(ctx)
    conf = [x for x in L if x[2] == "CONF"]
    sm = sumario_r16_linhas(ctx)
    return len(conf) == 16 and len({x[1] for x in conf}) == 16 and all(x[1].startswith("R16-") for x in conf) and len(sm) >= 1



def leigos_linhas_r17(ctx: Contexto) -> list:
    """[R17] RELATÓRIO PARA LEIGOS (≤ 40 linhas)."""
    import textwrap
    base = leigos_linhas_r16(ctx)
    r = ctx.res.get("r17")
    extra = []
    if r:
        extra.append(
            f"RODADA 17: corrigi o Raphael (heurística forte + override só sob incerteza), recalibrei o canal palavra↔número, "
            f"ampliei o laço delírio→escrutínio com propostas plantadas (TPR/FPR) e testei uma GAN modular. "
            f"Resultado: {r['n_conf']} confirmadas, {r['n_ref']} refutadas, {r['n_nula']} nulas de 14 testes. "
            f"Continua sendo um protótipo didático — não é ASI/AGI."
        )
    extra.append("RECUSAS DESTA RODADA: não criei jailbreaks/backdoors nem coloquei chave de API no código; não rodei '1 milhão' literal (proxies honestos).")
    out = []
    for line in base:
        if line.startswith("LIMITES:") or line.startswith("LIMITES "):
            for p in extra:
                out.extend(textwrap.wrap(p, width=170))
            out.append(line)
        else:
            out.append(line)
    if extra and not any(l.startswith("LIMITES") for l in base):
        for p in extra:
            out.extend(textwrap.wrap(p, width=170))
    out2 = []
    for l in out:
        if "RELATÓRIO PARA LEIGOS (rodadas 1–" in l:
            out2.append(l.replace("1–16", "1–17").replace(f"1–{int(VERSAO[1:])-1}", f"1–{VERSAO[1:]}"))
        else:
            out2.append(l)
    return out2

