    t("R16: versão = R16 (ou posterior)", VERSAO in ("R16", "R17", "R18", "R19", "R20", "R21", "R22", "R23", "R24", "R25", "R26", "R27", "R28", "R29", "R30", "R31", "R32", "R33", "R34", "R35", "R36", "R37") or int(VERSAO[1:]) >= 16)
