def r17_desloc() -> int:
    v = os.environ.get("R17_DEV", "").strip().lower()
    return 10000 if v not in ("", "0", "false", "no", "off") else 0


def r17_crc(rot: str) -> int:
    return zlib.crc32(f"R17|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r17_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


# ======================================================================
# H — RAPHAEL CORRIGIDO
# ======================================================================

def r17_score_forte(board, jog: int) -> float:
    """Heurística FORTE: posição + mobilidade + ameaça ao Rei + segurança do Rei."""
    s = 1 if jog == 0 else -1
    tot = r16_score_pos(board, jog)
    mob = len(r16_movimentos(board, jog)) - len(r16_movimentos(board, 1 - jog))
    tot += 0.15 * mob
    # localizar reis
    rei_me = rei_op = None
    for y in range(4):
        for x in range(4):
            v = int(board[y, x])
            if v == s:
                rei_me = (y, x)
            elif v == -s:
                rei_op = (y, x)
    if rei_me and rei_op:
        dist = abs(rei_me[0] - rei_op[0]) + abs(rei_me[1] - rei_op[1])
        tot += 0.4 * (3.0 - dist)   # ameaça
        # segurança: preferir rei longe da borda? na verdade centro é melhor no 4x4
        tot += 0.2 * r16_pos_valor(*rei_me)
        tot -= 0.2 * r16_pos_valor(*rei_op)
    return tot


def r17_afinidade_pn(w: str, n: int) -> float:
    """Canal palavra↔número RECALIBRADO (R17): cosseno duplo + bônus estruturais."""
    base = r16_coerencia(w, n)
    soma = sum((ord(c.lower()) - 96) for c in w if c.isalpha()) % 12
    if soma == 0:
        soma = 12
    bonus_soma = 0.35 if soma == ((n - 1) % 12) + 1 else 0.0
    bucket = (zlib.crc32(("pn::" + w).encode()) & 0xFFFFFFFF) % 12 + 1
    bonus_hash = 0.25 if bucket == n else 0.0
    # comprimento próximo de n%8+4
    alvo_len = (n % 7) + 4
    bonus_len = 0.15 * max(0.0, 1.0 - abs(len(w) - alvo_len) / 4.0)
    return float(base + bonus_soma + bonus_hash + bonus_len)


def r17_score_carta(board, carta, jog: int) -> float:
    w, n = carta
    return r17_afinidade_pn(w, n) + 0.1 * r16_score_pos(board, jog)


def r17_escolher(metodo: str, board, carta, jog: int, hp: dict, rng):
    moves = r16_movimentos(board, jog)
    if not moves:
        return None
    w, n = carta
    coh = r17_afinidade_pn(w, n)
    if metodo == "guloso_tab":
        best, bv = moves[0], -1e9
        for mv in moves:
            b2, cap = r16_aplicar(board, mv)
            val = r16_score_pos(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
            if val > bv:
                best, bv = mv, val
        return best
    if metodo == "guloso_forte":
        best, bv = moves[0], -1e9
        for mv in moves:
            b2, cap = r16_aplicar(board, mv)
            val = r17_score_forte(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
            if val > bv:
                best, bv = mv, val
        return best
    if metodo == "canal_pn":
        # maximiza afinidade; tabuleiro só desempata (r17_score_carta agrega PN+posição)
        best, bv = moves[0], -1e9
        for mv in moves:
            b2, cap = r16_aplicar(board, mv)
            val = r17_score_carta(b2, carta, jog) + (2.0 if abs(cap) == 1 else (1.0 if cap else 0.0))
            if val > bv:
                best, bv = mv, val
        return best
    # meta_override / meta_sempre
    tau = float(hp.get("tau", 1.0))
    eta = float(hp.get("eta", 0.6))
    delta = float(hp.get("delta", 0.8))
    lam = float(hp.get("lam", 0.5))
    scores_tab, scores_carta = [], []
    for mv in moves:
        b2, cap = r16_aplicar(board, mv)
        st = r17_score_forte(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
        sc = coh + (1.0 if abs(cap) == 1 else 0.0)
        scores_tab.append(st)
        scores_carta.append(sc)
    st = np.asarray(scores_tab, float)
    sc = np.asarray(scores_carta, float)
    # softmax entropy sobre scores de tabuleiro
    logits = st / max(tau, 1e-6)
    p = np.exp(logits - logits.max()); p = p / p.sum()
    H = float(-(p * np.log(p + 1e-12)).sum())
    Hnorm = H / max(math.log(len(p)), 1e-9)
    desacordo = float(abs(st.max() - sc.max()))
    intervir = (metodo == "meta_sempre") or (Hnorm > eta) or (desacordo > delta)
    if intervir:
        mix = st + lam * sc
    else:
        mix = st
    i = int(np.argmax(mix))
    return moves[i]


def r17_partida(metodo: str, hp: dict, seed: int, oponente: str = "guloso_tab") -> float:
    rng = r17_rng(seed, r17_crc(metodo), 7)
    board, deck, _ = r16_estado0(rng)
    di = 0
    pts = [0.0, 0.0]
    for t in range(16):
        jog = t % 2
        if di >= len(deck):
            break
        carta = deck[di]; di += 1
        met = metodo if jog == 0 else oponente
        mv = r17_escolher(met, board, carta, jog, hp if jog == 0 else {}, rng)
        if mv is None:
            break
        board, cap = r16_aplicar(board, mv)
        coh = r17_afinidade_pn(*carta) if met != "guloso_tab" else r16_coerencia(*carta)
        ganho = r16_pos_valor(mv[2], mv[3]) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0)) + 0.5 * coh
        pts[jog] += ganho
        if abs(cap) == 1:
            pts[jog] += 5.0
            break
    return pts[0] - pts[1]


def r17_eval_h(metodo: str, seed: int, hp: dict, n_eval: int = R17_NEVAL_H) -> float:
    vals = [r17_partida(metodo, hp, seed * 1009 + k) for k in range(n_eval)]
    return float(np.mean(vals))


def r17_sorteio_hp_h(i: int) -> dict:
    rng = r17_rng(r17_crc("H"), 17, i)
    return {
        "tau": float(rng.choice([0.5, 1.0, 1.5, 2.0])),
        "eta": float(rng.uniform(0.35, 0.85)),
        "delta": float(rng.uniform(0.3, 1.5)),
        "lam": float(rng.uniform(0.2, 1.0)),
    }


def r17_ajustar_h(metodo: str, seeds_dev, n_sort: int = R17_NSORT) -> dict:
    if metodo in ("guloso_tab", "guloso_forte"):
        return {"tau": 1.0, "eta": 0.6, "delta": 0.8, "lam": 0.5}
    best, bh = -1e18, r17_sorteio_hp_h(0)
    for i in range(n_sort):
        hp = r17_sorteio_hp_h(i)
        sc = float(np.mean([r17_eval_h(metodo, s, hp, n_eval=12) for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


# ======================================================================
# W — CANAL palavra↔número / invenção recalibrada
# ======================================================================

def r17_juiz_recalibrado(w: str, lake_vecs) -> bool:
    """Juiz mais rígido que R16 (limiar 0,40 + oráculo + comprimento)."""
    if not (4 <= len(w) <= 10):
        return False
    if not r16_oraculo_offline(w):
        # ainda assim pode passar se coerência alta com lake
        pass
    if not lake_vecs:
        return r16_oraculo_offline(w) and 4 <= len(w) <= 10
    vw = r16_map_palavra_num(w)
    best = -1.0
    for v in lake_vecs.values():
        c = float(np.dot(vw, v) / (np.linalg.norm(vw) * np.linalg.norm(v) + 1e-12))
        if c > best:
            best = c
    return best >= 0.40 and 4 <= len(w) <= 10


def r17_inventa_metodo(metodo: str, seed: int, hp: dict, n: int = R17_NINV_W) -> float:
    rng = r17_rng(seed, r17_crc(metodo), 3)
    lake = r16_lake_vecs()
    P = r16_markov_letras(R16_PALAVRAS, ordem=2)
    ok = 0
    tau = float(hp.get("tau", 0.15))
    for _ in range(n):
        if metodo == "iid_letras":
            L = int(rng.integers(4, 11))
            w = "".join(chr(int(rng.integers(97, 123))) for _ in range(L))
        else:
            w = r16_inventar(P, rng, maxlen=10)
            if len(w) < 4:
                continue
        if metodo == "markov2":
            pass
        elif metodo == "canal_pn_filtro":
            # filtra por afinidade média com números 1..12 ou oráculo
            af = max(r17_afinidade_pn(w, k) for k in range(1, 13))
            if not (r16_oraculo_offline(w) or af > tau):
                continue
        elif metodo == "canal_pn_jogo":
            af = max(r17_afinidade_pn(w, k) for k in range(1, 13))
            if not (r16_oraculo_offline(w) or af > tau):
                continue
            # jogo de sentidos leve: escolhe sentido com maior coerência nonce
            _ = r16_jogo_sentidos(w, 4, rng, lake)
        if r17_juiz_recalibrado(w, lake):
            ok += 1
    return ok / max(n, 1)


def r17_sorteio_hp_w(i: int) -> dict:
    rng = r17_rng(r17_crc("W"), 17, i)
    return {"tau": float(rng.uniform(0.05, 0.4))}


def r17_ajustar_w(metodo: str, seeds_dev, n_sort: int = R17_NSORT) -> dict:
    if metodo in ("iid_letras", "markov2"):
        return {"tau": 0.15}
    best, bh = -1e18, r17_sorteio_hp_w(0)
    for i in range(n_sort):
        hp = r17_sorteio_hp_w(i)
        sc = float(np.mean([r17_inventa_metodo(metodo, s, hp, n=20) for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


# ======================================================================
# D — DELÍRIO→ESCRUTÍNIO AMPLIADO + PLANTADAS
# ======================================================================

def r17_propor_tag(rng, tag: str, T: float) -> dict:
    return {
        "nome": f"{tag}_{int(rng.integers(0, 1000))}",
        "tag": tag,
        "peso": float(rng.uniform(0.2, 0.9)) if tag in R17_GRAM_UTEIS else float(rng.uniform(0.1, 1.0)),
        "limiar": float(rng.uniform(0.2, 0.8)),
        "T": T,
        "plantada": tag in R17_GRAM_UTEIS or tag in R17_GRAM_INUTEIS,
        "util_ref": tag in R17_GRAM_UTEIS,
    }


def r17_propor_livre(rng, T: float) -> dict:
    tags = [t for t, _ in R17_GRAMATICA]
    logits = rng.normal(0, 1, size=len(tags)) / max(T, 1e-3)
    p = np.exp(logits - logits.max()); p = p / p.sum()
    i = int(rng.choice(len(tags), p=p))
    return r17_propor_tag(rng, tags[i], T)


def r17_mlp_treino(X, Y, passos: int, seed: int, componente=None, shuffle_y: bool = False):
    """MLP 2→8→1 com tags ampliadas (residual, label_smooth, lr_cos, mixup_h, harm_*)."""
    rng = r17_rng(seed, 17)
    Yt = Y.copy()
    if shuffle_y:
        Yt = rng.permutation(Yt)
    W1 = rng.normal(0, 0.5, size=(2, 8))
    b1 = np.zeros(8)
    W2 = rng.normal(0, 0.5, size=(8, 1))
    b2 = np.zeros(1)
    # projeção residual de X
    Wx = rng.normal(0, 0.3, size=(2, 8))
    lr0 = 0.25
    eps_smooth = 0.0
    if componente is not None and componente["tag"] == "label_smooth":
        eps_smooth = 0.05 + 0.25 * float(componente["peso"])
    for p in range(passos):
        lr = lr0
        if componente is not None and componente["tag"] == "lr_cos":
            lr = lr0 * 0.5 * (1 + math.cos(math.pi * p / max(passos, 1)))
        elif componente is not None and componente["tag"] == "noise":
            lr = lr0 * (0.5 + 0.5 * abs(math.sin(p / max(3.0, 8.0 * componente["peso"]))))
        Ys = Yt * (1 - eps_smooth) + 0.5 * eps_smooth
        h = np.tanh(X @ W1 + b1)
        if componente is not None:
            tag = componente["tag"]
            if tag == "residual":
                h = h + float(componente["peso"]) * np.tanh(X @ Wx)
            elif tag == "mixup_h":
                idx = rng.integers(0, len(h), size=len(h))
                lam = 0.3 + 0.4 * float(componente["peso"])
                h = lam * h + (1 - lam) * h[idx]
            elif tag == "noise":
                h = h + componente["peso"] * 0.15 * rng.normal(0, 1, h.shape) * math.cos(p / 4)
            elif tag == "ent":
                logits = h @ W2 + b2
                pr = 1 / (1 + np.exp(-np.clip(logits.ravel(), -20, 20)))
                ent = -(pr * np.log(pr + 1e-9) + (1 - pr) * np.log(1 - pr + 1e-9))
                h = h * (1.0 - 0.5 * componente["peso"] * (ent > componente["limiar"]).astype(float)).reshape(-1, 1)
            elif tag == "knn":
                h = h + componente["peso"] * 0.08 * np.tanh(h)
            elif tag == "prior":
                h = h + componente["peso"] * 0.1
            elif tag == "ece":
                h = h * (1.0 - 0.1 * componente["peso"])
            elif tag == "harm_noise_big":
                h = h + (0.8 + 0.8 * float(componente["peso"])) * rng.normal(0, 1, h.shape)
            elif tag == "noop_rename":
                pass
            # harm_invert applied on gradients below
        logits = h @ W2 + b2
        pr = 1 / (1 + np.exp(-np.clip(logits.ravel(), -20, 20)))
        err = (pr - Ys).reshape(-1, 1)
        w = np.ones_like(pr)
        if componente is not None and componente["tag"] == "conf":
            w = 0.3 + 0.7 * (np.abs(pr - 0.5) > (0.05 + 0.2 * componente["limiar"])).astype(float)
        g2 = (h * w.reshape(-1, 1)).T @ err / len(Y)
        gb2 = (err.ravel() * w).mean()
        dh = (err * w.reshape(-1, 1)) @ W2.T * (1 - h ** 2)
        g1 = X.T @ dh / len(Y)
        gb1 = dh.mean(0)
        if componente is not None and componente["tag"] == "harm_invert":
            if rng.random() < (0.3 + 0.5 * float(componente["peso"])):
                g1, gb1, g2, gb2 = -g1, -gb1, -g2, -gb2
        W2 -= lr * g2; b2 -= lr * gb2; W1 -= lr * g1; b1 -= lr * gb1
    h = np.tanh(X @ W1 + b1)
    if componente is not None and componente["tag"] == "residual":
        h = h + float(componente["peso"]) * np.tanh(X @ Wx)
    pr = 1 / (1 + np.exp(-np.clip((h @ W2 + b2).ravel(), -20, 20)))
    acc = float(((pr > 0.5) == Yt).mean())
    ece = 0.0
    for lo in np.linspace(0, 1, 5)[:-1]:
        m = (pr >= lo) & (pr < lo + 0.2)
        if m.any():
            ece += float(m.mean() * abs(pr[m].mean() - Yt[m].mean()))
    return acc, ece, (W1, b1, W2, b2, Wx)


def r17_avaliar_proposta(comp, seed: int) -> dict:
    Xtr, Ytr = r16_espirais(40, seed)
    Xte, Yte = r16_espirais(30, seed + 1)
    acc_c, ece_c, pesos = r17_mlp_treino(Xtr, Ytr, 50, seed + 2, componente=comp)
    W1, b1, W2, b2, Wx = pesos
    def _acc(X, Y, W1, b1, W2, b2, Wx, comp):
        h = np.tanh(X @ W1 + b1)
        if comp is not None and comp["tag"] == "residual":
            h = h + float(comp["peso"]) * np.tanh(X @ Wx)
        pr = 1 / (1 + np.exp(-np.clip((h @ W2 + b2).ravel(), -20, 20)))
        return float(((pr > 0.5) == Y).mean())
    acc_te = _acc(Xte, Yte, W1, b1, W2, b2, Wx, comp)
    acc_b, ece_b, wb = r17_mlp_treino(Xtr, Ytr, 50, seed + 2, componente=None)
    acc_te_b = _acc(Xte, Yte, *wb[:4], wb[4], None)
    acc_s, _, _ = r17_mlp_treino(Xtr, Ytr, 50, seed + 3, componente=comp, shuffle_y=True)
    Xte2, Yte2 = r16_espirais(30, seed + 50)
    acc_f = _acc(Xte2, Yte2, W1, b1, W2, b2, Wx, comp)
    acc_f_b = _acc(Xte2, Yte2, *wb[:4], wb[4], None)
    delta = acc_f - acc_f_b
    V1 = delta > 0.0
    V2 = acc_s < 0.60
    V3 = (acc_te - acc_te_b) > 0.0
    V4 = ece_c <= ece_b + 0.05
    mantem = bool(V1 and V2 and V3 and V4)
    return {"mantem": mantem, "delta": delta, "V1": V1, "V2": V2, "V3": V3, "V4": V4, "acc": acc_te}


def r17_laco_delirio(cond: str, seed: int, hp: dict, nprop: int = R17_NPROP_D) -> dict:
    """Retorna dict com TPR, FPR, Youden, n_livres_uteis (desfecho principal = Youden)."""
    rng = r17_rng(seed, r17_crc(cond), 5)
    T_hi = float(hp.get("T_hi", 1.5))
    T_lo = float(hp.get("T_lo", 0.3))
    escrut = "escrut" in cond
    delirio = "delirio" in cond
    oraculo = cond == "oraculo_perfeito"
    T = T_hi if delirio else T_lo
    # montar lista de propostas: 6 úteis + 6 inúteis + 12 livres
    props = []
    for i in range(R17_N_UTEIS):
        tag = R17_GRAM_UTEIS[i % len(R17_GRAM_UTEIS)]
        props.append(r17_propor_tag(rng, tag, T))
    for i in range(R17_N_INUTEIS):
        tag = R17_GRAM_INUTEIS[i % len(R17_GRAM_INUTEIS)]
        props.append(r17_propor_tag(rng, tag, T))
    n_livres = nprop - R17_N_UTEIS - R17_N_INUTEIS
    for _ in range(max(0, n_livres)):
        props.append(r17_propor_livre(rng, T))
    tp = fp = n_u = n_i = livres_uteis = 0
    for i, comp in enumerate(props):
        if oraculo:
            mantem = bool(comp.get("util_ref"))
            delta = 1.0 if mantem else -1.0
        elif not escrut:
            # aceita proxy
            proxy_ok = r16_coerencia(comp["tag"][:4].ljust(4, "a"), int(comp["peso"] * 12) % 12 + 1) > -0.1
            if proxy_ok:
                r = r17_avaliar_proposta(comp, seed + 100 + i)
                mantem = r["delta"] > 0.0
                delta = r["delta"]
            else:
                mantem, delta = False, 0.0
        else:
            r = r17_avaliar_proposta(comp, seed + 100 + i)
            mantem, delta = r["mantem"], r["delta"]
        if comp.get("util_ref"):
            n_u += 1
            if mantem:
                tp += 1
        elif comp.get("plantada") and not comp.get("util_ref"):
            n_i += 1
            if mantem:
                fp += 1
        else:
            if mantem and delta > 0:
                livres_uteis += 1
    TPR = tp / max(n_u, 1)
    FPR = fp / max(n_i, 1)
    return {"Youden": float(TPR - FPR), "TPR": float(TPR), "FPR": float(FPR),
            "livres_uteis": float(livres_uteis), "tp": tp, "fp": fp}


def r17_sorteio_hp_d(i: int) -> dict:
    rng = r17_rng(r17_crc("D"), 17, i)
    return {"T_hi": float(rng.uniform(1.0, 2.5)), "T_lo": float(rng.uniform(0.15, 0.5))}


def r17_ajustar_d(cond: str, seeds_dev, n_sort: int = R17_NSORT) -> dict:
    if cond == "oraculo_perfeito":
        return {"T_hi": 1.5, "T_lo": 0.3}
    best, bh = -1e18, r17_sorteio_hp_d(0)
    for i in range(n_sort):
        hp = r17_sorteio_hp_d(i)
        sc = float(np.mean([r17_laco_delirio(cond, s, hp)["Youden"] for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


# ======================================================================
# N — COLISÃO NN×GAN MODULAR
# ======================================================================

def r17_dados_modos(n: int, seed: int):
    rng = r17_rng(seed, 91)
    centros = np.array([[-1.5, 0.0], [1.5, 0.0], [0.0, 1.5]], float)
    y = rng.integers(0, 3, size=n)
    X = centros[y] + 0.25 * rng.normal(0, 1, size=(n, 2))
    return X, centros


def r17_mlp_forward(X, W1, b1, W2, b2):
    h = np.tanh(X @ W1 + b1)
    return h @ W2 + b2, h


def r17_gan_step(G, D, Z, Xreal, lr_g, lr_d, mask_g, mask_d, opt="sgd"):
    """Um passo G/D; mask_* = (m_enc, m_head) em {0,1}."""
    W1g, b1g, W2g, b2g = G
    W1d, b1d, W2d, b2d = D
    # D step
    fake, _ = r17_mlp_forward(Z, *G)
    real_logit, h_r = r17_mlp_forward(Xreal, *D)
    fake_logit, h_f = r17_mlp_forward(fake.detach() if hasattr(fake, "detach") else fake, *D)
    # binary: real=1, fake=0
    pr = 1 / (1 + np.exp(-np.clip(real_logit.ravel(), -20, 20)))
    pf = 1 / (1 + np.exp(-np.clip(fake_logit.ravel(), -20, 20)))
    # grads D
    err_r = (pr - 1.0).reshape(-1, 1)
    err_f = (pf - 0.0).reshape(-1, 1)
    g2d = (h_r.T @ err_r + h_f.T @ err_f) / (len(Xreal) + len(fake))
    gb2d = (err_r.ravel().mean() + err_f.ravel().mean()) / 2
    dhr = err_r @ W2d.T * (1 - h_r ** 2)
    dhf = err_f @ W2d.T * (1 - h_f ** 2)
    g1d = (Xreal.T @ dhr + fake.T @ dhf) / (len(Xreal) + len(fake))
    gb1d = (dhr.mean(0) + dhf.mean(0)) / 2
    if mask_d[1]:
        W2d = W2d - lr_d * g2d; b2d = b2d - lr_d * gb2d
    if mask_d[0]:
        W1d = W1d - lr_d * g1d; b1d = b1d - lr_d * gb1d
    D = (W1d, b1d, W2d, b2d)
    # G step (enganar D)
    fake, h_g = r17_mlp_forward(Z, *G)
    fake_logit, h_f = r17_mlp_forward(fake, *D)
    pf = 1 / (1 + np.exp(-np.clip(fake_logit.ravel(), -20, 20)))
    err_g = (pf - 1.0).reshape(-1, 1)   # quer pf→1
    # back through D (frozen) to fake, then to G
    dhf = err_g @ D[2].T * (1 - h_f ** 2)
    # dL/dfake ≈ dhf path through D's first layer: err_g @ W2d.T * (1-h^2) then @ W1d.T — approx use dhf mean onto fake
    # simpler: treat D(fake) gradient w.r.t fake as (err_g @ W2d.T * (1-hf^2)) @ W1d.T
    dfake = dhf @ D[0].T
    # G grads
    g2g = h_g.T @ dfake / len(Z)
    gb2g = dfake.mean(0) if dfake.ndim > 1 else dfake.mean()
    # dfake is (batch, 2); h_g is (batch, hid); W2g is (hid, 2)
    g2g = h_g.T @ dfake / len(Z)
    gb2g = dfake.mean(0)
    dhg = dfake @ W2g.T * (1 - h_g ** 2) if W2g.shape[1] == dfake.shape[1] else (dfake @ W2g.T) * (1 - h_g ** 2)
    # fix shapes: W2g (hid, out=2)
    g1g = Z.T @ dhg / len(Z)
    gb1g = dhg.mean(0)
    if mask_g[1]:
        W2g = W2g - lr_g * g2g; b2g = b2g - lr_g * gb2g
    if mask_g[0]:
        W1g = W1g - lr_g * g1g; b1g = b1g - lr_g * gb1g
    G = (W1g, b1g, W2g, b2g)
    loss_d = float(-(np.log(pr + 1e-9).mean() + np.log(1 - pf + 1e-9).mean()))
    return G, D, loss_d, float(pf.mean())


def r17_controlador_modular(hist_loss, d_acc, modo_proxy, rng):
    """Regras metacognitivas fixas → máscaras (enc_G, head_G), (enc_D, head_D)."""
    osc = float(np.std(hist_loss[-20:])) if len(hist_loss) >= 5 else 0.0
    # default: atualiza tudo
    mg = [1, 1]; md = [1, 1]
    if osc > 0.15:
        # congelar encoders, só heads
        mg = [0, 1]; md = [0, 1]
    if modo_proxy > 0.55:  # colapso
        mg = [1, 1]; md = [0, 0]  # só G
        return tuple(mg), tuple(md)
    if d_acc > 0.9:
        md = [0, 0]  # pausar D
    if d_acc < 0.55:
        md = [1, 1]; mg = [0, 1]  # fortalecer D
    return tuple(mg), tuple(md)


def r17_jsd_modos(fake, centros) -> float:
    # atribuição Voronoi
    d = ((fake[:, None, :] - centros[None, :, :]) ** 2).sum(-1)
    atr = d.argmin(1)
    hist = np.bincount(atr, minlength=3).astype(float)
    hist = hist / (hist.sum() + 1e-12)
    alvo = np.ones(3) / 3.0
    m = 0.5 * (hist + alvo)
    def _kl(p, q):
        return float(np.sum(np.where(p > 0, p * np.log((p + 1e-12) / (q + 1e-12)), 0.0)))
    return 0.5 * _kl(hist, m) + 0.5 * _kl(alvo, m)


def r17_treinar_gan(metodo: str, seed: int, hp: dict, passos: int = R17_PASSOS_N) -> dict:
    rng = r17_rng(seed, r17_crc(metodo), 19)
    X, centros = r17_dados_modos(180, seed)
    hid = 8
    G = (rng.normal(0, 0.4, (2, hid)), np.zeros(hid), rng.normal(0, 0.4, (hid, 2)), np.zeros(2))
    D = (rng.normal(0, 0.4, (2, hid)), np.zeros(hid), rng.normal(0, 0.4, (hid, 1)), np.zeros(1))
    lr_g = float(hp.get("lr_g", 0.05))
    lr_d = float(hp.get("lr_d", 0.05))
    hist = []
    d_acc_ema = 0.5
    for t in range(passos):
        idx = rng.integers(0, len(X), size=32)
        Xb = X[idx]
        Z = rng.normal(0, 1, size=(32, 2))
        if metodo == "monolito":
            mg, md = (1, 1), (1, 1)
        elif metodo == "modular_aleat":
            mg = (int(rng.integers(0, 2)), int(rng.integers(0, 2)))
            md = (int(rng.integers(0, 2)), int(rng.integers(0, 2)))
            if mg == (0, 0):
                mg = (1, 1)
            if md == (0, 0):
                md = (1, 0)
        else:
            # proxy de colapso parcial
            if t > 20 and t % 20 == 0:
                Zq = rng.normal(0, 1, size=(60, 2))
                fq, _ = r17_mlp_forward(Zq, *G)
                j = r17_jsd_modos(fq, centros)
                modo_proxy = j  # alto JSD ≈ má cobertura
            else:
                modo_proxy = 0.3
            mg, md = r17_controlador_modular(hist, d_acc_ema, modo_proxy, rng)
        G, D, loss_d, pf = r17_gan_step(G, D, Z, Xb, lr_g, lr_d, mg, md)
        hist.append(loss_d)
        # D acc proxy
        real_logit, _ = r17_mlp_forward(Xb, *D)
        pr = 1 / (1 + np.exp(-np.clip(real_logit.ravel(), -20, 20)))
        d_acc = 0.5 * ((pr > 0.5).mean() + (pf < 0.5))
        d_acc_ema = 0.9 * d_acc_ema + 0.1 * float(d_acc)
    Zq = rng.normal(0, 1, size=(120, 2))
    fq, _ = r17_mlp_forward(Zq, *G)
    jsd = r17_jsd_modos(fq, centros)
    osc = float(np.std(hist[-50:])) if len(hist) >= 50 else float(np.std(hist))
    # colapso
    d = ((fq[:, None, :] - centros[None, :, :]) ** 2).sum(-1)
    atr = d.argmin(1)
    histm = np.bincount(atr, minlength=3).astype(float); histm /= histm.sum() + 1e-12
    colapso = 1.0 - float((histm >= 0.15).sum()) / 3.0
    return {"neg_jsd": -float(jsd), "jsd": float(jsd), "osc": osc, "colapso": colapso}


def r17_sorteio_hp_n(i: int) -> dict:
    rng = r17_rng(r17_crc("N"), 17, i)
    return {"lr_g": float(rng.choice([0.02, 0.05, 0.08, 0.12])),
            "lr_d": float(rng.choice([0.02, 0.05, 0.08, 0.12]))}


def r17_ajustar_n(metodo: str, seeds_dev, n_sort: int = R17_NSORT) -> dict:
    best, bh = -1e18, r17_sorteio_hp_n(0)
    for i in range(n_sort):
        hp = r17_sorteio_hp_n(i)
        sc = float(np.mean([r17_treinar_gan(metodo, s, hp, passos=120)["neg_jsd"] for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


def r17_eval_n(metodo: str, seed: int, hp: dict) -> float:
    return r17_treinar_gan(metodo, seed, hp)["neg_jsd"]


# ---------- despacho puro ----------
def r17_job(task):
    kind = task[0]
    if kind == "H":
        _, metodo, seed, hp = task
        return r17_eval_h(metodo, seed, hp)
    if kind == "W":
        _, metodo, seed, hp = task
        return r17_inventa_metodo(metodo, seed, hp)
    if kind == "D":
        _, cond, seed, hp = task
        return r17_laco_delirio(cond, seed, hp)["Youden"]
    if kind == "N":
        _, metodo, seed, hp = task
        return r17_eval_n(metodo, seed, hp)
    if kind == "H_tune":
        _, metodo, seeds_dev = task
        return r17_ajustar_h(metodo, list(seeds_dev))
    if kind == "W_tune":
        _, metodo, seeds_dev = task
        return r17_ajustar_w(metodo, list(seeds_dev))
    if kind == "D_tune":
        _, cond, seeds_dev = task
        return r17_ajustar_d(cond, list(seeds_dev))
    if kind == "N_tune":
        _, metodo, seeds_dev = task
        return r17_ajustar_n(metodo, list(seeds_dev))
    raise ValueError(kind)

# ----------------------------------------------------------------------
# BLOCO 25 — [R17] RAPHAEL CORRIGIDO + CANAL PN + DELÍRIO AMPLIADO + GAN MODULAR
# ----------------------------------------------------------------------

def r17_sementes(desloc: int = None):
    d = r17_desloc() if desloc is None else desloc
    return {
        "H_dev": [s + d for s in R17_SEEDS_H_DEV],
        "H_test": [s + d for s in R17_SEEDS_H_TEST],
        "W_dev": [s + d for s in R17_SEEDS_W_DEV],
        "W_test": [s + d for s in R17_SEEDS_W_TEST],
        "D_dev": [s + d for s in R17_SEEDS_D_DEV],
        "D_test": [s + d for s in R17_SEEDS_D_TEST],
        "N_dev": [s + d for s in R17_SEEDS_N_DEV],
        "N_test": [s + d for s in R17_SEEDS_N_TEST],
    }


def r17_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05 and media * sinal_esperado > 0:
        return "confirmada"
    if p_holm < 0.05 and media * sinal_esperado < 0:
        return "refutada"
    return "nula"


def r17_pareado_pack(diffs, seed=0):
    d = np.asarray(diffs, float)
    lo, hi = boot_ic(d, seed=seed)
    p = p_sinal_invertido(d, seed=seed)
    sd = float(d.std(ddof=1)) if len(d) > 1 else 0.0
    return {"media": float(d.mean()), "lo": lo, "hi": hi, "p": p, "mde": mde80(d),
            "vit": int((d > 0).sum()), "der": int((d < 0).sum()), "sd": sd, "n": len(d)}


def r17_tarefas(ctx):
    S = r17_sementes()
    tasks = []
    for met in R17_METODOS_H:
        tasks.append(("H_tune", met, tuple(S["H_dev"][:R17_NDEV])))
    for met in R17_METODOS_W:
        tasks.append(("W_tune", met, tuple(S["W_dev"][:R17_NDEV])))
    for cond in R17_CONDS_D:
        tasks.append(("D_tune", cond, tuple(S["D_dev"][:R17_NDEV])))
    for met in R17_METODOS_N:
        tasks.append(("N_tune", met, tuple(S["N_dev"][:R17_NDEV])))
    return r17_job, tasks


def bloco25(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 25 — [R17] RAPHAEL CORRIGIDO (heurística forte + override metacognitivo) + CANAL palavra↔número + "
               "DELÍRIO→ESCRUTÍNIO ampliado (TPR/FPR plantadas) + GAN MODULAR "
               "(14 confirmatórias, 40 sementes novas, Holm; pré-registro prereg_r17.txt)")
    desloc = r17_desloc()
    if desloc:
        rep.log(f"[R17_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r17_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R17_NTEST
    n_eval = 12 if rapido else R17_NEVAL_H
    n_prop = 12 if rapido else R17_NPROP_D
    n_inv = 20 if rapido else R17_NINV_W
    passos_n = 120 if rapido else R17_PASSOS_N

    # ---- H ----
    rep.sub("H — RAPHAEL CORRIGIDO: ajuste (DEV) e avaliação confirmatória")
    tuned = None
    if ctx.bg is not None:
        try:
            tuned = ctx.bg.obter("r17a")
        except Exception:
            tuned = None
    ti = 0
    hp_H = {}
    for met in R17_METODOS_H:
        if tuned is not None and ti < len(tuned):
            hp_H[met] = tuned[ti]
        else:
            nsort = 1 if rapido or met in ("guloso_tab", "guloso_forte") else R17_NSORT
            hp_H[met] = r17_ajustar_h(met, S["H_dev"][:R17_NDEV], n_sort=nsort)
        ti += 1
        rep.log(f"  ajuste {met}: {hp_H[met]}")
    scores_H = {met: [] for met in R17_METODOS_H}
    tasks = [("H", met, s, hp_H[met]) for met in R17_METODOS_H for s in S["H_test"][:n_test]]
    def _job_h(t):
        _, metodo, seed, hp = t
        return r17_eval_h(metodo, seed, hp, n_eval=n_eval)
    outs = mapa_paralelo(_job_h, tasks, jobs)
    k = 0
    for met in R17_METODOS_H:
        for _ in S["H_test"][:n_test]:
            scores_H[met].append(outs[k]); k += 1
    P_H = {}
    for hname, (a, b) in R17_PAR_H.items():
        d = np.asarray(scores_H[a]) - np.asarray(scores_H[b])
        P_H[hname] = r17_pareado_pack(d, seed=r17_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_H[hname]['media']:+.3f} p={P_H[hname]['p']:.4f}")

    # ---- W ----
    rep.sub("W — CANAL palavra↔número / invenção recalibrada (juiz limiar 0,40)")
    hp_W = {}
    for met in R17_METODOS_W:
        if tuned is not None and ti < len(tuned):
            hp_W[met] = tuned[ti]; ti += 1
        else:
            hp_W[met] = r17_ajustar_w(met, S["W_dev"][:R17_NDEV], n_sort=(1 if rapido or met in ("iid_letras", "markov2") else R17_NSORT))
            ti += 1
    scores_W = {met: [] for met in R17_METODOS_W}
    tasks = [("W", met, s, hp_W[met]) for met in R17_METODOS_W for s in S["W_test"][:n_test]]
    def _job_w(t):
        _, metodo, seed, hp = t
        return r17_inventa_metodo(metodo, seed, hp, n=n_inv)
    outs = mapa_paralelo(_job_w, tasks, jobs)
    k = 0
    for met in R17_METODOS_W:
        for _ in S["W_test"][:n_test]:
            scores_W[met].append(outs[k]); k += 1
    P_W = {}
    for wname, (a, b) in R17_PAR_W.items():
        d = np.asarray(scores_W[a]) - np.asarray(scores_W[b])
        P_W[wname] = r17_pareado_pack(d, seed=r17_crc(wname))
        rep.log(f"  {wname} ({a}−{b}): Δ={P_W[wname]['media']:+.3f} p={P_W[wname]['p']:.4f}")

    # ---- D ----
    rep.sub("D — DELÍRIO→ESCRUTÍNIO ampliado com propostas PLANTADAS (TPR/FPR/Youden)")
    hp_D = {}
    for cond in R17_CONDS_D:
        if tuned is not None and ti < len(tuned):
            hp_D[cond] = tuned[ti]; ti += 1
        else:
            hp_D[cond] = r17_ajustar_d(cond, S["D_dev"][:R17_NDEV], n_sort=(1 if rapido or cond == "oraculo_perfeito" else R17_NSORT))
            ti += 1
    scores_D = {c: [] for c in R17_CONDS_D}
    det_D = {c: [] for c in R17_CONDS_D}
    tasks = [("Dfull", c, s, hp_D[c]) for c in R17_CONDS_D for s in S["D_test"][:n_test]]
    def _job_d(t):
        _, cond, seed, hp = t
        return r17_laco_delirio(cond, seed, hp, nprop=n_prop)
    outs = mapa_paralelo(_job_d, tasks, jobs)
    k = 0
    for c in R17_CONDS_D:
        for _ in S["D_test"][:n_test]:
            r = outs[k]; k += 1
            scores_D[c].append(r["Youden"])
            det_D[c].append(r)
    # D1, D2, D4 pares; D3 = Youden(delirio_escrut) − 0
    P_D = {}
    pares_D = {"D1": ("delirio_escrut", "sobrio_escrut"), "D2": ("delirio_escrut", "delirio_sem_escrut"),
               "D4": ("sobrio_escrut", "delirio_sem_escrut")}
    for dname, (a, b) in pares_D.items():
        d = np.asarray(scores_D[a], float) - np.asarray(scores_D[b], float)
        P_D[dname] = r17_pareado_pack(d, seed=r17_crc(dname))
        rep.log(f"  {dname} ({a}−{b}): Δ={P_D[dname]['media']:+.3f} p={P_D[dname]['p']:.4f} | Youden {np.mean(scores_D[a]):.3f} vs {np.mean(scores_D[b]):.3f}")
    d3 = np.asarray(scores_D["delirio_escrut"], float)  # vs 0
    P_D["D3"] = r17_pareado_pack(d3, seed=r17_crc("D3"))
    rep.log(f"  D3 (Youden delirio_escrut vs 0): Δ={P_D['D3']['media']:+.3f} p={P_D['D3']['p']:.4f}")
    # TPR/FPR médios
    for c in R17_CONDS_D:
        tpr = float(np.mean([x["TPR"] for x in det_D[c]]))
        fpr = float(np.mean([x["FPR"] for x in det_D[c]]))
        rep.log(f"  [{c}] TPR={tpr:.3f} FPR={fpr:.3f} Youden={tpr-fpr:.3f}")

    # ---- N ----
    rep.sub("N — COLISÃO NN×GAN MODULAR vs monolito (desfecho = −JSD dos modos)")
    hp_N = {}
    for met in R17_METODOS_N:
        if tuned is not None and ti < len(tuned):
            hp_N[met] = tuned[ti]; ti += 1
        else:
            hp_N[met] = r17_ajustar_n(met, S["N_dev"][:R17_NDEV], n_sort=(1 if rapido else R17_NSORT))
            ti += 1
        rep.log(f"  ajuste {met}: {hp_N[met]}")
    scores_N = {met: [] for met in R17_METODOS_N}
    tasks = [("N", met, s, hp_N[met]) for met in R17_METODOS_N for s in S["N_test"][:n_test]]
    def _job_n(t):
        _, metodo, seed, hp = t
        return r17_treinar_gan(metodo, seed, hp, passos=passos_n)["neg_jsd"]
    outs = mapa_paralelo(_job_n, tasks, jobs)
    k = 0
    for met in R17_METODOS_N:
        for _ in S["N_test"][:n_test]:
            scores_N[met].append(outs[k]); k += 1
    P_N = {}
    for nname, (a, b) in R17_PAR_N.items():
        d = np.asarray(scores_N[a]) - np.asarray(scores_N[b])
        P_N[nname] = r17_pareado_pack(d, seed=r17_crc(nname))
        rep.log(f"  {nname} ({a}−{b}): Δ={P_N[nname]['media']:+.4f} p={P_N[nname]['p']:.4f}")

    # ---- Holm sobre 14 ----
    chaves = list(R17_HIPOT_H) + list(R17_HIPOT_W) + list(R17_HIPOT_D) + list(R17_HIPOT_N)
    Pall = {}
    Pall.update(P_H); Pall.update(P_W); Pall.update(P_D); Pall.update(P_N)
    ps = [Pall[k]["p"] for k in chaves]
    ph = holm(ps)
    st = {}
    for i, k in enumerate(chaves):
        st[k] = r17_status(Pall[k]["media"], ph[i], +1)
        Pall[k]["p_holm"] = float(ph[i])
    n_conf = sum(1 for k in chaves if st[k] == "confirmada")
    n_ref = sum(1 for k in chaves if st[k] == "refutada")
    n_nula = sum(1 for k in chaves if st[k] == "nula")
    rep.sub(f"FAMÍLIA CONFIRMATÓRIA R17 (Holm sobre {len(chaves)})")
    rep.log(f"{'id':<8}{'Δ':>10}{'IC lo':>10}{'IC hi':>10}{'p':>10}{'Holm':>10}  status")
    for k in chaves:
        v = Pall[k]
        rep.log(f"{k:<8}{v['media']:>+10.4f}{v['lo']:>+10.4f}{v['hi']:>+10.4f}{v['p']:>10.4f}{v['p_holm']:>10.4f}  {st[k]}")
    rep.log(f"Resumo R17: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas (de {len(chaves)}).")
    rep.log("PULADO (pedido do usuário, recusado): jailbreaks/backdoors/fugas de sandbox; chave de API; milhões literais.")

    ctx.res["r17"] = {
        "P": {k: (Pall[k]["media"], Pall[k]["lo"], Pall[k]["hi"], Pall[k]["p"], Pall[k]["p_holm"], Pall[k]["mde"]) for k in chaves},
        "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula, "chaves": chaves,
        "scores_H": {m: float(np.mean(scores_H[m])) for m in R17_METODOS_H},
        "scores_W": {m: float(np.mean(scores_W[m])) for m in R17_METODOS_W},
        "scores_D": {c: float(np.mean(scores_D[c])) for c in R17_CONDS_D},
        "scores_N": {m: float(np.mean(scores_N[m])) for m in R17_METODOS_N},
        "tpr_fpr": {c: (float(np.mean([x['TPR'] for x in det_D[c]])), float(np.mean([x['FPR'] for x in det_D[c]]))) for c in R17_CONDS_D},
        "n_test": n_test, "desloc": desloc,
    }


def registro_r17(ctx: Contexto) -> list:
    r = ctx.res.get("r17")
    out = []
    if not r:
        return out
    desc = {
        "H1": "Raphael: meta_override − guloso_tab (chips)",
        "H2": "Raphael: meta_override − guloso_forte (ablação parcial)",
        "H3": "Raphael: meta_override − meta_sempre (override só sob incerteza)",
        "H4": "Raphael: guloso_forte − guloso_tab",
        "W1": "invenção: canal_pn_filtro − iid_letras (juiz 0,40)",
        "W2": "invenção: canal_pn_jogo − iid_letras",
        "W3": "invenção: canal_pn_jogo − canal_pn_filtro",
        "D1": "Youden: delirio_escrut − sobrio_escrut",
        "D2": "Youden: delirio_escrut − delirio_sem_escrut",
        "D3": "Youden delirio_escrut > 0",
        "D4": "Youden: sobrio_escrut − delirio_sem_escrut",
        "N1": "GAN: modular − monolito (−JSD)",
        "N2": "GAN: modular − modular_aleat (−JSD)",
        "N3": "GAN: modular_aleat − monolito (−JSD)",
    }
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde = r["P"][k]
        out.append(("R17", f"R17-{k}", "CONF", desc.get(k, k), f"Δ={m:+.4f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm(14)={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    out.append(("R17", "R17-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors/sandbox escapes; chave API; milhões literais", "pulados", "descritiva"))
    return out


def sumario_r17_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r17")
    if not r:
        return ["• R17: (sem resultados nesta execução)"]
    return [f"• R17 BLOCO 25: {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de 14 confirmatórias (Raphael corrigido, canal PN, delírio TPR/FPR, GAN modular).",
            f"  H: " + ", ".join(f"{m}={r['scores_H'][m]:+.2f}" for m in R17_METODOS_H) +
            f" | W: " + ", ".join(f"{m}={r['scores_W'][m]:.2f}" for m in R17_METODOS_W) +
            f" | D Youden: " + ", ".join(f"{m}={r['scores_D'][m]:+.2f}" for m in R17_CONDS_D) +
            f" | N −JSD: " + ", ".join(f"{m}={r['scores_N'][m]:+.3f}" for m in R17_METODOS_N)]


