def r18_desloc() -> int:
    v = os.environ.get("R18_DEV", "").strip().lower()
    return 10000 if v not in ("", "0", "false", "no", "off") else 0


def r18_crc(rot: str) -> int:
    return zlib.crc32(f"R18|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r18_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


# ======================================================================
# W — CANAL palavra↔número COM PLANTIO
# ======================================================================

_R18_CV = ("ba", "be", "bi", "bo", "bu", "ca", "ce", "ci", "co", "cu",
           "da", "de", "di", "do", "du", "fa", "fe", "fi", "fo", "fu",
           "ga", "ge", "gi", "go", "gu", "la", "le", "li", "lo", "lu",
           "ma", "me", "mi", "mo", "mu", "na", "ne", "ni", "no", "nu",
           "pa", "pe", "pi", "po", "pu", "ra", "re", "ri", "ro", "ru",
           "sa", "se", "si", "so", "su", "ta", "te", "ti", "to", "tu")


def r18_numero_plantado(w: str) -> int:
    """Regra COERENTE pré-registrada: 1 + (soma_alfa + len + vogais) mod 12."""
    soma = sum((ord(c.lower()) - 96) for c in w if c.isalpha())
    vog = sum(1 for c in w.lower() if c in "aeiou")
    return 1 + (soma + len(w) + vog) % 12


def r18_lexico_plantado(seed: int, n: int = 48):
    """48 palavras CV determinísticas + número pela regra plantada."""
    rng = r18_rng(seed, r18_crc("lex"), 3)
    seen = set()
    pares = []
    tent = 0
    while len(pares) < n and tent < n * 40:
        tent += 1
        k = int(rng.integers(2, 5))
        w = "".join(_R18_CV[int(rng.integers(0, len(_R18_CV)))] for _ in range(k))
        if w in seen or len(w) < 4:
            continue
        seen.add(w)
        pares.append((w, r18_numero_plantado(w)))
    return pares


def r18_markov_de_pares(pares, ordem: int = 2):
    """Markov sobre o léxico plantado (só letras; ignora número)."""
    return r16_markov_letras([w for w, _ in pares], ordem=ordem)


def r18_juiz_plantado(w: str, n_pred: int, pares) -> bool:
    """Sucesso no modo plantado: número previsto == regra OU vizinho cos≥0,50."""
    if r18_numero_plantado(w) == n_pred:
        return True
    if not (4 <= len(w) <= 10):
        return False
    vw = r16_vec_palavra(w)
    best = -1.0
    for wp, _ in pares:
        c = float(np.dot(vw, r16_vec_palavra(wp)) / (np.linalg.norm(vw) * np.linalg.norm(r16_vec_palavra(wp)) + 1e-12))
        if c > best:
            best = c
    return best >= 0.50 and 4 <= len(w) <= 10


def r18_inventar_metodo(metodo: str, seed: int, hp: dict, modo: str, n: int = R18_NINV_W) -> float:
    """Taxa de sucesso sob juiz do modo (plantado|aberto)."""
    rng = r18_rng(seed, r18_crc(metodo + "|" + modo), 7)
    pares = r18_lexico_plantado(seed)
    P = r18_markov_de_pares(pares)
    lake = r16_lake_vecs()
    tau = float(hp.get("tau", 0.15))
    ok = 0
    gerados = 0
    tent = 0
    while gerados < n and tent < n * 30:
        tent += 1
        if metodo == "iid_letras":
            L = int(rng.integers(4, 11))
            w = "".join(chr(int(rng.integers(97, 123))) for _ in range(L))
        else:
            w = r16_inventar(P, rng, maxlen=10)
            if len(w) < 4:
                continue
        # filtragem / ranking
        if metodo == "estrutura_pn":
            n_pred = r18_numero_plantado(w)
            # prior: aceita se regra "faz sentido" internamente (sempre true by construction)
            # + afinidade mínima ao número
            af = r17_afinidade_pn(w, n_pred)
            if af < tau and modo == "aberto":
                # no aberto a regra é prior fraca: exige também oráculo ou af
                if not (r16_oraculo_offline(w) or af > tau * 0.5):
                    continue
            n_escolhido = n_pred
        elif metodo == "canal_pn_legado":
            afs = [r17_afinidade_pn(w, k) for k in range(1, 13)]
            n_escolhido = 1 + int(np.argmax(afs))
            if max(afs) < tau and not r16_oraculo_offline(w):
                continue
        elif metodo == "markov2":
            n_escolhido = r18_numero_plantado(w)  # só para juiz plantado; markov não usa
        else:
            n_escolhido = int(rng.integers(1, 13))
        gerados += 1
        if modo == "plantado":
            if r18_juiz_plantado(w, n_escolhido, pares):
                ok += 1
        else:
            if r17_juiz_recalibrado(w, lake):
                ok += 1
    return ok / max(gerados, 1)


def r18_sorteio_hp_w(i: int) -> dict:
    rng = r18_rng(r18_crc("W"), 18, i)
    return {"tau": float(rng.uniform(0.05, 0.45))}


def r18_ajustar_w(metodo: str, seeds_dev, modo: str = "plantado", n_sort: int = R18_NSORT) -> dict:
    if metodo in ("iid_letras", "markov2"):
        return {"tau": 0.15}
    best, bh = -1e18, r18_sorteio_hp_w(0)
    for i in range(n_sort):
        hp = r18_sorteio_hp_w(i)
        sc = float(np.mean([r18_inventar_metodo(metodo, s, hp, modo, n=20) for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


# ======================================================================
# D — DELÍRIO→ESCRUTÍNIO 2 ESTÁGIOS + LIMIARES DEV
# ======================================================================

def r18_proxy_rapido(comp) -> float:
    """Tela barata: confiança/novelty/ECE-proxy sem treinar MLP."""
    tag = comp["tag"]
    peso = float(comp.get("peso", 0.5))
    limiar = float(comp.get("limiar", 0.5))
    # heurística: tags úteis conhecidas ganham boost; harm_* perdem
    base = 0.45 + 0.2 * peso
    if tag in R17_GRAM_UTEIS:
        base += 0.25
    if tag in R17_GRAM_INUTEIS:
        base -= 0.35
    if tag in ("noise", "ent", "knn"):
        base += 0.05 * (1.0 - abs(limiar - 0.5))
    # novelty proxy: hash do nome
    h = (zlib.crc32(comp.get("nome", tag).encode()) & 0xFFFF) / 65535.0
    return float(np.clip(base + 0.05 * (h - 0.5), 0.0, 1.0))


def r18_score_laudo(r: dict) -> float:
    """Score contínuo do laudo (para limiar τ_laudo e ROC)."""
    s = 0.0
    s += 0.35 if r.get("V1") else 0.0
    s += 0.25 if r.get("V2") else 0.0
    s += 0.25 if r.get("V3") else 0.0
    s += 0.15 if r.get("V4") else 0.0
    s += 0.3 * float(np.clip(r.get("delta", 0.0), -0.5, 0.5) + 0.5)  # [0,0.3]
    return float(np.clip(s, 0.0, 1.0))


def r18_avaliar_proposta_scores(comp, seed: int) -> dict:
    """Reusa r17_avaliar_proposta + score contínuo + proxy."""
    r = r17_avaliar_proposta(comp, seed)
    r["proxy"] = r18_proxy_rapido(comp)
    r["score_laudo"] = r18_score_laudo(r)
    return r


def r18_laco_delirio(cond: str, seed: int, hp: dict, nprop: int = R18_NPROP_D) -> dict:
    """Youden com filtro 2-estágios ou baselines R17/sem/oráculo."""
    rng = r18_rng(seed, r18_crc(cond), 5)
    T_hi = float(hp.get("T_hi", 1.5))
    T_lo = float(hp.get("T_lo", 0.3))
    tau_tela = float(hp.get("tau_tela", 0.40))
    tau_laudo = float(hp.get("tau_laudo", 0.55))
    delirio = "delirio" in cond
    T = T_hi if delirio else T_lo
    props = []
    for i in range(R18_N_UTEIS):
        tag = R17_GRAM_UTEIS[i % len(R17_GRAM_UTEIS)]
        props.append(r17_propor_tag(rng, tag, T))
    for i in range(R18_N_INUTEIS):
        tag = R17_GRAM_INUTEIS[i % len(R17_GRAM_INUTEIS)]
        props.append(r17_propor_tag(rng, tag, T))
    n_livres = nprop - R18_N_UTEIS - R18_N_INUTEIS
    for _ in range(max(0, n_livres)):
        props.append(r17_propor_livre(rng, T))

    tp = fp = n_u = n_i = 0
    for i, comp in enumerate(props):
        if cond == "oraculo":
            mantem = bool(comp.get("util_ref"))
        elif cond == "delirio_sem":
            proxy = r18_proxy_rapido(comp)
            if proxy > 0.5:
                r = r18_avaliar_proposta_scores(comp, seed + 100 + i)
                mantem = r["delta"] > 0.0
            else:
                mantem = False
        elif cond == "delirio_r17":
            r = r17_avaliar_proposta(comp, seed + 100 + i)
            mantem = bool(r["mantem"])
        else:
            # 2 estágios
            proxy = r18_proxy_rapido(comp)
            if proxy < tau_tela:
                mantem = False
            else:
                r = r18_avaliar_proposta_scores(comp, seed + 100 + i)
                mantem = r["score_laudo"] >= tau_laudo
        if comp.get("util_ref"):
            n_u += 1
            if mantem:
                tp += 1
        elif comp.get("plantada") and not comp.get("util_ref"):
            n_i += 1
            if mantem:
                fp += 1
    TPR = tp / max(n_u, 1)
    FPR = fp / max(n_i, 1)
    return {"Youden": float(TPR - FPR), "TPR": float(TPR), "FPR": float(FPR), "tp": tp, "fp": fp}


def r18_sorteio_hp_d(i: int) -> dict:
    rng = r18_rng(r18_crc("D"), 18, i)
    return {
        "T_hi": float(rng.uniform(1.0, 2.5)),
        "T_lo": float(rng.uniform(0.15, 0.5)),
        "tau_tela": float(rng.uniform(0.25, 0.55)),
        "tau_laudo": float(rng.uniform(0.40, 0.75)),
    }


def r18_ajustar_d(cond: str, seeds_dev, n_sort: int = R18_NSORT) -> dict:
    if cond == "oraculo":
        return {"T_hi": 1.5, "T_lo": 0.3, "tau_tela": 0.0, "tau_laudo": 0.0}
    if cond == "delirio_r17":
        # limiares fixos R17 (só T)
        best, bh = -1e18, r18_sorteio_hp_d(0)
        for i in range(n_sort):
            hp = r18_sorteio_hp_d(i)
            hp = {"T_hi": hp["T_hi"], "T_lo": hp["T_lo"], "tau_tela": 0.0, "tau_laudo": 0.0}
            sc = float(np.mean([r18_laco_delirio(cond, s, hp)["Youden"] for s in seeds_dev]))
            if sc > best:
                best, bh = sc, hp
        return bh
    best, bh = -1e18, r18_sorteio_hp_d(0)
    for i in range(n_sort):
        hp = r18_sorteio_hp_d(i)
        sc = float(np.mean([r18_laco_delirio(cond, s, hp)["Youden"] for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


def r18_roc_dev(cond: str, seeds_dev, hp_base: dict):
    """Curva ROC exploratória no DEV variando τ_laudo (tela fixa)."""
    pontos = []
    for tau in np.linspace(0.2, 0.9, 8):
        hp = dict(hp_base); hp["tau_laudo"] = float(tau)
        ys = [r18_laco_delirio(cond, s, hp) for s in seeds_dev]
        tpr = float(np.mean([y["TPR"] for y in ys]))
        fpr = float(np.mean([y["FPR"] for y in ys]))
        you = float(np.mean([y["Youden"] for y in ys]))
        pontos.append({"tau_laudo": float(tau), "TPR": tpr, "FPR": fpr, "Youden": you})
    # Youden máximo
    best = max(pontos, key=lambda p: p["Youden"])
    return pontos, best


# ======================================================================
# N — GAN MODULAR MAIS DURA (5 modos, dim 4) + CONTROLADORES
# ======================================================================

def r18_dados_modos(n: int, seed: int):
    rng = r18_rng(seed, 91)
    # 5 centros em R^4 (simplex-ish)
    centros = np.array([
        [2.0, 0.0, 0.0, 0.0],
        [-2.0, 0.0, 0.0, 0.0],
        [0.0, 2.0, 0.0, 0.0],
        [0.0, -1.5, 1.5, 0.0],
        [0.0, 0.0, -1.5, 1.5],
    ], float)
    y = rng.integers(0, 5, size=n)
    X = centros[y] + 0.30 * rng.normal(0, 1, size=(n, 4))
    return X, centros


def r18_jsd_modos(fake, centros) -> float:
    d = ((fake[:, None, :] - centros[None, :, :]) ** 2).sum(-1)
    atr = d.argmin(1)
    k = centros.shape[0]
    hist = np.bincount(atr, minlength=k).astype(float)
    hist = hist / (hist.sum() + 1e-12)
    alvo = np.ones(k) / float(k)
    m = 0.5 * (hist + alvo)
    def _kl(p, q):
        return float(np.sum(np.where(p > 0, p * np.log((p + 1e-12) / (q + 1e-12)), 0.0)))
    return 0.5 * _kl(hist, m) + 0.5 * _kl(alvo, m)


def r18_ctrl_incerteza(hist_loss, d_acc, ent_d, modo_proxy, rng):
    mg = [1, 1]; md = [1, 1]
    if ent_d > 0.65:
        mg = [1, 0]; md = [1, 0]  # encoders
    else:
        mg = [0, 1]; md = [0, 1]  # heads
    if d_acc > 0.9:
        md = [0, 0]
    return tuple(mg), tuple(md)


def r18_ctrl_perda(hist_loss, d_acc, ent_d, modo_proxy, rng):
    mg = [1, 1]; md = [1, 1]
    osc = float(np.std(hist_loss[-20:])) if len(hist_loss) >= 5 else 0.0
    if osc > 0.12:
        mg = [0, 1]; md = [0, 1]
    if modo_proxy > 0.45:
        mg = [1, 1]; md = [0, 0]
        return tuple(mg), tuple(md)
    if d_acc > 0.9:
        md = [0, 0]
    if d_acc < 0.55:
        md = [1, 1]; mg = [0, 1]
    return tuple(mg), tuple(md)


def r18_ctrl_prolog(hist_loss, d_acc, ent_d, modo_proxy, rng):
    """Regras estilo Prolog: combina incerteza e perda."""
    osc = float(np.std(hist_loss[-20:])) if len(hist_loss) >= 5 else 0.0
    # fatos
    gira = osc > 0.12
    incerto = ent_d > 0.65
    colapsa = modo_proxy > 0.45
    d_forte = d_acc > 0.9
    d_fraco = d_acc < 0.55
    # regras (prioridade)
    if colapsa:
        return (1, 1), (0, 0)
    if gira and incerto:
        return (1, 0), (1, 0)
    if gira:
        return (0, 1), (0, 1)
    if d_forte:
        return (1, 1), (0, 0)
    if d_fraco:
        return (0, 1), (1, 1)
    if incerto:
        return (1, 0), (1, 0)
    return (1, 1), (1, 1)


def r18_treinar_gan(metodo: str, seed: int, hp: dict, passos: int = R18_PASSOS_N) -> dict:
    rng = r18_rng(seed, r18_crc(metodo), 19)
    X, centros = r18_dados_modos(200, seed)
    hid = 10
    dim = 4
    G = (rng.normal(0, 0.35, (dim, hid)), np.zeros(hid), rng.normal(0, 0.35, (hid, dim)), np.zeros(dim))
    D = (rng.normal(0, 0.35, (dim, hid)), np.zeros(hid), rng.normal(0, 0.35, (hid, 1)), np.zeros(1))
    lr_g = float(hp.get("lr_g", 0.05))
    lr_d = float(hp.get("lr_d", 0.05))
    hist = []
    d_acc_ema = 0.5
    ent_ema = 0.7
    for t in range(passos):
        idx = rng.integers(0, len(X), size=32)
        Xb = X[idx]
        Z = rng.normal(0, 1, size=(32, dim))
        # entropia de D sobre batch
        real_logit0, _ = r17_mlp_forward(Xb, *D)
        pr0 = 1 / (1 + np.exp(-np.clip(real_logit0.ravel(), -20, 20)))
        ent = float(-(pr0 * np.log(pr0 + 1e-9) + (1 - pr0) * np.log(1 - pr0 + 1e-9)).mean() / math.log(2))
        ent_ema = 0.9 * ent_ema + 0.1 * ent
        if t > 20 and t % 25 == 0:
            Zq = rng.normal(0, 1, size=(80, dim))
            fq, _ = r17_mlp_forward(Zq, *G)
            modo_proxy = r18_jsd_modos(fq, centros)
        else:
            modo_proxy = 0.3
        if metodo == "monolito":
            mg, md = (1, 1), (1, 1)
        elif metodo == "modular_aleat":
            mg = (int(rng.integers(0, 2)), int(rng.integers(0, 2)))
            md = (int(rng.integers(0, 2)), int(rng.integers(0, 2)))
            if mg == (0, 0):
                mg = (1, 1)
            if md == (0, 0):
                md = (1, 0)
        elif metodo == "ctrl_incerteza":
            mg, md = r18_ctrl_incerteza(hist, d_acc_ema, ent_ema, modo_proxy, rng)
        elif metodo == "ctrl_perda":
            mg, md = r18_ctrl_perda(hist, d_acc_ema, ent_ema, modo_proxy, rng)
        elif metodo == "ctrl_prolog":
            mg, md = r18_ctrl_prolog(hist, d_acc_ema, ent_ema, modo_proxy, rng)
        else:
            mg, md = (1, 1), (1, 1)
        G, D, loss_d, pf = r17_gan_step(G, D, Z, Xb, lr_g, lr_d, mg, md)
        hist.append(loss_d)
        real_logit, _ = r17_mlp_forward(Xb, *D)
        pr = 1 / (1 + np.exp(-np.clip(real_logit.ravel(), -20, 20)))
        d_acc = 0.5 * (float((pr > 0.5).mean()) + float(pf < 0.5))
        d_acc_ema = 0.9 * d_acc_ema + 0.1 * d_acc
    Zq = rng.normal(0, 1, size=(150, dim))
    fq, _ = r17_mlp_forward(Zq, *G)
    jsd = r18_jsd_modos(fq, centros)
    return {"neg_jsd": -float(jsd), "jsd": float(jsd)}


def r18_sorteio_hp_n(i: int) -> dict:
    rng = r18_rng(r18_crc("N"), 18, i)
    return {"lr_g": float(rng.choice([0.02, 0.05, 0.08, 0.12])),
            "lr_d": float(rng.choice([0.02, 0.05, 0.08, 0.12]))}


def r18_ajustar_n(metodo: str, seeds_dev, n_sort: int = R18_NSORT) -> dict:
    best, bh = -1e18, r18_sorteio_hp_n(0)
    for i in range(n_sort):
        hp = r18_sorteio_hp_n(i)
        sc = float(np.mean([r18_treinar_gan(metodo, s, hp, passos=120)["neg_jsd"] for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


def r18_eval_n(metodo: str, seed: int, hp: dict, passos: int = None) -> float:
    return r18_treinar_gan(metodo, seed, hp, passos=passos or R18_PASSOS_N)["neg_jsd"]


# ======================================================================
# C — APRENDIZADO CONTÍNUO → RL / TRANSFERÊNCIA
# ======================================================================

def r18_vec8(w: str) -> np.ndarray:
    v = r16_vec_palavra(w, dim=8).astype(float)
    n = np.linalg.norm(v) + 1e-12
    return v / n


def r18_fase1_raphael(seed: int, n_partidas: int = R18_N_RAPHAEL_C):
    """Joga Raphael com guloso_forte; atualiza vetores EMA e θ linear por REINFORCE."""
    rng = r18_rng(seed, r18_crc("C1"), 11)
    # dicionário de cartas → vetor
    vecs = {}
    theta = rng.normal(0, 0.05, size=8)  # política linear sobre features da carta
    baseline = 0.0
    lr_v, lr_t = 0.15, 0.08
    hist_ret = []
    for p in range(n_partidas):
        # uma partida curta vs guloso_tab
        hp = {"tau": 1.0, "eta": 0.6, "delta": 0.8, "lam": 0.5}
        ret = r17_eval_h("guloso_forte", seed + 17 * p, hp, n_eval=1)
        hist_ret.append(ret)
        # carta sintética da partida
        carta_w = "".join(_R18_CV[int(rng.integers(0, len(_R18_CV)))] for _ in range(3))
        if carta_w not in vecs:
            vecs[carta_w] = r18_vec8(carta_w)
        v = vecs[carta_w]
        # REINFORCE: θ ← θ + lr*(ret-baseline)*v
        baseline = 0.9 * baseline + 0.1 * ret
        adv = ret - baseline
        theta = theta + lr_t * adv * v
        # EMA do vetor na direção do retorno
        vecs[carta_w] = (1 - lr_v) * v + lr_v * np.sign(adv + 1e-9) * v
        nrm = np.linalg.norm(vecs[carta_w]) + 1e-12
        vecs[carta_w] = vecs[carta_w] / nrm
    return {"vecs": vecs, "theta": theta, "ret_medio": float(np.mean(hist_ret)) if hist_ret else 0.0}


def r18_jogo_alvo(seed: int, vecs, theta, n_itens: int = R18_N_ALVO_C, n_passos: int = 40, lr: float = 0.1):
    """Jogo retido: prever número (1..12) a partir da palavra; treina θ/vecs conforme flags externos."""
    rng = r18_rng(seed, r18_crc("alvo"), 13)
    pares = r18_lexico_plantado(seed + 99, n=60)
    # split
    itens = pares[:n_itens]
    hold = pares[n_itens:n_itens + 30] if len(pares) > n_itens + 30 else pares[-30:]
    # cópias locais
    V = {w: (vecs[w].copy() if w in vecs else r18_vec8(w)) for w, _ in pares}
    th = theta.copy()
    for step in range(n_passos):
        w, n_true = itens[int(rng.integers(0, len(itens)))]
        v = V[w]
        # scores para 12 classes: projeta v⊙φ(k) onde φ é vetor cíclico
        scores = np.array([float(np.dot(th * v, r16_vec_numero(k, 8))) for k in range(1, 13)])
        # softmax + cross-entropy gradiente simples
        ex = np.exp(scores - scores.max()); p = ex / ex.sum()
        y = n_true - 1
        g = p.copy(); g[y] -= 1.0
        # d/dθ ≈ sum_k g_k * (v ⊙ φ(k))
        gth = np.zeros(8)
        for k in range(1, 13):
            gth += g[k - 1] * (v * r16_vec_numero(k, 8))
        th = th - lr * gth
        # leve update do vetor
        V[w] = V[w] - 0.05 * lr * gth
        nrm = np.linalg.norm(V[w]) + 1e-12
        V[w] = V[w] / nrm
    # holdout
    acertos = 0
    for w, n_true in hold:
        v = V.get(w, r18_vec8(w))
        scores = np.array([float(np.dot(th * v, r16_vec_numero(k, 8))) for k in range(1, 13)])
        pred = 1 + int(np.argmax(scores))
        if pred == n_true:
            acertos += 1
    return acertos / max(len(hold), 1)


def r18_eval_c(metodo: str, seed: int, hp: dict) -> float:
    n_passos = int(hp.get("n_passos", 40))
    lr = float(hp.get("lr", 0.1))
    fonte = r18_fase1_raphael(seed, n_partidas=R18_N_RAPHAEL_C)
    rng = r18_rng(seed, 3)
    if metodo == "frio":
        vecs, theta = {}, rng.normal(0, 0.05, size=8)
        return r18_jogo_alvo(seed, vecs, theta, n_passos=n_passos, lr=lr)
    if metodo == "transfer_vetor":
        return r18_jogo_alvo(seed, fonte["vecs"], rng.normal(0, 0.05, size=8), n_passos=n_passos, lr=lr)
    if metodo == "transfer_politica":
        return r18_jogo_alvo(seed, {}, fonte["theta"], n_passos=n_passos, lr=lr)
    if metodo == "transfer_ambos":
        return r18_jogo_alvo(seed, fonte["vecs"], fonte["theta"], n_passos=n_passos, lr=lr)
    if metodo == "continuo":
        # 50/50: metade passos com refresh da fonte intercalado
        half = max(1, n_passos // 2)
        # primeiro half no alvo a partir de fonte
        acc1 = r18_jogo_alvo(seed, fonte["vecs"], fonte["theta"], n_passos=half, lr=lr)
        # refresh fonte e mais half
        fonte2 = r18_fase1_raphael(seed + 1000, n_partidas=max(4, R18_N_RAPHAEL_C // 2))
        # mescla vetores
        vmix = dict(fonte["vecs"])
        for w, v in fonte2["vecs"].items():
            vmix[w] = 0.5 * vmix.get(w, v) + 0.5 * v
        th = 0.5 * fonte["theta"] + 0.5 * fonte2["theta"]
        acc2 = r18_jogo_alvo(seed + 7, vmix, th, n_passos=half, lr=lr)
        return 0.5 * (acc1 + acc2)
    raise ValueError(metodo)


def r18_sorteio_hp_c(i: int) -> dict:
    rng = r18_rng(r18_crc("C"), 18, i)
    return {"n_passos": int(rng.choice([20, 40, 60])), "lr": float(rng.choice([0.05, 0.1, 0.2]))}


def r18_ajustar_c(metodo: str, seeds_dev, n_sort: int = R18_NSORT) -> dict:
    best, bh = -1e18, r18_sorteio_hp_c(0)
    for i in range(n_sort):
        hp = r18_sorteio_hp_c(i)
        sc = float(np.mean([r18_eval_c(metodo, s, hp) for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


# ---------- despacho puro ----------
def r18_job(task):
    kind = task[0]
    if kind == "W":
        _, metodo, seed, hp, modo = task
        return r18_inventar_metodo(metodo, seed, hp, modo)
    if kind == "D":
        _, cond, seed, hp = task
        return r18_laco_delirio(cond, seed, hp)["Youden"]
    if kind == "N":
        _, metodo, seed, hp = task
        return r18_eval_n(metodo, seed, hp)
    if kind == "C":
        _, metodo, seed, hp = task
        return r18_eval_c(metodo, seed, hp)
    if kind == "W_tune":
        _, metodo, seeds_dev, modo = task
        return r18_ajustar_w(metodo, list(seeds_dev), modo=modo)
    if kind == "D_tune":
        _, cond, seeds_dev = task
        return r18_ajustar_d(cond, list(seeds_dev))
    if kind == "N_tune":
        _, metodo, seeds_dev = task
        return r18_ajustar_n(metodo, list(seeds_dev))
    if kind == "C_tune":
        _, metodo, seeds_dev = task
        return r18_ajustar_c(metodo, list(seeds_dev))
    if kind == "M":
        _, metodo, seed, hp = task
        return r18_mega_eval(metodo, seed, hp)
    if kind == "M_tune":
        _, metodo, _seeds = task
        return r18_mega_ajustar(metodo)
    if kind == "S":
        _, metodo, seed, hp = task
        return r18_eval_s(metodo, seed, hp)["neg_jsd"]
    if kind == "S_tune":
        _, metodo, seeds_dev = task
        return r18_ajustar_s(metodo, list(seeds_dev))
    if kind == "A":
        _, metodo, seed, hp = task
        return r18_eval_a(metodo, seed, hp)
    if kind == "A_tune":
        _, metodo, seeds_dev = task
        return r18_ajustar_a(metodo, list(seeds_dev))
    raise ValueError(kind)

