R18_MEGA_NTEST = 200  # [R18] 200 walk-forward (era 400; custo; declarado no Adendo1)          # últimos N sorteios no teste (walk-forward)
R18_MEGA_METODOS = (
    "uniforme", "frequencia", "gaps", "coocorrencia",
    "logreg_numpy", "reforco_ordinario", "reforco_extraordinario",
)
R18_HIPOT_M = ("M1", "M2", "M3", "M4", "M5", "M6")
# Contrastes: método − uniforme, desfecho = taxa de acerto de dezenas (hits/6) média; sinal esperado ≤0 sob nula de imprevisibilidade
# Pré-registro no Adendo 1 (pedido do usuário APÓS carimbo do corpo):
#   M1 frequencia − uniforme
#   M2 gaps − uniforme
#   M3 coocorrencia − uniforme
#   M4 logreg_numpy − uniforme
#   M5 reforco_ordinario − uniforme
#   M6 reforco_extraordinario − uniforme
# Confirmada SÓ se Holm<0.05 E Δ>0 (bate chance). Expectativa: todos nulos/refutados.
R18_PAR_M = {
    "M1": ("frequencia", "uniforme"),
    "M2": ("gaps", "uniforme"),
    "M3": ("coocorrencia", "uniforme"),
    "M4": ("logreg_numpy", "uniforme"),
    "M5": ("reforco_ordinario", "uniforme"),
    "M6": ("reforco_extraordinario", "uniforme"),
}
R18_SEEDS_M = list(range(20900, 20904))  # 4 sementes (custo; Adendo1)


def r18_mega_carregar():
    """Decodifica o histórico embutido → lista [(concurso, [n1..n6]), ...] ordenada."""
    raw = zlib.decompress(_b64.b64decode("".join(R18_MEGA_B64)))
    out = []; i = 0
    while i + 8 <= len(raw):
        n = _struct.unpack_from("<H", raw, i)[0]; i += 2
        nums = list(raw[i:i+6]); i += 6
        out.append((int(n), [int(x) for x in nums]))
    return out


_R18_MEGA_CACHE = None
def r18_mega_draws():
    global _R18_MEGA_CACHE
    if _R18_MEGA_CACHE is None:
        _R18_MEGA_CACHE = r18_mega_carregar()
    return _R18_MEGA_CACHE


def r18_mega_chance_hits():
    """E[hits/6] sob aposta uniforme de 6 em 60 (hipergeométrica)."""
    # E[X] = 6*(6/60)=0.6; taxa = E[X]/6 = 0.1
    return 0.1


def r18_mega_p_k(k: int) -> float:
    """P(exatamente k acertos) hipergeométrica."""
    from math import comb
    return comb(6, k) * comb(54, 6 - k) / comb(60, 6) if 0 <= k <= 6 else 0.0


def r18_mega_features(hist, janela: int = 50):
    """Contagem, gaps e pares a partir do histórico passado (sem vazamento)."""
    freq = np.zeros(61, float)
    last = np.full(61, -10**9, int)
    pair = np.zeros((61, 61), float)
    for t, (conc, nums) in enumerate(hist):
        for a in nums:
            freq[a] += 1.0
            last[a] = t
        for i in range(6):
            for j in range(i+1, 6):
                a, b = nums[i], nums[j]
                pair[a, b] += 1; pair[b, a] += 1
    gaps = np.array([len(hist) - 1 - last[i] if last[i] >= 0 else len(hist) + 10 for i in range(61)], float)
    return freq, gaps, pair


def r18_mega_escolher(metodo: str, hist, rng, hp: dict) -> list:
    """Escolhe 6 dezenas ∈{1..60} usando SÓ hist (passado)."""
    if len(hist) < 10:
        return sorted(rng.choice(np.arange(1, 61), size=6, replace=False).tolist())
    freq, gaps, pair = r18_mega_features(hist)
    tau = float(hp.get("tau", 1.0))
    if metodo == "uniforme":
        return sorted(rng.choice(np.arange(1, 61), size=6, replace=False).tolist())
    if metodo == "frequencia":
        # top-6 mais frequentes; empate quebrado por rng
        score = freq[1:] + 1e-6 * rng.random(60)
        idx = np.argsort(-score)[:6] + 1
        return sorted(int(x) for x in idx)
    if metodo == "gaps":
        score = gaps[1:] + 1e-6 * rng.random(60)
        idx = np.argsort(-score)[:6] + 1
        return sorted(int(x) for x in idx)
    if metodo == "coocorrencia":
        # score = freq + λ * força de pares com já escolhidos (guloso)
        score = freq.copy()
        escolhidos = []
        for _ in range(6):
            s = score[1:].copy()
            for e in escolhidos:
                s += 0.15 * pair[1:, e]
            s += 1e-6 * rng.random(60)
            for e in escolhidos:
                s[e-1] = -1e18
            a = int(np.argmax(s)) + 1
            escolhidos.append(a)
        return sorted(escolhidos)
    if metodo == "logreg_numpy":
        # score linear: w0*freq_norm + w1*gap_norm + w2*recency_pair; pesos do hp
        f = freq[1:]; f = f / (f.max() + 1e-9)
        g = gaps[1:]; g = g / (g.max() + 1e-9)
        w0 = float(hp.get("w0", 0.5)); w1 = float(hp.get("w1", 0.3)); w2 = float(hp.get("w2", 0.2))
        # recency: 1/(1+gap)
        rec = 1.0 / (1.0 + gaps[1:])
        s = w0 * f + w1 * g + w2 * rec + 1e-6 * rng.random(60)
        # softmax temperature sampling of top
        logits = s / max(tau, 1e-3)
        ex = np.exp(logits - logits.max()); p = ex / ex.sum()
        escolhidos = []
        pp = p.copy()
        for _ in range(6):
            a = int(rng.choice(60, p=pp)) + 1
            escolhidos.append(a)
            pp[a-1] = 0; pp = pp / (pp.sum() + 1e-15)
        return sorted(set(escolhidos)) if len(set(escolhidos)) == 6 else sorted(rng.choice(np.arange(1,61), size=6, replace=False).tolist())
    # reforço: mantém pesos adaptativos em hp["_w"] shape (60,)
    w = hp.get("_w")
    if w is None:
        w = np.zeros(60, float)
        hp["_w"] = w
    f = freq[1:] / (freq[1:].max() + 1e-9)
    g = gaps[1:] / (gaps[1:].max() + 1e-9)
    s = w + 0.3 * f + 0.2 * g + 1e-6 * rng.random(60)
    idx = np.argsort(-s)[:6] + 1
    return sorted(int(x) for x in idx)


def r18_mega_atualizar_reforco(metodo: str, hp: dict, aposta: list, verdade: list, p_meta: float, rng):
    """Reforço ordinário (mais update no ACERTO) vs extraordinário (mais update no ERRO).
    Probabilidade metacognitiva p_meta: só atualiza com prob p_meta (incerteza ativa)."""
    if metodo not in ("reforco_ordinario", "reforco_extraordinario"):
        return
    if rng.random() > p_meta:
        return
    w = hp.setdefault("_w", np.zeros(60, float))
    hits = set(aposta) & set(verdade)
    n_hit = len(hits)
    lr = float(hp.get("lr", 0.05))
    if metodo == "reforco_ordinario":
        # recompensa no acerto: sobe pesos dos acertos; desce levemente os errados da aposta
        for a in aposta:
            if a in hits:
                w[a-1] += lr * (1.0 + 0.5 * n_hit)
            else:
                w[a-1] -= lr * 0.2
    else:
        # extraordinário: motivação/atualização MAIOR no ERRO
        for a in aposta:
            if a in hits:
                w[a-1] += lr * 0.3
            else:
                w[a-1] -= lr * (1.0 + 0.8 * (6 - n_hit))  # erro forte
        # também explora números ausentes com gap alto? leve boost nos não apostados mais atrasados
        # (já coberto pelo score de gaps na escolha)


def r18_mega_features_inc_init(hist):
    """Estado incremental de freq/gaps/pair a partir de hist inicial."""
    freq = np.zeros(61, float)
    last = np.full(61, -10**9, int)
    pair = np.zeros((61, 61), float)
    for t, (conc, nums) in enumerate(hist):
        for a in nums:
            freq[a] += 1.0
            last[a] = t
        for i in range(6):
            for j in range(i+1, 6):
                a, b = nums[i], nums[j]
                pair[a, b] += 1; pair[b, a] += 1
    return freq, last, pair, len(hist)


def r18_mega_features_inc_update(freq, last, pair, t_idx, nums):
    for a in nums:
        freq[a] += 1.0
        last[a] = t_idx
    for i in range(6):
        for j in range(i+1, 6):
            a, b = nums[i], nums[j]
            pair[a, b] += 1; pair[b, a] += 1


def r18_mega_escolher_fast(metodo, freq, last, pair, t_len, rng, hp):
    """Escolha usando estado incremental (sem re-scan do histórico)."""
    gaps = np.array([t_len - 1 - last[i] if last[i] >= 0 else t_len + 10 for i in range(61)], float)
    tau = float(hp.get("tau", 1.0))
    if metodo == "uniforme" or t_len < 10:
        return sorted(rng.choice(np.arange(1, 61), size=6, replace=False).tolist())
    if metodo == "frequencia":
        score = freq[1:] + 1e-6 * rng.random(60)
        return sorted(int(x) for x in (np.argsort(-score)[:6] + 1))
    if metodo == "gaps":
        score = gaps[1:] + 1e-6 * rng.random(60)
        return sorted(int(x) for x in (np.argsort(-score)[:6] + 1))
    if metodo == "coocorrencia":
        score = freq.copy(); escolhidos = []
        for _ in range(6):
            s = score[1:].copy()
            for e in escolhidos:
                s += 0.15 * pair[1:, e]
            s += 1e-6 * rng.random(60)
            for e in escolhidos:
                s[e-1] = -1e18
            a = int(np.argmax(s)) + 1
            escolhidos.append(a)
        return sorted(escolhidos)
    if metodo == "logreg_numpy":
        f = freq[1:] / (freq[1:].max() + 1e-9)
        g = gaps[1:] / (gaps[1:].max() + 1e-9)
        rec = 1.0 / (1.0 + gaps[1:])
        w0 = float(hp.get("w0", 0.5)); w1 = float(hp.get("w1", 0.3)); w2 = float(hp.get("w2", 0.2))
        s = w0*f + w1*g + w2*rec + 1e-6*rng.random(60)
        logits = s / max(tau, 1e-3)
        ex = np.exp(logits - logits.max()); pp = ex/ex.sum()
        escolhidos = []
        for _ in range(6):
            a = int(rng.choice(60, p=pp)) + 1
            escolhidos.append(a)
            pp[a-1] = 0; ssum = pp.sum()
            if ssum <= 0: break
            pp = pp / ssum
        return sorted(set(escolhidos)) if len(set(escolhidos))==6 else sorted(rng.choice(np.arange(1,61), size=6, replace=False).tolist())
    w = hp.get("_w")
    if w is None:
        w = np.zeros(60, float); hp["_w"] = w
    f = freq[1:]/(freq[1:].max()+1e-9); g = gaps[1:]/(gaps[1:].max()+1e-9)
    s = w + 0.3*f + 0.2*g + 1e-6*rng.random(60)
    return sorted(int(x) for x in (np.argsort(-s)[:6] + 1))


def r18_mega_backtest(metodo: str, seed: int, hp: dict, n_teste: int = R18_MEGA_NTEST) -> dict:
    """Walk-forward incremental (O(n) em vez de O(n²))."""
    draws = r18_mega_draws()
    assert len(draws) > n_teste + 50
    rng = r18_rng(seed, r18_crc("MEGA|" + metodo), 77)
    hp = dict(hp); hp["_w"] = np.zeros(60, float)
    p_meta = float(hp.get("p_meta", 0.7))
    inicio = len(draws) - n_teste
    freq, last, pair, t_len = r18_mega_features_inc_init(draws[:inicio])
    hits_list = []; terna = quadra = quina = sena = 0
    brier_acc = 0.0; n_brier = 0
    for t in range(inicio, len(draws)):
        verdade = draws[t][1]
        aposta = r18_mega_escolher_fast(metodo, freq, last, pair, t_len, rng, hp)
        if len(aposta) != 6:
            aposta = sorted(rng.choice(np.arange(1, 61), size=6, replace=False).tolist())
        hit = len(set(aposta) & set(verdade))
        hits_list.append(hit / 6.0)
        if hit >= 3: terna += 1
        if hit >= 4: quadra += 1
        if hit >= 5: quina += 1
        if hit >= 6: sena += 1
        s = freq[1:] / (freq[1:].sum() + 1e-9) + 0.01; s = s / s.sum()
        y = np.zeros(60)
        for v in verdade: y[v-1] = 1.0
        brier_acc += float(((s - y) ** 2).mean()); n_brier += 1
        r18_mega_atualizar_reforco(metodo, hp, aposta, verdade, p_meta, rng)
        # atualiza estado com o sorteio t (agora passado)
        r18_mega_features_inc_update(freq, last, pair, t_len, verdade)
        t_len += 1
    taxa = float(np.mean(hits_list))
    return {
        "taxa_dezena": taxa, "hits_medio": float(np.mean([h*6 for h in hits_list])),
        "terna": terna/n_teste, "quadra": quadra/n_teste, "quina": quina/n_teste, "sena": sena/n_teste,
        "brier": brier_acc/max(n_brier,1), "n": n_teste, "chance_dezena": r18_mega_chance_hits(),
    }


def r18_mega_sorteio_hp(i: int) -> dict:
    rng = r18_rng(r18_crc("MEGA_HP"), 18, i)
    return {
        "tau": float(rng.uniform(0.5, 2.0)),
        "w0": float(rng.uniform(0.2, 0.8)),
        "w1": float(rng.uniform(0.1, 0.6)),
        "w2": float(rng.uniform(0.05, 0.4)),
        "lr": float(rng.choice([0.02, 0.05, 0.1])),
        "p_meta": float(rng.uniform(0.4, 0.95)),
    }


def r18_mega_ajustar(metodo: str, n_sort: int = 4, n_val: int = 100) -> dict:
    """Ajuste SÓ no passado remoto (concursos antes da janela de teste)."""
    if metodo == "uniforme":
        return {"tau": 1.0, "p_meta": 0.7, "lr": 0.05}
    draws = r18_mega_draws()
    # validação: sorteios imediatamente anteriores à janela de teste
    n_teste = R18_MEGA_NTEST
    fim_val = len(draws) - n_teste
    inicio_val = max(50, fim_val - n_val)
    best, bh = -1e18, r18_mega_sorteio_hp(0)
    for i in range(n_sort):
        hp = r18_mega_sorteio_hp(i)
        # mini backtest na janela de validação
        rng = r18_rng(1818, i, r18_crc(metodo))
        hp = dict(hp); hp["_w"] = np.zeros(60, float)
        hits = []
        for t in range(inicio_val, fim_val):
            ap = r18_mega_escolher(metodo, draws[:t], rng, hp)
            verd = draws[t][1]
            hits.append(len(set(ap) & set(verd)) / 6.0)
            r18_mega_atualizar_reforco(metodo, hp, ap, verd, hp.get("p_meta", 0.7), rng)
        sc = float(np.mean(hits)) if hits else 0.0
        if sc > best:
            best, bh = sc, {k: v for k, v in hp.items() if k != "_w"}
    return bh


def r18_mega_eval(metodo: str, seed: int, hp: dict) -> float:
    return r18_mega_backtest(metodo, seed, hp)["taxa_dezena"]

# ----------------------------------------------------------------------
# BLOCO 26 — [R18] CANAL PN PLANTADO + DELÍRIO 2-ESTÁGIOS + GAN DURA + CL→RL
# ----------------------------------------------------------------------

def r18_sementes(desloc: int = None):
    d = r18_desloc() if desloc is None else desloc
    return {
        "W_dev": [s + d for s in R18_SEEDS_W_DEV],
        "W_test": [s + d for s in R18_SEEDS_W_TEST],
        "D_dev": [s + d for s in R18_SEEDS_D_DEV],
        "D_test": [s + d for s in R18_SEEDS_D_TEST],
        "N_dev": [s + d for s in R18_SEEDS_N_DEV],
        "N_test": [s + d for s in R18_SEEDS_N_TEST],
        "C_dev": [s + d for s in R18_SEEDS_C_DEV],
        "C_test": [s + d for s in R18_SEEDS_C_TEST],
    }


def r18_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05 and media * sinal_esperado > 0:
        return "confirmada"
    if p_holm < 0.05 and media * sinal_esperado < 0:
        return "refutada"
    return "nula"


def r18_pareado_pack(diffs, seed=0):
    d = np.asarray(diffs, float)
    lo, hi = boot_ic(d, seed=seed)
    p = p_sinal_invertido(d, seed=seed)
    sd = float(d.std(ddof=1)) if len(d) > 1 else 0.0
    return {"media": float(d.mean()), "lo": lo, "hi": hi, "p": p, "mde": mde80(d),
            "vit": int((d > 0).sum()), "der": int((d < 0).sum()), "sd": sd, "n": len(d)}


def r18_tarefas(ctx):
    S = r18_sementes()
    tasks = []
    # W_tune por método×modo (plantado para ajuste principal; aberto reusa tau)
    for met in R18_METODOS_W:
        tasks.append(("W_tune", met, tuple(S["W_dev"][:R18_NDEV]), "plantado"))
    for cond in R18_CONDS_D:
        tasks.append(("D_tune", cond, tuple(S["D_dev"][:R18_NDEV])))
    for met in R18_METODOS_N:
        tasks.append(("N_tune", met, tuple(S["N_dev"][:R18_NDEV])))
    for met in R18_METODOS_C:
        tasks.append(("C_tune", met, tuple(S["C_dev"][:R18_NDEV])))
    for met in R18_MEGA_METODOS:
        tasks.append(("M_tune", met, tuple(R18_SEEDS_M)))
    for met in R18_METODOS_S:
        tasks.append(("S_tune", met, tuple(R18_SEEDS_S_DEV[:R18_NDEV])))
    for met in R18_METODOS_A:
        tasks.append(("A_tune", met, tuple(R18_SEEDS_A_DEV[:R18_NDEV])))
    return r18_job, tasks



# ======================================================================
# [R18] SISTEMAS DINÂMICOS NL×LINEAR×DIFUSO + GAN (PARTE S)
# ======================================================================
# -*- coding: utf-8 -*-
"""BLOCO 26f — [R18] SISTEMAS DINÂMICOS: não-linear (Lorenz/Chen) × linear × panorâmico-difuso,
acoplados a GAN modular com learning rates NÃO UNIFORMES por camada. Ablação + Holm.
Expectativa: pode ajudar estabilidade (↓osc) sem necessariamente ↑qualidade (−JSD);
reportar honestamente. Sem Hertz/frequências cerebrais; sem alegar consciência.
"""

R18_HIPOT_S = ("S1", "S2", "S3", "S4", "S5")
R18_PAR_S = {
    # Δ = (−JSD)_A − (−JSD)_B  OU  (−osc)_A − (−osc)_B conforme desfecho
    "S1": ("nl_acoplado", "linear_acoplado"),       # não-linear vs linear (qualidade −JSD)
    "S2": ("nl_acoplado", "difuso_acoplado"),        # não-linear vs panorâmico-difuso
    "S3": ("nl_acoplado", "gan_so"),                 # acoplamento ajuda vs GAN só?
    "S4": ("nl_lr_nao_unif", "nl_lr_unif"),          # LR não-uniforme vs uniforme (sob NL)
    "S5": ("nl_acoplado", "nl_embarcado"),           # estrutura NL vs ruído embaralhado (específico?)
}
R18_METODOS_S = (
    "gan_so", "linear_acoplado", "difuso_acoplado", "nl_acoplado",
    "nl_lr_unif", "nl_lr_nao_unif", "nl_embarcado",
)
R18_SEEDS_S_DEV = list(range(21100, 21116))
R18_SEEDS_S_TEST = list(range(21200, 21240))
R18_PASSOS_S = 350
R18_NSORT_S = 4


def r18_lorenz_step(state, dt=0.01, sigma=10.0, rho=28.0, beta=8.0/3.0):
    x, y, z = state
    dx = sigma * (y - x)
    dy = x * (rho - z) - y
    dz = x * y - beta * z
    return np.array([x + dt * dx, y + dt * dy, z + dt * dz], float)


def r18_chen_step(state, dt=0.01, a=35.0, b=3.0, c=28.0):
    """Atrator de Chen (não-linear, contraposto ao Lorenz)."""
    x, y, z = state
    dx = a * (y - x)
    dy = (c - a) * x - x * z + c * y
    dz = x * y - b * z
    return np.array([x + dt * dx, y + dt * dy, z + dt * dz], float)


def r18_linear_step(state, dt=0.01, A=None):
    """Fluxo linear ẋ = A x (estável espiral se autovalores com Re<0)."""
    if A is None:
        A = np.array([[-0.5, -1.0, 0.0], [1.0, -0.5, 0.0], [0.0, 0.0, -0.3]], float)
    return state + dt * (A @ state)


def r18_difuso_step(state, dt=0.01, centros=None, pesos=None):
    """Campo panorâmico-linear DIFUSO: combinação convexa local de fluxos lineares
    em torno de centros (pesos softmáx pela distância)."""
    if centros is None:
        centros = np.array([[1., 0., 0.], [-1., 0., 0.], [0., 1., 0.]], float)
    if pesos is None:
        # matrizes A_k locais
        pesos = [
            np.array([[-0.4, -0.8, 0.], [0.8, -0.4, 0.], [0., 0., -0.2]], float),
            np.array([[-0.3, 0.6, 0.], [-0.6, -0.3, 0.], [0., 0., -0.25]], float),
            np.array([[-0.5, 0., 0.4], [0., -0.5, 0.], [-0.4, 0., -0.5]], float),
        ]
    d = np.linalg.norm(centros - state[None, :], axis=1)
    w = np.exp(-2.0 * d); w = w / (w.sum() + 1e-12)
    v = np.zeros(3, float)
    for wi, Ai in zip(w, pesos):
        v += wi * (Ai @ state)
    return state + dt * v


def r18_trajeto(sistema: str, n: int, seed: int, embaralhar: bool = False):
    """Gera trajetória (n,3). sistema ∈ {lorenz, chen, linear, difuso}."""
    rng = r18_rng(seed, r18_crc("dyn|" + sistema), 41)
    s = rng.normal(0, 1, size=3)
    if sistema in ("lorenz", "chen"):
        s = np.array([0.1, 0.0, 0.0]) + 0.01 * rng.normal(0, 1, 3)
    traj = np.zeros((n, 3), float)
    for t in range(n):
        if sistema == "lorenz":
            s = r18_lorenz_step(s)
        elif sistema == "chen":
            s = r18_chen_step(s)
        elif sistema == "linear":
            s = r18_linear_step(s)
        elif sistema == "difuso":
            s = r18_difuso_step(s)
        else:
            s = r18_lorenz_step(s)
        if not np.isfinite(s).all() or float(np.abs(s).max())>1e3:
            s = rng.normal(0, 1, size=3)
        traj[t] = s
    if embaralhar:
        traj = rng.permutation(traj)
    # normalizar por coluna
    traj = (traj - traj.mean(0)) / (traj.std(0) + 1e-9)
    return traj


def r18_modula_lr(base_lr: float, traj_t, camada: str, nao_unif: bool):
    """LR não uniforme por camada a partir do estado dinâmico."""
    if not nao_unif:
        return base_lr
    # energia / amplitude local
    amp = float(np.linalg.norm(traj_t))
    if camada == "enc":
        return base_lr * (0.5 + 0.5 * np.tanh(amp))
    if camada == "head":
        return base_lr * (0.5 + 0.5 * np.tanh(2.0 - amp))
    return base_lr


def r18_treinar_gan_dyn(metodo: str, seed: int, hp: dict, passos: int = R18_PASSOS_S) -> dict:
    """GAN modular 5 modos×4D (reusa r18_*) com acoplamento dinâmico → LR/máscara."""
    rng = r18_rng(seed, r18_crc("S|" + metodo), 19)
    X, centros = r18_dados_modos(180, seed)
    hid, dim = 10, 4
    G = (rng.normal(0, 0.35, (dim, hid)), np.zeros(hid), rng.normal(0, 0.35, (hid, dim)), np.zeros(dim))
    D = (rng.normal(0, 0.35, (dim, hid)), np.zeros(hid), rng.normal(0, 0.35, (hid, 1)), np.zeros(1))
    lr_g0 = float(hp.get("lr_g", 0.05))
    lr_d0 = float(hp.get("lr_d", 0.05))
    nao_unif = "nao_unif" in metodo or metodo in ("nl_acoplado", "linear_acoplado", "difuso_acoplado")
    if metodo == "nl_lr_unif":
        nao_unif = False
    if metodo == "nl_lr_nao_unif":
        nao_unif = True
    # escolher sistema
    if metodo in ("nl_acoplado", "nl_lr_unif", "nl_lr_nao_unif", "nl_embarcado"):
        # sobreposição Lorenz+Chen (média)
        traj_l = r18_trajeto("lorenz", passos, seed, embaralhar=("embarcado" in metodo))
        traj_c = r18_trajeto("chen", passos, seed + 1, embaralhar=("embarcado" in metodo))
        traj = 0.5 * traj_l + 0.5 * traj_c
    elif metodo == "linear_acoplado":
        traj = r18_trajeto("linear", passos, seed)
    elif metodo == "difuso_acoplado":
        traj = r18_trajeto("difuso", passos, seed)
    else:
        traj = np.zeros((passos, 3), float)  # gan_so: sem dinâmica
    hist = []
    d_acc_ema = 0.5
    for t in range(passos):
        idx = rng.integers(0, len(X), size=32)
        Xb = X[idx]
        Z = rng.normal(0, 1, size=(32, dim))
        st = traj[t] if t < len(traj) else np.zeros(3)
        # máscara modular: usa sinal dinâmico se acoplado
        if metodo == "gan_so":
            mg, md = (1, 1), (1, 1)
            lr_g, lr_d = lr_g0, lr_d0
        else:
            amp = float(np.linalg.norm(st))
            # contraposto: se amp alta → atualiza enc; se baixa → heads
            if amp > 1.0:
                mg, md = (1, 0), (1, 0)
            else:
                mg, md = (0, 1), (0, 1)
            if d_acc_ema > 0.9:
                md = (0, 0)
            lr_g = r18_modula_lr(lr_g0, st, "enc" if mg[0] else "head", nao_unif)
            lr_d = r18_modula_lr(lr_d0, st, "enc" if md[0] else "head", nao_unif)
        G, D, loss_d, pf = r17_gan_step(G, D, Z, Xb, lr_g, lr_d, mg, md)
        hist.append(loss_d)
        real_logit, _ = r17_mlp_forward(Xb, *D)
        pr = 1 / (1 + np.exp(-np.clip(real_logit.ravel(), -20, 20)))
        d_acc = 0.5 * (float((pr > 0.5).mean()) + float(pf < 0.5))
        d_acc_ema = 0.9 * d_acc_ema + 0.1 * d_acc
    Zq = rng.normal(0, 1, size=(120, dim))
    fq, _ = r17_mlp_forward(Zq, *G)
    jsd = r18_jsd_modos(fq, centros)
    hh = np.asarray(hist[-50:] if len(hist)>=50 else hist, float)
    hh = hh[np.isfinite(hh)]
    osc = float(np.std(hh)) if len(hh) else 0.0
    nj = -float(jsd) if np.isfinite(jsd) else -1.0
    return {"neg_jsd": nj, "jsd": float(jsd) if np.isfinite(jsd) else 1.0, "neg_osc": -osc, "osc": osc}


def r18_sorteio_hp_s(i: int) -> dict:
    rng = r18_rng(r18_crc("S"), 18, i)
    return {"lr_g": float(rng.choice([0.02, 0.05, 0.08])),
            "lr_d": float(rng.choice([0.02, 0.05, 0.08]))}


def r18_ajustar_s(metodo: str, seeds_dev, n_sort: int = R18_NSORT_S) -> dict:
    best, bh = -1e18, r18_sorteio_hp_s(0)
    for i in range(n_sort):
        hp = r18_sorteio_hp_s(i)
        sc = float(np.mean([r18_treinar_gan_dyn(metodo, s, hp, passos=100)["neg_jsd"] for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


def r18_eval_s(metodo: str, seed: int, hp: dict, passos: int = None) -> dict:
    return r18_treinar_gan_dyn(metodo, seed, hp, passos=passos or R18_PASSOS_S)

def bloco26(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 26 — [R18] CANAL palavra↔número PLANTADO + DELÍRIO→ESCRUTÍNIO 2-estágios "
               "+ GAN modular DURA (5 modos×4D) + CL→RL transferência "
               "(18 confirmatórias, 40 sementes novas, Holm; pré-registro prereg_r18.txt)")
    desloc = r18_desloc()
    if desloc:
        rep.log(f"[R18_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r18_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R18_NTEST
    n_prop = 12 if rapido else R18_NPROP_D
    n_inv = 20 if rapido else R18_NINV_W
    passos_n = 150 if rapido else R18_PASSOS_N

    # ---- pré-registro ----
    ok_p = hashlib.sha256(PREREG_R18_CORPO.encode("utf-8")).hexdigest() == PREREG_R18_CORPO_SHA256
    rep.log(f"Pré-registro R18: sha256={PREREG_R18_CORPO_SHA256[:16]}… "
            f"{'(CONFERE com versoes/prereg_r18.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R18_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R18_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R18_CORPO_SHA256
        rep.log(f"Adendo 1 R18: sha256={ADENDO1_R18_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!! NÃO CONFERE)'}")

    tuned = None
    if ctx.bg is not None:
        try:
            tuned = ctx.bg.obter("r18a")
        except Exception:
            tuned = None
    ti = 0

    # ---- W ----
    rep.sub("W — CANAL palavra↔número PLANTADO / ABERTO: ajuste (DEV) e avaliação")
    hp_W = {}
    for met in R18_METODOS_W:
        if tuned is not None and ti < len(tuned):
            hp_W[met] = tuned[ti]
        else:
            nsort = 1 if rapido or met in ("iid_letras", "markov2") else R18_NSORT
            hp_W[met] = r18_ajustar_w(met, S["W_dev"][:R18_NDEV], modo="plantado", n_sort=nsort)
        ti += 1
        rep.log(f"  ajuste {met}: {hp_W[met]}")
    # scores por (metodo, modo)
    scores_W = {(m, modo): [] for m in R18_METODOS_W for modo in ("plantado", "aberto")}
    tasks = []
    for modo in ("plantado", "aberto"):
        for met in R18_METODOS_W:
            for s in S["W_test"][:n_test]:
                tasks.append(("W", met, s, hp_W[met], modo))
    outs = mapa_paralelo(r18_job, tasks, jobs)
    k = 0
    for modo in ("plantado", "aberto"):
        for met in R18_METODOS_W:
            for _ in S["W_test"][:n_test]:
                scores_W[(met, modo)].append(outs[k]); k += 1
            rep.log(f"  {met}/{modo}: média={float(np.mean(scores_W[(met, modo)])):.3f}")
    P_W = {}
    for hname, (a, b, modo) in R18_PAR_W.items():
        d = np.asarray(scores_W[(a, modo)]) - np.asarray(scores_W[(b, modo)])
        P_W[hname] = r18_pareado_pack(d, seed=r18_crc(hname))
        rep.log(f"  {hname} ({a}−{b}|{modo}): Δ={P_W[hname]['media']:+.3f} p={P_W[hname]['p']:.4f}")

    # ---- D ----
    rep.sub("D — DELÍRIO→ESCRUTÍNIO 2-estágios: ajuste (DEV) e avaliação")
    hp_D = {}
    for cond in R18_CONDS_D:
        if tuned is not None and ti < len(tuned):
            hp_D[cond] = tuned[ti]
        else:
            nsort = 1 if rapido or cond == "oraculo" else R18_NSORT
            hp_D[cond] = r18_ajustar_d(cond, S["D_dev"][:R18_NDEV], n_sort=nsort)
        ti += 1
        rep.log(f"  ajuste {cond}: {hp_D[cond]}")
    # ROC exploratória no DEV para delirio_2est
    if not rapido:
        roc, best_roc = r18_roc_dev("delirio_2est", S["D_dev"][:R18_NDEV], hp_D["delirio_2est"])
        rep.log(f"  ROC-DEV delirio_2est (Youden máx): τ={best_roc['tau_laudo']:.2f} "
                f"TPR={best_roc['TPR']:.2f} FPR={best_roc['FPR']:.2f} Youden={best_roc['Youden']:+.2f}")
    scores_D = {c: [] for c in R18_CONDS_D}
    detail_D = {c: [] for c in R18_CONDS_D}
    tasks = [("D", c, s, hp_D[c]) for c in R18_CONDS_D for s in S["D_test"][:n_test]]
    # r18_job retorna só Youden; para TPR/FPR reavaliamos em série curta no fim se preciso
    outs = mapa_paralelo(r18_job, tasks, jobs)
    k = 0
    for c in R18_CONDS_D:
        for s in S["D_test"][:n_test]:
            scores_D[c].append(outs[k]); k += 1
        # detalhe TPR/FPR (amostra — 8 sementes para não explodir CPU)
        for s in S["D_test"][:min(8, n_test)]:
            detail_D[c].append(r18_laco_delirio(c, s, hp_D[c], nprop=n_prop))
        tpr_m = float(np.mean([d["TPR"] for d in detail_D[c]])) if detail_D[c] else float("nan")
        fpr_m = float(np.mean([d["FPR"] for d in detail_D[c]])) if detail_D[c] else float("nan")
        rep.log(f"  {c}: Youden={float(np.mean(scores_D[c])):+.3f} TPR≈{tpr_m:.2f} FPR≈{fpr_m:.2f}")
    P_D = {}
    for hname, (a, b) in R18_PAR_D.items():
        if b == "ZERO":
            d = np.asarray(scores_D[a], float)
        else:
            d = np.asarray(scores_D[a]) - np.asarray(scores_D[b])
        P_D[hname] = r18_pareado_pack(d, seed=r18_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_D[hname]['media']:+.3f} p={P_D[hname]['p']:.4f}")

    # ---- N ----
    rep.sub("N — GAN modular DURA (5 modos×4D) + controladores: ajuste e avaliação")
    hp_N = {}
    for met in R18_METODOS_N:
        if tuned is not None and ti < len(tuned):
            hp_N[met] = tuned[ti]
        else:
            nsort = 1 if rapido else R18_NSORT
            hp_N[met] = r18_ajustar_n(met, S["N_dev"][:R18_NDEV], n_sort=nsort)
        ti += 1
        rep.log(f"  ajuste {met}: {hp_N[met]}")
    # escolher BEST_CTRL no DEV
    ctrls = ("ctrl_incerteza", "ctrl_perda", "ctrl_prolog")
    dev_scores = {}
    for met in ctrls:
        dev_scores[met] = float(np.mean([
            r18_eval_n(met, s, hp_N[met], passos=120 if rapido else 200) for s in S["N_dev"][:R18_NDEV]
        ]))
    best_ctrl = max(ctrls, key=lambda m: dev_scores[m])
    rep.log(f"  BEST_CTRL (DEV): {best_ctrl} scores={{{', '.join(f'{k}:{v:+.3f}' for k,v in dev_scores.items())}}}")
    scores_N = {m: [] for m in R18_METODOS_N}
    tasks = [("N", m, s, hp_N[m]) for m in R18_METODOS_N for s in S["N_test"][:n_test]]
    # monkey: r18_job N uses default passos; for rapido override via partial eval
    def _job_n(t):
        _, metodo, seed, hp = t
        return r18_eval_n(metodo, seed, hp, passos=passos_n)
    outs = mapa_paralelo(_job_n, tasks, jobs)
    k = 0
    for m in R18_METODOS_N:
        for _ in S["N_test"][:n_test]:
            scores_N[m].append(outs[k]); k += 1
        rep.log(f"  {m}: −JSD médio={float(np.mean(scores_N[m])):+.4f}")
    # exploratório modular_aleat − monolito
    d_mod = np.asarray(scores_N["modular_aleat"]) - np.asarray(scores_N["monolito"])
    P_mod_exp = r18_pareado_pack(d_mod, seed=r18_crc("Nmod"))
    rep.log(f"  [exploratório] modular_aleat−monolito: Δ={P_mod_exp['media']:+.4f} p={P_mod_exp['p']:.4f}")
    P_N = {}
    for hname, (a, b) in R18_PAR_N.items():
        aa = best_ctrl if a == "BEST_CTRL" else a
        d = np.asarray(scores_N[aa]) - np.asarray(scores_N[b])
        P_N[hname] = r18_pareado_pack(d, seed=r18_crc(hname))
        rot = f"{aa}−{b}" if a == "BEST_CTRL" else f"{a}−{b}"
        rep.log(f"  {hname} ({rot}): Δ={P_N[hname]['media']:+.4f} p={P_N[hname]['p']:.4f}")

    # ---- C ----
    rep.sub("C — CL→RL transferência Raphael→jogo de palavras: ajuste e avaliação")
    hp_C = {}
    for met in R18_METODOS_C:
        if tuned is not None and ti < len(tuned):
            hp_C[met] = tuned[ti]
        else:
            nsort = 1 if rapido else R18_NSORT
            hp_C[met] = r18_ajustar_c(met, S["C_dev"][:R18_NDEV], n_sort=nsort)
        ti += 1
        rep.log(f"  ajuste {met}: {hp_C[met]}")
    scores_C = {m: [] for m in R18_METODOS_C}
    tasks = [("C", m, s, hp_C[m]) for m in R18_METODOS_C for s in S["C_test"][:n_test]]
    outs = mapa_paralelo(r18_job, tasks, jobs)
    k = 0
    for m in R18_METODOS_C:
        for _ in S["C_test"][:n_test]:
            scores_C[m].append(outs[k]); k += 1
        rep.log(f"  {m}: acc={float(np.mean(scores_C[m])):.3f}")
    P_C = {}
    for hname, (a, b) in R18_PAR_C.items():
        d = np.asarray(scores_C[a]) - np.asarray(scores_C[b])
        P_C[hname] = r18_pareado_pack(d, seed=r18_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_C[hname]['media']:+.3f} p={P_C[hname]['p']:.4f}")

    # ---- M Mega-Sena ----
    mega = r18_mega_secao(ctx, rep, jobs, rapido, None)
    # ---- S Dinâmica ----
    dyn = r18_dyn_secao(ctx, rep, jobs, rapido, None)
    # ---- A Anormais ----
    anorm = r18_anormal_secao(ctx, rep, jobs, rapido, None)

    # ---- Holm local + status ----

    def _holm_pack(Pdict, nomes):
        ps = [Pdict[h]["p"] for h in nomes]
        ph = holm(ps)
        st = {}
        for i, h in enumerate(nomes):
            Pdict[h]["p_holm"] = ph[i]
            st[h] = r18_status(Pdict[h]["media"], ph[i])
            rep.log(f"  status {h}: {st[h]} (p_holm={ph[i]:.4f})")
        return st
    st = {}
    st.update(_holm_pack(P_W, R18_HIPOT_W))
    st.update(_holm_pack(P_D, R18_HIPOT_D))
    st.update(_holm_pack(P_N, R18_HIPOT_N))
    st.update(_holm_pack(P_C, R18_HIPOT_C))

    # Holm Mega + Dyn
    st.update(mega["st"])
    P_M = mega["P"]
    st.update(dyn["st"])
    P_S = dyn["P"]
    st.update(anorm["st"])
    P_A = anorm["P"]

    P_all = {}
    P_all.update(P_W); P_all.update(P_D); P_all.update(P_N); P_all.update(P_C); P_all.update(P_M); P_all.update(P_S); P_all.update(P_A)
    # formato compatível com coletar_p_conf: val[3] = p
    P_tup = {k: (v["media"], v["lo"], v["hi"], v["p"], v.get("p_holm", v["p"]), v["mde"]) for k, v in P_all.items()}
    n_conf = sum(1 for v in st.values() if v == "confirmada")
    n_ref = sum(1 for v in st.values() if v == "refutada")
    n_nula = sum(1 for v in st.values() if v == "nula")
    n_tot = len(st)
    rep.log(f"RESUMO R18: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {n_tot} (18 corpo + 6 Mega + 5 Dyn + 4 Anormais Adendo1)")

    ctx.res["r18"] = {
        "P": P_tup, "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula,
        "best_ctrl": best_ctrl,
        "scores_W": {f"{m}/{modo}": float(np.mean(scores_W[(m, modo)])) for m in R18_METODOS_W for modo in ("plantado", "aberto")},
        "scores_D": {c: float(np.mean(scores_D[c])) for c in R18_CONDS_D},
        "scores_N": {m: float(np.mean(scores_N[m])) for m in R18_METODOS_N},
        "scores_C": {m: float(np.mean(scores_C[m])) for m in R18_METODOS_C},
        "detail_D": {c: {"TPR": float(np.mean([d["TPR"] for d in detail_D[c]])),
                         "FPR": float(np.mean([d["FPR"] for d in detail_D[c]]))} for c in R18_CONDS_D if detail_D[c]},
        "P_mod_exp": P_mod_exp,
        "hp_W": hp_W, "hp_D": hp_D, "hp_N": hp_N, "hp_C": hp_C,
        "desloc": desloc,
        "mega": mega,
        "dyn": dyn,
        "anorm": anorm,
        "chaves": list(R18_HIPOT) + list(R18_HIPOT_M) + list(R18_HIPOT_S) + list(R18_HIPOT_A),
    }
    return ctx.res["r18"]


def registro_r18_log(ctx: Contexto) -> list:
    """Linhas de log (strings) do BLOCO 26."""
    r = ctx.res.get("r18")
    if not r:
        return []
    chaves = r.get("chaves") or list(R18_HIPOT)
    L = [f"REGISTRO R18 (BLOCO 26) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de {len(chaves)}"]
    for h in chaves:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append(f"  BEST_CTRL={r.get('best_ctrl')}")
    return L


