    rep.log("  ρ por contraste: " + ", ".join(f"{k} {rho[k]:.2f}" for k in R15_HIPOT) + f". Fator de James–Stein (descritivo) = {Bjs:.2f}; Δ encolhidos (pp): " + ", ".join(f"{k} {_r15_pf(e)}" for k, e in zip(R15_HIPOT, eb)) + ".")
    n_real = sum(v == "REAL" for v in ver.values())
    n_infl = sum(v.startswith("REAL, mas") for v in ver.values())
    n_nao = sum(v.startswith("NÃO") for v in ver.values())
    n_inv = sum(v == "INVERTE" for v in ver.values())
    rep.sub("VEREDITO POR EFEITO (regra mecânica: 'REAL' = mesmo sinal e Holm < 0,05; 'inflado' se além disso ρ < 0,75)")
    VE = {}
