def registro_r15(ctx: Contexto) -> list:
    """Linhas do registro da R15: 9 CONF (A1–A3, B2–B20, C1, D1; BLOCO 23), descritivas e a contabilidade global."""
    r = ctx.res
    out = []
    pp = r.get("r15_rep")
    if pp:
        for k in R15_HIPOT:
            m_, lo, hi, pv, pa_, mde, qb = pp["P"][k]
            hip = f"replicação larga (N={pp['N'] if k != 'C1' else pp['n4']}, ajuste cruzado em 4 dobras): {R15_DESC[k]}; original {100 * R15_ORIG[k][0]:+.2f} pp"
            out.append(("R15", f"R15-{k}", "CONF", hip, f"Δ={100 * m_:+.2f} pp IC[{100 * lo:+.2f},{100 * hi:+.2f}] p={pv:.4f} p Holm(9)={pa_:.3f} MDE={100 * mde:.2f} pp ρ={pp['rho'][k]:.2f}", pp["st"][k]))
        cal = pp["cal"]
        out.append(("R15", "R15-RV", "DESC", "REPLICAÇÃO LARGA dos 5 efeitos (R1–R14): classificação e encolhimento",
                    f"{pp['n_real']} REAIS (ρ ≥ 0,75), {pp['n_infl']} reais mas inflados, {pp['n_nao']} não confirmados, {pp['n_inv']} invertidos de 9 | inclinação de calibração {cal['slope']:.2f} [{cal['lo']:.2f},{cal['hi']:.2f}] | ρ mediano {cal['rho_med']:.2f}", "descritiva"))
    out.append(("R15", "R15-L", "DESC", "ARQUIVO ENXUTO (asi_metacognitivo_enxuto.py): só componentes com evidência sobrevivente; --demo < 60 s; autoteste próprio conferido pelo autoteste principal",
                f"{R15_ENXUTO_INFO['linhas']} linhas; sha256 {R15_ENXUTO_INFO['sha'][:12]}…", "descritiva"))
    dz = r.get("r13_dorm")
    if dz and "BLOCO 20 (R13: autoconfiguração e meta-teste do guia)" in dz:
        out.append(("R15", "R15-D", "DESC", "BLOCO 20 (R13) segue DORMENTE nesta execução (replicação congelada, sha256 verificado, do código R13 inalterado)", dz["BLOCO 20 (R13: autoconfiguração e meta-teste do guia)"], "descritiva"))
    fw = r.get("r5_fwer")
    if fw:
        out.append(("R15", "R15-W1", "DESC", f"FWER global (Holm/BH) sobre {fw['m']} confirmatórias (nesta execução, família R2–R15; na R14 eram 389; as 9 novas da R15 entram)", f"Holm global confirma {fw['holm']}; BH confirma {fw['bh']}", "descritiva"))
    return out


