def leigos_linhas_r16(ctx: Contexto) -> list:
    """[R16] RELATÓRIO PARA LEIGOS (≤ 40 linhas)."""
    import textwrap
    base = leigos_linhas_r15(ctx)
    r = ctx.res.get("r16")
    extra = []
    if r:
        extra.append(f"RODADA 16: testei um jogo novo (Raphael: tabuleiro + cartas + dicionário), inventar palavras com filtro, um laço que 'delira' propostas de componentes e as escrutina, e um debate entre agentes-escore (sem alegar consciência). "
                     f"Resultado: {r['n_conf']} confirmadas, {r['n_ref']} refutadas, {r['n_nula']} nulas de 16 testes. A teoria do delírio como caminho à ASI continua sem demonstração.")
    extra.append("RECUSAS DESTA RODADA: não criei jailbreaks/backdoors nem coloquei chave de API no código; não rodei '1 milhão' literal de testes (useei proxies honestos).")
    # rebuild: keep header, insert extra before LIMITES if present
    out = []
    for line in base:
        if line.startswith("LIMITES:") or line.startswith("LIMITES "):
            for p in extra:
                out.extend(textwrap.wrap(p, width=170))
            out.append(line)
        else:
            out.append(line)
    if extra and not any(l.startswith("LIMITES") for l in base):
        for p in extra:
            out.extend(textwrap.wrap(p, width=170))
    # fix header rodadas
    out2 = []
    for l in out:
        if "RELATÓRIO PARA LEIGOS (rodadas 1–" in l:
            out2.append(l.replace("1–15", "1–16").replace(f"1–{int(VERSAO[1:])-1}", f"1–{VERSAO[1:]}"))
        else:
            out2.append(l)
    return out2

