def _t15_registro_sintetico() -> bool:
    import types
    P = {k: (0.01, -0.01, 0.03, 0.03, 0.2, 0.02, 0.2) for k in R15_HIPOT}
    st = {k: "nula" for k in R15_HIPOT}
    pp = {"N": 120, "n4": 120, "P": P, "st": st, "CL": {k: "NÃO REPLICA" for k in R15_HIPOT}, "rho": {k: 0.1 for k in R15_HIPOT}, "ver": {k: "NÃO confirmado (replicação nula/inconclusiva)" for k in R15_HIPOT}, "n_real": 0, "n_infl": 0, "n_nao": 9, "n_inv": 0,
          "cal": {"slope": 0.1, "lo": 0.0, "hi": 0.2, "rho_med": 0.1, "rho_mean": 0.1}, "otim_med": 0.02, "n_faixa": 3}
    ctx = types.SimpleNamespace(res={"r15_rep": pp, "r13_dorm": {"BLOCO 20 (R13: autoconfiguração e meta-teste do guia)": "dormente"}, "r5_fwer": {"m": 398, "holm": 1, "bh": 2}})
    rows = registro_r15(ctx)
    conf = [x for x in rows if x[2] == "CONF"]
    ids = [x[1] for x in rows]
    sl = sumario_r15_linhas(ctx)
    lg = leigos_linhas(ctx)
    return (len(conf) == 9 and len(set(ids)) == len(ids) and all(len(x) == 6 for x in rows) and all(x[1].startswith("R15-") for x in rows) and len(sl) == 2 and all(isinstance(l, str) for l in sl)
            and 8 <= len(lg) <= 40 and all(isinstance(l, str) for l in lg))


def _autoteste_r15(t, lk, ant):
    """[R15] Invariantes do BLOCO 23. `t(nome, cond)` registra; `ant` = sementes de rodadas anteriores (até a R10)."""
    import inspect as _insp
    import subprocess as _sp
    t("R15: pré-registro (corpo) confere com o sha256 embutido" + ("; adendo 1 idem" if ADENDO1_R15_CORPO_SHA256 else "") + ("; adendo 2 idem" if ADENDO2_R15_CORPO_SHA256 else ""),
      sha_ok(PREREG_R15_CORPO, PREREG_R15_CORPO_SHA256) and (not ADENDO1_R15_CORPO_SHA256 or sha_ok(ADENDO1_R15_CORPO, ADENDO1_R15_CORPO_SHA256)) and (not ADENDO2_R15_CORPO_SHA256 or sha_ok(ADENDO2_R15_CORPO, ADENDO2_R15_CORPO_SHA256)))
    try:
        _dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "versoes")
        _ft = open(os.path.join(_dir, "prereg_r15.txt"), encoding="utf-8").read()
        _ok_f = PREREG_R15_CORPO in _ft and PREREG_R15_CORPO_SHA256 in _ft
        for _n, _c, _h in ((1, ADENDO1_R15_CORPO, ADENDO1_R15_CORPO_SHA256), (2, ADENDO2_R15_CORPO, ADENDO2_R15_CORPO_SHA256)):
            if _h:
                _fa = open(os.path.join(_dir, f"prereg_r15_adendo{_n}.txt"), encoding="utf-8").read()
                _ok_f = _ok_f and _c in _fa and _h in _fa
        t("R15: versoes/prereg_r15.txt (e os adendos) contêm o corpo embutido e o seu sha256 no rodapé", _ok_f)
    except OSError:
        t("R15: versoes/prereg_r15.txt (e os adendos) contêm o corpo embutido e o seu sha256 no rodapé", True)
    t("R15: versão = R15 (ou posterior)", VERSAO in ("R15", "R16", "R17", "R18", "R19", "R20", "R21", "R22", "R23", "R24", "R25", "R26", "R27", "R28", "R29", "R30", "R31", "R32", "R33", "R34", "R35", "R36", "R37"))
    _s = [set(range(R15_SEM_ESP_DEV, R15_SEM_ESP_DEV + R15_K * R15_ESP_S)), set(range(R15_SEM_ESP_C, R15_SEM_ESP_C + R15_N)), set(range(R15_SEM_RAST_DEV, R15_SEM_RAST_DEV + R15_K * R15_RAST_S)), set(range(R15_SEM_RAST_C, R15_SEM_RAST_C + R15_N)),
          set(range(R15_SEM_TOY_DEV, R15_SEM_TOY_DEV + R15_K * R15_TOY_S)), set(range(R15_SEM_TOY_C, R15_SEM_TOY_C + R15_N)), set(range(R15_SEM_E4_C, R15_SEM_E4_C + R15_N))]
    _u = set().union(*_s)
    _r14 = set(range(R14_SEM_DEV, R14_SEM_DEV + R14_NDEV)) | set(range(R14_SEM_C, R14_SEM_C + R14_NC)) | set(range(R14_SEM_RDEV, R14_SEM_RDEV + R14_RNDEV)) | set(range(R14_SEM_RC, R14_SEM_RC + R14_NC))
    _r13 = set(range(R13_SEM_DEV, R13_SEM_DEV + sum(e[1] for e in R13_ESTAGIOS))) | set(range(R13_SEM_C, R13_SEM_C + R13_NC)) | set(range(R13_SEM_G, R13_SEM_G + R13_NG))
    _r11 = set(range(R11_SEM_DEV, R11_SEM_DEV + 5)) | set(range(R11_SEM_C, R11_SEM_C + R11_NC)) | set(range(R11_SEM_F, R11_SEM_F + R11_NF))
    _r12 = set(range(R12_SEM_DEV, R12_SEM_DEV + 5)) | set(range(R12_SEM_C, R12_SEM_C + R12_NC))
    # 17000–17039 aparece em `ant` por ser o deslocamento de DEPURAÇÃO (+10000) do laudo da autopoiese da R9 (sementes 7000–7039 do gerador de tarefas do BLOCO 7, outro gerador; nunca registrado):
    # as sementes do E4 (16950–17069) as contêm nominalmente, mas montar_semente6 deriva RNG de 7000+s etc., sem relação com gerar_tarefa; declarado no Adendo 1 da R15.
    _ant = (ant - set(range(17000, 17040))) | _r11 | _r12 | _r13 | _r14 | {x + 10000 for x in _r11 | _r12 | _r13 | _r14}
