    t("R15: meta-análise — original = replicação ⇒ efeito fixo = Δ, Q = 0, τ² = 0; EP_fixo = EP/√2; Q = 50 e p < 1e-6 quando discordam em 10 EP; o fixo pondera por 1/EP² (aproxima o mais preciso); DL ≥ fixo em EP",
      abs(_mt["fe"] - 0.10) < 1e-12 and _mt["Q"] < 1e-12 and _mt["tau2"] == 0.0 and abs(_mt["se_fe"] - 0.02 / math.sqrt(2)) < 1e-12 and abs(_mt2["Q"] - 50.0) < 1e-9 and _mt2["pQ"] < 1e-6 and abs(_mt3["fe"] - 0.2 * (1 / 0.0001) / (1 / 0.0001 + 1 / 0.0016)) < 1e-12 and _mt2["se_re"] >= _mt2["se_fe"] - 1e-12)
    _cl = [r15_classificar(0.2, 0.25, 0.2, 0.3, 0.0001, 0.001), r15_classificar(0.2, 0.08, 0.04, 0.12, 0.0001, 0.001), r15_classificar(0.2, 0.05, 0.01, 0.09, 0.03, 0.2), r15_classificar(0.2, 0.01, -0.05, 0.07, 0.6, 1.0),
           r15_classificar(0.2, -0.1, -0.15, -0.05, 0.0001, 0.001), r15_classificar(-0.2, -0.25, -0.3, -0.2, 0.0001, 0.001), r15_classificar(-0.2, -0.05, -0.1, -0.01, 0.0001, 0.001)]
    t("R15: regra de classificação — mantido / encolheu / só na direção / não replica / inverte, nos dois sinais", _cl == ["REAL (tamanho mantido)", "REAL, ENCOLHEU", "SÓ NA DIREÇÃO", "NÃO REPLICA", "INVERTE", "REAL (tamanho mantido)", "REAL, ENCOLHEU"])
    _ca = r15_calibracao([0.2, 0.1, 0.3, 0.05], [0.1, 0.05, 0.15, 0.025], [0.1, 0.1, 0.1, 0.1])
    _eb, _B = r15_eb([3.0, 2.0, 1.0, 0.5, 4.0], [0.1] * 5)
    t("R15: inclinação de calibração = c exatamente quando Δ_rep = c·Δ_orig (IC contém c, ρ = c); James–Stein: fator em [0,1], preserva a média dos z e encolhe a dispersão", abs(_ca["slope"] - 0.5) < 1e-12 and abs(_ca["rho_med"] - 0.5) < 1e-12 and _ca["lo"] <= 0.5 + 1e-9 <= _ca["hi"] + 1e-9 and 0 <= _B <= 1
      and abs(np.mean(np.array(_eb) / 0.1) - 2.1) < 1e-9 and np.std(np.array(_eb)) <= np.std([0.3, 0.2, 0.1, 0.05, 0.4]) + 1e-12)
    # --- meia-fração de E4: o estimador coincide com o efeito principal do fatorial completo se não há interação de ordem 4 (D×L×A×M)
    import itertools as _it
    _rg = np.random.default_rng(15)
    _ok_f = True
    _termos = [tm for r_ in range(1, 4) for tm in _it.combinations(range(4), r_)]              # todos os termos de ordem 1 a 3 em (D, L, A, M); sem o de ordem 4
    for _ in range(5):
        _co = {tm: _rg.standard_normal() for tm in _termos}
        def _y(D, L, A, M):
            v = (D, L, A, M)
            return sum(c_ * np.prod([v[i_] for i_ in tm]) for tm, c_ in _co.items())
        _full = np.mean([_y(1, *x) - _y(0, *x) for x in _it.product((0, 1), repeat=3)])
        _frac = np.mean([_y(1, *x) - _y(0, *x) for x in R15_E4_FRACAO])
