# ----------------------------------------------------------------------
# [R10] Registro de hipóteses, sumário e "o que mudou" da R10
# ----------------------------------------------------------------------

R10_DESC_A = {"real": "só dados reais", "aug_ruido": "aumento por ruído (online)", "aug_mixup": "mixup (online)", "self_train": "auto-treino com pseudo-rótulos"}


def registro_r10(ctx: Contexto) -> list:
    """Linhas do registro da R10 (BLOCO 17), construídas dos resultados desta execução: 55 CONF (20 A + 5 D + 5 Fa + 5 Fb + 5 Fc + 5 G + 5 C + 5 B), exploratórias, descritivas e laudos."""
    r = ctx.res
    out = []
    nn = r.get("r10_gen")
    if nn:
        desc = {"D": "delir_gen − MELHOR PADRÃO por DEV", "Fa": "delir_gen − delir_sem_filtro (o FILTRO ajuda o delírio?)", "Fb": "so_filtro − jitter_estatico (o FILTRO ajuda um aumento manso?)",
                "Fc": "delir_gen − delir_placebo (importa QUAIS candidatos, além de quantos?)", "G": "delir_gen − so_filtro (o DELÍRIO acrescenta algo além do filtro?)",
                "C": "delir_gen − delir_emb (a ESTRUTURA CAÓTICA importa?)", "B": "delir_gen − delir_sem_saida (a SAÍDA FORÇADA importa?)"}
        for (k, t), (m_, lo, hi, pv, pa_, mde) in nn["P"].items():
            if k.startswith("A_"):
                hip = f"delírio generativo, tarefa {t}: delir_gen − {R10_DESC_A[k[2:]]} (acc de teste, {nn['n_c']} sementes novas 10200+, ajuste com orçamento igual)"
            elif k == "D":
                hip = f"delírio generativo, tarefa {t}: {desc[k]} = {nn['melhor_pad'][t]} ({nn['n_c']} sementes novas)"
            else:
                hip = f"delírio generativo, tarefa {t}: {desc[k]} ({nn['n_c']} sementes novas)"
            out.append(("R10", f"R10-{k}_{t}", "CONF", hip, f"Δ={100 * m_:+.2f} pp IC[{100 * lo:+.2f},{100 * hi:+.2f}] p Holm(55)={pa_:.3f} MDE={100 * mde:.2f} pp", nn["st"][(k, t)]))
        for nome, (re_, se_, i2) in nn["E2"].items():
            out.append(("R10", f"R10-E2_{nome}", "DESC", f"meta-análise DL do efeito {nome} entre as 5 tarefas", f"efeito aleatório {100 * re_:+.2f} pp (EP {100 * se_:.2f}), I²={100 * i2:.0f}%", "descritiva"))
        for t, Ls in nn["laudo"].items():
            for k, L in Ls.items():
                out.append(("R10", f"R10-{k}_{t}", "DESC", f"laudo de escrutínio {R10_NOME_L[k]} em {t} (sementes frescas 10300+; V1 efeito, V2 rótulos embaralhados, V3 ablação, V4 calibração)",
                            f"{L['veredito']}" + (f" — falhas: {', '.join(m.split(' ')[0] for m in L['motivos'])}" if L["motivos"] else ""), "descritiva"))
        out.append(("R10", "R10-R", "DESC", "regras de decisão pré-registradas: R1 (o delírio generativo ajuda) | R2 (o que importa é o filtro) | R3 (o caos estruturado importa)",
                    f"R1 {'ATENDIDA em ' + ', '.join(nn['r1']) if nn['r1'] else 'NÃO atendida'} | R2 {'ATENDIDA em ' + ', '.join(nn['r2']) if nn['r2'] else 'NÃO atendida'} | R3 {'ATENDIDA em ' + ', '.join(nn['r3']) if nn['r3'] else 'NÃO atendida'}", "descritiva"))
    fw = r.get("r5_fwer")
    if fw:
        out.append(("R10", "R10-W1", "DESC", f"FWER global (Holm/BH) sobre {fw['m']} confirmatórias de R2–R10 (as 55 novas da R10 entram)", f"Holm global confirma {fw['holm']} ({', '.join(fw['ids_holm']) if fw['ids_holm'] else 'nenhuma'}); BH confirma {fw['bh']}", "descritiva"))
    return out


def sumario_r10_linhas(ctx: Contexto) -> list:
    r = ctx.res
    nn = r.get("r10_gen")
    L = []
    if nn:
        st, T = nn["st"], R10_TAREFAS
        nA, nAn = len(nn["A_pos"]), len(nn["A_neg"])
        L.append("• Delírio GENERATIVO (R10: alucinar exemplos/rótulos candidatos de alta temperatura com estrutura caótica + saída forçada + filtro de escrutínio; MLPs numpy em 5 tarefas — as 4 da R9 e uma de POUCOS DADOS —, 11 métodos com o MESMO orçamento de ajuste, 40 sementes novas, Holm sobre 55): "
                 "contra o melhor aumento/auto-treino PADRÃO por DEV (D) → " + ", ".join(f"{t}: {st[('D', t)]}" for t in T) + f"; contra cada um dos 4 padrões (A, 20 testes): delírio melhor em {nA}, pior em {nAn}.")
        L.append("• O que importa, o FILTRO ou o DELÍRIO? Filtro vs alucinação sem filtro (Fa): " + ", ".join(f"{t}: {st[('Fa', t)]}" for t in T) + " | filtro sobre aumento manso (Fb): " + ", ".join(f"{t}: {st[('Fb', t)]}" for t in T) +
                 " | delírio acrescenta além do filtro-só (G): " + ", ".join(f"{t}: {st[('G', t)]}" for t in T) + " | caos estruturado × embaralhado (C): " + ", ".join(f"{t}: {st[('C', t)]}" for t in T) +
                 f". Regras pré-registradas: R1 'o delírio generativo ajuda' {'ATENDIDA em ' + ', '.join(nn['r1']) if nn['r1'] else 'NÃO atendida'}; R2 'o que importa é o filtro' {'ATENDIDA em ' + ', '.join(nn['r2']) if nn['r2'] else 'NÃO atendida'}; R3 'o caos importa' {'ATENDIDA em ' + ', '.join(nn['r3']) if nn['r3'] else 'NÃO atendida'}.")
        L.append("• LAUDO DE ESCRUTÍNIO do delírio generativo (R10; 4 variantes de ablação, sementes frescas): VALIDO em " + "; ".join(f"{k}: {len(nn['nval'][k])} de 5" + (f" ({', '.join(nn['nval'][k])})" if nn["nval"][k] else "") for k in R10_LAUDOS) + ".")
    return L


def secao_mudancas_r10(ctx: Contexto):
    rep, r = ctx.rep, ctx.res
    rep.titulo("O QUE MUDOU NA RODADA 10 (com os resultados desta execução)")
    nn, fw = r.get("r10_gen"), r.get("r5_fwer")
    rep.log(f"0. CABEÇALHOS QUE ACOMPANHAM A RODADA: o texto introdutório do relatório dizia 'TABELA DE TODAS AS HIPÓTESES R1–R8' mesmo na R9 (texto fixo esquecido). Agora o rótulo vem de `rotulo_rodadas()` (derivado de VERSAO = {VERSAO} → 'R1–{VERSAO}'), usado no texto introdutório, no título da tabela, no sumário executivo e na contabilidade de FWER, e o autoteste confere que nenhum desses textos cita outra rodada.")
    if nn:
        st = nn["st"]
        rep.log("1. DELÍRIO NOS DADOS/HIPÓTESES, NÃO NOS PESOS (BLOCO 17; pré-registro R10 com sha256 e carimbo 16:57 PT ANTES de qualquer código do módulo gerador; sem piloto; Adendo 1 depois do código; ATENÇÃO: duas execuções completas de integração com as sementes registradas ocorreram ANTES do Adendo — ver D1 — e a execução final não é a primeira vez que essas sementes foram vistas): um gerador 'delirante' alucina m = 2n exemplos candidatos "
                "(base real + temperatura alta × fluxo de Lorenz por embutimento de atrasos) com rótulo herdado ou alucinado (amostrado do professor), aplica SAÍDA FORÇADA (contração para a variedade dos dados + resfriamento) e um FILTRO DE ESCRUTÍNIO (suporte, consistência local, acordo do professor); a rede treina com reais + aceitos. "
                f"Comparado, com orçamento de ajuste IGUAL (8 sorteios × 3 sementes DEV) e {nn['n_c']} sementes novas, com: real-só, aumento por ruído, mixup, auto-treino com pseudo-rótulos, alucinação sem filtro, filtro com subconjunto aleatório (placebo), caos embaralhado, sem saída forçada, filtro-só sobre aumento manso e aumento manso sem filtro; "
                "5 tarefas (as 4 da R9 + T5 de poucos dados, n=20..100). RESULTADO: D = " + ", ".join(f"{t}: {st[('D', t)]}" for t in R10_TAREFAS) + " | Fa (filtro) = " + ", ".join(f"{t}: {st[('Fa', t)]}" for t in R10_TAREFAS) + " | Fb = " + ", ".join(f"{t}: {st[('Fb', t)]}" for t in R10_TAREFAS) +
                " | Fc (placebo) = " + ", ".join(f"{t}: {st[('Fc', t)]}" for t in R10_TAREFAS) + " | G (delírio além do filtro) = " + ", ".join(f"{t}: {st[('G', t)]}" for t in R10_TAREFAS) + " | C (caos) = " + ", ".join(f"{t}: {st[('C', t)]}" for t in R10_TAREFAS) +
                " | B (saída) = " + ", ".join(f"{t}: {st[('B', t)]}" for t in R10_TAREFAS) + ". Acurácia média (%) delir_gen / melhor padrão por DEV / so_filtro / real: " +
                "; ".join(f"{t}: {100 * nn['acc'][('delir_gen', t)]:.1f} / {100 * nn['acc'][(nn['melhor_pad'][t], t)]:.1f} ({nn['melhor_pad'][t]}) / {100 * nn['acc'][('so_filtro', t)]:.1f} / {100 * nn['acc'][('real', t)]:.1f}" for t in R10_TAREFAS) + ".")
        rep.log("   LEITURA: R1 'o delírio generativo ajuda' " + ("ATENDIDA em " + ", ".join(nn["r1"]) + " (D confirmada, laudo L1 valido, G não negativa), com as ressalvas dos limites" if nn["r1"] else "NÃO atendida") + "; R2 'o que importa é o filtro, não o delírio' " +
                ("ATENDIDA em " + ", ".join(nn["r2"]) if nn["r2"] else "NÃO atendida") + "; R3 'o caos estruturado importa' " + ("ATENDIDA em " + ", ".join(nn["r3"]) if nn["r3"] else "NÃO atendida") +
                ". Veja o bloco 'LEITURA HONESTA' do BLOCO 17: a conclusão sobre filtro × delírio sai de Fa/Fb/Fc/G e das ablações L1–L4, não de uma tabela só; nada aqui se transfere a ASI.")
    rep.log("2. LAUDO COMPLETO NO MÉTODO NOVO: `laudo_escrutinio` (R9, sem alteração) roda em 4 variantes por tarefa (L1 sem saída forçada, L2 sem filtro, L3 sem delírio, L4 filtro-só), em sementes frescas 10300+ e com rótulos de treino embaralhados (a alucinação não pode fabricar sinal do nada).")
    rep.log("3. DESEMPENHO: ver o item de tempo abaixo; o BLOCO 17 usa treino em float32 e fluxos de Lorenz em lote com memória (resultado independente de quem já estava no cache). Otimizações do código antigo foram feitas e verificadas pelo relatório: ver item 6.")
    rep.log("4. MELHORIAS: ver 'MIL E UMA MELHORIAS' (itens [IMPLEMENTADA na R10] e as ideias [NOVA R10]).")
    _m = r.get("melhorias")
    if _m and len(_m) > 29:
        rep.log(f"   contagem: {_m[26]} itens marcados [IMPLEMENTADA na R10…] ({_m[27]} totalmente + {_m[28]} PARCIALMENTE) e {_m[29]} ideias [NOVA R10].")
    if fw:
        rep.log(f"5. ERRO TIPO I ENTRE RODADAS (agora R2–R10): {fw['m']} confirmatórias com p bruto (as 55 novas da R10 entram na família global) → Holm global confirma {fw['holm']} ({', '.join(fw['ids_holm']) if fw['ids_holm'] else 'nenhuma'}); BH global confirma {fw['bh']}; {fw['raw']} têm p bruto < 0,05.")
    tm = r.get("tempos", {})
    rep.log("   [tempos R10 desta execução, pelo relógio de parede] " + ", ".join(f"{k.replace('bloco', '')}={v:.1f}s" for k, v in tm.items() if v >= 0.5), vol=True)
    for l in NOTAS_R10_PERF:
        rep.log(l)
    rep.log("7. NEGATIVOS E LIMITES (R10): ver o fim do BLOCO 17 (ítens i–ix) e o pré-registro; resumo: tarefas minúsculas e escolhidas por mim, ajuste modesto, 'professor' = a própria rede, T2/T3 sem espaço para ganho, aumentos online × pools estáticos com custos de geração diferentes, "
            "laudo sem correção de multiplicidade, pré-registro auto-atestado. Depurei com sementes deslocadas (+10000), MAS rodei o programa completo duas vezes com as sementes registradas antes de escrever o Adendo (para integração e tempo; D1): vi os resultados, e só mudei depois disso a implementação numérica de r10_fb (desempenho) e um aviso; nenhuma escolha de análise/hipótese/regra mudou (Adendo 1).")


def _t_registro_r10_sintetico() -> bool:
    """Autoteste: o registro da R10 tem 55 confirmatórias com ids únicos e formato certo, com resultados sintéticos."""
    class _C:
        pass
    c = _C()
    ks = [(f"A_{m}", t) for t in R10_TAREFAS for m in R10_PADRAO] + [(k, t) for t in R10_TAREFAS for k in ("D", "Fa", "Fb", "Fc", "G", "C", "B")]
    P = {k: (0.01, -0.01, 0.03, 0.2, 0.9, 0.02) for k in ks}
    lau = {k: {"veredito": "INVALIDO", "motivos": ["V1 FALHOU: x"], "shuf": (0.5, 0.4, 0.6)} for k in R10_LAUDOS}
    c.res = {"r10_gen": {"n_c": 40, "n_f": 40, "P": P, "st": {k: "nula" for k in ks}, "melhor_pad": {t: "real" for t in R10_TAREFAS}, "E2": {"D": (0.0, 0.01, 0.0), "Fa": (0.0, 0.01, 0.0), "G": (0.0, 0.01, 0.0)},
                         "laudo": {t: lau for t in R10_TAREFAS}, "r1": [], "r2": [], "r3": []}}
    rows = registro_r10(c)
    conf = [x for x in rows if x[2] == "CONF"]
    return len(conf) == 55 and len({x[1] for x in rows}) == len(rows) and all(len(x) == 6 for x in rows)


