# ----------------------------------------------------------------------
# Registro de hipóteses, sumário e "o que mudou" da R9
# ----------------------------------------------------------------------

R9_DESC_A = {"sgdm": "SGD+momento", "adam": "Adam", "sgdr": "SGD com reinícios", "langevin": "Langevin (ruído iid anelado)", "ruido_pesos": "ruído nos pesos", "dropout": "dropout"}


def registro_r9(ctx: Contexto) -> list:
    """Linhas do registro da R9 (BLOCOS 15 e 16), construídas dos resultados desta execução: 36 CONF (24 A + 4 B + 4 C + 4 D), exploratórias, descritivas e laudos."""
    r = ctx.res
    out = []
    nn = r.get("r9_nn")
    if nn:
        for (k, t), (m_, lo, hi, pv, pa_, mde) in nn["P"].items():
            if k.startswith("A_"):
                hip = f"redes reais, tarefa {t}: delírio − {R9_DESC_A[k[2:]]} (acc de teste, {nn['n_c']} sementes novas 9200+, ajuste com orçamento igual)"
            elif k == "B":
                hip = f"redes reais, tarefa {t}: delírio − sem_saida (a SAÍDA FORÇADA ajuda? {nn['n_c']} sementes novas)"
            elif k == "C":
                hip = f"redes reais, tarefa {t}: delírio − delirio_emb (a ESTRUTURA CAÓTICA importa? {nn['n_c']} sementes novas)"
            else:
                hip = f"redes reais, tarefa {t}: delírio − MELHOR baseline por DEV = {nn['melhor_base'][t]} ({nn['n_c']} sementes novas)"
            out.append(("R9", f"R9-{k}_{t}", "CONF", hip, f"Δ={100 * m_:+.2f} pp IC[{100 * lo:+.2f},{100 * hi:+.2f}] p Holm(36)={pa_:.3f} MDE={100 * mde:.2f} pp", nn["st"][(k, t)]))
        out.append(("R9", "R9-E1", "EXPL", "delírio − so_agenda (o RUÍDO importa ou só a agenda?) por tarefa (acc de teste)", "; ".join(f"{t}: {100 * v[0]:+.2f} pp (p={v[1]:.3f})" for t, v in nn["E1"].items()), "exploratória"))
        out.append(("R9", "R9-E2", "DESC", "meta-análise DL do efeito D (delírio − melhor baseline por DEV) entre as 4 tarefas", f"efeito aleatório {100 * nn['E2'][0]:+.2f} pp (EP {100 * nn['E2'][1]:.2f}), I²={100 * nn['E2'][2]:.0f}%", "descritiva"))
        for t, L in nn["laudo"].items():
            out.append(("R9", f"R9-L_{t}", "DESC", f"laudo de escrutínio do delírio ajustado em {t} (sementes frescas 9300+; V1 efeito, V2 rótulos embaralhados, V3 sem saída forçada, V4 calibração)",
                        f"{L['veredito']}" + (f" — falhas: {', '.join(m.split(' ')[0] for m in L['motivos'])}" if L["motivos"] else ""), "descritiva"))
    au = r.get("r9_auto")
    if au:
        if not au["evol"]:
            out.append(("R9", "R9-LA", "DESC", "laudo de escrutínio dos genomas evoluídos (autopoiese, BLOCO 9)", "sem resultado evoluído a auditar (padrão mantido)", "descritiva"))
        for n, L in au["laudo"].items():
            out.append(("R9", f"R9-LA_{n.split('/')[0].replace(' ', '_')}", "DESC", f"laudo de escrutínio do genoma evoluído '{n}' (autopoiese; sementes de tarefa frescas 7000+)",
                        f"{L['veredito']}" + (f" — falhas: {', '.join(m.split(' ')[0] for m in L['motivos'])}" if L["motivos"] else ""), "descritiva"))
    fw = r.get("r5_fwer")
    if fw:
        out.append(("R9", "R9-W1", "DESC", f"FWER global (Holm/BH) sobre {fw['m']} confirmatórias de R2–R9 (as 36 novas da R9 entram)", f"Holm global confirma {fw['holm']} ({', '.join(fw['ids_holm']) if fw['ids_holm'] else 'nenhuma'}); BH confirma {fw['bh']}", "descritiva"))
    return out


def sumario_r9_linhas(ctx: Contexto) -> list:
    r = ctx.res
    nn, au = r.get("r9_nn"), r.get("r9_auto")
    L = []
    if nn:
        st, T = nn["st"], R9_TAREFAS
        nA = sum(st[(k, t)] == "confirmada" for (k, t) in st if k.startswith("A_"))
        nAn = sum(st[(k, t)].startswith("refutada") for (k, t) in st if k.startswith("A_"))
        L.append("• Delírio com saída forçada em REDES REAIS (R9: MLPs numpy em 4 tarefas — espirais, paridade, texto do dicionário, rede estreita e profunda —, 10 métodos com o MESMO orçamento de ajuste, 40 sementes novas, Holm sobre 36): contra o MELHOR baseline por DEV (D) → " +
                 ", ".join(f"{t}: {st[('D', t)]}" for t in T) + f"; contra cada um dos 6 baselines (A, 24 testes): delírio melhor em {nA}, pior em {nAn}; a saída forçada ajuda (B)? " + ", ".join(f"{t}: {st[('B', t)]}" for t in T) +
                 "; o caos estruturado importa vs caos embaralhado (C)? " + ", ".join(f"{t}: {st[('C', t)]}" for t in T) + ".")
        nv = [t for t in T if nn["laudo"][t]["veredito"] == "VALIDO"]
        L.append(f"• LAUDO DE ESCRUTÍNIO (R9; sementes frescas, rótulos embaralhados, ablação da saída forçada, calibração): resultado do delírio VALIDO em {len(nv)} de 4 tarefas" + (f" ({', '.join(nv)})" if nv else "") +
                 "; critério pré-registrado da tese (D confirmada com Δ>0 E laudo valido na mesma tarefa): " + (f"ATENDIDO em {', '.join(nn['suporte'])}" if nn["suporte"] else "NÃO atendido") + ".")
    if au:
        if au["evol"]:
            L.append("• Laudo da AUTOPOIESE (R9): " + "; ".join(f"genoma '{n}' → {au['laudo'][n]['veredito']}" + (f" ({', '.join(m.split(' ')[0] for m in au['laudo'][n]['motivos'])})" if au["laudo"][n]["motivos"] else "") for n in au["evol"]) +
                     " (a seleção do BLOCO 9 era menos exigente que o laudo).")
        else:
            L.append("• Laudo da AUTOPOIESE (R9): a seleção manteve o genoma padrão; nada evoluído a auditar.")
    return L


def secao_mudancas_r9(ctx: Contexto):
    rep, r = ctx.rep, ctx.res
    rep.titulo("O QUE MUDOU NA RODADA 9 (com os resultados desta execução)")
    nn, au, fw = r.get("r9_nn"), r.get("r9_auto"), r.get("r5_fwer")
    if nn:
        st = nn["st"]
        rep.log("1. A TEORIA CENTRAL EM REDES REAIS (BLOCO 15; pré-registro R9 com sha256 e carimbo 16:16 PT, antes do código integrado e das sementes confirmatórias; Adendo 1 depois do código e antes das sementes): MLPs numpy treinados em 4 tarefas (espirais, paridade k=5 de d=10, "
                "texto sintético do dicionário com rótulo XOR de tópicos, rede estreita e profunda em anéis) por 10 métodos — SGD+momento, Adam, SGD com reinícios, Langevin, ruído nos pesos, dropout, DELÍRIO com saída forçada e 3 controles (caos embaralhado, sem saída, só agenda) — cada um com 12 sorteios de hiperparâmetros × 3 sementes DEV "
                f"(orçamento de ajuste IGUAL) e uma avaliação única em {nn['n_c']} sementes novas; Holm sobre 36. RESULTADO: D (vs melhor baseline por DEV) = " + ", ".join(f"{t}: {st[('D', t)]}" for t in R9_TAREFAS) + " | B (sem saída forçada) = " + ", ".join(f"{t}: {st[('B', t)]}" for t in R9_TAREFAS) +
                " | C (caos embaralhado) = " + ", ".join(f"{t}: {st[('C', t)]}" for t in R9_TAREFAS) + " | A (24 comparações com cada baseline): " + f"{len(nn['A_conf'])} a favor do delírio. Acurácia média (%) por tarefa — delirio / melhor baseline por DEV: " +
                "; ".join(f"{t}: {100 * nn['acc'][('delirio', t)]:.1f} / {100 * nn['acc'][(nn['melhor_base'][t], t)]:.1f} ({nn['melhor_base'][t]})" for t in R9_TAREFAS) + ".")
        rep.log("   LEITURA: " + ("o critério pré-registrado da tese foi ATENDIDO em " + ", ".join(nn["suporte"]) + " (D confirmada com Δ>0 e laudo VALIDO), com as ressalvas de que são 4 tarefas minhas e redes minúsculas." if nn["suporte"] else
                 "o critério pré-registrado da tese (D confirmada com Δ>0 E laudo VALIDO na mesma tarefa) NÃO foi atendido; a teoria central do usuário segue sem suporte neste teste. Onde há diferença, veja a tabela de A: o que ela mostra é a comparação com cada baseline, não 'delírio > tudo'."))
    if au is not None:
        rep.log("2. LAUDO DE ESCRUTÍNIO (BLOCOS 15–16; generalização da validade pedida pelo usuário): função `laudo_escrutinio` com 4 critérios pré-registrados — V1 efeito em sementes frescas, V2 controle de rótulos embaralhados, V3 ablação da saída forçada, V4 calibração — que devolve VALIDO/INVALIDO e os motivos. "
                "Aplicado automaticamente (a) ao delírio ajustado em cada uma das 4 tarefas do BLOCO 15 e (b) a cada genoma evoluído da autopoiese (BLOCO 9) que difere do padrão. RESULTADO: " +
                ("(a) " + ", ".join(f"{t}: {nn['laudo'][t]['veredito']}" for t in R9_TAREFAS) + " | " if nn else "") + "(b) " + ("; ".join(f"{n}: {au['laudo'][n]['veredito']}" for n in au["evol"]) if au["evol"] else "o padrão foi mantido pela seleção (nada a auditar)") + ".")
    rep.log("3. SAÚDE DO CÓDIGO: índice (sumário) no topo do arquivo, gerado por script a partir dos marcadores de seção e conferido pelo autoteste (+ flag --indice); docstring do módulo com blocos, flags e receita de reprodução; duplicatas removidas e verificadas NEUTRAS para os resultados (dp/dpar → `dif_boot_palavras`; _AdamP7 → _AdamV com lr escalar ou por linha): "
            "relatório da R8 antes × depois idêntico linha a linha, exceto proveniência (sha256 do código) e uma cadeia de texto.")
    rep.log("4. MELHORIAS: ver 'MIL E UMA MELHORIAS' (itens [IMPLEMENTADA na R9] e 10 ideias [NOVA R9]).")
    _m = r.get("melhorias")
    if _m and len(_m) > 25:
        rep.log(f"   contagem: {_m[22]} itens marcados [IMPLEMENTADA na R9…] ({_m[23]} totalmente + {_m[24]} PARCIALMENTE) e {_m[25]} ideias [NOVA R9].")
    if fw:
        rep.log(f"5. ERRO TIPO I ENTRE RODADAS (agora R2–R9): {fw['m']} confirmatórias com p bruto (as 36 novas da R9 entram na família global) → Holm global confirma {fw['holm']} ({', '.join(fw['ids_holm']) if fw['ids_holm'] else 'nenhuma'}); BH global confirma {fw['bh']}.")
    tm = r.get("tempos", {})
    rep.log("6. DESEMPENHO/DIGEST: o DIGEST mudou (novos blocos 15 e 16, novas seções, VERSAO R9 → nova proveniência sha256 e nova sessão simulada 'sim-R9-…' no log de consultas na PRIMEIRA execução). Continua idêntico entre --jobs (cada célula do BLOCO 15 e cada grupo do BLOCO 16 é uma tarefa pura; "
            "o RNG de ruído de um lote depende só da composição do lote, que é fixa). Com --jobs > 1, as 40 células do BLOCO 15 são enviadas ao SEGUNDO PLANO logo após o BLOCO 2 e o laudo da autopoiese logo após o BLOCO 9 (rodam enquanto os outros blocos usam os núcleos ociosos).")
    rep.log("   [tempos R9 desta execução] " + ", ".join(f"{k.replace('bloco', '')}={v:.1f}s" for k, v in tm.items() if v >= 0.5), vol=True)
    rep.log("7. NEGATIVOS E LIMITES (R9): (a) redes minúsculas, lote completo, 400 passos e 4 tarefas escolhidas por mim — nada garante transferência a redes grandes ou dados reais; (b) 12 sorteios × 3 sementes DEV é um ajuste modesto e com maldição do vencedor; (c) `sem_saida` remove JUNTAS lr decrescente, wd e contração (B não separa qual componente importa); "
            "(d) as tarefas foram calibradas olhando sementes DEV (desvio declarado no pré-registro); (e) o envelope cosseno foi dado aos baselines (conservador contra o delírio); (f) o laudo é uma regra de decisão com limiares meus e SEM correção de multiplicidade; (g) pré-registro auto-atestado; (h) tudo é um simulador didático, não uma ASI.")


def _t_registro_r9_sintetico() -> bool:
    """Autoteste: o registro da R9 tem 36 confirmatórias com ids únicos e formato certo, com resultados sintéticos."""
    class _C:
        pass
    c = _C()
    ks = [(f"A_{m}", t) for t in R9_TAREFAS for m in R9_BASES] + [(k, t) for t in R9_TAREFAS for k in ("B", "C", "D")]
    P = {k: (0.01, -0.01, 0.03, 0.2, 0.9, 0.02) for k in ks}
    c.res = {"r9_nn": {"n_c": 40, "n_f": 40, "P": P, "st": {k: "nula" for k in ks}, "melhor_base": {t: "adam" for t in R9_TAREFAS}, "E1": {t: (0.0, 1.0) for t in R9_TAREFAS}, "E2": (0.0, 0.01, 0.0),
                       "laudo": {t: {"veredito": "INVALIDO", "motivos": ["V1 FALHOU: x"], "media": (0, 0, 0), "shuf": (0.5, 0.4, 0.6)} for t in R9_TAREFAS}},
             "r9_auto": {"evol": [], "laudo": {}}}
    rows = registro_r9(c)
    conf = [x for x in rows if x[2] == "CONF"]
    return len(conf) == 36 and len({x[1] for x in rows}) == len(rows) and all(len(x) == 6 for x in rows)


def registro_r8(ctx: Contexto) -> list:
    """Linhas do registro da R8 (BLOCOS 14, 7e e 13), construídas dos resultados desta execução."""
    r = ctx.res
    out = []
    g, o, e = r.get("r8_game"), r.get("r8_orc"), r.get("espelho")
    if g:
        dsc = {"J1": "CTRL vs SIM", "J2": "CTRL vs ALT", "J3": "CTRL vs OPT", "J4": "CTRL vs ALEAT (sem sinal)"}
        dg = {"G1": "CTRL vs ALT", "G2": "CTRL vs SIM", "G3": "CTRL vs OPT", "G4": "CTRL vs ALEAT", "G5": "OPT vs ALT (a correção otimista ajuda a GAN?)"}
        for (k, f), (m_, lo, hi, pv, pa_, mde) in g["P"].items():
            hip = (f"GAN real: {dg[k]} em distância→real, {g['n_g']} sementes novas 3100+" if f == "GAN" else f"jogo {f}: {dsc[k]} (Δ = Y_fixa − Y_CTRL, log₁₀ exploitability), {g['n_j']} sementes novas")
            out.append(("R8", f"R8-{k}_{f}", "CONF", hip, f"Δ={m_:+.3f} IC[{lo:+.3f},{hi:+.3f}] p Holm(21)={pa_:.3f} MDE={mde:.3f}", g["st"][(k, f)]))
        out.append(("R8", "R8-X1", "EXPL", "CTRL_H (histerese; pós-hoc) vs CTRL pré-registrado nos jogos (Δ = Y_CTRL − Y_CTRL_H)", "; ".join(f"{f}: {v[0]:+.3f} (p={v[1]:.3f})" for f, v in g["ctrlh"].items()), "exploratória"))
        out.append(("R8", "R8-X2", "DESC", "melhor regra fixa EX-POST × CTRL por família (Y médio)", "; ".join(f"{f}: {v[0]} {v[1]:+.2f} vs CTRL {v[2]:+.2f}" for f, v in g["orac"].items()), "descritiva"))
    if o:
        dsc = {"C1": "meta2_12 − langevin12 (igual nº de hiperparâmetros)", "C2": "meta_fixas48 − langevin48 (igual nº total de avaliações de ajuste)", "C3": "delirio48 − langevin48", "C4": "langevin48 − langevin12 (ajuste maior ajudou?)"}
        for (k, p), (m_, lo, hi, pv, pa_, mde) in o["C"].items():
            out.append(("R8", f"R8-{k}_{p}", "CONF", f"orçamento igual, paisagem {p}: Δscore {dsc[k]}, {o['n']} sementes novas 2200+", f"Δ={m_:+.3f} IC[{lo:+.3f},{hi:+.3f}] p Holm(12)={pa_:.3f} MDE={mde:.3f}", o["stC"][(k, p)]))
    if e:
        A = e["A"]
        inf = [k for k in M8_IDS if A[k]["auc"] > 0.65]
        out.append(("R8", "R8-M1", "DESC", f"componentes de IA: monitores com AUC > 0,65 para o desfecho 'saudável' ({e['n_te']} sementes de teste)", f"{len(inf)}/10: {', '.join(inf) if inf else 'nenhum'}", "descritiva"))
        mel = [k for k in M8_IDS if A[k]["n_acao"] >= 5 and A[k]["dlt_media"] > 0]
        out.append(("R8", "R8-M2", "DESC", "componentes de IA: controle disparado ≥ 5 vezes com ganho médio > 0 no desfecho", f"{len(mel)}/10: {', '.join(mel) if mel else 'nenhum'}", "descritiva"))
    fw = r.get("r5_fwer")
    if fw:
        out.append(("R8", "R8-W1", "DESC", f"FWER global (Holm/BH) sobre {fw['m']} confirmatórias de {rotulo_rodadas(ini=2)}", f"Holm global confirma {fw['holm']} ({', '.join(fw['ids_holm']) if fw['ids_holm'] else 'nenhuma'}); BH confirma {fw['bh']}", "descritiva"))
    return out


def sumario_r8_linhas(ctx: Contexto) -> list:
    r = ctx.res
    g, o, e = r.get("r8_game"), r.get("r8_orc"), r.get("espelho")
    L = []
    if g:
        st = g["st"]
        f = lambda k, fam: st[(k, fam)]
        L.append("• Jogos (R8): num jogo quadrático de n jogadores, a regra SIMULTÂNEA diverge quando há rotação e a OTIMISTA diverge no jogo cooperativo com passo grande; o controlador Prolog que escolhe a regra pelo ciclo observado → vs SIM " +
                 ", ".join(f"{fam}: {f('J1', fam)}" for fam in ("ZS2", "COOP2", "RPS3", "MIX")) + "; vs ALT " + ", ".join(f"{fam}: {f('J2', fam)}" for fam in ("ZS2", "COOP2", "RPS3", "MIX")) +
                 "; vs OPT " + ", ".join(f"{fam}: {f('J3', fam)}" for fam in ("ZS2", "COOP2", "RPS3", "MIX")) + ". A vantagem na mistura F4 sobre SIM/OPT é por construção do desenho (um nicho para cada regra fixa).")
        L.append("• GAN real (R8, 5 contrastes, Holm sobre 21): " + ", ".join(f"{k}: {st[(k, 'GAN')]}" for k in ("G1", "G2", "G3", "G4", "G5")) + ". Médias de distância→real: " + ", ".join(f"{k}={v[0]:.2f}" for k, v in g["gan"].items()) + ".")
    if o:
        L.append("• Orçamento de ajuste igual (R8): controlador vs Langevin com o mesmo nº de hiperparâmetros (C1) → " + ", ".join(f"{p}: {o['stC'][('C1', p)]}" for p in P7_PAIS) + "; com o mesmo nº total de avaliações de ajuste (C2) → " +
                 ", ".join(f"{p}: {o['stC'][('C2', p)]}" for p in P7_PAIS) + ". Critério 'o controle ajuda com orçamento igual': " + (f"ATENDIDO em {', '.join(o['ajuda'])}" if o["ajuda"] else "NÃO atendido") +
                 (f"; controlador PIOR com orçamento igual em {', '.join(o['pior'])}" if o["pior"] else "") + ".")
    if e:
        A = e["A"]
        inf = [k for k in M8_IDS if A[k]["auc"] > 0.65]
        L.append(f"• Componentes de IA com espelho metacognitivo (R8, descritivo): 10 componentes com monitor, controle e crença calibrada; {len(inf)}/10 monitores prevêem o desfecho acima do acaso (AUC > 0,65): {', '.join(inf) if inf else 'nenhum'}.")
    return L


