def _job_quad(x):
    return x * x







def _autoteste_r28(t, lk, anteriores):
    corpo = PREREG_R28_CORPO.encode() if isinstance(PREREG_R28_CORPO, str) else PREREG_R28_CORPO
    t("R28: pré-registro confere", hashlib.sha256(corpo).hexdigest() == PREREG_R28_CORPO_SHA256)
    if ADENDO1_R28_CORPO_SHA256:
        _a1 = ADENDO1_R28_CORPO.encode() if isinstance(ADENDO1_R28_CORPO, str) else ADENDO1_R28_CORPO
        t("R28: Adendo 1 confere", hashlib.sha256(_a1).hexdigest() == ADENDO1_R28_CORPO_SHA256)
    S0 = r28_sementes(0)
    S1 = r28_sementes(10000)
    nomes = list(S0)
    t("R28: contagens de sementes (16 DEV, 48 TESTE, 8 Mega, 100+100 verificador, 24×4 proxies, 16 DEV dos proxies)",
      [len(S0[k]) for k in ("dev", "test", "mega", "mega_pos", "p_mut", "p_ctl", "jepa", "cbp", "esq", "grpo", "px_dev")] == [16, 48, 8, 1, 100, 100, 24, 24, 24, 24, 16])
    t("R28: N usado (Adendo 1, só CPU): TESTE 40 ≤ 48 e proxies 16 ≤ 24, sempre PREFIXOS das faixas registradas; DEV 16 intacto", 8 <= R28_NTEST <= 48 and 8 <= R28_NPX <= 24 and R28_NDEV == 16 and (R28_NTEST, R28_NPX) == (40, 16))
    par_ok = all(set(S0[a]).isdisjoint(set(S0[b])) for i_, a in enumerate(nomes) for b in nomes[i_ + 1:])
    t("R28: faixas de sementes DISJUNTAS PAR A PAR (corrige a sobreposição S×X da R27) e sem repetição interna", par_ok and all(len(set(S0[k])) == len(S0[k]) for k in nomes))
    uso0 = set(s for k in nomes for s in S0[k])
    uso1 = set(s for k in nomes for s in S1[k])
    t("R28: sementes disjuntas de TODAS as rodadas anteriores (R24–R27 e autotestes) e o deslocamento +10000 não colide com as registradas", uso0.isdisjoint(set(anteriores)) and uso1.isdisjoint(set(anteriores)) and uso0.isdisjoint(uso1))
    t("R28: 13 hipóteses do núcleo (5+2+3+3) e 10 dos proxies, todas distintas, duas famílias Holm",
      len(R28_NUCLEO) == 13 and len(set(R28_NUCLEO)) == 13 and len(R28_HIPOT_PX) == 10 and not (set(R28_NUCLEO) & set(R28_HIPOT_PX)) and set(r28_desc_hipoteses()) == set(R28_NUCLEO) | set(R28_HIPOT_PX))
    t("R28: pilha padrão = RL ordinário + porta k=4 FIXO + filtro adaptativo; sem meta; sem extraordinário; k por tarefa só opcional",
      R28_STACK_DEFAULT["rl"] == "ordinario" and not R28_STACK_DEFAULT["extra"] and R28_STACK_DEFAULT["gate_k"] == 4 and R28_STACK_DEFAULT["meta"] is None
      and R28_STACK_DEFAULT["filtro"] == "adaptativo" and R25_K_GATE == 4 and R28_STACK_DEFAULT["modos_travados"]["H60"] == "OFF" and R28_STACK_DEFAULT["k_alocacao"].startswith("opcional"))
    t("R28: oito tarefas (4 Z + 4 H), duas novas (Z11, H50); lr travado dos seis antigos",
      len(R28_TAREFAS) == 8 and [R28_FAMILIA[x] for x in R28_TAREFAS].count("Z") == 4 and set(R28_NOVAS) == {"Z11", "H50"} and len(R28_LR_TRAVADO) == 6 and set(R28_LR_TRAVADO) | set(R28_NOVAS) == set(R28_TAREFAS))
    z11 = r28_tarefa("Z11")
    seq = [1, 1]
    while len(seq) < z11.L:
        seq.append((seq[-1] + seq[-2]) % z11.V)
    h50 = r28_tarefa("H50")
    h60 = r28_tarefa("H60")
    rh = r25_rng(98720, 1, 1)
    pol50 = h50.init_pol(rh)
    ids50, lp50 = h50.sample(pol50, rh)
    lau50 = h50.laudo(ids50, 98720, 1)
    t("R28: Z11 (mod 11): a sequência da regra tem r_clean=1; H50 (V=50, L=28, P=90) gera texto de 28 tokens com laudo em [0,1] e matriz diferente da H60",
      z11.V == 11 and abs(z11.r_clean(seq) - 1.0) < 1e-12 and z11.nome == "Z11" and h50.V == 50 and h50.L == 28 and h50.P == 90 and len(ids50) == 28 and max(ids50) < 50
      and 0.0 <= lau50["score_laudo"] <= 1.0 and h60.V == 60 and h50.M.shape != h60.M.shape)
    # regras de modo
    m_h60 = {"ON": 1.074, "LEVE": 1.195, "OFF": 1.192}
    t("R28: regra ANTIGA = r26_escolher_modo; a regra NOVA escolhe OFF no caso H60 da R27 (LEVE−OFF=0,003) onde a antiga escolhe LEVE",
      r28_regra_antiga(m_h60) == "LEVE" == r26_escolher_modo(m_h60) and r28_regra_nova(m_h60) == "OFF")
    t("R28: regra NOVA — o mais barato dentro de 0,01 do melhor (OFF<LEVE<ON); ON só se vence por >0,01; LEVE só se vence OFF por >0,01",
      r28_regra_nova({"ON": 0.9, "LEVE": 0.5, "OFF": 0.4}) == "ON" and r28_regra_nova({"ON": 0.90, "LEVE": 0.895, "OFF": 0.4}) == "LEVE"
      and r28_regra_nova({"ON": 0.5, "LEVE": 0.52, "OFF": 0.50}) == "LEVE" and r28_regra_nova({"ON": 0.5, "LEVE": 0.5, "OFF": 0.5}) == "OFF"
      and r28_regra_nova({"ON": 0.5, "LEVE": 0.6, "OFF": 0.5900001}) == "OFF")
    t("R28: regras divergem só no desempate de custo (antiga=ON quando ON está a ≤0,01 do melhor e OFF/LEVE não passam de ON+0,01; nova=o mais barato)",
      r28_regra_antiga({"ON": 0.50, "LEVE": 0.505, "OFF": 0.495}) == "ON" and r28_regra_nova({"ON": 0.50, "LEVE": 0.505, "OFF": 0.495}) == "OFF")
    # alocação a custo igual
    rg = np.random.default_rng(98721)
    ok_orc, ok_opt = True, True
    for _ in range(25):
        T_ = int(rg.integers(2, 5))
        v = {f"t{i}": {k: float(rg.normal()) for k in R28_KS} for i in range(T_)}
        al = r28_alocar(v)
        ok_orc = ok_orc and sum(al.values()) <= 4 * T_ and all(k in R28_KS for k in al.values())
        best = max(sum(v[f"t{i}"][c] for i, c in enumerate(cb)) for cb in itertools.product(R28_KS, repeat=T_) if sum(cb) <= 4 * T_)
        ok_opt = ok_opt and abs(sum(v[x][k] for x, k in al.items()) - best) < 1e-9
    t("R28: alocação a CUSTO IGUAL — Σk ≤ 4·T em todos os sorteios e ótima contra busca exaustiva independente", ok_orc and ok_opt)
    plano = {f"t{i}": {1: 0.0, 2: 0.0, 4: 0.0, 8: 0.0} for i in range(3)}
    t("R28: alocação — empate total ⇒ menor custo (todos k=1); orçamento explícito respeitado; só um k=8 sobe se o valor compensa",
      set(r28_alocar(plano).values()) == {1} and sum(r28_alocar({f"t{i}": {1: 0.0, 2: 0.1, 4: 0.2, 8: 0.9} for i in range(3)}, orcamento=10).values()) <= 10
      and sorted(r28_alocar({"a": {1: 0.0, 2: 0.0, 4: 0.0, 8: 1.0}, "b": {1: 0.0, 2: 0.0, 4: 0.0, 8: 0.0}, "c": {1: 0.0, 2: 0.0, 4: 0.0, 8: 0.0}}).values()) == [1, 1, 8])
    pm = r28_permutacoes({"a": 1, "b": 2, "c": 8})
    t("R28: permutações cíclicas — T−1 alocações, mesmo multiconjunto de k e mesmo custo",
      len(pm) == 2 and all(sorted(p_.values()) == [1, 2, 8] and sum(p_.values()) == 11 for p_ in pm) and pm[0] == {"a": 2, "b": 8, "c": 1})
    # contrastes + guardas de identidade
    ntt = 6
    rr = np.random.default_rng(98722)
    TEt = {}
    for tn in R28_TAREFAS:
        TEt[tn] = [{"Pf": {k: float(rr.random()) for k in R28_KS}, "Pr": {k: float(rr.random()) for k in R28_KS}, "aleat": 0.3} for _ in range(ntt)]
    nrm = {tn: (0.3, 0.9, 0.6) for tn in R28_TAREFAS}
    m_ = {tn: "ON" for tn in R28_TAREFAS}
    k4 = {tn: 4 for tn in R28_TAREFAS}
    D0, nd0, _ = r28_contrastes(TEt, nrm, m_, m_, k4, list(R28_TAREFAS))
    t("R28: GUARDA DE IDENTIDADE — k=4 em tudo e mesmos modos ⇒ E1,E2,E3,E4,E5,F1,F2 idênticos a 0 (n_dif=0) e status «nula por construção»",
      all(np.allclose(D0[h], 0.0, atol=1e-12) and nd0[h] == 0 for h in ("E1", "E2", "E3", "E4", "E5", "F1", "F2")) and r28_status("E1", 0.0, 1.0, 0) == "nula por construção" and r28_status("E2", 0.0, 0.0, 0) == "nula por construção")
    kk = {tn: 4 for tn in R28_TAREFAS}
    kk.update({"Z5": 8, "Z7": 8, "Z9": 2, "Z11": 2, "H50": 4, "H60": 1, "H70": 1, "H80": 4})
    mn = dict(m_)
    mn["H60"] = "OFF"
    ma = dict(m_)
    ma["H60"] = "LEVE"
    D1, nd1, SN1 = r28_contrastes(TEt, nrm, ma, mn, kk, list(R28_TAREFAS))
    polf = lambda tn: "Pr" if tn == "H60" else "Pf"      # modo antigo de H60 = LEVE (Pr); demais ON (Pf)
    man = np.mean([(np.asarray([e[polf(tn)][kk[tn]] for e in TEt[tn]]) - np.asarray([e[polf(tn)][4] for e in TEt[tn]])) / 0.6 for tn in R28_TAREFAS], axis=0)
    t("R28: E1 = média normalizada de (política@k_t − política@4) conferida à mão; E4/E5 usam só Z/H; F2 só as tarefas de modo diferente (H60)",
      np.allclose(D1["E1"], man) and nd1["E1"] == 6 and nd1["E4"] == 4 and nd1["E5"] == 2 and nd1["F1"] == 1 and nd1["F2"] == 1 and np.allclose(D1["E4"], np.mean([SN1[x]["ALLOC"] - SN1[x]["FIX4"] for x in ("Z5", "Z7", "Z9", "Z11")], axis=0))
      and np.allclose(D1["F2"], SN1["H60"]["NOV"] - SN1["H60"]["ANT"]))
    pm_ = r28_permutacoes({x: kk[x] for x in R28_TAREFAS})
    pp = np.mean([np.mean([r27_norm(np.asarray([e[polf(tn)][pm_[s_][tn]] for e in TEt[tn]]), 0.3, 0.6) for s_ in range(7)], axis=0) for tn in R28_TAREFAS], axis=0)
    t("R28: PERM = média sobre as 7 permutações cíclicas (mesmo custo) e E3 = ALLOC − PERM", np.allclose(D1["E3"], np.mean([SN1[x]["ALLOC"] for x in R28_TAREFAS], axis=0) - pp))
