    t("R28: Mega — 2994 concursos, 6 dezenas por concurso, janela de teste = os últimos 1000 (índices 1994..2993), aquecimento a partir do índice 60",
      Yr.shape == (len(dd), 60) and np.all(Yr.sum(axis=1) == 6) and len(dd) - R28_MEGA_TESTE == 1994 and R28_MEGA_INI == 60)
    rg2 = np.random.default_rng(98724)
    ell = rg2.normal(size=60)
    pk = [5, 17, 3, 44, 29, 8]

    def _lp(e):
        r_, s_ = 0.0, np.ones(60, bool)
        for j in pk:
            z = np.where(s_, e, -np.inf)
            z = z - z.max()
            r_ += float(z[j] - np.log(np.exp(z[s_]).sum()))
            s_[j] = False
        return r_
    gnum = np.array([(_lp(ell + 1e-6 * np.eye(60)[i]) - _lp(ell - 1e-6 * np.eye(60)[i])) / 2e-6 for i in range(60)])
