def _autoteste_r29(t, lk, anteriores):
    corpo = PREREG_R29_CORPO.encode() if isinstance(PREREG_R29_CORPO, str) else PREREG_R29_CORPO
    t("R29: pré-registro confere", hashlib.sha256(corpo).hexdigest() == PREREG_R29_CORPO_SHA256)
    if ADENDO1_R29_CORPO_SHA256:
        _a1 = ADENDO1_R29_CORPO.encode() if isinstance(ADENDO1_R29_CORPO, str) else ADENDO1_R29_CORPO
        t("R29: Adendo 1 confere", hashlib.sha256(_a1).hexdigest() == ADENDO1_R29_CORPO_SHA256)
    S0, S1 = r29_sementes(0), r29_sementes(10000)
    nomes = list(S0)
    t("R29: contagens de sementes (48 memória, 8+1 Mega, DEV 8×5, TESTE 48 GRPO/CBP/esquecimento/JEPA/dialética/dialética-RL)",
      [len(S0[k]) for k in ("mem", "mega", "mega_pos", "dev_grpo", "dev_cbp", "dev_esq", "dev_dial", "dev_dialrl", "grpo", "cbp", "esq", "jepa", "dial", "dialrl")] == [48, 8, 1, 8, 8, 8, 8, 8, 48, 48, 48, 48, 48, 48])
    t("R29: N usado (alvos; Adendo 1 só reduz por CPU) ≤ faixas reservadas e DEV ≤ 8", all(R29_NTEST[k] <= len(S0[{"mem": "mem", "jepa": "jepa", "cbp": "cbp", "esq": "esq", "dial": "dial", "grpo": "grpo", "dialrl": "dialrl"}[k]]) for k in R29_NTEST) and all(v <= 8 for v in R29_NDEV.values()))
    t("R29: faixas de sementes DISJUNTAS PAR A PAR e sem repetição interna", all(set(S0[a]).isdisjoint(set(S0[b])) for i_, a in enumerate(nomes) for b in nomes[i_ + 1:]) and all(len(set(S0[k])) == len(S0[k]) for k in nomes))
