    t("R30: congelado decodifica (sha256 confere) com os 9 blocos dormentes, cada um com suas linhas e a chave de resultado esperada; o 37 traz r29 com MEM 4/1/1, SEG 2/2/9, DIAL 1/4/6",
      cg is not None and all(b_ in cg and len(cg[b_]["linhas"]) > 5 and _chaves[b_] in cg[b_]["res"] for b_ in _blocos_d) and r29c.get("resumo") == {"MEM": (4, 1, 1), "SEG": (2, 2, 9), "DIAL": (1, 4, 6)}
      and "rng" in cg["bloco5"] and not any(k_.endswith("_dorm") for b_ in _blocos_d for k_ in cg[b_]["res"]))

    class _A:
        seed = 42; emb = "semantico"; rapido = False; offline = True; reativar_dormentes = False
    t("R30: dormência ativa no padrão para os 9 blocos; o BLOCO 38 nunca é dormente; blocos 36 (R29), 35 (R28) e 34 (R27) seguem dormentes; --rapido, outra semente ou --emb hash desligam",
      all(r30_dormente_ativo(_A(), b_) for b_ in _blocos_d) and not r30_dormente_ativo(_A(), "bloco38") and r29_dormente_ativo(_A(), "bloco36") and r28_dormente_ativo(_A(), "bloco35") and r27_dormente_ativo(_A(), "bloco34")
      and not any(r30_dormente_ativo(type("B", (), {"seed": 7, "emb": "semantico", "rapido": False, "offline": True, "reativar_dormentes": False})(), b_) for b_ in _blocos_d)
      and not r30_dormente_ativo(type("B", (), {"seed": 42, "emb": "semantico", "rapido": True, "offline": True, "reativar_dormentes": False})(), "bloco37"))
    _ok_env = True
