    _A.reativar_dormentes = True
    _ok_re = not any(r30_dormente_ativo(_A(), b_) for b_ in _blocos_d)
    _A.reativar_dormentes = False
    os.environ["R30_REATIVAR"] = "1"
    _ok_re2 = not any(r30_dormente_ativo(_A(), b_) for b_ in _blocos_d)
