    alega_t = [g for g, s in stn_t.items() if s == "confirmada"]
    ctx_b = type("C", (), {"res": {"r31": {"ver": ver_t}, "r28": {"custo_alloc": 24, "eff": list("abcdefgh")[:8]}, "r29": {}, "r30": {}}, "args": type("A_", (), {"seed": 42, "emb": "semantico", "rapido": False, "offline": True, "reativar_dormentes": False})()})()
    bc_t = r31_bc_do_run(ctx_b, {h: "registrada" for h in ("ST_RL", "CM1", "NG1")}, "v1_14_0", ver_t, pil_t, per_t, {tn: 4 for tn in R31_TAREFAS}, 24, stn_t, alega_t)
    ok_mut = True
    tipos_ = set()
    for i_ in range(16):
        bm, tp_ = r31_mutar(bc_t, i_, r25_rng(98930, i_, 1))
