    bc_t = r32_bc_do_run(ctx_b, {h: "registrada" for h in ("RP_RL", "CS1", "S1")}, "v1_15_0", ver_p, pil_p, per_p, dict(R32_KAL_R31), 21, stn_t, alega_t)
