    sB = dict(nula, G1="confirmada", G2="confirmada", G3="nula")
    sC = dict(nula, G1="nula")
    sD = dict(nula, G1="confirmada", G2="refutada", M1="refutada")
    vA, vB, vC, vD, v00 = r33_vereditos(sA), r33_vereditos(sB), r33_vereditos(sC), r33_vereditos(sD), r33_vereditos(nula)
    t("R33: decisão mecânica do GRPO — G1+G3+G4 confirmadas e G2 não refutada ⇒ MANTER (vivo); G1 confirmada, G3/G4 não ⇒ RESTRINGIR_Z (vivo); G1 nula ⇒ REVERTER (decorativo); G2 refutada ⇒ REVERTER (nocivo); dedup semântica viva só com M0, M1, M3 confirmadas e M2, M4 não refutadas; refutada ⇒ nociva",
      vA["decisao_grpo"] == "MANTER" and vA["grpo"] == "vivo" and vA["dedup_semantica"] == "vivo" and vB["decisao_grpo"] == "RESTRINGIR_Z" and vB["grpo"] == "vivo" and vC["decisao_grpo"] == "REVERTER" and vC["grpo"] == "decorativo"
      and vD["decisao_grpo"] == "REVERTER" and vD["grpo"] == "nocivo" and vD["dedup_semantica"] == "nocivo" and v00["dedup_semantica"] == "decorativo" and r33_vereditos(dict(sA, M2="refutada"))["dedup_semantica"] == "decorativo")
    pA, nA = r33_pilha_resultante(pil32, vA)
    pB, _nB = r33_pilha_resultante(pil32, vB)
    pC, _nC = r33_pilha_resultante(pil32, vC)
    t("R33: pilha resultante — MANTER ⇒ rl=grpo; RESTRINGIR_Z ⇒ rl=grpo_z (na_pilha traz GRPO e RL ordinário); REVERTER ⇒ rl=ordinario; dedup semântica viva entra como memória; a pilha permitida (função independente) coincide; o restante da pilha da R32 não muda",
      pA["rl"] == "grpo" and pA.get("memoria") == "dedup_semantica" and pB["rl"] == "grpo_z" and "memoria" not in pB and pC["rl"] == "ordinario" and pA == r33_permitido(vA, per32) and pB == r33_permitido(vB, per32) and pC == r33_permitido(vC, per32)
      and {"grpo", "rl_ordinario"} <= set(r33_na_pilha(pB)) and "rl_ordinario" not in r33_na_pilha(pA) and "dedup_semantica" in r33_na_pilha(pA) and all(pA[k] == pil32[k] for k in pil32 if k not in ("rl", "memoria")) and len(nA) == 2)
    stn_t = {f"ng{i}": ("confirmada" if i % 2 else "nula") for i in range(1, 10)}
    alega_t = [g for g, s in stn_t.items() if s == "confirmada"]
    ctx_b = type("C", (), {"res": {"r31": {"ver": ver_t}, "r32": {}, "r33": {}, "r28": {"custo_alloc": 17, "eff": list("abcdefgh")[:8]}, "r29": {}, "r30": {}}, "args": type("A_", (), {"seed": 42, "emb": "semantico", "rapido": False, "offline": True, "reativar_dormentes": False})()})()
    mk_bc = lambda vn, pil, per: r33_bc_do_run(ctx_b, {h: "registrada" for h in ("G1", "M1", "ND2")}, "v1_16_0", dict(ver_t, **{k: vn[k] for k in R33_COMP_NOVOS}), pil, per, dict(R33_KAL), 17, stn_t, alega_t)
    bcs = [mk_bc(vA, pA, r33_permitido(vA, per32)), mk_bc(vB, pB, r33_permitido(vB, per32)), mk_bc(vC, pC, r33_permitido(vC, per32))]
    t("R33: a BC com os vereditos R33 é CONSISTENTE no motor Prolog e no checador independente para MANTER, RESTRINGIR_Z e REVERTER; dedup_semantica entra como opcional",
      all(r31_checar_prolog(r31_bc_texto(b)) == [] and r31_checar_py(b) == [] for b in bcs) and all("dedup_semantica" in b["opcional"] for b in bcs) and bcs[0]["stack"]["rl"] == "grpo" and bcs[1]["stack"]["rl"] == "grpo_z")
    bad1 = copy.deepcopy(bcs[0]); bad1["na_pilha"] = [x for x in bad1["na_pilha"] if x != "dedup_semantica"]
    bad2 = copy.deepcopy(bcs[1]); bad2["na_pilha"].append("dedup_semantica"); bad2["veredito"]["dedup_semantica"] = "decorativo"
    t("R33: regras — dedup semântica VIVA fora da pilha é violação (vivo_opcional_fora) e componente NÃO vivo na pilha é violação (nao_vivo_na_pilha), Prolog = Python",
      r31_checar_prolog(r31_bc_texto(bad1)) == r31_checar_py(bad1) == ["vivo_opcional_fora(dedup_semantica)"] and r31_checar_prolog(r31_bc_texto(bad2)) == r31_checar_py(bad2) == ["nao_vivo_na_pilha(dedup_semantica)"])
    okm = True
    for b in bcs:
        for i_ in range(32):
            bm, tp_ = r33_mutar(b, i_, r25_rng(98972, i_, 1))
