    t("R35: hipóteses — LX 8, SN 9, OZ 8, FS 7 (32 distintas, descrições completas, quatro famílias Holm independentes)",
      len(R35_HIPOT_LX) == 8 and len(R35_HIPOT_SN) == 9 and len(R35_HIPOT_OZ) == 8 and len(R35_HIPOT_FS) == 7 and len(set(R35_TODAS)) == 32 and set(r35_desc_hipoteses()) == set(R35_TODAS))
    t("R35: grade de lr estendida além da borda da R34 (1,35; 4,05; 12,15; 36,45), lr fixos comuns ⊂ grade, o lr travado de H continua 0,15; alocação k idêntica à R34 (Σk = 17); Z = Z7, Z9; H = 5; H3 = tarefas da pilha",
      R35_LR_GRADE == (1.35, 4.05, 12.15, 36.45) and set(R35_LR_FIXO) <= set(R35_LR_GRADE) and R35_LR_GRADE[0] > max(R34_LR_GRADE1) and R35_LR_TRAV_H == R34_LR_TRAV_H == 0.15 and R35_KAL == R34_KAL and sum(R35_KAL.values()) == 17
      and R35_Z == ("Z7", "Z9") and len(R35_H) == 5 and R35_H3 == ("H80", "H70", "H60") and set(R35_STK5) == set(R35_Z) | set(R35_H3))
    # ---- job da pilha nova ----
