      set(js["SH"]) == set(R35_STK5) and all(js["SH"][tn][c]["F"] == js["SH"][tn][c]["BASE"] == js["SH"][tn][c]["LRM"] for tn in R35_Z for c in R35_CONDS) and all(js["SH"][tn]["ID"]["STK"] != js["SH"][tn]["ID"]["BASE"] for tn in R35_Z)
