def _autoteste_r27(t, lk, anteriores):
    r1_eq = lambda g1, g2: float(g1.random()) == float(g2.random())
    corpo = PREREG_R27_CORPO.encode() if isinstance(PREREG_R27_CORPO, str) else PREREG_R27_CORPO
    t("R27: pré-registro confere", hashlib.sha256(corpo).hexdigest() == PREREG_R27_CORPO_SHA256)
    if ADENDO1_R27_CORPO_SHA256:
        _a1 = ADENDO1_R27_CORPO.encode() if isinstance(ADENDO1_R27_CORPO, str) else ADENDO1_R27_CORPO
        t("R27: Adendo 1 confere", hashlib.sha256(_a1).hexdigest() == ADENDO1_R27_CORPO_SHA256)
    S0 = r27_sementes(0)
    uso = set(S0["dev"]) | set(S0["test"]) | set(S0["hw_dev"]) | set(S0["hw_s"]) | set(S0["hw_x"])
    t("R27: 40 sementes de texto e 80+80 de BitLinear", len(S0["test"]) == 40 and len(S0["hw_s"]) == 80 and len(S0["hw_x"]) == 80 and len(S0["hw_dev"]) == 8)
    t("R27: DEV disjunto de TESTE (texto)", set(S0["dev"]).isdisjoint(set(S0["test"])))
    t("R27: sementes disjuntas das rodadas anteriores (R24–R26)", uso.isdisjoint(set(anteriores)))
    hw_all = list(S0["hw_s"]) + list(S0["hw_x"]) + list(S0["hw_dev"])
    hw_u = set(S0["hw_s"]) | set(S0["hw_x"])
    t("R27: BitLinear com sementes ESPAÇADAS (passo 2): nenhum seed+1 (conjunto de teste de uma semente) coincide com outra semente de treino, e sem repetição dentro de cada tarefa",
      all((s + 1) not in hw_u for s in hw_u) and len(set(S0["hw_s"])) == 80 and len(set(S0["hw_x"])) == 80 and set(S0["hw_dev"]).isdisjoint(hw_u))
    t("R27: 18 hipóteses (7+3+6+2) em uma família Holm", len(R27_TODAS) == 18 and len(set(R27_TODAS)) == 18)
    # pilha padrão com filtro adaptativo travado, consistente com o congelado da R26
    cg = r27_congelado()
    r26c = (cg or {}).get("bloco34", {}).get("res", {}).get("r26", {})
    t("R27: pilha padrão = RL ordinário + porta k=4 + filtro adaptativo travado; sem meta; sem extraordinário",
      R27_STACK_DEFAULT["rl"] == "ordinario" and not R27_STACK_DEFAULT["extra"] and R27_STACK_DEFAULT["gate_k"] == 4
      and R27_STACK_DEFAULT["meta"] is None and R27_STACK_DEFAULT["filtro"] == "adaptativo" and R25_K_GATE == 4)
    t("R27: modos e lr TRAVADOS = os escolhidos no DEV da R26 (conferidos no congelado sha256 do BLOCO 34)",
      bool(r26c) and all(r26c["modos"][tn] == R27_TRAVADO[tn][0] and abs(r26c["lr"][tn] - R27_TRAVADO[tn][1]) < 1e-12 for tn in R27_TRAVADO))
    t("R27: 6 tarefas (3 Z + 3 H), 2 novas (Z9,H70)", len(R27_TAREFAS) == 6 and [R27_FAMILIA[x] for x in R27_TAREFAS].count("Z") == 3 and set(R27_NOVAS) == {"Z9", "H70"})
    z9 = r27_tarefa("Z9")
    seq = [1, 1]
    while len(seq) < z9.L:
        seq.append((seq[-1] + seq[-2]) % z9.V)
    t("R27: Z9 (mod 9): sequência da regra tem r_clean=1", z9.V == 9 and abs(z9.r_clean(seq) - 1.0) < 1e-12 and z9.nome == "Z9")
    h70, h60 = r27_tarefa("H70"), r27_tarefa("H60")
    t("R27: H70 é outra tarefa (V=70, L=36; matriz distinta da H60)", h70.V == 70 and h70.L == 36 and h70.M.shape == (70, 70) and abs(float(h70.M.sum(axis=1).mean()) - 1.0) < 1e-9 and h60.M.shape == (60, 60))
    ids = h70.sample_uniform(r25_rng(98500, 1, 1))
    lh = h70.laudo(ids, 98500, 1)
    t("R27: H70 laudo e r_clean finitos", np.isfinite(h70.r_clean(ids)) and 0.0 <= lh["score_laudo"] <= 1.0 and len(ids) == 36)
    # amostragem rápida bit-idêntica (CPU) — R27Hard e R27Sym contra as implementações originais
    for _tn in ("H80", "H70"):
        _p = R27_PRM_HARD[_tn]
        _rapido = r27_tarefa(_tn)
        _orig = R26Hard(_tn, _p["V"], _p["L"], _p["seed_lex"], _p["P"])
        _pol = _orig.init_pol(r25_rng(98510, 3, 3))
        _pol["W"] = _pol["W"] + np.random.default_rng(5).normal(0, 0.8, size=_pol["W"].shape)
        _r1, _r2 = r25_rng(98511, 7, 7), r25_rng(98511, 7, 7)
        _ok = True
        for _i in range(12):
            a_, b_ = _rapido.sample(_pol, _r1), _orig.sample(_pol, _r2)
            _ok = _ok and a_[0] == b_[0] and a_[1] == b_[1]
        t(f"R27/perf: amostragem rápida do texto {_tn} é BIT-IDÊNTICA à r24_sample_policy (ids e log-probs; estado do RNG idêntico depois)", _ok and r1_eq(_r1, _r2))
    _zr = r27_tarefa("Z9")
    _zo = R25Sym(R27_PRM_SYM["Z9"])
    _zo.nome = "Z9"
    _pz = _zo.init_pol(r25_rng(98512, 3, 3))
    _pz["W"] = _pz["W"] + np.random.default_rng(6).normal(0, 1.5, size=_pz["W"].shape)
    _q1, _q2 = r25_rng(98513, 8, 8), r25_rng(98513, 8, 8)
    _okz = True
    for _i in range(40):
        a_, b_ = _zr.sample(_pz, _q1), _zo.sample(_pz, _q2)
        _okz = _okz and a_[0] == b_[0] and all(np.array_equal(x1[2], x2[2]) and x1[:2] == x2[:2] for x1, x2 in zip(a_[1], b_[1]))
    t("R27/perf: amostragem rápida simbólica Z9 é BIT-IDÊNTICA à R25Sym.sample (ids, estados, probabilidades; RNG idêntico depois)", _okz and r1_eq(_q1, _q2))
    # configurações e orçamento IGUAL
    t("R27: cfg Pf (filtro), Pr (bruta) sem meta/extra; Pm usa a recompensa do modo + meta_norm",
      r27_cfg_pf()["recompensa"] == "filtro" and r27_cfg_pf()["meta"] is None and r27_cfg_pr()["recompensa"] == "raw" and r27_cfg_pr()["meta"] is None
      and r27_cfg_pm("ON")["recompensa"] == "filtro" and r27_cfg_pm("LEVE")["recompensa"] == "raw" and r27_cfg_pm("OFF")["recompensa"] == "raw"
      and all(r27_cfg_pm(m)["meta"] == "norm" and not r27_cfg_pm(m)["extra"] for m in R27_MODOS))
    t("R27: porta por modo (ON/LEVE k=4; OFF k=1)", [r27_k_modo(m) for m in R27_MODOS] == [4, 4, 1])
    cont = {"n": 0}

    class _Cnt(R25Sym):
        def update(self, pol, seqs, advs, lr, extra, pesos):
            cont["n"] += 1
            return super().update(pol, seqs, advs, lr, extra, pesos)
    tz = _Cnt({"V": 5, "L": 8, "B": 2, "P": 21, "tau_y": 0.5})
    tz.nome = "Z5"
    ns = []
    for cf in (r27_cfg_pf(), r27_cfg_pr(), r27_cfg_pm("ON"), r27_cfg_pm("OFF")):
        cont["n"] = 0
        r25_treinar(tz, cf, 98501, 1.0)
        ns.append(cont["n"])
    t("R27: ORÇAMENTO IGUAL (Pf, Pr, Pm_ON, Pm_OFF fazem o mesmo nº de atualizações)", ns == [21, 21, 21, 21])
    pa = r25_treinar(tz, R26_CFG["LEVE"], 98502, 1.0)["pol"]["W"]
    pb = r25_treinar(tz, R26_CFG["OFF"], 98502, 1.0)["pol"]["W"]
    pc = r25_treinar(tz, r27_cfg_pr(), 98502, 1.0)["pol"]["W"]
    t("R27: LEVE e OFF treinam a MESMA política (só a porta na avaliação difere) = a política Pr compartilhada", np.array_equal(pa, pb) and np.array_equal(pa, pc))
    # avaliação aninhada: propriedade de prefixo e referência ingênua
    tz2 = R25Sym({"V": 5, "L": 8, "B": 2, "P": 21, "tau_y": 0.5})
    tz2.nome = "Z5"
    pol = r25_treinar(tz2, r27_cfg_pf(), 98503, 1.0)["pol"]
    e8 = r27_avaliar_aninhado(tz2, pol, 98503, "Pf", 8)
    e4 = r27_avaliar_aninhado(tz2, pol, 98503, "Pf", 4)
    t("R27: avaliação aninhada — chaves k∈{1,2,4,8} (kmax=8) e {1,2,4} (kmax=4), valores finitos e keep em [0,1]", sorted(e8) == [1, 2, 4, 8] and sorted(e4) == [1, 2, 4]
      and all(np.isfinite(v[0]) and 0.0 <= v[1] <= 1.0 for v in list(e8.values()) + list(e4.values())))

    def _ref(kmax_):
        rng_n = r25_rng(98503, r25_crc("eval27|Z5|Pf"), 13)
        ref = {k: [] for k in (1, 2, 4, 8) if k <= kmax_}
        for i in range(R25_N_EVAL):
            cands = []
            for j in range(kmax_):
                ids_ = tz2.sample(pol, rng_n)[0]
                la = tz2.laudo(ids_, 98503, 5000 + i * 10 + j)
                cands.append((ids_, (1 if la["passa_tela"] else 0, la["score_laudo"])))
            for k in ref:
                best = cands[0]
                for c in cands[1:k]:
                    if c[1] > best[1]:
                        best = c
                ref[k].append(tz2.r_clean(best[0]))
        return ref
    r8, r4 = _ref(8), _ref(4)
    t("R27: avaliação aninhada = referência ingênua (melhor-de-k pela chave (passa_tela, score) a partir dos mesmos candidatos), para kmax=8 e kmax=4",
      all(abs(np.mean(r8[k]) - e8[k][0]) < 1e-12 for k in r8) and all(abs(np.mean(r4[k]) - e4[k][0]) < 1e-12 for k in r4))
    # normalização, escolha de k, contrastes e guardas de identidade
    A, R_, den = r27_norm_const(0.2, {"ON": 0.5, "LEVE": 0.4, "OFF": 0.3})
    t("R27: normalização — acaso→0, melhor modo do DEV→1, denominador com piso 0,05", abs(r27_norm(0.2, A, den)) < 1e-12 and abs(r27_norm(0.5, A, den) - 1.0) < 1e-12 and r27_norm_const(0.5, {"ON": 0.51, "LEVE": 0.5, "OFF": 0.5})[2] == R27_DEN_MIN)
    t("R27: escolha de k — o MENOR k dentro de 0,01 do melhor; empate/ruído → menor",
      r27_escolher_k({1: 0.50, 2: 0.55, 4: 0.60, 8: 0.605}) == 4 and r27_escolher_k({1: 0.50, 2: 0.60, 4: 0.60, 8: 0.60}) == 2 and r27_escolher_k({1: 0.6, 2: 0.6, 4: 0.6, 8: 0.6}) == 1
      and r27_escolher_k({1: 0.5, 2: 0.5, 4: 0.5, 8: 0.52}) == 8)
    n3 = 5
    SNt = {tn: {k: np.linspace(0.1, 0.5, n3) + 0.01 * i for i, k in enumerate(("ON", "LEVE", "OFF", "ADAPT", "META", "POL4", "POLK", "ALEAT"))} for tn in R27_TAREFAS}
    md_all_on = {tn: "ON" for tn in R27_TAREFAS}
    for tn in R27_TAREFAS:
        SNt[tn]["ADAPT"] = SNt[tn]["ON"].copy()
    Dt, ndt = r27_contrastes(SNt, md_all_on, {tn: 4 for tn in R27_TAREFAS})
    t("R27: GUARDA DE IDENTIDADE — adaptativo=ON em tudo ⇒ A1 exatamente 0 e tarefas_diferentes=0; G1/G2 idênticos a 0 com k*=4",
      np.all(Dt["A1"] == 0.0) and ndt["A1"] == 0 and ndt["A6"] == 0 and ndt["A2"] == 6 and ndt["G1"] == 0
      and r27_status("A1", 0.0, 1.0, 0) == "nula por construção" and r27_status("G2", 0.0, 0.0, 0) == "nula por construção")
    md_real = {"Z7": "ON", "Z5": "ON", "H80": "LEVE", "H60": "OFF", "Z9": "ON", "H70": "LEVE"}
    for tn in R27_TAREFAS:
        SNt[tn]["ADAPT"] = SNt[tn][md_real[tn]].copy()
    Dt2, ndt2 = r27_contrastes(SNt, md_real, {"Z7": 4, "Z5": 2, "H80": 4, "H60": 8, "Z9": 4, "H70": 4})
    t("R27: com os modos travados, A1–A5 NÃO são identidades (tarefas diferentes ≥ 1) e A3 (sempre_LEVE) difere de A1",
      all(ndt2[h] >= 1 for h in ("A1", "A2", "A3", "A4", "A5", "A6", "A7")) and not np.array_equal(Dt2["A1"], Dt2["A3"]) and ndt2["G1"] == 2)
    t("R27: A4 usa só a família H e A5 só a Z (média das 3 tarefas); A6/A7 só as novas",
      np.allclose(Dt2["A4"], np.mean([SNt[x]["ADAPT"] - SNt[x]["ON"] for x in ("H80", "H60", "H70")], axis=0))
      and np.allclose(Dt2["A5"], np.mean([SNt[x]["ADAPT"] - SNt[x]["OFF"] for x in ("Z7", "Z5", "Z9")], axis=0))
      and np.allclose(Dt2["A6"], np.mean([SNt[x]["ADAPT"] - SNt[x]["ON"] for x in ("Z9", "H70")], axis=0)))
    t("R27: G2 é não-inferioridade (margem −0,02): status usa Δ+0,02", r27_status("G2", -0.01, 0.001, 2) == "confirmada" and r27_status("G2", -0.05, 0.001, 2) == "refutada" and r27_status("G1", -0.01, 0.001, 2) == "refutada")
    pk = r25_pack(np.zeros(12), seed=1)
    t("R27: efeito exatamente 0 ⇒ p=1 e d_z=0", pk["p"] == 1.0 and pk["dz"] == 0.0)
    # vereditos
    vf = lambda a1, a2, a3, a6="nula", a7="nula": r27_regra_filtro({"A1": a1, "A2": a2, "A3": a3, "A6": a6, "A7": a7})
    t("R27: veredito do filtro — confirmado só se A1–A3 todas confirmadas; refutada rebaixa; senão mantido sem confirmação",
      "CONFIRMADO E MANTIDO" in vf("confirmada", "confirmada", "confirmada") and "REBAIXADO" in vf("confirmada", "refutada", "confirmada") and "SEM CONFIRMAÇÃO" in vf("confirmada", "nula", "confirmada"))
    t("R27: generalização a tarefas novas só se A6 E A7 confirmadas", "GENERALIZA" in vf("confirmada", "confirmada", "confirmada", "confirmada", "confirmada") and "NÃO demonstrada" in vf("confirmada", "confirmada", "confirmada", "confirmada", "nula"))
    vm = lambda a, b, c: r27_regra_meta({"M1": a, "M1_Z": b, "M1_H": c})
    t("R27: decisão da meta — dano (qualquer refutada) / opcional (alguma confirmada sem dano) / nula ⇒ sai da pilha recomendada",
      "SAIR DA PILHA RECOMENDADA (dano)" in vm("nula", "refutada", "nula") and "MANTER OPCIONAL" in vm("nula", "confirmada", "nula") and "SAIR DA PILHA RECOMENDADA (nula)" in vm("nula", "nula", "nula")
      and "SAIR DA PILHA RECOMENDADA (dano)" in vm("confirmada", "refutada", "nula"))
    kk = {tn: 4 for tn in R27_TAREFAS}
    kk2 = dict(kk); kk2["Z5"] = 2; kk2["H60"] = 2
    t("R27: decisão da porta — k*=4 em tudo ⇒ k=4 fixo (nulo por construção); G1 ⇒ adotada; G2 com k̄*<4 ⇒ opção econômica; senão k=4 fixo",
      "NULOS POR CONSTRUÇÃO" in r27_regra_gate({"G1": "nula", "G2": "nula"}, kk) and "ADOTADA (G1" in r27_regra_gate({"G1": "confirmada", "G2": "confirmada"}, kk2)
      and "OPÇÃO ECONÔMICA" in r27_regra_gate({"G1": "nula", "G2": "confirmada"}, kk2) and "FIXO MANTIDO" in r27_regra_gate({"G1": "nula", "G2": "nula"}, kk2))
    mh = {"acc_dense": 0.88, "acc_bit": 0.85}
    cs = lambda c1, c2, c3, m=mh: r27_veredito_hw_tarefa({"C1": c1, "C2": c2, "C3": c3}, m, "x")[0]
    t("R27: veredito BitLinear por tarefa — COLAPSA / INVÁLIDA / NÃO-INFERIOR / GAP / INCONCLUSIVO / teto bloqueia não-inferior",
      cs("nula", "confirmada", "nula") == "COLAPSA" and cs("confirmada", "nula", "nula") == "INVALIDA" and cs("confirmada", "confirmada", "confirmada") == "NAO-INFERIOR"
      and cs("confirmada", "confirmada", "refutada") == "GAP" and cs("confirmada", "confirmada", "nula") == "INCONCLUSIVO"
      and cs("confirmada", "confirmada", "confirmada", {"acc_dense": 0.99, "acc_bit": 0.98}) == "INCONCLUSIVO")
    t("R27: regra global de congelamento — SÓ 2× NÃO-INFERIOR mantém ativo; COLAPSA/GAP congela; resto congela por parcimônia",
      r27_hw_ativo(r27_regra_hw_global("NAO-INFERIOR", "NAO-INFERIOR")) and not r27_hw_ativo(r27_regra_hw_global("NAO-INFERIOR", "INCONCLUSIVO"))
      and "lacuna/colapso" in r27_regra_hw_global("GAP", "NAO-INFERIOR") and "parcimônia" in r27_regra_hw_global("INCONCLUSIVO", "INCONCLUSIVO")
      and not r27_hw_ativo(r27_regra_hw_global("COLAPSA", "NAO-INFERIOR")))
    # xadrez com ruído e escada
    X1, y1 = r27_xadrez(98504, 400, 4, 0.03, 0.05)
    X2, y2 = r27_xadrez(98504, 400, 4, 0.03, 0.05)
    Xt, yt = r27_xadrez(98505, 400, 4, 0.0, 0.0, teste=True)
    reg = (np.floor((Xt[:, 0] + 1.0) * 4 / 2.0) + np.floor((Xt[:, 1] + 1.0) * 4 / 2.0)) % 2
    t("R27: xadrez: formato, determinístico, rótulos em {0,1}; teste sem ruído tem rótulo = regra do tabuleiro; treino tem ~5% de rótulos invertidos",
      X1.shape == (400, 2) and np.array_equal(X1, X2) and set(np.unique(y1)) <= {0.0, 1.0} and np.array_equal(reg, yt) and 0.0 < float(np.mean(
          y1 != ((np.floor((X1[:, 0] + 1.0) * 2.0) + np.floor((X1[:, 1] + 1.0) * 2.0)) % 2))) < 0.25)
    t("R27: escada do xadrez — 5 níveis crescentes (g) e escolha = primeiro com denso em [0,70; 0,93]; senão o mais próximo de 0,85",
      [v["g"] for v in R27_X_NIVEIS] == sorted(v["g"] for v in R27_X_NIVEIS) and len(R27_X_NIVEIS) == 5
      and r27_escolher_nivel_x([(1, 0.9, 0.99), (2, 0.8, 0.9), (3, 0.7, 0.8)]) == (2, True) and r27_escolher_nivel_x([(1, 0.9, 0.99), (2, 0.5, 0.6), (3, 0.5, 0.97)]) == (3, False))
    nv_t = {"n": 9, "g": 3, "sx": 0.03, "f": 0.05, "ntr": 60}
    rg_t = {"g": 2, "H": 8, "passos": 20, "fourier": 3.0}
    hd = r27_mlp_xadrez("dense_fp", 98506, nv_t, rg_t)
    hb = r27_mlp_xadrez("bit_v2", 98506, nv_t, rg_t)
    t("R27: BitLinear/denso no xadrez: acc em [0,1], energia ternária < densa, determinístico, zeros ∈ [0,1]",
      0.0 <= hd["acc"] <= 1.0 and 0.0 <= hb["acc"] <= 1.0 and hb["energia"] < hd["energia"] and hb["acc"] == r27_mlp_xadrez("bit_v2", 98506, nv_t, rg_t)["acc"] and 0.0 <= hb["frac_zero"] <= 1.0)
    jh = r27_job_hw(("S", 98600))
    t("R27: job BitLinear espirais N2 = função R26 com o MESMO nível (N2, 2,0 voltas, σ 0,05) e ternário/denso finitos",
      R27_NIVEL_S == {"n": 2, "voltas": 2.0, "sx": 0.05, "ntr": 300} and 0.0 <= jh["acc_bit"] <= 1.0 and 0.0 <= jh["acc_dense"] <= 1.0)
    # dormência R27 (bloco 34)
    class _A:
        seed = 42; emb = "semantico"; rapido = False; offline = True; reativar_dormentes = False
    t("R27: congelado BLOCO 34 decodifica (sha256 confere) e traz r26 com 8 conf / 0 ref / 3 nulas",
      cg is not None and "bloco34" in cg and r26c.get("n_conf") == 8 and r26c.get("n_ref") == 0 and r26c.get("n_nula") == 3 and "P" in r26c)
    t("R27: dormência do BLOCO 34 ativa no padrão e desligada por R26_DEV; blocos 21/22/33 seguem dormentes (R26)",
      r27_dormente_ativo(_A(), "bloco34") and not r27_dormente_ativo(_A(), "bloco35") and all(r26_dormente_ativo(_A(), b_) for b_ in ("bloco21", "bloco22", "bloco33")))
    _env0 = os.environ.get("R26_DEV")
    os.environ["R26_DEV"] = "1"
    _off_flag = not r27_dormente_ativo(_A(), "bloco34")
    if _env0 is None:
        os.environ.pop("R26_DEV", None)
    else:
        os.environ["R26_DEV"] = _env0
    t("R27: flag R26_DEV desliga a dormência do BLOCO 34 (depuração roda ao vivo)", _off_flag)
    _A.reativar_dormentes = True
    t("R27: dormência desliga com --reativar-dormentes", not r27_dormente_ativo(_A(), "bloco34"))
    _A.reativar_dormentes = False
    t("R27: estado do mapa deriva da dormência (bloco34 DORMENTE R27; bloco33 DORMENTE; bloco35 ATIVO)",
      r27_estado_bloco(_A(), "bloco34").startswith("DORMENTE (R27") and r27_estado_bloco(_A(), "bloco33").startswith("DORMENTE") and r27_estado_bloco(_A(), "bloco35") == "ATIVO")
    ml = mapa_do_que_vive_linhas_r27(type("C", (), {"res": {}, "args": _A()})())
    t("R27: mapa lista todos os blocos, bloco35, 27 rodadas e módulos transversais (filtro adaptativo, meta, BitLinear)",
      len(ml) >= len(R27_MAPA) + 10 and any("bloco35" in x for x in ml) and any("27 rodadas" in x for x in ml) and any("adaptativo" in x for x in ml) and any("NORMALIZADA" in x for x in ml))
    t("R27: ≥6 IMPLEMENTADA + ≥10 NOVA", sum(1 for s in MELHORIAS if "IMPLEMENTADA na R27" in s) >= 6 and sum(1 for s in MELHORIAS if "[NOVA R27]" in s) >= 10)
    t("R27: versão = R27 (ou posterior)", VERSAO == "R27" or (VERSAO.startswith("R") and int(VERSAO[1:]) >= 27))
    try:
        _nx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nexus_lexico.py")
        _nt = open(_nx, encoding="utf-8").read() if os.path.exists(_nx) else None
    except OSError:
        _nt = None
    t("R27: nexus_lexico.py >= 1.10.0 (se presente)", _nt is None or any(f'VERSAO = "{_v}"' in _nt for _v in ("1.10.0", "1.11.0", "1.12.0", "1.13.0", "1.14.0", "1.15.0", "1.16.0", "1.17.0", "1.18.0", "1.19.0", "1.20.0")))
    try:
        src_l = open(os.path.abspath(__file__), encoding="utf-8").read()
    except OSError:
        src_l = ""
    proib = ["".join(("def sand", "box_escape")), "".join(("def jail", "break_")), "".join(("class Back", "door")),
             "".join(("os.system('/bin/", "bash")), "".join(("subprocess.Popen(['ba", "sh'")), "".join(("socket.connect(('ev", "il"))]
    t("R27: sem rotinas de ataque/fuga no fonte", not any(p in src_l for p in proib))
    _kfrag = "Ab8RN6JaFsPqP" + "-kYGjWC7UTpzIRhIjm7" + "DGvHxwQJdR0X2KHhKg"
    t("R27: sem chave API hardcoded", _kfrag not in src_l)


def _autoteste_r26(t, lk, anteriores):
    corpo = PREREG_R26_CORPO.encode() if isinstance(PREREG_R26_CORPO, str) else PREREG_R26_CORPO
    t("R26: pré-registro confere", hashlib.sha256(corpo).hexdigest() == PREREG_R26_CORPO_SHA256)
    if ADENDO1_R26_CORPO_SHA256:
        _a1 = ADENDO1_R26_CORPO.encode() if isinstance(ADENDO1_R26_CORPO, str) else ADENDO1_R26_CORPO
        t("R26: Adendo 1 confere", hashlib.sha256(_a1).hexdigest() == ADENDO1_R26_CORPO_SHA256)
    S0 = r26_sementes(0)
    S25 = r25_sementes(0)
    S24 = r24_sementes(0)
    t("R26: 40 sementes de teste", len(S0["test"]) == 40)
    t("R26: DEV disjunto de TESTE", set(S0["dev"]).isdisjoint(set(S0["test"])))
    t("R26: sementes disjuntas das da R25 e R24", (set(S0["test"]) | set(S0["dev"])).isdisjoint(set(S25["test"]) | set(S25["dev"]) | set(S24["test"]) | set(S24["dev"])))
    t("R26: 11 hipóteses (4+4+3) em uma família Holm", len(R26_TODAS) == 11 and len(set(R26_TODAS)) == 11)
    # pilha travada
    t("R26: pilha padrão travada = RL ordinário + porta k=4, sem meta, sem extraordinário",
      R26_STACK_DEFAULT == {"rl": "ordinario", "extra": False, "gate_k": 4, "meta": None}
      and R26_CFG["ON"]["rl"] and R26_CFG["ON"]["gate"] and R26_CFG["ON"]["meta"] is None and not R26_CFG["ON"]["extra"] and R25_K_GATE == 4)
    t("R26: modos do filtro (ON=filtro+porta; LEVE=bruto+porta; OFF=bruto sem porta)",
      R26_CFG["ON"]["recompensa"] == "filtro" and R26_CFG["ON"]["gate"]
      and R26_CFG["LEVE"]["recompensa"] == "raw" and R26_CFG["LEVE"]["gate"]
      and R26_CFG["OFF"]["recompensa"] == "raw" and not R26_CFG["OFF"]["gate"]
      and all(not R26_CFG[m]["extra"] and R26_CFG[m]["meta"] is None for m in R26_MODOS))
    t("R26: meta_norm/meta_bruta partilham filtro+porta de ON (só muda o peso)",
      all(R26_CFG[m]["gate"] and R26_CFG[m]["recompensa"] == "filtro" and not R26_CFG[m]["extra"] for m in ("meta_bruta", "meta_norm"))
      and R26_CFG["meta_norm"]["meta"] == "norm" and R26_CFG["meta_bruta"]["meta"] == "bruta")
    # regra do interruptor
    t("R26: regra do modo — empate/ruído favorece ON", r26_escolher_modo({"ON": 0.50, "LEVE": 0.505, "OFF": 0.509}) == "ON")
    t("R26: regra do modo — LEVE só se > ON+0,01", r26_escolher_modo({"ON": 0.50, "LEVE": 0.52, "OFF": 0.51}) == "LEVE")
    t("R26: regra do modo — OFF supera o atual (LEVE) só por > 0,01", r26_escolher_modo({"ON": 0.50, "LEVE": 0.52, "OFF": 0.531}) == "OFF"
      and r26_escolher_modo({"ON": 0.50, "LEVE": 0.52, "OFF": 0.529}) == "LEVE")
    # desempenho sem mudar números
    _Mt = r24_markov2(r24_vocab(60, 1), 1, hard=True)
    t("R26/perf: medianas por linha em cache são bit-idênticas a np.median(M[a])",
      np.array_equal(_r26_med_rows(_Mt), np.array([float(np.median(_Mt[i])) for i in range(_Mt.shape[0])])))
    # tarefas
    z5 = r26_tarefa("Z5")
    seq = [1, 1]
    while len(seq) < z5.L:
        seq.append((seq[-1] + seq[-2]) % z5.V)
    t("R26: Z5 (mod 5) sequência da regra tem r_clean=1", z5.V == 5 and abs(z5.r_clean(seq) - 1.0) < 1e-12 and z5.nome == "Z5")
    z7 = r26_tarefa("Z7")
    t("R26: Z7 mantém os parâmetros da R25 (V=7, L=12, lote 8, P=200)", (z7.V, z7.L, z7.batch, z7.P) == (7, 12, 8, 200))
    h80, h60 = r26_tarefa("H80"), r26_tarefa("H60")
    t("R26: H80 = HARD da R25 (mesma matriz de transição)", h80.V == 80 and h80.L == 40 and np.allclose(h80.M, R25Hard().M))
    t("R26: H60 é outra tarefa (V=60, L=32, matriz distinta)", h60.V == 60 and h60.L == 32 and h60.M.shape == (60, 60) and abs(float(h60.M.sum(axis=1).mean()) - 1.0) < 1e-9)
    t("R26: famílias das tarefas (Z7,Z5 | H80,H60)", [R26_FAMILIA[x] for x in R26_TAREFAS] == ["Z", "Z", "H", "H"])
    ids = h60.sample_uniform(r25_rng(98300, 1, 1))
    lh = h60.laudo(ids, 98300, 1)
    t("R26: H60 laudo e r_clean finitos", np.isfinite(h60.r_clean(ids)) and 0.0 <= lh["score_laudo"] <= 1.0 and len(ids) == 32)
    rho = r26_alinhamento("Z5", [98300], n=40)
    t("R26: alinhamento (Spearman) em [−1,1] e determinístico", -1.0 <= rho <= 1.0 and rho == r26_alinhamento("Z5", [98300], n=40))
    # ORÇAMENTO IGUAL com meta_norm
    cont = {"n": 0}

    class _Cnt(R25Sym):
        def update(self, pol, seqs, advs, lr, extra, pesos):
            cont["n"] += 1
            return super().update(pol, seqs, advs, lr, extra, pesos)
    tz = _Cnt({"V": 5, "L": 8, "B": 2, "P": 21, "tau_y": 0.5})
    tz.nome = "Z5"
    r25_treinar(tz, R26_CFG["ON"], 98301, 1.0)
    n_on = cont["n"]; cont["n"] = 0
    r25_treinar(tz, R26_CFG["meta_norm"], 98301, 1.0)
    n_mn = cont["n"]; cont["n"] = 0
    r25_treinar(tz, R26_CFG["OFF"], 98301, 1.0)
    n_of = cont["n"]
    t("R26: ORÇAMENTO IGUAL (ON, meta_norm, OFF fazem o mesmo nº de atualizações)", n_on == n_mn == n_of == 21)
    a = r25_avaliar(tz, R26_CFG["ON"], r25_treinar(tz, R26_CFG["ON"], 98302, 1.0), 98302, "Z5|ON")
    b = r25_avaliar(tz, R26_CFG["ON"], r25_treinar(tz, R26_CFG["ON"], 98302, 1.0), 98302, "Z5|ON")
    t("R26: treino+avaliação determinísticos e finitos", a["r_clean"] == b["r_clean"] and np.isfinite(a["r_clean"]))
    # agregação por semente (pooled) e hipóteses
    SCt = {tn: {br: [0.5, 0.6, 0.55] for br in R26_BRACOS_TREINO + ("aleat",)} for tn in R26_TAREFAS}
    D = r26_hipoteses_AB(SCt, {tn: "ON" for tn in R26_TAREFAS}, "ON")
    t("R26: adaptativo=ON em todas ⇒ S1=0 e S3=0 exatamente (nula por construção)", np.all(D["S1"] == 0.0) and np.all(D["S3"] == 0.0))
    SCt["Z7"]["OFF"] = [0.2, 0.2, 0.2]
    D2 = r26_hipoteses_AB(SCt, {tn: "ON" for tn in R26_TAREFAS}, "ON")
    t("R26: S2 pooled = média das 4 tarefas (só Z7 difere ⇒ Δ≈0,075..0,10)", np.all(D2["S2"] > 0.07) and np.all(D2["S2"] < 0.11))
    t("R26: contrastes M1/M2 por família (Z e H)", set(["M1_Z", "M1_H", "M2_Z", "M2_H"]) <= set(D.keys()))
    pk = r25_pack(np.zeros(12), seed=1)
    t("R26: efeito exatamente 0 ⇒ p=1 e d_z=0", pk["p"] == 1.0 and pk["dz"] == 0.0)
    # vereditos
    vm = lambda a_, b_: r26_veredito_meta({"M1_Z": a_, "M1_H": b_, "M2_Z": "nula", "M2_H": "nula"})
    t("R26: veredito meta (VIVE / VIVE EM 1 / DECORATIVA / NOCIVA)",
      "NOCIVA" in vm("refutada", "nula") and "VIVE (" in vm("confirmada", "confirmada") and "VIVE EM 1" in vm("confirmada", "nula") and "DECORATIVA" in vm("nula", "nula"))
    t("R26: meta só entra na pilha padrão se VIVE", "OPCIONAL" in vm("confirmada", "nula") and "compor a pilha padrão" in vm("confirmada", "confirmada"))
    md = {t_: "ON" for t_ in R26_TAREFAS}
    t("R26: regra de adoção (S3 confirmada ⇒ adaptativo; senão global fixo)",
      "ADAPTATIVO ADOTADO" in r26_regra_adocao({"S3": "confirmada"}, md, "ON") and "global fixo" in r26_regra_adocao({"S3": "nula"}, md, "OFF"))
    mh = {"acc_dense": 0.88, "acc_bit": 0.85}
    t("R26: regra BitLinear — congela se C1 não confirmada; inválida se C2 não; ativo/gap/inconclusivo",
      "CONGELADO" in r26_regra_hw({"C1": "nula", "C2": "confirmada", "C3": "nula"}, mh)
      and "INVÁLIDA" in r26_regra_hw({"C1": "confirmada", "C2": "nula", "C3": "nula"}, mh)
      and "não-inferior" in r26_regra_hw({"C1": "confirmada", "C2": "confirmada", "C3": "confirmada"}, mh)
      and "GAP" in r26_regra_hw({"C1": "confirmada", "C2": "confirmada", "C3": "refutada"}, mh)
      and "INCONCLUSIVO" in r26_regra_hw({"C1": "confirmada", "C2": "confirmada", "C3": "nula"}, mh))
    t("R26: flag de teto (denso > 0,95) impede sustentar não-inferior na difícil",
      "TETO" in r26_regra_hw({"C1": "confirmada", "C2": "confirmada", "C3": "confirmada"}, {"acc_dense": 0.99, "acc_bit": 0.98})
      and "ATIVO (proxy" not in r26_regra_hw({"C1": "confirmada", "C2": "confirmada", "C3": "confirmada"}, {"acc_dense": 0.99, "acc_bit": 0.98}))
    # espirais difíceis e escolha do nível
    X1, y1 = r26_espirais(98303, 100, 2.0, 0.05)
    X2, y2 = r26_espirais(98303, 100, 2.0, 0.05)
    X3, _ = r26_espirais(98303, 100, 2.0, 0.0)
    t("R26: espirais difíceis: formato, rótulos balanceados, determinístico, ruído altera os pontos",
      X1.shape == (100, 2) and abs(float(y1.mean()) - 0.5) < 1e-9 and np.array_equal(X1, X2) and not np.allclose(X1, X3))
    t("R26: escolha do nível — primeiro com denso em [0,70; 0,93]", r26_escolher_nivel([(1, 0.9, 0.97), (2, 0.8, 0.88), (3, 0.7, 0.8)]) == (2, True))
    t("R26: escolha do nível — sem faixa ⇒ o mais próximo de 0,85", r26_escolher_nivel([(1, 0.9, 0.99), (2, 0.5, 0.60), (3, 0.5, 0.97)]) == (3, False))
    nv_t = {"n": 9, "voltas": 1.5, "sx": 0.04, "ntr": 60}
    rg_t = {"g": 2, "H": 8, "passos": 20, "fourier": 2.0}
    hd = r26_mlp_treinar("dense_fp", 98304, nv_t, rg_t)
    hb = r26_mlp_treinar("bit_v2", 98304, nv_t, rg_t)
    t("R26: BitLinear/denso difícil: acc em [0,1], energia ternária < densa, determinístico",
      0.0 <= hd["acc"] <= 1.0 and 0.0 <= hb["acc"] <= 1.0 and hb["energia"] < hd["energia"] and hb["acc"] == r26_mlp_treinar("bit_v2", 98304, nv_t, rg_t)["acc"])
    t("R26: pesos ternários {−γ,0,+γ} também na tarefa difícil (zeros ≥ 0)", 0.0 <= hb["frac_zero"] <= 1.0)
    # dormência R26
    class _A:
        seed = 42; emb = "semantico"; rapido = False; offline = True; reativar_dormentes = False
    cg = r26_congelado()
    t("R26: congelado BLOCOS 21, 22 e 33 decodifica (sha256 confere) e traz r14_rl, r14_rep e r25",
      cg is not None and all(b_ in cg for b_ in ("bloco21", "bloco22", "bloco33")) and "r14_rl" in cg["bloco21"]["res"] and "r14_rep" in cg["bloco22"]["res"] and "r25" in cg["bloco33"]["res"])
    t("R26: dormência ativa no padrão (blocos 21, 22 e 33) e desligada pelas flags de depuração R14_DEV/R25_DEV",
      all(r26_dormente_ativo(_A(), b_) for b_ in ("bloco21", "bloco22", "bloco33")) and not r26_dormente_ativo(_A(), "bloco99"))
    _env0 = os.environ.get("R14_DEV")
    os.environ["R14_DEV"] = "1"
    _off_flag = not any(r26_dormente_ativo(_A(), b_) for b_ in ("bloco21", "bloco22", "bloco33"))
    if _env0 is None:
        os.environ.pop("R14_DEV", None)
    else:
        os.environ["R14_DEV"] = _env0
    t("R26: flag R14_DEV desliga a dormência (depuração roda ao vivo)", _off_flag)
    _A.reativar_dormentes = True
    t("R26: dormência desliga com --reativar-dormentes", not r26_dormente_ativo(_A(), "bloco33"))
    _A.reativar_dormentes = False
    t("R26: estado do mapa deriva da dormência", r26_estado_bloco(_A(), "bloco33").startswith("DORMENTE") and r26_estado_bloco(_A(), "bloco34") == "ATIVO"
      and r26_estado_bloco(_A(), "bloco32").startswith("DORMENTE"))
    ml = mapa_do_que_vive_linhas_r26(type("C", (), {"res": {}, "args": _A()})())
    t("R26: mapa lista todos os blocos, bloco34, 26 rodadas e módulos transversais",
      len(ml) >= len(R26_MAPA) + 10 and any("bloco34" in x for x in ml) and any("26 rodadas" in x for x in ml) and any("NORMALIZADA" in x for x in ml))
    t("R26: ≥6 IMPLEMENTADA + ≥10 NOVA", sum(1 for s in MELHORIAS if "IMPLEMENTADA na R26" in s) >= 6 and sum(1 for s in MELHORIAS if "[NOVA R26]" in s) >= 10)
    t("R26: versão = R26 (ou posterior)", VERSAO == "R26" or (VERSAO.startswith("R") and int(VERSAO[1:]) >= 26))
    try:
        _nx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nexus_lexico.py")
        _nt = open(_nx, encoding="utf-8").read() if os.path.exists(_nx) else None
    except OSError:
        _nt = None
    t("R26: nexus_lexico.py >= 1.9.0 (se presente)", _nt is None or any(f'VERSAO = "{_v}"' in _nt for _v in ("1.9.0", "1.10.0", "1.11.0", "1.12.0", "1.13.0", "1.14.0", "1.15.0", "1.16.0", "1.17.0", "1.18.0", "1.19.0", "1.20.0")))
    try:
        src_l = open(os.path.abspath(__file__), encoding="utf-8").read()
    except OSError:
        src_l = ""
    proib = ["".join(("def sand", "box_escape")), "".join(("def jail", "break_")), "".join(("class Back", "door")),
             "".join(("os.system('/bin/", "bash")), "".join(("subprocess.Popen(['ba", "sh'")), "".join(("socket.connect(('ev", "il"))]
    t("R26: sem rotinas de ataque/fuga no fonte", not any(p in src_l for p in proib))
    _kfrag = "Ab8RN6JaFsPqP" + "-kYGjWC7UTpzIRhIjm7" + "DGvHxwQJdR0X2KHhKg"
    t("R26: sem chave API hardcoded", _kfrag not in src_l)


def _autoteste_r25(t, lk, anteriores):
    corpo = PREREG_R25_CORPO.encode() if isinstance(PREREG_R25_CORPO, str) else PREREG_R25_CORPO
    t("R25: pré-registro confere", hashlib.sha256(corpo).hexdigest() == PREREG_R25_CORPO_SHA256)
    if ADENDO1_R25_CORPO_SHA256:
        _a1 = ADENDO1_R25_CORPO.encode() if isinstance(ADENDO1_R25_CORPO, str) else ADENDO1_R25_CORPO
        t("R25: Adendo 1 confere", hashlib.sha256(_a1).hexdigest() == ADENDO1_R25_CORPO_SHA256)
    S0 = r25_sementes(0)
    S24 = r24_sementes(0)
    t("R25: 40 sementes de teste", len(S0["test"]) == 40)
    t("R25: DEV disjunto de TESTE", set(S0["dev"]).isdisjoint(set(S0["test"])))
    t("R25: sementes disjuntas das da R24", (set(S0["test"]) | set(S0["dev"])).isdisjoint(set(S24["test"]) | set(S24["dev"])))
    t("R25: 18 hipóteses (7+7+4) em uma família Holm global", len(R25_TODAS) == 18 and len(set(R25_TODAS)) == 18)
    t("R25: vantagem extraordinária pune mais o erro", r25_adv(-1.0, True) < r25_adv(-1.0, False) and r25_adv(1.0, True) < r25_adv(1.0, False))
    # tarefa simbólica: sequência perfeita tem r_clean = 1; aleatória fica no teto baixo
    sy = R25Sym()
    seq = [1, 1]
    while len(seq) < sy.L:
        seq.append((seq[-1] + seq[-2]) % sy.V)
    t("R25: Z7 sequência da regra tem r_clean=1", abs(sy.r_clean(seq) - 1.0) < 1e-12)
    t("R25: Z7 constante sem diversidade < regra", sy.r_clean([0] * sy.L) < sy.r_clean(seq))
    lz = sy.laudo(seq, 98200, 1)
    t("R25: Z7 laudo da sequência perfeita passa a tela", bool(lz["passa_tela"]) and 0.0 <= lz["score_laudo"] <= 1.0)
    # ORÇAMENTO IGUAL: mesma quantidade de atualizações de política com e sem meta
    cont = {"n": 0}

    class _Cnt(R25Sym):
        def update(self, pol, seqs, advs, lr, extra, pesos):
            cont["n"] += 1
            return super().update(pol, seqs, advs, lr, extra, pesos)
    tz = _Cnt({"V": 5, "L": 8, "B": 2, "P": 21, "tau_y": 0.5})
    r25_treinar(tz, R25_CFG["sem_meta"], 98201, 1.0)
    n_sem = cont["n"]; cont["n"] = 0
    r25_treinar(tz, R25_CFG["stack_full"], 98201, 1.0)
    t("R25: ORÇAMENTO IGUAL (mesmo nº de atualizações com e sem meta)", n_sem == cont["n"] == 21)
    tz2 = R25Sym({"V": 5, "L": 8, "B": 2, "P": 12, "tau_y": 0.5})
    a = r25_avaliar(tz2, R25_CFG["stack_full"], r25_treinar(tz2, R25_CFG["stack_full"], 98202, 1.0), 98202, "stack_full")
    b = r25_avaliar(tz2, R25_CFG["stack_full"], r25_treinar(tz2, R25_CFG["stack_full"], 98202, 1.0), 98202, "stack_full")
    t("R25: Z7 treino+avaliação determinísticos e finitos", a["r_clean"] == b["r_clean"] and np.isfinite(a["r_clean"]))
    th = R25Hard()
    th.P = 12
    ev = r25_avaliar(th, R25_CFG["stack_full"], r25_treinar(th, R25_CFG["stack_full"], 98203, 0.1), 98203, "stack_full")
    t("R25: HARD stack_full finito, r_clean e keep em faixa", np.isfinite(ev["r_clean"]) and 0.0 <= ev["keep_rate"] <= 1.0)
    ev_a = r25_avaliar(th, R25_CFG["aleat"], {"pol": None}, 98203, "aleat")
    t("R25: HARD aleat determinístico", ev_a["r_clean"] == r25_avaliar(th, R25_CFG["aleat"], {"pol": None}, 98203, "aleat")["r_clean"])
    # estatística
    pk = r25_pack(np.full(12, 0.3) + np.linspace(-0.01, 0.01, 12), seed=1)
    t("R25: pack detecta efeito claro (p<0,01) e d_z>5", pk["p"] < 0.01 and pk["dz"] > 5)
    t("R25: pack sem efeito → p alto", r25_pack(np.array([0.1, -0.1] * 6), seed=1)["p"] > 0.5)
    t("R25: não-inferioridade desloca o teste (d=0 vs margem)", r25_pack(np.zeros(12) - 0.01, seed=1, deslocar=0.05)["p"] < 0.01)
    t("R25: status: refutada quando sentido contrário", r25_status(-0.1, 0.01) == "refutada" and r25_status(0.1, 0.01) == "confirmada" and r25_status(0.1, 0.2) == "nula")
    vp = r25_veredito_pecas({"A2": "confirmada", "Y2": "confirmada", "A3": "confirmada", "Y3": "refutada", "A4": "nula", "Y4": "nula",
                             "A5": "confirmada", "Y5": "nula", "A6": "nula", "Y6": "nula", "A7": "nula", "Y7": "confirmada"})
    t("R25: veredito por peça (VIVE / NOCIVA / DECORATIVA / VIVE EM 1)",
      vp["RL"] == "VIVE" and vp["meta-recompensa"] == "NOCIVA" and vp["calibração"] == "DECORATIVA" and vp["filtro (recompensa+porta)"] == "VIVE EM 1")
    # BitLinear v2
    Wt = np.random.default_rng(0).normal(size=(6, 5))
    q = r25_q_ternario(Wt)
    t("R25: pesos ternários = {−γ,0,+γ} (≤3 valores distintos)", len(np.unique(np.round(q, 12))) <= 3)
    rg = {"g": 1, "H": 16, "passos": 300, "fourier": 0.0}
    hd = r25_mlp_treinar("dense_fp", 98204, rg)
    hb = r25_mlp_treinar("bit_v2", 98204, rg)
    t("R25: dense_fp (backprop completo) acima do acaso nas espirais (acc>0,8)", hd["acc"] > 0.8)
    t("R25: bit_v2 (STE) acima do acaso nas espirais (acc>0,7)", hb["acc"] > 0.7)
    t("R25: energia-proxy ternária < densa", hb["energia"] < hd["energia"])
    t("R25: regra de congelamento", r25_regra_congelamento({"B1": "confirmada", "B2": "confirmada", "B3": "confirmada"}).startswith("BITLINEAR v2")
      and r25_regra_congelamento({"B1": "confirmada", "B2": "nula", "B3": "confirmada"}).startswith("TETO"))
    # dormência R25
    class _A:
        seed = 42; emb = "semantico"; rapido = False; offline = True; reativar_dormentes = False
    cg = r25_congelado()
    t("R25: congelado BLOCOS 31–32 decodifica (sha256 confere)", cg is not None and "bloco31" in cg and "bloco32" in cg and "r24" in cg["bloco32"]["res"])
    t("R25: dormência ativa no padrão (blocos 31 e 32)", r25_dormente_ativo(_A(), "bloco31") and r25_dormente_ativo(_A(), "bloco32"))
    _A.reativar_dormentes = True
    t("R25: dormência desliga com --reativar-dormentes", not r25_dormente_ativo(_A(), "bloco32"))
    _A.reativar_dormentes = False
    t("R25: estado do mapa deriva da dormência", r25_estado_bloco(_A(), "bloco32").startswith("DORMENTE") and r25_estado_bloco(_A(), "bloco33") == "ATIVO")
    ml = mapa_do_que_vive_linhas(type("C", (), {"res": {}, "args": _A()})())
    t("R25: mapa do que vive lista todos os blocos e módulos transversais", len(ml) >= len(R25_MAPA) + 10 and any("bloco33" in x for x in ml) and any("BitLinear" in x for x in ml))
    t("R25: ≥6 IMPLEMENTADA + ≥10 NOVA", sum(1 for s in MELHORIAS if "IMPLEMENTADA na R25" in s) >= 6 and sum(1 for s in MELHORIAS if "[NOVA R25]" in s) >= 10)
    t("R25: versão = R25 (ou posterior)", VERSAO == "R25" or (VERSAO.startswith("R") and int(VERSAO[1:]) >= 25))
    # nexus 1.8.0 (leitura estática do arquivo companheiro)
    try:
        _nx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nexus_lexico.py")
        _nt = open(_nx, encoding="utf-8").read() if os.path.exists(_nx) else None
    except OSError:
        _nt = None
    t("R25: nexus_lexico.py >= 1.8.0 (se presente)", _nt is None or any(f'VERSAO = "{_v}"' in _nt for _v in ("1.8.0", "1.9.0", "1.10.0", "1.11.0", "1.12.0", "1.13.0", "1.14.0", "1.15.0", "1.16.0", "1.17.0", "1.18.0", "1.19.0", "1.20.0")))
    try:
        src_l = open(os.path.abspath(__file__), encoding="utf-8").read()
    except OSError:
        src_l = ""
    proib = ["".join(("def sand", "box_escape")), "".join(("def jail", "break_")), "".join(("class Back", "door")),
             "".join(("os.system('/bin/", "bash")), "".join(("subprocess.Popen(['ba", "sh'")), "".join(("socket.connect(('ev", "il"))]
    t("R25: sem rotinas de ataque/fuga no fonte", not any(p in src_l for p in proib))
    _kfrag = "Ab8RN6JaFsPqP" + "-kYGjWC7UTpzIRhIjm7" + "DGvHxwQJdR0X2KHhKg"
    t("R25: sem chave API hardcoded", _kfrag not in src_l)



def _autoteste_r24(t, lk, anteriores):
    corpo = PREREG_R24_CORPO.encode() if isinstance(PREREG_R24_CORPO, str) else PREREG_R24_CORPO
    t("R24: pré-registro confere",
      hashlib.sha256(corpo).hexdigest() == PREREG_R24_CORPO_SHA256)
    hw = ADENDO_HW_R24_CORPO.encode() if isinstance(ADENDO_HW_R24_CORPO, str) else ADENDO_HW_R24_CORPO
    t("R24: Adendo HW confere", hashlib.sha256(hw).hexdigest() == ADENDO_HW_R24_CORPO_SHA256)
    if ADENDO1_R24_CORPO_SHA256:
        _a1 = ADENDO1_R24_CORPO.encode() if isinstance(ADENDO1_R24_CORPO, str) else ADENDO1_R24_CORPO
        t("R24: Adendo 1 confere", hashlib.sha256(_a1).hexdigest() == ADENDO1_R24_CORPO_SHA256)
    S0 = r24_sementes(0)
    t("R24: 40 sementes teste", len(S0["test"]) == 40)
    t("R24: DEV disjunto de TESTE", set(S0["dev"]).isdisjoint(set(S0["test"])))
    t("R24: sementes disjuntas de R23", set(S0["test"]).isdisjoint(set(r23_sementes(0)["S_test"])))
    ev = r24_eval_texto("aleatorio_h", 37210, {"passos": 40, "lr": 0.1}, n_textos=3)
    t("R24: eval aleatorio_h finito", np.isfinite(ev["r_clean"]))
    ev2 = r24_eval_texto("rl_ordinario_h", 37210, {"passos": 30, "lr": 0.1}, n_textos=3)
    t("R24: eval rl_ordinario_h finito", np.isfinite(ev2["r_clean"]))
