    # anti ataque: padrões montados em runtime (não se auto-flagrar)
    try:
        src_l = open(os.path.abspath(__file__), encoding="utf-8").read()
    except OSError:
        src_l = ""
    proib = ["".join(("def sand", "box_escape")), "".join(("def jail", "break_")), "".join(("class Back", "door")),
             "".join(("os.system('/bin/", "bash")), "".join(("subprocess.Popen(['ba", "sh'")), "".join(("socket.connect(('ev", "il"))]
