def registro_r4(ctx: Contexto) -> list:
    """Linhas do registro da R4, construídas a partir dos resultados desta execução (nada digitado à mão)."""
    r = ctx.res
    out = []
    g = r.get("r4_gold")
    if g:
        for (k, (desc, (est, lo, hi, p))), pa_ in zip(g["G"].items(), g["padj"]):
            ev = f"estim.={est:+.3f} IC[{lo:+.3f},{hi:+.3f}] p Holm={pa_:.3f}"
            out.append(("R4", f"R4-{k}", "CONF", desc + " (gabarito WordNet)", ev, "confirmada" if g["status"][k] == "CONFIRMADA" else "nula"))
    s = r.get("r4_sched")
    if s:
        nomes = {"S1": "so_agenda − baseline ≠ 0", "S2": "delirio − baseline ≠ 0", "S3": "so_agenda − delirio ≠ 0"}
        for (k, (m, lo, hi, p)), pa_ in zip(s["S"].items(), s["holm"]):
            st = s["status"][k]
            out.append(("R4", f"R4-{k}", "CONF", f"{nomes[k]} (acc de teste, {s['n']} sementes novas 800+)", f"Δ={100 * m:+.2f} pp IC[{100 * lo:+.2f},{100 * hi:+.2f}] p Holm={pa_:.3f}",
                        "confirmada" if st.startswith("CONFIRMADA") else ("refutada" if st.startswith("REFUTADA") else "nula")))
        lo, hi, eq = s["equiv"]
        out.append(("R4", "R4-S4", "CONF", "so_agenda e delirio EQUIVALENTES (margem ±1 pp, TOST por IC90%)", f"IC90%[{100 * lo:+.2f},{100 * hi:+.2f}] pp", "confirmada (equivalência)" if eq else "nula (equivalência não demonstrada)"))
    f = r.get("r4_replay_fiel")
    if f:
        out.append(("R4", "R4-C1", "DESC", "replay de sessão gravada reproduz o rastro original (determinismo/integridade do log)", f"{f[0]}/{f[1]} políticas idênticas; {f[2]} consultas fora do log; {f[3]} consultas gravadas",
                    "confirmada" if f[0] == f[1] and f[2] == 0 else "refutada"))
    return out


