R19_DORMENTES = {
    "bloco23": "BLOCO 23 (R15: replicação larga)",
    "bloco24": "BLOCO 24 (R16: Raphael/invenção/delírio/debate)",
    "bloco25": "BLOCO 25 (R17: Raphael/PN/delírio/GAN)",
    "bloco26": "BLOCO 26 (R18: PN plantado/delírio 2est/GAN/CL-RL/Mega/S/A)",
}
R19_ENV_VIVO = (
    "R15_DEV", "R15_SO_NOVOS", "R16_DEV", "R16_SO_NOVOS",
    "R17_DEV", "R17_SO_NOVOS", "R18_DEV", "R18_SO_NOVOS",
    "R19_DEV", "R19_SO_NOVOS",
)
# Filled by apply script after capture
R19_CONGELADO_ORIGEM = "PENDING"
R19_CONGELADO_SHA256 = "PENDING"
R19_CONGELADO_B64 = ""

_R19_CONG_CACHE = {"v": None}


def r19_congelado():
    if _R19_CONG_CACHE["v"] is not None:
        return _R19_CONG_CACHE["v"]
    if not R19_CONGELADO_B64 or R19_CONGELADO_SHA256 == "PENDING":
        _R19_CONG_CACHE["v"] = None
        return None
    try:
        raw = zlib.decompress(base64.b64decode("".join(R19_CONGELADO_B64) if isinstance(R19_CONGELADO_B64, (list, tuple)) else R19_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R19_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R19_CONG_CACHE["v"] = v
    return v


def r19_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if any(os.environ.get(v) for v in R19_ENV_VIVO):
        return False
    cg = r19_congelado()
    return cg is not None and nome in cg


def _dormente19(nome, vivo):
    def w(ctx):
        rot = R19_DORMENTES[nome]
        est = ctx.res.setdefault("r19_dorm", {})
        if r19_dormente_ativo(ctx.args, nome):
            cg = r19_congelado()[nome]
            ctx.rep.log(
                f"[R19 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R18 inalterado "
                f"(--offline --jobs 8, semente 42; sha256 {R19_CONGELADO_SHA256[:12]}… CONFERE; "
                f"origem {R19_CONGELADO_ORIGEM}). Para recalcular: --reativar-dormentes."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        o0 = {k: len(v) for k, v in ctx.obs.reg.items()}
        vivo(ctx)
        cg = r19_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + (
                "CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)"
            )
            ctx.rep.log(f"[R19 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w

