def r19_triade_score(kind: str, seed: int, hp: dict = None, n: int = 40, dim: int = 4) -> float:
    """Score = mean cos(y,x). kind in triade|so_A|so_B|media."""
    rng = np.random.default_rng([r19_crc("T|" + kind), int(seed), 19])
    # init two MLPs and a tiny GAN-meta masker
    def init(d_in, d_h, d_out, s):
        r = np.random.default_rng(s)
        return (
            r.normal(0, 0.4, size=(d_h, d_in)),
            np.zeros(d_h),
            r.normal(0, 0.4, size=(d_out, d_h)),
            np.zeros(d_out),
        )
    A = init(dim, 6, dim, [seed, 1])
    B = init(dim, 6, dim, [seed, 2])
    G = init(dim, 4, dim, [seed, 3])  # mask logits

    def fwd(x, W1, b1, W2, b2):
        h = np.tanh(W1 @ x + b1)
        return W2 @ h + b2

    acc = 0.0
    for i in range(n):
        x = rng.normal(0, 1, size=dim)
        x = x / (np.linalg.norm(x) + 1e-12)
        yA = fwd(x, *A)
        yB = fwd(x, *B)
        if kind == "so_A":
            y = yA
        elif kind == "so_B":
            y = yB
        elif kind == "media":
            y = 0.5 * yA + 0.5 * yB
        else:  # triade
            z = rng.normal(0, 1, size=dim)
            logits = fwd(z, *G)
            mask = 1.0 / (1.0 + np.exp(-logits))
            y = mask * yA + (1.0 - mask) * yB
        y = y / (np.linalg.norm(y) + 1e-12)
        acc += float(np.dot(y, x))
    return float(acc / n)


def r19_eval_t(metodo: str, seed: int, hp: dict = None) -> float:
    return r19_triade_score(metodo, seed, hp)




def r19_desloc() -> int:
    return 10000 if os.environ.get("R19_DEV") else 0


def r19_crc(rot: str) -> int:
    return zlib.crc32(f"R19|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r19_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


def r19_sementes(desloc=0):
    d = int(desloc)
    return {
        "F_dev": [s + d for s in R19_SEEDS_F_DEV],
        "F_test": [s + d for s in R19_SEEDS_F_TEST],
        "E_dev": [s + d for s in R19_SEEDS_E_DEV],
        "E_test": [s + d for s in R19_SEEDS_E_TEST],
        "W_dev": [s + d for s in R19_SEEDS_W_DEV],
        "W_test": [s + d for s in R19_SEEDS_W_TEST],
        "T_dev": [s + d for s in R19_SEEDS_T_DEV],
        "T_test": [s + d for s in R19_SEEDS_T_TEST],
    }


# ---------- F: map conditions → r18_laco_delirio cond names ----------
def r19_f_map_cond(cond: str) -> str:
    return {
        "ambos": "delirio_2est",
        "filtro_so": "sobrio_2est",
        "delirio_so": "delirio_sem",
        "nenhum": "delirio_sem",  # sobrio + proxy: use sobrio T via hp override
    }[cond]


def r19_eval_f(cond: str, seed: int, hp: dict, nprop: int = R19_NPROP_F) -> float:
    """Youden for F conditions. 'nenhum' = sóbrio T + proxy>0.5 (sem laudo)."""
    hp = dict(hp)
    if cond == "nenhum":
        # force low T and delirio_sem-style accept
        hp = {**hp, "T_hi": hp.get("T_lo", 0.3), "T_lo": hp.get("T_lo", 0.3)}
        # Use a dedicated path: sobrio proposals + proxy filter only
        return r19_laco_f_nenhum(seed, hp, nprop)
    # Map named F conditions onto R18 laço labels (hygiene: r19_f_map_cond referenced).
    return float(r18_laco_delirio(r19_f_map_cond(cond), seed, hp, nprop=nprop)["Youden"])


def r19_laco_f_nenhum(seed: int, hp: dict, nprop: int) -> float:
    """Sóbrio (T baixa) + aceitar se proxy>0.5 (sem laudo 2-estágios)."""
    rng = r18_rng(seed, r18_crc("nenhum"), 5)
    T = float(hp.get("T_lo", 0.3))
    props = []
    for i in range(R18_N_UTEIS):
        tag = R17_GRAM_UTEIS[i % len(R17_GRAM_UTEIS)]
        props.append(r17_propor_tag(rng, tag, T))
    for i in range(R18_N_INUTEIS):
        tag = R17_GRAM_INUTEIS[i % len(R17_GRAM_INUTEIS)]
        props.append(r17_propor_tag(rng, tag, T))
    for _ in range(max(0, nprop - R18_N_UTEIS - R18_N_INUTEIS)):
        props.append(r17_propor_livre(rng, T))
    tp = fp = n_u = n_i = 0
    for i, comp in enumerate(props):
        proxy = r18_proxy_rapido(comp)
        if proxy > 0.5:
            r = r18_avaliar_proposta_scores(comp, seed + 100 + i)
            mantem = r["delta"] > 0.0
        else:
            mantem = False
        if comp.get("util_ref"):
            n_u += 1
            if mantem:
                tp += 1
        elif comp.get("plantada") and not comp.get("util_ref"):
            n_i += 1
            if mantem:
                fp += 1
    TPR = tp / max(n_u, 1)
    FPR = fp / max(n_i, 1)
    return float(TPR - FPR)


# ---------- E: drifting bandit ----------
def r19_bandit_means(phase: int, K: int = R19_K_BANDIT):
    base = np.linspace(0.15, 0.85, K)
    return np.roll(base, phase % K)


def r19_eval_e(metodo: str, seed: int, hp: dict, H: int = R19_H_BANDIT, K: int = R19_K_BANDIT) -> float:
    """Return −average regret (higher better)."""
    rng = r19_rng(seed, r19_crc(metodo), 7)
    alpha = float(hp.get("alpha", 0.2))
    eps = float(hp.get("eps", 0.1))
    Q = np.zeros(K)
    N = np.zeros(K)
    regret = 0.0
    drift = int(hp.get("drift", 50))
    for t in range(H):
        phase = t // drift
        means = r19_bandit_means(phase, K)
        opt = float(means.max())
        if metodo == "ordinario":
            a = int(np.argmax(Q)) if (t > 0 and rng.random() > eps) else int(rng.integers(0, K))
            r = 1.0 if rng.random() < means[a] else 0.0
            if r >= 0.5:
                Q[a] += alpha * (r - Q[a])
            else:
                Q[a] += (0.1 * alpha) * (r - Q[a])
            N[a] += 1
        elif metodo == "extraordinario":
            a = int(np.argmax(Q)) if (t > 0 and rng.random() > eps) else int(rng.integers(0, K))
            r = 1.0 if rng.random() < means[a] else 0.0
            err = abs(r - Q[a])
            a_use = (3.0 * alpha) if r < 0.5 else alpha
            Q[a] += a_use * err * (r - Q[a]) if err > 1e-12 else a_use * (r - Q[a])
            N[a] += 1
        elif metodo == "greedy_eps":
            a = int(np.argmax(Q)) if (t > 0 and rng.random() > eps) else int(rng.integers(0, K))
            r = 1.0 if rng.random() < means[a] else 0.0
            N[a] += 1
            Q[a] += (r - Q[a]) / N[a]
        elif metodo == "ucb1":
            if t < K:
                a = t
            else:
                bon = np.sqrt(2.0 * np.log(t + 1) / np.maximum(N, 1))
                a = int(np.argmax(Q + bon))
            r = 1.0 if rng.random() < means[a] else 0.0
            N[a] += 1
            Q[a] += (r - Q[a]) / N[a]
        else:
            raise ValueError(metodo)
        regret += opt - means[a]
    return float(-regret / H)


def r19_ajustar_e(metodo: str, seeds_dev, n_sort: int = 6) -> dict:
    best, bh = -1e18, {"alpha": 0.2, "eps": 0.1, "drift": 50}
    rng = r19_rng(r19_crc("Eadj|" + metodo), 19, 0)
    for i in range(n_sort):
        hp = {
            "alpha": float(rng.choice([0.05, 0.1, 0.2, 0.4])),
            "eps": float(rng.choice([0.05, 0.1, 0.2])),
            "drift": 50,
        }
        if metodo == "ucb1":
            hp = {"alpha": 0.0, "eps": 0.0, "drift": 50}
        sc = float(np.mean([r19_eval_e(metodo, s, hp) for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


# ---------- W: last open-channel attempt ----------
def r19_lexico_lake():
    """Closed lexicon from CORPO_PT/EN-ish tokens already in module."""
    words = []
    for pair in LEXICO_PARES if "LEXICO_PARES" in dir() else []:
        if isinstance(pair, (tuple, list)) and len(pair) >= 1:
            words.append(str(pair[0]).lower())
    # fallback mini lex
    if len(words) < 20:
        words = [
            "casa", "mesa", "porta", "janela", "água", "fogo", "terra", "vento",
            "livro", "papel", "caneta", "escola", "amigo", "tempo", "noite", "dia",
            "flor", "pedra", "rio", "mar", "sol", "lua", "estrela", "nuvem",
            "cão", "gato", "pássaro", "peixe", "árvore", "folha", "raiz", "fruta",
        ]
    words = [w.strip().lower() for w in words if w and w.isalpha() and 4 <= len(w.strip()) <= 10]
    return sorted(set(words)) or ["casa", "mesa", "porta", "livro"]


def r19_ppmi_vizinhos(lex, seed: int):
    """Build crude co-occurrence / PPMI-like neighbor lists from character bigrams (offline proxy)."""
    rng = r19_rng(seed, r19_crc("ppmi"), 3)
    # char-ngram vectors
    grams = {}
    for w in lex:
        g = {}
        for i in range(len(w) - 1):
            bg = w[i:i + 2]
            g[bg] = g.get(bg, 0) + 1
        grams[w] = g
    # similarity
    neigh = {w: [] for w in lex}
    keys = list(lex)
    for i, a in enumerate(keys):
        ga = grams[a]
        na = math.sqrt(sum(v * v for v in ga.values())) or 1.0
        sims = []
        for j, b in enumerate(keys):
            if i == j:
                continue
            gb = grams[b]
            dot = sum(ga.get(k, 0) * gb.get(k, 0) for k in ga)
            nb = math.sqrt(sum(v * v for v in gb.values())) or 1.0
            sims.append((dot / (na * nb), b))
        sims.sort(reverse=True)
        neigh[a] = [b for _, b in sims[:8]]
    return neigh


def r19_inventa(metodo: str, seed: int, n: int = R19_NINV_W) -> list:
    rng = r19_rng(seed, r19_crc("W|" + metodo), 11)
    lex = r19_lexico_lake()
    out = []
    if metodo == "iid_letras":
        abc = "abcdefghijklmnopqrstuvwxyz"
        for _ in range(n):
            L = int(rng.integers(4, 11))
            out.append("".join(abc[int(rng.integers(0, 26))] for _ in range(L)))
    elif metodo == "markov2_lex":
        # bigram markov from lex
        from collections import defaultdict
        nxt = defaultdict(list)
        for w in lex:
            w2 = "^" + w + "$"
            for i in range(len(w2) - 2):
                nxt[w2[i:i + 2]].append(w2[i + 2])
        for _ in range(n):
            # start
            starts = [w for w in lex]
            s = starts[int(rng.integers(0, len(starts)))]
            cur = "^" + s[0]
            chars = [s[0]]
            for _k in range(12):
                opts = nxt.get(cur, [])
                if not opts:
                    break
                c = opts[int(rng.integers(0, len(opts)))]
                if c == "$":
                    break
                chars.append(c)
                cur = cur[-1] + c
                if len(chars) >= 10:
                    break
            w = "".join(chars)
            if len(w) < 4:
                w = (w + "aeio")[:4]
            out.append(w[:10])
    elif metodo == "ppmi_vizinho":
        neigh = r19_ppmi_vizinhos(lex, seed)
        for _ in range(n):
            seed_w = lex[int(rng.integers(0, len(lex)))]
            cands = neigh.get(seed_w) or lex
            base = cands[int(rng.integers(0, len(cands)))]
            # mutate lightly
            chars = list(base)
            if len(chars) >= 4 and rng.random() < 0.5:
                i = int(rng.integers(0, len(chars)))
                chars[i] = "aeiou"[int(rng.integers(0, 5))]
            w = "".join(chars)
            if not (4 <= len(w) <= 10):
                w = (w + "casa")[:8]
            out.append(w)
    else:
        raise ValueError(metodo)
    return out


def r19_juiz_aberto(w: str, lake_words) -> bool:
    """Open judge ≈ R18: length + offline oracle + crude affinity to lake."""
    if not (4 <= len(w) <= 10):
        return False
    if r16_oraculo_offline(w):
        return True
    # affinity: shared bigrams with any lake word
    best = 0.0
    bg = {w[i:i + 2] for i in range(len(w) - 1)}
    for lw in lake_words[:80]:
        lg = {lw[i:i + 2] for i in range(len(lw) - 1)}
        if not bg or not lg:
            continue
        best = max(best, len(bg & lg) / math.sqrt(len(bg) * len(lg)))
    return best >= 0.40


def r19_eval_w(metodo: str, seed: int, hp: dict = None, n: int = R19_NINV_W) -> float:
    words = r19_inventa(metodo, seed, n=n)
    lake = r19_lexico_lake()
    ok = sum(1 for w in words if r19_juiz_aberto(w, lake))
    return float(ok / max(len(words), 1))


def r19_pareado_pack(diffs, seed=0):
    return r18_pareado_pack(diffs, seed=seed)


def r19_status(media, p_holm, sinal_esperado=1):
    return r18_status(media, p_holm, sinal_esperado=sinal_esperado)


def r19_job(task):
    kind = task[0]
    if kind == "F":
        _, cond, seed, hp = task
        return r19_eval_f(cond, seed, hp)
    if kind == "E":
        _, met, seed, hp = task
        return r19_eval_e(met, seed, hp)
    if kind == "W":
        _, met, seed, hp = task
        return r19_eval_w(met, seed, hp or {})
    if kind == "T":
        _, met, seed, hp = task
        return r19_eval_t(met, seed, hp or {})
    raise ValueError(kind)


def r19_tarefas(ctx):
    """Background tasks: return (fn, list_of_tasks) for mapa — here adjusters return hp dicts."""
    desloc = r19_desloc()
    S = r19_sementes(desloc)
    rapido = bool(getattr(ctx.args, "rapido", False))
    nsort = 1 if rapido else 6
    tasks = []
    # We pack adjusters as serializable labels; worker computes hp
    for met in R19_METODOS_E:
        tasks.append(("adjE", met, tuple(S["E_dev"][: R19_NDEV]), nsort))
    for met in R19_METODOS_W:
        tasks.append(("adjW", met, tuple(S["W_dev"][: R19_NDEV]), nsort))
    return _r19_bg_worker, tasks


def _r19_bg_worker(t):
    kind = t[0]
    if kind == "adjE":
        _, met, seeds, nsort = t
        return r19_ajustar_e(met, list(seeds), n_sort=nsort)
    if kind == "adjW":
        return {"ok": True}  # W methods have no hp
    return None


def r19_veredito_filtro(st: dict) -> str:
    """Pré-registered decision rule."""
    f1, f2, f3, f4 = st.get("F1"), st.get("F2"), st.get("F3"), st.get("F4")
    filtro_ajuda = (f1 == "confirmada") or (f2 == "confirmada")
    delirio_nao = (f3 in ("nula", "refutada")) and (f4 in ("nula", "refutada"))
    if filtro_ajuda and delirio_nao:
        return "O FILTRO É TODA A HISTÓRIA"
    if f3 == "confirmada":
        return "DELÍRIO ACRESCENTA (tese permanece aberta neste simulador)"
    return "INDECISO"


