def bloco27(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 27 — [R19] FILTRO=HISTÓRIA? + RL ORDINÁRIO×EXTRAORDINÁRIO (bandido c/ deriva) "
               "+ ÚLTIMA TENTATIVA canal PN aberto (8 confirmatórias, 40 sementes, Holm; prereg_r19.txt)")
    desloc = r19_desloc()
    if desloc:
        rep.log(f"[R19_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r19_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R19_NTEST
    n_prop = 12 if rapido else R19_NPROP_F
    n_inv = 20 if rapido else R19_NINV_W

    ok_p = hashlib.sha256(PREREG_R19_CORPO.encode("utf-8")).hexdigest() == PREREG_R19_CORPO_SHA256
    rep.log(f"Pré-registro R19: sha256={PREREG_R19_CORPO_SHA256[:16]}… "
            f"{'(CONFERE com versoes/prereg_r19.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R19_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R19_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R19_CORPO_SHA256
        rep.log(f"Adendo 1 R19: sha256={ADENDO1_R19_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")

    # ---- F (limiares congelados R18) ----
    rep.sub("F — O FILTRO É TODA A HISTÓRIA? (limiares congelados da R18; 4 condições)")
    hp_F = dict(R19_HP_FILTRO_CONGELADO)
    rep.log(f"  hp congelado: {hp_F}")
    scores_F = {c: [] for c in R19_CONDS_F}
    tasks = [("F", c, s, hp_F) for c in R19_CONDS_F for s in S["F_test"][:n_test]]
    # bind nprop via wrapper
    def _jf(t):
        return r19_eval_f(t[1], t[2], t[3], nprop=n_prop)
    outs = mapa_paralelo(_jf, tasks, jobs)
    k = 0
    for c in R19_CONDS_F:
        for _ in S["F_test"][:n_test]:
            scores_F[c].append(outs[k]); k += 1
        rep.log(f"  {c}: Youden={float(np.mean(scores_F[c])):+.3f}")
    P_F = {}
    for hname, (a, b) in R19_PAR_F.items():
        d = np.asarray(scores_F[a]) - np.asarray(scores_F[b])
        P_F[hname] = r19_pareado_pack(d, seed=r19_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_F[hname]['media']:+.3f} p={P_F[hname]['p']:.4f}")

    # ---- E ----
    rep.sub("E — REFORÇO ORDINÁRIO × EXTRAORDINÁRIO (bandido Bernoulli com deriva; NÃO loteria)")
    tuned = None
    if ctx.bg is not None:
        try:
            tuned = ctx.bg.obter("r19a")
        except Exception:
            tuned = None
    hp_E = {}
    ti = 0
    for met in R19_METODOS_E:
        if tuned is not None and ti < len(tuned) and isinstance(tuned[ti], dict) and "alpha" in tuned[ti]:
            hp_E[met] = tuned[ti]
        else:
            nsort = 1 if rapido else 6
            hp_E[met] = r19_ajustar_e(met, S["E_dev"][:R19_NDEV], n_sort=nsort)
        ti += 1
        rep.log(f"  ajuste {met}: {hp_E[met]}")
    scores_E = {m: [] for m in R19_METODOS_E}
    tasks = [("E", m, s, hp_E[m]) for m in R19_METODOS_E for s in S["E_test"][:n_test]]
    outs = mapa_paralelo(r19_job, tasks, jobs)
    k = 0
    for m in R19_METODOS_E:
        for _ in S["E_test"][:n_test]:
            scores_E[m].append(outs[k]); k += 1
        rep.log(f"  {m}: −arrependimento={float(np.mean(scores_E[m])):+.4f}")
    P_E = {}
    for hname, (a, b) in R19_PAR_E.items():
        d = np.asarray(scores_E[a]) - np.asarray(scores_E[b])
        P_E[hname] = r19_pareado_pack(d, seed=r19_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_E[hname]['media']:+.4f} p={P_E[hname]['p']:.4f}")

    # ---- W ----
    rep.sub("W — ÚLTIMA TENTATIVA canal palavra↔número ABERTO (ppmi_vizinho vs iid)")
    scores_W = {m: [] for m in R19_METODOS_W}
    tasks = [("W", m, s, {}) for m in R19_METODOS_W for s in S["W_test"][:n_test]]
    def _jw(t):
        return r19_eval_w(t[1], t[2], t[3], n=n_inv)
    outs = mapa_paralelo(_jw, tasks, jobs)
    k = 0
    for m in R19_METODOS_W:
        for _ in S["W_test"][:n_test]:
            scores_W[m].append(outs[k]); k += 1
        rep.log(f"  {m}: taxa={float(np.mean(scores_W[m])):+.3f}")
    P_W = {}
    for hname, (a, b) in R19_PAR_W.items():
        d = np.asarray(scores_W[a]) - np.asarray(scores_W[b])
        P_W[hname] = r19_pareado_pack(d, seed=r19_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_W[hname]['media']:+.3f} p={P_W[hname]['p']:.4f}")
    # exploratório
    d_exp = np.asarray(scores_W["ppmi_vizinho"]) - np.asarray(scores_W["markov2_lex"])
    P_wexp = r19_pareado_pack(d_exp, seed=r19_crc("Wexp"))
    rep.log(f"  [exploratório] ppmi_vizinho−markov2_lex: Δ={P_wexp['media']:+.3f} p={P_wexp['p']:.4f}")

    # ---- T tríade NN_A ⇄ GAN_meta ⇄ NN_B ----
    rep.sub("T — TRÍADE NN_A ⇄ GAN_meta ⇄ NN_B (vs so_A / so_B / media)")
    scores_T = {m: [] for m in ("triade", "so_A", "so_B", "media")}
    tasks = [("T", m, s, {}) for m in scores_T for s in S["T_test"][:n_test]]
    outs = mapa_paralelo(r19_job, tasks, jobs)
    k = 0
    for m in scores_T:
        for _ in S["T_test"][:n_test]:
            scores_T[m].append(outs[k]); k += 1
        rep.log(f"  {m}: cos={float(np.mean(scores_T[m])):+.4f}")
    P_T = {}
    for hname, (a, b) in R19_PAR_T.items():
        d = np.asarray(scores_T[a]) - np.asarray(scores_T[b])
        P_T[hname] = r19_pareado_pack(d, seed=r19_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_T[hname]['media']:+.4f} p={P_T[hname]['p']:.4f}")

    # ---- Holm ----
    st = {}
    def _holm_pack(Pdict, nomes):
        ps = [Pdict[h]["p"] for h in nomes]
        ph = holm(ps)
        for i, h in enumerate(nomes):
            Pdict[h]["p_holm"] = ph[i]
            st[h] = r19_status(Pdict[h]["media"], ph[i])
            rep.log(f"  status {h}: {st[h]} (p_holm={ph[i]:.4f})")
    _holm_pack(P_F, R19_HIPOT_F)
    _holm_pack(P_E, R19_HIPOT_E)
    _holm_pack(P_W, R19_HIPOT_W)
    _holm_pack(P_T, R19_HIPOT_T)

    ver_f = r19_veredito_filtro(st)
    lim_w = "LIMITAÇÃO PERMANENTE do canal aberto" if st.get("W1") != "confirmada" else "mecanismo ppmi_vizinho MANTIDO"
    rep.log(f"VEREDITO F (regra pré-registrada): {ver_f}")
    rep.log(f"VEREDITO W (regra pré-registrada): {lim_w}")
    if ver_f == "O FILTRO É TODA A HISTÓRIA":
        rep.log("→ Tese «delírio como caminho à ASI»: EMPIRICAMENTE NÃO SUSTENTADA neste simulador "
                "(o ganho medido é do filtro; delírio não acrescenta além dele). "
                "Isto NÃO prova nem refuta ASI real — só o que cabe nestas tarefas de brinquedo.")

    P_all = {}
    P_all.update(P_F); P_all.update(P_E); P_all.update(P_W); P_all.update(P_T)
    P_tup = {k: (v["media"], v["lo"], v["hi"], v["p"], v.get("p_holm", v["p"]), v["mde"]) for k, v in P_all.items()}
    n_conf = sum(1 for v in st.values() if v == "confirmada")
    n_ref = sum(1 for v in st.values() if v == "refutada")
    n_nula = sum(1 for v in st.values() if v == "nula")
    rep.log(f"RESUMO R19: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {len(st)} (8 corpo + 3 tríade Adendo1)")

    ctx.res["r19"] = {
        "P": P_tup, "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula,
        "ver_f": ver_f, "lim_w": lim_w,
        "scores_F": {c: float(np.mean(scores_F[c])) for c in R19_CONDS_F},
        "scores_E": {m: float(np.mean(scores_E[m])) for m in R19_METODOS_E},
        "scores_W": {m: float(np.mean(scores_W[m])) for m in R19_METODOS_W},
        "scores_T": {m: float(np.mean(scores_T[m])) for m in scores_T},
        "hp_F": hp_F, "hp_E": hp_E, "desloc": desloc,
        "chaves": list(R19_HIPOT),
        "P_wexp": P_wexp,
    }
    return ctx.res["r19"]


def registro_r19_log(ctx: Contexto) -> list:
    r = ctx.res.get("r19")
    if not r:
        return []
    L = [f"REGISTRO R19 (BLOCO 27) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de {len(r['chaves'])}"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append(f"  VEREDITO_F={r.get('ver_f')} | VEREDITO_W={r.get('lim_w')}")
