def r20_desloc() -> int:
    return 10000 if os.environ.get("R20_DEV") else 0


def r20_crc(rot: str) -> int:
    return zlib.crc32(f"R20|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r20_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


def r20_sementes(desloc=0):
    d = int(desloc)
    return {
        "H_dev": [s + d for s in R20_SEEDS_H_DEV],
        "H_test": [s + d for s in R20_SEEDS_H_TEST],
        "M_dev": [s + d for s in R20_SEEDS_M_DEV],
        "M_test": [s + d for s in R20_SEEDS_M_TEST],
    }


# ---------- H: filter-first loop ----------
def r20_gerar_props(cond: str, seed: int, hp: dict, nprop: int):
    """Generate proposals under filter-first / delirium / random arms."""
    rng = r20_rng(seed, r20_crc("H|" + cond), 5)
    T_hi = float(hp.get("T_hi", 1.5))
    T_lo = float(hp.get("T_lo", 0.3))
    if cond == "delirio_filtro":
        T = T_hi
        mode = "tagged"
    elif cond == "filtro_so":
        T = T_lo
        mode = "tagged"
    elif cond == "aleatorio_filtro":
        T = T_lo
        mode = "random"
    else:
        raise ValueError(cond)
    props = []
    if mode == "tagged":
        for i in range(R18_N_UTEIS):
            tag = R17_GRAM_UTEIS[i % len(R17_GRAM_UTEIS)]
            props.append(r17_propor_tag(rng, tag, T))
        for i in range(R18_N_INUTEIS):
            tag = R17_GRAM_INUTEIS[i % len(R17_GRAM_INUTEIS)]
            props.append(r17_propor_tag(rng, tag, T))
        for _ in range(max(0, nprop - R18_N_UTEIS - R18_N_INUTEIS)):
            props.append(r17_propor_livre(rng, T))
    else:
        # random arm: still plant util_ref labels for evaluation, but generation
        # ignores grammar tags — shuffle all slots as free + random plant flags
        # Keep planted labels for Youden fairness: force same counts of util_ref
        for i in range(R18_N_UTEIS):
            p = r17_propor_livre(rng, T)
            p["util_ref"] = True
            p["plantada"] = True
            props.append(p)
        for i in range(R18_N_INUTEIS):
            p = r17_propor_livre(rng, T)
            p["util_ref"] = False
            p["plantada"] = True
            props.append(p)
        for _ in range(max(0, nprop - R18_N_UTEIS - R18_N_INUTEIS)):
            props.append(r17_propor_livre(rng, T))
    return props


def r20_filtrar_props(props, seed: int, hp: dict):
    """Apply frozen 2-stage filter; return list of (comp, mantem, delta)."""
    tau_tela = float(hp.get("tau_tela", 0.40))
    tau_laudo = float(hp.get("tau_laudo", 0.55))
    out = []
    for i, comp in enumerate(props):
        proxy = r18_proxy_rapido(comp)
        if proxy < tau_tela:
            mantem = False
            delta = 0.0
        else:
            r = r18_avaliar_proposta_scores(comp, seed + 100 + i)
            mantem = r["score_laudo"] >= tau_laudo
            delta = float(r.get("delta", 0.0))
        out.append((comp, mantem, delta))
    return out


def r20_eval_h(cond: str, seed: int, hp: dict, nprop: int = R20_NPROP_H) -> dict:
    """Return Youden + gain_downstream for one arm."""
    props = r20_gerar_props(cond, seed, hp, nprop)
    scored = r20_filtrar_props(props, seed, hp)
    tp = fp = n_u = n_i = 0
    kept_deltas = []
    for comp, mantem, delta in scored:
        if mantem:
            kept_deltas.append(delta)
        if comp.get("util_ref"):
            n_u += 1
            if mantem:
                tp += 1
        elif comp.get("plantada") and not comp.get("util_ref"):
            n_i += 1
            if mantem:
                fp += 1
    TPR = tp / max(n_u, 1)
    FPR = fp / max(n_i, 1)
    youden = float(TPR - FPR)
    gain = float(np.mean(kept_deltas)) if kept_deltas else 0.0
    return {"Youden": youden, "gain": gain, "TPR": float(TPR), "FPR": float(FPR),
            "n_kept": len(kept_deltas)}


# ---------- M: twin mutual repair ----------
def r20_xor8_data(rng, n: int):
    X = rng.integers(0, 2, size=(n, 8)).astype(np.float64)
    # parity of bits 0,2,5
    y = ((X[:, 0] + X[:, 2] + X[:, 5]) % 2).astype(np.float64)
    return X, y


def r20_mlp_init(rng, noise=0.0):
    """8→12→1 weights."""
    W1 = rng.normal(0, 0.4, size=(8, 12))
    b1 = rng.normal(0, 0.05, size=(12,))
    W2 = rng.normal(0, 0.4, size=(12, 1))
    b2 = rng.normal(0, 0.05, size=(1,))
    if noise:
        W1 = W1 + rng.normal(0, noise, size=W1.shape)
        W2 = W2 + rng.normal(0, noise, size=W2.shape)
    return [W1, b1, W2, b2]


def r20_mlp_forward(p, X):
    W1, b1, W2, b2 = p
    H = np.tanh(X @ W1 + b1)
    Z = H @ W2 + b2
    Y = 1.0 / (1.0 + np.exp(-np.clip(Z, -30, 30)))
    return Y.ravel(), H


def r20_mlp_step(p, X, y, lr=0.15):
    """One SGD step on BCE; returns updated params."""
    W1, b1, W2, b2 = [a.copy() for a in p]
    yhat, H = r20_mlp_forward(p, X)
    n = max(len(y), 1)
    err = (yhat - y) / n  # dL/dz
    # W2,b2
    gW2 = H.T @ err.reshape(-1, 1)
    gb2 = err.sum(keepdims=True)
    # back to H
    dH = err.reshape(-1, 1) @ W2.T
    dPre = dH * (1.0 - H * H)
    gW1 = X.T @ dPre
    gb1 = dPre.sum(axis=0)
    W1 -= lr * gW1
    b1 -= lr * gb1
    W2 -= lr * gW2
    b2 -= lr * gb2
    return [W1, b1, W2, b2]


def r20_mlp_acc(p, X, y):
    yhat, _ = r20_mlp_forward(p, X)
    return float(np.mean((yhat >= 0.5) == (y >= 0.5)))


def r20_erros_idx(p, X, y):
    yhat, _ = r20_mlp_forward(p, X)
    pred = (yhat >= 0.5).astype(np.float64)
    return np.where(pred != y)[0]


def r20_treino_modo(modo: str, seed: int, hp: dict = None) -> dict:
    """Train solo_A / solo_B / mutuo; return holdout accuracies."""
    hp = hp or {}
    epochs = int(hp.get("epochs", R20_M_EPOCHS))
    B = int(hp.get("batch", R20_M_BATCH))
    lr = float(hp.get("lr", 0.15))
    rng = r20_rng(seed, r20_crc("M|" + modo), 11)
    Xtr, ytr = r20_xor8_data(rng, R20_M_TRAIN)
    Xho, yho = r20_xor8_data(rng, R20_M_HOLDOUT)
    # shared init
    rng_init = r20_rng(seed, r20_crc("Minit"), 3)
    A = r20_mlp_init(rng_init, noise=0.0)
    Bnet = r20_mlp_init(rng_init, noise=0.05)  # near-copy
    for ep in range(epochs):
        # A errors / B errors on train
        ea = r20_erros_idx(A, Xtr, ytr)
        eb = r20_erros_idx(Bnet, Xtr, ytr)
        if modo == "solo_A":
            idx_a = ea if len(ea) else rng.integers(0, len(Xtr), size=B)
            idx_b = None
        elif modo == "solo_B":
            idx_a = None
            idx_b = eb if len(eb) else rng.integers(0, len(Xtr), size=B)
        elif modo == "mutuo":
            # each trains on own errors ∪ other's errors
            pool_a = np.unique(np.concatenate([ea, eb])) if (len(ea) or len(eb)) else np.arange(len(Xtr))
            pool_b = pool_a
            idx_a = pool_a
            idx_b = pool_b
        else:
            raise ValueError(modo)
        def _batch(idx):
            if idx is None:
                return None, None
            if len(idx) == 0:
                idx = rng.integers(0, len(Xtr), size=B)
            if len(idx) > B:
                idx = rng.choice(idx, size=B, replace=False)
            return Xtr[idx], ytr[idx]
        if idx_a is not None:
            Xb, yb = _batch(idx_a)
            A = r20_mlp_step(A, Xb, yb, lr=lr)
        if idx_b is not None:
            Xb, yb = _batch(idx_b)
            Bnet = r20_mlp_step(Bnet, Xb, yb, lr=lr)
        # if solo_A only trains A, still lightly keep B frozen (no step)
        # if solo_B only trains B
    acc_a = r20_mlp_acc(A, Xho, yho)
    acc_b = r20_mlp_acc(Bnet, Xho, yho)
    return {"acc_A": acc_a, "acc_B": acc_b, "acc_mean": 0.5 * (acc_a + acc_b)}


def r20_eval_m(metrica: str, seed: int, hp: dict = None) -> float:
    """Return the scalar used in contrasts.
    metrica in {mutuo_mean, solo_mean, mutuo_A, solo_A, mutuo_B, solo_B}
    """
    hp = hp or {}
    if metrica.startswith("mutuo"):
        r = r20_treino_modo("mutuo", seed, hp)
        if metrica == "mutuo_mean":
            return r["acc_mean"]
        if metrica == "mutuo_A":
            return r["acc_A"]
        if metrica == "mutuo_B":
            return r["acc_B"]
    elif metrica.startswith("solo"):
        if metrica == "solo_mean":
            a = r20_treino_modo("solo_A", seed, hp)["acc_A"]
            b = r20_treino_modo("solo_B", seed, hp)["acc_B"]
            return 0.5 * (a + b)
        if metrica == "solo_A":
            return r20_treino_modo("solo_A", seed, hp)["acc_A"]
        if metrica == "solo_B":
            return r20_treino_modo("solo_B", seed, hp)["acc_B"]
    raise ValueError(metrica)


def r20_ajustar_m(seeds_dev, n_sort: int = 4) -> dict:
    best, bh = -1e18, {"epochs": R20_M_EPOCHS, "batch": R20_M_BATCH, "lr": 0.15}
    rng = r20_rng(r20_crc("Madj"), 20, 0)
    for i in range(n_sort):
        hp = {
            "epochs": int(rng.choice([8, 12, 16])),
            "batch": int(rng.choice([16, 32])),
            "lr": float(rng.choice([0.08, 0.15, 0.25])),
        }
        sc = float(np.mean([r20_eval_m("mutuo_mean", s, hp) for s in seeds_dev]))
        if sc > best:
            best, bh = sc, hp
    return bh


def r20_pareado_pack(diffs, seed=0):
    # reuse r19 if available else local
    if "r19_pareado_pack" in globals():
        return r19_pareado_pack(diffs, seed=seed)
    d = np.asarray(diffs, dtype=float)
    media = float(np.mean(d))
    # sign-flip permutation
    rng = np.random.default_rng(int(seed) & 0xFFFFFFFF)
    n = len(d)
    if n == 0:
        return {"media": 0.0, "lo": 0.0, "hi": 0.0, "p": 1.0, "mde": 0.0}
    obs = abs(media)
    cnt = 0
    B = 10000
    for _ in range(B):
        s = rng.choice([-1.0, 1.0], size=n)
        if abs(float(np.mean(d * s))) >= obs - 1e-15:
            cnt += 1
    p = (cnt + 1) / (B + 1)
    # bootstrap IC
    boots = []
    for _ in range(2000):
        idx = rng.integers(0, n, size=n)
        boots.append(float(np.mean(d[idx])))
    lo, hi = float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))
    # crude MDE80
    sd = float(np.std(d, ddof=1)) if n > 1 else 1.0
    mde = 2.8 * sd / max(np.sqrt(n), 1e-9)
    return {"media": media, "lo": lo, "hi": hi, "p": float(p), "mde": float(mde)}


def r20_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05:
        if media * sinal_esperado > 0:
            return "confirmada"
        return "refutada"
    return "nula"


def r20_job(task):
    kind = task[0]
    if kind == "H":
        _, cond, seed, hp = task
        return r20_eval_h(cond, seed, hp)
    if kind == "M":
        _, met, seed, hp = task
        return r20_eval_m(met, seed, hp)
    raise ValueError(kind)


def r20_tarefas(ctx):
    """Background tuning for M (H has frozen thresholds)."""
    desloc = r20_desloc()
    S = r20_sementes(desloc)
    return _r20_bg_worker, S["M_dev"][:R20_NDEV]


def _r20_bg_worker(t):
    return r20_ajustar_m(t, n_sort=4)


def r20_veredito_filtro_primeiro(st: dict) -> str:
    """Pré-registered decision rule."""
    h1 = st.get("H1", "nula")
    h2 = st.get("H2", "nula")
    h3 = st.get("H3", "nula")
    h4 = st.get("H4", "nula")
    ok_filtro = (h1 == "confirmada") or (h3 == "confirmada")
    del_nao_acrescenta = (h2 in ("nula", "refutada")) and (h4 in ("nula", "refutada"))
    if ok_filtro and del_nao_acrescenta:
        return "FILTRO-PRIMEIRO PROMOVIDO"
    if h2 == "confirmada" or h4 == "confirmada":
        return "DELIRIO AINDA CANDIDATO"
    return "INDECISO"


