# [R20] ORQUESTRAÇÃO DO BLOCO 28 + registro/sumário/leigos

def bloco28(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 28 — [R20] FILTRO-PRIMEIRO (H: filtro_so × delirio+filtro × aleatorio+filtro) "
               "+ REPARO MÚTUO GÊMEO (M) (7 confirmatórias, 40 sementes, Holm; prereg_r20.txt)")
    desloc = r20_desloc()
    if desloc:
        rep.log(f"[R20_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r20_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R20_NTEST
    n_prop = 12 if rapido else R20_NPROP_H

    ok_p = hashlib.sha256(PREREG_R20_CORPO.encode("utf-8")).hexdigest() == PREREG_R20_CORPO_SHA256
    rep.log(f"Pré-registro R20: sha256={PREREG_R20_CORPO_SHA256[:16]}… "
            f"{'(CONFERE com versoes/prereg_r20.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R20_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R20_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R20_CORPO_SHA256
        rep.log(f"Adendo 1 R20: sha256={ADENDO1_R20_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")

    # ---- H (filter-first) ----
    rep.sub("H — FILTRO-PRIMEIRO (limiares congelados; 3 braços; Youden + ganho a jusante)")
    hp_H = dict(R20_HP_FILTRO_CONGELADO)
    rep.log(f"  hp congelado: {hp_H}")
    scores_H = {c: {"Youden": [], "gain": []} for c in R20_CONDS_H}
    tasks = [("H", c, s, hp_H) for c in R20_CONDS_H for s in S["H_test"][:n_test]]
    outs = mapa_paralelo(r20_job, tasks, jobs)
    k = 0
    for c in R20_CONDS_H:
        for _ in S["H_test"][:n_test]:
            r = outs[k]; k += 1
            scores_H[c]["Youden"].append(r["Youden"])
            scores_H[c]["gain"].append(r["gain"])
        rep.log(f"  {c}: Youden={float(np.mean(scores_H[c]['Youden'])):+.3f} "
                f"gain={float(np.mean(scores_H[c]['gain'])):+.4f}")
    P_H = {}
    for hname, (a, b, met) in R20_PAR_H.items():
        d = np.asarray(scores_H[a][met]) - np.asarray(scores_H[b][met])
        P_H[hname] = r20_pareado_pack(d, seed=r20_crc(hname))
        rep.log(f"  {hname} ({a}−{b} [{met}]): Δ={P_H[hname]['media']:+.4f} p={P_H[hname]['p']:.4f}")

    # ---- M (mutual repair) ----
    rep.sub("M — REPARO MÚTUO DE CÓDIGO GÊMEO (XOR-8; mutuo vs solo)")
    tuned = None
    if ctx.bg is not None:
        try:
            tuned = ctx.bg.obter("r20a")
        except Exception:
            tuned = None
    if isinstance(tuned, dict) and "lr" in tuned:
        hp_M = tuned
    else:
        nsort = 1 if rapido else 4
        hp_M = r20_ajustar_m(S["M_dev"][:R20_NDEV], n_sort=nsort)
    rep.log(f"  ajuste M: {hp_M}")
    mets = ("mutuo_mean", "solo_mean", "mutuo_A", "solo_A", "mutuo_B", "solo_B")
    scores_M = {m: [] for m in mets}
    tasks = [("M", m, s, hp_M) for m in mets for s in S["M_test"][:n_test]]
    outs = mapa_paralelo(r20_job, tasks, jobs)
    k = 0
    for m in mets:
        for _ in S["M_test"][:n_test]:
            scores_M[m].append(outs[k]); k += 1
        rep.log(f"  {m}: acc={float(np.mean(scores_M[m])):+.4f}")
    P_M = {}
    pars_m = {
        "M1": ("mutuo_mean", "solo_mean"),
        "M2": ("mutuo_A", "solo_A"),
        "M3": ("mutuo_B", "solo_B"),
    }
    for hname, (a, b) in pars_m.items():
        d = np.asarray(scores_M[a]) - np.asarray(scores_M[b])
        P_M[hname] = r20_pareado_pack(d, seed=r20_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_M[hname]['media']:+.4f} p={P_M[hname]['p']:.4f}")

    # ---- Holm ----
    st = {}
    def _holm_pack(Pdict, nomes):
        ps = [Pdict[h]["p"] for h in nomes]
        ph = holm(ps)
        for i, h in enumerate(nomes):
            Pdict[h]["p_holm"] = ph[i]
            st[h] = r20_status(Pdict[h]["media"], ph[i])
            rep.log(f"  status {h}: {st[h]} (p_holm={ph[i]:.4f})")
    _holm_pack(P_H, R20_HIPOT_H)
    _holm_pack(P_M, R20_HIPOT_M)

    ver_h = r20_veredito_filtro_primeiro(st)
    rep.log(f"VEREDITO H (regra pré-registrada): {ver_h}")
    if ver_h == "FILTRO-PRIMEIRO PROMOVIDO":
        rep.log("→ Arquitetura promovida: o ESCRUTINADOR/FILTRO é o motor primário de evolução; "
                "delírio = explorador OPCIONAL sem ganho medido além do filtro-só. "
                "Isto NÃO é ASI/AGI — só o que cabe nestas tarefas de brinquedo.")
    ver_m = "REPARO MÚTUO AJUDA" if st.get("M1") == "confirmada" else (
        "REPARO MÚTUO NÃO SUPERA SOLO" if st.get("M1") in ("nula", "refutada") else "INDECISO")
    rep.log(f"VEREDITO M: {ver_m}")

    P_all = {}
    P_all.update(P_H); P_all.update(P_M)
    P_tup = {k: (v["media"], v["lo"], v["hi"], v["p"], v.get("p_holm", v["p"]), v["mde"]) for k, v in P_all.items()}
    n_conf = sum(1 for v in st.values() if v == "confirmada")
    n_ref = sum(1 for v in st.values() if v == "refutada")
    n_nula = sum(1 for v in st.values() if v == "nula")
    rep.log(f"RESUMO R20: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {len(st)}")

    ctx.res["r20"] = {
        "P": P_tup, "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula,
        "ver_h": ver_h, "ver_m": ver_m,
        "scores_H": {c: {"Youden": float(np.mean(scores_H[c]["Youden"])),
                         "gain": float(np.mean(scores_H[c]["gain"]))} for c in R20_CONDS_H},
        "scores_M": {m: float(np.mean(scores_M[m])) for m in mets},
        "hp_H": hp_H, "hp_M": hp_M, "desloc": desloc,
        "chaves": list(R20_HIPOT),
    }
    return ctx.res["r20"]


def registro_r20(ctx: Contexto) -> list:
    r = ctx.res.get("r20")
    if not r:
        return []
    L = [f"REGISTRO R20 (BLOCO 28) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de {len(r['chaves'])}"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append(f"  VEREDITO_H={r.get('ver_h')} | VEREDITO_M={r.get('ver_m')}")
    return L


def sumario_r20_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r20")
    if not r:
        return ["R20: (ainda sem resultados nesta execução)"]
    return [
        f"R20 BLOCO 28: {r['n_conf']} conf / {r['n_ref']} ref / {r['n_nula']} nulas | "
        f"H veredito={r.get('ver_h')} | M={r.get('ver_m')} | "
        f"H1={r['st'].get('H1')} H2={r['st'].get('H2')} M1={r['st'].get('M1')}"
    ]


def registro_hipoteses_r20(ctx: Contexto) -> list:
    r = ctx.res.get("r20")
    if not r:
        return []
    out = []
    desc = {
        "H1": "filtro_so − aleatorio_filtro (Youden; filtro-primeiro > aleatório+filtro?)",
        "H2": "delirio_filtro − filtro_so (Youden; delírio acrescenta?)",
        "H3": "filtro_so − aleatorio_filtro (ganho jusante)",
        "H4": "delirio_filtro − filtro_so (ganho jusante; delírio acrescenta?)",
        "M1": "mutuo_mean − solo_mean (reparo mútuo gêmeo)",
        "M2": "mutuo_A − solo_A",
        "M3": "mutuo_B − solo_B",
    }
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde = r["P"][k]
        out.append(("R20", f"R20-{k}", "CONF", desc.get(k, k),
                    f"Δ={m:+.4f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    out.append(("R20", "R20-VH", "DESC", "Veredito H (filtro-primeiro)", r.get("ver_h", "?"), "descritiva"))
    out.append(("R20", "R20-VM", "DESC", "Veredito M (reparo mútuo)", r.get("ver_m", "?"), "descritiva"))
    out.append(("R20", "R20-SKIP", "DESC",
                "Pedidos recusados: jailbreaks/backdoors/sandbox escapes; chave API; Hertz; milhões literais; alegar consciência/ASI",
                "pulados", "descritiva"))
    return out


