R22_N_UTEIS = 6
R22_N_INUTEIS = 6

R22_SEEDS_M_DEV = list(range(25100, 25116))
R22_SEEDS_M_TEST = list(range(25200, 25240))
R22_SEEDS_L_DEV = list(range(25300, 25316))
R22_SEEDS_L_TEST = list(range(25400, 25440))
R22_SEEDS_G_DEV = list(range(25500, 25516))
R22_SEEDS_G_TEST = list(range(25600, 25640))

R22_CONDS_M = ("mfm", "fixed", "pfp")
R22_HIPOT_M = ("M1", "M2", "M3")
R22_PAR_M = {
    "M1": ("mfm", "fixed", "Youden"),
    "M2": ("mfm", "pfp", "Youden"),
    "M3": ("mfm", "fixed", "gain"),
}

R22_CONDS_L = ("oneshot", "inv_k2", "inv_k6", "inv_k12")
R22_HIPOT_L = ("L1", "L2", "L3")
R22_PAR_L = {
    "L1": ("inv_k6", "oneshot", "gain"),
    "L2": ("inv_k12", "inv_k6", "gain"),
    "L3": ("inv_k12", "oneshot", "Youden"),
}

R22_CONDS_G = ("ghost", "proxy", "ghost_px", "chance")
R22_HIPOT_G = ("G1", "G2", "G3")
R22_PAR_G = {
    "G1": ("ghost", "chance", "AUC"),
    "G2": ("ghost_px", "proxy", "AUC"),
    "G3": ("ghost", "proxy", "AUC"),
}

R22_HIPOT = R22_HIPOT_M + R22_HIPOT_L + R22_HIPOT_G

R22_HP_FILTRO_CONGELADO = {"T_hi": 1.5, "T_lo": 0.3, "tau_tela": 0.40, "tau_laudo": 0.55}

# NEW planted family (≠ R17 residual/harm_invert)
R22_GRAM_UTEIS = ("ema_shadow", "skip_gate", "temp_scale")
R22_GRAM_INUTEIS = ("harm_flip", "harm_scale", "harm_jitter")


def r22_desloc() -> int:
    v = os.environ.get("R22_DEV")
    if not v or v in ("0", "false", "False", "no", "off", ""):
        return 0
    return 10000


def r22_crc(rot: str) -> int:
    return zlib.crc32(f"R22|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r22_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


def r22_sementes(desloc=0):
    d = int(desloc)
    return {
        "M_dev": [s + d for s in R22_SEEDS_M_DEV],
        "M_test": [s + d for s in R22_SEEDS_M_TEST],
        "L_dev": [s + d for s in R22_SEEDS_L_DEV],
        "L_test": [s + d for s in R22_SEEDS_L_TEST],
        "G_dev": [s + d for s in R22_SEEDS_G_DEV],
        "G_test": [s + d for s in R22_SEEDS_G_TEST],
    }


# ---------- NEW family proposals ----------
def r22_propor_tag(rng, tag: str, T: float) -> dict:
    util = tag in R22_GRAM_UTEIS
    harm = tag in R22_GRAM_INUTEIS
    return {
        "tag": tag,
        "nome": f"{tag}_{int(rng.integers(0, 1_000_000))}",
        "peso": float(rng.uniform(0.2, 0.9)) if util else float(rng.uniform(0.1, 1.0)),
        "limiar": float(np.clip(0.5 + float(rng.normal(0, 0.15 * max(T, 0.3))), 0.05, 0.95)),
        "T": float(T),
        "plantada": util or harm,
        "util_ref": util,
        "familia": "R22",
    }


def r22_proxy_novo(comp) -> float:
    """Proxy for NEW family (structural twin of r18_proxy_rapido; milder boosts)."""
    tag = comp["tag"]
    peso = float(comp.get("peso", 0.5))
    limiar = float(comp.get("limiar", 0.5))
    base = 0.42 + 0.18 * peso
    if tag in R22_GRAM_UTEIS:
        base += 0.18  # milder than R18 (+0.25) to avoid ceiling
    if tag in R22_GRAM_INUTEIS:
        base -= 0.22
    h = (zlib.crc32(comp.get("nome", tag).encode()) & 0xFFFF) / 65535.0
    return float(np.clip(base + 0.08 * (h - 0.5) + 0.05 * (1.0 - abs(limiar - 0.5)), 0.0, 1.0))


def r22_avaliar_novo(comp, seed: int) -> dict:
    """Cheap laudo for NEW family: noisy V-pattern (avoids Youden=1 ceiling)."""
    rng = r22_rng(seed, r22_crc("laudo_novo"), zlib.crc32(comp.get("nome", "").encode()) & 0xFFFF)
    util = bool(comp.get("util_ref"))
    harm = comp.get("tag") in R22_GRAM_INUTEIS
    proxy = r22_proxy_novo(comp)
    # noisy checks: flip with small probability so filter has room to err
    V1 = bool(util and proxy > 0.50) or (not harm and proxy > 0.72)
    if rng.random() < 0.12:
        V1 = not V1
    V2 = bool(abs(proxy - (0.70 if util else 0.35)) < 0.40)
    if rng.random() < 0.10:
        V2 = not V2
    V3 = (not harm) if rng.random() >= 0.08 else harm
    V4 = float(comp.get("limiar", 0.5)) > 0.20
    delta = (0.06 if util else -0.05) + float(rng.normal(0, 0.04))
    score = 0.0
    score += 0.30 if V1 else 0.0
    score += 0.25 if V2 else 0.0
    score += 0.25 if V3 else 0.0
    score += 0.10 if V4 else 0.0
    score += 0.25 * float(np.clip(delta, -0.5, 0.5) + 0.5)
    # inject proxy-tied continuous noise so tau_mode can bite
    score = 0.75 * score + 0.25 * proxy + float(rng.normal(0, 0.03))
    return {
        "V1": V1, "V2": V2, "V3": V3, "V4": V4,
        "delta": float(delta),
        "proxy": float(proxy),
        "score_laudo": float(np.clip(score, 0.0, 1.0)),
        "mantem": False,
    }


def r22_gerar_props_nova(seed: int, hp: dict, nprop: int):
    rng = r22_rng(seed, r22_crc("props|nova"), 5)
    T = float(hp.get("T_lo", 0.3))
    props = []
    for i in range(R22_N_UTEIS):
        tag = R22_GRAM_UTEIS[i % len(R22_GRAM_UTEIS)]
        props.append(r22_propor_tag(rng, tag, T))
    for i in range(R22_N_INUTEIS):
        tag = R22_GRAM_INUTEIS[i % len(R22_GRAM_INUTEIS)]
        props.append(r22_propor_tag(rng, tag, T))
    # livres misturam tags novas
    livres = R22_GRAM_UTEIS + R22_GRAM_INUTEIS
    for _ in range(max(0, nprop - R22_N_UTEIS - R22_N_INUTEIS)):
        tag = livres[int(rng.integers(0, len(livres)))]
        p = r22_propor_tag(rng, tag, T)
        p["plantada"] = False  # livre: sem rótulo forçado no Youden (só plantadas contam)
        p["util_ref"] = False
        props.append(p)
    return props


def r22_youden_gain(scored) -> dict:
    tp = fp = n_u = n_i = 0
    kept_deltas = []
    for comp, mantem, delta in scored:
        if mantem:
            kept_deltas.append(delta)
        if comp.get("util_ref"):
            n_u += 1
            if mantem:
                tp += 1
        elif comp.get("plantada") and not comp.get("util_ref"):
            n_i += 1
            if mantem:
                fp += 1
    TPR = tp / max(n_u, 1)
    FPR = fp / max(n_i, 1)
    youden = float(TPR - FPR)
    gain = float(np.mean(kept_deltas)) if kept_deltas else 0.0
    return {"Youden": youden, "gain": gain, "TPR": float(TPR), "FPR": float(FPR),
            "n_kept": len(kept_deltas)}


def r22_mfm_tau_novo(comp, seed: int, i: int) -> float:
    """mfm fixed-point using NEW-family features (not R17 shim)."""
    peso = float(comp.get("peso", 0.5))
    limiar = float(comp.get("limiar", 0.5))
    util = 1.0 if comp.get("tag") in R22_GRAM_UTEIS else 0.0
    harm = 1.0 if comp.get("tag") in R22_GRAM_INUTEIS else 0.0
    proxy = r22_proxy_novo(comp)
    v = np.array([peso, limiar, util, harm, proxy], dtype=float)
    rng = r22_rng(seed, r22_crc("C|mfm_novo"), 9)
    ctx = rng.normal(0, 1, size=5)
    ctx = ctx / (np.linalg.norm(ctx) + 1e-12)
    v = v / (np.linalg.norm(v) + 1e-12)
    obs = []
    cur = v
    for _ in range(3):
        c = float(np.clip(np.dot(cur, ctx), -1.0, 1.0))
        c2 = 2.0 * c * c - 1.0
        obs.append(c2)
        cur = 0.7 * cur + 0.3 * (c2 * ctx)
        cur = cur / (np.linalg.norm(cur) + 1e-12)
    sim_norm = float(np.clip(0.5 * (np.mean(obs) + 1.0), 0.0, 1.0))
    tau = 0.35 + 0.40 * sim_norm
    return float(np.clip(tau, 0.35, 0.75))


def r22_pfp_tau_novo(comp, seed: int, i: int) -> float:
    """pfp fixed-point on NEW proxy (ablation / demotion arm)."""
    rng = r22_rng(seed, r22_crc("C|pfp_novo"), i + 3)
    proxy = float(np.clip(r22_proxy_novo(comp), 1e-3, 1 - 1e-3))
    a = 1.0 + 8.0 * proxy
    b = 1.0 + 8.0 * (1.0 - proxy)
    for _ in range(4):
        q = float(rng.beta(a, b))
        a = 1.0 + 8.0 * q
        b = 1.0 + 8.0 * (1.0 - q)
    mean = a / (a + b)
    var = (a * b) / (((a + b) ** 2) * (a + b + 1.0))
    var_norm = float(np.clip(var / 0.25, 0.0, 1.0))
    tau = 0.35 + 0.40 * (1.0 - var_norm) * (0.5 + 0.5 * mean)
    return float(np.clip(tau, 0.35, 0.75))


def r22_filtrar_com_tau_novo(props, seed: int, hp: dict, tau_mode: str):
    """2-stage filter on NEW family; tau_mode in {fixed,mfm,pfp}."""
    tau_tela = float(hp.get("tau_tela", 0.40))
    tau_laudo_fixed = float(hp.get("tau_laudo", 0.55))
    out = []
    for i, comp in enumerate(props):
        proxy = r22_proxy_novo(comp)
        if proxy < tau_tela:
            out.append((comp, False, 0.0))
            continue
        if tau_mode == "fixed":
            tau_l = tau_laudo_fixed
        elif tau_mode == "mfm":
            tau_l = r22_mfm_tau_novo(comp, seed, i)
        elif tau_mode == "pfp":
            tau_l = r22_pfp_tau_novo(comp, seed, i)
        else:
            raise ValueError(tau_mode)
        r = r22_avaliar_novo(comp, seed + 100 + i)
        mantem = r["score_laudo"] >= tau_l
        out.append((comp, mantem, float(r.get("delta", 0.0)) if mantem else 0.0))
    return out


def r22_eval_m(cond: str, seed: int, hp: dict, nprop: int = R22_NPROP) -> dict:
    props = r22_gerar_props_nova(seed, hp, nprop)
    scored = r22_filtrar_com_tau_novo(props, seed, hp, cond)
    return r22_youden_gain(scored)


# ---------- L: inversion length in default generator path ----------
def r22_gerar_props_r17(seed: int, hp: dict, nprop: int):
    """Classic R17 planted family (for L/G — not the NEW M family)."""
    return r21_gerar_props_filtro_so(seed, hp, nprop)


def r22_eval_l(cond: str, seed: int, hp: dict, nprop: int = R22_NPROP) -> dict:
    props = r22_gerar_props_r17(seed, hp, nprop)
    if cond == "oneshot":
        pass
    elif cond == "inv_k2":
        props = [r21_laco_inversao(p, seed, i, k_max=2) for i, p in enumerate(props)]
    elif cond == "inv_k6":
        props = [r21_laco_inversao(p, seed, i, k_max=6) for i, p in enumerate(props)]
    elif cond == "inv_k12":
        props = [r21_laco_inversao(p, seed, i, k_max=12) for i, p in enumerate(props)]
    else:
        raise ValueError(cond)
    # frozen single filter-first with FIXED tau (prereg: L does not depend on M)
    scored = r21_filtrar_single(props, seed, hp)
    return r22_youden_gain(scored)


# ---------- G: ghost residual monitoring ----------
def r22_encode_state(comp) -> np.ndarray:
    tag = comp.get("tag", "")
    peso = float(comp.get("peso", 0.5))
    limiar = float(comp.get("limiar", 0.5))
    util = 1.0 if tag in R17_GRAM_UTEIS else 0.0
    harm = 1.0 if tag in R17_GRAM_INUTEIS else 0.0
    proxy = float(r18_proxy_rapido(comp))
    h = (zlib.crc32(comp.get("nome", tag).encode()) & 0xFFFF) / 65535.0
    v = np.array([peso, limiar, util, harm, proxy, h, peso * limiar, abs(peso - limiar)], dtype=float)
    return v


def r22_ghost_residual(comp, seed: int, i: int, steps: int = 8) -> float:
    """Dual parallel state: simultaneous add/sub and mul/div on shared (a,b)."""
    rng = r22_rng(seed, r22_crc("G|ghost"), i + 11)
    main = r22_encode_state(comp)
    ghost = main.copy()
    for _ in range(steps):
        a = rng.uniform(-1.0, 1.0, size=main.shape)
        b = rng.uniform(0.5, 1.5, size=main.shape)
        main = (main + a) * b
        ghost = (ghost - a) / np.maximum(b, 1e-6)
    return float(np.linalg.norm(main - ghost))


def r22_score_ghost(comp, seed: int, i: int) -> float:
    r = r22_ghost_residual(comp, seed, i)
    return float(1.0 / (1.0 + r))  # higher = more stable → expect utiles


def r22_eval_g(cond: str, seed: int, hp: dict, nprop: int = R22_NPROP) -> dict:
    """Return AUC of the named monitor on planted R17 proposals."""
    props = r22_gerar_props_r17(seed, hp, nprop)
    ys, ss = [], []
    rng_chance = r22_rng(seed, r22_crc("G|chance"), 3)
    for i, comp in enumerate(props):
        if not comp.get("plantada"):
            continue
        y = 1.0 if comp.get("util_ref") else 0.0
        if cond == "ghost":
            s = r22_score_ghost(comp, seed, i)
        elif cond == "proxy":
            s = float(r18_proxy_rapido(comp))
        elif cond == "ghost_px":
            s = 0.5 * r22_score_ghost(comp, seed, i) + 0.5 * float(r18_proxy_rapido(comp))
        elif cond == "chance":
            s = float(rng_chance.random())
        else:
            raise ValueError(cond)
        ys.append(y)
        ss.append(s)
    auc = float(auc_rank(ss, ys)) if ys else float("nan")
    if not np.isfinite(auc):
        auc = 0.5
    return {"AUC": auc, "Youden": auc - 0.5, "gain": auc}  # Youden/gain aliases unused for G


# ---------- stats / jobs ----------
def r22_pareado_pack(diffs, seed=0):
    if "r21_pareado_pack" in globals():
        return r21_pareado_pack(diffs, seed=seed)
    if "r20_pareado_pack" in globals():
        return r20_pareado_pack(diffs, seed=seed)
    d = np.asarray(diffs, dtype=float)
    media = float(np.mean(d)) if len(d) else 0.0
    rng = np.random.default_rng(int(seed) & 0xFFFFFFFF)
    n = len(d)
    if n == 0:
        return {"media": 0.0, "lo": 0.0, "hi": 0.0, "p": 1.0, "mde": 0.0}
    obs = abs(media)
    cnt = 0
    B = 10000
    for _ in range(B):
        s = rng.choice([-1.0, 1.0], size=n)
        if abs(float(np.mean(d * s))) >= obs - 1e-15:
            cnt += 1
    p = (cnt + 1) / (B + 1)
    boots = [float(np.mean(d[rng.integers(0, n, size=n)])) for _ in range(2000)]
    lo, hi = float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))
    sd = float(np.std(d, ddof=1)) if n > 1 else 1.0
    mde = 2.8 * sd / max(np.sqrt(n), 1e-9)
    return {"media": media, "lo": lo, "hi": hi, "p": float(p), "mde": float(mde)}


def r22_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05:
        if media * sinal_esperado > 0:
            return "confirmada"
        return "refutada"
    return "nula"


def r22_job(task):
    kind = task[0]
    if kind == "M":
        _, cond, seed, hp = task
        return r22_eval_m(cond, seed, hp)
    if kind == "L":
        _, cond, seed, hp = task
        return r22_eval_l(cond, seed, hp)
    if kind == "G":
        _, cond, seed, hp = task
        return r22_eval_g(cond, seed, hp)
    raise ValueError(kind)


def r22_tarefas(ctx):
    """No heavy DEV tune; placeholder returns identity for bg compat."""
    desloc = r22_desloc()
    S = r22_sementes(desloc)
    return _r22_bg_worker, S["M_dev"][:R22_NDEV]


def _r22_bg_worker(t):
    # sanity: evaluate mfm Youden mean on DEV (not used to change contrasts)
    hp = dict(R22_HP_FILTRO_CONGELADO)
    ys = [r22_eval_m("mfm", s, hp, nprop=16)["Youden"] for s in t]
    return {"mfm_youden_dev": float(np.mean(ys)), "n": len(ys)}


def r22_veredito_m(st: dict) -> str:
    if st.get("M1") == "confirmada":
        extra = " (pfp DEMOVIDO)" if st.get("M2") == "confirmada" else ""
        return "MFM PROMOVIDO COMO LIMIAR VIVO" + extra
    return "LIMIAR FIXO SUFICIENTE (mfm nao replica na familia nova)"


def r22_veredito_l(st: dict) -> str:
    l1 = st.get("L1", "nula")
    l2 = st.get("L2", "nula")
    if l1 == "confirmada" and l2 == "confirmada":
        return "INVERSAO DEFAULT; ALONGAR AJUDA"
    if l1 == "confirmada" and l2 in ("nula", "refutada"):
        return "INVERSAO DEFAULT; ALONGAR SATURA"
    if l1 != "confirmada" and l2 == "confirmada":
        return "ALONGAR AJUDA (sem default k6)"
    return "ONESHOT SUFICIENTE"


def r22_veredito_g(st: dict) -> str:
    g1 = st.get("G1", "nula")
    g2 = st.get("G2", "nula")
    g3 = st.get("G3", "nula")
    if g1 == "confirmada" and (g2 == "confirmada" or g3 == "confirmada"):
        return "FANTASMA AJUDA O MONITOR"
    if g1 == "confirmada":
        return "FANTASMA > ACASO MAS NAO SUPERA PROXY"
    return "FANTASMA NAO AJUDA"


# -*- coding: utf-8 -*-
# [R22] ORQUESTRAÇÃO DO BLOCO 30 + registro/sumário/leigos

def bloco30(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 30 — [R22] MFM VIVO (M) + INVERSÃO DEFAULT/COMPRIMENTO (L) "
               "+ FANTASMA RESIDUAL (G) (9 confirmatórias, 40 sementes, Holm; prereg_r22.txt)")
    desloc = r22_desloc()
    if desloc:
        rep.log(f"[R22_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r22_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R22_NTEST
    n_prop = 12 if rapido else R22_NPROP

    ok_p = hashlib.sha256(PREREG_R22_CORPO.encode("utf-8")).hexdigest() == PREREG_R22_CORPO_SHA256
    rep.log(f"Pré-registro R22: sha256={PREREG_R22_CORPO_SHA256[:16]}… "
            f"{'(CONFERE com versoes/prereg_r22.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R22_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R22_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R22_CORPO_SHA256
        rep.log(f"Adendo 1 R22: sha256={ADENDO1_R22_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")

    hp = dict(R22_HP_FILTRO_CONGELADO)

    # ---- M (mfm live on NEW family) ----
    rep.sub("M — MFM VIVO vs fixed vs pfp (família NOVA ema_shadow/skip_gate/temp_scale × harm_*)")
    if ctx.bg is not None:
        try:
            _bg = ctx.bg.obter("r22a")
            if isinstance(_bg, dict):
                rep.log(f"  sanidade DEV mfm_youden≈{_bg.get('mfm_youden_dev', float('nan')):+.3f} (não altera contrastes)")
        except Exception:
            pass
    scores_M = {c: {"Youden": [], "gain": []} for c in R22_CONDS_M}
    tasks = [("M", c, s, hp) for c in R22_CONDS_M for s in S["M_test"][:n_test]]
    outs = mapa_paralelo(r22_job, tasks, jobs)
    k = 0
    for c in R22_CONDS_M:
        for _ in S["M_test"][:n_test]:
            r = outs[k]; k += 1
            scores_M[c]["Youden"].append(r["Youden"])
            scores_M[c]["gain"].append(r["gain"])
        rep.log(f"  {c}: Youden={float(np.mean(scores_M[c]['Youden'])):+.3f} "
                f"gain={float(np.mean(scores_M[c]['gain'])):+.4f}")
    P_M = {}
    for hname, (a, b, met) in R22_PAR_M.items():
        d = np.asarray(scores_M[a][met]) - np.asarray(scores_M[b][met])
        P_M[hname] = r22_pareado_pack(d, seed=r22_crc(hname))
        rep.log(f"  {hname} ({a}−{b} [{met}]): Δ={P_M[hname]['media']:+.4f} p={P_M[hname]['p']:.4f}")

    # ---- L (inversion default + length) ----
    rep.sub("L — INVERSÃO CL⇄LC no gerador (k=2/6/12) vs oneshot → filtro-simples FIXED")
    scores_L = {c: {"Youden": [], "gain": []} for c in R22_CONDS_L}
    tasks = [("L", c, s, hp) for c in R22_CONDS_L for s in S["L_test"][:n_test]]
    outs = mapa_paralelo(r22_job, tasks, jobs)
    k = 0
    for c in R22_CONDS_L:
        for _ in S["L_test"][:n_test]:
            r = outs[k]; k += 1
            scores_L[c]["Youden"].append(r["Youden"])
            scores_L[c]["gain"].append(r["gain"])
        rep.log(f"  {c}: Youden={float(np.mean(scores_L[c]['Youden'])):+.3f} "
                f"gain={float(np.mean(scores_L[c]['gain'])):+.4f}")
    P_L = {}
    for hname, (a, b, met) in R22_PAR_L.items():
        d = np.asarray(scores_L[a][met]) - np.asarray(scores_L[b][met])
        P_L[hname] = r22_pareado_pack(d, seed=r22_crc(hname))
        rep.log(f"  {hname} ({a}−{b} [{met}]): Δ={P_L[hname]['media']:+.4f} p={P_L[hname]['p']:.4f}")

    # ---- G (ghost residual) ----
    rep.sub("G — INSTÂNCIA FANTASMA (main±a ×/÷ b vs ghost) residual → AUC de monitoramento")
    scores_G = {c: {"AUC": []} for c in R22_CONDS_G}
    tasks = [("G", c, s, hp) for c in R22_CONDS_G for s in S["G_test"][:n_test]]
    outs = mapa_paralelo(r22_job, tasks, jobs)
    k = 0
    for c in R22_CONDS_G:
        for _ in S["G_test"][:n_test]:
            r = outs[k]; k += 1
            scores_G[c]["AUC"].append(r["AUC"])
        rep.log(f"  {c}: AUC={float(np.mean(scores_G[c]['AUC'])):.3f}")
    P_G = {}
    for hname, (a, b, met) in R22_PAR_G.items():
        d = np.asarray(scores_G[a]["AUC"]) - np.asarray(scores_G[b]["AUC"])
        P_G[hname] = r22_pareado_pack(d, seed=r22_crc(hname))
        rep.log(f"  {hname} ({a}−{b} [AUC]): Δ={P_G[hname]['media']:+.4f} p={P_G[hname]['p']:.4f}")

    # ---- Holm ----
    st = {}
    def _holm_pack(Pdict, nomes):
        ps = [Pdict[h]["p"] for h in nomes]
        ph = holm(ps)
        for i, h in enumerate(nomes):
            Pdict[h]["p_holm"] = ph[i]
            st[h] = r22_status(Pdict[h]["media"], ph[i])
            rep.log(f"  status {h}: {st[h]} (p_holm={ph[i]:.4f})")
    _holm_pack(P_M, R22_HIPOT_M)
    _holm_pack(P_L, R22_HIPOT_L)
    _holm_pack(P_G, R22_HIPOT_G)

    ver_m = r22_veredito_m(st)
    ver_l = r22_veredito_l(st)
    ver_g = r22_veredito_g(st)
    rep.log(f"VEREDITO M (regra pré-registrada): {ver_m}")
    rep.log(f"VEREDITO L: {ver_l}")
    rep.log(f"VEREDITO G: {ver_g}")
    if "MFM PROMOVIDO" in ver_m:
        rep.log("→ mfm passa a controlador VIVO padrão de τ_laudo do filtro-simples; pfp demovido do papel de limiar.")
    else:
        rep.log("→ Mantém-se τ_laudo FIXED; mfm permanece disponível como ablação.")
    if "INVERSAO DEFAULT" in ver_l:
        rep.log("→ Inversão CL⇄LC (k=6) entra no caminho DEFAULT do gerador de propostas.")
    rep.log("→ Filtro-primeiro permanece MOTOR; delírio continua explorador opcional. Continua NÃO sendo ASI/AGI.")

    P_all = {}
    P_all.update(P_M); P_all.update(P_L); P_all.update(P_G)
    P_tup = {k: (v["media"], v["lo"], v["hi"], v["p"], v.get("p_holm", v["p"]), v["mde"]) for k, v in P_all.items()}
    n_conf = sum(1 for v in st.values() if v == "confirmada")
    n_ref = sum(1 for v in st.values() if v == "refutada")
    n_nula = sum(1 for v in st.values() if v == "nula")
    rep.log(f"RESUMO R22: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {len(st)}")

    ctx.res["r22"] = {
        "P": P_tup, "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula,
        "ver_m": ver_m, "ver_l": ver_l, "ver_g": ver_g,
        "scores_M": {c: {"Youden": float(np.mean(scores_M[c]["Youden"])),
                         "gain": float(np.mean(scores_M[c]["gain"]))} for c in R22_CONDS_M},
        "scores_L": {c: {"Youden": float(np.mean(scores_L[c]["Youden"])),
                         "gain": float(np.mean(scores_L[c]["gain"]))} for c in R22_CONDS_L},
        "scores_G": {c: {"AUC": float(np.mean(scores_G[c]["AUC"]))} for c in R22_CONDS_G},
        "hp": hp, "desloc": desloc,
        "chaves": list(R22_HIPOT),
    }
    return ctx.res["r22"]


def registro_r22(ctx: Contexto) -> list:
    r = ctx.res.get("r22")
    if not r:
        return []
    L = [f"REGISTRO R22 (BLOCO 30) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de {len(r['chaves'])}"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append(f"  VEREDITO_M={r.get('ver_m')} | VEREDITO_L={r.get('ver_l')} | VEREDITO_G={r.get('ver_g')}")
    return L


