R23_CONGELADO_B64 = "".join(R23_CONGELADO_B64_CHUNKS)

_R23_CONG_CACHE = {"v": None}


def r23_congelado():
    if _R23_CONG_CACHE["v"] is not None:
        return _R23_CONG_CACHE["v"]
    if not R23_CONGELADO_B64 or R23_CONGELADO_SHA256 == "PENDING":
        _R23_CONG_CACHE["v"] = None
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R23_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R23_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R23_CONG_CACHE["v"] = v
    return v


def r23_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if any(os.environ.get(v) for v in R23_ENV_VIVO):
        return False
    cg = r23_congelado()
    return cg is not None and nome in cg


def _dormente23(nome, vivo):
    def w(ctx):
        rot = R23_DORMENTES[nome]
        est = ctx.res.setdefault("r23_dorm", {})
        if r23_dormente_ativo(ctx.args, nome):
            cg = r23_congelado()[nome]
            ctx.rep.log(
                f"[R23 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R22 inalterado "
                f"(--offline --jobs 8, semente 42; sha256 {R23_CONGELADO_SHA256[:12]}… CONFERE; "
                f"origem {R23_CONGELADO_ORIGEM}). Módulos refutados (mfm-limiar/p∈p/fantasma/PN-aberto/tríade/reparo) "
                f"ficam atrás de --reativar-dormentes."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        o0 = {k: len(v) for k, v in ctx.obs.reg.items()}
        vivo(ctx)
        cg = r23_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + (
                "CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)"
            )
            ctx.rep.log(f"[R23 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w



# ======================================================================
# [R23] NÚCLEO + ORQUESTRAÇÃO DO BLOCO 31
# ======================================================================
# -*- coding: utf-8 -*-
# [R23] NÚCLEO DO BLOCO 31 — geração textual auto-recompensada (filtro-primeiro + REINFORCE)
# Depende de símbolos já no asi_metacognitivo.py (holm, np, zlib, os).


R23_NTEST = 40
R23_NDEV = 4
R23_N_TEXTOS_EVAL = 32
R23_L = 24  # tokens por texto
R23_V = 64  # vocab size

R23_SEEDS_S_DEV = list(range(26100, 26116))
R23_SEEDS_S_TEST = list(range(26200, 26240))

R23_METODOS = (
    "aleatorio", "guloso_markov", "rl_ordinario", "rl_extraord",
    "filtro_so_prop", "delirio_prop",
)
R23_HIPOT_S = ("S1", "S2", "S3", "S4", "S5")  # S6 informativa
R23_PAR_S = {
    "S1": ("rl_ordinario", "aleatorio", "r_clean"),
    "S2": ("rl_ordinario", "guloso_markov", "r_clean"),
    "S3": ("rl_extraord", "rl_ordinario", "r_clean"),
    "S4": ("rl_ordinario", "filtro_so_prop", "r_clean"),
    "S5": ("filtro_so_prop", "delirio_prop", "r_clean"),
}

R23_HP_FILTRO = {"tau_tela": 0.40, "tau_laudo": 0.55, "T_hi": 1.5, "T_lo": 0.3}
R23_SIGMA_CAMUF = 0.08
R23_DELTA_CAMUF = 0.05
R23_BETA_EXTRA = 0.50


def r23_desloc() -> int:
    v = os.environ.get("R23_DEV")
    if not v or v in ("0", "false", "False", "no", "off", ""):
        return 0
    return 10000


def r23_crc(rot: str) -> int:
    return zlib.crc32(f"R23|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r23_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


def r23_sementes(desloc=0):
    d = int(desloc)
    return {
        "S_dev": [s + d for s in R23_SEEDS_S_DEV],
        "S_test": [s + d for s in R23_SEEDS_S_TEST],
    }


# ---------- léxico fechado determinístico ----------
_VOGAIS = "aeiou"
_CONS = "bcdfghjklmnpqrstvwxz"


def r23_vocab(seed_lex: int = 0):
    """64 tokens: 48 sílabas CV + 16 'palavras' compostas; ordem fixa."""
    rng = r23_rng(seed_lex, r23_crc("vocab"), 7)
    toks = []
    for c in _CONS:
        for v in _VOGAIS:
            toks.append(c + v)
            if len(toks) >= 48:
                break
        if len(toks) >= 48:
            break
    # 16 compostos determinísticos
    for i in range(16):
        a = toks[int(rng.integers(0, 48))]
        b = toks[int(rng.integers(0, 48))]
        toks.append(a + b)
    assert len(toks) == R23_V
    return toks


def r23_markov2(vocab, seed_lex: int = 0):
    """Transições bigrama plantadas: diagonal dominante + vizinhança silábica."""
    rng = r23_rng(seed_lex, r23_crc("markov2"), 11)
    V = len(vocab)
    M = np.full((V, V), 1.0 / V, dtype=np.float64)
    for i in range(V):
        M[i, i] += 3.0
        M[i, (i + 1) % V] += 1.5
        M[i, (i - 1) % V] += 1.5
        # same first char bonus
        ci = vocab[i][0]
        for j in range(V):
            if vocab[j][0] == ci:
                M[i, j] += 0.8
        M[i] += rng.random(V) * 0.05
        M[i] /= M[i].sum()
    return M


def r23_fluencia(texto_ids, M) -> float:
    if len(texto_ids) < 2:
        return 0.0
    s = 0.0
    for a, b in zip(texto_ids[:-1], texto_ids[1:]):
        s += float(M[int(a), int(b)])
    return s / (len(texto_ids) - 1)


def r23_diversidade(texto_ids) -> float:
    return len(set(int(x) for x in texto_ids)) / max(len(texto_ids), 1)


# ---------- crítico filtro-primeiro ----------
def r23_proxy_texto(texto_ids, M) -> float:
    flu = r23_fluencia(texto_ids, M)
    div = r23_diversidade(texto_ids)
    # coerência: fração de bigramas acima da mediana da linha
    if len(texto_ids) < 2:
        coh = 0.0
    else:
        ok = 0
        for a, b in zip(texto_ids[:-1], texto_ids[1:]):
            med = float(np.median(M[int(a)]))
            ok += 1 if M[int(a), int(b)] >= med else 0
        coh = ok / (len(texto_ids) - 1)
    return float(np.clip(0.45 * flu / 0.12 + 0.25 * div + 0.30 * coh, 0.0, 1.0))


def r23_laudo_texto(texto_ids, M, seed: int, i: int) -> dict:
    """Comitê V1..V4; score_laudo em [0,1]; limiares externos decidem aceite."""
    rng = r23_rng(seed, r23_crc("laudo"), i + 3)
    proxy = r23_proxy_texto(texto_ids, M)
    flu = r23_fluencia(texto_ids, M)
    div = r23_diversidade(texto_ids)
    V1 = flu >= 0.055                     # fluência mínima
    V2 = div >= 0.25                      # não colapsar a 1 token
    V3 = proxy >= 0.40
    # V4: checagem ruidosa de 'estrutura' (reprodutível)
    h = (zlib.crc32(bytes(int(x) & 0xFF for x in texto_ids)) & 0xFFFF) / 65535.0
    V4 = (0.6 * proxy + 0.4 * h) > 0.42
    if rng.random() < 0.06:
        V1 = not V1
    if rng.random() < 0.05:
        V3 = not V3
    score = 0.0
    score += 0.30 if V1 else 0.0
    score += 0.20 if V2 else 0.0
    score += 0.30 if V3 else 0.0
    score += 0.20 if V4 else 0.0
    score = 0.70 * score + 0.30 * proxy + float(rng.normal(0, 0.02))
    return {
        "V1": bool(V1), "V2": bool(V2), "V3": bool(V3), "V4": bool(V4),
        "proxy": float(proxy), "flu": float(flu), "div": float(div),
        "score_laudo": float(np.clip(score, 0.0, 1.0)),
    }


def r23_filtro_primeiro(texto_ids, M, seed: int, i: int, hp=None) -> dict:
    hp = hp or R23_HP_FILTRO
    r = r23_laudo_texto(texto_ids, M, seed, i)
    if r["proxy"] < float(hp["tau_tela"]):
        r["mantem"] = False
        return r
    r["mantem"] = r["score_laudo"] >= float(hp["tau_laudo"])
    return r


def r23_r_clean(texto_ids, M) -> float:
    """Métrica LIMPA retida: fluência verdadeira + proxy sem ruído de laudo."""
    flu = r23_fluencia(texto_ids, M)
    proxy = r23_proxy_texto(texto_ids, M)
    div = r23_diversidade(texto_ids)
    return float(np.clip(0.50 * (flu / 0.12) + 0.35 * proxy + 0.15 * div, 0.0, 1.5))


def r23_r_train(texto_ids, M, seed: int, i: int, hp=None) -> float:
    """Recompensa CAMUFLADA de treino (inexata de propósito)."""
    r = r23_filtro_primeiro(texto_ids, M, seed, i, hp)
    base = float(r["score_laudo"])
    rng = r23_rng(seed, r23_crc("camuf"), i + 17)
    ruido = float(rng.normal(0, R23_SIGMA_CAMUF))
    h = (zlib.crc32(bytes(int(x) & 0xFF for x in texto_ids)) & 0xFFFF) / 65535.0
    camuf = R23_DELTA_CAMUF * (h - 0.5)
    return float(base + ruido + camuf)


# ---------- política linear + REINFORCE ----------
def r23_policy_init(rng, M=None):
    # W[prev_token, next_token] + bias[next]; warm-start from log-Markov when given
    W = rng.normal(0, 0.02, size=(R23_V, R23_V))
    b = rng.normal(0, 0.01, size=(R23_V,))
    if M is not None:
        W = W + 0.85 * np.log(np.asarray(M, dtype=float) + 1e-12)
        W -= W.mean(axis=1, keepdims=True)
    return {"W": W, "b": b}


def r23_softmax(logits):
    z = logits - np.max(logits)
    e = np.exp(np.clip(z, -60, 60))
    return e / (e.sum() + 1e-12)


def r23_sample_policy(pol, M, rng, L=R23_L, temp=1.0):
    ids = []
    logps = []
    prev = int(rng.integers(0, R23_V))
    ids.append(prev)
    for _ in range(L - 1):
        logits = pol["W"][prev] + pol["b"]
        if temp != 1.0:
            logits = logits / max(temp, 1e-3)
        # leve prior markov (estabilidade)
        logits = logits + 0.55 * np.log(M[prev] + 1e-12)
        p = r23_softmax(logits)
        nxt = int(rng.choice(R23_V, p=p))
        logps.append(float(np.log(p[nxt] + 1e-12)))
        ids.append(nxt)
        prev = nxt
    return ids, logps


def r23_sample_uniform(rng, L=R23_L):
    ids = [int(x) for x in rng.integers(0, R23_V, size=L)]
    return ids, [0.0] * (L - 1)


def r23_sample_markov(M, rng, L=R23_L):
    ids = [int(rng.integers(0, R23_V))]
    logps = []
    for _ in range(L - 1):
        p = M[ids[-1]]
        nxt = int(rng.choice(R23_V, p=p))
        logps.append(float(np.log(p[nxt] + 1e-12)))
        ids.append(nxt)
    return ids, logps


def r23_reinforce_update(pol, ids, logps, advantage, lr, extraordinario=False):
    """REINFORCE on linear logits; extraordinary amplifies negative advantages."""
    if not logps:
        return 0.0
    adv = float(advantage)
    if extraordinario:
        if adv < 0:
            adv = adv * (1.0 + R23_BETA_EXTRA)
        else:
            adv = adv * (1.0 - R23_BETA_EXTRA / 2.0)
    # gradient proxy: for each step, push chosen token by adv
    for t, (prev, nxt) in enumerate(zip(ids[:-1], ids[1:])):
        g = lr * adv
        pol["W"][prev, nxt] += g
        pol["b"][nxt] += g * 0.5
        # soft normalize row to avoid explosion
        pol["W"][prev] -= pol["W"][prev].mean()
    return adv


def r23_treinar_rl(metodo: str, seed: int, hp: dict, passos: int, lr: float):
    vocab = r23_vocab(0)
    M = r23_markov2(vocab, 0)
    rng = r23_rng(seed, r23_crc(f"train|{metodo}"), 5)
    pol = r23_policy_init(rng, M=M)
    baseline = 0.0
    hist = []
    extra = metodo == "rl_extraord"
    for t in range(passos):
        ids, logps = r23_sample_policy(pol, M, rng, L=R23_L, temp=1.0)
        r = r23_r_train(ids, M, seed, t, R23_HP_FILTRO)
        adv = r - baseline
        baseline = 0.9 * baseline + 0.1 * r
        r23_reinforce_update(pol, ids, logps, adv, lr, extraordinario=extra)
        hist.append(r)
    return {"pol": pol, "M": M, "vocab": vocab, "baseline": baseline,
            "r_train_mean": float(np.mean(hist[-20:])) if hist else 0.0}


def r23_eval_metodo(metodo: str, seed: int, hp: dict, n_textos: int = R23_N_TEXTOS_EVAL) -> dict:
    """Avalia um método; retorna r_clean médio e r_train_eval (camuflado) médio."""
    vocab = r23_vocab(0)
    M = r23_markov2(vocab, 0)
    rng = r23_rng(seed, r23_crc(f"eval|{metodo}"), 13)
    hp = dict(hp or {})
    passos = int(hp.get("passos", 120))
    lr = float(hp.get("lr", 0.10))

    pol = None
    if metodo in ("rl_ordinario", "rl_extraord"):
        tr = r23_treinar_rl(metodo, seed, hp, passos=passos, lr=lr)
        pol = tr["pol"]
        M = tr["M"]

    cleans = []
    trains = []
    kept = 0
    for i in range(n_textos):
        if metodo == "aleatorio":
            ids, _ = r23_sample_uniform(rng, L=R23_L)
        elif metodo == "guloso_markov":
            ids, _ = r23_sample_markov(M, rng, L=R23_L)
        elif metodo in ("rl_ordinario", "rl_extraord"):
            ids, _ = r23_sample_policy(pol, M, rng, L=R23_L, temp=1.0)
        elif metodo == "filtro_so_prop":
            # sample markov candidates, keep best by filter-first score_laudo
            best, best_s = None, -1e9
            for k in range(6):
                cand, _ = r23_sample_markov(M, rng, L=R23_L)
                rr = r23_filtro_primeiro(cand, M, seed, i * 10 + k)
                if rr["score_laudo"] > best_s:
                    best_s = rr["score_laudo"]
                    best = cand
            ids = best
        elif metodo == "delirio_prop":
            # high-temp policy noise + forced exit (cool) + same filter
            best, best_s = None, -1e9
            for k in range(6):
                # delírio: amostra com temp alta misturando uniforme
                ids_hi = []
                prev = int(rng.integers(0, R23_V))
                ids_hi.append(prev)
                for _ in range(R23_L - 1):
                    if rng.random() < 0.45:
                        nxt = int(rng.integers(0, R23_V))
                    else:
                        p = M[prev] ** (1.0 / R23_HP_FILTRO["T_hi"])
                        p = p / p.sum()
                        nxt = int(rng.choice(R23_V, p=p))
                    ids_hi.append(nxt)
                    prev = nxt
                # saída forçada: um passo de polishing markov guloso parcial
                ids_cool = list(ids_hi)
                for t in range(1, R23_L):
                    if rng.random() < 0.25:
                        ids_cool[t] = int(np.argmax(M[ids_cool[t - 1]]))
                rr = r23_filtro_primeiro(ids_cool, M, seed, i * 10 + k)
                if rr["score_laudo"] > best_s:
                    best_s = rr["score_laudo"]
                    best = ids_cool
            ids = best
        else:
            raise ValueError(metodo)
        cleans.append(r23_r_clean(ids, M))
        trains.append(r23_r_train(ids, M, seed, 1000 + i))
        fr = r23_filtro_primeiro(ids, M, seed, 2000 + i)
        if fr["mantem"]:
            kept += 1
    return {
        "r_clean": float(np.mean(cleans)),
        "r_train_eval": float(np.mean(trains)),
        "keep_rate": kept / max(n_textos, 1),
        "metodo": metodo,
        "seed": int(seed),
    }


def r23_ajustar(metodo: str, seeds_dev, n_sort: int = 6) -> dict:
    """Orçamento igual: n_sort configs × len(seeds_dev) evals; escolhe por r_clean DEV."""
    rng = r23_rng(r23_crc(f"ajuste|{metodo}"), 21)
    grade = []
    for _ in range(n_sort):
        grade.append({
            "passos": int(rng.choice([80, 160])),
            "lr": float(rng.choice([0.05, 0.15])),
        })
    # métodos sem treino: hp dummy único
    if metodo in ("aleatorio", "guloso_markov", "filtro_so_prop", "delirio_prop"):
        grade = [{"passos": 80, "lr": 0.10}]
    best, best_sc = None, -1e9
    for hp in grade:
        scs = [r23_eval_metodo(metodo, s, hp, n_textos=12)["r_clean"] for s in seeds_dev]
        m = float(np.mean(scs))
        if m > best_sc:
            best_sc = m
            best = dict(hp)
    return best or {"passos": 120, "lr": 0.10}


def r23_pareado_pack(diffs, seed=0):
    d = np.asarray(diffs, dtype=float)
    n = len(d)
    media = float(d.mean()) if n else 0.0
    rng = r23_rng(seed, r23_crc("pareado"), 3)
    if n == 0:
        return {"media": 0.0, "lo": 0.0, "hi": 0.0, "p": 1.0, "mde": 0.0}
    # sign-flip permutation
    B = 10000
    abs0 = abs(media)
    cnt = 0
    for _ in range(B):
        s = rng.choice([-1.0, 1.0], size=n)
        if abs(float((d * s).mean())) >= abs0 - 1e-15:
            cnt += 1
    p = (cnt + 1) / (B + 1)
    # bootstrap IC
    boots = []
    for _ in range(2000):
        idx = rng.integers(0, n, size=n)
        boots.append(float(d[idx].mean()))
    lo, hi = float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))
    sd = float(d.std(ddof=1)) if n > 1 else 0.0
    mde = 2.8 * sd / max(n ** 0.5, 1.0)
    return {"media": media, "lo": lo, "hi": hi, "p": float(p), "mde": float(mde)}


def r23_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05:
        if media * sinal_esperado > 0:
            return "confirmada"
        return "refutada"
    return "nula"


def r23_veredito_s(st: dict) -> str:
    s1 = st.get("S1") == "confirmada"
    s2 = st.get("S2") == "confirmada"
    s4 = st.get("S4") == "confirmada"
    s3 = st.get("S3") == "confirmada"
    s5 = st.get("S5")
    if s1 and (s2 or s4):
        base = "AUTO-RECOMPENSA SINALIZA"
    elif s1:
        base = "APRENDE MAS NAO SUPERA BASELINES"
    else:
        base = "AUTO-RECOMPENSA NULA"
    if s3:
        base += "; EXTRAORDINARIO AJUDA"
    if s5 == "refutada":
        base += "; DELIRIO ACRESCENTA"
    return base


def r23_job(task):
    """task = (metodo, seed, hp) → dict com r_clean / r_train_eval."""
    metodo, seed, hp = task
    return r23_eval_metodo(metodo, seed, hp, n_textos=R23_N_TEXTOS_EVAL)


def r23_tarefas(ctx):
    """Sanidade DEV em segundo plano (não altera contrastes registrados)."""
    desloc = r23_desloc()
    S = r23_sementes(desloc)
    def _fn():
        hp = r23_ajustar("rl_ordinario", S["S_dev"][:2], n_sort=2)
        ev = r23_eval_metodo("rl_ordinario", S["S_dev"][0], hp, n_textos=8)
        return {"rl_clean_dev": ev["r_clean"], "hp": hp}
    return _fn, ()


