# [R23] ORQUESTRAÇÃO DO BLOCO 31 + dormência 27–30 + registro/sumário/leigos

def bloco31(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 31 — [R23] GERAÇÃO TEXTUAL AUTO-RECOMPENSADA "
               "(crítico filtro-primeiro + REINFORCE ordinário×extraordinário; "
               "6 confirmatórias/informativas, 40 sementes, Holm; prereg_r23.txt)")
    desloc = r23_desloc()
    if desloc:
        rep.log(f"[R23_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r23_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R23_NTEST
    n_sort = 2 if rapido else 6

    ok_p = hashlib.sha256(PREREG_R23_CORPO.encode("utf-8")).hexdigest() == PREREG_R23_CORPO_SHA256
    rep.log(f"Pré-registro R23: sha256={PREREG_R23_CORPO_SHA256[:16]}… "
            f"{'(CONFERE com versoes/prereg_r23.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R23_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R23_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R23_CORPO_SHA256
        rep.log(f"Adendo 1 R23: sha256={ADENDO1_R23_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")

    rep.log("ARQUITETURA TRAVADA: filtro-primeiro + τ_laudo FIXED; delírio = explorador opcional; "
            "mfm/pfp/fantasma/tríade/reparo/PN-aberto = DORMENTES (R18–R22).")
    rep.log(f"  hp filtro congelado: {R23_HP_FILTRO}")

    # ajuste DEV (orçamento igual)
    rep.sub("S — ajuste DEV (orçamento igual) e avaliação TESTE (r_clean limpo)")
    if ctx.bg is not None:
        try:
            _bg = ctx.bg.obter("r23a")
            if isinstance(_bg, dict):
                rep.log(f"  sanidade DEV rl_clean≈{_bg.get('rl_clean_dev', float('nan')):+.3f} (não altera contrastes)")
        except Exception:
            pass

    hp_S = {}
    for met in R23_METODOS:
        hp_S[met] = r23_ajustar(met, S["S_dev"][:R23_NDEV], n_sort=n_sort)
        rep.log(f"  ajuste {met}: {hp_S[met]}")

    scores = {m: {"r_clean": [], "r_train_eval": [], "keep_rate": []} for m in R23_METODOS}
    tasks = [(m, s, hp_S[m]) for m in R23_METODOS for s in S["S_test"][:n_test]]
    outs = mapa_paralelo(r23_job, tasks, jobs)
    k = 0
    for m in R23_METODOS:
        for _ in S["S_test"][:n_test]:
            r = outs[k]; k += 1
            scores[m]["r_clean"].append(r["r_clean"])
            scores[m]["r_train_eval"].append(r["r_train_eval"])
            scores[m]["keep_rate"].append(r["keep_rate"])
        rep.log(f"  {m}: r_clean={float(np.mean(scores[m]['r_clean'])):+.4f} "
                f"r_train_eval={float(np.mean(scores[m]['r_train_eval'])):+.4f} "
                f"keep={float(np.mean(scores[m]['keep_rate'])):.3f}")

    P_S = {}
    for hname, (a, b, met) in R23_PAR_S.items():
        d = np.asarray(scores[a][met]) - np.asarray(scores[b][met])
        P_S[hname] = r23_pareado_pack(d, seed=r23_crc(hname))
        rep.log(f"  {hname} ({a}−{b} [{met}]): Δ={P_S[hname]['media']:+.4f} p={P_S[hname]['p']:.4f}")

    # S6 informativa (camuflagem vs limpa no mesmo método rl_ordinario)
    d6 = np.asarray(scores["rl_ordinario"]["r_clean"]) - np.asarray(scores["rl_ordinario"]["r_train_eval"])
    P_S6 = r23_pareado_pack(d6, seed=r23_crc("S6"))
    rep.log(f"  S6 (rl_ordinario r_clean − r_train_eval) INFORMATIVA: Δ={P_S6['media']:+.4f} p={P_S6['p']:.4f}")

    # Holm S1–S5
    st = {}
    ps = [P_S[h]["p"] for h in R23_HIPOT_S]
    ph = holm(ps)
    for i, h in enumerate(R23_HIPOT_S):
        P_S[h]["p_holm"] = ph[i]
        st[h] = r23_status(P_S[h]["media"], ph[i], sinal_esperado=1)
        rep.log(f"  status {h}: {st[h]} (p_holm={ph[i]:.4f})")
    st["S6"] = "informativa"
    P_S["S6"] = P_S6
    P_S["S6"]["p_holm"] = P_S6["p"]

    ver_s = r23_veredito_s(st)
    rep.log(f"VEREDITO S (regra pré-registrada): {ver_s}")
    if "SINALIZA" in ver_s:
        rep.log("→ Há sinal de aprendizado por auto-recompensa sob crítico filtro-primeiro; "
                "avaliado na métrica LIMPA (a camuflagem ficou só no treino).")
    else:
        rep.log("→ Sem sinal robusto além dos baselines; honest null aceitável.")
    rep.log("→ Filtro-primeiro permanece MOTOR; delírio continua explorador opcional. Continua NÃO sendo ASI/AGI.")
    rep.log("→ Módulos dormentes R18–R22: mfm-limiar, p∈p-limiar, fantasma, PN-aberto, tríade, reparo mútuo.")

    P_tup = {k: (v["media"], v["lo"], v["hi"], v["p"], v.get("p_holm", v["p"]), v["mde"]) for k, v in P_S.items()}
    n_conf = sum(1 for h in R23_HIPOT_S if st.get(h) == "confirmada")
    n_ref = sum(1 for h in R23_HIPOT_S if st.get(h) == "refutada")
    n_nula = sum(1 for h in R23_HIPOT_S if st.get(h) == "nula")
    rep.log(f"RESUMO R23: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {len(R23_HIPOT_S)} (S6 informativa)")

    ctx.res["r23"] = {
        "P": P_tup, "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula,
        "ver_s": ver_s,
        "scores": {m: {"r_clean": float(np.mean(scores[m]["r_clean"])),
                       "r_train_eval": float(np.mean(scores[m]["r_train_eval"])),
                       "keep_rate": float(np.mean(scores[m]["keep_rate"]))} for m in R23_METODOS},
        "hp": hp_S, "desloc": desloc,
        "chaves": list(R23_HIPOT_S) + ["S6"],
        "dormentes": ["mfm-limiar", "pfp-limiar", "fantasma", "PN-aberto", "triade", "reparo_mutuo",
                      "bloco27", "bloco28", "bloco29", "bloco30"],
    }
    return ctx.res["r23"]


def registro_r23(ctx: Contexto) -> list:
    r = ctx.res.get("r23")
    if not r:
        return []
    L = [f"REGISTRO R23 (BLOCO 31) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de 5 (+S6 info)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append(f"  VEREDITO_S={r.get('ver_s')}")
    L.append(f"  DORMENTES={','.join(r.get('dormentes') or [])}")
    return L


