R24_SIGMA_CAMUF = 0.08
R24_DELTA_CAMUF = 0.05
R24_BETA_EXTRA = 0.50


def r24_desloc() -> int:
    v = os.environ.get("R24_DEV")
    if not v or v in ("0", "false", "False", "no", "off", ""):
        return 0
    return 10000


def r24_crc(rot: str) -> int:
    return zlib.crc32(f"R24|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r24_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


def r24_sementes(desloc=0):
    d = int(desloc)
    return {
        "dev": [s + d for s in R24_SEEDS_DEV],
        "test": [s + d for s in R24_SEEDS_TEST],
    }


_VOGAIS = "aeiou"
_CONS = "bcdfghjklmnpqrstvwxz"


def r24_vocab(V: int, seed_lex: int = 0):
    rng = r24_rng(seed_lex, r24_crc(f"vocab|{V}"), 7)
    toks = []
    for c in _CONS:
        for v in _VOGAIS:
            toks.append(c + v)
            if len(toks) >= max(1, V - V // 4):
                break
        if len(toks) >= max(1, V - V // 4):
            break
    base_n = len(toks)
    while len(toks) < V:
        a = toks[int(rng.integers(0, base_n))]
        b = toks[int(rng.integers(0, base_n))]
        toks.append(a + b)
    assert len(toks) == V
    return toks


def r24_markov2(vocab, seed_lex: int = 0, hard: bool = True):
    """HARD: diagonal menos dominante + mais ruído."""
    rng = r24_rng(seed_lex, r24_crc(f"markov2|{'H' if hard else 'E'}|{len(vocab)}"), 11)
    V = len(vocab)
    M = np.full((V, V), 1.0 / V, dtype=np.float64)
    diag = 1.6 if hard else 3.0
    neigh = 0.9 if hard else 1.5
    noise = 0.18 if hard else 0.05
    same = 0.4 if hard else 0.8
    for i in range(V):
        M[i, i] += diag
        M[i, (i + 1) % V] += neigh
        M[i, (i - 1) % V] += neigh
        ci = vocab[i][0]
        for j in range(V):
            if vocab[j][0] == ci:
                M[i, j] += same
        M[i] += rng.random(V) * noise
        M[i] /= M[i].sum()
    return M


def r24_fluencia(texto_ids, M) -> float:
    if len(texto_ids) < 2:
        return 0.0
    s = 0.0
    for a, b in zip(texto_ids[:-1], texto_ids[1:]):
        s += float(M[int(a), int(b)])
    return s / (len(texto_ids) - 1)


def r24_diversidade(texto_ids) -> float:
    return len(set(int(x) for x in texto_ids)) / max(len(texto_ids), 1)


def r24_proxy_texto(texto_ids, M) -> float:
    flu = r24_fluencia(texto_ids, M)
    div = r24_diversidade(texto_ids)
    if len(texto_ids) < 2:
        coh = 0.0
    else:
        ok = 0
        for a, b in zip(texto_ids[:-1], texto_ids[1:]):
            med = float(_r26_med_rows(M)[int(a)])      # [R26/perf] cache das medianas por linha (bit-idêntico a np.median(M[a]))
            ok += 1 if M[int(a), int(b)] >= med else 0
        coh = ok / (len(texto_ids) - 1)
    # HARD: fluência tipicamente menor → normalizador mais frouxo
    return float(np.clip(0.45 * flu / 0.09 + 0.25 * div + 0.30 * coh, 0.0, 1.0))


def r24_laudo_texto(texto_ids, M, seed: int, i: int) -> dict:
    rng = r24_rng(seed, r24_crc("laudo"), i + 3)
    proxy = r24_proxy_texto(texto_ids, M)
    flu = r24_fluencia(texto_ids, M)
    div = r24_diversidade(texto_ids)
    V1 = flu >= 0.040
    V2 = div >= 0.20
    V3 = proxy >= 0.38
    h = (zlib.crc32(bytes(int(x) & 0xFF for x in texto_ids)) & 0xFFFF) / 65535.0
    V4 = (0.6 * proxy + 0.4 * h) > 0.40
    if rng.random() < 0.06:
        V1 = not V1
    if rng.random() < 0.05:
        V3 = not V3
    score = 0.0
    score += 0.30 if V1 else 0.0
    score += 0.20 if V2 else 0.0
    score += 0.30 if V3 else 0.0
    score += 0.20 if V4 else 0.0
    score = 0.70 * score + 0.30 * proxy + float(rng.normal(0, 0.02))
    return {
        "V1": bool(V1), "V2": bool(V2), "V3": bool(V3), "V4": bool(V4),
        "proxy": float(proxy), "flu": float(flu), "div": float(div),
        "score_laudo": float(np.clip(score, 0.0, 1.0)),
    }


def r24_filtro_primeiro(texto_ids, M, seed: int, i: int, hp=None) -> dict:
    hp = hp or R24_HP_FILTRO
    r = r24_laudo_texto(texto_ids, M, seed, i)
    if r["proxy"] < float(hp["tau_tela"]):
        r["mantem"] = False
        return r
    r["mantem"] = r["score_laudo"] >= float(hp["tau_laudo"])
    return r


def r24_r_clean(texto_ids, M) -> float:
    flu = r24_fluencia(texto_ids, M)
    proxy = r24_proxy_texto(texto_ids, M)
    div = r24_diversidade(texto_ids)
    return float(np.clip(0.50 * (flu / 0.09) + 0.35 * proxy + 0.15 * div, 0.0, 1.5))


def r24_r_train(texto_ids, M, seed: int, i: int, hp=None) -> float:
    r = r24_filtro_primeiro(texto_ids, M, seed, i, hp)
    base = float(r["score_laudo"])
    rng = r24_rng(seed, r24_crc("camuf"), i + 17)
    ruido = float(rng.normal(0, R24_SIGMA_CAMUF))
    h = (zlib.crc32(bytes(int(x) & 0xFF for x in texto_ids)) & 0xFFFF) / 65535.0
    camuf = R24_DELTA_CAMUF * (h - 0.5)
    return float(base + ruido + camuf)


def r24_features(texto_ids, M, seed: int, i: int) -> np.ndarray:
    r = r24_filtro_primeiro(texto_ids, M, seed, i)
    flu = r24_fluencia(texto_ids, M)
    div = r24_diversidade(texto_ids)
    return np.asarray([flu, div, r["proxy"], r["score_laudo"], 1.0], dtype=np.float64)


def r24_softmax(logits):
    z = logits - np.max(logits)
    e = np.exp(np.clip(z, -60, 60))
    return e / (e.sum() + 1e-12)


def r24_policy_init(rng, V, M=None):
    W = rng.normal(0, 0.02, size=(V, V))
    b = rng.normal(0, 0.01, size=(V,))
    if M is not None:
        W = W + 0.85 * np.log(np.asarray(M, dtype=float) + 1e-12)
        W -= W.mean(axis=1, keepdims=True)
    return {"W": W, "b": b, "V": V}


def r24_sample_policy(pol, M, rng, L, temp=1.0):
    V = pol["V"]
    ids = []
    logps = []
    prev = int(rng.integers(0, V))
    ids.append(prev)
    for _ in range(L - 1):
        logits = pol["W"][prev] + pol["b"]
        if temp != 1.0:
            logits = logits / max(temp, 1e-3)
        logits = logits + 0.55 * np.log(M[prev] + 1e-12)
        p = r24_softmax(logits)
        nxt = int(rng.choice(V, p=p))
        logps.append(float(np.log(p[nxt] + 1e-12)))
        ids.append(nxt)
        prev = nxt
    return ids, logps


def r24_sample_uniform(rng, V, L):
    ids = [int(x) for x in rng.integers(0, V, size=L)]
    return ids, [0.0] * (L - 1)


def r24_sample_markov(M, rng, L):
    V = M.shape[0]
    ids = [int(rng.integers(0, V))]
    logps = []
    for _ in range(L - 1):
        p = M[ids[-1]]
        nxt = int(rng.choice(V, p=p))
        logps.append(float(np.log(p[nxt] + 1e-12)))
        ids.append(nxt)
    return ids, logps


def r24_reinforce_update(pol, ids, logps, advantage, lr, extraordinario=False, peso=1.0):
    if not logps:
        return 0.0
    adv = float(advantage) * float(peso)
    if extraordinario:
        if adv < 0:
            adv = adv * (1.0 + R24_BETA_EXTRA)
        else:
            adv = adv * (1.0 - R24_BETA_EXTRA / 2.0)
    for prev, nxt in zip(ids[:-1], ids[1:]):
        g = lr * adv
        pol["W"][prev, nxt] += g
        pol["b"][nxt] += g * 0.5
        pol["W"][prev] -= pol["W"][prev].mean()
    return adv


def r24_resize_policy(pol_src, V_dst, M_dst, rng):
    """Redimensiona política EASY→HARD (média por bloco / pad com log-Markov)."""
    V_src = pol_src["V"]
    W = np.zeros((V_dst, V_dst), dtype=float)
    b = np.zeros(V_dst, dtype=float)
    # map src indices → dst by modulo / block average
    for i in range(V_dst):
        isrc = i % V_src
        for j in range(V_dst):
            jsrc = j % V_src
            W[i, j] = pol_src["W"][isrc, jsrc]
        b[i] = pol_src["b"][isrc]
    # blend with log-Markov of HARD
    W = 0.65 * W + 0.35 * np.log(np.asarray(M_dst, dtype=float) + 1e-12)
    W += rng.normal(0, 0.01, size=W.shape)
    W -= W.mean(axis=1, keepdims=True)
    return {"W": W, "b": b, "V": V_dst}


def r24_treinar_rl(metodo: str, seed: int, hp: dict, passos: int, lr: float,
                   L=None, V=None, hard=True, peso_fn=None, init_pol=None):
    L = int(L if L is not None else R24_L_HARD)
    V = int(V if V is not None else R24_V_HARD)
    vocab = r24_vocab(V, 0)
    M = r24_markov2(vocab, 0, hard=hard)
    rng = r24_rng(seed, r24_crc(f"train|{metodo}|{L}|{V}"), 5)
    pol = init_pol if init_pol is not None else r24_policy_init(rng, V, M=M)
    baseline = 0.0
    hist = []
    feats_hist = []
    y_hist = []
    extra = "extraord" in metodo
    for t in range(passos):
        ids, logps = r24_sample_policy(pol, M, rng, L=L, temp=1.0)
        r = r24_r_train(ids, M, seed, t)
        adv = r - baseline
        baseline = 0.9 * baseline + 0.1 * r
        peso = 1.0
        if peso_fn is not None:
            peso = float(peso_fn(ids, M, seed, t))
        r24_reinforce_update(pol, ids, logps, adv, lr, extraordinario=extra, peso=peso)
        hist.append(r)
        phi = r24_features(ids, M, seed, t)
        y = 1.0 if r24_r_clean(ids, M) >= R24_HP_FILTRO["tau_laudo"] else 0.0
        feats_hist.append(phi)
        y_hist.append(y)
    return {
        "pol": pol, "M": M, "vocab": vocab, "baseline": baseline,
        "r_train_mean": float(np.mean(hist[-20:])) if hist else 0.0,
        "feats": np.asarray(feats_hist) if feats_hist else np.zeros((0, 5)),
        "ys": np.asarray(y_hist, dtype=float) if y_hist else np.zeros(0),
    }


def r24_fit_logreg(X, y, seed=0, passos=80, lr=0.3):
    """Logística simples w∈R^d; retorna w."""
    rng = r24_rng(seed, r24_crc("logreg"), 9)
    X = np.asarray(X, dtype=float)
    y = np.asarray(y, dtype=float)
    if len(X) < 4:
        return np.zeros(X.shape[1] if X.ndim == 2 else 5)
    d = X.shape[1]
    w = rng.normal(0, 0.05, size=d)
    for _ in range(passos):
        z = X @ w
        p = 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
        g = X.T @ (p - y) / max(len(y), 1) + 1e-3 * w
        w = w - lr * g
    return w


def r24_predict_p(w, X, T=1.0):
    z = np.asarray(X, dtype=float) @ np.asarray(w, dtype=float)
    return 1.0 / (1.0 + np.exp(-np.clip(z / max(T, 1e-3), -40, 40)))


def r24_ece(p, y, bins=8) -> float:
    p = np.asarray(p, dtype=float)
    y = np.asarray(y, dtype=float)
    if len(p) == 0:
        return 1.0
    edges = np.linspace(0, 1, bins + 1)
    tot = 0.0
    n = len(p)
    for i in range(bins):
        lo, hi = edges[i], edges[i + 1]
        m = (p >= lo) & (p < hi if i < bins - 1 else p <= hi)
        if not np.any(m):
            continue
        tot += (m.sum() / n) * abs(p[m].mean() - y[m].mean())
    return float(tot)


def r24_escolher_T(w, X, y, candidatos=None):
    candidatos = candidatos or [0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 3.0]
    best_T, best_e = 1.0, 1e9
    for T in candidatos:
        e = r24_ece(r24_predict_p(w, X, T=T), y, bins=8)
        if e < best_e:
            best_e, best_T = e, T
    return float(best_T)


def r24_eval_texto(metodo: str, seed: int, hp: dict, n_textos: int = R24_N_TEXTOS_EVAL,
                   meta_w=None, meta_T=1.0) -> dict:
    """Avalia método textual HARD (ou transfer)."""
    L, V = R24_L_HARD, R24_V_HARD
    vocab = r24_vocab(V, 0)
    M = r24_markov2(vocab, 0, hard=True)
    rng = r24_rng(seed, r24_crc(f"eval|{metodo}"), 13)
    hp = dict(hp or {})
    passos = int(hp.get("passos", 90))
    lr = float(hp.get("lr", 0.10))
    pol = None
    meta_info = {}

    if metodo == "rl_ordinario_h":
        tr = r24_treinar_rl(metodo, seed, hp, passos=passos, lr=lr, L=L, V=V, hard=True)
        pol, M = tr["pol"], tr["M"]
    elif metodo == "rl_extraord_h":
        tr = r24_treinar_rl(metodo, seed, hp, passos=passos, lr=lr, L=L, V=V, hard=True)
        pol, M = tr["pol"], tr["M"]
    elif metodo == "rl_meta_p":
        # first fit meta on a short run, then train with peso=P_cal
        tr0 = r24_treinar_rl("rl_ordinario_h", seed, hp, passos=max(20, passos // 3), lr=lr, L=L, V=V, hard=True)
        w = r24_fit_logreg(tr0["feats"], tr0["ys"], seed=seed)
        T = r24_escolher_T(w, tr0["feats"], tr0["ys"]) if len(tr0["feats"]) else 1.0

        def peso_fn(ids, M_, seed_, t_):
            phi = r24_features(ids, M_, seed_, t_)
            return float(r24_predict_p(w, phi[None, :], T=T)[0])

        tr = r24_treinar_rl(metodo, seed + 1, hp, passos=passos, lr=lr, L=L, V=V, hard=True,
                            peso_fn=peso_fn, init_pol=tr0["pol"])
        pol, M = tr["pol"], tr["M"]
        meta_info = {"w": w, "T": T}
    elif metodo == "rl_transfer_h":
        # train EASY with SAME step budget, resize → HARD zero-shot (no further training)
        tr_e = r24_treinar_rl("rl_ordinario_h", seed, hp, passos=passos, lr=lr,
                              L=R24_L_EASY, V=R24_V_EASY, hard=False)
        pol = r24_resize_policy(tr_e["pol"], V, M, rng)
    elif metodo in ("aleatorio_h", "guloso_markov_h", "filtro_so_prop_h", "delirio_prop_h"):
        pass
    else:
        raise ValueError(metodo)

    cleans, trains, kept = [], [], 0
    pairs_p_raw, pairs_p_cal, pairs_y = [], [], []
    # optional meta head for ECE reporting (fit on-the-fly from eval samples of ordinario path)
    for i in range(n_textos):
        if metodo == "aleatorio_h":
            ids, _ = r24_sample_uniform(rng, V, L)
        elif metodo == "guloso_markov_h":
            ids, _ = r24_sample_markov(M, rng, L)
        elif metodo in ("rl_ordinario_h", "rl_extraord_h", "rl_transfer_h", "rl_meta_p"):
            ids, _ = r24_sample_policy(pol, M, rng, L=L, temp=1.0)
        elif metodo == "filtro_so_prop_h":
            best, best_s = None, -1e9
            for k in range(5):
                cand, _ = r24_sample_markov(M, rng, L)
                rr = r24_filtro_primeiro(cand, M, seed, i * 10 + k)
                if rr["score_laudo"] > best_s:
                    best_s = rr["score_laudo"]
                    best = cand
            ids = best
        elif metodo == "delirio_prop_h":
            best, best_s = None, -1e9
            for k in range(5):
                ids_hi = [int(rng.integers(0, V))]
                prev = ids_hi[0]
                for _ in range(L - 1):
                    if rng.random() < 0.45:
                        nxt = int(rng.integers(0, V))
                    else:
                        p = M[prev] ** (1.0 / R24_HP_FILTRO["T_hi"])
                        p = p / p.sum()
                        nxt = int(rng.choice(V, p=p))
                    ids_hi.append(nxt)
                    prev = nxt
                ids_cool = list(ids_hi)
                for t in range(1, L):
                    if rng.random() < 0.25:
                        ids_cool[t] = int(np.argmax(M[ids_cool[t - 1]]))
                rr = r24_filtro_primeiro(ids_cool, M, seed, i * 10 + k)
                if rr["score_laudo"] > best_s:
                    best_s = rr["score_laudo"]
                    best = ids_cool
            ids = best
        cleans.append(r24_r_clean(ids, M))
        trains.append(r24_r_train(ids, M, seed, 1000 + i))
        fr = r24_filtro_primeiro(ids, M, seed, 2000 + i)
        if fr["mantem"]:
            kept += 1
        y = 1.0 if cleans[-1] >= R24_HP_FILTRO["tau_laudo"] else 0.0
        pairs_y.append(y)
        # raw: score_laudo as "probability"
        pairs_p_raw.append(float(fr["score_laudo"]))
        if meta_w is not None:
            phi = r24_features(ids, M, seed, 3000 + i)
            pairs_p_cal.append(float(r24_predict_p(meta_w, phi[None, :], T=meta_T)[0]))
        else:
            pairs_p_cal.append(float(fr["score_laudo"]))

    return {
        "r_clean": float(np.mean(cleans)),
        "r_train_eval": float(np.mean(trains)),
        "keep_rate": kept / max(n_textos, 1),
        "ece_raw": r24_ece(pairs_p_raw, pairs_y, bins=8),
        "ece_cal": r24_ece(pairs_p_cal, pairs_y, bins=8),
        "metodo": metodo,
        "seed": int(seed),
        "meta": meta_info,
        "pol": pol,
        "M": M,
    }


def r24_ajustar(metodo: str, seeds_dev, n_sort: int = 6) -> dict:
    rng = r24_rng(r24_crc(f"ajuste|{metodo}"), 21)
    grade = []
    for _ in range(n_sort):
        grade.append({
            "passos": int(rng.choice([60, 120])),
            "lr": float(rng.choice([0.05, 0.15])),
        })
    if metodo in ("aleatorio_h", "guloso_markov_h", "filtro_so_prop_h", "delirio_prop_h",
                  "aleatorio_rap", "guloso_tab_rap", "guloso_forte_rap"):
        grade = [{"passos": 60, "lr": 0.10}]
    best, best_sc = None, -1e9
    for hp in grade:
        if metodo.endswith("_rap"):
            scs = [r24_eval_raphael(metodo, s, hp)["chips"] for s in seeds_dev]
        else:
            scs = [r24_eval_texto(metodo, s, hp, n_textos=10)["r_clean"] for s in seeds_dev]
        m = float(np.mean(scs))
        if m > best_sc:
            best_sc = m
            best = dict(hp)
    return best or {"passos": 90, "lr": 0.10}


def r24_bigram_prior_from_pol(pol) -> np.ndarray:
    """Extrai preferência de bigramas (softmax das linhas de W) como vetor V."""
    W = pol["W"]
    # média das distribuições → perfil de token "preferido"
    prefs = []
    for i in range(W.shape[0]):
        prefs.append(r24_softmax(W[i] + pol["b"]))
    return np.mean(prefs, axis=0)


def r24_eval_raphael(metodo: str, seed: int, hp: dict, n_eval: int = 8) -> dict:
    """Transferência TEXT→RAPHAEL: prior bigrama do RL HARD modula afinidade PN."""
    hp = dict(hp or {})
    passos = int(hp.get("passos", 60))
    lr = float(hp.get("lr", 0.10))
    prior = None
    if metodo == "rl_transfer_rap":
        tr = r24_treinar_rl("rl_ordinario_h", seed, hp, passos=passos, lr=lr,
                            L=R24_L_HARD, V=R24_V_HARD, hard=True)
        prior = r24_bigram_prior_from_pol(tr["pol"])

    chips = []
    for j in range(n_eval):
        s = seed * 17 + j * 3 + 11
        if metodo == "aleatorio_rap":
            # usa r17_eval_h com método aleatório via canal: guloso_tab com ruído
            # r17 não tem aleatorio puro; usamos meta_sempre com lambda=0 ≈ forte? 
            # Melhor: chamar r17_partida com guloso_tab vs si mesmo não; usar r16 se disponível.
            # Fallback honesto: r17_eval_h("guloso_tab") com seed embaralhada + ruído no placar? 
            # Usar r17_eval_h com "canal_pn" como proxy fraco? Prereg pede aleatorio_rap.
            # Implementação: média de partidas com escolhas uniformes entre moves legais.
            chips.append(r24_raphael_aleatorio(s))
        elif metodo == "guloso_tab_rap":
            chips.append(float(r17_eval_h("guloso_tab", s, {"tau": 1.0, "eta": 0.6, "delta": 0.8, "lam": 0.5}, n_eval=1)))
        elif metodo == "guloso_forte_rap":
            chips.append(float(r17_eval_h("guloso_forte", s, {"tau": 1.0, "eta": 0.6, "delta": 0.8, "lam": 0.5}, n_eval=1)))
        elif metodo == "rl_transfer_rap":
            chips.append(r24_raphael_transfer(s, prior))
        else:
            raise ValueError(metodo)
    return {"chips": float(np.mean(chips)), "metodo": metodo, "seed": int(seed)}


def r24_raphael_aleatorio(seed: int) -> float:
    """Partida Raphael: jogador 0 move uniforme; oponente guloso_tab. Placar = pts0-pts1."""
    rng = r24_rng(seed, r24_crc("rap_ale"), 2)
    board, deck, _ = r16_estado0(rng)
    di = 0
    pts = [0.0, 0.0]
    for t in range(16):
        jog = t % 2
        if di >= len(deck):
            break
        carta = deck[di]; di += 1
        moves = r16_movimentos(board, jog)
        if not moves:
            break
        if jog == 0:
            mv = moves[int(rng.integers(0, len(moves)))]
        else:
            best, bv = moves[0], -1e9
            for m in moves:
                b2, cap = r16_aplicar(board, m)
                val = r16_score_pos(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
                if val > bv:
                    best, bv = m, val
            mv = best
        board, cap = r16_aplicar(board, mv)
        coh = r16_coerencia(*carta)
        ganho = r16_pos_valor(mv[2], mv[3]) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0)) + 0.5 * coh
        pts[jog] += ganho
        if abs(cap) == 1:
            pts[jog] += 5.0
            break
    return float(pts[0] - pts[1])


def r24_raphael_transfer(seed: int, prior) -> float:
    """Jogador 0: guloso_forte + bias de carta do prior bigrama textual; oponente guloso_tab."""
    rng = r24_rng(seed, r24_crc("rap_tr"), 4)
    board, deck, _ = r16_estado0(rng)
    di = 0
    pts = [0.0, 0.0]
    V = len(prior) if prior is not None else 0
    for t in range(16):
        jog = t % 2
        if di >= len(deck):
            break
        carta = deck[di]; di += 1
        w, n = carta
        moves = r16_movimentos(board, jog)
        if not moves:
            break
        if jog == 0:
            idx = (zlib.crc32(w.encode("utf-8")) & 0xFFFFFFFF) % max(V, 1) if V else 0
            bias = float(prior[idx]) * 2.0 if prior is not None else 0.0
            best, bv = moves[0], -1e9
            for m in moves:
                b2, cap = r16_aplicar(board, m)
                val = r17_score_forte(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
                val += 0.8 * bias * r17_afinidade_pn(w, n)
                if val > bv:
                    best, bv = m, val
            mv = best
            coh = r17_afinidade_pn(w, n)
        else:
            best, bv = moves[0], -1e9
            for m in moves:
                b2, cap = r16_aplicar(board, m)
                val = r16_score_pos(b2, jog) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0))
                if val > bv:
                    best, bv = m, val
            mv = best
            coh = r16_coerencia(w, n)
        board, cap = r16_aplicar(board, mv)
        ganho = r16_pos_valor(mv[2], mv[3]) + (3.0 if abs(cap) == 1 else (1.5 if cap else 0.0)) + 0.5 * coh
        pts[jog] += ganho
        if abs(cap) == 1:
            pts[jog] += 5.0
            break
    return float(pts[0] - pts[1])


def r24_pareado_pack(diffs, seed=0):
    d = np.asarray(diffs, dtype=float)
    n = len(d)
    media = float(d.mean()) if n else 0.0
    rng = r24_rng(seed, r24_crc("pareado"), 3)
    if n == 0:
        return {"media": 0.0, "lo": 0.0, "hi": 0.0, "p": 1.0, "mde": 0.0}
    B = 8000
    abs0 = abs(media)
    cnt = 0
    for _ in range(B):
        s = rng.choice([-1.0, 1.0], size=n)
        if abs(float((d * s).mean())) >= abs0 - 1e-15:
            cnt += 1
    p = (cnt + 1) / (B + 1)
    boots = []
    for _ in range(1500):
        idx = rng.integers(0, n, size=n)
        boots.append(float(d[idx].mean()))
    lo, hi = float(np.percentile(boots, 2.5)), float(np.percentile(boots, 97.5))
    sd = float(d.std(ddof=1)) if n > 1 else 0.0
    mde = 2.8 * sd / max(n ** 0.5, 1.0)
    return {"media": media, "lo": lo, "hi": hi, "p": float(p), "mde": float(mde)}


def r24_status(media, p_holm, sinal_esperado=1):
    if p_holm < 0.05:
        if media * sinal_esperado > 0:
            return "confirmada"
        return "refutada"
    return "nula"


def r24_veredito_h(st: dict) -> str:
    h1 = st.get("H1") == "confirmada"
    h2 = st.get("H2") == "confirmada"
    h4 = st.get("H4") == "confirmada"
    h3 = st.get("H3")
    h5 = st.get("H5")
    if h1 and (h2 or h4):
        base = "ESCALA HARD SINALIZA"
    elif h1:
        base = "APRENDE HARD MAS NAO SUPERA BASELINES"
    else:
        base = "ESCALA HARD NULA"
    if h3 == "confirmada":
        base += "; EXTRAORDINARIO AJUDA NO HARD"
    elif h3 == "refutada":
        base += "; EXTRAORDINARIO PIORA/NAO AJUDA"
    if h5 == "refutada":
        base += "; DELIRIO ACRESCENTA NO HARD"
    return base


def r24_veredito_x(st: dict) -> str:
    x1 = st.get("X1") == "confirmada"
    x2 = st.get("X2") == "confirmada"
    x3 = st.get("X3")
    if x1 and x2:
        base = "TRANSFER RAPHAEL SINALIZA"
    elif x1:
        base = "TRANSFER > ALEATORIO SO"
    else:
        base = "TRANSFER RAPHAEL NULA"
    if x3 == "refutada":
        base += "; TRANSFER SUPERA FORTE"
    return base


def r24_veredito_m(st: dict) -> str:
    m1 = st.get("M1")
    m2 = st.get("M2")
    if m1 == "confirmada" and m2 == "confirmada":
        return "META-RECOMPENSA CALIBRA; E AJUDA O RL"
    if m1 == "confirmada":
        return "META-RECOMPENSA CALIBRA MAS NAO AJUDA RL"
    return "META-RECOMPENSA NAO CALIBRA"


def r24_job(task):
    """task = (familia, metodo, seed, hp[, meta_w, meta_T])"""
    fam = task[0]
    if fam == "H":
        _, metodo, seed, hp = task
        return r24_eval_texto(metodo, seed, hp)
    if fam == "X":
        _, metodo, seed, hp = task
        return r24_eval_raphael(metodo, seed, hp)
    if fam == "M":
        # M eval: returns ece_raw, ece_cal, and optionally rl_meta r_clean
        _, kind, seed, hp, meta_w, meta_T = task
        if kind == "ece":
            ev = r24_eval_texto("rl_ordinario_h", seed, hp, meta_w=meta_w, meta_T=meta_T)
            return {"ece_raw": ev["ece_raw"], "ece_cal": ev["ece_cal"], "r_clean": ev["r_clean"], "seed": seed}
        if kind == "meta_rl":
            ev = r24_eval_texto("rl_meta_p", seed, hp)
            return {"r_clean": ev["r_clean"], "seed": seed}
        raise ValueError(kind)
    raise ValueError(fam)


def r24_fit_meta_dev(seeds_dev, hp):
    """Ajusta w,T no DEV a partir de trajetórias ordinárias HARD."""
    feats, ys = [], []
    for s in seeds_dev:
        tr = r24_treinar_rl("rl_ordinario_h", s, hp, passos=int(hp.get("passos", 60)),
                            lr=float(hp.get("lr", 0.10)), L=R24_L_HARD, V=R24_V_HARD, hard=True)
        if len(tr["feats"]):
            feats.append(tr["feats"])
            ys.append(tr["ys"])
    if not feats:
        return np.zeros(5), 1.0
    X = np.vstack(feats)
    y = np.concatenate(ys)
    w = r24_fit_logreg(X, y, seed=r24_crc("meta_dev"))
    T = r24_escolher_T(w, X, y)
    return w, T


def r24_tarefas(ctx):
    desloc = r24_desloc()
    S = r24_sementes(desloc)

    def _fn():
        hp = r24_ajustar("rl_ordinario_h", S["dev"][:2], n_sort=2)
        ev = r24_eval_texto("rl_ordinario_h", S["dev"][0], hp, n_textos=6)
        return {"rl_clean_dev": ev["r_clean"], "hp": hp}
    return _fn, ()

# ======================================================================
# [R24] PARTE HW — proxies numpy (BitLinear / prefill-decode / SNN LIF)
# Adendo HW sha256 346993409882ef2aa6a2974820e4c877927ef5a761d4f39798738d44853f15e9
# ======================================================================

ADENDO_HW_R24_CORPO_SHA256 = "346993409882ef2aa6a2974820e4c877927ef5a761d4f39798738d44853f15e9"

R24_HIPOT_W = ("W1", "W2", "W3", "W4", "W5")
R24_METODOS_W_BIT = ("fp16_proxy", "bitlinear")
R24_METODOS_W_NN = ("ann_dense", "snn_lif")


def r24_espirais(seed: int, n: int = 400):
    rng = r24_rng(seed, r24_crc("espirais"), 3)
    n2 = n // 2
    t0 = rng.uniform(0, 2 * np.pi, n2)
    t1 = rng.uniform(0, 2 * np.pi, n2)
    r0 = 0.5 * t0 / (2 * np.pi) + 0.2
    r1 = 0.5 * t1 / (2 * np.pi) + 0.2
    x0 = np.stack([r0 * np.cos(t0), r0 * np.sin(t0)], axis=1)
    x1 = np.stack([r1 * np.cos(t1 + np.pi), r1 * np.sin(t1 + np.pi)], axis=1)
    X = np.vstack([x0, x1]).astype(np.float64)
    y = np.concatenate([np.zeros(n2), np.ones(n2)]).astype(np.float64)
    idx = rng.permutation(n)
    return X[idx], y[idx]


def r24_trunc_fp16(a):
    """Proxy FP16: reduz mantissa (não é IEEE real; determinístico)."""
    a = np.asarray(a, dtype=np.float64)
    # scale to retain ~10 bits mantissa
    return np.round(a * 1024.0) / 1024.0


def r24_ternarize(W, delta=0.05):
    W = np.asarray(W, dtype=np.float64)
    out = np.sign(W)
    out[np.abs(W) < delta] = 0.0
    return out


def r24_mlp_init(rng, dims):
    ws = []
    for a, b in zip(dims[:-1], dims[1:]):
        ws.append(rng.normal(0, 0.4 / max(a, 1) ** 0.5, size=(a, b)))
    return ws


def r24_forward_fp16(ws, X, contagem=None):
    h = r24_trunc_fp16(X)
    for i, W in enumerate(ws):
        Wq = r24_trunc_fp16(W)
        # mul+add GEMM proxy
        n_mul = h.shape[0] * Wq.shape[0] * Wq.shape[1]
        n_add = n_mul
        if contagem is not None:
            contagem["mul"] = contagem.get("mul", 0) + n_mul
            contagem["add"] = contagem.get("add", 0) + n_add
        z = h @ Wq
        if i < len(ws) - 1:
            h = np.maximum(0.0, r24_trunc_fp16(z))
        else:
            h = 1.0 / (1.0 + np.exp(-np.clip(r24_trunc_fp16(z), -40, 40)))
    return h.reshape(-1)


def r24_forward_bit(ws, X, contagem=None):
    h = X.astype(np.float64)
    for i, W in enumerate(ws):
        Wt = r24_ternarize(W)
        # add/sub only: for each weight ±1, add/sub activation
        # proxy ops: each nonzero weight → one add/sub per example
        nnz = int(np.count_nonzero(Wt))
        n_add = h.shape[0] * nnz
        if contagem is not None:
            contagem["add"] = contagem.get("add", 0) + n_add
            contagem["mul"] = contagem.get("mul", 0) + 0
        z = h @ Wt  # numerically OK; ops counted as add/sub
        if i < len(ws) - 1:
            h = np.maximum(0.0, z)
        else:
            h = 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
    return h.reshape(-1)


def r24_train_mlp(metodo: str, seed: int, passos: int, lr: float):
    rng = r24_rng(seed, r24_crc(f"mlp|{metodo}"), 5)
    Xtr, ytr = r24_espirais(seed, 400)
    Xte, yte = r24_espirais(seed + 1, 200)
    dims = [2, 16, 16, 1]
    ws = r24_mlp_init(rng, dims)
    for t in range(passos):
        if metodo == "fp16_proxy":
            p = r24_forward_fp16(ws, Xtr)
        else:
            p = r24_forward_bit(ws, Xtr)
        # gradient proxy (float); then project
        err = (p - ytr).reshape(-1, 1)
        # last layer
        h2 = np.maximum(0.0, Xtr @ ws[0])
        h2 = np.maximum(0.0, h2 @ ws[1])
        # crude backprop last layer only + small first layers
        g2 = h2.T @ err / len(ytr)
        ws[2] = ws[2] - lr * g2
        if metodo == "bitlinear":
            ws[2] = r24_ternarize(ws[2], delta=0.02)
            # soft update earlier layers then ternarize periodically
            if t % 5 == 0:
                for i in range(2):
                    ws[i] = r24_ternarize(ws[i] + rng.normal(0, 0.01, size=ws[i].shape), delta=0.05)
        else:
            ws[2] = r24_trunc_fp16(ws[2])
            if t % 5 == 0:
                for i in range(2):
                    ws[i] = r24_trunc_fp16(ws[i] - lr * 0.1 * rng.normal(0, 0.01, size=ws[i].shape))
    cont = {"mul": 0, "add": 0}
    if metodo == "fp16_proxy":
        pte = r24_forward_fp16(ws, Xte, cont)
    else:
        pte = r24_forward_bit(ws, Xte, cont)
    acc = float(((pte >= 0.5) == (yte >= 0.5)).mean())
    energia = 1.0 * cont["mul"] + 0.25 * cont["add"]
    return {"acc": acc, "energia": float(energia), "mul": cont["mul"], "add": cont["add"],
            "metodo": metodo, "seed": seed}


def r24_prefill_decode(seed: int, L: int = 64, d: int = 32):
    """Sintético: intensity = flops/bytes."""
    rng = r24_rng(seed, r24_crc("pd"), L)
    # prefill: one big matmul over L tokens
    flops_prefill = 2.0 * L * d * d
    bytes_prefill = L * d * 2.0  # read activations once
    # decode: L steps, each matmul d×d, traffic L*d*2 per step-ish
    flops_decode = 2.0 * L * d * d
    bytes_decode = L * d * 2.0 * L / max(L ** 0.5, 1.0)  # more traffic relative
    # make decode more bandwidth-heavy as declared
    bytes_decode = L * d * 2.0 * 4.0
    inten_p = flops_prefill / (bytes_prefill + 1.0)
    inten_d = flops_decode / (bytes_decode + 1.0)
    # tiny noise for paired variance across seeds
    inten_p *= 1.0 + 0.01 * float(rng.normal())
    inten_d *= 1.0 + 0.01 * float(rng.normal())
    return {"intensity_prefill": float(inten_p), "intensity_decode": float(inten_d),
            "flops_p": flops_prefill, "bytes_p": bytes_prefill,
            "flops_d": flops_decode, "bytes_d": bytes_decode, "seed": seed}


def r24_train_ann(seed: int, passos: int, lr: float):
    rng = r24_rng(seed, r24_crc("ann"), 8)
    Xtr, ytr = r24_espirais(seed, 400)
    Xte, yte = r24_espirais(seed + 1, 200)
    dims = [2, 16, 16, 1]
    ws = r24_mlp_init(rng, dims)
    for t in range(passos):
        h = Xtr
        acts = [h]
        for i, W in enumerate(ws):
            z = h @ W
            h = np.maximum(0.0, z) if i < len(ws) - 1 else 1 / (1 + np.exp(-np.clip(z, -40, 40)))
            acts.append(h)
        err = (acts[-1].reshape(-1) - ytr).reshape(-1, 1)
        # last layer gd
        ws[-1] = ws[-1] - lr * (acts[-2].T @ err) / len(ytr)
        # light updates
        if t % 3 == 0:
            for i in range(len(ws) - 1):
                ws[i] -= lr * 0.05 * rng.normal(0, 0.02, size=ws[i].shape)
    # eval
    h = Xte
    for i, W in enumerate(ws):
        z = h @ W
        h = np.maximum(0.0, z) if i < len(ws) - 1 else 1 / (1 + np.exp(-np.clip(z, -40, 40)))
    acc = float(((h.reshape(-1) >= 0.5) == (yte >= 0.5)).mean())
    return {"acc": acc, "sparsity": 0.0, "metodo": "ann_dense", "seed": seed}


def r24_train_snn(seed: int, passos: int, lr: float, theta: float = 1.0):
    """LIF proxy: V+=Wx; spike if V>=θ; reset; sparsidade = spikes/opportunities."""
    rng = r24_rng(seed, r24_crc("snn"), 8)
    Xtr, ytr = r24_espirais(seed, 400)
    Xte, yte = r24_espirais(seed + 1, 200)
    dims = [2, 16, 16, 1]
    ws = r24_mlp_init(rng, dims)
    spikes_total = 0
    slots = 0
    for t in range(passos):
        # one «timestep» presentation of batch
        h = Xtr
        for i, W in enumerate(ws):
            V = h @ W
            if i < len(ws) - 1:
                sp = (V >= theta).astype(np.float64)
                spikes_total += int(sp.sum())
                slots += sp.size
                h = sp  # binary spikes as activations
                # surrogate: nudge weights where spike happened
                if t % 2 == 0:
                    target = (ytr.reshape(-1, 1) - 0.5)
                    # crude
                    ws[i] = ws[i] + lr * 0.01 * rng.normal(0, 1.0, size=ws[i].shape) * (0.5 + 0.5 * (sp.mean()))
            else:
                p = 1 / (1 + np.exp(-np.clip(V, -40, 40)))
                err = (p.reshape(-1) - ytr).reshape(-1, 1)
                ws[i] = ws[i] - lr * (h.T @ err) / len(ytr)
    # eval with LIF
    h = Xte
    for i, W in enumerate(ws):
        V = h @ W
        if i < len(ws) - 1:
            sp = (V >= theta).astype(np.float64)
            spikes_total += int(sp.sum())
            slots += sp.size
            h = sp
        else:
            p = 1 / (1 + np.exp(-np.clip(V, -40, 40)))
    acc = float(((p.reshape(-1) >= 0.5) == (yte >= 0.5)).mean())
    spars = 1.0 - (spikes_total / max(slots, 1))  # fraction silent = sparsity
    # also report spike rate
    spike_rate = spikes_total / max(slots, 1)
    return {"acc": acc, "sparsity": float(spars), "spike_rate": float(spike_rate),
            "metodo": "snn_lif", "seed": seed}


def r24_eval_hw(metodo: str, seed: int, hp: dict) -> dict:
    passos = int(hp.get("passos", 80))
    lr = float(hp.get("lr", 0.10))
    if metodo in ("fp16_proxy", "bitlinear"):
        return r24_train_mlp(metodo, seed, passos, lr)
    if metodo == "ann_dense":
        return r24_train_ann(seed, passos, lr)
    if metodo == "snn_lif":
        return r24_train_snn(seed, passos, lr)
    if metodo == "prefill_decode":
        return r24_prefill_decode(seed)
    raise ValueError(metodo)


def r24_veredito_w(st: dict) -> str:
    parts = []
    if st.get("W2") == "confirmada" and st.get("W1") != "refutada":
        parts.append("BITLINEAR PROXY ECONOMIZA SEM COLAPSAR")
    if st.get("W3") == "confirmada":
        parts.append("PREFILL COMPUTE-BOUND VS DECODE BANDWIDTH")
    if st.get("W5") == "confirmada" and st.get("W4") != "refutada":
        parts.append("SNN ESPARSO SEM GANHO DE ACURACIA")
    elif st.get("W4") == "refutada":
        parts.append("SNN SUPERA ANN (surpreendente)")
    if not parts:
        return "PROXIES HW SEM SINAL CLARO"
    return "; ".join(parts)


# -*- coding: utf-8 -*-
# [R24] ORQUESTRAÇÃO DO BLOCO 32 + registro/sumário/leigos

def bloco32(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 32 — [R24] ESCALA HARD do ganho R23 + TRANSFER Raphael + META-RECOMPENSA "
               "(H1–H7 + X1–X3 + M1–M2; 40 sementes; Holm local; prereg_r24.txt)")
    desloc = r24_desloc()
    if desloc:
        rep.log(f"[R24_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r24_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R24_NTEST
    n_sort = 2 if rapido else 6

    ok_p = hashlib.sha256(PREREG_R24_CORPO.encode("utf-8")).hexdigest() == PREREG_R24_CORPO_SHA256
    rep.log(f"Pré-registro R24: sha256={PREREG_R24_CORPO_SHA256[:16]}… "
            f"{'(CONFERE com versoes/prereg_r24.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R24_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R24_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R24_CORPO_SHA256
        rep.log(f"Adendo 1 R24: sha256={ADENDO1_R24_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")

    rep.log("ARQUITETURA TRAVADA: filtro-primeiro + τ_laudo FIXED; delírio = explorador opcional; "
            "RL ordinário preferido ao extraordinário (R23 S3); BLOCOS 27–30 dormentes.")
    rep.log(f"  HARD: L={R24_L_HARD} V={R24_V_HARD} | EASY transfer: L={R24_L_EASY} V={R24_V_EASY} | hp filtro={R24_HP_FILTRO}")

    # ---------- H: texto HARD ----------
    rep.sub("H — escala HARD (orçamento igual) + avaliação TESTE (r_clean limpo)")
    if ctx.bg is not None:
        try:
            _bg = ctx.bg.obter("r24a")
            if isinstance(_bg, dict):
                rep.log(f"  sanidade DEV rl_clean≈{_bg.get('rl_clean_dev', float('nan')):+.3f}")
        except Exception:
            pass

    hp_H = {}
    for met in R24_METODOS_H:
        hp_H[met] = r24_ajustar(met, S["dev"][:R24_NDEV], n_sort=n_sort)
        rep.log(f"  ajuste {met}: {hp_H[met]}")

    scores_H = {m: {"r_clean": [], "r_train_eval": [], "keep_rate": []} for m in R24_METODOS_H}
    tasks = [("H", m, s, hp_H[m]) for m in R24_METODOS_H for s in S["test"][:n_test]]
    outs = mapa_paralelo(r24_job, tasks, jobs)
    k = 0
    for m in R24_METODOS_H:
        for _ in S["test"][:n_test]:
            r = outs[k]; k += 1
            scores_H[m]["r_clean"].append(r["r_clean"])
            scores_H[m]["r_train_eval"].append(r.get("r_train_eval", float("nan")))
            scores_H[m]["keep_rate"].append(r.get("keep_rate", float("nan")))
        rep.log(f"  {m}: r_clean={float(np.mean(scores_H[m]['r_clean'])):+.4f} "
                f"keep={float(np.nanmean(scores_H[m]['keep_rate'])):.3f}")

    P_H = {}
    for hname, (a, b, met) in R24_PAR_H.items():
        d = np.asarray(scores_H[a][met]) - np.asarray(scores_H[b][met])
        P_H[hname] = r24_pareado_pack(d, seed=r24_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_H[hname]['media']:+.4f} p={P_H[hname]['p']:.4f}")

    st_H = {}
    ps = [P_H[h]["p"] for h in R24_HIPOT_H]
    ph = holm(ps)
    for i, h in enumerate(R24_HIPOT_H):
        P_H[h]["p_holm"] = ph[i]
        # H3: expected for "confirmation" is extraord > ordinario (Δ>0); refutation if Δ<0
        sinal = 1
        st_H[h] = r24_status(P_H[h]["media"], ph[i], sinal_esperado=sinal)
        rep.log(f"  status {h}: {st_H[h]} (p_holm={ph[i]:.4f})")

    ver_h = r24_veredito_h(st_H)
    rep.log(f"VEREDITO H (regra pré-registrada): {ver_h}")

    # ---------- X: transfer Raphael ----------
    rep.sub("X — transferência TEXT→RAPHAEL (chips; orçamento igual)")
    hp_X = {}
    for met in R24_METODOS_X:
        hp_X[met] = r24_ajustar(met, S["dev"][:R24_NDEV], n_sort=max(1, n_sort // 2))
        rep.log(f"  ajuste {met}: {hp_X[met]}")

    scores_X = {m: {"chips": []} for m in R24_METODOS_X}
    tasks_x = [("X", m, s, hp_X[m]) for m in R24_METODOS_X for s in S["test"][:n_test]]
    outs_x = mapa_paralelo(r24_job, tasks_x, jobs)
    k = 0
    for m in R24_METODOS_X:
        for _ in S["test"][:n_test]:
            r = outs_x[k]; k += 1
            scores_X[m]["chips"].append(r["chips"])
        rep.log(f"  {m}: chips={float(np.mean(scores_X[m]['chips'])):+.4f}")

    P_X = {}
    for hname, (a, b, met) in R24_PAR_X.items():
        d = np.asarray(scores_X[a][met]) - np.asarray(scores_X[b][met])
        P_X[hname] = r24_pareado_pack(d, seed=r24_crc(hname))
        rep.log(f"  {hname} ({a}−{b}): Δ={P_X[hname]['media']:+.4f} p={P_X[hname]['p']:.4f}")
    st_X = {}
    psx = [P_X[h]["p"] for h in R24_HIPOT_X]
    phx = holm(psx)
    for i, h in enumerate(R24_HIPOT_X):
        P_X[h]["p_holm"] = phx[i]
        st_X[h] = r24_status(P_X[h]["media"], phx[i], sinal_esperado=1)
        rep.log(f"  status {h}: {st_X[h]} (p_holm={phx[i]:.4f})")
    ver_x = r24_veredito_x(st_X)
    rep.log(f"VEREDITO X (regra pré-registrada): {ver_x}")

    # ---------- M: meta-recompensa ----------
    rep.sub("M — meta-recompensa P̂(reward) + ECE + RL ponderado")
    # fit meta on DEV with ordinario hp
    hp_ord = hp_H.get("rl_ordinario_h", {"passos": 60, "lr": 0.10})
    meta_w, meta_T = r24_fit_meta_dev(S["dev"][:R24_NDEV], hp_ord)
    rep.log(f"  meta DEV: T*={meta_T:.3f} | ||w||={float(np.linalg.norm(meta_w)):.3f}")

    ece_raw, ece_cal, rc_ord, rc_meta = [], [], [], []
    tasks_m = []
    for s in S["test"][:n_test]:
        tasks_m.append(("M", "ece", s, hp_ord, meta_w, meta_T))
    for s in S["test"][:n_test]:
        tasks_m.append(("M", "meta_rl", s, hp_ord, meta_w, meta_T))
    outs_m = mapa_paralelo(r24_job, tasks_m, jobs)
    for i in range(n_test):
        ece_raw.append(outs_m[i]["ece_raw"])
        ece_cal.append(outs_m[i]["ece_cal"])
        rc_ord.append(outs_m[i]["r_clean"])
    for i in range(n_test):
        rc_meta.append(outs_m[n_test + i]["r_clean"])
    rep.log(f"  ECE_raw={float(np.mean(ece_raw)):.4f} | ECE_cal={float(np.mean(ece_cal)):.4f}")
    rep.log(f"  r_clean ordinario={float(np.mean(rc_ord)):+.4f} | rl_meta_p={float(np.mean(rc_meta)):+.4f}")

    P_M = {}
    d_m1 = np.asarray(ece_raw) - np.asarray(ece_cal)  # >0 → cal better
    P_M["M1"] = r24_pareado_pack(d_m1, seed=r24_crc("M1"))
    d_m2 = np.asarray(rc_meta) - np.asarray(rc_ord)
    P_M["M2"] = r24_pareado_pack(d_m2, seed=r24_crc("M2"))
    st_M = {}
    psm = [P_M[h]["p"] for h in R24_HIPOT_M]
    phm = holm(psm)
    for i, h in enumerate(R24_HIPOT_M):
        P_M[h]["p_holm"] = phm[i]
        st_M[h] = r24_status(P_M[h]["media"], phm[i], sinal_esperado=1)
        rep.log(f"  {h}: Δ={P_M[h]['media']:+.4f} p={P_M[h]['p']:.4f} status={st_M[h]} (p_holm={phm[i]:.4f})")
    ver_m = r24_veredito_m(st_M)
    rep.log(f"VEREDITO M (regra pré-registrada): {ver_m}")


    # ---------- W: proxies HW ----------
    rep.sub("W — proxies HW (BitLinear vs FP16; prefill/decode; SNN LIF vs ANN)")
    ok_hw = hashlib.sha256(ADENDO_HW_R24_CORPO.encode("utf-8")).hexdigest() == ADENDO_HW_R24_CORPO_SHA256
    rep.log(f"Adendo HW R24: sha256={ADENDO_HW_R24_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_hw else '(!!)'}")
    rep.log("LIMITES: energia=proxy aritmético (não joules); BitLinear≠BitNet produção; SNN LIF brinquedo; sem CXL/RDMA/memristor físico; NÃO é ASI.")

    hp_W = {}
    for met in list(R24_METODOS_W_BIT) + list(R24_METODOS_W_NN):
        rng = r24_rng(r24_crc(f"ajW|{met}"), 21)
        grade = [{"passos": int(rng.choice([80, 160])), "lr": float(rng.choice([0.05, 0.15]))}
                 for _ in range(max(1, n_sort // 2))]
        best, best_sc = None, -1e9
        for hp in grade:
            scs = [r24_eval_hw(met, s, hp)["acc"] for s in S["dev"][:R24_NDEV]]
            m = float(np.mean(scs))
            if m > best_sc:
                best_sc, best = m, dict(hp)
        hp_W[met] = best or {"passos": 80, "lr": 0.10}
        rep.log(f"  ajuste {met}: {hp_W[met]}")

    scores_W = {m: {"acc": [], "energia": [], "sparsity": []} for m in list(R24_METODOS_W_BIT) + list(R24_METODOS_W_NN)}
    inten_p, inten_d = [], []
    for s in S["test"][:n_test]:
        for met in list(R24_METODOS_W_BIT) + list(R24_METODOS_W_NN):
            r = r24_eval_hw(met, s, hp_W[met])
            scores_W[met]["acc"].append(r["acc"])
            scores_W[met]["energia"].append(r.get("energia", float("nan")))
            scores_W[met]["sparsity"].append(r.get("sparsity", float("nan")))
        pd = r24_prefill_decode(s)
        inten_p.append(pd["intensity_prefill"])
        inten_d.append(pd["intensity_decode"])
    for met in list(R24_METODOS_W_BIT) + list(R24_METODOS_W_NN):
        rep.log(f"  {met}: acc={float(np.mean(scores_W[met]['acc'])):.4f} "
                f"energia={float(np.nanmean(scores_W[met]['energia'])):.1f} "
                f"spars={float(np.nanmean(scores_W[met]['sparsity'])):.3f}")
    rep.log(f"  intensity prefill={float(np.mean(inten_p)):.3f} decode={float(np.mean(inten_d)):.3f}")

    P_W = {}
    # W1: bitlinear - fp16 accuracy (non-inferiority soft: status via Δ)
    d1 = np.asarray(scores_W["bitlinear"]["acc"]) - np.asarray(scores_W["fp16_proxy"]["acc"])
    P_W["W1"] = r24_pareado_pack(d1, seed=r24_crc("W1"))
    # W2: energia fp16 - bitlinear
    d2 = np.asarray(scores_W["fp16_proxy"]["energia"]) - np.asarray(scores_W["bitlinear"]["energia"])
    P_W["W2"] = r24_pareado_pack(d2, seed=r24_crc("W2"))
    # W3: intensity prefill - decode
    d3 = np.asarray(inten_p) - np.asarray(inten_d)
    P_W["W3"] = r24_pareado_pack(d3, seed=r24_crc("W3"))
    # W4: ann - snn accuracy
    d4 = np.asarray(scores_W["ann_dense"]["acc"]) - np.asarray(scores_W["snn_lif"]["acc"])
    P_W["W4"] = r24_pareado_pack(d4, seed=r24_crc("W4"))
    # W5: sparsity_snn - 0.5
    d5 = np.asarray(scores_W["snn_lif"]["sparsity"]) - 0.5
    P_W["W5"] = r24_pareado_pack(d5, seed=r24_crc("W5"))

    st_W = {}
    psw = [P_W[h]["p"] for h in R24_HIPOT_W]
    phw = holm(psw)
    for i, h in enumerate(R24_HIPOT_W):
        P_W[h]["p_holm"] = phw[i]
        # W1 special: refutada se Δ<−0.05 e p_holm<0.05; confirmada se Δ≥0 e p_holm<0.05; else nula
        if h == "W1":
            med, phv = P_W[h]["media"], phw[i]
            if phv < 0.05 and med < -0.05:
                st_W[h] = "refutada"
            elif phv < 0.05 and med >= 0.0:
                st_W[h] = "confirmada"
            else:
                st_W[h] = "nula"
        else:
            st_W[h] = r24_status(P_W[h]["media"], phw[i], sinal_esperado=1)
        rep.log(f"  {h}: Δ={P_W[h]['media']:+.4f} p={P_W[h]['p']:.4f} status={st_W[h]} (p_holm={phw[i]:.4f})")
    ver_w = r24_veredito_w(st_W)
    rep.log(f"VEREDITO W (regra pré-registrada): {ver_w}")

    # pack
    def _tup(P):
        return {k: (v["media"], v["lo"], v["hi"], v["p"], v.get("p_holm", v["p"]), v["mde"]) for k, v in P.items()}

    st_all0 = {**st_H, **st_X, **st_M, **st_W}
    keys_all = list(R24_HIPOT_H) + list(R24_HIPOT_X) + list(R24_HIPOT_M) + list(R24_HIPOT_W)
    n_conf = sum(1 for h in keys_all if st_all0.get(h) == "confirmada")
    n_ref = sum(1 for h in keys_all if st_all0.get(h) == "refutada")
    n_nula = sum(1 for h in keys_all if st_all0.get(h) == "nula")
    rep.log(f"RESUMO R24: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {len(keys_all)}")
    rep.log("→ Continua NÃO sendo ASI/AGI. Filtro-primeiro permanece MOTOR. Mega-Sena não reaberta.")

    P_all = {}
    P_all.update(_tup(P_H))
    P_all.update(_tup(P_X))
    P_all.update(_tup(P_M))
    P_all.update(_tup(P_W))
    st_all = {**st_H, **st_X, **st_M, **st_W}

    ctx.res["r24"] = {
        "P": P_all, "st": st_all,
        "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula,
        "ver_h": ver_h, "ver_x": ver_x, "ver_m": ver_m, "ver_w": ver_w,
        "scores_H": {m: {"r_clean": float(np.mean(scores_H[m]["r_clean"]))} for m in R24_METODOS_H},
        "scores_X": {m: {"chips": float(np.mean(scores_X[m]["chips"]))} for m in R24_METODOS_X},
        "ece_raw": float(np.mean(ece_raw)), "ece_cal": float(np.mean(ece_cal)),
        "meta_T": float(meta_T),
        "hp_H": hp_H, "hp_X": hp_X, "desloc": desloc,
        "chaves": list(R24_HIPOT_H) + list(R24_HIPOT_X) + list(R24_HIPOT_M) + list(R24_HIPOT_W),
        "scores_W": {m: {"acc": float(np.mean(scores_W[m]["acc"]))} for m in list(R24_METODOS_W_BIT)+list(R24_METODOS_W_NN)},
        "inten_p": float(np.mean(inten_p)), "inten_d": float(np.mean(inten_d)),
    }
    return ctx.res["r24"]


def registro_r24(ctx: Contexto) -> list:
    r = ctx.res.get("r24")
    if not r:
        return []
    L = [f"REGISTRO R24 (BLOCO 32) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de 17"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append(f"  VEREDITO_H={r.get('ver_h')} | VEREDITO_X={r.get('ver_x')} | VEREDITO_M={r.get('ver_m')} | VEREDITO_W={r.get('ver_w')}")
    L.append(f"  ECE_raw={r.get('ece_raw'):.4f} ECE_cal={r.get('ece_cal'):.4f} T*={r.get('meta_T'):.3f}")
    return L


def sumario_r24_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r24")
