def r25_desloc() -> int:
    v = os.environ.get("R25_DEV")
    if not v or v in ("0", "false", "False", "no", "off", ""):
        return 0
    return 10000


def r25_crc(rot: str) -> int:
    return zlib.crc32(f"R25|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r25_rng(*keys):
    return np.random.default_rng([int(k) & 0xFFFFFFFF for k in keys])


def r25_sementes(desloc=0):
    d = int(desloc)
    return {"dev": [s + d for s in R25_SEEDS_DEV], "test": [s + d for s in R25_SEEDS_TEST]}


def r25_adv(adv: float, extra: bool) -> float:
    if not extra:
        return float(adv)
    return float(adv * (1.0 + R25_BETA_EXTRA)) if adv < 0 else float(adv * (1.0 - R25_BETA_EXTRA / 2.0))


def r25_dz(d) -> float:
    d = np.asarray(d, dtype=float)
    if len(d) < 2:
        return 0.0
    sd = float(d.std(ddof=1))
    return float(d.mean() / sd) if sd > 1e-12 else 0.0


# ---------------------------------------------------------------------------
# Tarefa HARD (texto) — adaptador sobre as funções r24_*
# ---------------------------------------------------------------------------
_R25_HARD_CACHE = {}


class R25Hard:
    nome = "H"
    batch = 1
    P = R25_P_HARD
    tau_y = 0.55

    def __init__(self):
        if "M" not in _R25_HARD_CACHE:
            vocab = r24_vocab(R24_V_HARD, 0)
            _R25_HARD_CACHE["M"] = r24_markov2(vocab, 0, hard=True)
        self.M = _R25_HARD_CACHE["M"]
        self.V = R24_V_HARD
        self.L = R24_L_HARD

    def init_pol(self, rng):
        return r24_policy_init(rng, self.V, M=self.M)

    def sample_uniform(self, rng):
        return r24_sample_uniform(rng, self.V, self.L)[0]

    def sample(self, pol, rng):
        ids, logps = r24_sample_policy(pol, self.M, rng, L=self.L, temp=1.0)
        return ids, logps

    def laudo(self, ids, seed, i):
        r = r24_laudo_texto(ids, self.M, seed, i)
        r["mantem"] = bool(r["proxy"] >= R24_HP_FILTRO["tau_tela"] and r["score_laudo"] >= R24_HP_FILTRO["tau_laudo"])
        r["passa_tela"] = bool(r["proxy"] >= R24_HP_FILTRO["tau_tela"])
        return r

    def r_clean(self, ids):
        return r24_r_clean(ids, self.M)

    def ruido(self, ids, seed, i):
        rng = r24_rng(seed, r24_crc("camuf"), i + 17)
        ruido = float(rng.normal(0, R24_SIGMA_CAMUF))
        h = (zlib.crc32(bytes(int(x) & 0xFF for x in ids)) & 0xFFFF) / 65535.0
        return ruido + R24_DELTA_CAMUF * (h - 0.5)

    def r_raw(self, ids, lau, seed, i):
        return float(lau["proxy"]) + self.ruido(ids, seed, i)

    def phi(self, ids, lau, usar_laudo=True):
        return np.asarray([lau["flu"], lau["div"], lau["proxy"], lau["score_laudo"] if usar_laudo else lau["proxy"], 1.0], dtype=np.float64)

    def update(self, pol, seqs, advs, lr, extra, pesos):
        for (ids, logps), adv, w in zip(seqs, advs, pesos):
            r24_reinforce_update(pol, ids, logps, adv, lr, extraordinario=extra, peso=w)


# ---------------------------------------------------------------------------
# Tarefa SIMBÓLICA Z7: x_t = (x_{t-1} + x_{t-2}) mod 7
# ---------------------------------------------------------------------------
class R25Sym:
    nome = "Y"

    def __init__(self, prm=None):
        prm = dict(prm or R25_SYM)
        self.V = int(prm["V"])
        self.L = int(prm["L"])
        self.batch = int(prm["B"])
        self.P = int(prm["P"])
        self.tau_y = float(prm["tau_y"])
        self.S = (self.V + 1) ** 2

    def init_pol(self, rng):
        return {"W": np.zeros((self.S, self.V)), "V": self.V}

    def sample_uniform(self, rng):
        return [int(x) for x in rng.integers(0, self.V, size=self.L)]

    def _state(self, ids, t):
        a = ids[t - 2] if t >= 2 else self.V
        b = ids[t - 1] if t >= 1 else self.V
        return a * (self.V + 1) + b

    def sample(self, pol, rng):
        ids, trace = [], []
        V = self.V
        for t in range(self.L):
            s = self._state(ids, t)
            z = pol["W"][s]
            p = np.exp(z - z.max())
            p = p / p.sum()
            u = float(rng.random())
            c = 0.0
            x = V - 1
            for k in range(V):
                c += float(p[k])
                if u < c:
                    x = k
                    break
            trace.append((s, x, p))
            ids.append(x)
        return ids, trace

    def _ok(self, ids):
        V = self.V
        return np.asarray([1.0 if ids[t] == (ids[t - 1] + ids[t - 2]) % V else 0.0 for t in range(2, len(ids))])

    def _div(self, ids):
        return min(1.0, len(set(ids)) / 4.0)

    def r_clean(self, ids):
        return float(0.8 * self._ok(ids).mean() + 0.2 * self._div(ids))

    def laudo(self, ids, seed, i):
        rng = r25_rng(seed, r25_crc("laudo_s"), i + 3)
        ok = self._ok(ids)
        mask = rng.random(len(ok)) < 0.6
        frac = float(ok[mask].mean()) if mask.any() else 0.0
        div = self._div(ids)
        proxy = 0.8 * frac + 0.2 * div
        V1 = frac >= 0.5
        if rng.random() < 0.06:
            V1 = not V1
        V2 = len(set(ids)) >= 3
        V3 = proxy >= 0.38
        score = 0.5 * proxy + 0.3 * float(V1) + 0.1 * float(V2) + 0.1 * float(V3) + float(rng.normal(0, 0.03))
        score = float(np.clip(score, 0.0, 1.0))
        passa = proxy >= R24_HP_FILTRO["tau_tela"]
        return {"flu": frac, "div": div, "proxy": float(proxy), "score_laudo": score,
                "passa_tela": bool(passa), "mantem": bool(passa and score >= R24_HP_FILTRO["tau_laudo"])}

    def ruido(self, ids, seed, i):
        rng = r25_rng(seed, r25_crc("camuf_s"), i + 17)
        h = (zlib.crc32(bytes(int(x) & 0xFF for x in ids)) & 0xFFFF) / 65535.0
        return float(rng.normal(0, R24_SIGMA_CAMUF)) + R24_DELTA_CAMUF * (h - 0.5)

    def r_raw(self, ids, lau, seed, i):
        nr = float(np.mean([1.0 if ids[t] != ids[t - 1] else 0.0 for t in range(1, len(ids))]))
        return 0.5 * nr + 0.5 * min(1.0, len(set(ids)) / 5.0) + self.ruido(ids, seed, i)

    def phi(self, ids, lau, usar_laudo=True):
        return np.asarray([lau["flu"], lau["div"], lau["proxy"], lau["score_laudo"] if usar_laudo else lau["proxy"], 1.0], dtype=np.float64)

    def update(self, pol, seqs, advs, lr, extra, pesos):
        B = max(len(seqs), 1)
        for (ids, trace), adv, w in zip(seqs, advs, pesos):
            g = lr * float(adv) * float(w) / B
            for (s, x, p) in trace:
                oh = -p.copy()
                oh[x] += 1.0
                pol["W"][s] += g * oh


def r25_tarefa(fam: str, prm=None):
    return R25Hard() if fam == "H" else R25Sym(prm)


# ---------------------------------------------------------------------------
# Treino e avaliação (genéricos; MESMO orçamento P de atualizações para todos os braços RL)
# ---------------------------------------------------------------------------
def r25_treinar(tarefa, cfg, seed: int, lr: float):
    P = tarefa.P
    rng = r25_rng(seed, r25_crc(f"train|{tarefa.nome}"), 5)
    pol = tarefa.init_pol(rng)
    if not cfg["rl"]:
        return {"pol": pol, "meta": {}, "w": None, "T": 1.0}
    com_meta = cfg["meta"] is not None
    P0 = int(math.ceil(P / 3.0)) if com_meta else P
    usar_laudo = cfg["recompensa"] == "filtro"
    baseline = 0.0
    X, Y = [], []
    w, T = None, 1.0
    escala = 1.0
    par = []   # (p_cal, p_bruta, y) fora da amostra (fase com peso)
    for t in range(P):
        if com_meta and t == P0:
            Xa, Ya = np.asarray(X), np.asarray(Y)
            w = r24_fit_logreg(Xa, Ya, seed=seed)
            T = r24_escolher_T(w, Xa, Ya) if cfg["meta"] in ("cal", "norm") and len(Xa) else 1.0
            if cfg["meta"] == "norm" and len(Xa):
                escala = 1.0 / max(float(np.mean(r24_predict_p(w, Xa, T=T))), 1e-3)
        seqs, rs, pes = [], [], []
        for b in range(tarefa.batch):
            ids, tr = tarefa.sample(pol, rng)
            lau = tarefa.laudo(ids, seed, t * tarefa.batch + b)
            if usar_laudo:
                r = float(lau["score_laudo"]) + tarefa.ruido(ids, seed, t * tarefa.batch + b)
            else:
                r = tarefa.r_raw(ids, lau, seed, t * tarefa.batch + b)
            phi = tarefa.phi(ids, lau, usar_laudo)
            if com_meta and t < P0:
                X.append(phi)
                Y.append(1.0 if tarefa.r_clean(ids) >= tarefa.tau_y else 0.0)
                peso = 1.0
            elif com_meta:
                peso = float(r24_predict_p(w, phi[None, :], T=T)[0])
                if cfg["meta"] == "norm":
                    peso = min(2.0, peso * escala)
                par.append((peso, float(r24_predict_p(w, phi[None, :], T=1.0)[0]), 1.0 if tarefa.r_clean(ids) >= tarefa.tau_y else 0.0))
            else:
                peso = 1.0
            seqs.append((ids, tr)); rs.append(r); pes.append(peso)
        rm = float(np.mean(rs))
        advs = [r25_adv(r - baseline, cfg["extra"]) for r in rs]
        baseline = 0.9 * baseline + 0.1 * rm
        tarefa.update(pol, seqs, advs, lr, False, pes)
    ece_c = ece_b = float("nan")
    if par:
        yy = [q[2] for q in par]
        ece_c = r24_ece([q[0] for q in par], yy, bins=8)
        ece_b = r24_ece([q[1] for q in par], yy, bins=8)
    return {"pol": pol, "meta": {"T": T}, "w": w, "T": T, "ece_cal_oos": ece_c, "ece_bruta_oos": ece_b}


def r25_avaliar(tarefa, cfg, treinado, seed: int, braco: str, meta_w=None):
    rng = r25_rng(seed, r25_crc(f"eval|{tarefa.nome}|{braco}"), 13)
    pol = treinado["pol"]
    cl, keep, pr, py = [], 0, [], []
    for i in range(R25_N_EVAL):
        k = R25_K_GATE if cfg["gate"] else 1
        melhor, ms, mp = None, -1e9, False
        for j in range(k):
            if cfg["uniforme"]:
                ids = tarefa.sample_uniform(rng)
            else:
                ids = tarefa.sample(pol, rng)[0]
            lau = tarefa.laudo(ids, seed, 5000 + i * 10 + j)
            chave = (1 if lau["passa_tela"] else 0, lau["score_laudo"])
            if melhor is None or chave > (1 if mp else 0, ms):
                melhor, ms, mp, mlau = ids, lau["score_laudo"], lau["passa_tela"], lau
        c = tarefa.r_clean(melhor)
        cl.append(c)
        keep += 1 if mlau["mantem"] else 0
        pr.append(float(mlau["score_laudo"]))
        py.append(1.0 if c >= tarefa.tau_y else 0.0)
    return {"r_clean": float(np.mean(cl)), "keep_rate": keep / R25_N_EVAL,
            "ece_raw": r24_ece(pr, py, bins=8)}


def r25_job_texto(task):
    """task = (fam 'H'|'Y', braco, seed, lr, prm_sym)"""
    fam, braco, seed, lr, prm = task
    tarefa = r25_tarefa(fam, prm)
    cfg = R25_CFG[braco]
    tr = r25_treinar(tarefa, cfg, seed, lr)
    ev = r25_avaliar(tarefa, cfg, tr, seed, braco)
    ev["seed"] = int(seed); ev["braco"] = braco; ev["fam"] = fam
    # ECE da meta (apenas descritivo): meta calibrada vs bruta nos textos avaliados é custosa; aqui ECE do score_laudo bruto
    ev["T"] = float(tr.get("T", 1.0))
    ev["ece_cal_oos"] = float(tr.get("ece_cal_oos", float("nan")))
    ev["ece_bruta_oos"] = float(tr.get("ece_bruta_oos", float("nan")))
    return ev


def r25_job(task):
    """Despacho para o pool: ('B', rung, seed, v1) = BitLinear; senão texto/simbólica."""
    if task[0] == "B":
        return r25_job_hw(task[1:])
    return r25_job_texto(task)


def r25_escolher_lr(fam: str, seeds_dev, prm=None):
    """Escolhe o lr no DEV pelo braço rl_ord (sem porta, sem meta) — MESMO lr para todos os braços RL."""
    tarefa = r25_tarefa(fam, prm)
    cfg = R25_CFG["rl_ord"]
    melhor, ms = None, -1e9
    tab = {}
    for lr in R25_LR_GRID[fam]:
        sc = [r25_avaliar(tarefa, cfg, r25_treinar(tarefa, cfg, s, lr), s, "rl_ord")["r_clean"] for s in seeds_dev]
        m = float(np.mean(sc))
        tab[lr] = m
        if m > ms:
            ms, melhor = m, lr
    alea = float(np.mean([r25_avaliar(tarefa, R25_CFG["aleat"], {"pol": None}, s, "aleat")["r_clean"] for s in seeds_dev]))
    return melhor, tab, alea


# ---------------------------------------------------------------------------
# Estatística pareada + status
# ---------------------------------------------------------------------------
def r25_pack(d, seed=0, deslocar=0.0):
    """Permutação de sinais bicaudal de (d + deslocar) (B3 usa deslocar=+margem); IC bootstrap de d; d_z de d."""
    d = np.asarray(d, dtype=float)
    n = len(d)
    if n == 0:
        return {"media": 0.0, "lo": 0.0, "hi": 0.0, "p": 1.0, "mde": 0.0, "dz": 0.0}
    dd = d + float(deslocar)
    rng = r24_rng(seed, r25_crc("pack"), 3)
    obs = abs(float(dd.mean()))
    B = 8000
    sg = rng.choice([-1.0, 1.0], size=(B, n))
    cnt = int(np.sum(np.abs(sg @ dd) / n >= obs - 1e-15))
    p = (cnt + 1) / (B + 1)
    boots = [float(d[rng.integers(0, n, size=n)].mean()) for _ in range(1500)]
    sd = float(d.std(ddof=1)) if n > 1 else 0.0
    return {"media": float(d.mean()), "lo": float(np.percentile(boots, 2.5)), "hi": float(np.percentile(boots, 97.5)),
            "p": float(p), "mde": float(2.8 * sd / max(n ** 0.5, 1.0)), "dz": r25_dz(d)}


def r25_status(media, p_holm, sentido=1.0):
    if p_holm < 0.05:
        return "confirmada" if media * sentido > 0 else "refutada"
    return "nula"


def r25_veredito_pecas(st: dict, sinal_insuficiente=False) -> dict:
    """Por peça: VIVE (confirmada nas duas tarefas) | VIVE EM 1 | DECORATIVA (nula nas duas) | NOCIVA (refutada em alguma)."""
    out = {}
    for nome, ha, hy, _ in R25_PECAS:
        a, y = st.get(ha), st.get(hy)
        vs = [a] if sinal_insuficiente else [a, y]
        if any(v == "refutada" for v in vs):
            out[nome] = "NOCIVA"
        elif all(v == "confirmada" for v in vs):
            out[nome] = "VIVE"
        elif any(v == "confirmada" for v in vs):
            out[nome] = "VIVE EM 1"
        else:
            out[nome] = "DECORATIVA"
    return out


# ---------------------------------------------------------------------------
# PARTE B — BitLinear ternário v2 (STE + backprop completo) e comparador denso
# ---------------------------------------------------------------------------
def r25_hw_feats(X, seed, sigma, nf=16):
    if not sigma:
        return np.asarray(X, dtype=float)
    rng = r25_rng(seed, r25_crc("fourier"), 3)
    B = rng.normal(0.0, float(sigma), size=(2, nf))
    Z = np.asarray(X, dtype=float) @ B
    return np.hstack([np.asarray(X, dtype=float), np.sin(Z), np.cos(Z)])


def r25_q_dense(W):
    return r24_trunc_fp16(W)


def r25_q_ternario(W):
    g = float(np.mean(np.abs(W))) + 1e-12
    return g * np.clip(np.round(W / g), -1.0, 1.0)


def r25_mlp_treinar(modo: str, seed: int, rung: dict):
    """modo 'dense_fp' | 'bit_v2'. Adam, BCE, backprop completo; bit: pesos ternarizados no forward, gradiente straight-through."""
    Xtr0, ytr = r24_espirais(seed, 400)
    Xte0, yte = r24_espirais(seed + 1, 200)
    Xtr = r25_hw_feats(Xtr0, seed, rung["fourier"])
    Xte = r25_hw_feats(Xte0, seed, rung["fourier"])
    d_in = Xtr.shape[1]
    H = int(rung["H"])
    dims = [d_in, H, H, 1]
    rng = r25_rng(seed, r25_crc(f"mlp2|{modo}"), 5)
    W = [rng.normal(0.0, math.sqrt(2.0 / dims[i]), size=(dims[i], dims[i + 1])) for i in range(3)]
    b = [np.zeros(dims[i + 1]) for i in range(3)]
    q = r25_q_dense if modo == "dense_fp" else r25_q_ternario
    mW = [np.zeros_like(w) for w in W]; vW = [np.zeros_like(w) for w in W]
    mb = [np.zeros_like(x) for x in b]; vb = [np.zeros_like(x) for x in b]
    lr, b1, b2, eps = R25_HW_LR, 0.9, 0.999, 1e-8
    n = len(ytr)
    yv = ytr.reshape(-1, 1)
    for t in range(1, int(rung["passos"]) + 1):
        Wq = [q(w) for w in W]
        hs = [Xtr]
        h = Xtr
        for i in range(3):
            z = h @ Wq[i] + b[i]
            h = np.maximum(0.0, z) if i < 2 else 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
            hs.append(h)
        dz = (hs[3] - yv) / n
        gW, gb = [None] * 3, [None] * 3
        for i in (2, 1, 0):
            gW[i] = hs[i].T @ dz            # STE: gradiente do peso quantizado aplicado aos latentes
            gb[i] = dz.sum(axis=0)
            if i > 0:
                dh = dz @ Wq[i].T
                dz = dh * (hs[i] > 0)
        for i in range(3):
            mW[i] = b1 * mW[i] + (1 - b1) * gW[i]; vW[i] = b2 * vW[i] + (1 - b2) * gW[i] ** 2
            mb[i] = b1 * mb[i] + (1 - b1) * gb[i]; vb[i] = b2 * vb[i] + (1 - b2) * gb[i] ** 2
            W[i] -= lr * (mW[i] / (1 - b1 ** t)) / (np.sqrt(vW[i] / (1 - b2 ** t)) + eps)
            b[i] -= lr * (mb[i] / (1 - b1 ** t)) / (np.sqrt(vb[i] / (1 - b2 ** t)) + eps)
    Wq = [q(w) for w in W]
    h = Xte
    mul = add = 0
    for i in range(3):
        z = h @ Wq[i] + b[i]
        if modo == "dense_fp":
            mul += h.shape[0] * Wq[i].shape[0] * Wq[i].shape[1]; add += mul
        else:
            nnz = int(np.count_nonzero(np.abs(Wq[i]) > 0))
            add += h.shape[0] * nnz
            mul += h.shape[0] * Wq[i].shape[1]      # 1 multiplicação por saída (escala γ)
        h = np.maximum(0.0, z) if i < 2 else 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
    acc = float(((h.reshape(-1) >= 0.5) == (yte >= 0.5)).mean())
    frac_zero = float(np.mean([np.mean(np.abs(w) < 1e-12) for w in Wq])) if modo == "bit_v2" else 0.0
    return {"acc": acc, "energia": float(1.0 * mul + 0.25 * add), "frac_zero": frac_zero, "modo": modo, "seed": int(seed)}


def r25_job_hw(task):
    """task = (rung_dict, seed, incluir_v1)"""
    rung, seed, v1 = task
    d = r25_mlp_treinar("dense_fp", seed, rung)
    b = r25_mlp_treinar("bit_v2", seed, rung)
    out = {"acc_dense": d["acc"], "acc_bit": b["acc"], "en_dense": d["energia"], "en_bit": b["energia"],
           "frac_zero": b["frac_zero"], "seed": int(seed)}
    if v1:
        out["acc_v1"] = float(r24_train_mlp("bitlinear", seed, 160, 0.15)["acc"])
    return out


def r25_escolher_rung(seeds_dev):
    """Primeiro degrau da escada em que, no DEV, acc(bit_v2)≥0,70 e acc(dense_fp)≥0,70. Se nenhum, degrau 3 (tentativa final)."""
    tab = []
    for rung in R25_ESCADA:
        rs = [r25_job_hw((rung, s, False)) for s in seeds_dev]
        a_b = float(np.mean([r["acc_bit"] for r in rs]))
        a_d = float(np.mean([r["acc_dense"] for r in rs]))
        tab.append((rung["g"], a_b, a_d))
        if a_b >= R25_HW_CRIT and a_d >= R25_HW_CRIT:
            return rung, tab, True
    return R25_ESCADA[-1], tab, False


def r25_regra_congelamento(st: dict) -> str:
    if st.get("B1") == "confirmada" and st.get("B2") == "confirmada" and st.get("B3") == "confirmada":
        return "BITLINEAR v2 ACIMA DO ACASO (proxy de brinquedo; não é BitNet real)"
    return "TETO DE BRINQUEDO PERMANENTE: módulo BitLinear CONGELADO"


def r25_tarefas(ctx):
    S = r25_sementes(r25_desloc())

    def _fn():
        tz = R25Hard()
        cfg = R25_CFG["stack_full"]
        tr = r25_treinar(tz, cfg, S["dev"][0], 0.10)
        ev = r25_avaliar(tz, cfg, tr, S["dev"][0], "stack_full")
        return {"stack_clean_dev": ev["r_clean"]}
    return _fn, ()


