def bloco33(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("BLOCO 33 — [R25] PILHA PADRÃO (RL ordinário + meta-recompensa calibrada + filtro-primeiro): ABLAÇÃO em texto HARD (A1–A7) e tarefa simbólica Z7 (Y1–Y7) "
               "+ BITLINEAR v2 (B1–B4) | 40 sementes; Holm GLOBAL sobre 18; prereg_r25.txt")
    desloc = r25_desloc()
    if desloc:
        rep.log(f"[R25_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r25_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    rapido = bool(getattr(ctx.args, "rapido", False))
    n_test = 12 if rapido else R25_NTEST

    ok_p = hashlib.sha256(PREREG_R25_CORPO.encode("utf-8")).hexdigest() == PREREG_R25_CORPO_SHA256
    rep.log(f"Pré-registro R25: sha256={PREREG_R25_CORPO_SHA256[:16]}… {'(CONFERE com versoes/prereg_r25.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R25_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R25_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R25_CORPO_SHA256
        rep.log(f"Adendo 1 R25: sha256={ADENDO1_R25_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")
        rep.log(f"Adendo 2 R25: sha256={hashlib.sha256(ADENDO2_R25_TEXTO.encode('utf-8')).hexdigest()[:16]}… — {ADENDO2_R25_TEXTO}")
    rep.log("ARQUITETURA TRAVADA: filtro-primeiro + τ FIXED (tela 0,40; laudo 0,55); delírio = explorador opcional; RL ordinário preferido; BitLinear/SNN = brinquedos-proxy.")
    rep.log("ORÇAMENTO IGUAL (correção do defeito R24): TODOS os braços RL fazem exatamente P atualizações de política; braços com meta gastam os primeiros ⌈P/3⌉ sem peso e o resto com peso P̂.")
    rep.log(f"  HARD: L={R24_L_HARD} V={R24_V_HARD} P={R25_P_HARD} | SIMBÓLICA Z{R25_SYM['V']}: L={R25_SYM['L']} lote={R25_SYM['B']} P={R25_SYM['P']} τ_y={R25_SYM['tau_y']} | porta k={R25_K_GATE}")

    # ---------- DEV ----------
    rep.sub("DEV — lr (braço rl_ord, mesmo lr para todos os RL), sinal mínimo da tarefa simbólica, degrau da escada BitLinear")
    lr, lr_tab, alea_dev = {}, {}, {}
    for fam in ("H", "Y"):
        lr[fam], lr_tab[fam], alea_dev[fam] = r25_escolher_lr(fam, S["dev"][:R25_NDEV])
        rep.log(f"  {fam}: lr*={lr[fam]} | r_clean DEV por lr: " + ", ".join(f"{k}→{v:+.3f}" for k, v in lr_tab[fam].items()) + f" | aleat DEV={alea_dev[fam]:+.3f}")
    sinal_ins = {f: bool(lr_tab[f][lr[f]] - alea_dev[f] < 0.05) for f in ("H", "Y")}
    rep.log(f"  sinal mínimo (rl_ord − aleat ≥ 0,05 no DEV): H={'OK' if not sinal_ins['H'] else 'INSUFICIENTE'} | Y={'OK' if not sinal_ins['Y'] else 'INSUFICIENTE'}")
    rung, tab_rung, rung_ok = r25_escolher_rung(S["dev"][:R25_NDEV])
    rep.log("  escada BitLinear v2 (DEV; degrau, acc_bit, acc_dense): " + " | ".join(f"g{g}: {a:.3f}/{d:.3f}" for g, a, d in tab_rung) +
            f" → degrau escolhido g{rung['g']} ({'critério ≥0,70 atendido' if rung_ok else 'NENHUM passou: tentativa final no degrau 3'})")

    # ---------- TESTE ----------
    rep.sub("TESTE — 8 braços × 2 tarefas + BitLinear (mesmas sementes por braço; r_clean limpo)")
    tasks, idx = [], []
    for fam in ("H", "Y"):
        for br in R25_BRACOS + R25_EXPL:
            for sd in S["test"][:n_test]:
                tasks.append((fam, br, sd, lr[fam], None)); idx.append((fam, br))
    for sd in S["test"][:n_test]:
        tasks.append(("B", rung, sd, True)); idx.append(("B", "hw"))
    outs = mapa_paralelo(r25_job, tasks, jobs)
    SC = {f: {b: {"r_clean": [], "keep": [], "ece_c": [], "ece_b": []} for b in R25_BRACOS + R25_EXPL} for f in ("H", "Y")}
    HW = {"acc_dense": [], "acc_bit": [], "acc_v1": [], "en_dense": [], "en_bit": [], "frac_zero": []}
    for (fam, br), o in zip(idx, outs):
        if fam == "B":
            for k in HW:
                HW[k].append(o[k])
        else:
            SC[fam][br]["r_clean"].append(o["r_clean"]); SC[fam][br]["keep"].append(o["keep_rate"])
            SC[fam][br]["ece_c"].append(o["ece_cal_oos"]); SC[fam][br]["ece_b"].append(o["ece_bruta_oos"])
    for fam, nm in (("H", "HARD"), ("Y", "SIMBÓLICA Z7")):
        rep.log(f"  [{nm}] r_clean por braço: " + " | ".join(f"{b}={float(np.mean(SC[fam][b]['r_clean'])):+.3f}" for b in R25_BRACOS))
    for fam, nm in (("H", "HARD"), ("Y", "Z7")):
        rep.log(f"  [{nm}] EXPLORATÓRIO (fora do Holm; Adendo 1) meta_norm = pilha com P̂ normalizado pela média do pré-treino: r_clean={float(np.mean(SC[fam]['meta_norm']['r_clean'])):+.3f}")
    rep.log(f"  [BitLinear] acc: dense_fp={float(np.mean(HW['acc_dense'])):.4f} bit_v2={float(np.mean(HW['acc_bit'])):.4f} bit_v1(R24)={float(np.mean(HW['acc_v1'])):.4f} | "
            f"energia-proxy (aritmética, NÃO joules) dense={float(np.mean(HW['en_dense'])):.0f} bit={float(np.mean(HW['en_bit'])):.0f} (razão {float(np.mean(HW['en_dense']))/max(float(np.mean(HW['en_bit'])),1):.2f}×) | zeros no ternário={float(np.mean(HW['frac_zero'])):.2f}")

    # ---------- Hipóteses ----------
    P = {}
    for h, (fam, a, b) in R25_PAR.items():
        d = np.asarray(SC[fam][a]["r_clean"]) - np.asarray(SC[fam][b]["r_clean"])
        P[h] = r25_pack(d, seed=r25_crc(h))
    P["B1"] = r25_pack(np.asarray(HW["acc_bit"]) - 0.5, seed=r25_crc("B1"))
    P["B2"] = r25_pack(np.asarray(HW["acc_dense"]) - 0.5, seed=r25_crc("B2"))
    P["B3"] = r25_pack(np.asarray(HW["acc_bit"]) - np.asarray(HW["acc_dense"]), seed=r25_crc("B3"), deslocar=R25_HW_MARGEM)
    P["B4"] = r25_pack(np.asarray(HW["acc_bit"]) - np.asarray(HW["acc_v1"]), seed=r25_crc("B4"))
    ph = holm([P[h]["p"] for h in R25_TODAS])
    st = {}
    for i, h in enumerate(R25_TODAS):
        P[h]["p_holm"] = float(ph[i])
        med = P[h]["media"]
        if h in ("B1", "B2"):
            st[h] = "confirmada" if (ph[i] < 0.05 and med > 0 and med + 0.5 >= R25_HW_CRIT) else ("nula" if not (ph[i] < 0.05 and med < 0) else "refutada")
        elif h == "B3":
            st[h] = r25_status(med + R25_HW_MARGEM, ph[i])
        else:
            st[h] = r25_status(med, ph[i])
    rep.sub("Hipóteses (Δ = stack_full − braço; d_z pareado; Holm GLOBAL sobre 18)")
    desc = r25_desc_hipoteses()
    for h in R25_TODAS:
        p = P[h]
        rep.log(f"  {h} [{desc[h]}]: Δ={p['media']:+.4f} d_z={p['dz']:+.2f} IC95%[{p['lo']:+.4f},{p['hi']:+.4f}] p={p['p']:.4f} Holm={p['p_holm']:.4f} MDE={p['mde']:.4f} → {st[h]}")
    expl = {}
    for fam, nm in (("H", "HARD"), ("Y", "Z7")):
        for rot, a_, b_ in (("meta_norm − sem_meta", "meta_norm", "sem_meta"), ("meta_norm − stack_full", "meta_norm", "stack_full")):
            d = np.asarray(SC[fam][a_]["r_clean"]) - np.asarray(SC[fam][b_]["r_clean"])
            pk = r25_pack(d, seed=r25_crc(f"E|{fam}|{rot}"))
            expl[f"{fam}:{rot}"] = (pk["media"], pk["lo"], pk["hi"], pk["p"], pk["dz"])
            rep.log(f"  EXPLORATÓRIA [{nm}] {rot}: Δ={pk['media']:+.4f} d_z={pk['dz']:+.2f} IC95%[{pk['lo']:+.4f},{pk['hi']:+.4f}] p={pk['p']:.4f} (sem correção; não entra no veredito)")
    rep.log("  LEITURA DO A5: no HARD o proxy bruto (r24_proxy_texto) é um dos três termos do r_clean; logo, treinar no proxy bruto alinha quase por construção com a métrica limpa. A5 refutada mede em boa parte essa circularidade, não a inutilidade do filtro; a Z7 (verificador de regra, sem circularidade) é o teste limpo do filtro (Y5).")
    pecas = r25_veredito_pecas(st, sinal_insuficiente=sinal_ins["Y"])
    rep.sub("Veredito por peça da pilha padrão (regra fixa do prereg)")
    for nome, ha, hy, _ in R25_PECAS:
        rep.log(f"  {nome}: {pecas[nome]}  ({ha}={st[ha]}, {hy}={st[hy]})")
    ece_c = float(np.nanmean(SC["H"]["stack_full"]["ece_c"])); ece_b = float(np.nanmean(SC["H"]["stack_full"]["ece_b"]))
    ece_cy = float(np.nanmean(SC["Y"]["stack_full"]["ece_c"])); ece_by = float(np.nanmean(SC["Y"]["stack_full"]["ece_b"]))
    rep.log(f"  ECE da meta FORA DA AMOSTRA (fase com peso; descritivo): HARD cal={ece_c:.3f} bruta={ece_b:.3f} | SIMBÓLICA cal={ece_cy:.3f} bruta={ece_by:.3f}")
    manter = [n for n, v in pecas.items() if v in ("VIVE", "VIVE EM 1")]
    opcional = [n for n, v in pecas.items() if v in ("DECORATIVA", "NOCIVA")]
    ver_pilha = ("PILHA PADRÃO: manter = [" + ", ".join(manter) + "]; opcional = [" + ", ".join(opcional) + "]")
    rep.log("VEREDITO PILHA (regra pré-registrada): " + ver_pilha)
    ver_hw = r25_regra_congelamento(st)
    rep.log("VEREDITO BITLINEAR (regra de congelamento): " + ver_hw)
    n_conf = sum(1 for h in R25_TODAS if st[h] == "confirmada")
    n_ref = sum(1 for h in R25_TODAS if st[h] == "refutada")
    n_nula = sum(1 for h in R25_TODAS if st[h] == "nula")
    rep.log(f"RESUMO R25: {n_conf} confirmadas, {n_ref} refutadas, {n_nula} nulas de {len(R25_TODAS)}")
    rep.log("→ Continua NÃO sendo ASI/AGI. Filtro-primeiro permanece MOTOR. Mega-Sena não reaberta. Tarefas sintéticas; ganho em r_clean não é inteligência.")
    ctx.res["r25"] = {
        "P": {k: (v["media"], v["lo"], v["hi"], v["p"], v["p_holm"], v["mde"], v["dz"]) for k, v in P.items()},
        "st": st, "n_conf": n_conf, "n_ref": n_ref, "n_nula": n_nula, "chaves": list(R25_TODAS),
        "pecas": pecas, "ver_pilha": ver_pilha, "ver_hw": ver_hw, "manter": manter, "opcional": opcional,
        "sc": {f: {b: float(np.mean(SC[f][b]["r_clean"])) for b in R25_BRACOS} for f in ("H", "Y")},
        "hw": {k: float(np.mean(v)) for k, v in HW.items()}, "rung": rung["g"], "rung_ok": bool(rung_ok),
        "lr": lr, "sinal_ins": sinal_ins, "ece": {"H": (ece_c, ece_b), "Y": (ece_cy, ece_by)}, "desloc": desloc,
        "congelado_bitlinear": ver_hw.startswith("TETO"), "expl": expl,
    }
    return ctx.res["r25"]


def r25_desc_hipoteses():
    d = {}
    nomes = {"aleat": "aleat", "sem_rl": "−RL", "sem_meta": "−meta", "meta_bruta": "−calibração", "sem_filtro": "−filtro",
             "extraord": "ordinário vs extraord.", "sem_porta": "−porta"}
    for h, (fam, a, b) in R25_PAR.items():
        d[h] = f"{'HARD' if fam == 'H' else 'Z7'}: stack_full − {b} ({nomes[b]})"
    d["B1"] = "acc(bit_v2) − 0,5; confirmada só se média ≥ 0,70"
    d["B2"] = "acc(dense_fp) − 0,5; confirmada só se média ≥ 0,70"
    d["B3"] = "acc(bit_v2) − acc(dense_fp) ≥ −0,05 (não-inferioridade)"
    d["B4"] = "acc(bit_v2) − acc(bit_v1 R24)"
    return d


def registro_r25(ctx: Contexto) -> list:
    r = ctx.res.get("r25")
    if not r:
        return []
    L = [f"REGISTRO R25 (BLOCO 33) — {r['n_conf']} confirmadas / {r['n_ref']} refutadas / {r['n_nula']} nulas de 18 (Holm global)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} d_z={p[6]:+.2f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append("  PEÇAS: " + " | ".join(f"{k}={v}" for k, v in r["pecas"].items()))
    L.append(f"  {r['ver_pilha']}")
    L.append(f"  BITLINEAR: {r['ver_hw']}")
    return L


