def r25_estado_bloco(args, nome: str) -> str:
    for fn, tag in (("r25_dormente_ativo", "R25"), ("r23_dormente_ativo", "R23"), ("r19_dormente_ativo", "R19"),
                    ("r14_dormente_ativo", "R14"), ("r13_dormente_ativo", "R13"), ("r12_dormente_ativo", "R12")):
        try:
            if globals()[fn](args, nome):
                return f"DORMENTE ({tag}, congelado sha256)"
        except Exception:  # noqa: BLE001
            pass
    return "ATIVO"


