R26_CONGELADO_B64 = "".join(R26_CONGELADO_B64_CHUNKS)

_R26_CONG_CACHE = {"v": None}


def r26_congelado():
    if _R26_CONG_CACHE["v"] is not None:
        return _R26_CONG_CACHE["v"]
    if not R26_CONGELADO_B64 or R26_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R26_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R26_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R26_CONG_CACHE["v"] = v
    return v


def r26_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if any(os.environ.get(v) for v in R26_ENV_VIVO):
        return False
    cg = r26_congelado()
    return cg is not None and nome in cg


def _dormente26(nome, vivo):
    def w(ctx):
        rot = R26_DORMENTES[nome]
        est = ctx.res.setdefault("r26_dorm", {})
        if r26_dormente_ativo(ctx.args, nome):
            cg = r26_congelado()[nome]
            ctx.rep.log(
                f"[R26 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R25 inalterado "
                f"(--offline --jobs 8, semente 42; sha256 {R26_CONGELADO_SHA256[:12]}… CONFERE; origem {R26_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r26_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R26 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w



