def r26_desloc() -> int:
    v = os.environ.get("R26_DEV")
    if not v or v in ("0", "false", "False", "no", "off", ""):
        return 0
    return 10000


def r26_crc(rot: str) -> int:
    return zlib.crc32(f"R26|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r26_sementes(desloc=0):
    d = int(desloc)
    return {"dev": [s + d for s in R26_SEEDS_DEV], "test": [s + d for s in R26_SEEDS_TEST]}


# ---------------------------------------------------------------------------
# Desempenho: medianas por linha de M em cache (usado por r24_proxy_texto; bit-idêntico a np.median(M[a]))
# ---------------------------------------------------------------------------
_R26_MED_CACHE = {}


def _r26_med_rows(M):
    k = id(M)
    v = _R26_MED_CACHE.get(k)
    if v is None or v[0] is not M:
        v = (M, np.median(M, axis=1))
        _R26_MED_CACHE[k] = v
    return v[1]


# ---------------------------------------------------------------------------
# Tarefas
# ---------------------------------------------------------------------------
_R26_M_CACHE = {}


class R26Hard(R25Hard):
    """Texto HARD parametrizado (V, L, matriz de transição por seed_lex); resto = R25Hard sem alteração."""

    def __init__(self, nome, V, L, seed_lex, P):
        key = (int(V), int(seed_lex))
        if key not in _R26_M_CACHE:
            vocab = r24_vocab(int(V), int(seed_lex))
            _R26_M_CACHE[key] = r24_markov2(vocab, int(seed_lex), hard=True)
        self.M = _R26_M_CACHE[key]
        self.V = int(V)
        self.L = int(L)
        self.P = int(P)
        self.nome = nome


def r26_tarefa(nome: str):
    if nome in R26_PRM_SYM:
        t = R25Sym(R26_PRM_SYM[nome])
        t.nome = nome
        return t
    p = R26_PRM_HARD[nome]
    return R26Hard(nome, p["V"], p["L"], p["seed_lex"], p["P"])


def r26_alinhamento(nome: str, seeds_dev, n=200) -> float:
    """EXPLORATÓRIO: ρ de Spearman entre o proxy bruto e o r_clean em n amostras uniformes (sementes DEV)."""
    tz = r26_tarefa(nome)
    rng = r25_rng(int(seeds_dev[0]), r26_crc(f"alin|{nome}"), 7)
    px, rc = [], []
    for i in range(int(n)):
        ids = tz.sample_uniform(rng)
        lau = tz.laudo(ids, int(seeds_dev[0]), 7000 + i)
        px.append(float(lau["proxy"]))
        rc.append(float(tz.r_clean(ids)))
    px, rc = np.asarray(px), np.asarray(rc)
    if px.std() < 1e-12 or rc.std() < 1e-12:
        return 0.0
    rx = np.argsort(np.argsort(px)).astype(float)
    ry = np.argsort(np.argsort(rc)).astype(float)
    return float(np.corrcoef(rx, ry)[0, 1])


# ---------------------------------------------------------------------------
# Jobs (texto/simbólico)
# ---------------------------------------------------------------------------
def r26_job_texto(task):
    """task = ('T', tarefa, braco, seed, lr)"""
    _, tn, braco, seed, lr = task
    tz = r26_tarefa(tn)
    cfg = R26_CFG[braco]
    if cfg["uniforme"]:
        tr = {"pol": None}
    else:
        tr = r25_treinar(tz, cfg, seed, lr)
    ev = r25_avaliar(tz, cfg, tr, seed, f"{tn}|{braco}")
    return {"tarefa": tn, "braco": braco, "seed": int(seed), "r_clean": float(ev["r_clean"]), "keep": float(ev["keep_rate"]),
            "ece_cal": float(tr.get("ece_cal_oos", float("nan"))), "ece_bruta": float(tr.get("ece_bruta_oos", float("nan")))}


def r26_escolher_modo(medias: dict) -> str:
    """Regra FIXA do prereg: início ON; LEVE e depois OFF só substituem se superarem o atual por > 0,01 (empate favorece ON)."""
    m = "ON"
    for c in ("LEVE", "OFF"):
        if medias[c] > medias[m] + R26_MARGEM_SW:
            m = c
    return m


# ---------------------------------------------------------------------------
# Hipóteses (pooled por semente)
# ---------------------------------------------------------------------------
def r26_pool(SC, escolha, tarefas=R26_TAREFAS):
    """Média sobre as tarefas do r_clean por semente. escolha: callable(tarefa)->braço."""
    return np.mean([np.asarray(SC[t][escolha(t)]) for t in tarefas], axis=0)


def r26_hipoteses_AB(SC, modos, modo_global):
    ad = r26_pool(SC, lambda t: modos[t])
    on = r26_pool(SC, lambda t: "ON")
    off = r26_pool(SC, lambda t: "OFF")
    gl = r26_pool(SC, lambda t: modo_global)
    al = r26_pool(SC, lambda t: "aleat")
    D = {"S1": ad - on, "S2": ad - off, "S3": ad - gl, "L1": ad - al}
    for fam in ("Z", "H"):
        ts = [t for t in R26_TAREFAS if R26_FAMILIA[t] == fam]
        mn = r26_pool(SC, lambda t: "meta_norm", ts)
        D[f"M1_{fam}"] = mn - r26_pool(SC, lambda t: "ON", ts)
        D[f"M2_{fam}"] = mn - r26_pool(SC, lambda t: "meta_bruta", ts)
    return D


def r26_veredito_meta(st: dict) -> str:
    a, b = st.get("M1_Z"), st.get("M1_H")
    if "refutada" in (a, b):
        v = "NOCIVA"
    elif a == "confirmada" and b == "confirmada":
        v = "VIVE"
    elif "confirmada" in (a, b):
        v = "VIVE EM 1"
    else:
        v = "DECORATIVA"
    conserta = [k for k in ("M2_Z", "M2_H") if st.get(k) == "confirmada"]
    return f"META NORMALIZADA: {v} (M1_Z={a}, M1_H={b}); conserta a meta bruta em: {', '.join(conserta) if conserta else 'nenhuma família'}; " + \
           ("meta passa a compor a pilha padrão" if v == "VIVE" else "meta permanece OPCIONAL (fora da pilha padrão)")


def r26_regra_adocao(st: dict, modos: dict, modo_global: str) -> str:
    esc = ", ".join(f"{t}:{modos[t]}" for t in R26_TAREFAS)
    if st.get("S3") == "confirmada":
        return f"FILTRO: INTERRUPTOR ADAPTATIVO ADOTADO (S3 confirmada; modos por tarefa [{esc}])"
    return f"FILTRO: padrão = modo global fixo «{modo_global}» (S3 {st.get('S3')}); a dependência da tarefa é só DESCRITA (DEV escolheu [{esc}])"


def r26_regra_hw(st: dict, medias: dict) -> str:
    gap = (medias["acc_dense"] - medias["acc_bit"]) * 100.0
    teto = medias["acc_dense"] > R26_HW_TETO
    sfx = " [TAREFA AINDA NO TETO]" if teto else ""
    if st.get("C1") != "confirmada":
        return "BITLINEAR v2 CONGELADO: colapsa para o acaso (ou <0,60) na tarefa difícil" + sfx
    if st.get("C2") != "confirmada":
        return "TAREFA INVÁLIDA PARA O DENSO: BitLinear não avaliado; sem veredito (não congela)" + sfx
    if st.get("C3") == "confirmada" and not teto:
        return "BITLINEAR v2 ATIVO (proxy de brinquedo): não-inferior ao denso na tarefa difícil"
    if st.get("C3") == "refutada":
        return f"BITLINEAR v2 ATIVO COM GAP: abaixo do denso em {gap:.1f} p.p. (proxy de brinquedo)" + sfx
    return "BITLINEAR v2 INCONCLUSIVO: não-inferioridade não demonstrada" + sfx


# ---------------------------------------------------------------------------
# PARTE C — espirais difíceis + BitLinear v2
# ---------------------------------------------------------------------------
def r26_espirais(seed: int, n: int, voltas: float, sx: float):
    rng = r25_rng(seed, r26_crc("espirais_dificeis"), 3)
    n2 = int(n) // 2
    T = 2.0 * np.pi * float(voltas)
    t0 = rng.uniform(0, T, n2)
    t1 = rng.uniform(0, T, n2)
    r0 = 0.2 + 0.5 * t0 / T
    r1 = 0.2 + 0.5 * t1 / T
    x0 = np.stack([r0 * np.cos(t0), r0 * np.sin(t0)], axis=1)
    x1 = np.stack([r1 * np.cos(t1 + np.pi), r1 * np.sin(t1 + np.pi)], axis=1)
    X = np.vstack([x0, x1]).astype(np.float64)
    X = X + rng.normal(0.0, float(sx), size=X.shape)
    y = np.concatenate([np.zeros(n2), np.ones(n2)]).astype(np.float64)
    idx = rng.permutation(2 * n2)
    return X[idx], y[idx]


def r26_mlp_treinar(modo: str, seed: int, nivel: dict, rung=None):
    """Igual ao r25_mlp_treinar (Adam, BCE, backprop completo; bit: ternário no forward + STE), mas nas espirais DIFÍCEIS do nível dado."""
    rung = rung or R26_HW_RUNG
    Xtr0, ytr = r26_espirais(seed, nivel["ntr"], nivel["voltas"], nivel["sx"])
    Xte0, yte = r26_espirais(seed + 1, 200, nivel["voltas"], nivel["sx"])
    Xtr = r25_hw_feats(Xtr0, seed, rung["fourier"])
    Xte = r25_hw_feats(Xte0, seed, rung["fourier"])
    d_in = Xtr.shape[1]
    H = int(rung["H"])
    dims = [d_in, H, H, 1]
    rng = r25_rng(seed, r26_crc(f"mlp|{modo}|{nivel['n']}"), 5)
    W = [rng.normal(0.0, math.sqrt(2.0 / dims[i]), size=(dims[i], dims[i + 1])) for i in range(3)]
    b = [np.zeros(dims[i + 1]) for i in range(3)]
    q = r25_q_dense if modo == "dense_fp" else r25_q_ternario
    mW = [np.zeros_like(w) for w in W]; vW = [np.zeros_like(w) for w in W]
    mb = [np.zeros_like(x) for x in b]; vb = [np.zeros_like(x) for x in b]
    lr, b1, b2, eps = R25_HW_LR, 0.9, 0.999, 1e-8
    n = len(ytr)
    yv = ytr.reshape(-1, 1)
    for t in range(1, int(rung["passos"]) + 1):
        Wq = [q(w) for w in W]
        hs = [Xtr]
        h = Xtr
        for i in range(3):
            z = h @ Wq[i] + b[i]
            h = np.maximum(0.0, z) if i < 2 else 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
            hs.append(h)
        dz = (hs[3] - yv) / n
        gW, gb = [None] * 3, [None] * 3
        for i in (2, 1, 0):
            gW[i] = hs[i].T @ dz
            gb[i] = dz.sum(axis=0)
            if i > 0:
                dh = dz @ Wq[i].T
                dz = dh * (hs[i] > 0)
        for i in range(3):
            mW[i] = b1 * mW[i] + (1 - b1) * gW[i]; vW[i] = b2 * vW[i] + (1 - b2) * gW[i] ** 2
            mb[i] = b1 * mb[i] + (1 - b1) * gb[i]; vb[i] = b2 * vb[i] + (1 - b2) * gb[i] ** 2
            W[i] -= lr * (mW[i] / (1 - b1 ** t)) / (np.sqrt(vW[i] / (1 - b2 ** t)) + eps)
            b[i] -= lr * (mb[i] / (1 - b1 ** t)) / (np.sqrt(vb[i] / (1 - b2 ** t)) + eps)
    Wq = [q(w) for w in W]
    h = Xte
    mul = add = 0
    for i in range(3):
        z = h @ Wq[i] + b[i]
        if modo == "dense_fp":
            mul += h.shape[0] * Wq[i].shape[0] * Wq[i].shape[1]; add += mul
        else:
            nnz = int(np.count_nonzero(np.abs(Wq[i]) > 0))
            add += h.shape[0] * nnz
            mul += h.shape[0] * Wq[i].shape[1]
        h = np.maximum(0.0, z) if i < 2 else 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
    acc = float(((h.reshape(-1) >= 0.5) == (yte >= 0.5)).mean())
    # acurácia de treino (diagnóstico de sobreajuste; descritivo)
    frac_zero = float(np.mean([np.mean(np.abs(w) < 1e-12) for w in Wq])) if modo == "bit_v2" else 0.0
    return {"acc": acc, "energia": float(1.0 * mul + 0.25 * add), "frac_zero": frac_zero, "modo": modo, "seed": int(seed)}


def r26_job_hw(task):
    """task = ('B', nivel_dict, seed)"""
    _, nivel, seed = task
    d = r26_mlp_treinar("dense_fp", seed, nivel)
    b = r26_mlp_treinar("bit_v2", seed, nivel)
    return {"acc_dense": d["acc"], "acc_bit": b["acc"], "en_dense": d["energia"], "en_bit": b["energia"],
            "frac_zero": b["frac_zero"], "seed": int(seed), "nivel": int(nivel["n"])}


def r26_job(task):
    return r26_job_hw(task) if task[0] == "B" else r26_job_texto(task)


def r26_escolher_nivel(tab: list):
    """tab = [(n, acc_bit, acc_dense), ...] na ordem da escada. Regra FIXA do prereg."""
    lo, hi = R26_HW_FAIXA
    for n, a_b, a_d in tab:
        if lo <= a_d <= hi:
            return n, True
    n_best = min(tab, key=lambda r: abs(r[2] - R26_HW_ALVO))[0]
    return n_best, False


