def _r26_mapa_linhas():
    out = []
    for row in R25_MAPA:
        if row[0] == "bloco33":
            out.append(("bloco33", ("bloco33",), "R25", "Ablação da pilha padrão + tarefa Z7 + BitLinear v2 (fácil)", None,
                        "13 conf / 2 ref / 3 nulas: RL, ordinário>extraord., porta VIVEM; meta NOCIVA; filtro depende da tarefa; BitLinear v2 acima do acaso só em tarefa fácil"))
        elif row[0] == "nexus_lexico.py":
            out.append(("nexus_lexico.py", (), "R1–R26", "Companion stdlib-only autodocumentado + auditor RECUSA", "ATIVO", "1.9.0; roda offline; demo do interruptor adaptativo em Z7/Z5"))
        elif row[0] == "asi_metacognitivo_enxuto.py":
            out.append(("asi_metacognitivo_enxuto.py", (), "R15–R26", "Só o que sobreviveu (numpy-only)", "ATIVO", "demo <60 s; autoteste próprio"))
        else:
            out.append(row)
    ix = [i for i, r_ in enumerate(out) if r_[0] == "nexus_lexico.py"][0]
    out.insert(ix, ("bloco34", ("bloco34",), "R26", "Pilha travada + interruptor adaptativo do filtro + meta normalizada + BitLinear difícil", "ATIVO",
                    "ver BLOCO 34 (veredito do filtro, da meta normalizada e do BitLinear v2 na tarefa difícil)"))
    return tuple(out)


R26_MAPA = _r26_mapa_linhas()


def r26_estado_bloco(args, nome: str) -> str:
    try:
        if r26_dormente_ativo(args, nome):
            return "DORMENTE (R26, congelado sha256)"
    except Exception:  # noqa: BLE001
        pass
    return r25_estado_bloco(args, nome)


def mapa_do_que_vive_linhas_r26(ctx: Contexto) -> list:
    r = ctx.res.get("r26") or {}
    L = []
    L.append("MAPA DO QUE VIVE (26 rodadas) — estado de cada bloco derivado das funções de dormência do próprio código")
    L.append("estados: ATIVO = roda ao vivo | DORMENTE = resultado congelado (sha256), recálculo atrás de --reativar-dormentes | CONGELADO = módulo encerrado | NÚCLEO-MATEMÁTICO = fato verificável, não evidência de cognição")
    L.append(f"{'módulo/bloco':<28}{'rodada':<9}{'estado':<38}tema → evidência")
    for rotulo, nomes, rod, tema, fixo, evid in R26_MAPA:
        if fixo:
            est = fixo
        else:
            ests = sorted(set(r26_estado_bloco(ctx.args, n) for n in nomes)) or ["ATIVO"]
            est = ests[0] if len(ests) == 1 else "MISTO: " + "/".join(e.split(" ")[0] for e in ests)
        L.append(f"{rotulo:<28}{rod:<9}{est:<38}{tema} → {evid}")
    L.append("--- módulos transversais (estado pelo veredito desta execução) ---")
    st = r.get("st", {})
    cong = bool(r.get("congelado_bitlinear", False))
    vf = r.get("ver_filtro", "?")
    vm = r.get("ver_meta", "?")
    meta_v = vm.split(":")[1].split("(")[0].strip() if ":" in vm else "?"
    trans = [
        ("filtro-primeiro (τ fixo)", "R20", "ATIVO (motor)", "R19 'filtro é toda a história'; R23–R26 replicam; modo por tarefa: " + ("interruptor adaptativo" if st.get("S3") == "confirmada" else "global fixo")),
        ("interruptor do filtro", "R26", "ATIVO (padrão)" if st.get("S3") == "confirmada" else "DESCRITIVO (global fixo)", vf[:110]),
        ("RL ordinário", "R19–R26", "ATIVO (pilha padrão TRAVADA)", "R23 S1/S2, R24 H1/H2; R25 A1/Y1; R26 L1"),
        ("RL extraordinário", "R19–R26", "DORMENTE/REFUTADO", "R23 S3, R24 H3 refutadas; R25 A6/Y6"),
        ("porta de geração k=4", "R25–R26", "ATIVO (pilha padrão TRAVADA)", "R25 A7/Y7 VIVE; presente em ON/LEVE"),
        ("meta-recompensa (calibrada/bruta)", "R24–R26", "OPCIONAL [NOCIVA na R25]", "R25 A3/Y3 (orçamento igual): dano na Z7"),
        ("meta-recompensa NORMALIZADA", "R26", "OPCIONAL" if meta_v != "VIVE" else "ATIVO", f"R26 M1/M2: {meta_v}"),
        ("delírio", "R3–R22", "OPCIONAL (explorador)", "sem ganho além do filtro"),
        ("BitLinear ternário v2 (STE)", "R25–R26", "CONGELADO (colapso na tarefa difícil)" if cong else "ATIVO (proxy; não é BitNet)", r.get("ver_hw", "?")[:110]),
        ("BitLinear v1 (R24)", "R24", "CONGELADO", "Acc≈0,50 (acaso); superado pelo v2"),
        ("SNN LIF (R24)", "R24", "CONGELADO", "Acc≈0,50; só sparsity documentada"),
        ("prefill/decode (intensidade)", "R24", "NÚCLEO-MATEMÁTICO", "razão aritmética; não é medição de hardware"),
        ("Mega-Sena", "R18", "DORMENTE (nulo honesto)", "nenhum método bate o acaso após correção"),
    ]
    for n, rod, est, ev in trans:
        L.append(f"{n:<28}{rod:<9}{est:<38}{ev}")
    return L



