def r27_desloc() -> int:
    v = os.environ.get("R27_DEV")
    if not v or v in ("0", "false", "False", "no", "off", ""):
        return 0
    return 10000


def r27_crc(rot: str) -> int:
    return zlib.crc32(f"R27|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r27_sementes(desloc=0):
    d = int(desloc)
    return {"dev": [s + d for s in R27_SEEDS_DEV], "test": [s + d for s in R27_SEEDS_TEST],
            "hw_dev": [s + d for s in R27_SEEDS_HW_DEV], "hw_s": [s + d for s in R27_SEEDS_HW_S], "hw_x": [s + d for s in R27_SEEDS_HW_X]}


# ---------------------------------------------------------------------------
# Tarefas
# ---------------------------------------------------------------------------
_R27_LM_CACHE = {}


def _r27_lm(M):
    """0,55·log(M+1e-12) por matriz (cache; elemento a elemento ⇒ bit-idêntico à conta feita linha a linha em r24_sample_policy)."""
    k = id(M)
    v = _R27_LM_CACHE.get(k)
    if v is None or v[0] is not M:
        v = (M, 0.55 * np.log(M + 1e-12))
        _R27_LM_CACHE[k] = v
    return v[1]


class R27Hard(R26Hard):
    """R26Hard com amostragem RÁPIDA e BIT-IDÊNTICA a r24_sample_policy (temp=1): LM em cache, softmax sem np.clip (z ≤ 0 ⇒ só o piso −60 age),
    categórica por cumsum+searchsorted exatamente como Generator.choice(p=…). Verificado no autoteste contra a implementação original."""

    def sample(self, pol, rng):
        V = pol["V"]
        W, b = pol["W"], pol["b"]
        LM = _r27_lm(self.M)
        prev = int(rng.integers(0, V))
        ids = [prev]
        logps = []
        for _ in range(self.L - 1):
            logits = W[prev] + b + LM[prev]
            z = logits - logits.max()
            e = np.exp(np.maximum(z, -60.0))
            p = e / (e.sum() + 1e-12)
            cdf = p.cumsum()
            cdf /= cdf[-1]
            nxt = int(cdf.searchsorted(rng.random(), side="right"))
            logps.append(float(np.log(p[nxt] + 1e-12)))
            ids.append(nxt)
            prev = nxt
        return ids, logps


class R27Sym(R25Sym):
    """R25Sym com a categórica por cumsum+searchsorted (bit-idêntica ao laço sequencial c += p[k]; primeiro k com u < c; senão V−1)."""

    def sample(self, pol, rng):
        ids, trace = [], []
        V = self.V
        Wm = pol["W"]
        for t in range(self.L):
            s = self._state(ids, t)
            z = Wm[s]
            p = np.exp(z - z.max())
            p = p / p.sum()
            u = float(rng.random())
            x = int(p.cumsum().searchsorted(u, side="right"))
            if x > V - 1:
                x = V - 1
            trace.append((s, x, p))
            ids.append(x)
        return ids, trace


def r27_tarefa(nome: str):
    if nome in R27_PRM_SYM:
        t = R27Sym(R27_PRM_SYM[nome])
        t.nome = nome
        return t
    p = R27_PRM_HARD[nome]
    return R27Hard(nome, p["V"], p["L"], p["seed_lex"], p["P"])


def r27_cfg_pf():
    return dict(R26_CFG["ON"])       # recompensa do filtro, sem meta (a porta só age na avaliação)


def r27_cfg_pr():
    return dict(R26_CFG["LEVE"])     # recompensa bruta, sem meta


def r27_cfg_pm(modo: str):
    """Meta normalizada sobre o modo adaptativo: mesma recompensa do modo (filtro se ON; bruta se LEVE/OFF); mesmo nº de atualizações."""
    return dict(rl=True, uniforme=False, gate=(modo != "OFF"), meta="norm", recompensa=("filtro" if modo == "ON" else "raw"), extra=False)


def r27_k_modo(modo: str) -> int:
    return 1 if modo == "OFF" else R25_K_GATE


# ---------------------------------------------------------------------------
# Avaliação com candidatos ANINHADOS (melhor-de-k para k=1,2,4,8 a partir dos MESMOS candidatos); chave de desempate = a da R25
# ---------------------------------------------------------------------------
def r27_avaliar_aninhado(tarefa, pol, seed: int, rotulo: str, kmax: int = 8):
    rng = r25_rng(seed, r25_crc(f"eval27|{tarefa.nome}|{rotulo}"), 13)
    ks = [k for k in R27_KS if k <= int(kmax)]
    kmax = max(ks)
    cl = {k: [] for k in ks}
    kp = {k: 0 for k in ks}
    for i in range(R25_N_EVAL):
        melhor, ms, mp, mlau = None, -1e9, False, None
        for j in range(kmax):
            ids = tarefa.sample(pol, rng)[0]
            lau = tarefa.laudo(ids, seed, 5000 + i * 10 + j)
            chave = (1 if lau["passa_tela"] else 0, lau["score_laudo"])
            if melhor is None or chave > (1 if mp else 0, ms):
                melhor, ms, mp, mlau = ids, lau["score_laudo"], lau["passa_tela"], lau
            if (j + 1) in cl:
                cl[j + 1].append(tarefa.r_clean(melhor))
                kp[j + 1] += 1 if mlau["mantem"] else 0
    return {k: (float(np.mean(cl[k])), kp[k] / float(R25_N_EVAL)) for k in ks}


def r27_job_lr(task):
    """task = ('L', tarefa, seed, lr): braço RL ordinário com recompensa do filtro, sem porta (k=1) e sem meta — só para escolher lr no DEV."""
    _, tn, seed, lr = task
    tz = r27_tarefa(tn)
    tr = r25_treinar(tz, R25_CFG["rl_ord"], seed, lr)
    ev = r25_avaliar(tz, R25_CFG["rl_ord"], tr, seed, f"{tn}|rl_ord")
    return {"tarefa": tn, "seed": int(seed), "lr": float(lr), "r_clean": float(ev["r_clean"])}


def r27_job_dev(task):
    """task = ('D', tarefa, seed, lr): treina Pf e Pr, avalia aninhado até k=8 + aleat."""
    _, tn, seed, lr = task
    tz = r27_tarefa(tn)
    pf = r25_treinar(tz, r27_cfg_pf(), seed, lr)
    pr = r25_treinar(tz, r27_cfg_pr(), seed, lr)
    ef = r27_avaliar_aninhado(tz, pf["pol"], seed, "Pf", 8)
    er = r27_avaliar_aninhado(tz, pr["pol"], seed, "Pr", 8)
    al = r25_avaliar(tz, R25_CFG["aleat"], {"pol": None}, seed, f"{tn}|aleat")
    return {"tarefa": tn, "seed": int(seed), "Pf": {k: v[0] for k, v in ef.items()}, "Pr": {k: v[0] for k, v in er.items()}, "aleat": float(al["r_clean"])}


def r27_job_teste(task):
    """task = ('T', tarefa, seed, lr, modo): treina Pf, Pr e Pm (meta_norm sobre o modo) e avalia (aninhado)."""
    _, tn, seed, lr, modo = task
    tz = r27_tarefa(tn)
    pf = r25_treinar(tz, r27_cfg_pf(), seed, lr)
    pr = r25_treinar(tz, r27_cfg_pr(), seed, lr)
    pm = r25_treinar(tz, r27_cfg_pm(modo), seed, lr)
    ef = r27_avaliar_aninhado(tz, pf["pol"], seed, "Pf", 8 if modo == "ON" else 4)
    er = r27_avaliar_aninhado(tz, pr["pol"], seed, "Pr", 8 if modo != "ON" else 4)
    em = r27_avaliar_aninhado(tz, pm["pol"], seed, "Pm", 4)
    al = r25_avaliar(tz, R25_CFG["aleat"], {"pol": None}, seed, f"{tn}|aleat")
    return {"tarefa": tn, "seed": int(seed), "Pf": {k: v[0] for k, v in ef.items()}, "Pr": {k: v[0] for k, v in er.items()},
            "Pm": {k: v[0] for k, v in em.items()}, "keepf": ef[4][1], "keepr": er[4][1], "keepm": em[4][1], "aleat": float(al["r_clean"]),
            "ece_cal": float(pm.get("ece_cal_oos", float("nan"))), "ece_bruta": float(pm.get("ece_bruta_oos", float("nan")))}


def r27_modo_r_clean(ent: dict, modo: str, k_ref=None):
    """Valor de um modo a partir de um resultado de job: ON=Pf@4; LEVE=Pr@4; OFF=Pr@1."""
    if modo == "ON":
        return ent["Pf"][4]
    if modo == "LEVE":
        return ent["Pr"][4]
    return ent["Pr"][1]


def r27_escolher_k(m_k: dict) -> int:
    """Regra FIXA: o MENOR k cuja média DEV fica a ≤ 0,01 do melhor k."""
    mx = max(m_k.values())
    for k in sorted(m_k):
        if m_k[k] >= mx - R27_MARGEM_K:
            return int(k)
    return int(max(m_k))


def r27_norm_const(dev_aleat: float, dev_modos: dict):
    A = float(dev_aleat)
    R = float(max(dev_modos.values()))
    return A, R, max(R - A, R27_DEN_MIN)


def r27_norm(r, A, den):
    return (np.asarray(r, dtype=float) - A) / den


# ---------------------------------------------------------------------------
# Hipóteses A, M, G (escore normalizado por semente) + guarda de identidade
# ---------------------------------------------------------------------------
def r27_pool(SN, tarefas, f):
    """Média, por semente, do escore normalizado s_t (SN[t][braço]) nas tarefas dadas; f(t) → nome do braço."""
    return np.mean([np.asarray(SN[t][f(t)]) for t in tarefas], axis=0)


def r27_contrastes(SN, modos, kstar):
    """SN[t] = {'ON','LEVE','OFF','ADAPT','META','POL4','POLK'} (escore normalizado por semente). Devolve (D, n_dif) onde n_dif = nº de
    tarefas em que o braço difere do comparador por CONSTRUÇÃO (0 ⇒ identidade ⇒ nulo por construção)."""
    T = list(R27_TAREFAS)
    H = [t for t in T if R27_FAMILIA[t] == "H"]
    Z = [t for t in T if R27_FAMILIA[t] == "Z"]
    N = list(R27_NOVAS)
    D, nd = {}, {}

    def dif(par, comp):
        return sum(1 for t in par if modos[t] != comp)
    ad = lambda t: "ADAPT"
    D["A1"] = r27_pool(SN, T, ad) - r27_pool(SN, T, lambda t: "ON");   nd["A1"] = dif(T, "ON")
    D["A2"] = r27_pool(SN, T, ad) - r27_pool(SN, T, lambda t: "OFF");  nd["A2"] = dif(T, "OFF")
    D["A3"] = r27_pool(SN, T, ad) - r27_pool(SN, T, lambda t: "LEVE"); nd["A3"] = dif(T, "LEVE")
    D["A4"] = r27_pool(SN, H, ad) - r27_pool(SN, H, lambda t: "ON");   nd["A4"] = dif(H, "ON")
    D["A5"] = r27_pool(SN, Z, ad) - r27_pool(SN, Z, lambda t: "OFF");  nd["A5"] = dif(Z, "OFF")
    D["A6"] = r27_pool(SN, N, ad) - r27_pool(SN, N, lambda t: "ON");   nd["A6"] = dif(N, "ON")
    D["A7"] = r27_pool(SN, N, ad) - r27_pool(SN, N, lambda t: "OFF");  nd["A7"] = dif(N, "OFF")
    me = lambda t: "META"
    D["M1"] = r27_pool(SN, T, me) - r27_pool(SN, T, ad);   nd["M1"] = len(T)
    D["M1_Z"] = r27_pool(SN, Z, me) - r27_pool(SN, Z, ad); nd["M1_Z"] = len(Z)
    D["M1_H"] = r27_pool(SN, H, me) - r27_pool(SN, H, ad); nd["M1_H"] = len(H)
    g = r27_pool(SN, T, lambda t: "POLK") - r27_pool(SN, T, lambda t: "POL4")
    D["G1"] = g
    D["G2"] = g
    nd["G1"] = nd["G2"] = sum(1 for t in T if int(kstar[t]) != R25_K_GATE)
    return D, nd


def r27_status(h, media, p_holm, n_dif):
    if n_dif == 0:
        return "nula por construção"
    if h == "G2":
        return r25_status(media + R27_MARGEM_G2, p_holm)
    return r25_status(media, p_holm)


def r27_regra_filtro(st: dict) -> str:
    A = [st.get(k) for k in ("A1", "A2", "A3")]
    ger = st.get("A6") == "confirmada" and st.get("A7") == "confirmada"
    gtxt = "INTERRUPTOR GENERALIZA a tarefas novas (A6 e A7 confirmadas)" if ger else \
        "generalização a tarefas novas NÃO demonstrada (A6/A7 não ambas confirmadas; travado só nas tarefas já vistas)"
    if "refutada" in A:
        return "FILTRO ADAPTATIVO REBAIXADO: volta a ser modo por tarefa DESCRITIVO (A1–A3 com refutada); " + gtxt
    if all(a == "confirmada" for a in A):
        return "FILTRO ADAPTATIVO CONFIRMADO E MANTIDO NA PILHA PADRÃO (A1, A2 e A3 confirmadas contra sempre-ON, sempre-OFF e sempre-LEVE); " + gtxt
    return "ADAPTATIVO MANTIDO SEM CONFIRMAÇÃO (A1–A3 não todas confirmadas); " + gtxt


def r27_regra_meta(st: dict) -> str:
    v = [st.get(k) for k in ("M1", "M1_Z", "M1_H")]
    if "refutada" in v:
        return f"META NORMALIZADA: SAIR DA PILHA RECOMENDADA (dano) (M1={v[0]}, M1_Z={v[1]}, M1_H={v[2]}); fica só como flag experimental"
    if "confirmada" in v:
        return f"META NORMALIZADA: MANTER OPCIONAL (ajuda em algum recorte, sem dano; M1={v[0]}, M1_Z={v[1]}, M1_H={v[2]}); NÃO compõe a pilha padrão"
    return f"META NORMALIZADA: SAIR DA PILHA RECOMENDADA (nula) (M1={v[0]}, M1_Z={v[1]}, M1_H={v[2]}); fica só como flag experimental"


def r27_regra_gate(st: dict, kstar: dict) -> str:
    kb = float(np.mean([kstar[t] for t in R27_TAREFAS]))
    ks = ", ".join(f"{t}:{kstar[t]}" for t in R27_TAREFAS)
    if all(int(kstar[t]) == R25_K_GATE for t in R27_TAREFAS):
        return f"k=4 FIXO MANTIDO (k* = 4 em todas as tarefas; G1/G2 NULOS POR CONSTRUÇÃO) [k*: {ks}]"
    if st.get("G1") == "confirmada":
        return f"PORTA CALIBRADA POR TAREFA ADOTADA (G1 confirmada; custo médio k̄*={kb:.2f} amostras/geração vs 4; não é custo igual) [k*: {ks}]"
    if st.get("G2") == "confirmada" and kb < R25_K_GATE:
        return f"PORTA CALIBRADA ADOTADA COMO OPÇÃO ECONÔMICA (não-inferior com k̄*={kb:.2f} < 4 amostras/geração) [k*: {ks}]"
    return f"k=4 FIXO MANTIDO (G1 {st.get('G1')}, G2 {st.get('G2')}; k̄*={kb:.2f}) [k*: {ks}]"


# ---------------------------------------------------------------------------
# BitLinear: tabuleiro de xadrez com ruído + MLP genérico
# ---------------------------------------------------------------------------
def r27_xadrez(seed: int, n: int, g: int, sx: float, f: float, teste: bool = False):
    rng = r25_rng(seed, r27_crc("xadrez|" + ("te" if teste else "tr")), 3)
    X = rng.uniform(-1.0, 1.0, size=(int(n), 2))
    y = ((np.floor((X[:, 0] + 1.0) * g / 2.0) + np.floor((X[:, 1] + 1.0) * g / 2.0)) % 2).astype(np.float64)
    Xn = X + rng.normal(0.0, float(sx), size=X.shape)
    if not teste and f > 0:
        fl = rng.random(int(n)) < float(f)
        y = np.where(fl, 1.0 - y, y)
    return Xn, y


def r27_mlp_xadrez(modo: str, seed: int, nivel: dict, rung=None):
    """Mesmo MLP/otimizador da R26 (Adam, BCE, backprop completo; bit: ternário + STE) no tabuleiro de xadrez com ruído."""
    rung = rung or R27_RUNG_X
    Xtr0, ytr = r27_xadrez(seed, nivel["ntr"], nivel["g"], nivel["sx"], nivel["f"], teste=False)
    Xte0, yte = r27_xadrez(seed + 1, 200, nivel["g"], nivel["sx"], nivel["f"], teste=True)
    Xtr = r25_hw_feats(Xtr0, seed, rung["fourier"])
    Xte = r25_hw_feats(Xte0, seed, rung["fourier"])
    d_in = Xtr.shape[1]
    H = int(rung["H"])
    dims = [d_in, H, H, 1]
    rng = r25_rng(seed, r27_crc(f"mlpx|{modo}|{nivel['n']}"), 5)
    W = [rng.normal(0.0, math.sqrt(2.0 / dims[i]), size=(dims[i], dims[i + 1])) for i in range(3)]
    b = [np.zeros(dims[i + 1]) for i in range(3)]
    q = r25_q_dense if modo == "dense_fp" else r25_q_ternario
    mW = [np.zeros_like(w) for w in W]; vW = [np.zeros_like(w) for w in W]
    mb = [np.zeros_like(x) for x in b]; vb = [np.zeros_like(x) for x in b]
    lr, b1, b2, eps = R25_HW_LR, 0.9, 0.999, 1e-8
    n = len(ytr)
    yv = ytr.reshape(-1, 1)
    for t in range(1, int(rung["passos"]) + 1):
        Wq = [q(w) for w in W]
        hs = [Xtr]
        h = Xtr
        for i in range(3):
            z = h @ Wq[i] + b[i]
            h = np.maximum(0.0, z) if i < 2 else 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
            hs.append(h)
        dz = (hs[3] - yv) / n
        gW, gb = [None] * 3, [None] * 3
        for i in (2, 1, 0):
            gW[i] = hs[i].T @ dz
            gb[i] = dz.sum(axis=0)
            if i > 0:
                dh = dz @ Wq[i].T
                dz = dh * (hs[i] > 0)
        for i in range(3):
            mW[i] = b1 * mW[i] + (1 - b1) * gW[i]; vW[i] = b2 * vW[i] + (1 - b2) * gW[i] ** 2
            mb[i] = b1 * mb[i] + (1 - b1) * gb[i]; vb[i] = b2 * vb[i] + (1 - b2) * gb[i] ** 2
            W[i] -= lr * (mW[i] / (1 - b1 ** t)) / (np.sqrt(vW[i] / (1 - b2 ** t)) + eps)
            b[i] -= lr * (mb[i] / (1 - b1 ** t)) / (np.sqrt(vb[i] / (1 - b2 ** t)) + eps)
    Wq = [q(w) for w in W]
    h = Xte
    mul = add = 0
    for i in range(3):
        z = h @ Wq[i] + b[i]
        if modo == "dense_fp":
            mul += h.shape[0] * Wq[i].shape[0] * Wq[i].shape[1]; add += mul
        else:
            nnz = int(np.count_nonzero(np.abs(Wq[i]) > 0))
            add += h.shape[0] * nnz
            mul += h.shape[0] * Wq[i].shape[1]
        h = np.maximum(0.0, z) if i < 2 else 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))
    acc = float(((h.reshape(-1) >= 0.5) == (yte >= 0.5)).mean())
    frac_zero = float(np.mean([np.mean(np.abs(w) < 1e-12) for w in Wq])) if modo == "bit_v2" else 0.0
    return {"acc": acc, "energia": float(1.0 * mul + 0.25 * add), "frac_zero": frac_zero, "modo": modo, "seed": int(seed)}


def r27_job_hw(task):
    """task = ('S', seed) espirais N2 | ('X', nivel, seed) xadrez."""
    if task[0] == "S":
        _, seed = task
        d = r26_mlp_treinar("dense_fp", seed, R27_NIVEL_S, R27_RUNG_S)
        b = r26_mlp_treinar("bit_v2", seed, R27_NIVEL_S, R27_RUNG_S)
        nv = R27_NIVEL_S["n"]
    else:
        _, nivel, seed = task
        d = r27_mlp_xadrez("dense_fp", seed, nivel)
        b = r27_mlp_xadrez("bit_v2", seed, nivel)
        nv = nivel["n"]
    return {"acc_dense": d["acc"], "acc_bit": b["acc"], "en_dense": d["energia"], "en_bit": b["energia"], "frac_zero": b["frac_zero"],
            "seed": int(seed), "nivel": int(nv)}


def r27_escolher_nivel_x(tab: list):
    """tab = [(n, acc_bit, acc_dense), ...] na ordem da escada: o PRIMEIRO com denso em [0,70; 0,93]; senão o mais próximo de 0,85."""
    return r26_escolher_nivel(tab)


def r27_veredito_hw_tarefa(st: dict, med: dict, sfx: str):
    """Devolve (código, texto) pela regra de 5 casos da R26; st tem C1/C2/C3 da tarefa (chaves 'C1','C2','C3')."""
    gap = (med["acc_dense"] - med["acc_bit"]) * 100.0
    teto = med["acc_dense"] > R26_HW_TETO
    t = " [TAREFA NO TETO]" if teto else ""
    if st.get("C1") != "confirmada":
        return "COLAPSA", f"{sfx}: COLAPSA (bit_v2 <0,60 ou não acima do acaso){t}"
    if st.get("C2") != "confirmada":
        return "INVALIDA", f"{sfx}: INVÁLIDA PARA O DENSO (sem veredito){t}"
    if st.get("C3") == "confirmada" and not teto:
        return "NAO-INFERIOR", f"{sfx}: NÃO-INFERIOR (margem −0,05; Δ={-gap:+.1f} p.p.)"
    if st.get("C3") == "refutada":
        return "GAP", f"{sfx}: GAP de {gap:.1f} p.p. abaixo do denso{t}"
    return "INCONCLUSIVO", f"{sfx}: INCONCLUSIVO (não-inferioridade não demonstrada; Δ={-gap:+.1f} p.p.){t}"


def r27_regra_hw_global(cod_s: str, cod_x: str) -> str:
    if cod_s == "NAO-INFERIOR" and cod_x == "NAO-INFERIOR":
        return "BITLINEAR v2 ATIVO (proxy de brinquedo): não-inferior ao denso em 2 tarefas difíceis"
    if "COLAPSA" in (cod_s, cod_x) or "GAP" in (cod_s, cod_x):
        return "BITLINEAR v2 CONGELADO: lacuna/colapso documentado (" + f"espirais {cod_s}, xadrez {cod_x})"
    return ("BITLINEAR v2 CONGELADO por parcimônia: não-inferioridade NÃO demonstrada mesmo com N=80 e uma segunda tarefa " +
            f"(espirais {cod_s}, xadrez {cod_x}); sem mais investimento nesta linha; só o resultado fica")


def r27_hw_ativo(ver_hw: str) -> bool:
    return str(ver_hw).startswith("BITLINEAR v2 ATIVO")


