def registro_hipoteses_r27(ctx: Contexto) -> list:
    r = ctx.res.get("r27")
    if not r:
        return []
    desc = r27_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R27", f"R27-{k}", "CONF", desc[k],
                    f"Δ={m:+.4f} d_z={dz:+.2f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    for k, v in (r.get("expl") or {}).items():
        m, lo, hi, p, dz, dn = v
        out.append(("R27", f"R27-E[{k}]", "DESC", f"EXPLORATÓRIA (fora do Holm) {k}", f"Δ={m:+.4f} Δnorm={dn:+.4f} d_z={dz:+.2f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f}", "descritiva"))
    out.append(("R27", "R27-VF", "DESC", "Veredito do filtro adaptativo (A1–A3; A6/A7 = generalização)", r["ver_filtro"], "descritiva"))
    out.append(("R27", "R27-VM", "DESC", "Decisão da meta normalizada sobre a pilha adaptativa", r["ver_meta"], "descritiva"))
    out.append(("R27", "R27-VG", "DESC", "Veredito da porta k calibrada por tarefa", r["ver_gate"], "descritiva"))
    out.append(("R27", "R27-VB", "DESC", "Veredito BitLinear v2 (regra global de congelamento)", r["ver_hw"], "descritiva"))
    out.append(("R27", "R27-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI", "pulados", "descritiva"))
    return out


