def r27_estado_bloco(args, nome: str) -> str:
    try:
        if r27_dormente_ativo(args, nome):
            return "DORMENTE (R27, congelado sha256)"
    except Exception:  # noqa: BLE001
        pass
    return r26_estado_bloco(args, nome)


def mapa_do_que_vive_linhas_r27(ctx: Contexto) -> list:
    r = ctx.res.get("r27") or {}
    L = []
    L.append("MAPA DO QUE VIVE (27 rodadas) — estado de cada bloco derivado das funções de dormência do próprio código")
    L.append("estados: ATIVO = roda ao vivo | DORMENTE = resultado congelado (sha256), recálculo atrás de --reativar-dormentes | CONGELADO = módulo encerrado | NÚCLEO-MATEMÁTICO = fato verificável, não evidência de cognição")
    L.append(f"{'módulo/bloco':<28}{'rodada':<9}{'estado':<38}tema → evidência")
    for rotulo, nomes, rod, tema, fixo, evid in R27_MAPA:
        if fixo:
            est = fixo
        else:
            ests = sorted(set(r27_estado_bloco(ctx.args, n) for n in nomes)) or ["ATIVO"]
            est = ests[0] if len(ests) == 1 else "MISTO: " + "/".join(e.split(" ")[0] for e in ests)
        L.append(f"{rotulo:<28}{rod:<9}{est:<38}{tema} → {evid}")
    L.append("--- módulos transversais (estado pelo veredito desta execução) ---")
    vf = r.get("ver_filtro", "?")
    vm = r.get("ver_meta", "?")
    vg = r.get("ver_gate", "?")
    cong = bool(r.get("congelado_bitlinear", False))
    meta_sai = (r.get("meta_decisao") == "SAIR") if r else False
    filtro_ok = bool(r.get("filtro_confirmado", False)) if r else False
    trans = [
        ("filtro-primeiro (τ fixo)", "R20", "ATIVO (motor)", "R19 'filtro é toda a história'; R23–R27 replicam; modo por tarefa: filtro adaptativo travado"),
        ("filtro adaptativo (travado)", "R26–R27", ("ATIVO (padrão; confirmado R27)" if filtro_ok else "ATIVO (padrão; sem confirmação R27)") if r else "ATIVO (padrão)", vf[:120]),
        ("RL ordinário", "R19–R27", "ATIVO (pilha padrão TRAVADA)", "R23 S1/S2, R24 H1/H2; R25 A1/Y1; R26 L1"),
        ("RL extraordinário", "R19–R27", "DORMENTE/REFUTADO", "R23 S3, R24 H3 refutadas; R25 A6/Y6"),
        ("porta de geração (k)", "R25–R27", "ATIVO (pilha padrão TRAVADA, k=4)", vg[:120]),
        ("meta-recompensa (bruta/calibrada)", "R24–R27", "OPCIONAL [NOCIVA na R25]", "R25 A3/Y3 (orçamento igual): dano na Z7"),
        ("meta-recompensa NORMALIZADA", "R26–R27", ("FORA DA PILHA RECOMENDADA (flag experimental)" if meta_sai else "OPCIONAL (flag experimental)") if r else "OPCIONAL", vm[:120]),
        ("delírio", "R3–R22", "OPCIONAL (explorador)", "sem ganho além do filtro"),
        ("BitLinear ternário v2 (STE)", "R25–R27", ("CONGELADO (R27)" if cong else "ATIVO (proxy; não é BitNet)") if r else "ATIVO (proxy; não é BitNet)", r.get("ver_hw", "R26: INCONCLUSIVO")[:120]),
        ("BitLinear v1 (R24)", "R24", "CONGELADO", "Acc≈0,50 (acaso); superado pelo v2"),
        ("SNN LIF (R24)", "R24", "CONGELADO", "Acc≈0,50; só sparsity documentada"),
        ("prefill/decode (intensidade)", "R24", "NÚCLEO-MATEMÁTICO", "razão aritmética; não é medição de hardware"),
        ("Mega-Sena", "R18", "DORMENTE (nulo honesto)", "nenhum método bate o acaso após correção"),
    ]
    for n, rod, est, ev in trans:
        L.append(f"{n:<28}{rod:<9}{est:<38}{ev}")
    return L



