R28_CONGELADO_B64 = "".join(R28_CONGELADO_B64_CHUNKS)

_R28_CONG_CACHE = {"v": None}


def r28_congelado():
    if _R28_CONG_CACHE["v"] is not None:
        return _R28_CONG_CACHE["v"]
    if not R28_CONGELADO_B64 or R28_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R28_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R28_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R28_CONG_CACHE["v"] = v
    return v


def r28_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if any(os.environ.get(v) for v in R28_ENV_VIVO):
        return False
    cg = r28_congelado()
    return cg is not None and nome in cg


def _dormente28(nome, vivo):
    def w(ctx):
        rot = R28_DORMENTES[nome]
        est = ctx.res.setdefault("r28_dorm", {})
        if r28_dormente_ativo(ctx.args, nome):
            cg = r28_congelado()[nome]
            ctx.rep.log(
                f"[R28 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R27 inalterado "
                f"(--offline --jobs 8, semente 42; sha256 {R28_CONGELADO_SHA256[:12]}… CONFERE; origem {R28_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r28_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R28 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w


