def r28_desloc() -> int:
    v = os.environ.get("R28_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r28_crc(rot: str) -> int:
    return zlib.crc32(f"R28|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r28_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R28_SEEDS.items()}


# ---------------------------------------------------------------------------
# Tarefas (funções da R27 sem alteração) e jobs
# ---------------------------------------------------------------------------
def r28_tarefa(nome: str):
    if nome in R28_PRM_SYM:
        t = R27Sym(R28_PRM_SYM[nome])
        t.nome = nome
        return t
    p = R28_PRM_HARD[nome]
    return R27Hard(nome, p["V"], p["L"], p["seed_lex"], p["P"])


def r28_job_lr(task):
    _, tn, seed, lr = task
    tz = r28_tarefa(tn)
    tr = r25_treinar(tz, R25_CFG["rl_ord"], seed, lr)
    ev = r25_avaliar(tz, R25_CFG["rl_ord"], tr, seed, f"{tn}|rl_ord")
    return {"tarefa": tn, "seed": int(seed), "lr": float(lr), "r_clean": float(ev["r_clean"])}


def r28_job_pol(task):
    """task = ('D', tarefa, seed, lr): treina Pf e Pr (mesmas cfgs da R27), avalia aninhado até k=8 e o aleat. Serve DEV e TESTE."""
    _, tn, seed, lr = task
    tz = r28_tarefa(tn)
    pf = r25_treinar(tz, r27_cfg_pf(), seed, lr)
    pr = r25_treinar(tz, r27_cfg_pr(), seed, lr)
    ef = r27_avaliar_aninhado(tz, pf["pol"], seed, "Pf", 8)
    er = r27_avaliar_aninhado(tz, pr["pol"], seed, "Pr", 8)
    al = r25_avaliar(tz, R25_CFG["aleat"], {"pol": None}, seed, f"{tn}|aleat")
    return {"tarefa": tn, "seed": int(seed), "Pf": {k: v[0] for k, v in ef.items()}, "Pr": {k: v[0] for k, v in er.items()}, "aleat": float(al["r_clean"])}


# ---------------------------------------------------------------------------
# Regras de modo, normalização, alocação a custo igual
# ---------------------------------------------------------------------------
def r28_valor_modo(ent: dict, modo: str) -> float:
    return r27_modo_r_clean(ent, modo)


def r28_regra_antiga(m: dict) -> str:
    return r26_escolher_modo(m)


def r28_regra_nova(m: dict) -> str:
    """CORREÇÃO ÚNICA pré-registrada: o modo MAIS BARATO (OFF < LEVE < ON) cuja média DEV fica a ≤ 0,01 do melhor."""
    best = max(m[x] for x in R28_MODOS)
    for x in sorted(R28_MODOS, key=lambda z: R28_CUSTO[z]):
        if m[x] >= best - R28_MARGEM - 1e-12:
            return x
    return "ON"


def r28_pol_modo(modo: str) -> str:
    return "Pf" if modo == "ON" else "Pr"


def r28_norm_const(dev_aleat: float, dev_modos: dict):
    A = float(dev_aleat)
    R = float(max(dev_modos[x] for x in R28_MODOS))
    return A, R, max(R - A, R27_DEN_MIN)


def r28_com_sinal(A: float, R: float) -> bool:
    return (R - A) >= R28_SINAL_MIN - 1e-12


def r28_alocar(v: dict, orcamento=None):
    """v = {tarefa: {k: escore DEV normalizado}} (ordem de inserção = ordem das tarefas). Maximiza Σ v[t][k_t] s.t. Σ k_t ≤ orçamento
    (padrão 4·T). Empates (<1e-9): menor Σk; depois lexicográfico crescente. Devolve {tarefa: k}."""
    ts = list(v)
    T = len(ts)
    B = int(orcamento) if orcamento is not None else R25_K_GATE * T
    mk, ms, mc = None, None, None
    for comb in itertools.product(R28_KS, repeat=T):       # ordem lexicográfica crescente
        c = sum(comb)
        if c > B:
            continue
        s = sum(v[t][k] for t, k in zip(ts, comb))
        if mk is None or s > ms + 1e-9 or (abs(s - ms) <= 1e-9 and c < mc):
            mk, ms, mc = comb, s, c
    return dict(zip(ts, mk))


def r28_permutacoes(kalloc: dict):
    """Alocações permutadas ciclicamente (s=1..T−1): a tarefa t usa k_{(t+s) mod T}. Mesmo multiconjunto de k, mesmo custo."""
    ts = list(kalloc)
    T = len(ts)
    return [{ts[i]: kalloc[ts[(i + s) % T]] for i in range(T)} for s in range(1, T)]


def r28_pool(SN, tarefas, f):
    """Média, sobre as tarefas, do escore normalizado por semente. f(t) devolve a chave do braço."""
    return np.mean([np.asarray(SN[t][f(t)]) for t in tarefas], axis=0)


def r28_contrastes(TE, norm, modos_ant, modos_nov, kalloc, eff):
    """TE[t] = lista de jobs (Pf/Pr/aleat) por semente de TESTE; norm[t] = (A, R, den); eff = tarefas com sinal. Devolve (D, n_dif, braços)."""
    SN = {}
    perms = r28_permutacoes({x: kalloc[x] for x in eff}) if len(eff) > 1 else []
    for t in eff:
        A, _R, den = norm[t]
        E = TE[t]
        pol = r28_pol_modo(modos_ant[t])
        SN[t] = {
            "FIX4": r27_norm(np.asarray([e[pol][4] for e in E]), A, den),
            "ALLOC": r27_norm(np.asarray([e[pol][kalloc[t]] for e in E]), A, den),
            "ANT": r27_norm(np.asarray([r28_valor_modo(e, modos_ant[t]) for e in E]), A, den),
            "NOV": r27_norm(np.asarray([r28_valor_modo(e, modos_nov[t]) for e in E]), A, den),
        }
        SN[t]["PERM"] = np.mean([r27_norm(np.asarray([e[pol][pk[t]] for e in E]), A, den) for pk in perms], axis=0) \
            if perms else SN[t]["ALLOC"]
    Z = [t for t in eff if R28_FAMILIA[t] == "Z"]
    H = [t for t in eff if R28_FAMILIA[t] == "H"]
    dif_modo = [t for t in eff if modos_ant[t] != modos_nov[t]]
    D, nd = {}, {}
    D["E1"] = D["E2"] = r28_pool(SN, eff, lambda t: "ALLOC") - r28_pool(SN, eff, lambda t: "FIX4") if eff else np.zeros(1)
    nd["E1"] = nd["E2"] = sum(1 for t in eff if kalloc[t] != R25_K_GATE)
    D["E3"] = r28_pool(SN, eff, lambda t: "ALLOC") - r28_pool(SN, eff, lambda t: "PERM") if eff else np.zeros(1)
    nd["E3"] = 0 if len(set(kalloc[t] for t in eff)) <= 1 else len(eff)
    D["E4"] = (r28_pool(SN, Z, lambda t: "ALLOC") - r28_pool(SN, Z, lambda t: "FIX4")) if Z else np.zeros(len(next(iter(TE.values()))))
    nd["E4"] = sum(1 for t in Z if kalloc[t] != R25_K_GATE)
    D["E5"] = (r28_pool(SN, H, lambda t: "ALLOC") - r28_pool(SN, H, lambda t: "FIX4")) if H else np.zeros(len(next(iter(TE.values()))))
    nd["E5"] = sum(1 for t in H if kalloc[t] != R25_K_GATE)
    D["F1"] = r28_pool(SN, eff, lambda t: "NOV") - r28_pool(SN, eff, lambda t: "ANT") if eff else np.zeros(1)
    nd["F1"] = len(dif_modo)
    D["F2"] = (r28_pool(SN, dif_modo, lambda t: "NOV") - r28_pool(SN, dif_modo, lambda t: "ANT")) if dif_modo else np.zeros(len(next(iter(TE.values()))))
    nd["F2"] = len(dif_modo)
    return D, nd, SN


def r28_status(h, media, p_holm, n_dif):
    if n_dif == 0:
        return "nula por construção"
    if h == "E2":
        return r25_status(media + R28_MARGEM_E2, p_holm)
    return r25_status(media, p_holm)


def r28_regra_porta(st: dict, kalloc: dict) -> str:
    kb = float(np.mean(list(kalloc.values()))) if kalloc else 4.0
    ks = ", ".join(f"{t}:{k}" for t, k in kalloc.items())
    if all(int(k) == R25_K_GATE for k in kalloc.values()):
        return f"k=4 FIXO MANTIDO (a alocação calibrada deu k=4 em todas as tarefas; E1–E5 NULOS POR CONSTRUÇÃO) [k: {ks}]"
    if st.get("E1") == "confirmada":
        extra = "" if st.get("E3") == "confirmada" else "; o ganho NÃO é atribuível à atribuição específica por tarefa (E3 não confirmada)"
        return f"PORTA CALIBRADA A CUSTO IGUAL ADOTADA COMO OPÇÃO (ganho a custo igual: k̄={kb:.2f} ≤ 4, Σk ≤ 4T){extra} [k: {ks}]"
    if st.get("E2") == "confirmada":
        return f"NÃO-INFERIOR A CUSTO IGUAL (sem ganho demonstrado): k=4 FIXO MANTIDO por simplicidade [k: {ks}]"
    if "refutada" in (st.get("E1"), st.get("E2")):
        return f"k=4 FIXO MANTIDO (a alocação calibrada é PIOR a custo igual) [k: {ks}]"
    return f"k=4 FIXO MANTIDO (sem evidência de ganho a custo igual) [k: {ks}]"


def r28_regra_filtro(st: dict, ruidosa: bool) -> str:
    f1 = st.get("F1")
    if f1 == "confirmada":
        return "REGRA NOVA (mais barato dentro da margem) ADOTADA para tarefas NOVAS; os modos travados das tarefas antigas não mudam"
    if f1 == "refutada":
        return "REGRA ANTIGA MANTIDA (a regra nova piora)"
    txt = "REGRA ANTIGA MANTIDA SEM EVIDÊNCIA PARA TROCAR"
    if ruidosa:
        txt += "; REGRA DECLARADA RUIDOSA no eixo LEVE×OFF: tratar LEVE e OFF como intercambiáveis (OFF é mais barato)"
    return txt


def r28_estabilidade(dev_por_modo: dict, regra, B=500, seed=0):
    """dev_por_modo[modo] = lista (16) de r_clean DEV por semente. Fração de reamostragens bootstrap (com reposição) em que a regra escolhe o
    MESMO modo que na amostra completa."""
    n = len(dev_por_modo["ON"])
    full = regra({m: float(np.mean(dev_por_modo[m])) for m in R28_MODOS})
    rng = r25_rng(seed, r28_crc("ruido"), 5)
    arr = {m: np.asarray(dev_por_modo[m], float) for m in R28_MODOS}
    ig = 0
    for _ in range(int(B)):
        ix = rng.integers(0, n, size=n)
        if regra({m: float(arr[m][ix].mean()) for m in R28_MODOS}) == full:
            ig += 1
    return ig / float(B), full


def r28_ep_pareado(a, b) -> float:
    d = np.asarray(a, float) - np.asarray(b, float)
    return float(d.std(ddof=1) / math.sqrt(len(d))) if len(d) > 1 else float("inf")


# ---------------------------------------------------------------------------
# MEGA-SENA: backtest temporal honesto (walk-forward)
# ---------------------------------------------------------------------------
def r28_mega_onehot(draws):
    Y = np.zeros((len(draws), 60))
    for i, nums in enumerate(draws):
        for a in nums:
            Y[i, int(a) - 1] = 1.0
    return Y


def r28_pl_grad(ell, picks):
    """Gradiente de log p_PL(picks | ell) em relação aos logits (Plackett–Luce sem reposição; picks = 6 índices ordenados)."""
    O = np.zeros((len(picks), 60))
    O[np.arange(len(picks)), picks] = 1.0
    usado = np.cumsum(O, axis=0) - O          # já escolhidos antes de j
    z = np.where(usado > 0, -np.inf, ell[None, :])
    z = z - z.max(axis=1, keepdims=True)
    e = np.exp(z)
    P = e / e.sum(axis=1, keepdims=True)
    return (O - P).sum(axis=0)


def _r28_zs(v):
    s = float(v.std())
    return (v - v.mean()) / (s if s > 1e-9 else 1.0)


def r28_mega_stack(Y, seed: int, ini: int, n_teste: int, rotulo="stack", lr=0.3, k=4, jan=100, mudo_futuro=False):
    """Pilha padrão no Mega: política softmax (θ + β_f·zf + β_g·zg), k=4 candidatas Plackett–Luce (Gumbel-top-6), porta = maior Σ zf,
    REINFORCE ordinário sobre as k candidatas após revelar o concurso. Só o passado entra em qualquer decisão. Devolve (hits/6 por concurso
    de teste, apostas de teste)."""
    N = Y.shape[0]
    rng = r25_rng(seed, r28_crc("mega|" + rotulo), 9)
    theta = np.zeros(60)
    beta = np.zeros(2)
    base = 0.0
    last = np.full(60, -1.0)
    hits, apostas = [], []
    t0 = ini
    for t in range(t0, N):
        lo = max(0, t - jan)
        cw = Y[lo:t].sum(axis=0) if t > 0 else np.zeros(60)
        gap = np.where(last >= 0, t - 1 - last, t + 10.0)
        zf = _r28_zs(cw)
        zg = _r28_zs(np.log1p(gap))
        ell = theta + beta[0] * zf + beta[1] * zg
        g = ell[None, :] + rng.gumbel(size=(k, 60))
        picks = np.argsort(-g, axis=1)[:, :6]
        chave = zf[picks].sum(axis=1)
        jogada = int(np.argmax(chave))
        y = Y[t]
        h = y[picks].sum(axis=1)
        if t >= ini + 0 and t >= (N - n_teste):
            hits.append(float(h[jogada]) / 6.0)
            apostas.append(sorted(int(x) + 1 for x in picks[jogada]))
        r = h / 6.0
        adv = r - base
        base = 0.9 * base + 0.1 * float(r.mean())
        gt = np.zeros(60)
        gb = np.zeros(2)
        for c in range(k):
            gr = r28_pl_grad(ell, picks[c])
            gt += adv[c] * gr
            gb += adv[c] * np.array([float(gr @ zf), float(gr @ zg)])
        theta = np.clip(theta + lr * gt / k, -2.0, 2.0)
        beta = np.clip(beta + lr * gb / k, -3.0, 3.0)
        last[y > 0] = t
    return np.asarray(hits), apostas


def r28_mega_random(Y, seed: int, n_teste: int, rotulo="random"):
    N = Y.shape[0]
    rng = r25_rng(seed, r28_crc("mega|" + rotulo), 9)
    out = []
    for t in range(N - n_teste, N):
        pk = np.argsort(rng.random(60))[:6]
        out.append(float(Y[t][pk].sum()) / 6.0)
    return np.asarray(out)


def r28_mega_freq(Y, n_teste: int):
    """Baseline de FREQUÊNCIA: as 6 dezenas mais frequentes do passado acumulado (desempate: menor dezena)."""
    N = Y.shape[0]
    cnt = Y[:N - n_teste].sum(axis=0).copy()
    out = []
    for t in range(N - n_teste, N):
        pk = np.argsort(-cnt, kind="stable")[:6]
        out.append(float(Y[t][pk].sum()) / 6.0)
        cnt += Y[t]
    return np.asarray(out)


def r28_z_dif(d):
    d = np.asarray(d, float)
    n = len(d)
    sd = float(d.std(ddof=1)) if n > 1 else 0.0
    z = float(d.mean()) / (sd / math.sqrt(n)) if sd > 1e-15 else 0.0
    p = math.erfc(abs(z) / math.sqrt(2.0))
    return z, float(p)


def r28_ic_bloco(d, bloco=25, B=2000, seed=0):
    d = np.asarray(d, float)
    n = len(d)
    nb = int(math.ceil(n / float(bloco)))
    rng = r25_rng(seed, r28_crc("icbloco"), 4)
    ms = []
    for _ in range(int(B)):
        ix = rng.integers(0, nb, size=nb)
        seg = np.concatenate([d[i * bloco:(i + 1) * bloco] for i in ix])
        ms.append(float(seg.mean()))
    return float(np.percentile(ms, 2.5)), float(np.percentile(ms, 97.5))


def r28_mega_pack(d, rot):
    d = np.asarray(d, float)
    z, p = r28_z_dif(d)
    lo, hi = r28_ic_bloco(d, seed=r28_crc(rot))
    sd = float(d.std(ddof=1)) if len(d) > 1 else 0.0
    return {"media": float(d.mean()), "lo": lo, "hi": hi, "p": p, "z": z, "mde": float(2.8 * sd / max(len(d) ** 0.5, 1.0)), "dz": r25_dz(d)}


def r28_mega_viesada(seed: int, n: int = 1500):
    """Loteria sintética com viés (dezenas 1–10 com peso 4; demais peso 1; sorteio sem reposição) — controle positivo."""
    rng = r25_rng(seed, r28_crc("mega|viesada"), 2)
    lw = np.log(np.where(np.arange(60) < 10, 4.0, 1.0))
    out = []
    for _ in range(int(n)):
        pk = np.argsort(-(lw + rng.gumbel(size=60)))[:6]
        out.append(sorted(int(x) + 1 for x in pk))
    return out


def r28_mega_job(task):
    """task = ('M', seed_ou_lista...) — um job por semente (stack+random) para paralelismo; a frequência é calculada à parte."""
    _, seed, n_teste, ini, viesada = task
    if viesada:
        Y = r28_mega_onehot(r28_mega_viesada(seed))
    else:
        Y = r28_mega_onehot([d[1] for d in r18_mega_draws()])
    h, ap = r28_mega_stack(Y, seed, ini, n_teste)
    return {"stack": h, "random": r28_mega_random(Y, seed, n_teste), "ap": ap[:20]}


def r28_regra_mega(st: dict, pos_ok: bool) -> str:
    if not pos_ok:
        return "MEGA-SENA: NULO NÃO INFORMATIVO (controle positivo falhou)"
    if st.get("MS1") == "confirmada" or st.get("MS3") == "confirmada":
        return "MEGA-SENA: ALERTA: sinal aparente — NÃO é previsão; requer replicação em dados novos e é provável falso positivo da família"
    if st.get("MS2") == "refutada":
        return "MEGA-SENA: NULO HONESTO (nenhum método bate o acaso; a pilha é PIOR que a frequência; sensibilidade confirmada pelo controle positivo)"
    return "MEGA-SENA: NULO HONESTO (nenhum método bate o acaso; sensibilidade confirmada pelo controle positivo)"


# ---------------------------------------------------------------------------
# VERIFICADOR DE CONSISTÊNCIA (meta-interpretador Prolog) + checador independente + mutação
# ---------------------------------------------------------------------------
class R28Motor(MotorProlog):
    """MotorProlog com índice por (functor, aridade) e dois predicados embutidos: menor_igual/2 e diferente/2."""

    def __init__(self, programa: str = "", prof_max: int = 80):
        self._idx = None
        super().__init__(programa, prof_max)

    def carregar(self, texto: str, dinamica: bool = False):
        self._idx = None
        super().carregar(texto, dinamica)

    def _indice(self):
        if self._idx is None:
            ix = {}
            for cl in self.clausulas:
                cab = cl[0]
                ch = (cab[0], len(cab) - 1) if isinstance(cab, tuple) else (cab, 0)
                ix.setdefault(ch, []).append(cl)
            self._idx = ix
        return self._idx

    def _solve(self, metas, sub, prof):
        if not metas:
            yield sub
            return
        if prof > self.prof_max:
            return
        meta, resto = metas[0], metas[1:]
        meta = _pl_walk(meta, sub)
        if isinstance(meta, tuple) and meta[0] == "\\+":
            ok = next(self._solve([meta[1]], sub, prof + 1), None)
            if ok is None:
                yield from self._solve(resto, sub, prof + 1)
            return
        if isinstance(meta, tuple) and meta[0] in ("menor_igual", "diferente") and len(meta) == 3:
            a, b = _pl_resolve(meta[1], sub), _pl_resolve(meta[2], sub)
            if isinstance(a, (VarP, tuple)) or isinstance(b, (VarP, tuple)):
                return
            ok = (a <= b) if meta[0] == "menor_igual" else (a != b)
            if ok:
                yield from self._solve(resto, sub, prof + 1)
            return
        ch = (meta[0], len(meta) - 1) if isinstance(meta, tuple) else (meta, 0)
        for cab, corpo, _d in list(self._indice().get(ch, [])):
            m: dict = {}
            c2, b2 = self._renomear(cab, m), [self._renomear(x, m) for x in corpo]
            s2 = _pl_unif(meta, c2, sub)
            if s2 is not None:
                yield from self._solve(b2 + list(resto), s2, prof + 1)


R28_REGRAS_TXT = (
    "inconsistente(pilha(X,V)) :- stack(X,V), \\+ permitido(X,V).\n"
    "inconsistente(estado_duplo(M)) :- estado(M,A), estado(M,B), diferente(A,B).\n"
    "inconsistente(ativo_sem_evidencia(M)) :- estado(M,ativo), \\+ evidencia(M).\n"
    "inconsistente(refutado_na_pilha(M)) :- refutado(M), na_pilha(M).\n"
    "inconsistente(extraordinario_na_pilha) :- na_pilha(extraordinario).\n"
    "inconsistente(meta_na_pilha) :- na_pilha(meta_norm).\n"
    "inconsistente(custo_acima(C)) :- custo(alocado,C), custo(fixo,F), \\+ menor_igual(C,F).\n"
    "inconsistente(sem_status(H)) :- hipotese(H), \\+ status(H,S0).\n"
    "inconsistente(mega_previsivel) :- estado(mega,ativo).\n"
    "inconsistente(bitlinear_ativo_sem_veredito) :- estado(bitlinear_v2,ativo).\n"
    "inconsistente(versao(N,V)) :- versao(N,V), \\+ versao_esperada(N,V).\n"
)
R28_PERMITIDO = {"rl": "ordinario", "gate": 4, "filtro": "adaptativo", "meta": "nenhum", "extra": "nao"}


def r28_slug(s: str) -> str:
    import unicodedata
    t = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii").lower()
    t = re.sub(r"[^a-z0-9]+", "_", t).strip("_")
    return t or "x"


def r28_estado_atom(est: str) -> str:
    e = est.upper()
    for pref, atom in (("DORMENTE", "dormente"), ("CONGELADO", "congelado"), ("NÚCLEO", "nucleo"), ("NUCLEO", "nucleo"), ("OPCIONAL", "opcional"),
                       ("FORA", "fora"), ("PROXY", "proxy"), ("BACKLOG", "backlog"), ("MISTO", "ativo"), ("ATIVO", "ativo")):
        if e.startswith(pref):
            return atom
    return "ativo"


R28_ID_CANON = {"filtro adaptativo (travado)": "filtro_adaptativo", "RL ordinário": "rl_ordinario", "RL extraordinário": "extraordinario",
                "porta de geração (k)": "porta_k", "meta-recompensa NORMALIZADA": "meta_norm", "BitLinear ternário v2 (STE)": "bitlinear_v2", "Mega-Sena": "mega"}


def r28_bc_de_mapa(linhas_mapa, st_hip, stack, custo, versao, esperada, refutados):
    """Monta a BC estruturada (dict). linhas_mapa = [(rótulo, estado, evidência)]; st_hip = {hipótese: status}."""
    estado, evid = {}, set()
    for rot, est, ev in linhas_mapa:
        mid = R28_ID_CANON.get(rot) or ("m_" + r28_slug(rot))
        estado.setdefault(mid, [])
        a = r28_estado_atom(est)
        if a not in estado[mid]:
            estado[mid].append(a)
        if ev and str(ev).strip():
            evid.add(mid)
    na = ["rl_ordinario", "porta_k", "filtro_adaptativo"]
    return {"stack": dict(stack), "permitido": dict(R28_PERMITIDO), "na_pilha": list(na), "estado": estado, "evidencia": sorted(evid),
            "refutado": sorted(refutados), "custo": dict(custo), "hipoteses": sorted(r28_slug(h) for h in st_hip),
            "status": {r28_slug(h): r28_slug(s) for h, s in st_hip.items()}, "versao": dict(versao),
            "esperada": dict(esperada), "irrelevante": []}


def r28_bc_texto(bc: dict, rng=None, benigno: bool = False) -> str:
    fatos = []
    for x, v in bc["stack"].items():
        fatos.append(f"stack({x},{v}).")
    for x, v in bc["permitido"].items():
        fatos.append(f"permitido({x},{v}).")
    for m in bc["na_pilha"]:
        fatos.append(f"na_pilha({m}).")
    for m, es in bc["estado"].items():
        for e in es:
            fatos.append(f"estado({m},{e}).")
    for m in bc["evidencia"]:
        fatos.append(f"evidencia({m}).")
    for m in bc["refutado"]:
        fatos.append(f"refutado({m}).")
    for k, v in bc["custo"].items():
        fatos.append(f"custo({k},{v}).")
    for h in bc["hipoteses"]:
        fatos.append(f"hipotese({h}).")
    for h, s in bc["status"].items():
        fatos.append(f"status({h},{s}).")
    for n, v in bc["versao"].items():
        fatos.append(f"versao({n},{v}).")
    for n, v in bc["esperada"].items():
        fatos.append(f"versao_esperada({n},{v}).")
    for i in bc.get("irrelevante", []):
        fatos.append(f"irrelevante({i}).")
    regras = [r for r in R28_REGRAS_TXT.strip().split("\n")]
    if benigno and rng is not None:
        nom = ["Alfa", "Beta", "Gama", "Delta", "Eps"]
        regras = [re.sub(r"\b([A-Z][A-Z0-9]?)\b", lambda m_: nom[(ord(m_.group(1)[0]) + len(regras)) % 5] + m_.group(1) if m_.group(1) not in ("S0",) else m_.group(1), r) for r in regras]
        fatos = fatos + [f for f in fatos if rng.random() < 0.15]
        fatos = fatos + [f"irrelevante(z{int(x)})." for x in rng.integers(0, 999, size=int(rng.integers(1, 6)))]
        rng.shuffle(fatos)
        rng.shuffle(regras)
    return "\n".join(fatos) + "\n" + "\n".join(regras) + "\n"


_R36_PL_CACHE = {}


def r28_checar_prolog(texto: str) -> list:
    """[R36] puro em função do texto: cache por conteúdo (o autoteste repete BCs idênticas)."""
    c_ = _R36_PL_CACHE.get(texto)
    if c_ is None:
        mt = R28Motor(texto)
        sols = mt.consulta("inconsistente(X)", max_sol=64)
        out = set()
        for s in sols:
            v = [x for x in s.values()]
            out.add(r28_termo_txt(v[0]) if v else "?")
        c_ = sorted(out)
        _R36_PL_CACHE[texto] = c_
    return list(c_)


def r28_termo_txt(t) -> str:
    if isinstance(t, tuple):
        return t[0] + "(" + ",".join(r28_termo_txt(x) for x in t[1:]) + ")"
    return str(t)


def r28_checar_py(bc: dict) -> list:
    """Checador INDEPENDENTE (sem o motor Prolog): mesmas violações, mesmo texto."""
    out = set()
    for x, v in bc["stack"].items():
        if bc["permitido"].get(x) != v:
            out.add(f"pilha({x},{v})")
    for m, es in bc["estado"].items():
        if len(set(es)) > 1:
            out.add(f"estado_duplo({m})")
        if "ativo" in es and m not in bc["evidencia"]:
            out.add(f"ativo_sem_evidencia({m})")
        if m == "mega" and "ativo" in es:
            out.add("mega_previsivel")
        if m == "bitlinear_v2" and "ativo" in es:
            out.add("bitlinear_ativo_sem_veredito")
    for m in bc["refutado"]:
        if m in bc["na_pilha"]:
            out.add(f"refutado_na_pilha({m})")
    if "extraordinario" in bc["na_pilha"]:
        out.add("extraordinario_na_pilha")
    if "meta_norm" in bc["na_pilha"]:
        out.add("meta_na_pilha")
    if "alocado" in bc["custo"] and "fixo" in bc["custo"] and not (bc["custo"]["alocado"] <= bc["custo"]["fixo"]):
        out.add(f"custo_acima({bc['custo']['alocado']})")
    for h in bc["hipoteses"]:
        if h not in bc["status"]:
            out.add(f"sem_status({h})")
    for n, v in bc["versao"].items():
        if bc["esperada"].get(n) != v:
            out.add(f"versao({n},{v})")
    return sorted(out)


R28_MUTACOES = ("meta_na_stack", "gate_diferente", "rl_diferente", "estado_duplo", "extraordinario_na_pilha", "ativo_sem_evidencia",
                "hipotese_sem_status", "custo_acima", "mega_ativo", "refutado_na_pilha", "versao_diferente", "bitlinear_ativo")


def r28_mutar(bc: dict, tipo: int, rng):
    b = copy.deepcopy(bc)
    t = R28_MUTACOES[tipo % 12]
    if t == "meta_na_stack":
        b["stack"]["meta"] = ["norm", "bruta", "calibrada"][int(rng.integers(0, 3))]
    elif t == "gate_diferente":
        b["stack"]["gate"] = int([1, 2, 8][int(rng.integers(0, 3))])
    elif t == "rl_diferente":
        b["stack"]["rl"] = ["extraordinario", "grpo", "nenhum"][int(rng.integers(0, 3))]
    elif t == "estado_duplo":
        ms = sorted(m for m, es in b["estado"].items() if len(es) == 1)
        m = ms[int(rng.integers(0, len(ms)))]
        outro = [a for a in ("ativo", "dormente", "congelado", "nucleo") if a not in b["estado"][m]]
        b["estado"][m] = b["estado"][m] + [outro[int(rng.integers(0, len(outro)))]]
    elif t == "extraordinario_na_pilha":
        b["na_pilha"].append("extraordinario")
    elif t == "ativo_sem_evidencia":
        ms = sorted(m for m, es in b["estado"].items() if "ativo" in es and m in b["evidencia"])
        m = ms[int(rng.integers(0, len(ms)))]
        b["evidencia"] = [x for x in b["evidencia"] if x != m]
    elif t == "hipotese_sem_status":
        b["hipoteses"] = sorted(b["hipoteses"] + [f"hx{int(rng.integers(0, 999))}"])
    elif t == "custo_acima":
        b["custo"]["alocado"] = b["custo"]["fixo"] + int(rng.integers(1, 9))
    elif t == "mega_ativo":
        b["estado"]["mega"] = b["estado"].get("mega", []) + ["ativo"]
    elif t == "refutado_na_pilha":
        b["refutado"] = sorted(set(b["refutado"]) | {b["na_pilha"][int(rng.integers(0, len(b["na_pilha"])))]})
    elif t == "versao_diferente":
        b["versao"]["nexus"] = f"v{int(rng.integers(0, 9))}_{int(rng.integers(0, 9))}_{int(rng.integers(0, 9))}"
        if b["versao"]["nexus"] == b["esperada"]["nexus"]:
            b["versao"]["nexus"] = "v0_0_0"
    else:
        b["estado"]["bitlinear_v2"] = b["estado"].get("bitlinear_v2", []) + ["ativo"]
    return b, t


def r28_binom_cauda(k: int, n: int, p0: float, superior: bool = True) -> float:
    """P(X ≥ k) (superior) ou P(X ≤ k) (inferior) para X ~ Binomial(n, p0), exato."""
    from math import comb
    if superior:
        return float(sum(comb(n, i) * p0 ** i * (1 - p0) ** (n - i) for i in range(int(k), n + 1)))
    return float(sum(comb(n, i) * p0 ** i * (1 - p0) ** (n - i) for i in range(0, int(k) + 1)))


def r28_validar_verificador(bc: dict, n_mut: int, n_ctl: int, seeds_mut, seeds_ctl):
    """Mutantes (1 mutação plantada, 12 tipos em rodízio) e controles benignos; devolve contagens + concordância com o checador independente."""
    det, conc, tipos, nao_viol_py = 0, 0, {}, 0
    for i in range(n_mut):
        rng = r25_rng(seeds_mut[i], r28_crc("mut"), i)
        bm, tp = r28_mutar(bc, i, rng)
        vp, vy = r28_checar_prolog(r28_bc_texto(bm)), r28_checar_py(bm)
        det += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
        nao_viol_py += 0 if vy else 1
        tipos.setdefault(tp, [0, 0])
        tipos[tp][0] += 1
        tipos[tp][1] += 1 if vp else 0
    fa = 0
    for i in range(n_ctl):
        rng = r25_rng(seeds_ctl[i], r28_crc("ctl"), i)
        txt = r28_bc_texto(bc, rng, benigno=True)
        vp, vy = r28_checar_prolog(txt), r28_checar_py(bc)
        fa += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
    return {"detectados": det, "n_mut": n_mut, "falsos_alarmes": fa, "n_ctl": n_ctl, "concordancia": conc, "n_total": n_mut + n_ctl,
            "tipos": tipos, "mutante_nao_violacao_py": nao_viol_py}


# ---------------------------------------------------------------------------
# PROXIES (rotulados): MLP numpy mínimo com Adam
# ---------------------------------------------------------------------------
def r28_adam_passo(P, G, M, V, t, lr, b1=0.9, b2=0.999, eps=1e-8):
    for i in range(len(P)):
        M[i] = b1 * M[i] + (1 - b1) * G[i]
        V[i] = b2 * V[i] + (1 - b2) * G[i] ** 2
        P[i] -= lr * (M[i] / (1 - b1 ** t)) / (np.sqrt(V[i] / (1 - b2 ** t)) + eps)


def _r28_rede2(rng, d_in, h, d_out):
    return [rng.normal(0, 1.0 / math.sqrt(d_in), (d_in, h)), np.zeros(h), rng.normal(0, 1.0 / math.sqrt(h), (h, d_out)), np.zeros(d_out)]


def _r28_fw(P, x):
    h = np.tanh(x @ P[0] + P[1])
    return h @ P[2] + P[3], h


def _r28_bw(P, x, h, dout):
    g2 = h.T @ dout
    gb2 = dout.sum(0)
    dh = (dout @ P[2].T) * (1.0 - h * h)
    return [x.T @ dh, dh.sum(0), g2, gb2], dh @ P[0].T


def r28_posto_efetivo(E) -> float:
    Ec = np.asarray(E, float) - np.mean(E, axis=0, keepdims=True)
    s = np.linalg.svd(Ec, compute_uv=False)
    if s.sum() < 1e-12:
        return 1.0
    p = s / s.sum()
    p = p[p > 1e-12]
    return float(np.exp(-(p * np.log(p)).sum()))


def r28_sonda_r2(Etr, Ztr, Ete, Zte, lam=1e-3) -> float:
    mu = Etr.mean(0, keepdims=True)
    A = np.c_[Etr - mu, np.ones(len(Etr))]
    W = np.linalg.solve(A.T @ A + lam * np.eye(A.shape[1]), A.T @ Ztr)
    pred = np.c_[Ete - mu, np.ones(len(Ete))] @ W
    ss_res = float(((Zte - pred) ** 2).sum())
    ss_tot = float(((Zte - Zte.mean(0, keepdims=True)) ** 2).sum())
    return 1.0 - ss_res / max(ss_tot, 1e-12)


def r28_jepa(seed: int, n: int = 512, passos: int = 600):
    rng = r25_rng(seed, r28_crc("jepa"), 1)
    A, B = rng.normal(size=(4, 3)), rng.normal(size=(4, 3))

    def gerar(m):
        z = rng.normal(size=(m, 3))
        x1 = np.c_[z @ A.T + 0.1 * rng.normal(size=(m, 4)), 3.0 * rng.normal(size=(m, 4))]
        x2 = np.c_[z @ B.T + 0.1 * rng.normal(size=(m, 4)), 3.0 * rng.normal(size=(m, 4))]
        return z, x1, x2
    ztr, x1, x2 = gerar(n)
    zte, x1t, _x2t = gerar(n)
    out = {}
    for braco in ("JEPA_EMA", "JEPA_SG0", "RECON"):
        r = r25_rng(seed, r28_crc("jepa|init"), 2)
        f = _r28_rede2(r, 8, 16, 8)
        g = _r28_rede2(r, 8, 16, 8)
        ft = [p.copy() for p in f]
        P = f + g
        M = [np.zeros_like(p) for p in P]
        V = [np.zeros_like(p) for p in P]
        for t in range(1, passos + 1):
            e1, h1 = _r28_fw(f, x1)
            pred, hp = _r28_fw(g, e1)
            if braco == "RECON":
                dpred = 2.0 * (pred - x2) / pred.size
                gg, de = _r28_bw(g, e1, hp, dpred)
                gf, _ = _r28_bw(f, x1, h1, de)
            elif braco == "JEPA_EMA":
                et, _ = _r28_fw(ft, x2)
                dpred = 2.0 * (pred - et) / pred.size
                gg, de = _r28_bw(g, e1, hp, dpred)
                gf, _ = _r28_bw(f, x1, h1, de)
            else:
                e2, h2 = _r28_fw(f, x2)
                dpred = 2.0 * (pred - e2) / pred.size
                gg, de = _r28_bw(g, e1, hp, dpred)
                gf, _ = _r28_bw(f, x1, h1, de)
                gf2, _ = _r28_bw(f, x2, h2, -dpred)
                gf = [a + b for a, b in zip(gf, gf2)]
            r28_adam_passo(P, gf + gg, M, V, t, 0.01)
            if braco == "JEPA_EMA":
                for i in range(4):
                    ft[i] = 0.99 * ft[i] + 0.01 * f[i]
        Etr = _r28_fw(f, x1)[0]
        Ete = _r28_fw(f, x1t)[0]
        out[braco] = {"posto": r28_posto_efetivo(Ete), "std": float(Ete.std(axis=0).mean()), "r2": r28_sonda_r2(Etr, ztr, Ete, zte)}
    return out


def _r28_mlp_bin(rng, d_in, h):
    return [rng.normal(0, math.sqrt(2.0 / d_in), (d_in, h)), np.zeros(h), rng.normal(0, math.sqrt(1.0 / h), (h, 1)), np.zeros(1)]


def _r28_relu_fw(P, x):
    z = x @ P[0] + P[1]
    h = np.maximum(z, 0.0)
    lg = (h @ P[2] + P[3]).reshape(-1)
    return lg, h, z


def _r28_sgd_passo(P, x, y, lr, extra_grad=None):
    lg, h, z = _r28_relu_fw(P, x)
    p = 1.0 / (1.0 + np.exp(-np.clip(lg, -40, 40)))
    dl = ((p - y) / len(y)).reshape(-1, 1)
    g2 = h.T @ dl
    gb2 = dl.sum(0)
    dh = (dl @ P[2].T) * (z > 0)
    g = [x.T @ dh, dh.sum(0), g2, gb2]
    if extra_grad is not None:
        g = [a + b for a, b in zip(g, extra_grad)]
    for i in range(4):
        P[i] -= lr * g[i]
    return h


def r28_cbp(seed: int, T: int = 10, passos: int = 300):
    rng = r25_rng(seed, r28_crc("cbp"), 1)
    tarefas = []
    for _ in range(T):
        Wt, bt, vt = rng.normal(size=(8, 8)), rng.normal(size=8), rng.normal(size=8)
        xtr, xte = rng.normal(size=(256, 8)), rng.normal(size=(256, 8))
        ttr, tte = np.tanh(xtr @ Wt + bt) @ vt, np.tanh(xte @ Wt + bt) @ vt
        med = float(np.median(ttr))
        tarefas.append((xtr, (ttr > med).astype(float), xte, (tte > med).astype(float)))
    sonda = rng.normal(size=(256, 8))
    out = {}
    for braco in ("BP", "SP", "CBP"):
        r = r25_rng(seed, r28_crc("cbp|init"), 2)
        P = _r28_mlp_bin(r, 8, 32)
        rs = r25_rng(seed, r28_crc("cbp|sp"), 3)
        util = np.zeros(32)
        idade = np.zeros(32)
        cont = 0.0
        plast = []
        for k, (xtr, ytr, xte, yte) in enumerate(tarefas):
            if braco == "SP" and k > 0:
                P = [0.8 * p + rs.normal(0, 0.05, p.shape) for p in P]
            rb = r25_rng(seed, r28_crc("cbp|batch"), k)
            for _ in range(passos):
                ix = rb.integers(0, 256, size=32)
                h = _r28_sgd_passo(P, xtr[ix], ytr[ix], 0.1)
                if braco == "CBP":
                    util = 0.99 * util + 0.01 * (np.abs(h).mean(0) * np.abs(P[2]).reshape(-1))
                    idade += 1
                    el = np.where(idade > 100)[0]
                    cont += 0.01 * len(el)
                    if cont >= 1.0 and len(el) > 0:
                        j = int(el[np.argmin(util[el])])
                        P[0][:, j] = rs.normal(0, math.sqrt(2.0 / 8), 8)
                        P[1][j] = 0.0
                        P[2][j, 0] = 0.0
                        util[j] = float(np.median(util))
                        idade[j] = 0
                        cont -= 1.0
            lg, _, _ = _r28_relu_fw(P, xte)
            if k >= T - 3:
                plast.append(float(((lg > 0) == (yte > 0.5)).mean()))
        _lg, hh, _z = _r28_relu_fw(P, sonda)
        out[braco] = {"plast": float(np.mean(plast)), "mortas": float(np.mean((hh > 0).sum(axis=0) == 0)), "posto": r28_posto_efetivo(hh) if hh.std() > 0 else 1.0,
                      "norma": float(np.sqrt(sum(float((p ** 2).sum()) for p in P)))}
    return out


def r28_esquecimento(seed: int, lam: float = 100.0, n_tar: int = 5, passos: int = 200):
    rng = r25_rng(seed, r28_crc("esq"), 1)
    D = []
    for _ in range(n_tar):
        d = rng.normal(size=10)
        d /= np.linalg.norm(d)

        def amostra(m, d=d):
            y = (rng.random(m) < 0.5).astype(float)
            x = rng.normal(size=(m, 10)) + (2.0 * y - 1.0)[:, None] * 0.75 * d[None, :]
            return x, y
        D.append((amostra(200), amostra(400)))
    out = {}
    for braco in ("NADA", "REPLAY", "EWC"):
        r = r25_rng(seed, r28_crc("esq|init"), 2)
        P = _r28_mlp_bin(r, 10, 32)
        buf_x, buf_y = [], []
        ancoras, fishers = [], []
        apos = []
        rb = r25_rng(seed, r28_crc("esq|batch"), 3)
        for k, ((xtr, ytr), _te) in enumerate(D):
            for _ in range(passos):
                ix = rb.integers(0, len(ytr), size=32 if braco != "REPLAY" or not buf_x else 16)
                x, y = xtr[ix], ytr[ix]
                if braco == "REPLAY" and buf_x:
                    bx, by = np.concatenate(buf_x), np.concatenate(buf_y)
                    jx = rb.integers(0, len(by), size=16)
                    x, y = np.concatenate([x, bx[jx]]), np.concatenate([y, by[jx]])
                eg = None
                if braco == "EWC" and ancoras:
                    eg = [sum(lam * F[i] * (P[i] - A[i]) for A, F in zip(ancoras, fishers)) for i in range(4)]
                _r28_sgd_passo(P, x, y, 0.05, eg)
            if braco == "REPLAY":
                ji = rb.integers(0, len(ytr), size=20)
                buf_x.append(xtr[ji]); buf_y.append(ytr[ji])
            if braco == "EWC":
                F = [np.zeros_like(p) for p in P]
                ji = rb.integers(0, len(ytr), size=200)
                for i1 in ji:
                    xs = xtr[i1:i1 + 1]
                    lg, h, z = _r28_relu_fw(P, xs)
                    p1 = 1.0 / (1.0 + math.exp(-float(np.clip(lg[0], -40, 40))))
                    yy = float(ytr[i1])                          # Fisher EMPÍRICA (rótulo verdadeiro)
                    dl = np.array([[p1 - yy]])
                    dh = (dl @ P[2].T) * (z > 0)
                    gs = [xs.T @ dh, dh.sum(0), h.T @ dl, dl.sum(0)]
                    for i in range(4):
                        F[i] += gs[i] ** 2 / 200.0
                fishers.append(F)
                ancoras.append([p.copy() for p in P])
            apos.append(float(((_r28_relu_fw(P, D[k][1][0])[0] > 0) == (D[k][1][1] > 0.5)).mean()))
        fim = [float(((_r28_relu_fw(P, te[0])[0] > 0) == (te[1] > 0.5)).mean()) for _tr, te in D]
        out[braco] = {"acc": float(np.mean(fim)), "esq": float(np.mean([apos[k] - fim[k] for k in range(n_tar - 1)]))}
    return out


def r28_ent_norm(tarefa, pol, seed: int, rot: str, n: int = 24) -> float:
    """Entropia média por token (nats) da política nos estados visitados por n sequências amostradas, dividida por log V."""
    rng = r25_rng(seed, r28_crc("ent|" + rot), 6)
    h = []
    for _ in range(n):
        ids, tr = tarefa.sample(pol, rng)
        for (_s, _x, p) in tr:
            h.append(float(-(p * np.log(p + 1e-12)).sum()))
    return float(np.mean(h)) / math.log(tarefa.V)


def r28_treinar_grpo(tarefa, seed: int, lr: float, eps=0.2, beta=0.02, epocas=2):
    """GRPO sem crítico na tarefa simbólica (política tabular): grupo = lote de B sequências; vantagem normalizada pelo grupo; razão de
    importância por token com recorte; KL(π‖π_ref uniforme) com gradiente exato; mesmas amostras/rodadas que o ordinário."""
    P = tarefa.P
    rng = r25_rng(seed, r25_crc(f"train|{tarefa.nome}"), 5)
    pol = tarefa.init_pol(rng)
    for t in range(P):
        seqs, rs = [], []
        for b in range(tarefa.batch):
            ids, tr = tarefa.sample(pol, rng)
            lau = tarefa.laudo(ids, seed, t * tarefa.batch + b)
            rs.append(float(lau["score_laudo"]) + tarefa.ruido(ids, seed, t * tarefa.batch + b))
            seqs.append((ids, tr))
        rs = np.asarray(rs)
        sd = float(rs.std())
        adv = (rs - rs.mean()) / (sd + 1e-6) if sd > 1e-8 else np.zeros_like(rs)
        B = max(len(seqs), 1)
        S = np.asarray([s for (_ids, tr) in seqs for (s, _x, _p) in tr], dtype=int)
        X = np.asarray([x for (_ids, tr) in seqs for (_s, x, _p) in tr], dtype=int)
        Pox = np.asarray([float(p_old[x]) for (_ids, tr) in seqs for (_s, x, p_old) in tr])
        Ad = np.asarray([a for (_ids, tr), a in zip(seqs, adv) for _tok in tr], dtype=float)
        ar = np.arange(len(S))
        for ep in range(int(epocas)):               # gradientes do SNAPSHOT (vetorizado; razão = 1 na época 1)
            z = pol["W"][S]
            p = np.exp(z - z.max(axis=1, keepdims=True))
            p = p / p.sum(axis=1, keepdims=True)
            ratio = p[ar, X] / np.maximum(Pox, 1e-12)
            oh = -p
            oh[ar, X] += 1.0
            corte = ((Ad > 0) & (ratio > 1.0 + eps)) | ((Ad < 0) & (ratio < 1.0 - eps))
            g = np.where(corte, 0.0, Ad * ratio)[:, None] * oh
            lq = np.log(p + 1e-12) + math.log(p.shape[1])      # log(p/q), q uniforme
            kl = (p * lq).sum(axis=1, keepdims=True)
            G = np.zeros_like(pol["W"])
            np.add.at(G, S, g - beta * p * (lq - kl))
            pol["W"] += lr * G / B
    return {"pol": pol}


def r28_job_grpo(task):
    """task = ('W'|'WD', tarefa, seed, lr_grpo): ORD (r25_treinar Pf, lr travado) e GRPO na mesma tarefa; r_clean k=1, k=4 e entropia."""
    k_, tn, seed, lr_g = task
    tz = r28_tarefa(tn)
    gr = r28_treinar_grpo(tz, seed, lr_g)
    if k_ == "WD":                      # DEV do lr do GRPO: só o braço GRPO (o ordinário não depende deste lr)
        return {"GRPO": {"k1": r27_avaliar_aninhado(tz, gr["pol"], seed, "GRPO", 1)[1][0]}}
    ord_ = r25_treinar(tz, r27_cfg_pf(), seed, R28_LR_TRAVADO[tn])
    out = {"tarefa": tn, "seed": int(seed)}
    for rot, tr in (("ORD", ord_), ("GRPO", gr)):
        e = r27_avaliar_aninhado(tz, tr["pol"], seed, rot, 4)
        out[rot] = {"k1": e[1][0], "k4": e[4][0], "ent": r28_ent_norm(tz, tr["pol"], seed, rot)}
    return out


def r28_job_px(task):
    k = task[0]
    if k == "PJ":
        return r28_jepa(task[1])
    if k == "PK":
        return r28_cbp(task[1])
    if k == "PQ":
        return r28_esquecimento(task[1], task[2])
    return r28_job_grpo(task)


