def r28_wilson(k, n, z=1.96):
    if n == 0:
        return 0.0, 1.0
    p = k / float(n)
    d = 1 + z * z / n
    c = (p + z * z / (2 * n)) / d
    h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return float(c - h), float(c + h)


def r28_pack_fracao(k, n, p0, superior, rot):
    p = r28_binom_cauda(k, n, p0, superior=superior)
    lo, hi = r28_wilson(k, n)
    return {"media": k / float(n), "lo": lo, "hi": hi, "p": float(p), "mde": 0.0, "dz": 0.0}


