        ("RL extraordinário", "DORMENTE/REFUTADO", "R23 S3, R24 H3 refutadas; R25 A6/Y6"),
        ("porta de geração (k)", "ATIVO (pilha padrão TRAVADA, k=4 fixo)", "R28 E1–E5 (custo igual): " + g("ver_porta28")[:130]),
        ("meta-recompensa (bruta/calibrada)", "OPCIONAL [NOCIVA na R25]", "R25 A3/Y3 (orçamento igual): dano na Z7"),
        ("meta-recompensa NORMALIZADA", "FORA DA PILHA RECOMENDADA (flag experimental)" if meta_sai else "OPCIONAL (flag experimental)", vm[:120]),
        ("delírio", "OPCIONAL (explorador)", "sem ganho além do filtro"),
        ("BitLinear ternário v2 (STE)", "CONGELADO (R27)" if cong else "ATIVO (proxy; não é BitNet)", (r27 or {}).get("ver_hw", "R27: congelado por parcimônia")[:120]),
        ("BitLinear v1 (R24)", "CONGELADO", "Acc≈0,50 (acaso); superado pelo v2"),
        ("SNN LIF (R24)", "CONGELADO", "Acc≈0,50; só sparsity documentada"),
        ("prefill/decode (intensidade)", "NÚCLEO-MATEMÁTICO", "razão aritmética; não é medição de hardware"),
        ("Mega-Sena", "DORMENTE (nulo honesto; reavaliado ao vivo na R28)", g("ver_mega")[:140]),
        ("mini-JEPA (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_jepa")[:130]),
        ("CBP / shrink-and-perturb (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_cbp")[:130]),
        ("esquecimento: replay × EWC (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_esq")[:130]),
        ("GRPO sem crítico (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_grpo")[:130]),
        ("memória em tokens core/recall/archival", "BACKLOG (R29)", "declarada no pré-registro R28; não implementada"),
        ("verificador de consistência (Prolog)", "ATIVO (núcleo lógico; não é evidência de cognição)", g("ver_verif")[:140]),
