def registro_r28(ctx: Contexto) -> list:
    r = ctx.res.get("r28")
    if not r or "P" not in r:
        return []
    L = [f"REGISTRO R28 (BLOCO 36) — NÚCLEO {r['n_conf']} conf / {r['n_ref']} ref / {r['n_nula']} nulas de 13 (Holm) | PROXIES {r['p_conf']} / {r['p_ref']} / {r['p_nula']} de 10 (Holm próprio)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} d_z={p[6]:+.2f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    L.append("  k (custo igual): " + ", ".join(f"{t}:{r['kalloc'][t]}" for t in r["eff"]) + f" | modos antigo/novo: " + ", ".join(f"{t}:{r['modos_ant'][t]}/{r['modos_nov'][t]}" for t in R28_TAREFAS))
    for k in ("ver_porta28", "ver_filtro28", "ver_mega", "ver_verif", "ver_jepa", "ver_cbp", "ver_esq", "ver_grpo"):
        L.append(f"  {r[k]}")
    return L


