    out.append(("R28", "R28-VP", "DESC", "Veredito da porta k a custo igual", r["ver_porta28"], "descritiva"))
    out.append(("R28", "R28-VF", "DESC", "Veredito da regra do filtro adaptativo (reexame)", r["ver_filtro28"], "descritiva"))
    out.append(("R28", "R28-VM", "DESC", "Veredito do Mega-Sena (backtest temporal)", r["ver_mega"], "descritiva"))
    out.append(("R28", "R28-VV", "DESC", "Veredito do verificador de consistência (Prolog)", r["ver_verif"], "descritiva"))
    out.append(("R28", "R28-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


