R29_CONGELADO_B64 = "".join(R29_CONGELADO_B64_CHUNKS)

_R29_CONG_CACHE = {"v": None}


def r29_congelado():
    if _R29_CONG_CACHE["v"] is not None:
        return _R29_CONG_CACHE["v"]
    if not R29_CONGELADO_B64 or R29_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R29_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R29_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R29_CONG_CACHE["v"] = v
    return v


def r29_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if any(os.environ.get(v) for v in R29_ENV_VIVO):
        return False
    cg = r29_congelado()
    return cg is not None and nome in cg


def _dormente29(nome, vivo):
    def w(ctx):
        rot = R29_DORMENTES[nome]
        est = ctx.res.setdefault("r29_dorm", {})
        if r29_dormente_ativo(ctx.args, nome):
            cg = r29_congelado()[nome]
            ctx.rep.log(
                f"[R29 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R28 inalterado "
                f"(--offline --jobs 8, semente 42; sha256 {R29_CONGELADO_SHA256[:12]}… CONFERE; origem {R29_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r29_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R29 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w


