def r29_desloc() -> int:
    v = os.environ.get("R29_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r29_crc(rot: str) -> int:
    return zlib.crc32(f"R29|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r29_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R29_SEEDS.items()}


# ---------------------------------------------------------------------------
# PARTE A — MEMÓRIA EM TOKENS
# ---------------------------------------------------------------------------
def r29_mem_payload(lake):
    """Palavras da ponte do dicionário: 6 pares-atributo (as 6 primeiras de PARES_PONTE com as duas palavras no vocabulário) + irrelevantes; vetores do lake."""
    ok = [(p, e) for p, e in PARES_PONTE if p in lake.emb.idx and e in lake.emb.idx]
    attrs = ok[:6]
    usados = set(w for par in attrs for w in par)
    irr = [w for par in ok[6:] for w in par if w not in usados][:60]
    vec = {w: np.asarray(lake.vetor(w), float) for w in list(usados) + irr}
    return {"attrs": [list(a) for a in attrs], "irr": irr, "vec": vec}


def _r29_cos(a, b):
    na, nb = float(np.linalg.norm(a)), float(np.linalg.norm(b))
    return float(a @ b) / (na * nb) if na > 1e-12 and nb > 1e-12 else 0.0


def r29_mem_mundo(seed: int, payload: dict):
    rng = r25_rng(seed, r29_crc("mem"), 1)
    attrs, irr = payload["attrs"], payload["irr"]
    perfil = [(0, 0), (0, 1)]
    quentes = [(1, 2), (1, 3), (1, 4), (1, 5)]
    hot = perfil + quentes
    resto = [(e, a) for e in range(24) for a in range(6) if (e, a) not in hot]
    outros = [resto[int(i)] for i in rng.choice(len(resto), 42, replace=False)]
    slots = hot + outros
    seq = list(slots)
    for _ in range(142):
        if rng.random() < 0.5:
            seq.append(hot[int(rng.integers(0, 6))])
        else:
            seq.append(outros[int(rng.integers(0, 42))])
    seq = [seq[int(i)] for i in rng.permutation(len(seq))]
    n_ev = 280
    pos_conv = set(int(i) for i in rng.choice(n_ev, 90, replace=False))
    eventos, atual, hist = [], {}, {s: [] for s in slots}
    iu = 0
    for t in range(n_ev):
        if t in pos_conv:
            eventos.append({"t": t, "ent": int(rng.integers(0, 24)), "canon": -1, "w": irr[int(rng.integers(0, len(irr)))], "val": int(rng.integers(0, 20)), "perfil": False, "slot": None})
        else:
            s = seq[iu]
            iu += 1
            v = int(rng.integers(0, 20))
            while s in atual and v == atual[s]:
                v = int(rng.integers(0, 20))
            atual[s] = v
            hist[s].append((t, v))
            lang = int(rng.integers(0, 2))
            eventos.append({"t": t, "ent": s[0], "canon": s[1], "w": attrs[s[1]][lang], "val": v, "perfil": s in perfil, "slot": s})
    uso = []
    for _ in range(40):
        t = int(rng.integers(100, n_ev))
        uso.append((t, hot[int(rng.integers(0, 6))] if rng.random() < 0.6 else outros[int(rng.integers(0, 42))]))
    cand_h = [s for s in hot if len(hist[s]) >= 2]
    cand_c = [s for s in outros if len(hist[s]) >= 2] or cand_h
    cons = []
    for _ in range(24):
        cons.append((hot[int(rng.integers(0, 6))], "vig"))
    for _ in range(24):
        cons.append((outros[int(rng.integers(0, 42))], "vig"))
    for _ in range(6):
        cons.append((cand_h[int(rng.integers(0, len(cand_h)))], "hist"))
    for _ in range(6):
        cons.append((cand_c[int(rng.integers(0, len(cand_c)))], "hist"))
    langs = [int(rng.integers(0, 2)) for _ in cons]
    return {"eventos": eventos, "atual": atual, "hist": hist, "uso": uso, "cons": cons, "langs": langs, "hot": hot, "perfil": perfil, "slots": slots}


def r29_mem_consolidar(eventos, ate: int):
    """CONSOLIDAÇÃO (sono): por slot (forma canônica), mantém VIGENTE e ANTERIOR com seus tempos; descarta conversas. Devolve (entradas, nº de operações)."""
    por = {}
    ops = 0
    for e in eventos:
        if e["t"] >= ate:
            break
        ops += 1
        if e["slot"] is None:
            continue
        por.setdefault(e["slot"], []).append(e)
    arq = []
    for s, lst in por.items():
        lst = sorted(lst, key=lambda x: x["t"])
        ops += 1
        arq.append(dict(lst[-1], status="vigente"))
        if len(lst) >= 2:
            arq.append(dict(lst[-2], status="anterior"))
    return arq, ops


def r29_mem_ler(entradas, ent_q, w_q, canon_q, tipo, canonico, vec, rng):
    """Leitor determinístico (igual em todos os braços). Devolve valor (ou aleatório se o contexto não tem a informação)."""
    cand = [e for e in entradas if e["ent"] == ent_q]
    if canonico:
        grp = [e for e in cand if e["canon"] == canon_q and e["canon"] >= 0]
        if not grp:
            return int(rng.integers(0, 20))
    else:
        if not cand:
            return int(rng.integers(0, 20))
        sc = [1.0 + _r29_cos(vec[e["w"]], vec[w_q]) for e in cand]
        best = max(sc)
        grp = [e for e, s in zip(cand, sc) if s >= best - 1e-9]
    grp = sorted(grp, key=lambda x: -x["t"])
    if tipo == "vig":
        return int(grp[0]["val"])
    if len(grp) >= 2:
        return int(grp[1]["val"])
    return int(rng.integers(0, 20))


def _r29_topk(pool, ent_q, w_q, canon_q, canonico, vec, k, rng, hist=False):
    sc = []
    for e in pool:
        if canonico:
            s = (1.0 if e["ent"] == ent_q else 0.0) + (1.0 if (e["canon"] == canon_q and e["canon"] >= 0) else 0.0)
            if hist and e.get("status") == "anterior":
                s += 0.5
        else:
            s = (1.0 if e["ent"] == ent_q else 0.0) + _r29_cos(vec[e["w"]], vec[w_q])
        sc.append(s)
    jit = rng.random(len(pool)) * 1e-6
    ordem = np.argsort(-(np.asarray(sc) + jit))
    return [pool[int(i)] for i in ordem[:k]], len(pool)


def r29_mem_run(seed: int, payload: dict):
    W = r29_mem_mundo(seed, payload)
    ev = W["eventos"]
    vec = payload["vec"]
    attrs = payload["attrs"]
    rng = r25_rng(seed, r29_crc("mem|leitor"), 2)
    # estado do sono (sonos em 50,100,...,250; últimos 30 eventos não consolidados)
    t_sono = 250
    arq, ops = r29_mem_consolidar(ev, t_sono)
    n_ops = ops
    cont = {}
    for (t, s) in W["uso"]:
        if t < t_sono:
            cont[s] = cont.get(s, 0) + 1
    perfil = W["perfil"]
    ordem = sorted([s for s in W["slots"] if s not in perfil], key=lambda s: (-cont.get(s, 0), W["slots"].index(s)))
    nucleo4 = list(perfil) + ordem[:2]
    # núcleo A4: valores vigentes no instante do último sono (slots sinalizados: sempre frescos; promovidos: velhos até 30 eventos)
    def vig_ate(s, ate):
        h = [x for x in W["hist"][s] if x[0] < ate]
        return h[-1] if h else None
    def mk_core(slots_core, fresco):
        out = []
        for s in slots_core:
            ate = 10 ** 9 if (s in perfil or fresco) else t_sono
            h = vig_ate(s, ate)
            if h is not None:
                out.append({"t": h[0], "ent": s[0], "canon": s[1], "w": attrs[s[1]][0], "val": h[1], "slot": s, "status": "vigente"})
        return out
    core_a3 = mk_core(list(perfil), True)
    core_a4 = mk_core(nucleo4, False)
    raw_pos = [e for e in ev if e["t"] >= t_sono]
    pool_a4 = arq + [dict(e, status="vigente") for e in raw_pos]
    BRACOS = ("A0", "A1", "A2", "A3", "A4", "ORACULO", "ALEAT")
    ac = {b: {"vig_q": [], "vig_f": [], "hist": []} for b in BRACOS}
    incons = {b: [] for b in ("A0", "A1", "A2", "A3", "A4")}
    vaz = {"A3": [], "A4": []}
    nsim = {b: 0 for b in ("A0", "A1", "A2", "A3", "A4")}
    toks_max = 0
    hot = set(W["hot"])
    for qi, ((s, tipo), lang) in enumerate(zip(W["cons"], W["langs"])):
        w_q = attrs[s[1]][lang]
        verd = W["atual"][s] if tipo == "vig" else W["hist"][s][-2][1]
        cat = "hist" if tipo == "hist" else ("vig_q" if s in hot else "vig_f")
        r_q = r25_rng(seed, r29_crc("mem|q"), 100 + qi)
        ctxs = {}
        ctxs["A0"] = ev[-6:]
        c1, n1 = _r29_topk(ev, s[0], w_q, s[1], False, vec, 6, r_q); ctxs["A1"] = c1; nsim["A1"] += n1
        c2, n2 = _r29_topk(ev, s[0], w_q, s[1], True, vec, 6, r_q); ctxs["A2"] = c2; nsim["A2"] += n2
        c3, n3 = _r29_topk(ev, s[0], w_q, s[1], False, vec, 2, r_q); ctxs["A3"] = core_a3 + c3; nsim["A3"] += n3
        c4, n4 = _r29_topk(pool_a4, s[0], w_q, s[1], True, vec, 2, r_q, hist=(tipo == "hist")); ctxs["A4"] = core_a4 + c4; nsim["A4"] += n4
        nsim["A0"] += 0
        reserva = {"A0": 6, "A1": 6, "A2": 6, "A3": 4 + 2, "A4": 4 + 2}
        for b in ("A0", "A1", "A2", "A3", "A4"):
            assert len(ctxs[b]) <= reserva[b] and reserva[b] * R29_ITEM_TOK <= R29_B_TOK
            toks_max = max(toks_max, reserva[b] * R29_ITEM_TOK)
            canon_b = b in ("A2", "A4")
            r_l = r25_rng(seed, r29_crc("mem|l" + b), 200 + qi)
            resp = r29_mem_ler(ctxs[b], s[0], w_q, s[1], tipo, canon_b, vec, r_l)
            ac[b][cat].append(1.0 if resp == verd else 0.0)
            if tipo == "vig":
                vs = set(e["val"] for e in ctxs[b] if e["ent"] == s[0] and e["canon"] == s[1] and e.get("status") != "anterior")
                incons[b].append(1.0 if len(vs) >= 2 else 0.0)
        if tipo == "vig":
            for b, core in (("A3", core_a3), ("A4", core_a4)):
                it = [e for e in core if e["slot"] == s]
                if it:
                    vaz[b].append(1.0 if it[0]["val"] != W["atual"][s] else 0.0)
                else:
                    vaz[b].append(0.0)
        ac["ORACULO"][cat].append(1.0)
        ac["ALEAT"][cat].append(1.0 if int(r_q.integers(0, 20)) == verd else 0.0)
    out = {}
    for b in BRACOS:
        allq = ac[b]["vig_q"] + ac[b]["vig_f"] + ac[b]["hist"]
        out[b] = {"all": float(np.mean(allq)), "vig_q": float(np.mean(ac[b]["vig_q"])), "vig_f": float(np.mean(ac[b]["vig_f"])), "hist": float(np.mean(ac[b]["hist"]))}
    for b in incons:
        out[b]["incons"] = float(np.mean(incons[b]))
    for b in vaz:
        out[b]["vaz"] = float(np.mean(vaz[b])) if vaz[b] else 0.0
    out["custo"] = {"tokens_max": int(toks_max), "sim": {b: int(v) for b, v in nsim.items()}, "ops_sono": int(n_ops)}
    return out


# ---------------------------------------------------------------------------
# SÍNTESE DIALÉTICA DE GRADIENTES (genérica) + RL tabular (GRPO/ORD/mitigações)
# ---------------------------------------------------------------------------
def r29_confianca(G, gbar):
    n = len(G)
    g2 = float(gbar @ gbar)
    var = float(np.var(G, axis=0, ddof=1).sum()) if n > 1 else 0.0
    return g2 / (g2 + var / max(n, 1) + 1e-30) if g2 > 0 else 0.0


def r29_sintese(Gt, Ga, modo: str, beta: float = 1.0):
    """Combina tese (Gt: n×D por amostra) e antítese (Ga) em um gradiente. Devolve (g, info)."""
    gt, ga = Gt.mean(axis=0), Ga.mean(axis=0)
    nt, na = float(np.linalg.norm(gt)), float(np.linalg.norm(ga))
    cosv = float(gt @ ga) / (nt * na) if nt > 1e-15 and na > 1e-15 else 0.0
    info = {"cos": cosv, "wa": 0.0}
    if modo == "TESE":
        return gt, info
    if modo == "SOMA":
        info["wa"] = 1.0
        return gt + ga, info
    if modo == "FIXA":
        info["wa"] = float(beta)
        return gt + float(beta) * ga, info
    if modo == "PCG":
        if gt @ ga < 0 and nt > 1e-15 and na > 1e-15:
            gt2 = gt - (gt @ ga) / (na * na) * ga
            ga2 = ga - (ga @ gt) / (nt * nt) * gt
            info["wa"] = 1.0
            return gt2 + ga2, info
        info["wa"] = 1.0
        return gt + ga, info
    ga_p = ga
    if modo != "DIAL_SEMPROJ" and cosv < 0 and nt > 1e-15:
        ga_p = ga - (ga @ gt) / (nt * nt) * gt
    if modo == "DIAL_ANG":
        wa = (1.0 + cosv) / 2.0
        info["wa"] = wa
        return gt + wa * ga_p, info
    ct, ca = r29_confianca(Gt, gt), r29_confianca(Ga, ga)
    s = ct + ca
    wt, wa = (ct / s, ca / s) if s > 1e-12 else (0.5, 0.5)
    info["wa"] = 2.0 * wa
    return 2.0 * (wt * gt + wa * ga_p), info


def r29_dH(p):
    """Gradiente da entropia em relação aos logits, por linha: −p⊙(log p + H)."""
    lp = np.log(p + 1e-12)
    H = -(p * lp).sum(axis=-1, keepdims=True)
    return -p * (lp + H)


def r29_rl_treinar(tarefa, seed: int, lr: float, modo: str, hp=None):
    """Treinadores tabulares do BLOCO 37 (mesmas amostras e rodadas P×B que o ordinário/GRPO da R28; GRPO e braços com antítese fazem 2 gradientes por rodada).
    modo ∈ ORD, GRPO, ENT (hp=c), CH (hp=e), SOMA/PCG/DIAL (RL com antítese = ascensão de entropia, reescalada à norma da tese; hp=β para SOMA)."""
    hp = hp if hp is not None else 0.0
    P = tarefa.P
    V = tarefa.V
    rng = r25_rng(seed, r25_crc(f"train|{tarefa.nome}"), 5)
    pol = tarefa.init_pol(rng)
    baseline = 0.0
    wa_list, cos_list = [], []
    for t in range(P):
        seqs, rs = [], []
        for b in range(tarefa.batch):
            ids, tr = tarefa.sample(pol, rng)
            lau = tarefa.laudo(ids, seed, t * tarefa.batch + b)
            rs.append(float(lau["score_laudo"]) + tarefa.ruido(ids, seed, t * tarefa.batch + b))
            seqs.append((ids, tr))
        rs = np.asarray(rs)
        B = max(len(seqs), 1)
        if modo in ("GRPO", "ENT", "CH"):
            eps_hi = float(hp) if modo == "CH" else 0.2
            c_ent = float(hp) if modo == "ENT" else 0.0
            eps, beta, epocas = 0.2, 0.02, 2
            sd = float(rs.std())
            adv = (rs - rs.mean()) / (sd + 1e-6) if sd > 1e-8 else np.zeros_like(rs)
            S = np.asarray([s for (_ids, tr) in seqs for (s, _x, _p) in tr], dtype=int)
            X = np.asarray([x for (_ids, tr) in seqs for (_s, x, _p) in tr], dtype=int)
            Pox = np.asarray([float(p_old[x]) for (_ids, tr) in seqs for (_s, x, p_old) in tr])
            Ad = np.asarray([a for (_ids, tr), a in zip(seqs, adv) for _tok in tr], dtype=float)
            ar = np.arange(len(S))
            for ep in range(epocas):
                z = pol["W"][S]
                p = np.exp(z - z.max(axis=1, keepdims=True))
                p = p / p.sum(axis=1, keepdims=True)
                ratio = p[ar, X] / np.maximum(Pox, 1e-12)
                oh = -p
                oh[ar, X] += 1.0
                corte = ((Ad > 0) & (ratio > 1.0 + eps_hi)) | ((Ad < 0) & (ratio < 1.0 - eps))
                g = np.where(corte, 0.0, Ad * ratio)[:, None] * oh
                lq = np.log(p + 1e-12) + math.log(p.shape[1])
                kl = (p * lq).sum(axis=1, keepdims=True)
                G = np.zeros_like(pol["W"])
                extra = -beta * p * (lq - kl)
                if c_ent:
                    extra = extra + c_ent * r29_dH(p)
                np.add.at(G, S, g + extra)
                pol["W"] += lr * G / B
            continue
        # ORD e braços com antítese: gradientes por SEQUÊNCIA
        adv = rs - baseline
        baseline = 0.9 * baseline + 0.1 * float(rs.mean())
        shp = pol["W"].shape
        Gt = np.zeros((B, shp[0] * shp[1]))
        Ga = np.zeros((B, shp[0] * shp[1]))
        for i, (ids, tr) in enumerate(seqs):
            gt = np.zeros(shp)
            ga = np.zeros(shp)
            for (s, x, p_old) in tr:
                p = np.exp(pol["W"][s] - pol["W"][s].max())
                p = p / p.sum()
                oh = -p.copy()
                oh[x] += 1.0
                gt[s] += adv[i] * oh
                if modo != "ORD":
                    ga[s] += r29_dH(p[None, :])[0]
            Gt[i] = gt.reshape(-1)
            Ga[i] = ga.reshape(-1)
        if modo == "ORD":
            pol["W"] += lr * Gt.mean(axis=0).reshape(shp)
            continue
        nt, na = float(np.linalg.norm(Gt.mean(axis=0))), float(np.linalg.norm(Ga.mean(axis=0)))
        if na > 1e-15:
            Ga = Ga * (nt / na)
        mm = {"SOMA": "FIXA", "PCG": "PCG", "DIAL": "DIAL"}[modo]
        g, info = r29_sintese(Gt, Ga, mm, beta=float(hp) if modo == "SOMA" else 1.0)
        wa_list.append(info["wa"]); cos_list.append(info["cos"])
        pol["W"] += lr * g.reshape(shp)
    return {"pol": pol, "wa": float(np.mean(wa_list)) if wa_list else 0.0, "conf": float(np.mean([c < 0 for c in cos_list])) if cos_list else 0.0}


def r29_job_rl(task):
    """task = ('RL', modo, tarefa, seed, lr, hp, completo). DEV: só r_clean k=1; TESTE: + entropia."""
    _, modo, tn, seed, lr, hp, completo = task
    tz = r28_tarefa(tn)
    tr = r29_rl_treinar(tz, seed, lr, modo, hp)
    k1 = r27_avaliar_aninhado(tz, tr["pol"], seed, f"R29|{modo}", 1)[1][0]
    out = {"k1": float(k1), "modo": modo, "tarefa": tn, "seed": int(seed)}
    if completo:
        out["ent"] = float(r28_ent_norm(tz, tr["pol"], seed, f"R29|{modo}"))
        out["wa"] = tr["wa"]
        out["conf"] = tr["conf"]
    return out


# ---------------------------------------------------------------------------
# DIALÉTICA — ambientes de brinquedo E1–E3
# ---------------------------------------------------------------------------
def _r29_rede(rng, nh):
    return [rng.normal(0, 1.0 / math.sqrt(10), (10, 16)), np.zeros(16), rng.normal(0, 0.25, (16, nh)), np.zeros(nh)]


def _r29_psg(P, x, dl, head):
    h = np.tanh(x @ P[0] + P[1])
    dh = dl[:, None] * P[2][:, head][None, :] * (1.0 - h * h)
    n = len(x)
    gW1 = (x[:, :, None] * dh[:, None, :]).reshape(n, -1)
    nh = P[2].shape[1]
    gW2 = np.zeros((n, 16, nh))
    gW2[:, :, head] = dl[:, None] * h
    gb2 = np.zeros((n, nh))
    gb2[:, head] = dl
    return np.concatenate([gW1, dh, gW2.reshape(n, -1), gb2], axis=1), h


def _r29_logit(P, x, head):
    h = np.tanh(x @ P[0] + P[1])
    return h @ P[2][:, head] + P[3][head]


def _r29_prob(z):
    return 1.0 / (1.0 + np.exp(-np.clip(z, -40, 40)))


def _r29_dx(P, x, dl, head):
    h = np.tanh(x @ P[0] + P[1])
    return (dl[:, None] * P[2][:, head][None, :] * (1.0 - h * h)) @ P[0].T


def _r29_aplicar(P, g, lr):
    o = 0
    for i in range(4):
        n = P[i].size
        P[i] -= lr * g[o:o + n].reshape(P[i].shape)
        o += n


def r29_toy_dados(env: str, seed: int):
    rng = r25_rng(seed, r29_crc("toy|" + env), 1)
    dA = rng.normal(size=10); dA /= np.linalg.norm(dA)
    u = rng.normal(size=10); u -= (u @ dA) * dA; u /= np.linalg.norm(u)
    dB = -0.5 * dA + math.sqrt(0.75) * u
    xtr, xte = rng.normal(size=(256, 10)), rng.normal(size=(400, 10))
    yA, yAt = (xtr @ dA > 0).astype(float), (xte @ dA > 0).astype(float)
    yB, yBt = (xtr @ dB > 0).astype(float), (xte @ dB > 0).astype(float)
    if env == "E1":
        yA = np.where(rng.random(256) < 0.10, 1 - yA, yA)
        yB = np.where(rng.random(256) < 0.10, 1 - yB, yB)
    elif env == "E2":
        yA = np.where(rng.random(256) < 0.25, 1 - yA, yA)
    return xtr, yA, yB, xte, yAt, yBt


def r29_toy_run(env: str, seed: int, arm: str, lr: float, beta: float = 1.0):
    xtr, yA, yB, xte, yAt, yBt = r29_toy_dados(env, seed)
    nh = 2 if env == "E1" else 1
    P = _r29_rede(r25_rng(seed, r29_crc("toy|init"), 2), nh)
    rb = r25_rng(seed, r29_crc("toy|batch|" + env), 3)
    batch = 64 if arm == "TESE_2X" else 32
    modo = {"TESE_2X": "TESE", "FIXA": "FIXA"}.get(arm, arm)
    wa_l, cf_l = [], []
    eps_adv = 0.3
    for _ in range(150):
        ix = rb.integers(0, 256, size=batch)
        x = xtr[ix]
        dlA = _r29_prob(_r29_logit(P, x, 0)) - yA[ix]
        Gt, _h = _r29_psg(P, x, dlA, 0)
        if modo == "TESE":
            g = Gt.mean(0)
        else:
            if env == "E1":
                dlB = _r29_prob(_r29_logit(P, x, 1)) - yB[ix]
                Ga, _h2 = _r29_psg(P, x, dlB, 1)
            elif env == "E2":
                perda = -(yA[ix] * np.log(_r29_prob(_r29_logit(P, x, 0)) + 1e-12) + (1 - yA[ix]) * np.log(1 - _r29_prob(_r29_logit(P, x, 0)) + 1e-12))
                top = np.argsort(-perda)[:8]
                Ga = Gt[top]
            else:
                xa = x + eps_adv * np.sign(_r29_dx(P, x, dlA, 0))
                dla = _r29_prob(_r29_logit(P, xa, 0)) - yA[ix]
                Ga, _h3 = _r29_psg(P, xa, dla, 0)
            g, info = r29_sintese(Gt, Ga, modo, beta=beta)
            wa_l.append(info["wa"]); cf_l.append(info["cos"] < 0)
        _r29_aplicar(P, g, lr)
    ok = True
    accA = float(((_r29_logit(P, xte, 0) > 0) == (yAt > 0.5)).mean())
    if env == "E1":
        accB = float(((_r29_logit(P, xte, 1) > 0) == (yBt > 0.5)).mean())
        m = 0.5 * (accA + accB)
    elif env == "E2":
        m = accA
    else:
        dl = _r29_prob(_r29_logit(P, xte, 0)) - yAt
        xa = xte + eps_adv * np.sign(_r29_dx(P, xte, dl, 0))
        accR = float(((_r29_logit(P, xa, 0) > 0) == (yAt > 0.5)).mean())
        m = 0.5 * (accA + accR)
    if not all(np.isfinite(p).all() for p in P):
        m = 0.5
    return {"m": float(m), "wa": float(np.mean(wa_l)) if wa_l else 0.0, "conf": float(np.mean(cf_l)) if cf_l else 0.0}


def r29_job_toy(task):
    _, env, arm, seed, lr, beta = task
    return r29_toy_run(env, seed, arm, lr, beta)


# ---------------------------------------------------------------------------
# PARTE C — CBP com variantes de sequência
# ---------------------------------------------------------------------------
def r29_cbp_seq(seed: int, var: str, rho: float, bracos=("BP", "SP", "CBP"), T: int = 40):
    H = 16 if var == "V3" else 32
    lr = {"V1": 0.1, "V2": 0.5, "V3": 0.3}[var]
    passos = 300 if var == "V2" else 150
    rng = r25_rng(seed, r29_crc("cbp|" + var), 1)
    tarefas = []
    X0 = rng.normal(size=(128, 8))
    for _ in range(T):
        if var == "V2":
            Wt, bt, vt = rng.normal(size=(8, 8)), rng.normal(size=8), rng.normal(size=8)
            xtr, xte = rng.normal(size=(256, 8)), rng.normal(size=(256, 8))
            ttr, tte = np.tanh(xtr @ Wt + bt) @ vt, np.tanh(xte @ Wt + bt) @ vt
            med = float(np.median(ttr))
            tarefas.append((xtr, (ttr > med).astype(float), xte, (tte > med).astype(float)))
        else:
            y = (rng.random(128) < 0.5).astype(float)
            tarefas.append((X0, y, X0, y))
    sonda = rng.normal(size=(256, 8))
    out = {}
    for braco in bracos:
        r = r25_rng(seed, r29_crc("cbp|init"), 2)
        P = _r28_mlp_bin(r, 8, H)
        rs = r25_rng(seed, r29_crc("cbp|sp"), 3)
        util = np.zeros(H); idade = np.zeros(H); cont = 0.0
        curva = []
        for k, (xtr, ytr, xte, yte) in enumerate(tarefas):
            if braco == "SP" and k > 0:
                P = [0.8 * p + rs.normal(0, 0.05, p.shape) for p in P]
            rb = r25_rng(seed, r29_crc("cbp|batch"), k)
            n = len(ytr)
            for _ in range(passos):
                ix = rb.integers(0, n, size=32)
                h = _r28_sgd_passo(P, xtr[ix], ytr[ix], lr)
                if braco == "CBP":
                    util = 0.99 * util + 0.01 * (np.abs(h).mean(0) * np.abs(P[2]).reshape(-1))
                    idade += 1
                    el = np.where(idade > 100)[0]
                    cont += rho * len(el)
                    if cont >= 1.0 and len(el) > 0:
                        j = int(el[np.argmin(util[el])])
                        P[0][:, j] = rs.normal(0, math.sqrt(2.0 / 8), 8)
                        P[1][j] = 0.0; P[2][j, 0] = 0.0
                        util[j] = float(np.median(util)); idade[j] = 0; cont -= 1.0
            lg, _, _ = _r28_relu_fw(P, xte)
            curva.append(float(((lg > 0) == (yte > 0.5)).mean()) if np.isfinite(lg).all() else 0.5)
        _lg, hh, _z = _r28_relu_fw(P, sonda)
        c = np.asarray(curva)
        out[braco] = {"curva": c, "ini5": float(c[:5].mean()), "fim5": float(c[-5:].mean()), "mortas": float(np.mean((hh > 0).sum(axis=0) == 0)),
                      "posto": r28_posto_efetivo(hh) if hh.std() > 0 else 1.0, "norma": float(np.sqrt(sum(float((p ** 2).sum()) for p in P)))}
    return out


def r29_job_cbp(task):
    _, var, seed, rho, bracos = task
    return r29_cbp_seq(seed, var, rho, bracos)


# ---------------------------------------------------------------------------
# PARTE D — EWC proximal × replay
# ---------------------------------------------------------------------------
def r29_esq(seed: int, lams, bracos=("NADA", "REPLAY", "EWC"), n_tar: int = 5, passos: int = 200):
    rng = r25_rng(seed, r29_crc("esq"), 1)
    D = []
    for _ in range(n_tar):
        d = rng.normal(size=10); d /= np.linalg.norm(d)

        def amostra(m, d=d):
            y = (rng.random(m) < 0.5).astype(float)
            x = rng.normal(size=(m, 10)) + (2.0 * y - 1.0)[:, None] * 0.75 * d[None, :]
            return x, y
        D.append((amostra(200), amostra(400)))
    out = {}
    plano = [(b, None) for b in bracos if b != "EWC"] + ([("EWC", lam) for lam in lams] if "EWC" in bracos else [])
    for braco, lam in plano:
        r = r25_rng(seed, r29_crc("esq|init"), 2)
        P = _r28_mlp_bin(r, 10, 32)
        buf_x, buf_y = [], []
        Fs = [np.zeros_like(p) for p in P]
        FA = [np.zeros_like(p) for p in P]
        apos = []
        rb = r25_rng(seed, r29_crc("esq|batch"), 3)
        rf = r25_rng(seed, r29_crc("esq|fisher"), 4)
        for k, ((xtr, ytr), _te) in enumerate(D):
            for _ in range(passos):
                ix = rb.integers(0, len(ytr), size=32 if braco != "REPLAY" or not buf_x else 16)
                x, y = xtr[ix], ytr[ix]
                if braco == "REPLAY" and buf_x:
                    bx, by = np.concatenate(buf_x), np.concatenate(buf_y)
                    jx = rb.integers(0, len(by), size=16)
                    x, y = np.concatenate([x, bx[jx]]), np.concatenate([y, by[jx]])
                _r28_sgd_passo(P, x, y, 0.05)
                if braco == "EWC" and k > 0:
                    for i in range(4):
                        P[i] = (P[i] + 0.05 * lam * FA[i]) / (1.0 + 0.05 * lam * Fs[i])
            if braco == "REPLAY":
                ji = rb.integers(0, len(ytr), size=20)
                buf_x.append(xtr[ji]); buf_y.append(ytr[ji])
            if braco == "EWC":
                F = [np.zeros_like(p) for p in P]
                ji = rf.integers(0, len(ytr), size=200)
                for i1 in ji:
                    xs = xtr[i1:i1 + 1]
                    lg, h, z = _r28_relu_fw(P, xs)
                    p1 = 1.0 / (1.0 + math.exp(-float(np.clip(lg[0], -40, 40))))
                    dl = np.array([[p1 - float(ytr[i1])]])
                    dh = (dl @ P[2].T) * (z > 0)
                    gs = [xs.T @ dh, dh.sum(0), h.T @ dl, dl.sum(0)]
                    for i in range(4):
                        F[i] += gs[i] ** 2 / 200.0
                mu = float(np.mean(np.concatenate([f.reshape(-1) for f in F]))) + 1e-12
                for i in range(4):
                    Fn = F[i] / mu
                    Fs[i] += Fn
                    FA[i] += Fn * P[i]
            apos.append(float(((_r28_relu_fw(P, D[k][1][0])[0] > 0) == (D[k][1][1] > 0.5)).mean()))
        fim = [float(((_r28_relu_fw(P, te[0])[0] > 0) == (te[1] > 0.5)).mean()) for _tr, te in D]
        fin = all(np.isfinite(p).all() for p in P)
        acc = float(np.mean(fim))
        rot = braco if lam is None else f"EWC@{lam:g}"
        out[rot] = {"acc": acc, "esq": float(np.mean([apos[k] - fim[k] for k in range(n_tar - 1)])), "diverge": bool((not fin) or acc < 0.45)}
    return out


def r29_job_esq(task):
    _, seed, lams, bracos = task
    return r29_esq(seed, lams, bracos)


# ---------------------------------------------------------------------------
# PARTE E — mini-JEPA em dose-resposta
# ---------------------------------------------------------------------------
def r29_jepa(seed: int, sd_d: float, n: int = 256, passos: int = 600):
    rng = r25_rng(seed, r29_crc("jepa|%g" % sd_d), 1)
    A, B = rng.normal(size=(4, 3)), rng.normal(size=(4, 3))

    def gerar(m):
        z = rng.normal(size=(m, 3))
        x1 = np.c_[z @ A.T + 0.1 * rng.normal(size=(m, 4)), sd_d * rng.normal(size=(m, 4))]
        x2 = np.c_[z @ B.T + 0.1 * rng.normal(size=(m, 4)), sd_d * rng.normal(size=(m, 4))]
        return z, x1, x2
    ztr, x1, x2 = gerar(n)
    zte, x1t, _x2t = gerar(n)
    out = {}
    for braco in ("JEPA_EMA", "RECON"):
        r = r25_rng(seed, r29_crc("jepa|init"), 2)
        f = _r28_rede2(r, 8, 16, 8)
        g = _r28_rede2(r, 8, 16, 8)
        ft = [p.copy() for p in f]
        P = f + g
        M = [np.zeros_like(p) for p in P]
        V = [np.zeros_like(p) for p in P]
        for t in range(1, passos + 1):
            e1, h1 = _r28_fw(f, x1)
            pred, hp = _r28_fw(g, e1)
            if braco == "RECON":
                dpred = 2.0 * (pred - x2) / pred.size
            else:
                et, _ = _r28_fw(ft, x2)
                dpred = 2.0 * (pred - et) / pred.size
            gg, de = _r28_bw(g, e1, hp, dpred)
            gf, _ = _r28_bw(f, x1, h1, de)
            r28_adam_passo(P, gf + gg, M, V, t, 0.01)
            if braco == "JEPA_EMA":
                for i in range(4):
                    ft[i] = 0.99 * ft[i] + 0.01 * f[i]
        Etr = _r28_fw(f, x1)[0]
        Ete = _r28_fw(f, x1t)[0]
        out[braco] = {"posto": r28_posto_efetivo(Ete), "std": float(Ete.std(axis=0).mean()), "r2": r28_sonda_r2(Etr, ztr, Ete, zte)}
    return out


def r29_job_jepa(task):
    _, seed, sd_d = task
    return r29_jepa(seed, sd_d)


def r29_job(task):
    k = task[0]
    return {"MEM": lambda t: r29_mem_run(t[1], t[2]), "RL": r29_job_rl, "TOY": r29_job_toy, "CBP": r29_job_cbp, "ESQ": r29_job_esq,
            "JEP": r29_job_jepa, "M": r28_mega_job}[k](task)


