def r29_dev_escolher(tab, chaves, fator, extensao):
    """tab: {(lr, hp): média}. Escolhe o maior (empate: menor lr, depois menor hp). Se na borda do lr e extensao ainda não usada, devolve a extensão pedida."""
    best = max(tab, key=lambda k: (tab[k], -k[0], -k[1]))
    lrs = sorted(set(k[0] for k in tab))
    if best[0] == lrs[0] and not extensao:
        return best, ("baixo", lrs[0] / fator)
    if best[0] == lrs[-1] and not extensao:
        return best, ("alto", lrs[-1] * fator)
    return best, None


