def registro_r29(ctx: Contexto) -> list:
    r = ctx.res.get("r29")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R29 (BLOCO 37) — " + " | ".join(f"{f} {a} conf / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: MEM 6, SEG 13, DIAL 11)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} d_z={p[6]:+.2f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    for k in ("ver_mem", "ver_grpo29", "ver_cbp29", "ver_esq29", "ver_jepa29", "ver_dial29", "ver_mega29", "ver_verif29"):
        L.append(f"  {r[k]}")
    return L


