    desc = r29_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R29", f"R29-{k}", "CONF", desc[k], f"Δ={m:+.4f} d_z={dz:+.2f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    for nome, ch in (("memória", "ver_mem"), ("dialética", "ver_dial29"), ("Mega-Sena (regressão)", "ver_mega29"), ("verificador Prolog (invariante)", "ver_verif29")):
        out.append(("R29", f"R29-V[{nome}]", "DESC", f"Veredito: {nome}", r[ch], "descritiva"))
    out.append(("R29", "R29-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
