def r30_desloc() -> int:
    v = os.environ.get("R30_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r30_crc(rot: str) -> int:
    return zlib.crc32(f"R30|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r30_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R30_SEEDS.items()}


# ---------------------------------------------------------------------------
# PARTE A — MEMÓRIA EM TOKENS (observáveis só)
# ---------------------------------------------------------------------------
def r30_mem_payload(lake):
    """6 pares-atributo da ponte (como na R29), palavras irrelevantes, e a VIZINHA de maior cosseno de cada um dos 12 termos (fora dos termos e das irrelevantes)."""
    ok = [(p, e) for p, e in PARES_PONTE if p in lake.emb.idx and e in lake.emb.idx]
    attrs = ok[:6]
    termos = [w for par in attrs for w in par]
    usados = set(termos)
    irr = [w for par in ok[6:] for w in par if w not in usados][:60]
    vocab = [w for w, _i in sorted(lake.emb.idx.items(), key=lambda kv: kv[1])]
    Vm = np.array([np.asarray(lake.vetor(w), float) for w in vocab])
    Vm = Vm / np.maximum(np.linalg.norm(Vm, axis=1, keepdims=True), 1e-12)
    excl = set(termos) | set(irr)
    viz = {}
    for t_ in termos:
        v = np.asarray(lake.vetor(t_), float)
        s = Vm @ (v / max(float(np.linalg.norm(v)), 1e-12))
        for i in np.argsort(-s):
            if vocab[int(i)] not in excl:
                viz[t_] = vocab[int(i)]
                break
    vec = {w: np.asarray(lake.vetor(w), float) for w in list(termos) + irr + list(viz.values())}
    return {"attrs": [list(a) for a in attrs], "irr": irr, "viz": viz, "vec": vec}


def r30_canon_map(payload):
    return {w: i for i, par in enumerate(payload["attrs"]) for w in par}


def r30_mem_mundo(seed: int, payload: dict):
    rng = r25_rng(seed, r30_crc("mem"), 1)
    attrs, irr, viz = payload["attrs"], payload["irr"], payload["viz"]
    cm = r30_canon_map(payload)
    perfil = [(0, 0), (0, 1)]
    quentes = [(1, 2), (1, 3), (1, 4), (1, 5)]
    hot = perfil + quentes
    resto = [(e, a) for e in range(24) for a in range(6) if (e, a) not in hot]
    outros = [resto[int(i)] for i in rng.choice(len(resto), 42, replace=False)]
    slots = hot + outros
    seq = list(slots)
    for _ in range(142):
        seq.append(hot[int(rng.integers(0, 6))] if rng.random() < 0.5 else outros[int(rng.integers(0, 42))])
    seq = [seq[int(i)] for i in rng.permutation(len(seq))]
    n_ev = 340
    pos_q = set(int(i) for i in rng.choice(np.arange(80, n_ev), 50, replace=False))
    resto_pos = [i for i in range(n_ev) if i not in pos_q]
    ordem = [resto_pos[int(i)] for i in rng.permutation(len(resto_pos))]
    tipo_de = {}
    for k, p_ in enumerate(ordem):
        tipo_de[p_] = "u" if k < 190 else ("c" if k < 250 else "n")
    for p_ in pos_q:
        tipo_de[p_] = "q"
    eventos, atual, hist = [], {}, {s: [] for s in slots}
    iu = 0
    nq_fallback = 0
    for t in range(n_ev):
        tp = tipo_de[t]
        if tp == "q":
            cand = [s for s in slots if len(hist[s]) >= 2]
            if not cand:
                tp = "c"
                nq_fallback += 1
        if tp == "u":
            s = seq[iu]
            iu += 1
            v = int(rng.integers(0, 20))
            while s in atual and v == atual[s]:
                v = int(rng.integers(0, 20))
            atual[s] = v
            hist[s].append((t, v))
            w = attrs[s[1]][int(rng.integers(0, 2))]
            eventos.append({"t": t, "ent": s[0], "w": w, "canon": cm.get(w, -1), "val": v, "perfil": s in perfil, "cit": False, "slot": s})
        elif tp == "c":
            w = irr[int(rng.integers(0, len(irr)))]
            eventos.append({"t": t, "ent": int(rng.integers(0, 24)), "w": w, "canon": cm.get(w, -1), "val": int(rng.integers(0, 20)), "perfil": False, "cit": False, "slot": None})
        elif tp == "n":
            s = slots[int(rng.integers(0, len(slots)))]
            w0 = attrs[s[1]][int(rng.integers(0, 2))]
            w = viz[w0]
            eventos.append({"t": t, "ent": s[0], "w": w, "canon": cm.get(w, -1), "val": int(rng.integers(0, 20)), "perfil": False, "cit": False, "slot": None})
        else:
            s = cand[int(rng.integers(0, len(cand)))]
            antigos = [x[1] for x in hist[s][:-1]]
            v = int(antigos[int(rng.integers(0, len(antigos)))])
            w = attrs[s[1]][int(rng.integers(0, 2))]
            eventos.append({"t": t, "ent": s[0], "w": w, "canon": cm.get(w, -1), "val": v, "perfil": False, "cit": True, "slot": None})
    uso = []
    for _ in range(40):
        t = int(rng.integers(100, n_ev))
        uso.append((t, hot[int(rng.integers(0, 6))] if rng.random() < 0.6 else outros[int(rng.integers(0, 42))]))
    cand_h = [s for s in hot if len(hist[s]) >= 2]
    cand_c = [s for s in outros if len(hist[s]) >= 2] or cand_h
    cons = []
    for _ in range(24):
        cons.append((hot[int(rng.integers(0, 6))], "vig"))
    for _ in range(24):
        cons.append((outros[int(rng.integers(0, 42))], "vig"))
    for _ in range(18):
        cons.append((cand_h[int(rng.integers(0, len(cand_h)))], "hist"))
    for _ in range(18):
        cons.append((cand_c[int(rng.integers(0, len(cand_c)))], "hist"))
    langs = [int(rng.integers(0, 2)) for _ in cons]
    return {"eventos": eventos, "atual": atual, "hist": hist, "uso": uso, "cons": cons, "langs": langs, "hot": hot, "perfil": perfil, "slots": slots, "nq_fallback": nq_fallback}


def r30_mem_ler(entradas, ent_q, w_q, canon_q, tipo, canonico, vec, rng):
    """Leitor (igual em todos os braços): descarta citações (cit); bruto = maior cosseno (empate: mais recente); canônico = canon igual; vigente = maior t; histórico = 2º maior t."""
    cand = [e for e in entradas if e["ent"] == ent_q and not e.get("cit")]
    if canonico:
        grp = [e for e in cand if e["canon"] == canon_q and e["canon"] >= 0]
        if not grp:
            return int(rng.integers(0, 20))
    else:
        if not cand:
            return int(rng.integers(0, 20))
        sc = [1.0 + _r29_cos(vec[e["w"]], vec[w_q]) for e in cand]
        best = max(sc)
        grp = [e for e, s in zip(cand, sc) if s >= best - 1e-9]
    grp = sorted(grp, key=lambda x: -x["t"])
    if tipo == "vig":
        return int(grp[0]["val"])
    if len(grp) >= 2:
        return int(grp[1]["val"])
    return int(rng.integers(0, 20))


def _r30_topk(pool, ent_q, w_q, canon_q, canonico, vec, k, rng, hist=False):
    sc = []
    for e in pool:
        if canonico:
            s = (1.0 if e["ent"] == ent_q else 0.0) + (1.0 if (e["canon"] == canon_q and e["canon"] >= 0) else 0.0)
            if hist and e.get("status") == "anterior":
                s += 0.5
        else:
            s = (1.0 if e["ent"] == ent_q else 0.0) + _r29_cos(vec[e["w"]], vec[w_q])
        sc.append(s)
    jit = rng.random(len(pool)) * 1e-6
    ordem = np.argsort(-(np.asarray(sc) + jit))
    return [pool[int(i)] for i in ordem[:k]], len(pool)


def r30_mem_dedup(eventos, ate=None):
    """Estrutura por (entidade, canon): VIGENTE + ANTERIOR, só observáveis (descarta canon<0 e cit). Devolve (entradas, nº de operações)."""
    por = {}
    ops = 0
    for e in eventos:
        if ate is not None and e["t"] >= ate:
            break
        ops += 1
        if e["canon"] < 0 or e["cit"]:
            continue
        por.setdefault((e["ent"], e["canon"]), []).append(e)
    arq = []
    for k_, lst in por.items():
        lst = sorted(lst, key=lambda x: x["t"])
        arq.append(dict(lst[-1], status="vigente"))
        if len(lst) >= 2:
            arq.append(dict(lst[-2], status="anterior"))
    return arq, ops


R30_SONOS = (60, 120, 180, 240, 300)


def r30_mem_sono(eventos):
    """Consolidação incremental nos instantes de R30_SONOS (só observáveis). Devolve (arquivo no último sono, nº de operações offline)."""
    ops = 0
    prev = 0
    for ts in R30_SONOS:
        novos = [e for e in eventos if prev <= e["t"] < ts]
        ops += len(novos) + len(set((e["ent"], e["canon"]) for e in novos if e["canon"] >= 0 and not e["cit"]))
        prev = ts
    arq, _ = r30_mem_dedup(eventos, R30_SONOS[-1])
    return arq, ops


def r30_mem_run(seed: int, payload: dict):
    W = r30_mem_mundo(seed, payload)
    ev = W["eventos"]
    vec = payload["vec"]
    attrs = payload["attrs"]
    t_sono = R30_SONOS[-1]
    arq, ops_sono = r30_mem_sono(ev)
    cont = {}
    for (t, s) in W["uso"]:
        if t < t_sono:
            cont[(s[0], s[1])] = cont.get((s[0], s[1]), 0) + 1
    # perfil observável: chaves (ent, canon) com algum evento sinalizado
    chaves_perfil = sorted(set((e["ent"], e["canon"]) for e in ev if e["perfil"]))
    chaves_all = sorted(set((e["ent"], e["canon"]) for e in ev if e["canon"] >= 0 and not e["cit"]))
    ordem = sorted([k_ for k_ in chaves_all if k_ not in chaves_perfil], key=lambda k_: (-cont.get(k_, 0), k_))
    nucleo4 = chaves_perfil + ordem[:max(0, 4 - len(chaves_perfil))]

    def item_chave(k_, ate):
        lst = [e for e in ev if (e["ent"], e["canon"]) == k_ and not e["cit"] and e["t"] < ate]
        return dict(max(lst, key=lambda x: x["t"]), status="vigente") if lst else None

    core_a3 = [x for x in (item_chave(k_, 10 ** 9) for k_ in chaves_perfil) if x is not None]
    core_a4 = [x for x in (item_chave(k_, 10 ** 9 if k_ in chaves_perfil else t_sono) for k_ in nucleo4) if x is not None]
    raw_pos = [e for e in ev if e["t"] >= t_sono]
    pool_a4 = arq + [dict(e, status="vigente") for e in raw_pos]
    BR = ("A0", "A1", "A2", "A3", "A4", "A5")
    ac = {b: {"vig_q": [], "vig_f": [], "hist": []} for b in BR + ("ORACULO", "ALEAT")}
    confl = {b: [] for b in BR}
    obs_ = {b: [] for b in BR}
    nsim = {b: 0 for b in BR}
    toks_max = 0
    hot = set(W["hot"])
    cm = r30_canon_map(payload)
    reserva = {"A0": 6, "A1": 6, "A2": 6, "A3": 6, "A4": 6, "A5": 6}
    pool_a5, _o5 = r30_mem_dedup(ev)
    for qi, ((s, tipo), lang) in enumerate(zip(W["cons"], W["langs"])):
        w_q = attrs[s[1]][lang]
        verd = W["atual"][s] if tipo == "vig" else W["hist"][s][-2][1]
        cat = "hist" if tipo == "hist" else ("vig_q" if s in hot else "vig_f")
        r_q = r25_rng(seed, r30_crc("mem|q"), 100 + qi)
        ctxs = {}
        ctxs["A0"] = ev[-6:]
        c1, n1 = _r30_topk(ev, s[0], w_q, s[1], False, vec, 6, r_q); ctxs["A1"] = c1; nsim["A1"] += n1
        c2, n2 = _r30_topk(ev, s[0], w_q, s[1], True, vec, 6, r_q); ctxs["A2"] = c2; nsim["A2"] += n2
        c3, n3 = _r30_topk(ev, s[0], w_q, s[1], False, vec, 2, r_q); ctxs["A3"] = core_a3 + c3; nsim["A3"] += n3
        c4, n4 = _r30_topk(pool_a4, s[0], w_q, s[1], True, vec, 2, r_q, hist=(tipo == "hist")); ctxs["A4"] = core_a4 + c4; nsim["A4"] += n4
        c5, n5 = _r30_topk(pool_a5, s[0], w_q, s[1], True, vec, 6, r_q, hist=(tipo == "hist")); ctxs["A5"] = c5; nsim["A5"] += n5
        stale = set(x[1] for x in W["hist"][s][:-1]) - {W["atual"][s]}
        for b in BR:
            assert len(ctxs[b]) <= reserva[b] and reserva[b] * R30_ITEM_TOK <= R30_B_TOK
            toks_max = max(toks_max, reserva[b] * R30_ITEM_TOK)
            r_l = r25_rng(seed, r30_crc("mem|l" + b), 200 + qi)
            resp = r30_mem_ler(ctxs[b], s[0], w_q, s[1], tipo, b in ("A2", "A4", "A5"), vec, r_l)
            ac[b][cat].append(1.0 if resp == verd else 0.0)
            if tipo == "vig":
                vs = set(e["val"] for e in ctxs[b] if e["ent"] == s[0] and e["canon"] == s[1])
                confl[b].append(1.0 if len(vs) >= 2 else 0.0)
                obs_[b].append(1.0 if (resp != verd and resp in stale) else 0.0)
        ac["ORACULO"][cat].append(1.0)
        ac["ALEAT"][cat].append(1.0 if int(r_q.integers(0, 20)) == verd else 0.0)
    out = {}
    for b in BR + ("ORACULO", "ALEAT"):
        allq = ac[b]["vig_q"] + ac[b]["vig_f"] + ac[b]["hist"]
        out[b] = {"all": float(np.mean(allq)), "vig_q": float(np.mean(ac[b]["vig_q"])), "vig_f": float(np.mean(ac[b]["vig_f"])), "hist": float(np.mean(ac[b]["hist"]))}
    for b in BR:
        out[b]["confl"] = float(np.mean(confl[b]))
        out[b]["obsol"] = float(np.mean(obs_[b]))
    out["custo"] = {"tokens_max": int(toks_max), "sim": {b: int(v) for b, v in nsim.items()}, "ops_sono": int(ops_sono), "ops_escrita_a5": len(ev), "nq_fallback": int(W["nq_fallback"])}
    return out


# ---------------------------------------------------------------------------
# PARTE B — PLASTICIDADE
# ---------------------------------------------------------------------------
def r30_pla_seq(seed: int, opt: str, lr: float, braco: str, hp=None, T: int = 60, S: int = 60, n: int = 64, d: int = 8, H: int = 16):
    """Sequência de T tarefas de rótulos aleatórios sobre as mesmas n entradas. braco ∈ BP, SP (hp=λ), CBP (hp=ρ), BP_LOWLR (hp=divisor do lr)."""
    rng = r25_rng(seed, r30_crc("pla"), 1)
    X = rng.normal(size=(n, d))
    ys = [(rng.random(n) < 0.5).astype(float) for _ in range(T)]
    P = _r28_mlp_bin(r25_rng(seed, r30_crc("pla|init"), 2), d, H)
    rs = r25_rng(seed, r30_crc("pla|ruido"), 4)
    rb = r25_rng(seed, r30_crc("pla|batch"), 3)
    lr_ef = lr / float(hp) if braco == "BP_LOWLR" else lr
    M = [np.zeros_like(p) for p in P]
    V = [np.zeros_like(p) for p in P]
    t_ad = 0
    util = np.zeros(H); idade = np.zeros(H); cont = 0.0
    curva = []
    for k, y in enumerate(ys):
        if braco == "SP" and k > 0:
            P = [float(hp) * p + rs.normal(0, 0.01, p.shape) for p in P]
            M = [np.zeros_like(p) for p in P]; V = [np.zeros_like(p) for p in P]; t_ad = 0
        for _ in range(S):
            ix = rb.integers(0, n, size=32)
            xb, yb = X[ix], y[ix]
            lg, h, z = _r28_relu_fw(P, xb)
            p = 1.0 / (1.0 + np.exp(-np.clip(lg, -40, 40)))
            dl = ((p - yb) / len(yb)).reshape(-1, 1)
            dh = (dl @ P[2].T) * (z > 0)
            G = [xb.T @ dh, dh.sum(0), h.T @ dl, dl.sum(0)]
            if opt == "sgd":
                for i in range(4):
                    P[i] -= lr_ef * G[i]
            else:
                t_ad += 1
                r28_adam_passo(P, G, M, V, t_ad, lr_ef)
            if braco == "CBP":
                util = 0.99 * util + 0.01 * (np.abs(h).mean(0) * np.abs(P[2]).reshape(-1))
                idade += 1
                el = np.where(idade > 100)[0]
                cont += float(hp) * len(el)
                if cont >= 1.0 and len(el) > 0:
                    j = int(el[np.argmin(util[el])])
                    P[0][:, j] = rs.normal(0, math.sqrt(2.0 / d), d)
                    P[1][j] = 0.0; P[2][j, 0] = 0.0
                    for Q in (M, V):
                        Q[0][:, j] = 0.0; Q[1][j] = 0.0; Q[2][j, 0] = 0.0
                    util[j] = float(np.median(util)); idade[j] = 0; cont -= 1.0
        lg, _h, _z = _r28_relu_fw(P, X)
        curva.append(float(((lg > 0) == (y > 0.5)).mean()) if np.isfinite(lg).all() else 0.5)
    _lg, hh, _z = _r28_relu_fw(P, X)
    c = np.asarray(curva)
    return {"curva": c, "ini10": float(c[:10].mean()), "fim10": float(c[-10:].mean()), "mortas": float(np.mean((hh > 0).sum(axis=0) == 0)), "norma": float(np.sqrt(sum(float((p_ ** 2).sum()) for p_ in P)))}


def r30_job_pla(task):
    """task = ('PLA', seed, cand_idx, [(braco, hp), ...])."""
    _, seed, ci, arms = task
    _nome, opt, lr = R30_PLA_CAND[ci]
    return {f"{b}|{hp}": r30_pla_seq(seed, opt, lr, b, hp) for (b, hp) in arms}


# ---------------------------------------------------------------------------
# PARTE C — mini-JEPA com distratores de alta variância
# ---------------------------------------------------------------------------
def r30_jepa_dados(seed: int, var: str, sd: float = 30.0, n: int = 256):
    rng = r25_rng(seed, r30_crc("jepa|" + var), 1)
    A, B = rng.normal(size=(4, 3)), rng.normal(size=(4, 3))
    C, D = rng.normal(size=(4, 4)) / 2.0, rng.normal(size=(4, 4)) / 2.0

    def gerar(m):
        z = rng.normal(size=(m, 3))
        if var == "A":
            x1 = np.c_[z @ A.T + 0.1 * rng.normal(size=(m, 4)), sd * rng.normal(size=(m, 4))]
            x2 = np.c_[z @ B.T + 0.1 * rng.normal(size=(m, 4)), sd * rng.normal(size=(m, 4))]
        else:
            nz = sd * rng.normal(size=(m, 4))
            x1 = np.c_[z @ A.T + 0.1 * rng.normal(size=(m, 4)), nz @ C.T]
            x2 = np.c_[z @ B.T + 0.1 * rng.normal(size=(m, 4)), nz @ D.T]
        return z, x1, x2
    ztr, x1, x2 = gerar(n)
    zte, x1t, _x2t = gerar(n)
    mu, sg = x1.mean(0), x1.std(0) + 1e-8
    return ztr, (x1 - mu) / sg, x2, zte, (x1t - mu) / sg


def r30_jepa_treino(seed: int, var: str, braco: str, lr: float, dados=None, passos: int = 400):
    ztr, x1, x2, zte, x1t = dados if dados is not None else r30_jepa_dados(seed, var)
    de = 4 if var == "C" else 8
    r = r25_rng(seed, r30_crc("jepa|init"), 2)
    f = _r28_rede2(r, 8, 16, de)
    g = _r28_rede2(r, de, 16, de if braco == "JEPA" else 8)
    ft = [p.copy() for p in f]
    P = f + g
    M = [np.zeros_like(p) for p in P]
    V = [np.zeros_like(p) for p in P]
    alvo = (x2 - x2.mean(0)) / (x2.std(0) + 1e-8) if braco == "RECON_NORM" else x2
    for t in range(1, passos + 1):
        e1, h1 = _r28_fw(f, x1)
        pred, hp_ = _r28_fw(g, e1)
        if braco == "JEPA":
            et, _ = _r28_fw(ft, x2)
            dpred = 2.0 * (pred - et) / pred.size
        else:
            dpred = 2.0 * (pred - alvo) / pred.size
        gg, dE = _r28_bw(g, e1, hp_, dpred)
        gf, _ = _r28_bw(f, x1, h1, dE)
        r28_adam_passo(P, gf + gg, M, V, t, lr)
        if braco == "JEPA":
            for i in range(4):
                ft[i] = 0.99 * ft[i] + 0.01 * f[i]
    Etr, Ete = _r28_fw(f, x1)[0], _r28_fw(f, x1t)[0]
    return {"r2": r28_sonda_r2(Etr, ztr, Ete, zte), "posto": r28_posto_efetivo(Ete), "std": float(Ete.std(axis=0).mean())}


def r30_job_jepa(task):
    """task = ('JEP', seed, [(braco, lr), ...], vars). Devolve {(var, braco, lr): métricas}."""
    _, seed, specs, vars_ = task
    out = {}
    for var in vars_:
        dados = r30_jepa_dados(seed, var)
        for (b, lr) in specs:
            out[(var, b, lr)] = r30_jepa_treino(seed, var, b, lr, dados)
    return out


# ---------------------------------------------------------------------------
# PARTE D — DIALÉTICA RECALIBRADA
# ---------------------------------------------------------------------------
def r30_dial2_novo():
    return {"a": 0.0, "rap": None, "len": None}


def r30_dial2(Gt, Ga, eta: float, st: dict, perda: float):
    """SÍNTESE CALIBRADA: g = ḡ_t + w_a ĝ_a, w_a = η·π·α·s (antítese NATURAL, sem reescala). st = estado (concordância suavizada, EMAs da perda)."""
    gt, ga = Gt.mean(axis=0), Ga.mean(axis=0)
    nt, na = float(np.linalg.norm(gt)), float(np.linalg.norm(ga))
    cosv = float(gt @ ga) / (nt * na) if nt > 1e-15 and na > 1e-15 else 0.0
    st["a"] = 0.9 * st["a"] + 0.1 * cosv
    alfa = (1.0 + st["a"]) / 2.0
    ct, ca = r29_confianca(Gt, gt), r29_confianca(Ga, ga)
    pi_ = ca / (ct + ca) if (ct + ca) > 1e-12 else 0.5
    if st["rap"] is None:
        st["rap"] = st["len"] = float(perda)
    else:
        st["rap"] = 0.8 * st["rap"] + 0.2 * float(perda)
        st["len"] = 0.95 * st["len"] + 0.05 * float(perda)
    u = (st["len"] - st["rap"]) / (abs(st["len"]) + 0.05)
    s = 1.0 - min(max(u / 0.02, 0.0), 1.0)
    ga_p = ga - (ga @ gt) / (nt * nt) * gt if (cosv < 0 and nt > 1e-15) else ga
    wa = float(eta) * pi_ * alfa * s
    return gt + wa * ga_p, {"cos": cosv, "wa": wa, "pi": pi_, "alfa": alfa, "s": s}


def r30_sintese(Gt, Ga, modo: str, beta: float, st: dict, perda: float):
    if modo == "DIAL2":
        return r30_dial2(Gt, Ga, beta, st, perda)
    mm = {"DIAL_R29": "DIAL"}.get(modo, modo)
    return r29_sintese(Gt, Ga, mm, beta=beta)


def r30_toy_run(env: str, seed: int, arm: str, lr: float, beta: float = 1.0):
    xtr, yA, yB, xte, yAt, yBt = r29_toy_dados(env, seed)
    nh = 2 if env == "E1" else 1
    P = _r29_rede(r25_rng(seed, r29_crc("toy|init"), 2), nh)
    rb = r25_rng(seed, r29_crc("toy|batch|" + env), 3)
    batch = 64 if arm == "TESE_2X" else 32
    modo = {"TESE_2X": "TESE"}.get(arm, arm)
    st = r30_dial2_novo()
    wa_l, cf_l = [], []
    eps_adv = 0.3
    for _ in range(150):
        ix = rb.integers(0, 256, size=batch)
        x = xtr[ix]
        pA = _r29_prob(_r29_logit(P, x, 0))
        dlA = pA - yA[ix]
        Gt, _h = _r29_psg(P, x, dlA, 0)
        if modo == "TESE":
            g = Gt.mean(0)
        else:
            if env == "E1":
                dlB = _r29_prob(_r29_logit(P, x, 1)) - yB[ix]
                Ga, _h2 = _r29_psg(P, x, dlB, 1)
            elif env == "E2":
                perda_i = -(yA[ix] * np.log(pA + 1e-12) + (1 - yA[ix]) * np.log(1 - pA + 1e-12))
                top = np.argsort(-perda_i)[:8]
                Ga = Gt[top]
            else:
                xa = x + eps_adv * np.sign(_r29_dx(P, x, dlA, 0))
                dla = _r29_prob(_r29_logit(P, xa, 0)) - yA[ix]
                Ga, _h3 = _r29_psg(P, xa, dla, 0)
            perda = float(np.mean(-(yA[ix] * np.log(pA + 1e-12) + (1 - yA[ix]) * np.log(1 - pA + 1e-12))))
            g, info = r30_sintese(Gt, Ga, modo, beta, st, perda)
            wa_l.append(info["wa"]); cf_l.append(info["cos"] < 0)
        _r29_aplicar(P, g, lr)
    accA = float(((_r29_logit(P, xte, 0) > 0) == (yAt > 0.5)).mean())
    if env == "E1":
        m = 0.5 * (accA + float(((_r29_logit(P, xte, 1) > 0) == (yBt > 0.5)).mean()))
    elif env == "E2":
        m = accA
    else:
        dl = _r29_prob(_r29_logit(P, xte, 0)) - yAt
        xa = xte + eps_adv * np.sign(_r29_dx(P, xte, dl, 0))
        m = 0.5 * (accA + float(((_r29_logit(P, xa, 0) > 0) == (yAt > 0.5)).mean()))
    if not all(np.isfinite(p).all() for p in P):
        m = 0.5
    return {"m": float(m), "wa": float(np.mean(wa_l)) if wa_l else 0.0, "conf": float(np.mean(cf_l)) if cf_l else 0.0}


def r30_job_toy(task):
    _, env, arm, seed, lr, beta = task
    return r30_toy_run(env, seed, arm, lr, beta)


def r30_rl_treinar(tarefa, seed: int, lr: float, modo: str, hp=None):
    """RL tabular. ORD/GRPO/DIAL_R29 delegam ao treinador R29 (inalterado). FIXA/PCG/DIAL2: antítese = ascensão de entropia em ESCALA NATURAL (sem reescala à norma da tese)."""
    if modo == "ORD":
        return r29_rl_treinar(tarefa, seed, lr, "ORD", 0.0)
    if modo == "GRPO":
        return r29_rl_treinar(tarefa, seed, lr, "GRPO", 0.0)
    if modo == "DIAL_R29":
        return r29_rl_treinar(tarefa, seed, lr, "DIAL", 0.0)
    hp = float(hp) if hp is not None else 1.0
    rng = r25_rng(seed, r25_crc(f"train|{tarefa.nome}"), 5)
    pol = tarefa.init_pol(rng)
    baseline = 0.0
    st = r30_dial2_novo()
    wa_l, cos_l = [], []
    for t in range(tarefa.P):
        seqs, rs = [], []
        for b in range(tarefa.batch):
            ids, tr = tarefa.sample(pol, rng)
            lau = tarefa.laudo(ids, seed, t * tarefa.batch + b)
            rs.append(float(lau["score_laudo"]) + tarefa.ruido(ids, seed, t * tarefa.batch + b))
            seqs.append((ids, tr))
        rs = np.asarray(rs)
        B = max(len(seqs), 1)
        adv = rs - baseline
        baseline = 0.9 * baseline + 0.1 * float(rs.mean())
        shp = pol["W"].shape
        Gt = np.zeros((B, shp[0] * shp[1]))
        Ga = np.zeros((B, shp[0] * shp[1]))
        for i, (ids, tr) in enumerate(seqs):
            gt = np.zeros(shp)
            ga = np.zeros(shp)
            for (s, x, _p_old) in tr:
                p = np.exp(pol["W"][s] - pol["W"][s].max())
                p = p / p.sum()
                oh = -p.copy()
                oh[x] += 1.0
                gt[s] += adv[i] * oh
                ga[s] += r29_dH(p[None, :])[0]
            Gt[i] = gt.reshape(-1)
            Ga[i] = ga.reshape(-1)
        g, info = r30_sintese(Gt, Ga, modo, hp, st, -float(rs.mean()))
        wa_l.append(info["wa"]); cos_l.append(info["cos"])
        pol["W"] += lr * g.reshape(shp)
    return {"pol": pol, "wa": float(np.mean(wa_l)) if wa_l else 0.0, "conf": float(np.mean([c < 0 for c in cos_l])) if cos_l else 0.0}


def r30_job_rl(task):
    """task = ('RL', modo, tarefa, seed, lr, hp, completo)."""
    _, modo, tn, seed, lr, hp, completo = task
    tz = r28_tarefa(tn)
    tr = r30_rl_treinar(tz, seed, lr, modo, hp)
    k1 = r27_avaliar_aninhado(tz, tr["pol"], seed, f"R30|{modo}", 1)[1][0]
    out = {"k1": float(k1), "modo": modo, "tarefa": tn, "seed": int(seed)}
    if completo:
        out["ent"] = float(r28_ent_norm(tz, tr["pol"], seed, f"R30|{modo}"))
        out["wa"] = tr["wa"]
        out["conf"] = tr["conf"]
    return out


def r30_job(task):
    k = task[0]
    return {"MEM": lambda t: r30_mem_run(t[1], t[2]), "RL": r30_job_rl, "TOY": r30_job_toy, "PLA": r30_job_pla, "JEP": r30_job_jepa, "M": r28_mega_job}[k](task)


