def r30_linhas_mapa(args, r27, r28v, r29v, r30v):
    L = []
    for rotulo, nomes, rod, tema, fixo, evid in R30_MAPA:
        if fixo:
            est = fixo
        else:
            ests = sorted(set(r30_estado_bloco(args, n) for n in nomes)) or ["ATIVO"]
            est = ests[0] if len(ests) == 1 else "MISTO: " + "/".join(e.split(" ")[0] for e in ests)
        L.append((rotulo, est, tema + " → " + evid))
    base = r29_linhas_mapa(args, r27, r28v, r29v)[len(R29_MAPA):]
    g = lambda k, d="(sem resultado nesta execução)": (r30v or {}).get(k, d)
    sub = {
        "RL ordinário": ("RL ordinário", "ATIVO (pilha padrão TRAVADA)", "R23 S1/S2, R24 H1/H2; R25 A1/Y1; R26 L1; R28 W1; R29 GR1/DL8; R30 D5 (ORD) comparam"),
        "Mega-Sena": ("Mega-Sena", "DORMENTE (nulo honesto; regressão ao vivo na R30)", g("ver_mega30")[:140]),
        "mini-JEPA (proxy)": ("mini-JEPA (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_jepa30")[:140]),
        "CBP / shrink-and-perturb (proxy)": ("CBP / shrink-and-perturb (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_cbp30")[:140]),
        "memória em tokens core/recall/archival": ("memória em tokens core/recall/archival", "PROXY (brinquedo; fora da pilha)", g("ver_mem30")[:140]),
        "verificador de consistência (Prolog)": ("verificador de consistência (Prolog)", "ATIVO (núcleo lógico; não é evidência de cognição)", g("ver_verif30")[:140]),
        "dialética de gradientes (proxy)": ("dialética de gradientes (proxy)", "PROXY (brinquedo; fora da pilha)", g("ver_dial30")[:140]),
    }
    for (n, est, ev) in base:
        L.append(sub[n] if n in sub else (n, est, ev))
    return L


def mapa_do_que_vive_linhas_r30(ctx: Contexto) -> list:
    lin = r30_linhas_mapa(ctx.args, ctx.res.get("r27") or {}, ctx.res.get("r28") or {}, ctx.res.get("r29") or {}, ctx.res.get("r30") or {})
    n_blocos = len(R30_MAPA)
    rods = {r_[0]: r_[2] for r_ in R30_MAPA}
    trans_rod = {"filtro-primeiro (τ fixo)": "R20", "filtro adaptativo (travado)": "R26–R30", "RL ordinário": "R19–R30", "RL extraordinário": "R19–R30",
                 "porta de geração (k)": "R25–R30", "meta-recompensa (bruta/calibrada)": "R24–R30", "meta-recompensa NORMALIZADA": "R26–R30", "delírio": "R3–R22",
                 "BitLinear ternário v2 (STE)": "R25–R30", "BitLinear v1 (R24)": "R24", "SNN LIF (R24)": "R24", "prefill/decode (intensidade)": "R24", "Mega-Sena": "R18–R30",
                 "memória em tokens core/recall/archival": "R29–R30", "dialética de gradientes (proxy)": "R29–R30", "verificador de consistência (Prolog)": "R28–R30",
                 "mini-JEPA (proxy)": "R29–R30", "CBP / shrink-and-perturb (proxy)": "R29–R30"}
    L = ["MAPA DO QUE VIVE (30 rodadas) — estado de cada bloco derivado das funções de dormência do próprio código",
         "estados: ATIVO = roda ao vivo | DORMENTE = resultado congelado (sha256), recálculo atrás de --reativar-dormentes | CONGELADO = módulo encerrado | PROXY = brinquedo rotulado, fora da pilha | NÚCLEO-MATEMÁTICO = fato verificável, não evidência de cognição",
         f"{'módulo/bloco':<28}{'rodada':<9}{'estado':<38}tema → evidência"]
    for i, (rot, est, ev) in enumerate(lin):
        if i == n_blocos:
            L.append("--- módulos transversais (estado pelo veredito desta execução) ---")
        rod = rods.get(rot) if i < n_blocos else trans_rod.get(rot, "R29")
        L.append(f"{rot:<28}{rod:<9}{est:<38}{ev}")
    return L


def r30_bc_do_run(ctx, st_hip, vt):
    linhas = r30_linhas_mapa(ctx.args, ctx.res.get("r27") or {}, ctx.res.get("r28") or {}, ctx.res.get("r29") or {}, ctx.res.get("r30") or {})
    r28 = ctx.res.get("r28") or {}
    n_k = int(r28.get("custo_alloc", 0)); T_eff = len(r28.get("eff", []))
    stack = {"rl": R28_STACK_DEFAULT["rl"], "gate": R28_STACK_DEFAULT["gate_k"], "filtro": R28_STACK_DEFAULT["filtro"],
             "meta": "nenhum" if R28_STACK_DEFAULT["meta"] is None else str(R28_STACK_DEFAULT["meta"]), "extra": "sim" if R28_STACK_DEFAULT["extra"] else "nao"}
    return r28_bc_de_mapa(linhas, st_hip, stack, {"alocado": n_k, "fixo": int(R25_K_GATE * T_eff)}, {"nexus": vt}, {"nexus": R30_NEXUS_ESPERADO}, ["extraordinario"])


