def registro_r30(ctx: Contexto) -> list:
    r = ctx.res.get("r30")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R30 (BLOCO 38) — " + " | ".join(f"{f} {a} conf / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: MEM 7, PLA 5, JEP 6, DIAL 9)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} d_z={p[6]:+.2f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    for k in ("ver_mem30", "ver_pla30", "ver_jep30", "ver_dial30", "ver_mega30", "ver_verif30"):
        L.append(f"  {r[k]}")
    return L


