def registro_hipoteses_r30(ctx: Contexto) -> list:
    r = ctx.res.get("r30")
    if not r or "P" not in r:
        return []
    desc = r30_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R30", f"R30-{k}", "CONF", desc[k], f"Δ={m:+.4f} d_z={dz:+.2f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    for nome, ch in (("memória", "ver_mem30"), ("plasticidade", "ver_pla30"), ("mini-JEPA", "ver_jep30"), ("dialética", "ver_dial30"), ("Mega-Sena (regressão)", "ver_mega30"), ("verificador Prolog (invariante)", "ver_verif30")):
        out.append(("R30", f"R30-V[{nome}]", "DESC", f"Veredito: {nome}", r[ch], "descritiva"))
    out.append(("R30", "R30-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


