R31_CONGELADO_B64 = "".join(R31_CONGELADO_B64_CHUNKS)

_R31_CONG_CACHE = {"v": None}


def r31_congelado():
    if _R31_CONG_CACHE["v"] is not None:
        return _R31_CONG_CACHE["v"]
    if not R31_CONGELADO_B64 or R31_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R31_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R31_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R31_CONG_CACHE["v"] = v
    return v


def r31_env_vivo() -> bool:
    """Qualquer flag de depuração/bloco novo de OUTRA rodada (R<n>_DEV, R<n>_SO_NOVOS, n≠31) liga o código vivo; R31_DEV/R31_SO_NOVOS (depuração do BLOCO 39) não."""
    return any(re.fullmatch(r"R(\d+)_(DEV|SO_NOVOS)", k) and k[1:3] not in ("31", "32", "33", "34", "35", "36", "37") and v for k, v in os.environ.items())


def r31_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or os.environ.get("R31_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if r31_env_vivo():
        return False
    cg = r31_congelado()
    return cg is not None and nome in cg


def _dormente31(nome, vivo):
    def w(ctx):
        rot = R31_DORMENTES[nome]
        est = ctx.res.setdefault("r31_dorm", {})
        if r31_dormente_ativo(ctx.args, nome):
            cg = r31_congelado()[nome]
            ctx.rep.log(
                f"[R31 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R30 inalterado "
                f"(execução completa, --offline --jobs 8, semente 42; sha256 {R31_CONGELADO_SHA256[:12]}… CONFERE; origem {R31_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes (ou R31_REATIVAR=1)."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            if "rng" in cg:
                ctx.rng.bit_generator.state = copy.deepcopy(cg["rng"])
            if "sinal" in cg:
                ctx.sinal = copy.deepcopy(cg["sinal"])
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r31_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or os.environ.get("R31_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R31 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w


