def r31_versao_nexus() -> str:
    try:
        nx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nexus_lexico.py")
        if os.path.exists(nx):
            m_ = re.search(r'VERSAO\s*=\s*"(\d+)\.(\d+)\.(\d+)"', open(nx, encoding="utf-8").read())
            if m_:
                return "v" + "_".join(m_.groups())
    except OSError:
        pass
    return R31_NEXUS_ESPERADO


def r31_nexus_verificar(pilha: dict, permitido: dict, na_pilha: list, ver: dict):
    """Carrega o nexus_lexico.py vizinho (se existir) e confere: aceita a pilha final e RECUSA uma pilha com o extraordinário (ou meta) quando não-viva. Devolve (ok, texto)."""
    try:
        import importlib.util
        nx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nexus_lexico.py")
        if not os.path.exists(nx):
            return None, "nexus_lexico.py ausente (verificação do companion pulada)"
        spec = importlib.util.spec_from_file_location("nexus_lexico_r31", nx)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        if not hasattr(mod, "verificar_pilha_r31"):
            return False, "nexus sem verificar_pilha_r31"
        ok = mod.verificar_pilha_r31(pilha, permitido, na_pilha, ver)
        bad = mod.verificar_pilha_r31(pilha, permitido, list(na_pilha) + ["extraordinario"], dict(ver, extraordinario="nocivo"))
        return (ok == [] and len(bad) > 0), f"nexus aceita a pilha final ({len(ok)} violações) e recusa a pilha com o extraordinário NOCIVO ({len(bad)} violações)"
    except Exception as e:  # noqa: BLE001
        return False, f"falha ao carregar o nexus: {type(e).__name__}"


