def registro_r31(ctx: Contexto) -> list:
    r = ctx.res.get("r31")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R31 (BLOCO 39) — " + " | ".join(f"{f} {a} conf / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: STK 8, COMP 9, NASH 9)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ/fração={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}")
    for cid, rot, _h, _op in R31_COMPONENTES:
        L.append(f"  veredito {rot}: {r['ev'][cid]}")
    L.append("  pilha resultante: " + ", ".join(f"{k}={v}" for k, v in r["pilha"].items()) + " | " + "; ".join(r["notas"]))
    for k in ("ver_nash31", "ver_mega31", "ver_verif31"):
        L.append(f"  {r[k]}")
    return L


def sumario_r31_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r31")
    if not r or "P" not in r:
        return ["R31: (ainda sem resultados nesta execução)"]
    vs = ", ".join(f"{cid}:{r['ver'][cid]}" for cid, _rot, _h, _op in R31_COMPONENTES)
    return ["R31 BLOCO 39: " + "; ".join(f"{f} {a}/{b}/{c}" for f, (a, b, c) in r["resumo"].items()) + f" | vereditos {vs} | {r['ver_nash31'][:120]} | {r['ver_mega31'][:60]} | {r['ver_verif31'][:70]}"]


def registro_hipoteses_r31(ctx: Contexto) -> list:
    r = ctx.res.get("r31")
    if not r or "P" not in r:
        return []
    desc = r31_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R31", f"R31-{k}", "CONF", desc[k], f"Δ/fração={m:+.4f} d_z={dz:+.2f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    for nome, ch in (("auditoria da pilha (vereditos)", None), ("jogos (Nash analítico)", "ver_nash31"), ("Mega-Sena (regressão)", "ver_mega31"), ("verificador Prolog × vereditos", "ver_verif31")):
        out.append(("R31", f"R31-V[{nome}]", "DESC", f"Veredito: {nome}", (r[ch] if ch else "; ".join(f"{k}:{v}" for k, v in r["ver"].items()) + " | " + "; ".join(r["notas"])), "descritiva"))
    out.append(("R31", "R31-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


