R32_CONGELADO_B64 = "".join(R32_CONGELADO_B64_CHUNKS)

_R32_CONG_CACHE = {"v": None}


def r32_congelado():
    if _R32_CONG_CACHE["v"] is not None:
        return _R32_CONG_CACHE["v"]
    if not R32_CONGELADO_B64 or R32_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R32_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R32_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R32_CONG_CACHE["v"] = v
    return v


def r32_env_vivo() -> bool:
    """Qualquer flag de depuração/bloco novo de OUTRA rodada (R<n>_DEV, R<n>_SO_NOVOS, n≠31) liga o código vivo; R32_DEV/R32_SO_NOVOS (depuração do BLOCO 40) não."""
    return any(re.fullmatch(r"R(\d+)_(DEV|SO_NOVOS)", k) and k[1:3] not in ("31", "32", "33", "34", "35", "36", "37") and v for k, v in os.environ.items())


def r32_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or os.environ.get("R32_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if r32_env_vivo():
        return False
    cg = r32_congelado()
    return cg is not None and nome in cg


def _dormente32(nome, vivo):
    def w(ctx):
        rot = R32_DORMENTES[nome]
        est = ctx.res.setdefault("r32_dorm", {})
        if r32_dormente_ativo(ctx.args, nome):
            cg = r32_congelado()[nome]
            ctx.rep.log(
                f"[R32 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R31 inalterado "
                f"(execução completa, --offline --jobs 8, semente 42; sha256 {R32_CONGELADO_SHA256[:12]}… CONFERE; origem {R32_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes (ou R32_REATIVAR=1)."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            if "rng" in cg:
                ctx.rng.bit_generator.state = copy.deepcopy(cg["rng"])
            if "sinal" in cg:
                ctx.sinal = copy.deepcopy(cg["sinal"])
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r32_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or os.environ.get("R32_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R32 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w


# ======================================================================
# [R32] NÚCLEO + ORQUESTRAÇÃO DO BLOCO 40 (replicação da pilha, candidatos dentro da pilha, predição seletiva, regressão Mega/Nash/Prolog, mapa)
# ======================================================================
# -*- coding: utf-8 -*-
# [R32] NÚCLEO DO BLOCO 40 — (a) replicação da pilha (alocação k, filtro, GRPO, meta normalizada), (b) candidatos DENTRO da pilha sem atalho (EWC/replay em fluxo não estacionário,
#       dedup no portão, dedup semântico sem marcador), (c) predição seletiva com confiança metacognitiva, (d) regressão (Mega, Nash, Prolog).
# Depende de: np, zlib, os, math, copy (R25: r25_*; R27: r27_*; R28: r28_*; R29: r29_*; R30: r30_*; R31: r31_*), holm.

PREREG_R32_CORPO_SHA256 = "a6081d5f9452cfeefd34e97cee4225f77aaf2dbdb9e9fad2de32414ce872e6f6"

