def r32_desloc() -> int:
    v = os.environ.get("R32_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r32_crc(rot: str) -> int:
    return zlib.crc32(f"R32|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r32_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R32_SEEDS.items()}


# ---------------------------------------------------------------------------
# PARTE A — replicação da pilha
# ---------------------------------------------------------------------------
def r32_aval_dedup(tz, pol, seed: int, rot: str, k: int = 4, cap: int = 32):
    """Portão com/sem dedup (cache de candidatos) a orçamento IGUAL de chamadas ao verificador (k). Mesmos sorteios nos dois braços (RNG por consulta)."""
    cs, cd, nd = [], [], []
    for i in range(R25_N_EVAL):
        rng = r25_rng(seed, r25_crc(f"dd|{tz.nome}|{rot}"), 1000 + i)
        draws = []

        def get(n):
            while len(draws) <= n:
                draws.append([int(x) for x in tz.sample(pol, rng)[0]])
            return draws[n]
        b_ids, b_key = None, None
        for j in range(k):
            ids = get(j)
            lau = tz.laudo(ids, seed, 5000 + i * 10 + j)
            key = (1 if lau["passa_tela"] else 0, lau["score_laudo"])
            if b_key is None or key > b_key:
                b_ids, b_key = ids, key
        cs.append(tz.r_clean(b_ids))
        seen, nv, n = set(), 0, 0
        d_ids, d_key = None, None
        while nv < k and n < cap:
            ids = get(n)
            n += 1
            tup = tuple(ids)
            if tup in seen:
                continue
            seen.add(tup)
            lau = tz.laudo(ids, seed, 5000 + i * 10 + nv)
            key = (1 if lau["passa_tela"] else 0, lau["score_laudo"])
            nv += 1
            if d_key is None or key > d_key:
                d_ids, d_key = ids, key
        cd.append(tz.r_clean(d_ids))
        nd.append(n)
    return {"base": float(np.mean(cs)), "dedup": float(np.mean(cd)), "sorteios": float(np.mean(nd))}


def r32_job_stk(task):
    """task = ('RSTK', tarefa, seed, dev). DEV: Pf, Pr, aleatório (normalização). TESTE: Pf, Pr (só LEVE/OFF), S0 (sem RL), MN, e o portão com/sem dedup (tarefas com portão)."""
    _, tn, seed, dev = task
    tz = r28_tarefa(tn)
    lr = R28_LR_TRAVADO[tn]
    modo = R32_MODO_TAREFA[tn]
    ev = lambda pol: {k: float(v[0]) for k, v in r27_avaliar_aninhado(tz, pol, seed, "R32|eval", 8).items()}
    out = {"tarefa": tn, "seed": int(seed)}
    pf = r25_treinar(tz, r27_cfg_pf(), seed, lr)["pol"]
    out["Pf"] = ev(pf)
    if dev:
        out["Pr"] = ev(r25_treinar(tz, r27_cfg_pr(), seed, lr)["pol"])
        out["aleat"] = float(r25_avaliar(tz, R25_CFG["aleat"], {"pol": None}, seed, f"{tn}|aleat")["r_clean"])
        return out
    if modo == "ON":
        pdef = pf
        out["Pr"] = None
    else:
        pdef = r25_treinar(tz, r27_cfg_pr(), seed, lr)["pol"]
        out["Pr"] = ev(pdef)
    out["S0"] = ev(r25_treinar(tz, r31_cfg_s0(), seed, lr)["pol"])
    out["MN"] = ev(r25_treinar(tz, r27_cfg_pm(modo), seed, lr)["pol"])
    if modo != "OFF":
        out["DD"] = r32_aval_dedup(tz, pdef, seed, "R32|dd", 4)
    return out


def r32_pol_def(ent: dict, tn: str):
    return ent["Pf"] if R32_MODO_TAREFA[tn] == "ON" else ent["Pr"]


def r32_scores_stk(ent: dict, tn: str, A: dict, DEN: dict, kal: dict):
    n = lambda x: (float(x) - A[tn]) / DEN[tn]
    kd = r31_kdef(R32_MODO_TAREFA[tn])
    dp = r32_pol_def(ent, tn)
    out = {"DEF": n(dp[kd]), "SEM_RL": n(ent["S0"][kd]), "SEM_PORTA": n(dp[1]), "FIXO": n(ent["Pf"][4]), "O_MN": n(ent["MN"][kd]), "O_KA": n(dp[kal[tn]])}
    if "DD" in ent:
        out["DD_BASE"] = n(ent["DD"]["base"])
        out["DD_DEDUP"] = n(ent["DD"]["dedup"])
    return out


def r32_job_rl(task):
    """task = ('RLR', modo, tarefa, seed, lr, hp). r_clean em k=1 e k=4 com rótulo de avaliação COMUM aos dois braços."""
    _, modo, tn, seed, lr, hp = task
    tz = r28_tarefa(tn)
    tr = r29_rl_treinar(tz, seed, lr, modo, hp)
    ev = r27_avaliar_aninhado(tz, tr["pol"], seed, "R32|rl", 4)
    return {"k1": float(ev[1][0]), "k4": float(ev[4][0]), "modo": modo, "tarefa": tn, "seed": int(seed)}


def r32_consistente(d) -> bool:
    d = np.asarray(d, float)
    n = len(d)
    h = n // 2
    if h < 1:
        return False
    a, b, t = float(d[:h].mean()), float(d[n - h:].mean()), float(d.mean())
    return bool(a * b > 0 and t * a > 0)


# ---------------------------------------------------------------------------
# PARTE B1 — fluxo não estacionário: EWC e replay dentro da pilha
# ---------------------------------------------------------------------------
class R32SymRegra(R27Sym):
    """Tarefa simbólica V=7 com regra x_t = (c1·x_{t−1} + c2·x_{t−2}) mod 7 (laudo, recompensa e r_clean seguem a regra)."""

    def __init__(self, c1: int, c2: int):
        super().__init__(R28_PRM_SYM["Z7"])
        self.c1, self.c2 = int(c1), int(c2)
        self.nome = f"Z7r{self.c1}{self.c2}"

    def _ok(self, ids):
        V = self.V
        return np.asarray([1.0 if ids[t] == (self.c1 * ids[t - 1] + self.c2 * ids[t - 2]) % V else 0.0 for t in range(2, len(ids))])


def r32_passos(tz, pol, seed_l: int, rng, t0: int, n: int, lr: float, base: float, pen=None):
    """n atualizações do RL ordinário da pilha (recompensa do filtro: score do laudo + ruído do verificador); pen = (W_A, F, λ) aplica a penalidade EWC após cada atualização."""
    for t in range(t0, t0 + n):
        seqs, rs = [], []
        for b in range(tz.batch):
            ids, tr = tz.sample(pol, rng)
            lau = tz.laudo(ids, seed_l, t * tz.batch + b)
            rs.append(float(lau["score_laudo"]) + tz.ruido(ids, seed_l, t * tz.batch + b))
            seqs.append((ids, tr))
        rm = float(np.mean(rs))
        advs = [r - base for r in rs]
        base = 0.9 * base + 0.1 * rm
        tz.update(pol, seqs, advs, lr, False, [1.0] * len(seqs))
        if pen is not None:
            WA, F, lam = pen
            pol["W"] -= np.minimum(1.0, lr * lam * F) * (pol["W"] - WA)
    return base


def r32_fisher(tz, pol, seed: int, n: int = 64):
    """Fisher diagonal empírica dos logits da política de A MISTURADA com 20% de uniforme: F[s,k] = visitas esperadas ao estado s por sequência × p_mix(1−p_mix)."""
    rng = r25_rng(seed, r32_crc("fisher"), 3)
    V = tz.V
    F = np.zeros_like(pol["W"])
    for _ in range(n):
        ids = []
        for t in range(tz.L):
            s = tz._state(ids, t)
            z = pol["W"][s]
            p = np.exp(z - z.max())
            p = p / p.sum()
            pm = 0.8 * p + 0.2 / V
            F[s] += pm * (1.0 - pm)
            x = int(min(np.searchsorted(np.cumsum(pm), float(rng.random()), side="right"), V - 1))
            ids.append(x)
    return F / n


def r32_acc(tz, pol, seed: int, rot: str) -> float:
    return float(r25_avaliar(tz, r27_cfg_pf(), {"pol": pol}, seed, rot)["r_clean"])


def r32_esq_troca(seed: int, troca, lams, P: int = 200, lr: float = 3.0):
    cA1, cA2, cB1, cB2 = troca
    tzA, tzB = R32SymRegra(cA1, cA2), R32SymRegra(cB1, cB2)
    tag = f"{cA1}{cA2}{cB1}{cB2}"
    rngA = r25_rng(seed, r32_crc("cont|A|" + tag), 1)
    pol = tzA.init_pol(rngA)
    base = r32_passos(tzA, pol, seed, rngA, 0, P, lr, 0.0)
    a_apos_A = r32_acc(tzA, pol, seed, "R32|A")
    F = r32_fisher(tzA, pol, seed)
    WA = pol["W"].copy()
    out = {}
    arms = [("NADA", None)] + [("REPLAY", None)] + [(f"EWC@{lam:g}", lam) for lam in lams]
    for nome, lam in arms:
        p2 = {"W": WA.copy(), "V": pol["V"]}
        rng = r25_rng(seed, r32_crc("cont|B|" + tag), 2)
        b0 = base
        if nome == "REPLAY":
            rngr = r25_rng(seed, r32_crc("cont|R|" + tag), 4)
            bA = base
            half = P // 2
            for blk in range(half):
                b0 = r32_passos(tzB, p2, seed + 1000003, rng, blk, 1, lr, b0)
                bA = r32_passos(tzA, p2, seed + 2000003, rngr, blk, 1, lr, bA)
        elif lam is not None:
            r32_passos(tzB, p2, seed + 1000003, rng, 0, P, lr, b0, pen=(WA, F, lam))
        else:
            r32_passos(tzB, p2, seed + 1000003, rng, 0, P, lr, b0)
        a, b = r32_acc(tzA, p2, seed, "R32|A"), r32_acc(tzB, p2, seed, "R32|B")
        out[nome] = {"acc": 0.5 * (a + b), "A": a, "B": b, "forget": a_apos_A - a}
    return out


def r32_job_esq(task):
    """task = ('ESQ2', seed, lams) → média sobre as 2 trocas de regra de {braço: {acc, A, B, forget}}."""
    _, seed, lams = task
    rs = [r32_esq_troca(seed, tr, lams) for tr in R32_TROCAS]
    return {k: {m: float(np.mean([r[k][m] for r in rs])) for m in ("acc", "A", "B", "forget")} for k in rs[0]}


# ---------------------------------------------------------------------------
# PARTE B3 — memória: dedup semântico sem marcador de citação
# ---------------------------------------------------------------------------
def r32_mem_loja(ev, vec, theta: float):
    """Loja deduplicada: aglomerados por entidade (single-link pelo cosseno máximo ≥ θ); guarda os 2 eventos mais recentes por aglomerado. Devolve (pool, nº de comparações)."""
    cl_por_ent = {}
    ncmp = 0
    for e in ev:
        cls = cl_por_ent.setdefault(e["ent"], [])
        best, bs = None, -2.0
        for c in cls:
            for w in c["words"]:
                sc = _r29_cos(vec[w], vec[e["w"]])
                ncmp += 1
                if sc > bs:
                    best, bs = c, sc
        if best is not None and bs >= theta - 1e-12:
            best["ev"].append(e)
            best["ev"] = best["ev"][-2:]
            if e["w"] not in best["words"]:
                best["words"].append(e["w"])
        else:
            cls.append({"words": [e["w"]], "ev": [e]})
    pool = []
    for ent in sorted(cl_por_ent):
        for c in cl_por_ent[ent]:
            es = sorted(c["ev"], key=lambda x: x["t"])
            for i, e in enumerate(es):
                pool.append(dict(e, status=("vigente" if i == len(es) - 1 else "anterior")))
    return pool, ncmp


def r32_mem_run(seed: int, payload: dict, thetas):
    W = r29_mem_mundo(seed, payload)
    ev, vec, attrs = W["eventos"], payload["vec"], payload["attrs"]
    pools = {th: r32_mem_loja(ev, vec, th) for th in thetas}
    acc = {"A1": [], "A2": []}
    for th in thetas:
        acc[f"S|{th:g}"] = []
    for qi, ((s, tipo), lang) in enumerate(zip(W["cons"], W["langs"])):
        w_q = attrs[s[1]][lang]
        verd = W["atual"][s] if tipo == "vig" else W["hist"][s][-2][1]
        r_q = r25_rng(seed, r32_crc("mem|q"), 100 + qi)
        c1, _n1 = _r29_topk(ev, s[0], w_q, s[1], False, vec, 6, r_q)
        resp = r29_mem_ler(c1, s[0], w_q, s[1], tipo, False, vec, r25_rng(seed, r32_crc("mem|l1"), 200 + qi))
        acc["A1"].append(1.0 if resp == verd else 0.0)
        r_q2 = r25_rng(seed, r32_crc("mem|q"), 100 + qi)
        c2, _n2 = _r29_topk(ev, s[0], w_q, s[1], True, vec, 6, r_q2)
        resp = r29_mem_ler(c2, s[0], w_q, s[1], tipo, True, vec, r25_rng(seed, r32_crc("mem|l2"), 200 + qi))
        acc["A2"].append(1.0 if resp == verd else 0.0)
        for th in thetas:
            r_q3 = r25_rng(seed, r32_crc("mem|q"), 100 + qi)
            c3, _n3 = _r29_topk(pools[th][0], s[0], w_q, s[1], False, vec, 6, r_q3)
            resp = r29_mem_ler(c3, s[0], w_q, s[1], tipo, False, vec, r25_rng(seed, r32_crc("mem|l5"), 200 + qi))
            acc[f"S|{th:g}"].append(1.0 if resp == verd else 0.0)
    out = {k: float(np.mean(v)) for k, v in acc.items()}
    out["ncmp"] = {f"{th:g}": int(pools[th][1]) for th in thetas}
    out["loja"] = {f"{th:g}": int(len(pools[th][0])) for th in thetas}
    return out


def r32_job_mem(task):
    _, seed, payload, thetas = task
    return r32_mem_run(seed, payload, thetas)


# ---------------------------------------------------------------------------
# PARTE C — predição seletiva com confiança metacognitiva
# ---------------------------------------------------------------------------
def r32_sel_dados(seed: int):
    rng = r25_rng(seed, r32_crc("sel|dados"), 1)
    d, K = 10, 3
    mu = rng.normal(0.0, 0.9, size=(K, d))
    v = rng.normal(size=d)
    v = v / np.linalg.norm(v)

    def gerar(n, desl):
        y = rng.integers(0, K, size=n)
        eps = rng.normal(size=(n, d))
        x = mu[y] + (2.4 if desl else 1.6) * eps + (1.5 * v if desl else 0.0)
        flip = rng.random(n) < 0.04
        yl = np.where(flip, (y + rng.integers(1, K, size=n)) % K, y)
        return x, yl.astype(int)
    return {"tr": gerar(240, False), "cal": gerar(300, False), "id": gerar(500, False), "sh": gerar(500, True)}


def _r32_softmax(Z):
    Z = Z - Z.max(axis=-1, keepdims=True)
    E = np.exp(Z)
    return E / E.sum(axis=-1, keepdims=True)


def r32_mlp_fit(X, y, rng, h: int = 16, K: int = 3, passos: int = 200, lr: float = 0.2, wd: float = 1e-3):
    n, d = X.shape
    W1, b1 = rng.normal(0.0, 1.0 / math.sqrt(d), size=(d, h)), np.zeros(h)
    W2, b2 = rng.normal(0.0, 1.0 / math.sqrt(h), size=(h, K)), np.zeros(K)
    Y = np.eye(K)[y]
    for _ in range(passos):
        H = np.tanh(X @ W1 + b1)
        P = _r32_softmax(H @ W2 + b2)
        dZ = (P - Y) / n
        gW2, gb2 = H.T @ dZ + wd * W2, dZ.sum(axis=0)
        dH = (dZ @ W2.T) * (1.0 - H * H)
        gW1, gb1 = X.T @ dH + wd * W1, dH.sum(axis=0)
        W1 -= lr * gW1; b1 -= lr * gb1; W2 -= lr * gW2; b2 -= lr * gb2
    return (W1, b1, W2, b2)


def _r32_mlp_prob(m, X):
    W1, b1, W2, b2 = m
    return _r32_softmax(np.tanh(X @ W1 + b1) @ W2 + b2)


def r32_sel_sinais(modelos, X, mu_tr, sd_tr):
    Xs = (X - mu_tr) / sd_tr
    Ps = np.stack([_r32_mlp_prob(m, Xs) for m in modelos])
    Pm = Ps.mean(axis=0)
    Hm = -(Pm * np.log(Pm + 1e-12)).sum(axis=1)
    Hi = (-(Ps * np.log(Ps + 1e-12)).sum(axis=2)).mean(axis=0)
    MI = Hm - Hi
    srt = np.sort(Pm, axis=1)
    margem = srt[:, -1] - srt[:, -2]
    nov = np.sqrt((Xs ** 2).mean(axis=1))
    c_ens = Pm.max(axis=1)
    return {"pred": Pm.argmax(axis=1), "Pm": Pm, "c_sm": Ps[0].max(axis=1), "c_ens": c_ens, "c_dis": -MI, "feats": np.c_[c_ens, margem, MI, Hm, nov]}


def r32_logit_ridge(F, y, lam: float = 0.01, its: int = 25):
    n, d = F.shape
    A = np.c_[np.ones(n), F]
    w = np.zeros(d + 1)
    R = lam * np.eye(d + 1)
    R[0, 0] = 0.0
    for _ in range(its):
        p = 1.0 / (1.0 + np.exp(-np.clip(A @ w, -30, 30)))
        g = A.T @ (p - y) + R @ w
        Hs = (A * (p * (1 - p))[:, None]).T @ A + R + 1e-9 * np.eye(d + 1)
        w = w - np.linalg.solve(Hs, g)
    return w


def r32_logit_pred(w, F):
    return 1.0 / (1.0 + np.exp(-np.clip(np.c_[np.ones(len(F)), F] @ w, -30, 30)))


def r32_aurc(conf, ok) -> float:
    o = np.argsort(-np.asarray(conf, float), kind="stable")
    e = 1.0 - np.asarray(ok, float)[o]
    return float(np.mean(np.cumsum(e) / np.arange(1, len(e) + 1)))


def r32_ece(p, ok, bins: int = 10) -> float:
    p, ok = np.asarray(p, float), np.asarray(ok, float)
    ix = np.minimum((p * bins).astype(int), bins - 1)
    e = 0.0
    for b in range(bins):
        m = ix == b
        if m.any():
            e += m.mean() * abs(float(ok[m].mean()) - float(p[m].mean()))
    return float(e)


def r32_util(p, ok, thr: float = 2.0 / 3.0) -> float:
    ans = np.asarray(p, float) >= thr - 1e-12
    return float(np.mean(np.where(ans, np.where(np.asarray(ok, bool), 1.0, -2.0), 0.0)))


def r32_risco_cob(conf, ok, c: float) -> float:
    o = np.argsort(-np.asarray(conf, float), kind="stable")
    m = max(1, int(math.ceil(c * len(o))))
    return float(1.0 - np.asarray(ok, float)[o][:m].mean())


def r32_job_sel(task):
    """task = ('SEL', seed). Devolve as métricas no TESTE-DESLOCADO e no TESTE-ID (todas as quantidades dos hipóteses S1–S6 + descritivos)."""
    _, seed = task
    D = r32_sel_dados(seed)
    Xtr, ytr = D["tr"]
    mu_tr, sd_tr = Xtr.mean(axis=0), Xtr.std(axis=0) + 1e-9
    rng = r25_rng(seed, r32_crc("sel|modelos"), 2)
    mods = []
    for _ in range(5):
        ix = rng.integers(0, len(ytr), size=len(ytr))
        mods.append(r32_mlp_fit((Xtr[ix] - mu_tr) / sd_tr, ytr[ix], rng))
    sc = {k: r32_sel_sinais(mods, D[k][0], mu_tr, sd_tr) for k in ("cal", "id", "sh")}
    ok = {k: (sc[k]["pred"] == D[k][1]).astype(float) for k in sc}
    w = None
    Fc = sc["cal"]["feats"]
    fm, fs = Fc.mean(axis=0), Fc.std(axis=0) + 1e-9
    w = r32_logit_ridge((Fc - fm) / fs, ok["cal"])
    pm = {k: r32_logit_pred(w, (sc[k]["feats"] - fm) / fs) for k in sc}
    # temperatura na CALIBRAÇÃO (log-verossimilhança negativa do rótulo verdadeiro)
    ycal = D["cal"][1]
    Ts = [round(0.5 + 0.1 * i, 1) for i in range(26)]
    nll = []
    for T in Ts:
        Pt = _r32_softmax(np.log(sc["cal"]["Pm"] + 1e-12) / T)
        nll.append(float(-np.mean(np.log(Pt[np.arange(len(ycal)), ycal] + 1e-12))))
    Tb = Ts[int(np.argmin(nll))]
    pt = {k: _r32_softmax(np.log(sc[k]["Pm"] + 1e-12) / Tb).max(axis=1) for k in sc}
    o = {"T": Tb, "acc_id": float(ok["id"].mean()), "acc_sh": float(ok["sh"].mean())}
    for sinal, conf in (("sm", sc["sh"]["c_sm"]), ("ens", sc["sh"]["c_ens"]), ("dis", sc["sh"]["c_dis"]), ("meta", pm["sh"]), ("temp", pt["sh"])):
        o["aurc_" + sinal] = r32_aurc(conf, ok["sh"])
    o["aurc_rand"] = float(1.0 - ok["sh"].mean())
    o["ece_meta"], o["ece_temp"] = r32_ece(pm["sh"], ok["sh"]), r32_ece(pt["sh"], ok["sh"])
    o["u_meta"], o["u_temp"], o["u_always"] = r32_util(pm["sh"], ok["sh"]), r32_util(pt["sh"], ok["sh"]), float(np.mean(np.where(ok["sh"] > 0, 1.0, -2.0)))
    o["abst_meta_sh"] = float(1.0 - np.mean(pm["sh"] >= 2.0 / 3.0 - 1e-12))
    o["abst_meta_id"] = float(1.0 - np.mean(pm["id"] >= 2.0 / 3.0 - 1e-12))
    o["risco50_meta"], o["risco80_meta"] = r32_risco_cob(pm["sh"], ok["sh"], 0.5), r32_risco_cob(pm["sh"], ok["sh"], 0.8)
    o["risco50_ens"], o["risco80_ens"] = r32_risco_cob(sc["sh"]["c_ens"], ok["sh"], 0.5), r32_risco_cob(sc["sh"]["c_ens"], ok["sh"], 0.8)
    o["discorda"] = float(np.mean((pm["sh"] >= 2.0 / 3.0 - 1e-12) != (pt["sh"] >= 2.0 / 3.0 - 1e-12)))
    return o


# ---------------------------------------------------------------------------
# despacho
# ---------------------------------------------------------------------------
def r32_job(task):
    k = task[0]
    if k == "RSTK":
        return r32_job_stk(task)
    if k == "RLR":
        return r32_job_rl(task)
    if k == "ESQ2":
        return r32_job_esq(task)
    if k == "MEM2":
        return r32_job_mem(task)
    if k == "SEL":
        return r32_job_sel(task)
    return r31_job(task)


# ---------------------------------------------------------------------------
# vereditos e pilha (regras E1–E4 e B do prereg; mecânicas)
# ---------------------------------------------------------------------------
def r32_vereditos(st: dict, cons: dict) -> dict:
    trio = lambda h: "vivo" if st[h] == "confirmada" else ("nocivo" if st[h] == "refutada" else "decorativo")
    adot = lambda h: "vivo" if (st[h] == "confirmada" and cons[h]) else ("nocivo" if st[h] == "refutada" else "decorativo")
    v = {"rl_ordinario": trio("RP_RL"), "porta_k": trio("RP_GATE"), "filtro_adaptativo": trio("RP_FILT"), "porta_k_alocada": adot("RP_KA"), "meta_norm": adot("RP_MN")}
    g = (st["RP_GRPO"], st["RP_GRPO4"])
    v["grpo"] = "nocivo" if any(s == "refutada" for s in g) else ("vivo" if (all(s == "confirmada" for s in g) and cons["RP_GRPO"] and cons["RP_GRPO4"]) else "decorativo")
    e = (st["CS1"], st["CS3"])
    v["ewc"] = "nocivo" if any(s == "refutada" for s in e) else ("vivo" if all(s == "confirmada" for s in e) else "decorativo")
    d = (st["CS4"], st["CS5"])
    v["dedup_online"] = "nocivo" if any(s == "refutada" for s in d) else ("vivo" if all(s == "confirmada" for s in d) else "decorativo")
    return v


def r32_pilha_resultante(ver: dict, fixo: str = "ON") -> tuple:
    notas = []
    pil = {"rl": "ordinario", "gate": R25_K_GATE, "filtro": "adaptativo", "meta": "nenhum", "extra": "nao"}
    if ver["grpo"] == "vivo":
        pil["rl"] = "grpo"; notas.append("E4: GRPO VIVO (RP_GRPO e RP_GRPO4 confirmadas e consistentes) → ENTRA no lugar do RL ordinário (provisório)")
    elif ver["rl_ordinario"] != "vivo":
        pil["rl"] = "nenhum"; notas.append(f"E1: RL ordinário {ver['rl_ordinario'].upper()} → REMOVIDO")
    if ver["porta_k"] != "vivo":
        pil["gate"] = 1; notas.append(f"E1: porta k=4 {ver['porta_k'].upper()} → REMOVIDA (k=1)")
    if ver["filtro_adaptativo"] != "vivo":
        pil["filtro"] = "fixo_" + fixo.lower(); notas.append(f"E1: filtro adaptativo {ver['filtro_adaptativo'].upper()} → REMOVIDO (modo fixo {fixo})")
    if ver["meta_norm"] == "vivo":
        pil["meta"] = "norm"; notas.append("E3: meta normalizada VIVA (confirmada e consistente) → ADOTADA (provisória)")
    if ver["porta_k_alocada"] == "vivo":
        pil["k_alocada"] = "sim"; notas.append("E2: porta k ALOCADA confirmada e consistente → ADOTADA DEFINITIVAMENTE (alocação congelada da R31)")
    else:
        notas.append(f"E2: porta k ALOCADA {ver['porta_k_alocada'].upper()} (não replicou) → RETIRADA: a pilha volta a k=4 fixo")
    if ver["ewc"] == "vivo":
        pil["ewc"] = "sim"; notas.append("B: EWC VIVO dentro da pilha (CS1 e CS3 confirmadas) → ENTRA no modo de fluxo não estacionário (provisório)")
    if ver["dedup_online"] == "vivo":
        pil["dedup"] = "sim"; notas.append("B: dedup online VIVA dentro da pilha (CS4 e CS5 confirmadas) → ENTRA no portão e na memória (provisório)")
    if ver["ewc"] != "vivo" and ver["dedup_online"] != "vivo":
        notas.append(f"B: EWC {ver['ewc'].upper()} e dedup online {ver['dedup_online'].upper()} dentro da pilha → ficam FORA")
    return pil, notas


def r32_permitido(ver: dict, fixo: str = "ON") -> dict:
    """Derivação INDEPENDENTE (por campo) da pilha permitida."""
    per = {"rl": ("grpo" if ver["grpo"] == "vivo" else ("ordinario" if ver["rl_ordinario"] == "vivo" else "nenhum")),
           "gate": R25_K_GATE if ver["porta_k"] == "vivo" else 1, "filtro": "adaptativo" if ver["filtro_adaptativo"] == "vivo" else "fixo_" + fixo.lower(),
           "meta": "norm" if ver["meta_norm"] == "vivo" else "nenhum", "extra": "nao"}
    if ver["porta_k_alocada"] == "vivo":
        per["k_alocada"] = "sim"
    if ver["ewc"] == "vivo":
        per["ewc"] = "sim"
    if ver["dedup_online"] == "vivo":
        per["dedup"] = "sim"
    return per


def r32_na_pilha(pil: dict) -> list:
    na = []
    if pil["rl"] == "ordinario":
        na.append("rl_ordinario")
    if pil["rl"] == "grpo":
        na.append("grpo")
    if pil["gate"] != 1:
        na.append("porta_k")
    if pil["filtro"] == "adaptativo":
        na.append("filtro_adaptativo")
    if pil["meta"] == "norm":
        na.append("meta_norm")
    if pil.get("k_alocada") == "sim":
        na.append("porta_k_alocada")
    if pil.get("ewc") == "sim":
        na.append("ewc")
    if pil.get("dedup") == "sim":
        na.append("dedup_online")
    return na


def r32_bc(linhas_mapa, st_hip, pilha, permitido, custo, versao, esperada, ver, status_nash, alega):
    bc = r31_bc(linhas_mapa, st_hip, pilha, permitido, custo, versao, esperada, ver, status_nash, alega)
    bc["na_pilha"] = r32_na_pilha(pilha)
    for c in bc["na_pilha"]:
        bc["estado"].setdefault(c, ["ativo"])
        bc["evidencia"] = sorted(set(bc["evidencia"]) | {c})
    bc["opcional"] = sorted(set(bc["opcional"]) | set(R32_OPCIONAIS_EXTRA))
    bc["avaliado"] = sorted(ver)
    return bc


def r32_mutar(bc: dict, tipo: int, rng):
    """Mutante da BC. Correção mecânica (Adendo 1): o mutante «rl_diferente» herdado da R28 sorteia entre extraordinario/grpo/nenhum e viraria NÃO-mutante quando o GRPO é a pilha permitida; aqui nunca devolve o RL original."""
    b, t = r31_mutar(bc, tipo, rng)
    if t == "rl_diferente" and b["stack"].get("rl") == bc["stack"].get("rl"):
        c = [x for x in ("extraordinario", "grpo", "nenhum", "ordinario") if x != bc["stack"]["rl"]]
        b["stack"]["rl"] = c[int(rng.integers(0, len(c)))]
    return b, t


def r32_validar_verificador(bc: dict, n_mut: int, n_ctl: int, seeds_mut, seeds_ctl):
    det, conc, tipos, fa = 0, 0, {}, 0
    for i in range(n_mut):
        rng = r25_rng(seeds_mut[i], r31_crc("mut"), i)
        bm, tp = r32_mutar(bc, i, rng)
        vp, vy = r31_checar_prolog(r31_bc_texto(bm)), r31_checar_py(bm)
        det += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
        tipos.setdefault(tp, [0, 0]); tipos[tp][0] += 1; tipos[tp][1] += 1 if vp else 0
    for i in range(n_ctl):
        rng = r25_rng(seeds_ctl[i], r31_crc("ctl"), i)
        vp, vy = r31_checar_prolog(r31_bc_texto(bc, rng, benigno=True)), r31_checar_py(bc)
        fa += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
    return {"detectados": det, "n_mut": n_mut, "falsos_alarmes": fa, "n_ctl": n_ctl, "concordancia": conc, "n_total": n_mut + n_ctl, "tipos": tipos}


