def registro_r32(ctx: Contexto) -> list:
    r = ctx.res.get("r32")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R32 (BLOCO 40) — " + " | ".join(f"{f} {a} conf / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: REP 7, CAND 5, SEL 6; regressão NASH 9)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}" + (" (consistente entre metades)" if r["cons"].get(h) else ""))
    for cid in R32_COMP_NOVOS:
        L.append(f"  veredito {cid}: {r['ev_novos'][cid]}")
    L.append("  pilha resultante: " + ", ".join(f"{k}={v}" for k, v in r["pilha"].items()) + " | " + "; ".join(r["notas"]))
    for k in ("ver_nash31", "ver_mega31", "ver_verif31", "ver_sel32"):
        L.append(f"  {r[k]}")
    return L


def sumario_r32_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r32")
    if not r or "P" not in r:
        return ["R32: (ainda sem resultados nesta execução)"]
    vs = ", ".join(f"{cid}:{r['ver_novos'][cid]}" for cid in R32_COMP_NOVOS)
    return ["R32 BLOCO 40: " + "; ".join(f"{f} {a}/{b}/{c}" for f, (a, b, c) in r["resumo"].items()) + f" | vereditos {vs} | {r['ver_nash31'][:100]} | {r['ver_mega31'][:60]} | {r['ver_verif31'][:70]}"]


def registro_hipoteses_r32(ctx: Contexto) -> list:
    r = ctx.res.get("r32")
    if not r or "P" not in r:
        return []
    desc = r32_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R32", f"R32-{k}", "CONF", desc[k], f"Δ={m:+.4f} d_z={dz:+.2f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} MDE={mde:.4f}", r["st"][k]))
    for nome, ch in (("replicação + candidatos (vereditos)", None), ("predição seletiva", "ver_sel32"), ("jogos (Nash analítico, regressão)", "ver_nash31"), ("Mega-Sena (regressão)", "ver_mega31"), ("verificador Prolog × vereditos", "ver_verif31")):
        out.append(("R32", f"R32-V[{nome}]", "DESC", f"Veredito: {nome}", (r[ch] if ch else "; ".join(f"{k}:{v}" for k, v in r["ver_novos"].items()) + " | " + "; ".join(r["notas"])), "descritiva"))
    out.append(("R32", "R32-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


def secao_mudancas_r32(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("O QUE MUDOU NA RODADA 32 (calculado desta execução)")
