R33_CONGELADO_B64 = "".join(R33_CONGELADO_B64_CHUNKS)

_R33_CONG_CACHE = {"v": None}


def r33_congelado():
    if _R33_CONG_CACHE["v"] is not None:
        return _R33_CONG_CACHE["v"]
    if not R33_CONGELADO_B64 or R33_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R33_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R33_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R33_CONG_CACHE["v"] = v
    return v


def r33_env_vivo() -> bool:
    """Qualquer flag de depuração/bloco novo de OUTRA rodada (R<n>_DEV, R<n>_SO_NOVOS, n≠33) liga o código vivo; R33_DEV/R33_SO_NOVOS (depuração do BLOCO 41) não. R32_DEV/R32_SO_NOVOS (depuração do BLOCO 40) LIGAM o código vivo do 40."""
    return any(re.fullmatch(r"R(\d+)_(DEV|SO_NOVOS)", k) and k[1:3] not in ("33", "34", "35", "36", "37") and v for k, v in os.environ.items())


def r33_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or os.environ.get("R33_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if r33_env_vivo():
        return False
    cg = r33_congelado()
    return cg is not None and nome in cg


def _dormente33(nome, vivo):
    def w(ctx):
        rot = R33_DORMENTES[nome]
        est = ctx.res.setdefault("r33_dorm", {})
        if r33_dormente_ativo(ctx.args, nome):
            cg = r33_congelado()[nome]
            ctx.rep.log(
                f"[R33 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R32 inalterado "
                f"(execução completa, --offline --jobs 8, semente 42; sha256 {R33_CONGELADO_SHA256[:12]}… CONFERE; origem {R33_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes (ou R33_REATIVAR=1)."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            if "rng" in cg:
                ctx.rng.bit_generator.state = copy.deepcopy(cg["rng"])
            if "sinal" in cg:
                ctx.sinal = copy.deepcopy(cg["sinal"])
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r33_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or os.environ.get("R33_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R33 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w


