def r33_desloc() -> int:
    v = os.environ.get("R33_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r33_crc(rot: str) -> int:
    return zlib.crc32(f"R33|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r33_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R33_SEEDS.items()}


# ---------------------------------------------------------------------------
# Tarefas
# ---------------------------------------------------------------------------
class R33Sym(R27Sym):
    """Tarefa simbólica com regra x_t = (c1·x_{t−1} + c2·x_{t−2}) mod V (V, c1, c2 por tarefa); L=12, B=8, P=200, tau_y=0,5."""

    def __init__(self, nome: str, V: int, c1: int, c2: int):
        super().__init__({"V": int(V), "L": 12, "B": 8, "P": 200, "tau_y": 0.50})
        self.c1, self.c2 = int(c1), int(c2)
        self.nome = nome

    def _ok(self, ids):
        V = self.V
        return np.asarray([1.0 if ids[t] == (self.c1 * ids[t - 1] + self.c2 * ids[t - 2]) % V else 0.0 for t in range(2, len(ids))])


def r33_tarefa(nome: str):
    if nome in R33_PRM_Z:
        V, c1, c2 = R33_PRM_Z[nome]
        return R33Sym(nome, V, c1, c2)
    if nome in R33_PRM_H:
        p = R33_PRM_H[nome]
        return R27Hard(nome, p["V"], p["L"], p["seed_lex"], p["P"])
    return r28_tarefa(nome)


def r33_cfg(tn: str):
    return r27_cfg_pf() if R33_MODO[tn] == "ON" else r27_cfg_pr()


def r33_seed_lex(tn: str) -> int:
    return int(R33_PRM_H[tn]["seed_lex"] if tn in R33_PRM_H else R28_PRM_HARD[tn]["seed_lex"])


# ---------------------------------------------------------------------------
# Treinadores
# ---------------------------------------------------------------------------
def r33_recompensa(tz, ids, modo: str, seed: int, idx: int) -> float:
    lau = tz.laudo(ids, seed, idx)
    if modo == "ON":
        return float(lau["score_laudo"]) + tz.ruido(ids, seed, idx)
    return float(tz.r_raw(ids, lau, seed, idx))


def _r33_h_probs(pol, LM, prevs):
    Z = pol["W"][prevs] + pol["b"] + LM[prevs]
    z = Z - Z.max(axis=1, keepdims=True)
    e = np.exp(np.maximum(z, -60.0))
    return e / (e.sum(axis=1, keepdims=True) + 1e-12)


def _r33_h_upd(pol, ids, g_: float):
    for prev, nxt in zip(ids[:-1], ids[1:]):
        pol["W"][prev, nxt] += g_
        pol["b"][nxt] += g_ * 0.5
        pol["W"][prev] -= pol["W"][prev].mean()


def r33_grpo_h(tz, modo: str, seed: int, lr: float, G: int = R33_G, epocas: int = 2):
    """GRPO-H: grupos de G sequências, vantagem relativa ao grupo, razão p_novo/p_antigo por token com corte (±0,2), `epocas` épocas por grupo, atualização por token igual à da pilha H (÷G); sem KL."""
    rng = r25_rng(seed, r25_crc(f"train|{tz.nome}"), 5)
    pol = tz.init_pol(rng)
    LM = _r27_lm(tz.M)
    cnt = 0
    for _g in range(tz.P // G):
        seqs, rs = [], []
        for _i in range(G):
            ids, logps = tz.sample(pol, rng)
            rs.append(r33_recompensa(tz, ids, modo, seed, cnt))
            cnt += 1
            seqs.append((ids, np.exp(np.asarray(logps, float))))
        rs = np.asarray(rs)
        sd = float(rs.std())
        adv = (rs - rs.mean()) / (sd + 1e-6) if sd > 1e-8 else np.zeros(G)
        for _ep in range(epocas):
            raz = []
            for ids, pold in seqs:
                prevs = np.asarray(ids[:-1], int)
                nx = np.asarray(ids[1:], int)
                pn = _r33_h_probs(pol, LM, prevs)[np.arange(len(nx)), nx]
                raz.append(pn / np.maximum(pold, 1e-12))
            for (ids, _pold), A, rz in zip(seqs, adv, raz):
                if A == 0.0:
                    continue
                for j, (prev, nxt) in enumerate(zip(ids[:-1], ids[1:])):
                    if (A > 0 and rz[j] > 1.2) or (A < 0 and rz[j] < 0.8):
                        continue
                    g_ = lr * float(A) * float(rz[j]) / G
                    pol["W"][prev, nxt] += g_
                    pol["b"][nxt] += g_ * 0.5
                    pol["W"][prev] -= pol["W"][prev].mean()
    return pol


def r33_ordg_h(tz, modo: str, seed: int, lr: float, G: int = R33_G):
    """ORD-G: RL ordinário com o MESMO lote de G e o mesmo nº de atualizações do GRPO-H (vantagem = recompensa − linha de base EMA 0,9), atualização da pilha ÷G."""
    rng = r25_rng(seed, r25_crc(f"train|{tz.nome}"), 5)
    pol = tz.init_pol(rng)
    base, cnt = 0.0, 0
    for _g in range(tz.P // G):
        seqs, rs = [], []
        for _i in range(G):
            ids, _lp = tz.sample(pol, rng)
            rs.append(r33_recompensa(tz, ids, modo, seed, cnt))
            cnt += 1
            seqs.append(ids)
        advs = [r - base for r in rs]
        base = 0.9 * base + 0.1 * float(np.mean(rs))
        for ids, a in zip(seqs, advs):
            _r33_h_upd(pol, ids, lr * float(a) / G)
    return pol


def r33_treina(tz, tn: str, algo: str, seed: int, rl_sel: dict, lr_h: dict):
    """Política treinada de `algo` ∈ ORD, GRPO, ORDG para a tarefa tn (Z: r29 com lr/hp do DEV da R30; H: r25 / GRPO-H / ORD-G com lr do DEV H)."""
    if tn in R33_Z:
        lr, hp = rl_sel[algo]
        return r29_rl_treinar(tz, seed, lr, algo, hp)["pol"]
    modo = R33_MODO[tn]
    if algo == "ORD":
        return r25_treinar(tz, r33_cfg(tn), seed, lr_h["ORD"])["pol"]
    if algo == "GRPO":
        return r33_grpo_h(tz, "ON" if modo == "ON" else "RAW", seed, lr_h["GRPO"])
    return r33_ordg_h(tz, "ON" if modo == "ON" else "RAW", seed, lr_h["ORDG"])


def r33_ev(tz, pol, seed: int, rot: str, kmax: int):
    return {int(k): float(v[0]) for k, v in r27_avaliar_aninhado(tz, pol, seed, rot, kmax).items()}


# ---------------------------------------------------------------------------
# Deslocamentos (só na avaliação)
# ---------------------------------------------------------------------------
class R33DeslVer:
    """Verificador pior: score_laudo += N(0; 0,15) (limitado a [0,1]); passa_tela invertido com prob. 0,20; r_clean limpo."""

    def __init__(self, tz):
        self.tz, self.nome, self.V, self.L = tz, tz.nome + "|V", tz.V, tz.L

    def sample(self, pol, rng):
        return self.tz.sample(pol, rng)

    def r_clean(self, ids):
        return self.tz.r_clean(ids)

    def laudo(self, ids, seed, i):
        lau = dict(self.tz.laudo(ids, seed, i))
        rng = r25_rng(seed, r33_crc("shv"), int(i) + 99)
        s = float(np.clip(lau["score_laudo"] + rng.normal(0.0, 0.15), 0.0, 1.0))
        passa = (not lau["passa_tela"]) if rng.random() < 0.20 else lau["passa_tela"]
        lau.update(score_laudo=s, passa_tela=bool(passa), mantem=bool(passa and s >= R24_HP_FILTRO["tau_laudo"]))
        return lau


class R33DeslEntZ:
    """Z: os 2 primeiros símbolos são sorteados uniformemente (contexto inicial não visto no treino); a política continua daí."""

    def __init__(self, tz):
        self.tz, self.nome, self.V, self.L = tz, tz.nome + "|E", tz.V, tz.L

    def sample(self, pol, rng):
        V = self.V
        ids = [int(rng.integers(0, V)), int(rng.integers(0, V))]
        Wm = pol["W"]
        for t in range(2, self.L):
            z = Wm[self.tz._state(ids, t)]
            p = np.exp(z - z.max())
            p = p / p.sum()
            ids.append(int(min(p.cumsum().searchsorted(float(rng.random()), side="right"), V - 1)))
        return ids, []

    def r_clean(self, ids):
        return self.tz.r_clean(ids)

    def laudo(self, ids, seed, i):
        return self.tz.laudo(ids, seed, i)


def r33_tarefa_desloc(tz, tn: str, cond: str):
    if cond == "ID":
        return tz
    if cond == "VER":
        return R33DeslVer(tz)
    if tn in R33_Z:
        return R33DeslEntZ(tz)
    p = R28_PRM_HARD[tn] if tn in R28_PRM_HARD else R33_PRM_H[tn]
    return R27Hard(tn + "|E", p["V"], p["L"], int(p["seed_lex"]) + 7, p["P"])


# ---------------------------------------------------------------------------
# Jobs (por semente: todas as tarefas)
# ---------------------------------------------------------------------------
def r33_job_devh(task):
    """task = ('R33DEVH', seed). Para cada algoritmo H e lr da grade: r_clean@k=4 em H80 e H60 (DEV do lr dos treinadores de texto)."""
    _, seed = task
    out = {}
    for tn in R33_DEV_H_TAREFAS:
        tz = r33_tarefa(tn)
        modo = "ON" if R33_MODO[tn] == "ON" else "RAW"
        for lr in R33_LR_H_GRADE:
            pols = {"ORD": r25_treinar(tz, r33_cfg(tn), seed, lr)["pol"], "GRPO": r33_grpo_h(tz, modo, seed, lr), "ORDG": r33_ordg_h(tz, modo, seed, lr)}
            for a, pol in pols.items():
                out[(a, lr, tn)] = r33_ev(tz, pol, seed, "R33|dev", 4)[4]
    return out


def r33_job_stk(task):
    """task = ('R33STK', seed, rl_sel, lr_h). Por tarefa: G (ORD, GRPO, [ORD-G]) em k=1,2,4; nas 5 tarefas da pilha: SH (BASE, F, FULL) × (ID, ENT, VER) em k≤max(4, k_t)."""
    _, seed, rl_sel, lr_h = task
    out = {"seed": int(seed), "G": {}, "SH": {}, "ent": {}}
    for tn in R33_TAREFAS:
        tz = r33_tarefa(tn)
        pol = {a: r33_treina(tz, tn, a, seed, rl_sel, lr_h) for a in (("ORD", "GRPO") if tn in R33_Z else ("ORD", "GRPO", "ORDG"))}
        out["G"][tn] = {a: r33_ev(tz, p, seed, "R33|g", 4) for a, p in pol.items()}
        if tn in R33_Z:
            out["ent"][tn] = {a: float(r28_ent_norm(tz, pol[a], seed, f"R33|{a}")) for a in ("ORD", "GRPO")}
        if tn not in R33_STK5:
            continue
        lr_l = R28_LR_TRAVADO[tn]
        kmax = max(4, R33_KAL[tn])
        if R33_MODO[tn] == "ON":
            f_pol = r25_treinar(tz, r27_cfg_pf(), seed, lr_l)["pol"]
            base_pol = f_pol
        else:
            base_pol = r25_treinar(tz, r27_cfg_pf(), seed, lr_l)["pol"]
            f_pol = pol["ORD"] if abs(lr_h["ORD"] - lr_l) < 1e-12 else r25_treinar(tz, r27_cfg_pr(), seed, lr_l)["pol"]
        out["SH"][tn] = {}
        for c in R33_CONDS:
            tc = r33_tarefa_desloc(tz, tn, c)
            ef = r33_ev(tc, f_pol, seed, "R33|sh", kmax)
            out["SH"][tn][c] = {"F": ef, "BASE": ef if base_pol is f_pol else r33_ev(tc, base_pol, seed, "R33|sh", kmax), "FULL": r33_ev(tc, pol["GRPO"], seed, "R33|sh", kmax)}
    return out


# ---------------------------------------------------------------------------
# PARTE B — memória (mundo da R32 e mundo com ecos)
# ---------------------------------------------------------------------------
def r33_mem_prep(payload: dict) -> dict:
    words = sorted(payload["vec"])
    wid = {w: i for i, w in enumerate(words)}
    Vm = np.stack([np.asarray(payload["vec"][w], float) for w in words])
    nr = np.linalg.norm(Vm, axis=1)
    Vn = np.where(nr[:, None] > 1e-12, Vm / np.where(nr > 1e-12, nr, 1.0)[:, None], 0.0)
    return {"wid": wid, "C": Vn @ Vn.T, "vec": payload["vec"], "attrs": payload["attrs"]}


def r33_mem_eco(Wm: dict, seed: int, payload: dict):
    """Mundo com ecos: cada atualização é seguida, com prob. 0,6, por 1–3 repetições (mesmo valor; idioma sorteado); tempos renumerados; + 12 consultas de profundidade 2."""
    rng = r25_rng(seed, r33_crc("mem|eco"), 1)
    attrs = payload["attrs"]
    ev = []
    for e in Wm["eventos"]:
        ev.append(dict(e))
        if e["slot"] is not None and rng.random() < 0.6:
            for _ in range(int(rng.integers(1, 4))):
                ev.append(dict(e, w=attrs[e["canon"]][int(rng.integers(0, 2))]))
    for i, e in enumerate(ev):
        e["t"] = i
    hist = Wm["hist"]
    outros = Wm["slots"][6:]
    cand_h = [s for s in Wm["hot"] if len(hist[s]) >= 3]
    cand_o = [s for s in outros if len(hist[s]) >= 3]
    todos = [s for s in Wm["slots"] if len(hist[s]) >= 3]
    cand_h = cand_h or todos
    cand_o = cand_o or todos or cand_h
    rq = r25_rng(seed, r33_crc("mem|d2"), 2)
    q2 = [(cand_h[int(rq.integers(0, len(cand_h)))], 2) for _ in range(6)] + [(cand_o[int(rq.integers(0, len(cand_o)))], 2) for _ in range(6)]
    l2 = [int(rq.integers(0, 2)) for _ in q2]
    return ev, q2, l2


def r33_arr(pool, prep):
    wid = prep["wid"]
    return {"ent": np.asarray([e["ent"] for e in pool], int), "canon": np.asarray([e["canon"] for e in pool], int), "w": np.asarray([wid[e["w"]] for e in pool], int), "pool": pool}


def r33_topk(A, ent_q: int, wid_q: int, canon_q: int, canonico: bool, k: int, rng, C):
    n = len(A["ent"])
    sc = (A["ent"] == ent_q).astype(float) + (((A["canon"] == canon_q) & (A["canon"] >= 0)).astype(float) if canonico else C[A["w"], wid_q])
    ordem = np.argsort(-(sc + rng.random(n) * 1e-6))
    return [A["pool"][int(i)] for i in ordem[:k]]


def r33_mem_ler(items, ent_q, w_q, canon_q, depth: int, canonico: bool, prep, rng, colapsa: bool):
    """Leitor único. colapsa=False reproduz o leitor da R29/R32 (profundidade 0/1 por evento); colapsa=True ordena por tempo, colapsa valores consecutivos repetidos e devolve o valor na profundidade pedida."""
    vec = prep["vec"]
    cand = [e for e in items if e["ent"] == ent_q]
    if canonico:
        grp = [e for e in cand if e["canon"] == canon_q and e["canon"] >= 0]
        if not grp:
            return int(rng.integers(0, 20))
    else:
        if not cand:
            return int(rng.integers(0, 20))
        sc = [1.0 + _r29_cos(vec[e["w"]], vec[w_q]) for e in cand]
        best = max(sc)
        grp = [e for e, s in zip(cand, sc) if s >= best - 1e-9]
    grp = sorted(grp, key=lambda x: -x["t"])
    if not colapsa:
        if depth == 0:
            return int(grp[0]["val"])
        if len(grp) >= 2:
            return int(grp[1]["val"])
        return int(rng.integers(0, 20))
    vals = []
    for e in grp:
        if not vals or e["val"] != vals[-1]:
            vals.append(int(e["val"]))
    return vals[depth] if len(vals) > depth else int(rng.integers(0, 20))


def r33_mem_loja_runs(ev, prep, theta: float, cs):
    """Loja deduplicada do mundo com ecos: aglomerados por entidade (ligação simples, cosseno ≥ θ sobre as palavras do aglomerado); um evento com o MESMO valor da corrida mais recente a funde;
    valor novo abre corrida; guarda as c corridas mais recentes. Devolve ({c: pool}, nº de comparações, nº de aglomerados impuros, nº de aglomerados)."""
    C, wid = prep["C"], prep["wid"]
    por_ent, ncmp = {}, 0
    for e in ev:
        cls = por_ent.setdefault(e["ent"], [])
        wi = wid[e["w"]]
        best, bs = None, -2.0
        for c in cls:
            for wj in c["wids"]:
                s_ = float(C[wj, wi])
                ncmp += 1
                if s_ > bs:
                    best, bs = c, s_
        if best is not None and bs >= theta - 1e-12:
            if best["runs"][-1]["val"] == e["val"]:
                best["runs"][-1] = e
            else:
                best["runs"].append(e)
            if wi not in best["wids"]:
                best["wids"].append(wi)
            best["canons"].add(e["canon"])
        else:
            cls.append({"wids": [wi], "runs": [e], "canons": {e["canon"]}})
    todos = [cl for ent in sorted(por_ent) for cl in por_ent[ent]]
    pools = {c: [e for cl in todos for e in cl["runs"][-c:]] for c in cs}
    return pools, ncmp, sum(1 for cl in todos if len(cl["canons"]) > 1), len(todos)


def r33_mem_run(seed: int, payload: dict, thetas, cs):
    prep = r33_mem_prep(payload)
    C, wid, attrs = prep["C"], prep["wid"], payload["attrs"]
    Wm = r29_mem_mundo(seed, payload)
    out = {"M0": {}, "E": {}, "loja": {}, "ncmp": {}, "impuro": {}}
    # ---- M0: mundo da R32 (mesmos rótulos de RNG e leitor da R32; acertos A1, A2 e S|θ com c=2 por evento)
    ev0 = Wm["eventos"]
    A0 = r33_arr(ev0, prep)
    st0 = {th: r33_arr(r32_mem_loja(ev0, payload["vec"], th)[0], prep) for th in thetas}
    acc = {"A1": [], "A2": []}
    for th in thetas:
        acc[f"S|{th:g}"] = []
    for qi, ((s, tipo), lang) in enumerate(zip(Wm["cons"], Wm["langs"])):
        w_q = attrs[s[1]][lang]
        verd = Wm["atual"][s] if tipo == "vig" else Wm["hist"][s][-2][1]
        dp = 0 if tipo == "vig" else 1
        for nome, Aq, canon, rot_q, rot_l in (("A1", A0, False, "mem|q", "mem|l1"), ("A2", A0, True, "mem|q", "mem|l2")):
            it = r33_topk(Aq, s[0], wid[w_q], s[1], canon, 6, r25_rng(seed, r32_crc(rot_q), 100 + qi), C)
            acc[nome].append(1.0 if r33_mem_ler(it, s[0], w_q, s[1], dp, canon, prep, r25_rng(seed, r32_crc(rot_l), 200 + qi), False) == verd else 0.0)
        for th in thetas:
            it = r33_topk(st0[th], s[0], wid[w_q], s[1], False, 6, r25_rng(seed, r32_crc("mem|q"), 100 + qi), C)
            acc[f"S|{th:g}"].append(1.0 if r33_mem_ler(it, s[0], w_q, s[1], dp, False, prep, r25_rng(seed, r32_crc("mem|l5"), 200 + qi), False) == verd else 0.0)
    out["M0"] = {k: float(np.mean(v)) for k, v in acc.items()}
    # ---- mundo com ecos
    ev1, q2, l2 = r33_mem_eco(Wm, seed, payload)
    A1 = r33_arr(ev1, prep)
    pools, meta = {}, {}
    for th in thetas:
        pl, ncmp, imp, ncl = r33_mem_loja_runs(ev1, prep, th, cs)
        for c in cs:
            pools[(th, c)] = r33_arr(pl[c], prep)
            out["loja"][f"{th:g}|{c}"] = len(pl[c])
        out["ncmp"][f"{th:g}"], out["impuro"][f"{th:g}"] = int(ncmp), (int(imp), int(ncl))
    qs = [(s, ("vig", "hist")[0] if tipo == "vig" else "hist", lang) for (s, tipo), lang in zip(Wm["cons"], Wm["langs"])]
    consultas = [(s, {"vig": 0, "hist": 1}[tipo], lang) for s, tipo, lang in qs] + [(s, 2, lg) for (s, _d), lg in zip(q2, l2)]
    arms = ["APPEND", "CANON"] + [f"D|{th:g}|{c}" for th in thetas for c in cs]
    res = {a: {0: [], 1: [], 2: []} for a in arms}
    for qi, (s, dp, lang) in enumerate(consultas):
        w_q = attrs[s[1]][lang]
        verd = Wm["atual"][s] if dp == 0 else Wm["hist"][s][-1 - dp][1]
        for a in arms:
            if a == "APPEND":
                Aq, canon = A1, False
            elif a == "CANON":
                Aq, canon = A1, True
            else:
                _, th_s, c_s = a.split("|")
                Aq, canon = pools[(float(th_s), int(c_s))], False
            it = r33_topk(Aq, s[0], wid[w_q], s[1], canon, 6, r25_rng(seed, r33_crc("mem|q"), 100 + qi), C)
            resp = r33_mem_ler(it, s[0], w_q, s[1], dp, canon, prep, r25_rng(seed, r33_crc("mem|l"), 200 + qi), True)
            res[a][dp].append(1.0 if resp == verd else 0.0)
    for a in arms:
        allq = res[a][0] + res[a][1] + res[a][2]
        out["E"][a] = {"all": float(np.mean(allq)), "d0": float(np.mean(res[a][0])), "d1": float(np.mean(res[a][1])), "d2": float(np.mean(res[a][2]))}
    out["n_ev"] = (len(ev0), len(ev1))
    return out


def r33_job_mem(task):
    _, seed, payload, thetas, cs = task
    return r33_mem_run(seed, payload, thetas, cs)


# ---------------------------------------------------------------------------
# PARTE D — Nash NG9: diagnóstico (jogos cooperativos 3×3; vetorizado por jogo e por condição inicial)
# ---------------------------------------------------------------------------
def r33_proj(V):
    """Projeção euclidiana no simplex de 3 coordenadas, em lote (último eixo)."""
    U = -np.sort(-V, axis=-1)
    css = np.cumsum(U, axis=-1)
    rho = (U * np.arange(1, V.shape[-1] + 1) > (css - 1.0)).sum(axis=-1)
    th = (np.take_along_axis(css, (rho - 1)[..., None], axis=-1)[..., 0] - 1.0) / rho
    return np.maximum(V - th[..., None], 0.0)


def r33_ga(A, X, Y, T: int, eta: float = R33_ND_ETA, tau=None, sig=None, ruido=None):
    """Subida de gradiente simultânea projetada (A: (G,3,3); X, Y: (G,n,3)). tau(t): peso do gradiente de entropia (−log x); sig(t) × ruido[g,t,:,:] soma ruído ao gradiente."""
    At = A.transpose(0, 2, 1)
    for t in range(T):
        gx, gy = Y @ At, X @ A
        if tau is not None:
            tt = tau(t)
            gx = gx - tt * np.log(np.maximum(X, 1e-12))
            gy = gy - tt * np.log(np.maximum(Y, 1e-12))
        if sig is not None and sig(t) > 0.0:
            gx = gx + sig(t) * ruido[:, t, 0:1, :]
            gy = gy + sig(t) * ruido[:, t, 1:2, :]
        X, Y = r33_proj(X + eta * gx), r33_proj(Y + eta * gy)
    return X, Y


def r33_nash_diag(seeds, nin: int = R33_ND_NIN, T: int = R33_ND_T):
    G = len(seeds)
    A = np.zeros((G, 3, 3)); X0 = np.zeros((G, nin, 3)); Y0 = np.zeros((G, nin, 3))
    for gi, s in enumerate(seeds):
        rng = np.random.default_rng([int(s), 33, 2])
        A[gi] = rng.normal(size=(3, 3))
        for j in range(nin):
            X0[gi, j] = rng.dirichlet(np.ones(3)); Y0[gi, j] = rng.dirichlet(np.ones(3))
    Amax = A.reshape(G, 9).max(axis=1)
    pay = lambda X, Y: np.einsum("gni,gij,gnj->gn", X, A, Y)
    expl = lambda X, Y: (np.einsum("gij,gnj->gni", A, Y).max(axis=2) - pay(X, Y)) + (np.einsum("gni,gij->gnj", X, A).max(axis=2) - pay(X, Y))
    ok = lambda p: p >= Amax[:, None] - 0.05
    X, Y = r33_ga(A, X0, Y0, T)
    p, e = pay(X, Y), expl(X, Y)
    s_all = ok(p)
    out = {"ga1": s_all[:, 0].copy(), "nash_ga1": (e[:, 0] <= 0.05), "basin": s_all.mean(axis=1)}
    best = lambda k: ok(np.take_along_axis(p[:, :k], p[:, :k].argmax(axis=1)[:, None], axis=1)[:, 0:1])[:, 0]
    out["rs4"], out["rs16"] = best(4), best(16)
    X4, Y4 = r33_ga(A, X0[:, :4], Y0[:, :4], T // 4)
    p4 = pay(X4, Y4)
    out["rs4eq"] = ok(np.take_along_axis(p4, p4.argmax(axis=1)[:, None], axis=1))[:, 0]
    Xh, Yh = r33_ga(A, X0[:, :1], Y0[:, :1], T, tau=lambda t: 0.3 * (1.0 - t / T))
    out["ann_h"] = ok(pay(Xh, Yh))[:, 0]
    ruido = np.stack([np.random.default_rng([int(s), 33, 3]).normal(size=(T // 2, 2, 3)) for s in seeds])
    ruido = np.concatenate([ruido, np.zeros((G, T - T // 2, 2, 3))], axis=1)
    Xn, Yn = r33_ga(A, X0[:, :1], Y0[:, :1], T, sig=lambda t: max(0.0, 1.0 * (1.0 - 2.0 * t / T)), ruido=ruido)
    out["ann_n"] = ok(pay(Xn, Yn))[:, 0]
    nn = np.zeros(G, int)
    for gi in range(G):
        M = A[gi]
        nn[gi] = int(sum(1 for i in range(3) for j in range(3) if M[i, j] >= M[:, j].max() and M[i, j] >= M[i, :].max()))
    out["n_nash"] = nn
    out["gap2"] = np.asarray([float(np.sort(A[gi].reshape(-1))[-1] - np.sort(A[gi].reshape(-1))[-2]) for gi in range(G)])
    return out


def r33_job_nd(task):
    _, seeds = task
    return r33_nash_diag(list(seeds))


# ---------------------------------------------------------------------------
# despacho
# ---------------------------------------------------------------------------
def r33_job(task):
    k = task[0]
    if k == "R33STK":
        return r33_job_stk(task)
    if k == "R33DEVH":
        return r33_job_devh(task)
    if k == "R33MEM":
        return r33_job_mem(task)
    if k == "R33ND":
        return r33_job_nd(task)
    return r32_job(task)


# ---------------------------------------------------------------------------
# vereditos e pilha (regras da Parte A e B do prereg; mecânicas)
# ---------------------------------------------------------------------------
def r33_decisao_grpo(st: dict) -> str:
    if st["G1"] == "confirmada" and st["G3"] == "confirmada" and st["G4"] == "confirmada" and st["G2"] != "refutada":
        return "MANTER"
    if st["G1"] == "confirmada" and st["G2"] != "refutada":
        return "RESTRINGIR_Z"
    return "REVERTER"


def r33_vereditos(st: dict) -> dict:
    dec = r33_decisao_grpo(st)
    if dec in ("MANTER", "RESTRINGIR_Z"):
        g = "vivo"
    elif st["G1"] == "refutada" or st["G2"] == "refutada":
        g = "nocivo"
    else:
        g = "decorativo"
    m0, m1, m3 = st["M0"], st["M1"], st["M3"]
    if all(x == "confirmada" for x in (m0, m1, m3)) and st["M2"] != "refutada" and st["M4"] != "refutada":
        d = "vivo"
    elif any(x == "refutada" for x in (m0, m1, m3)):
        d = "nocivo"
    else:
        d = "decorativo"
    return {"grpo": g, "dedup_semantica": d, "decisao_grpo": dec}


def r33_pilha_resultante(pil32: dict, ver: dict) -> tuple:
    notas = []
    pil = dict(pil32)
    dec = ver["decisao_grpo"]
    if dec == "MANTER":
        pil["rl"] = "grpo"; notas.append("A: GRPO MANTIDO (G1, G3, G4 confirmadas; G2 não refutada) → fica no lugar do RL ordinário em tarefas Z e H")
    elif dec == "RESTRINGIR_Z":
        pil["rl"] = "grpo_z"; notas.append("A: GRPO RESTRITO ao tipo Z (G1 confirmada, G2 não refutada; G3 ou G4 não confirmada) → tarefas H voltam ao RL ordinário")
    else:
        pil["rl"] = "ordinario"; notas.append("A: GRPO REVERTIDO (G1 nula/refutada ou G2 refutada) → a pilha volta ao RL ordinário")
    if ver["dedup_semantica"] == "vivo":
        pil["memoria"] = "dedup_semantica"; notas.append("B: dedup semântica da memória VIVA (M0, M1, M3 confirmadas; M2, M4 não refutadas) → ENTRA como componente de memória (provisório)")
    else:
        pil.pop("memoria", None); notas.append(f"B: dedup semântica da memória {ver['dedup_semantica'].upper()} → fica FORA")
    return pil, notas


def r33_permitido(ver: dict, per32: dict) -> dict:
    """Derivação INDEPENDENTE (por campo) a partir do permitido da R32."""
    per = {k: v for k, v in per32.items() if k not in ("rl", "memoria")}
    per["rl"] = {"MANTER": "grpo", "RESTRINGIR_Z": "grpo_z"}.get(ver["decisao_grpo"], "ordinario")
    if ver["dedup_semantica"] == "vivo":
        per["memoria"] = "dedup_semantica"
    return per


def r33_na_pilha(pil: dict) -> list:
    na = []
    if pil["rl"] in ("ordinario", "grpo_z"):
        na.append("rl_ordinario")
    if pil["rl"] in ("grpo", "grpo_z"):
        na.append("grpo")
    if pil["gate"] != 1:
        na.append("porta_k")
    if pil["filtro"] == "adaptativo":
        na.append("filtro_adaptativo")
    if pil["meta"] == "norm":
        na.append("meta_norm")
    if pil.get("k_alocada") == "sim":
        na.append("porta_k_alocada")
    if pil.get("ewc") == "sim":
        na.append("ewc")
    if pil.get("dedup") == "sim":
        na.append("dedup_online")
    if pil.get("memoria") == "dedup_semantica":
        na.append("dedup_semantica")
    return na


def r33_bc(linhas_mapa, st_hip, pilha, permitido, custo, versao, esperada, ver, status_nash, alega):
    pil_b = dict(pilha, rl=("ordinario" if pilha["rl"] == "grpo_z" else pilha["rl"]))
    bc = r31_bc(linhas_mapa, st_hip, pil_b, permitido, custo, versao, esperada, ver, status_nash, alega)
    bc["stack"] = dict(pilha)
    bc["na_pilha"] = r33_na_pilha(pilha)
    for c in bc["na_pilha"]:
        bc["estado"].setdefault(c, ["ativo"])
        bc["evidencia"] = sorted(set(bc["evidencia"]) | {c})
    bc["opcional"] = sorted(set(bc["opcional"]) | set(R32_OPCIONAIS_EXTRA) | set(R33_OPCIONAIS_EXTRA))
    bc["avaliado"] = sorted(ver)
    return bc


def r33_mutar(bc: dict, tipo: int, rng):
    b, t = r32_mutar(bc, tipo, rng)
    if t == "rl_diferente" and b["stack"].get("rl") == bc["stack"].get("rl"):
        c = [x for x in ("extraordinario", "grpo", "grpo_z", "nenhum", "ordinario") if x != bc["stack"]["rl"]]
        b["stack"]["rl"] = c[int(rng.integers(0, len(c)))]
    return b, t


def r33_validar_verificador(bc: dict, n_mut: int, n_ctl: int, seeds_mut, seeds_ctl):
    det, conc, tipos, fa = 0, 0, {}, 0
    for i in range(n_mut):
        rng = r25_rng(seeds_mut[i], r31_crc("mut"), i)
        bm, tp = r33_mutar(bc, i, rng)
        vp, vy = r31_checar_prolog(r31_bc_texto(bm)), r31_checar_py(bm)
        det += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
        tipos.setdefault(tp, [0, 0]); tipos[tp][0] += 1; tipos[tp][1] += 1 if vp else 0
    for i in range(n_ctl):
        rng = r25_rng(seeds_ctl[i], r31_crc("ctl"), i)
        vp, vy = r31_checar_prolog(r31_bc_texto(bc, rng, benigno=True)), r31_checar_py(bc)
        fa += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
    return {"detectados": det, "n_mut": n_mut, "falsos_alarmes": fa, "n_ctl": n_ctl, "concordancia": conc, "n_total": n_mut + n_ctl, "tipos": tipos}


