def r33_linhas_mapa(args, r27, r28v, r29v, r30v, r31v, r32v, r33v):
    base = r32_linhas_mapa(args, r27, r28v, r29v, r30v, r31v, r32v)
    n32 = len(R32_MAPA)
    vn = (r33v or {}).get("ver_novos") or {}
    evn = (r33v or {}).get("ev_novos") or {}
    dec = (r33v or {}).get("decisao_grpo")
    L = []
    for i, (rot, est, ev) in enumerate(base):
        if i < n32:
            if rot == "bloco40":
                L.append((rot, r33_estado_bloco(args, "bloco40"), dict((r[0], r[3] + " → " + r[5]) for r in R33_MAPA)["bloco40"]))
                L.append(("bloco41", "ATIVO", dict((r[0], r[3] + " → " + r[5]) for r in R33_MAPA)["bloco41"]))
            elif rot in ("nexus_lexico.py", "asi_metacognitivo_enxuto.py"):
                r_ = [r for r in R33_MAPA if r[0] == rot][0]
                L.append((rot, "ATIVO", r_[3] + " → " + r_[5]))
            else:
                L.append((rot, est, ev))
            continue
        if rot == "GRPO sem crítico (proxy)" and dec:
            est = {"MANTER": "ATIVO (ADOTADO na pilha; MANTIDO na confirmação R33 em Z e H; VIVO)",
                   "RESTRINGIR_Z": "ATIVO (RESTRITO ao tipo Z na confirmação R33; tarefas H usam RL ordinário; VIVO)"}.get(dec, "FORA (REVERTIDO na confirmação R33: o RL ordinário volta à pilha)")
            ev = evn.get("grpo", ev)
        if rot == "Mega-Sena":
            est = "DORMENTE (nulo honesto; regressão ao vivo na R33)"
        if rot == "verificador de consistência (Prolog)" and (r33v or {}).get("ver_verif33"):
            ev = r33v["ver_verif33"][:140]
        if rot.startswith("jogos do gradiente: Nash analítico") and (r33v or {}).get("ver_nd33"):
            ev = (ev + " | " + r33v["ver_nd33"])[:300]
        L.append((rot, est, ev))
    dv = vn.get("dedup_semantica")
    est_d = ("ATIVO (ADOTADO como componente de memória; VIVO — provisório)" if dv == "vivo" else (f"PROXY (brinquedo; fora da pilha; {_r31_rot_ver(dv)} na confirmação R33)" if dv else "PROXY (brinquedo; sem resultado nesta execução)"))
    L.append(("dedup semântica da memória (R33)", est_d, evn.get("dedup_semantica", "(sem resultado nesta execução)")))
    L.append(("robustez sob deslocamento (R33)", "DESCRITIVO (rótulos de robustez por etapa; a pilha não muda por eles)", ((r33v or {}).get("ver_sh33") or "(sem resultado nesta execução)")[:240]))
    return L


def mapa_do_que_vive_linhas_r33(ctx: Contexto) -> list:
    lin = r33_linhas_mapa(ctx.args, ctx.res.get("r27") or {}, ctx.res.get("r28") or {}, ctx.res.get("r29") or {}, ctx.res.get("r30") or {}, ctx.res.get("r31") or {}, ctx.res.get("r32") or {}, ctx.res.get("r33") or {})
    n_blocos = len(R33_MAPA)
    rods = {r_[0]: r_[2] for r_ in R33_MAPA}
    trans_rod = {"filtro-primeiro (τ fixo)": "R20", "filtro adaptativo (travado)": "R26–R33", "RL ordinário": "R19–R33", "RL extraordinário": "R19–R33",
                 "porta de geração (k)": "R25–R33", "meta-recompensa (bruta/calibrada)": "R24–R33", "meta-recompensa NORMALIZADA": "R26–R33", "delírio": "R3–R22",
                 "BitLinear ternário v2 (STE)": "R25–R33", "BitLinear v1 (R24)": "R24", "SNN LIF (R24)": "R24", "prefill/decode (intensidade)": "R24", "Mega-Sena": "R18–R33",
                 "memória em tokens core/recall/archival": "R29–R33", "dialética de gradientes (proxy)": "R29–R33", "verificador de consistência (Prolog)": "R28–R33",
                 "mini-JEPA (proxy)": "R29–R33", "CBP / shrink-and-perturb (proxy)": "R29–R33", "esquecimento: replay × EWC (proxy)": "R29–R33", "GRPO sem crítico (proxy)": "R29–R33",
                 "dedup online (estrutura na escrita)": "R30–R33", "porta k alocada (custo igual)": "R28–R33", "pilha completa (todas as opcionais)": "R31", "jogos do gradiente: Nash analítico (R31)": "R8–R33",
                 "predição seletiva (R32)": "R32", "dedup semântica da memória (R33)": "R33", "robustez sob deslocamento (R33)": "R33"}
    L = ["MAPA DO QUE VIVE (33 rodadas) — estado de cada bloco derivado das funções de dormência do próprio código e dos vereditos das auditorias R31, R32 e R33",
         "estados: ATIVO = roda ao vivo | DORMENTE = resultado congelado (sha256), recálculo atrás de --reativar-dormentes | CONGELADO = módulo encerrado | PROXY = brinquedo rotulado, fora da pilha | FORA = removido ou nunca adotado | NÚCLEO-MATEMÁTICO = fato verificável, não evidência de cognição | VIVO/DECORATIVO/NOCIVO = veredito pré-registrado (R31, R32 ou R33 quando replicado)",
         f"{'módulo/bloco':<28}{'rodada':<9}{'estado':<38}tema → evidência"]
    for i, (rot, est, ev) in enumerate(lin):
        if i == n_blocos:
            L.append("--- módulos transversais (estado pelo veredito desta execução) ---")
        rod = rods.get(rot) if i < n_blocos else trans_rod.get(rot, "R29")
        L.append(f"{rot:<28}{rod:<9}{est:<38}{ev}")
    return L


def r33_bc_do_run(ctx, st_hip, vt, ver, pilha, permitido, kal, kdef_soma, status_nash, alega):
    r33v = dict(ctx.res.get("r33") or {})
    r33v["ver_novos"] = {k: ver[k] for k in R33_COMP_NOVOS if k in ver}
    linhas = r33_linhas_mapa(ctx.args, ctx.res.get("r27") or {}, ctx.res.get("r28") or {}, ctx.res.get("r29") or {}, ctx.res.get("r30") or {}, ctx.res.get("r31") or {}, ctx.res.get("r32") or {}, r33v)
    custo = {"alocado": int(sum(kal.values())), "fixo": int(kdef_soma)}
    return r33_bc(linhas, st_hip, pilha, permitido, custo, {"nexus": vt}, {"nexus": R33_NEXUS_ESPERADO}, ver, status_nash, alega)


def r33_rotulo_robustez(st: dict, e: str) -> str:
    sid, sen, sve = st[f"ST_{e}_ID"], st[f"ST_{e}_ENT"], st[f"ST_{e}_VER"]
    if sid != "confirmada":
        return "SEM EFEITO"
    if sen == "refutada" or sve == "refutada":
        return "QUEBRA"
    if sen == "confirmada" and sve == "confirmada":
        return "ROBUSTO"
    return "FRÁGIL"


def r33_veredito_texto(ver_novos: dict, st: dict, P: dict, cons: dict) -> dict:
    d = lambda h: f"{h} Δ={P[h]['media']:+.3f} [{P[h]['lo']:+.3f},{P[h]['hi']:+.3f}] Holm={P[h]['p_holm']:.3f} {st[h]}" + (" consistente" if cons.get(h) else (" INCONSISTENTE entre metades" if h in cons else ""))
    return {"grpo": f"{ver_novos['decisao_grpo']} ({_r31_rot_ver(ver_novos['grpo'])}) — " + "; ".join(d(h) for h in R33_HIPOT_GR),
            "dedup_semantica": _r31_rot_ver(ver_novos["dedup_semantica"]) + " — " + "; ".join(d(h) for h in R33_HIPOT_MEM)}


def bloco41(ctx: Contexto):
    rep = ctx.rep
    N = dict(R33_NTEST)
    rapido = bool(getattr(ctx.args, "rapido", False))
    if rapido:
        N = {"stk": 4, "mem": 12, "nash": 12}
    rep.titulo("BLOCO 41 — [R33] CONFIRMAÇÃO DO GRPO (HARD/texto e Z frescas) + DEDUP SEMÂNTICO DA MEMÓRIA (mundo com ecos) + ROBUSTEZ DA PILHA COMPLETA SOB DESLOCAMENTO + DIAGNÓSTICO DO NASH NG9 + REGRESSÃO MEGA/PROLOG | "
               f"N: pilha/GRPO/deslocamento {N['stk']}, memória {N['mem']}, Nash {N['nash']} jogos; Holm: GR 7 + MEM 5 + SH 12 + ND 6; prereg_r33.txt")
    desloc = r33_desloc()
    if desloc:
        rep.log(f"[R33_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r33_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    ok_p = hashlib.sha256(PREREG_R33_CORPO.encode("utf-8")).hexdigest() == PREREG_R33_CORPO_SHA256
    rep.log(f"Pré-registro R33: sha256={PREREG_R33_CORPO_SHA256[:16]}… {'(CONFERE com prereg_r33.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R33_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R33_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R33_CORPO_SHA256
        rep.log(f"Adendo 1 R33: sha256={ADENDO1_R33_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")
    if ADENDO2_R33_TEXTO:
        rep.log(f"Adendo 2 R33: sha256={hashlib.sha256(ADENDO2_R33_TEXTO.encode('utf-8')).hexdigest()[:16]}… — {ADENDO2_R33_TEXTO}")
    r30, r32 = ctx.res.get("r30"), ctx.res.get("r32")
    if not r30 or "rl_sel" not in r30 or not r32 or "pilha" not in r32:
        rep.log("!! resultados dos BLOCOS 38/40 ausentes: o BLOCO 41 precisa do DEV da R30 (rl_sel) e do resultado da R32 (pilha, vereditos, Nash) — abortado")
        ctx.res["r33"] = {"erro": "sem r30/r32"}
        return ctx.res["r33"]
    kal32 = {tn: int(r32["kal"][tn]) for tn in r32["kal"]}
    ok_kal = all(kal32.get(tn) == R33_KAL[tn] for tn in R33_KAL) and sum(R33_KAL.values()) == 17 == sum(R33_KDEF[tn] for tn in R33_STK5)
    rep.log(f"Alocação k CONGELADA (R31, lida do resultado da R32) restrita às 5 tarefas da pilha: {', '.join(f'{tn}:{R33_KAL[tn]}' for tn in R33_STK5)} (Σk = {sum(R33_KAL.values())} = Σk_def) — {'CONFERE com o prereg' if ok_kal else '!! NÃO CONFERE com o prereg'}")
    rl_sel = {a: tuple(r30["rl_sel"][a]) for a in ("ORD", "GRPO")}
    rep.log("PILHA DE PARTIDA (R32): " + ", ".join(f"{k}={v}" for k, v in r32["pilha"].items()) + " (GRPO provisório; testado até aqui só em Z). Esta rodada decide MANTER/RESTRINGIR AO TIPO Z/REVERTER o GRPO, confirma a dedup semântica da memória, mede a robustez da pilha completa e diagnostica o NG9.")

    # ---------------- DEV ----------------
    rep.sub("DEV — lr dos treinadores de texto (ORD, GRPO-H, ORD-G), (θ, c) da dedup semântica")
    nds = 2 if rapido else R33_NDEV["stk"]
    od = mapa_paralelo(r33_job, [("R33DEVH", sd) for sd in S["dev_stk"][:nds]], jobs)
    lr_h, tab_h = {}, {}
    for a in ("ORD", "GRPO", "ORDG"):
        tab_h[a] = {lr: float(np.mean([o[(a, lr, tn)] for o in od for tn in R33_DEV_H_TAREFAS])) for lr in R33_LR_H_GRADE}
        lr_h[a] = max(R33_LR_H_GRADE, key=lambda x: (tab_h[a][x], -x))
        rep.log(f"  lr dos treinadores de texto — {a}: " + ", ".join(f"lr {lr:g}→{v:.3f}" for lr, v in tab_h[a].items()) + f" → lr*={lr_h[a]:g}" + (" (NA BORDA da grade)" if lr_h[a] in (R33_LR_H_GRADE[0], R33_LR_H_GRADE[-1]) else "") + " [r_clean@k=4 médio em H80 e H60; DEV " + f"{S['dev_stk'][0]}–{S['dev_stk'][nds - 1]}]")
    rep.log(f"  lr/hp dos treinadores Z (lidos do DEV da R30, o mesmo esforço de ajuste para os dois): ORD {rl_sel['ORD']}, GRPO {rl_sel['GRPO']}")
    pay = r30_mem_payload(ctx.lake)
    nm_dev = 3 if rapido else R33_NDEV["mem"]
    om = mapa_paralelo(r33_job, [("R33MEM", sd, pay, R33_THETAS, R33_CS) for sd in S["dev_mem"][:nm_dev]], jobs)
    sc_tc = {(th, c): float(np.mean([0.5 * (o["E"][f"D|{th:g}|{c}"]["all"] + o["M0"][f"S|{th:g}"]) for o in om])) for th in R33_THETAS for c in R33_CS}
    theta, c_star = max(sc_tc, key=lambda k: (sc_tc[k], k[0], -k[1]))
    rep.log("  Dedup semântica — DEV (média do acerto geral nos 2 mundos), melhor c por θ: " + ", ".join(f"θ {th:g}→{max(sc_tc[(th, c)] for c in R33_CS):.3f}" for th in R33_THETAS) + f" → (θ*, c*) = ({theta:g}, {c_star})" + (" (θ* NA BORDA da grade)" if theta in (R33_THETAS[0], R33_THETAS[-1]) else "") +
            f" | APPEND {np.mean([o['E']['APPEND']['all'] for o in om]):.3f}, CANON {np.mean([o['E']['CANON']['all'] for o in om]):.3f} (mundo com ecos); RAG {np.mean([o['M0']['A1'] for o in om]):.3f}, canônico {np.mean([o['M0']['A2'] for o in om]):.3f} (mundo R32)")

    # ---------------- TESTE ----------------
    rep.sub("TESTE (sementes RETIDAS) — GRPO, robustez, memória, Nash; regressão")
    t3, i3 = [], []
    for sd in S["stk"][:N["stk"]]:
        t3.append(("R33STK", sd, rl_sel, lr_h)); i3.append(("SK",))
    for sd in S["mem"][:N["mem"]]:
        t3.append(("R33MEM", sd, pay, (theta,), (c_star,))); i3.append(("ME",))
    t3.append(("R33ND", tuple(S["nash"][:N["nash"]]))); i3.append(("ND",))
    n_mega = 200 if rapido else R28_MEGA_TESTE
    for sd in S["mega"]:
        t3.append(("M", sd, n_mega, R28_MEGA_INI, False)); i3.append(("MG",))
    t3.append(("M", S["mega_pos"][0], 200 if rapido else 1000, R28_MEGA_INI, True)); i3.append(("MP",))
    o3 = mapa_paralelo(r33_job, t3, jobs)
    SK, ME, MG, MP, ND = [], [], [], None, None
    for ik, o in zip(i3, o3):
        k = ik[0]
        if k == "SK":
            SK.append(o)
        elif k == "ME":
            ME.append(o)
        elif k == "ND":
            ND = o
        elif k == "MG":
            MG.append(o)
        else:
            MP = o
    ns = len(SK)
    # ---- GR
    mg = lambda a, k_, tns, o: float(np.mean([o["G"][tn][a][k_ if k_ is not None else R33_KDEF[tn]] for tn in tns]))
    arr = lambda f: np.asarray([f(o) for o in SK], float)
    dif = {}
    dif["G1"] = arr(lambda o: mg("GRPO", 4, R33_Z, o) - mg("ORD", 4, R33_Z, o))
    dif["G2"] = arr(lambda o: mg("GRPO", 4, R33_Z_FRESCAS, o) - mg("ORD", 4, R33_Z_FRESCAS, o))
    dif["G3"] = arr(lambda o: mg("GRPO", None, R33_H_DURAS, o) - mg("ORD", None, R33_H_DURAS, o))
    dif["G4"] = arr(lambda o: mg("GRPO", 4, R33_H_FRESCAS, o) - mg("ORD", 4, R33_H_FRESCAS, o))
    dif["G5"] = arr(lambda o: mg("GRPO", 1, R33_H, o) - mg("ORD", 1, R33_H, o))
    dif["G6"] = arr(lambda o: mg("GRPO", 1, R33_Z, o) - mg("ORD", 1, R33_Z, o))
    dif["G7"] = arr(lambda o: mg("GRPO", None, R33_H, o) - mg("ORDG", None, R33_H, o))
    # ---- SH
    def stage(o, c, e):
        sh = o["SH"]
        if e == "BASE":
            return float(np.mean([sh[tn][c]["BASE"][4] for tn in R33_STK5]))
        if e == "F":
            return float(np.mean([sh[tn][c]["F"][R33_KDEF[tn]] for tn in R33_STK5]))
        if e == "KA":
            return float(np.mean([sh[tn][c]["F"][R33_KAL[tn]] for tn in R33_STK5]))
        return float(np.mean([sh[tn][c]["FULL"][R33_KAL[tn]] for tn in R33_STK5]))
    for c in R33_CONDS:
        dif[f"ST_FILT_{c}"] = arr(lambda o: stage(o, c, "F") - stage(o, c, "BASE"))
        dif[f"ST_KA_{c}"] = arr(lambda o: stage(o, c, "KA") - stage(o, c, "F"))
        dif[f"ST_GRPO_{c}"] = arr(lambda o: stage(o, c, "FULL") - stage(o, c, "KA"))
        dif[f"TOT_{c}"] = arr(lambda o: stage(o, c, "FULL") - stage(o, c, "BASE"))
    # ---- MEM
    ka = f"D|{theta:g}|{c_star}"
    me = lambda f: np.asarray([f(o) for o in ME], float)
    dif["M0"] = me(lambda o: o["M0"][f"S|{theta:g}"] - o["M0"]["A1"])
    dif["M1"] = me(lambda o: o["E"][ka]["all"] - o["E"]["APPEND"]["all"])
    dif["M2"] = me(lambda o: o["E"][ka]["all"] - o["E"]["CANON"]["all"])
    dif["M3"] = me(lambda o: o["E"][ka]["d2"] - o["E"]["APPEND"]["d2"])
    dif["M4"] = me(lambda o: o["E"][ka]["d2"] - o["E"]["CANON"]["d2"])
    # ---- ND
    ga1 = np.asarray(ND["ga1"], bool)
    for h, key in (("ND2", "rs4"), ("ND3", "rs4eq"), ("ND4", "ann_h"), ("ND5", "ann_n")):
        dif[h] = np.asarray(ND[key], float) - ga1.astype(float)
    falhas = ~ga1
    n1, k1 = int(falhas.sum()), int(np.asarray(ND["nash_ga1"], bool)[falhas].sum())
    uni = np.asarray(ND["n_nash"]) == 1
    n6, k6 = int(uni.sum()), int(ga1[uni].sum())
    P, st, cons = {}, {}, {}
    for h in R33_TODAS:
        if h in ("ND1", "ND6"):
            continue
        P[h] = r25_pack(dif[h], seed=r33_crc(h))
        cons[h] = r32_consistente(dif[h]) if h not in R33_HIPOT_ND else None
    cnd = {"ND1": (k1, n1, 0.9), "ND6": (k6, n6, 0.95)}
    dirnd = {}
    for h, (k_, n_, c_) in cnd.items():
        p_, dr_ = r31_binom_nash(k_, n_, c_) if n_ > 0 else (1.0, "conf")
        if h == "ND1" and n_ < 10:
            p_ = 1.0
        lo_, hi_ = r31_wilson(k_, n_)
        P[h] = {"media": (k_ / n_ - c_) if n_ > 0 else 0.0, "lo": lo_ - c_, "hi": hi_ - c_, "p": float(p_), "mde": float("nan"), "dz": float("nan")}
        dirnd[h] = dr_
    for fam in (R33_HIPOT_GR, R33_HIPOT_MEM, R33_HIPOT_SH, R33_HIPOT_ND):
        ph = holm([P[h]["p"] for h in fam])
        for i, h in enumerate(fam):
            P[h]["p_holm"] = float(ph[i])
            if h in cnd:
                st[h] = "nula (poucas falhas: sem poder)" if (h == "ND1" and cnd[h][1] < 10) else r31_status_nash(dirnd[h], ph[i])
            else:
                st[h] = r31_status(h, P[h]["media"], ph[i], dif[h])
    for h in R33_HIPOT_ND:
        cons.pop(h, None)
    for h in cnd:
        pass
    # ---------- vereditos e pilha ----------
    ver_novos = r33_vereditos(st)
    ver_comp = {k: ver_novos[k] for k in R33_COMP_NOVOS}
    ver = dict(r32["ver"])
    ver.update(ver_comp)
    pilha, notas = r33_pilha_resultante(r32["pilha"], ver_novos)
    permitido = r33_permitido(ver_novos, r32["permitido"])
    ev_novos = r33_veredito_texto(ver_novos, st, P, cons)
    ev = dict(r32.get("ev") or {})
    ev.update(ev_novos)
    rob = {e: r33_rotulo_robustez(st, e) for e in R33_ETAPAS}
    sustenta = st["TOT_ENT"] == "confirmada" and st["TOT_VER"] == "confirmada"
    ver_sh33 = ("ROBUSTEZ R33: " + "; ".join(f"{R33_SH_ROT[e]} {rob[e]}" for e in R33_ETAPAS) + f" | pilha completa vs RL ordinário+porta: ID {st['TOT_ID']}, ENTRADA {st['TOT_ENT']}, VERIFICADOR {st['TOT_VER']} → " + ("SE SUSTENTA sob deslocamento" if sustenta else "NÃO se sustenta sob os dois deslocamentos"))
    # ---------- Mega regressão ----------
    Y = r28_mega_onehot([d[1] for d in r18_mega_draws()])
    Sm = np.mean([o["stack"] for o in MG], axis=0); Rm = np.mean([o["random"] for o in MG], axis=0); Fm = r28_mega_freq(Y, n_mega)
    z_sr, z_sf = r28_z_dif(Sm - Rm)[0], r28_z_dif(Sm - Fm)[0]
    nposte = 200 if rapido else 1000
    zp_s = r28_z_dif(np.asarray(MP["stack"]) - np.asarray(MP["random"]))[0]
    Yp = r28_mega_onehot(r28_mega_viesada(S["mega_pos"][0], 700 if rapido else 1500))
    zp_f = r28_z_dif(r28_mega_freq(Yp, nposte) - np.asarray(MP["random"]))[0]
    ver_mega33 = r29_regra_mega([z_sr, z_sf], zp_s, zp_f)
    # ---------- Prolog ----------
    vt = r33_versao_nexus()
    st_all = dict(st)
    for rk in ("r28", "r29", "r30", "r31", "r32"):
        rr = ctx.res.get(rk) or {}
        for h in rr.get("chaves", []):
            st_all[rk + "_" + h] = rr.get("st", {}).get(h, "registrada")
    status_nash = {h.lower(): s_ for h, s_ in r32["st_nash"].items()}
    alega = [h.lower() for h, s_ in r32["st_nash"].items() if s_ == "confirmada"]
    kdef_soma = sum(r31_kdef(R32_MODO_TAREFA[tn]) for tn in R32_TAREFAS)
    ctx.res["r33"] = {"ver_novos": dict(ver_comp), "ev_novos": dict(ev_novos), "decisao_grpo": ver_novos["decisao_grpo"], "ver_sh33": ver_sh33, "ver_mega33": ver_mega33, "ver_verif33": "", "ver_nd33": ""}
    bc = r33_bc_do_run(ctx, st_all, vt, ver, pilha, permitido, kal32, kdef_soma, status_nash, alega)
    viol = r31_checar_prolog(r31_bc_texto(bc))
    viol_py = r31_checar_py(bc)
    nm_ = 12 if rapido else 96
    val = r33_validar_verificador(bc, nm_, nm_, S["p_mut"], S["p_ctl"])
    nx_ok, nx_txt = r33_nexus_verificar(pilha, permitido, bc["na_pilha"], ver)
    inv_ok = (not viol) and (not viol_py)
    val_ok = val["detectados"] == val["n_mut"] and val["falsos_alarmes"] == 0 and val["concordancia"] == val["n_total"]
    prolog_ok = inv_ok and val_ok and (nx_ok is not False)
    ver_verif33 = (("VERIFICADOR R33: PASSA — BC genuína sem violações (Prolog e Python independente), " if inv_ok else "VERIFICADOR R33: FALHA — violações na BC genuína: " + ", ".join(viol or viol_py) + "; ") +
                   f"mutantes detectados {val['detectados']}/{val['n_mut']}, falsos alarmes {val['falsos_alarmes']}/{val['n_ctl']}, concordância Prolog×Python {val['concordancia']}/{val['n_total']}; {nx_txt}")
    # ---------- descritivos ----------
    g_t = lambda tn, a, k_: float(np.mean([o["G"][tn][a][k_] for o in SK]))
    ng = len(ND["ga1"])
    nn = np.asarray(ND["n_nash"])
    wil = lambda arr_: (lambda k_, n_: (k_ / n_, *r31_wilson(k_, n_)))(int(np.asarray(arr_, bool).sum()), len(arr_))
    nd_taxas = {k_: wil(ND[k_]) for k_ in ("ga1", "rs4", "rs4eq", "rs16", "ann_h", "ann_n")}
    p_ng9, dir_ng9 = r31_binom_nash(int(ga1.sum()), ng, 0.8)
    ver_nd33 = ("DIAGNÓSTICO NG9 (R33): " + "; ".join(f"{h} {st[h]}" for h in R33_HIPOT_ND) + f" | sucesso GA1 {nd_taxas['ga1'][0]:.2f}, RS4 {nd_taxas['rs4'][0]:.2f}, RS4EQ {nd_taxas['rs4eq'][0]:.2f}, RS16 {nd_taxas['rs16'][0]:.2f}, recozimento entropia {nd_taxas['ann_h'][0]:.2f}, ruído {nd_taxas['ann_n'][0]:.2f}")
    ctx.res["r33"]["ver_nd33"] = ver_nd33
    ctx.res["r33"]["ver_verif33"] = ver_verif33

    rep.sub("RESULTADOS — hipóteses (Holm por família)")
    for h in R33_TODAS:
        p = P[h]
        extra = ""
        if h in R33_HIPOT_GR or h.startswith("ST_") or h.startswith("TOT_"):
            extra = " consistente-metades" if cons.get(h) else " INCONSISTENTE-metades"
        rep.log(f"  {h}: Δ={p['media']:+.4f} IC95%[{p['lo']:+.4f},{p['hi']:+.4f}] p={p['p']:.4f} holm={p['p_holm']:.4f}" + ("" if h in cnd else f" d_z={p['dz']:+.2f} MDE={p['mde']:.4f}") + f" → {st[h]}{extra}")
    rep.log(f"  GRPO × ORD (N={ns}; lr/hp Z do DEV R30: ORD {rl_sel['ORD']}, GRPO {rl_sel['GRPO']}; lr H: " + ", ".join(f"{a} {lr_h[a]:g}" for a in ('ORD', 'GRPO', 'ORDG')) + ") — r_clean@k_def por tarefa (ORD / GRPO" + " / ORD-G em H): " +
            " | ".join(f"{tn}[{R33_MODO[tn]}]: {g_t(tn, 'ORD', R33_KDEF[tn]):.3f}/{g_t(tn, 'GRPO', R33_KDEF[tn]):.3f}" + (f"/{g_t(tn, 'ORDG', R33_KDEF[tn]):.3f}" if tn in R33_H else "") for tn in R33_TAREFAS))
    rep.log("  GRPO × ORD — r_clean@k=1 por tarefa (ORD / GRPO): " + " | ".join(f"{tn}: {g_t(tn, 'ORD', 1):.3f}/{g_t(tn, 'GRPO', 1):.3f}" for tn in R33_TAREFAS) + " | entropia normalizada final em Z (ORD/GRPO): " +
            ", ".join(f"{tn} {np.mean([o['ent'][tn]['ORD'] for o in SK]):.3f}/{np.mean([o['ent'][tn]['GRPO'] for o in SK]):.3f}" for tn in R33_Z) + " (entropia só em Z: o treinador H não tem tabela de estados)")
    rep.log(f"  DECISÃO MECÂNICA SOBRE O GRPO: {ver_novos['decisao_grpo']} (G1 {st['G1']}, G2 {st['G2']}, G3 {st['G3']}, G4 {st['G4']})")
    for c in R33_CONDS:
        rep.log(f"  ROBUSTEZ [{R33_COND_ROT[c]}] — r_clean médio (5 tarefas): BASE {np.mean([stage(o, c, 'BASE') for o in SK]):.3f} | F {np.mean([stage(o, c, 'F') for o in SK]):.3f} | KA {np.mean([stage(o, c, 'KA') for o in SK]):.3f} | FULL {np.mean([stage(o, c, 'FULL') for o in SK]):.3f}")
    rep.log("  ROBUSTEZ — por tarefa (BASE/F/KA/FULL) ID → ENTRADA → VERIFICADOR: " + " | ".join(f"{tn}: " + " → ".join("/".join(f"{np.mean([ {'BASE': o['SH'][tn][c]['BASE'][4], 'F': o['SH'][tn][c]['F'][R33_KDEF[tn]], 'KA': o['SH'][tn][c]['F'][R33_KAL[tn]], 'FULL': o['SH'][tn][c]['FULL'][R33_KAL[tn]]}[e] for o in SK]):.2f}" for e in ('BASE', 'F', 'KA', 'FULL')) for c in R33_CONDS) for tn in R33_STK5))
    rep.log("  RÓTULOS DE ROBUSTEZ (mecânicos; a pilha não muda por eles): " + "; ".join(f"{R33_SH_ROT[e]}: {rob[e]}" for e in R33_ETAPAS) + f" | pilha completa se sustenta (TOT_ENT e TOT_VER confirmadas): {'SIM' if sustenta else 'NÃO'}")
    nME = len(ME)
