def registro_r33(ctx: Contexto) -> list:
    r = ctx.res.get("r33")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R33 (BLOCO 41) — " + " | ".join(f"{f} {a} conf / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: GR 7, MEM 5, SH 12, ND 6; regressão Mega/Prolog)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}" + (" (consistente entre metades)" if r["cons"].get(h) else ""))
    for cid in R33_COMP_NOVOS:
        L.append(f"  veredito {cid}: {r['ev_novos'][cid]}")
    L.append("  pilha resultante: " + ", ".join(f"{k}={v}" for k, v in r["pilha"].items()) + " | " + "; ".join(r["notas"]))
    for k in ("ver_sh33", "ver_nd33", "ver_mega33", "ver_verif33"):
        L.append(f"  {r[k]}")
    return L


def sumario_r33_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r33")
    if not r or "P" not in r:
        return ["R33: (ainda sem resultados nesta execução)"]
    vs = ", ".join(f"{cid}:{r['ver_novos'][cid]}" for cid in R33_COMP_NOVOS)
    return ["R33 BLOCO 41: " + "; ".join(f"{f} {a}/{b}/{c}" for f, (a, b, c) in r["resumo"].items()) + f" | GRPO {r['decisao_grpo']} | vereditos {vs} | {r['ver_sh33'][:110]} | {r['ver_nd33'][:100]} | {r['ver_mega33'][:60]} | {r['ver_verif33'][:70]}"]


def registro_hipoteses_r33(ctx: Contexto) -> list:
    r = ctx.res.get("r33")
    if not r or "P" not in r:
        return []
    desc = r33_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R33", f"R33-{k}", "CONF", desc[k], f"Δ={m:+.4f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f}" + ("" if k in ("ND1", "ND6") else f" d_z={dz:+.2f} MDE={mde:.4f}"), r["st"][k]))
    for nome, ch in (("GRPO e dedup semântica (vereditos)", None), ("robustez sob deslocamento", "ver_sh33"), ("diagnóstico Nash NG9", "ver_nd33"), ("Mega-Sena (regressão)", "ver_mega33"), ("verificador Prolog × vereditos", "ver_verif33")):
        out.append(("R33", f"R33-V[{nome}]", "DESC", f"Veredito: {nome}", (r[ch] if ch else "; ".join(f"{k}:{v}" for k, v in r["ver_novos"].items()) + f" | GRPO {r['decisao_grpo']} | " + "; ".join(r["notas"])), "descritiva"))
    out.append(("R33", "R33-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


