def r34_desloc() -> int:
    v = os.environ.get("R34_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r34_crc(rot: str) -> int:
    return zlib.crc32(f"R34|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r34_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R34_SEEDS.items()}


def r34_binom(k: int, n: int, c: float):
    """Binomial EXATO unilateral por direção (definição única do prereg R34): (p, direção) com direção ∈ conf/ref/nula."""
    if n <= 0 or abs(k / n - c) < 1e-12:
        return 1.0, "nula"
    if k / n > c:
        return r28_binom_cauda(int(k), int(n), c, True), "conf"
    return r28_binom_cauda(int(k), int(n), c, False), "ref"


# ---------------------------------------------------------------------------
# PARTE A — lr em H com a MESMA grade para os três algoritmos
# ---------------------------------------------------------------------------
def r34_job_devh(task):
    """task = ('R34DEVH', seed, lrs): para cada algoritmo H (ORD, GRPO-H, ORD-G), cada lr da lista e cada tarefa de DEV (H80, H60): r_clean@k=4."""
    _, seed, lrs = task
    out = {}
    for tn in R33_DEV_H_TAREFAS:
        tz = r33_tarefa(tn)
        modo = "ON" if R33_MODO[tn] == "ON" else "RAW"
        for lr in lrs:
            pols = {"ORD": r25_treinar(tz, r33_cfg(tn), seed, lr)["pol"], "GRPO": r33_grpo_h(tz, modo, seed, lr), "ORDG": r33_ordg_h(tz, modo, seed, lr)}
            for a, pol in pols.items():
                out[(a, float(lr), tn)] = r33_ev(tz, pol, seed, "R34|dev", 4)[4]
    return out


def r34_escolher_lr(tab: dict, grade) -> dict:
    """Por algoritmo: argmax de tab[a][lr] sobre a grade (empate: menor lr)."""
    return {a: max(grade, key=lambda x: (tab[a][x], -x)) for a in tab}


def r34_precisa_estender(lr_h: dict) -> bool:
    return any(abs(v - R34_LR_GRADE1[-1]) < 1e-12 for v in lr_h.values())


def r34_treina_z(tz, algo: str, seed: int, rl_sel: dict):
    lr, hp = rl_sel[algo]
    return r29_rl_treinar(tz, seed, lr, algo, hp)["pol"]


def r34_treina_h(tz, tn: str, algo: str, seed: int, lr: float):
    modo = "ON" if R33_MODO[tn] == "ON" else "RAW"
    if algo == "ORD":
        return r25_treinar(tz, r33_cfg(tn), seed, lr)["pol"]
    if algo == "GRPO":
        return r33_grpo_h(tz, modo, seed, lr)
    return r33_ordg_h(tz, modo, seed, lr)


def r34_job_stk(task):
    """task = ('R34STK', seed, rl_sel, lr_h). Z (Z7, Z9, ZA): G{ORD, GRPO}; H (5 tarefas): G{ORD, GRPO, ORDG, ORD15}; nas 5 tarefas da pilha: SH (BASE, F, STACK) × (ID, ENT, VER) nos k da alocação."""
    _, seed, rl_sel, lr_h = task
    out = {"seed": int(seed), "G": {}, "SH": {}, "ent": {}}
    pol_all = {}
    for tn in R34_Z + R34_H:
        tz = r33_tarefa(tn)
        if tn in R34_Z:
            pol = {a: r34_treina_z(tz, a, seed, rl_sel) for a in ("ORD", "GRPO")}
            out["ent"][tn] = {a: float(r28_ent_norm(tz, pol[a], seed, f"R34|{a}")) for a in ("ORD", "GRPO")}
        else:
            pol = {a: r34_treina_h(tz, tn, a, seed, lr_h[a]) for a in R34_ALGOS_H}
            pol["ORD15"] = pol["ORD"] if abs(lr_h["ORD"] - R34_LR_TRAV_H) < 1e-12 else r34_treina_h(tz, tn, "ORD", seed, R34_LR_TRAV_H)
        pol_all[tn] = pol
        out["G"][tn] = {a: r33_ev(tz, p, seed, "R34|g", 4) for a, p in pol.items() if not (a == "ORD15" and p is pol["ORD"])}
        if "ORD15" in pol and pol["ORD15"] is pol["ORD"]:
            out["G"][tn]["ORD15"] = out["G"][tn]["ORD"]
    for tn in R34_STK5:
        tz = r33_tarefa(tn)
        lr_l = R28_LR_TRAVADO[tn]
        kmax = max(4, R34_KAL[tn])
        base_pol = r25_treinar(tz, r27_cfg_pf(), seed, lr_l)["pol"]
        if R33_MODO[tn] == "ON":
            f_pol, stack_pol = base_pol, pol_all[tn]["GRPO"]
        else:
            f_pol = pol_all[tn]["ORD15"]          # r25_treinar com r27_cfg_pr e o MESMO lr travado (0,15)
            stack_pol = f_pol
        out["SH"][tn] = {}
        for c in R34_CONDS:
            tc = r33_tarefa_desloc(tz, tn, c)
            ef = r33_ev(tc, f_pol, seed, "R34|sh", kmax)
            eb = ef if base_pol is f_pol else r33_ev(tc, base_pol, seed, "R34|sh", kmax)
            es = ef if stack_pol is f_pol else r33_ev(tc, stack_pol, seed, "R34|sh", kmax)
            out["SH"][tn][c] = {"F": ef, "BASE": eb, "STACK": es}
    return out


# ---------------------------------------------------------------------------
# PARTE C — Nash: cooperativo 3×3 (remédio de reinícios) e soma zero (verificação adversarial)
# ---------------------------------------------------------------------------
def r34_nash_coop(seeds, nin: int = R34_ND_NIN, T: int = R34_ND_T):
    G = len(seeds)
    A = np.zeros((G, 3, 3)); X0 = np.zeros((G, nin, 3)); Y0 = np.zeros((G, nin, 3))
    for gi, s in enumerate(seeds):
        rng = np.random.default_rng([int(s), 34, 2])
        A[gi] = rng.normal(size=(3, 3))
        for j in range(nin):
            X0[gi, j] = rng.dirichlet(np.ones(3)); Y0[gi, j] = rng.dirichlet(np.ones(3))
    Amax = A.reshape(G, 9).max(axis=1)
    pay = lambda X, Y: np.einsum("gni,gij,gnj->gn", X, A, Y)
    ok = lambda p: p >= Amax[:, None] - 0.05
    X, Y = r33_ga(A, X0, Y0, T)
    p = pay(X, Y)
    s_all = ok(p)
    e = (np.einsum("gij,gnj->gni", A, Y).max(axis=2) - p) + (np.einsum("gni,gij->gnj", X, A).max(axis=2) - p)
    out = {"ga1": s_all[:, 0].copy(), "nash_ga1": (e[:, 0] <= 0.05), "basin": s_all.mean(axis=1)}
    best = lambda pp: ok(np.take_along_axis(pp, pp.argmax(axis=1)[:, None], axis=1))[:, 0]
    for k in (2, 4, 8, 16):
        out[f"rs{k}"] = best(p[:, :k]) if k <= nin else best(p)
    X4, Y4 = r33_ga(A, X0[:, :4], Y0[:, :4], R34_ND_TEQ)
    out["rs4eq"] = best(pay(X4, Y4))
    nn = np.zeros(G, int)
    for gi in range(G):
        M = A[gi]
        nn[gi] = int(sum(1 for i in range(3) for j in range(3) if M[i, j] >= M[:, j].max() and M[i, j] >= M[i, :].max()))
    out["n_nash"] = nn
    return out


def r34_nash_zs(seeds, nin: int = R34_ZS_NIN, T: int = R34_ND_T, eta: float = R34_ND_ETA):
    """Soma zero 3×3 (linha maximiza xᵀAy). GDA simultâneo projetado; último estado e média temporal; valor analítico por enumeração de suportes."""
    G = len(seeds)
    A = np.zeros((G, 3, 3)); X = np.zeros((G, nin, 3)); Y = np.zeros((G, nin, 3)); vstar = np.zeros(G)
    for gi, s in enumerate(seeds):
        rng = np.random.default_rng([int(s), 34, 3])
        A[gi] = rng.normal(size=(3, 3))
        for j in range(nin):
            X[gi, j] = rng.dirichlet(np.ones(3)); Y[gi, j] = rng.dirichlet(np.ones(3))
        vstar[gi] = r31_zs_valor(A[gi])[0]
    At = A.transpose(0, 2, 1)
    Xs, Ys = np.zeros_like(X), np.zeros_like(Y)
    for _ in range(T):
        Xs += X; Ys += Y
        gx, gy = Y @ At, -(X @ A)
        X, Y = r33_proj(X + eta * gx), r33_proj(Y + eta * gy)
    Xm, Ym = Xs / T, Ys / T

    def met(Xe, Ye):
        v = np.einsum("gni,gij,gnj->gn", Xe, A, Ye)
        ex = np.einsum("gij,gnj->gni", A, Ye).max(axis=2) - np.einsum("gni,gij->gnj", Xe, A).min(axis=2)
        return v, ex, (ex <= 0.05) & (np.abs(v - vstar[:, None]) <= 0.05)
    v, ex, ok = met(X, Y)
    _vm, _em, okm = met(Xm, Ym)
    iu = v.argmax(axis=1)[:, None]
    ie = ex.argmin(axis=1)[:, None]
    return {"single": ok[:, 0].copy(), "avg": okm[:, 0].copy(), "restart_u": np.take_along_axis(ok, iu, axis=1)[:, 0], "restart_e": np.take_along_axis(ok, ie, axis=1)[:, 0],
            "expl1": ex[:, 0].copy(), "gap1": np.abs(v[:, 0] - vstar), "frac_pure": np.asarray([float(np.max(np.min(A[g], axis=1)) >= np.min(np.max(A[g], axis=0)) - 1e-12) for g in range(G)])}


def r34_job_nd(task):
    return r34_nash_coop(list(task[1]))


def r34_job_nz(task):
    return r34_nash_zs(list(task[1]))


# ---------------------------------------------------------------------------
# PARTE D — consolidação seletiva no «sono»
# ---------------------------------------------------------------------------
class R34Sleep(R27Sym):
    """Tarefa simbólica V=7, L=12, B=8; alvo tgt[a, b] para o próximo símbolo dado os dois anteriores (a, b); r_clean/laudo/ruído seguem o alvo da tarefa."""

    def __init__(self, tgt, nome: str):
        super().__init__({"V": 7, "L": 12, "B": 8, "P": 200, "tau_y": 0.50})
        self.tgt = np.asarray(tgt, int)
        self.nome = nome

    def _ok(self, ids):
        tg = self.tgt
        return np.asarray([1.0 if ids[t] == tg[ids[t - 2], ids[t - 1]] else 0.0 for t in range(2, len(ids))])


def r34_fluxo(seed: int, conflito: bool, cfg=None):
    """4 tarefas. Regra-base (a+b) mod 7; no fluxo com conflito, as tarefas 2–4 redefinem o alvo em 14 de 49 estados (sem reposição) para um valor ≠ base; no controle, as 4 são a regra-base."""
    cfg = cfg or R34_SL
    base = np.asarray([[(a + b) % 7 for b in range(7)] for a in range(7)], int)
    rng = np.random.default_rng([int(seed), 34, 5])
    tgts = [base.copy()]
    for _k in range(1, cfg["tarefas"]):
        t = base.copy()
        if conflito:
            for s_ in rng.choice(49, size=cfg["n_redef"], replace=False):
                a, b = divmod(int(s_), 7)
                t[a, b] = (base[a, b] + int(rng.integers(1, 7))) % 7
        tgts.append(t)
    return [R34Sleep(t, f"R34S{k}") for k, t in enumerate(tgts)]


def r34_acc(tz, pol, seed: int, rot: str, n: int) -> float:
    rng = r25_rng(seed, r34_crc(rot), 7)
    return float(np.mean([tz.r_clean(tz.sample(pol, rng)[0]) for _ in range(n)]))


def r34_sono_run(seed: int, conflito: bool, cfg=None):
    """Treina o fluxo, mede o esquecimento numa sonda independente, define F e roda os braços de sono (todos com o MESMO nº de passos S quando dormem)."""
    cfg = cfg or R34_SL
    P, S, lr, delta = cfg["P_treino"], cfg["S"], cfg["lr"], cfg["delta"]
    tzs = r34_fluxo(seed, conflito, cfg)
    K = len(tzs)
    rng_tr = r25_rng(seed, r34_crc("sono|treino"), 1)
    pol = tzs[0].init_pol(rng_tr)
    base, bases, post = 0.0, [], []
    for k, tz in enumerate(tzs):
        base = r32_passos(tz, pol, seed + 1000003 * (k + 1), rng_tr, 0, P, lr, base)
        bases.append(base)
        post.append(r34_acc(tz, pol, seed, f"sonda|pos|{k}", cfg["n_sonda"]))
    fim = [r34_acc(tz, pol, seed, f"sonda|fim|{k}", cfg["n_sonda"]) for k, tz in enumerate(tzs)]
    forg = [post[k] - fim[k] for k in range(K)]
    F = [k for k in range(K) if forg[k] >= delta]
    rng_a = np.random.default_rng([int(seed), 34, 6])
    alea = sorted(int(x) for x in rng_a.choice(K, size=len(F), replace=False)) if F else []
    listas = {"NADA": [], "ULTIMA": [K - 1], "TODAS": list(range(K)), "SEL": list(F), "ALEA": alea}
    bracos = ("NADA", "ULTIMA", "TODAS", "SEL", "ALEA") if conflito else ("NADA", "TODAS", "SEL")
    accs, steps, acc_t = {}, {}, {}
    for nome in bracos:
        lst = listas[nome]
        p2 = {"W": pol["W"].copy(), "V": pol["V"]}
        if lst:
            rngS = r25_rng(seed, r34_crc("sono|" + nome), 3)
            b = {k: bases[k] for k in range(K)}
            for j in range(S):
                k = lst[j % len(lst)]
                b[k] = r32_passos(tzs[k], p2, seed + 2000003 * (k + 1), rngS, 1000 + j, 1, lr, b[k])
        steps[nome] = S if lst else 0
        acc_t[nome] = [r34_acc(tz, p2, seed, f"final|{k}", cfg["n_final"]) for k, tz in enumerate(tzs)]
        accs[nome] = float(np.mean(acc_t[nome]))
    return {"F": F, "forg": forg, "post": post, "fim": fim, "acc": accs, "steps": steps, "acc_t": acc_t, "lista_alea": alea}


def r34_job_sl(task):
    _, seed, conflito = task[:3]
    expl = bool(task[3]) if len(task) > 3 else False
    return r34_sono_run(seed, bool(conflito), R34_SL_EXPL if expl else None)


# ---------------------------------------------------------------------------
# despacho
# ---------------------------------------------------------------------------
def r34_job(task):
    k = task[0]
    if k == "R34STK":
        return r34_job_stk(task)
    if k == "R34DEVH":
        return r34_job_devh(task)
    if k == "R34ND":
        return r34_job_nd(task)
    if k == "R34NZ":
        return r34_job_nz(task)
    if k == "R34SL":
        return r34_job_sl(task)
    return r33_job(task)


# ---------------------------------------------------------------------------
# vereditos e pilha (regras mecânicas das Partes A e D do prereg)
# ---------------------------------------------------------------------------
def r34_decisao_grpo(st: dict) -> str:
    if st["Q1"] == "confirmada" and st["Q3"] == "confirmada" and st["Q4"] == "confirmada" and st["Q6"] != "refutada":
        return "ESTENDER"
    if st["Q1"] == "confirmada":
        return "RESTRINGIR_Z"
    return "REVERTER"


def r34_vereditos(st: dict) -> dict:
    dec = r34_decisao_grpo(st)
    if dec in ("ESTENDER", "RESTRINGIR_Z"):
        g = "vivo"
    elif st["Q1"] == "refutada":
        g = "nocivo"
    else:
        g = "decorativo"
    if st["SL1"] == "confirmada" and st["SL2"] == "confirmada" and st["SL3"] == "confirmada" and st["SL4"] != "refutada" and st["SL5"] == "confirmada":
        s = "vivo"
    elif any(st[h] == "refutada" for h in ("SL1", "SL2", "SL3")):
        s = "nocivo"
    else:
        s = "decorativo"
    return {"grpo": g, "sono_seletivo": s, "decisao_grpo": dec}


def r34_pilha_resultante(pil33: dict, ver: dict) -> tuple:
    notas = []
    pil = dict(pil33)
    dec = ver["decisao_grpo"]
    if dec == "ESTENDER":
        pil["rl"] = "grpo"; notas.append("A: GRPO ESTENDIDO ao texto (Q1, Q3, Q4 confirmadas; Q6 não refutada) → rl=grpo em Z e H")
    elif dec == "RESTRINGIR_Z":
        pil["rl"] = "grpo_z"; notas.append("A: a restrição CONTINUA: GRPO só no tipo Z (Q1 confirmada; não estende ao texto) → rl=grpo_z; tarefas H usam o RL ordinário")
    else:
        pil["rl"] = "ordinario"; notas.append("A: GRPO REVERTIDO (Q1 nula ou refutada) → a pilha volta ao RL ordinário")
    if ver["sono_seletivo"] == "vivo":
        pil["continuo"] = "sono_seletivo"; notas.append("D: sono seletivo VIVO (SL1, SL2, SL3, SL5 confirmadas; SL4 não refutada) → ENTRA como componente de fluxos não estacionários (provisório)")
    else:
        pil.pop("continuo", None); notas.append(f"D: sono seletivo {ver['sono_seletivo'].upper()} → fica FORA")
    return pil, notas


def r34_permitido(ver: dict, per33: dict) -> dict:
    """Derivação INDEPENDENTE (por campo) a partir do permitido da R33."""
    per = {k: v for k, v in per33.items() if k not in ("rl", "continuo")}
    per["rl"] = {"ESTENDER": "grpo", "RESTRINGIR_Z": "grpo_z"}.get(ver["decisao_grpo"], "ordinario")
    if ver["sono_seletivo"] == "vivo":
        per["continuo"] = "sono_seletivo"
    return per


def r34_na_pilha(pil: dict) -> list:
    na = r33_na_pilha({k: v for k, v in pil.items() if k != "continuo"})
    if pil.get("continuo") == "sono_seletivo":
        na.append("sono_seletivo")
    return na


def r34_bc(linhas_mapa, st_hip, pilha, permitido, custo, versao, esperada, ver, status_nash, alega):
    pil_b = dict(pilha, rl=("ordinario" if pilha["rl"] == "grpo_z" else pilha["rl"]))
    pil_b.pop("continuo", None)
    per_b = {k: v for k, v in permitido.items() if k != "continuo"}
    bc = r31_bc(linhas_mapa, st_hip, pil_b, per_b, custo, versao, esperada, ver, status_nash, alega)
    bc["stack"] = dict(pilha)
    bc["permitido"] = dict(permitido)
    bc["na_pilha"] = r34_na_pilha(pilha)
    for c in bc["na_pilha"]:
        bc["estado"].setdefault(c, ["ativo"])
        bc["evidencia"] = sorted(set(bc["evidencia"]) | {c})
    bc["opcional"] = sorted(set(bc["opcional"]) | set(R32_OPCIONAIS_EXTRA) | set(R33_OPCIONAIS_EXTRA) | set(R34_OPCIONAIS_EXTRA))
    bc["avaliado"] = sorted(ver)
    return bc


def r34_mutar(bc: dict, tipo: int, rng):
    return r33_mutar(bc, tipo, rng)


def r34_validar_verificador(bc: dict, n_mut: int, n_ctl: int, seeds_mut, seeds_ctl):
    det, conc, tipos, fa = 0, 0, {}, 0
    for i in range(n_mut):
        rng = r25_rng(seeds_mut[i], r31_crc("mut"), i)
        bm, tp = r34_mutar(bc, i, rng)
        vp, vy = r31_checar_prolog(r31_bc_texto(bm)), r31_checar_py(bm)
        det += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
        tipos.setdefault(tp, [0, 0]); tipos[tp][0] += 1; tipos[tp][1] += 1 if vp else 0
    for i in range(n_ctl):
        rng = r25_rng(seeds_ctl[i], r31_crc("ctl"), i)
        vp, vy = r31_checar_prolog(r31_bc_texto(bc, rng, benigno=True)), r31_checar_py(bc)
        fa += 1 if vp else 0
        conc += 1 if (bool(vp) == bool(vy)) else 0
    return {"detectados": det, "n_mut": n_mut, "falsos_alarmes": fa, "n_ctl": n_ctl, "concordancia": conc, "n_total": n_mut + n_ctl, "tipos": tipos}


