R28_ID_CANON.update({"lr do GRPO no texto (R35)": "grpo_texto", "pilha nova sob deslocamento (R35)": "pilha_nova", "sono em regime com esquecimento (R35)": "sono_real", "soma zero: OGDA/EG (R35)": "oz"})


def r35_desloc() -> int:
    v = os.environ.get("R35_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r35_crc(rot: str) -> int:
    return zlib.crc32(f"R35|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r35_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R35_SEEDS.items()}


# ---------------------------------------------------------------------------
# PARTES A e B — um job por semente (tarefas Z7, Z9 e as 5 de texto)
# ---------------------------------------------------------------------------
def r35_job_stk(task):
    """task = ('R35STK', seed, rl_sel, lr_h, lr_txt). G[tn][(algo, lr)] = r_clean aninhado (k=1,2,4) sem deslocamento (texto: braços do lr escolhido e da varredura fixa);
    SH[tn][cond][pol] (pol ∈ BASE, F, LRM, STK) nas 5 tarefas da pilha, nos k de max(4, k alocada)."""
    _, seed, rl_sel, lr_h, lr_txt = task
    out = {"seed": int(seed), "G": {}, "SH": {}}
    cache = {}

    def pol_h(tn, tz, algo, lr):
        key = (tn, algo, float(lr))
        if key not in cache:
            cache[key] = r34_treina_h(tz, tn, algo, seed, float(lr))
        return cache[key]
    for tn in R35_Z:
        tz = r33_tarefa(tn)
        kmax = max(4, R35_KAL[tn])
        base_pol = r25_treinar(tz, r27_cfg_pf(), seed, R28_LR_TRAVADO[tn])["pol"]
        grpo_pol = r34_treina_z(tz, "GRPO", seed, rl_sel)
        out["SH"][tn] = {}
        for c in R35_CONDS:
            tc = r33_tarefa_desloc(tz, tn, c)
            eb = r33_ev(tc, base_pol, seed, "R35|sh", kmax)
            es = r33_ev(tc, grpo_pol, seed, "R35|sh", kmax)
            out["SH"][tn][c] = {"BASE": eb, "F": eb, "LRM": eb, "STK": es}
    for tn in R35_H:
        tz = r33_tarefa(tn)
        out["G"][tn] = {}
        arms = [("ORD", lr_h["ORD"]), ("GRPO", lr_h["GRPO"]), ("ORDG", lr_h["ORDG"])]
        if tn in R35_H3:
            arms += [(a, lr) for a in ("ORD", "GRPO") for lr in R35_LR_FIXO]
            arms += [("ORD", lr_txt), ("GRPO", lr_txt), ("ORD", R35_LR_TRAV_H)]
        evc = {}
        for a, lr in arms:
            key = (a, float(lr))
            if key not in evc:
                evc[key] = r33_ev(tz, pol_h(tn, tz, a, lr), seed, "R35|g", 4)
            out["G"][tn][key] = evc[key]
        if tn not in R35_H3:
            continue
        kmax = max(4, R35_KAL[tn])
        base_pol = r25_treinar(tz, r27_cfg_pf(), seed, R35_LR_TRAV_H)["pol"]
        pols = {"BASE": base_pol, "F": pol_h(tn, tz, "ORD", R35_LR_TRAV_H), "LRM": pol_h(tn, tz, "ORD", lr_txt), "STK": pol_h(tn, tz, "GRPO", lr_txt)}
        out["SH"][tn] = {}
        for c in R35_CONDS:
            tc = r33_tarefa_desloc(tz, tn, c)
            row = {}
            for nome, p in pols.items():
                if c == "ID" and nome == "F":
                    row[nome] = evc[("ORD", float(R35_LR_TRAV_H))]
                elif c == "ID" and nome == "LRM":
                    row[nome] = evc[("ORD", float(lr_txt))]
                elif c == "ID" and nome == "STK":
                    row[nome] = evc[("GRPO", float(lr_txt))]
                else:
                    row[nome] = r33_ev(tc, p, seed, "R35|sh", kmax)
            out["SH"][tn][c] = row
    return out


# ---------------------------------------------------------------------------
# PARTE C — sono seletivo em regime com esquecimento real
# ---------------------------------------------------------------------------
def r35_fluxo(seed: int, conflito: bool, cfg=None):
    """4 tarefas sobre a regra-base (a+b) mod 7. Conflito: m estados DISPUTADOS (sem reposição, gerador (s,35,5)), cada um com um valor alternativo fixo ≠ base; as tarefas 2–4 escolhem, independentemente por
    estado disputado, o alternativo (prob. 0,5) ou a base (prob. 0,5). Controle: as 4 tarefas são a regra-base."""
    cfg = cfg or R35_SL
    base = np.asarray([[(a + b) % 7 for b in range(7)] for a in range(7)], int)
    tgts = [base.copy()]
    rng = np.random.default_rng([int(seed), 35, 5])
    pool, alt = [], {}
    if conflito:
        pool = [int(x) for x in rng.permutation(49)[:int(cfg["n_pool"])]]
        for s_ in pool:
            a, b = divmod(s_, 7)
            alt[s_] = (int(base[a, b]) + int(rng.integers(1, 7))) % 7
    for _k in range(1, cfg["tarefas"]):
        t = base.copy()
        for s_ in pool:
            a, b = divmod(s_, 7)
            if rng.random() < 0.5:
                t[a, b] = alt[s_]
        tgts.append(t)
    return [R34Sleep(t, f"R35S{k}") for k, t in enumerate(tgts)]


def r35_sono_run(seed: int, conflito: bool, cfg=None, so_forg: bool = False):
    """Como r34_sono_run, com o fluxo r35_fluxo. so_forg=True: só treino + sonda (DEV dos desenhos; braço NADA)."""
    cfg = cfg or R35_SL
    P, S, lr, delta = cfg["P_treino"], cfg["S"], cfg["lr"], cfg["delta"]
    tzs = r35_fluxo(seed, conflito, cfg)
    K = len(tzs)
    rng_tr = r25_rng(seed, r35_crc("sono|treino"), 1)
    pol = tzs[0].init_pol(rng_tr)
    base, bases, post = 0.0, [], []
    for k, tz in enumerate(tzs):
        base = r32_passos(tz, pol, seed + 1000003 * (k + 1), rng_tr, 0, P, lr, base)
        bases.append(base)
        post.append(r34_acc(tz, pol, seed, f"sonda|pos|{k}", cfg["n_sonda"]))
    fim = [r34_acc(tz, pol, seed, f"sonda|fim|{k}", cfg["n_sonda"]) for k, tz in enumerate(tzs)]
    forg = [post[k] - fim[k] for k in range(K)]
    F = [k for k in range(K) if forg[k] >= delta]
    if so_forg:
        return {"F": F, "forg": forg, "post": post, "fim": fim}
    rng_a = np.random.default_rng([int(seed), 35, 6])
    alea = sorted(int(x) for x in rng_a.choice(K, size=len(F), replace=False)) if F else []
    listas = {"NADA": [], "ULTIMA": [K - 1], "TODAS": list(range(K)), "SEL": list(F), "ALEA": alea}
    bracos = ("NADA", "ULTIMA", "TODAS", "SEL", "ALEA") if conflito else ("NADA", "TODAS", "SEL")
    accs, steps, acc_t = {}, {}, {}
    for nome in bracos:
        lst = listas[nome]
        p2 = {"W": pol["W"].copy(), "V": pol["V"]}
        if lst:
            rngS = r25_rng(seed, r35_crc("sono|" + nome), 3)
            b = {k: bases[k] for k in range(K)}
            for j in range(S):
                k = lst[j % len(lst)]
                b[k] = r32_passos(tzs[k], p2, seed + 2000003 * (k + 1), rngS, 1000 + j, 1, lr, b[k])
        steps[nome] = S if lst else 0
        acc_t[nome] = [r34_acc(tz, p2, seed, f"final|{k}", cfg["n_final"]) for k, tz in enumerate(tzs)]
        accs[nome] = float(np.mean(acc_t[nome]))
    return {"F": F, "forg": forg, "post": post, "fim": fim, "acc": accs, "steps": steps, "acc_t": acc_t, "lista_alea": alea}


def r35_cfg_sono(m: int, P: int) -> dict:
    return dict(R35_SL, n_pool=int(m), P_treino=int(P))


def r35_job_devs(task):
    """task = ('R35DEVS', seed, nome, m, P): treino + sonda no desenho (m, P) com conflito (braço NADA)."""
    _, seed, nome, m, P = task
    o = r35_sono_run(int(seed), True, r35_cfg_sono(m, P), so_forg=True)
    return {"nome": nome, "forg": o["forg"], "F": o["F"]}


def r35_job_sl(task):
    """task = ('R35SL', seed, conflito, m, P)."""
    _, seed, conflito, m, P = task
    return r35_sono_run(int(seed), bool(conflito), r35_cfg_sono(m, P))


def r35_escolher_desenho(tab: dict) -> tuple:
    """tab[nome] = (média do esquecimento das tarefas 1–3, fração de fluxos com F não vazio). Primeiro desenho (ordem D1…D4) que passa; senão o de maior esquecimento (passou=False)."""
    for nome, _m, _P in R35_DESENHOS:
        if nome in tab and tab[nome][0] >= R35_DEV_SL["forg_min"] and tab[nome][1] >= R35_DEV_SL["frac_f_min"]:
            return nome, True
    nomes = [d[0] for d in R35_DESENHOS if d[0] in tab]
    return max(nomes, key=lambda n: (tab[n][0], -nomes.index(n))), False


# ---------------------------------------------------------------------------
# PARTE D — soma zero: GDA × OGDA × EG
# ---------------------------------------------------------------------------
def r35_zs_dyn(A, X0, Y0, T: int, eta: float, kind: str):
    """Dinâmica simultânea projetada em jogos soma-zero (A: (G,3,3); X0, Y0: (G,n,3)); kind ∈ GDA, OGDA, EG. Retorna (X_T, Y_T, média das T iteradas que antecedem cada passo, estado em T/2)."""
    At = A.transpose(0, 2, 1)
    X, Y = X0.copy(), Y0.copy()
    Xs, Ys = np.zeros_like(X), np.zeros_like(Y)
    gxp = gyp = None
    half = None
    for t in range(T):
        if t == T // 2:
            half = (X.copy(), Y.copy())
        Xs += X
        Ys += Y
        gx, gy = Y @ At, -(X @ A)
        if kind == "GDA":
            Xn, Yn = r33_proj(X + eta * gx), r33_proj(Y + eta * gy)
        elif kind == "OGDA":
            if gxp is None:
                gxp, gyp = gx, gy
            Xn, Yn = r33_proj(X + 2.0 * eta * gx - eta * gxp), r33_proj(Y + 2.0 * eta * gy - eta * gyp)
            gxp, gyp = gx, gy
        else:
            Xh, Yh = r33_proj(X + eta * gx), r33_proj(Y + eta * gy)
            Xn, Yn = r33_proj(X + eta * (Yh @ At)), r33_proj(Y + eta * (-(Xh @ A)))
        X, Y = Xn, Yn
    return X, Y, Xs / T, Ys / T, half


def r35_nash_zs(seeds, nin: int = R35_ZS_NIN, T: int = R35_ZS_T, eta: float = R35_ZS_ETA):
    G = len(seeds)
    A = np.zeros((G, 3, 3)); X0 = np.zeros((G, nin, 3)); Y0 = np.zeros((G, nin, 3)); vstar = np.zeros(G)
    xs, ys = np.zeros((G, 3)), np.zeros((G, 3))
    for gi, s in enumerate(seeds):
        rng = np.random.default_rng([int(s), 35, 3])
        A[gi] = rng.normal(size=(3, 3))
        for j in range(nin):
            X0[gi, j] = rng.dirichlet(np.ones(3)); Y0[gi, j] = rng.dirichlet(np.ones(3))
        v_, xs[gi], ys[gi] = r31_zs_valor(A[gi])
        vstar[gi] = v_

    def met(Xe, Ye):
        v = np.einsum("gni,gij,gnj->gn", Xe, A, Ye)
        ex = np.einsum("gij,gnj->gni", A, Ye).max(axis=2) - np.einsum("gni,gij->gnj", Xe, A).min(axis=2)
        return v, ex, (ex <= 0.05) & (np.abs(v - vstar[:, None]) <= 0.05)
    out = {"vstar": vstar}
    for k in ("GDA", "OGDA", "EG"):
        X, Y, Xm, Ym, hf = r35_zs_dyn(A, X0, Y0, T, eta, k)
        _v, ex, ok = met(X, Y)
        _vm, _em, okm = met(Xm, Ym)
        _vh, exh, _okh = met(hf[0], hf[1])
        out[k] = {"last": ok[:, 0].copy(), "avg": okm[:, 0].copy(), "last_all": ok.mean(axis=1), "avg_all": okm.mean(axis=1), "ex": ex[:, 0].copy(), "ex_half": exh[:, 0].copy(),
                  "dist": (np.abs(X[:, 0] - xs).sum(axis=1) + np.abs(Y[:, 0] - ys).sum(axis=1))}
    puro = np.asarray([float(np.max(np.min(A[g], axis=1)) >= np.min(np.max(A[g], axis=0)) - 1e-12) for g in range(G)])
    out["pure"] = puro
    out["full"] = np.asarray([float((xs[g] > 1e-9).all() and (ys[g] > 1e-9).all()) for g in range(G)])
    return out


def r35_sem_decaimento(ex_T, ex_h):
    return (ex_T >= 0.9 * ex_h) & (ex_T > 0.05)


def r35_decai(ex_T, ex_h):
    return (ex_T <= 0.5 * ex_h) | (ex_T <= 1e-6)


def r35_job_nz(task):
    return r35_nash_zs(list(task[1]))


# ---------------------------------------------------------------------------
# despacho
# ---------------------------------------------------------------------------
def r35_job(task):
    k = task[0]
    if k == "R35STK":
        return r35_job_stk(task)
    if k == "R35DEVH":
        return r34_job_devh(("R34DEVH",) + tuple(task[1:]))
    if k == "R35DEVS":
        return r35_job_devs(task)
    if k == "R35SL":
        return r35_job_sl(task)
    if k == "R35NZ":
        return r35_job_nz(task)
    return r34_job(task)


# ---------------------------------------------------------------------------
# vereditos e pilha (regras mecânicas das Partes A e C do prereg)
# ---------------------------------------------------------------------------
def r35_texto_sobrevive(st: dict) -> str:
    if st["LX1"] == "confirmada" and st["LX2"] == "confirmada" and st["LX3"] != "refutada":
        return "SOBREVIVE"
    if st["LX1"] == "refutada":
        return "INVERTE"
    return "NULO"


def r35_decisao_grpo(st: dict) -> str:
    if st["LX8"] != "confirmada":
        return "SAIR"
    if r35_texto_sobrevive(st) == "SOBREVIVE" and st["ALG_ENT"] != "refutada" and st["ALG_VER"] != "refutada":
        return "MANTER"
    return "RESTRINGIR_Z"


def r35_vereditos(st: dict, gate_ok: bool) -> dict:
    dec = r35_decisao_grpo(st)
    if dec in ("MANTER", "RESTRINGIR_Z"):
        g = "vivo"
    elif st["LX8"] == "refutada":
        g = "nocivo"
    else:
        g = "decorativo"
    ts = r35_texto_sobrevive(st)
    gt = {"SOBREVIVE": "vivo", "INVERTE": "nocivo", "NULO": "decorativo"}[ts]
    if not gate_ok:
        s = "inconclusivo"
    elif st["FS1"] == "confirmada" and st["FS2"] == "confirmada" and st["FS3"] == "confirmada" and st["FS4"] != "refutada" and st["FS5"] == "confirmada":
        s = "vivo"
    elif any(st[h] == "refutada" for h in ("FS1", "FS2", "FS3")):
        s = "nocivo"
    else:
        s = "decorativo"
    return {"grpo": g, "grpo_texto": gt, "sono_seletivo": s, "decisao_grpo": dec, "texto": ts}


def r35_ver_kb(ver_novos: dict) -> dict:
    """Vereditos para o verificador Prolog: «inconclusivo» entra como decorativo (fora da pilha)."""
    return {"grpo": ver_novos["grpo"], "sono_seletivo": ("decorativo" if ver_novos["sono_seletivo"] == "inconclusivo" else ver_novos["sono_seletivo"])}


def r35_pilha_resultante(pil34: dict, ver: dict) -> tuple:
    notas = []
    pil = dict(pil34)
    dec = ver["decisao_grpo"]
    if dec == "MANTER":
        pil["rl"] = "grpo"; notas.append("A: GRPO MANTIDO também no texto (LX8 confirmada; efeito no texto SOBREVIVE à grade estendida; ALG_ENT e ALG_VER não refutadas) → rl=grpo")
    elif dec == "RESTRINGIR_Z":
        pil["rl"] = "grpo_z"; notas.append("A: GRPO RESTRITO ao tipo Z (LX8 confirmada; o efeito no texto não sobrevive à grade estendida ou quebra sob deslocamento) → rl=grpo_z; tarefas H voltam ao RL ordinário")
    else:
        pil["rl"] = "ordinario"; notas.append("A: GRPO SAI da pilha (LX8 não confirmada) → rl=ordinario")
    if ver["sono_seletivo"] == "vivo":
        pil["continuo"] = "sono_seletivo"; notas.append("C: sono seletivo VIVO em regime com esquecimento real → ENTRA como componente de fluxos não estacionários (provisório)")
    else:
        pil.pop("continuo", None); notas.append(f"C: sono seletivo {ver['sono_seletivo'].upper()} → fica FORA")
    return pil, notas


def r35_permitido(ver: dict, per34: dict) -> dict:
    per = {k: v for k, v in per34.items() if k not in ("rl", "continuo")}
    per["rl"] = {"MANTER": "grpo", "RESTRINGIR_Z": "grpo_z"}.get(ver["decisao_grpo"], "ordinario")
    if ver["sono_seletivo"] == "vivo":
        per["continuo"] = "sono_seletivo"
    return per


