def r35_linhas_mapa(args, r27, r28v, r29v, r30v, r31v, r32v, r33v, r34v, r35v):
    base = r34_linhas_mapa(args, r27, r28v, r29v, r30v, r31v, r32v, r33v, r34v)
    n34 = len(R34_MAPA)
    vn = (r35v or {}).get("ver_novos") or {}
    evn = (r35v or {}).get("ev_novos") or {}
    dec = (r35v or {}).get("decisao_grpo")
    d35 = dict((r[0], r[3] + " → " + r[5]) for r in R35_MAPA)
    L = []
    for i, (rot, est, ev) in enumerate(base):
        if i < n34:
            if rot == "bloco42":
                L.append((rot, r35_estado_bloco(args, "bloco42"), d35["bloco42"]))
                L.append(("bloco43", "ATIVO", d35["bloco43"]))
            elif rot in ("nexus_lexico.py", "asi_metacognitivo_enxuto.py"):
                r_ = [r for r in R35_MAPA if r[0] == rot][0]
                L.append((rot, "ATIVO", r_[3] + " → " + r_[5]))
            else:
                L.append((rot, est, ev))
            continue
        if rot == "GRPO sem crítico (proxy)" and dec:
            est = {"MANTER": "ATIVO (MANTIDO também no texto na R35, grade de lr estendida; VIVO)",
                   "RESTRINGIR_Z": "ATIVO (RESTRITO ao tipo Z na R35: o efeito no texto não sobreviveu; VIVO em Z)"}.get(dec, "FORA (a R35 o retirou da pilha: LX8 não confirmada)")
            ev = evn.get("grpo", ev)
        if rot == "Mega-Sena":
            est = "DORMENTE (nulo honesto; regressão ao vivo na R35)"
        if rot == "verificador de consistência (Prolog)" and (r35v or {}).get("ver_verif35"):
            ev = r35v["ver_verif35"][:140]
        if rot.startswith("jogos do gradiente: Nash analítico") and (r35v or {}).get("ver_oz35"):
            ev = (ev + " | " + r35v["ver_oz35"])[:340]
        if rot == "consolidação seletiva no sono (R34)":
            ds = vn.get("sono_seletivo")
            est = ("ATIVO (ADOTADO como componente de fluxos não estacionários; VIVO — provisório, R35)" if ds == "vivo"
                   else (f"PROXY (brinquedo; fora da pilha; R34 NOCIVO; R35 {_r31_rot_ver(ds) if ds != 'inconclusivo' else 'INCONCLUSIVO'})" if ds else est))
            ev = evn.get("sono_seletivo", ev)
        if rot == "pilha real sob deslocamento (R34)":
            est = "DESCRITIVO (R34: pilha RESTRITA; R35 mede a pilha NOVA; a pilha não muda por rótulos)"
            if (r35v or {}).get("ver_sn35"):
                ev = r35v["ver_sn35"][:240]
        L.append((rot, est, ev))
    L.append(("lr do GRPO no texto (R35)", "DESCRITIVO (grade estendida + lr fixo; define se rl=grpo continua no texto)", ((r35v or {}).get("ver_lx35") or "(sem resultado nesta execução)")[:240]))
    L.append(("soma zero: OGDA/EG (R35)", "PROXY (brinquedo 3×3; fora da pilha)", ((r35v or {}).get("ver_oz35") or "(sem resultado nesta execução)")[:240]))
    return L


def mapa_do_que_vive_linhas_r35(ctx: Contexto) -> list:
    lin = r35_linhas_mapa(ctx.args, ctx.res.get("r27") or {}, ctx.res.get("r28") or {}, ctx.res.get("r29") or {}, ctx.res.get("r30") or {}, ctx.res.get("r31") or {}, ctx.res.get("r32") or {}, ctx.res.get("r33") or {}, ctx.res.get("r34") or {}, ctx.res.get("r35") or {})
    n_blocos = len(R35_MAPA)
    rods = {r_[0]: r_[2] for r_ in R35_MAPA}
    trans_rod = {"filtro-primeiro (τ fixo)": "R20", "filtro adaptativo (travado)": "R26–R35", "RL ordinário": "R19–R35", "RL extraordinário": "R19–R35",
                 "porta de geração (k)": "R25–R35", "meta-recompensa (bruta/calibrada)": "R24–R35", "meta-recompensa NORMALIZADA": "R26–R35", "delírio": "R3–R22",
                 "BitLinear ternário v2 (STE)": "R25–R35", "BitLinear v1 (R24)": "R24", "SNN LIF (R24)": "R24", "prefill/decode (intensidade)": "R24", "Mega-Sena": "R18–R35",
                 "memória em tokens core/recall/archival": "R29–R35", "dialética de gradientes (proxy)": "R29–R35", "verificador de consistência (Prolog)": "R28–R35",
                 "mini-JEPA (proxy)": "R29–R35", "CBP / shrink-and-perturb (proxy)": "R29–R35", "esquecimento: replay × EWC (proxy)": "R29–R35", "GRPO sem crítico (proxy)": "R29–R35",
                 "dedup online (estrutura na escrita)": "R30–R35", "porta k alocada (custo igual)": "R28–R35", "pilha completa (todas as opcionais)": "R31", "jogos do gradiente: Nash analítico (R31)": "R8–R35",
                 "predição seletiva (R32)": "R32", "dedup semântica da memória (R33)": "R33", "robustez sob deslocamento (R33)": "R33",
                 "consolidação seletiva no sono (R34)": "R34–R35", "pilha real sob deslocamento (R34)": "R34–R35", "lr do GRPO no texto (R35)": "R35", "soma zero: OGDA/EG (R35)": "R35"}
    L = ["MAPA DO QUE VIVE (35 rodadas) — estado de cada bloco derivado das funções de dormência do próprio código e dos vereditos das auditorias R31, R32, R33, R34 e R35",
         "estados: ATIVO = roda ao vivo | DORMENTE = resultado congelado (sha256), recálculo atrás de --reativar-dormentes | CONGELADO = módulo encerrado | PROXY = brinquedo rotulado, fora da pilha | FORA = removido ou nunca adotado | NÚCLEO-MATEMÁTICO = fato verificável, não evidência de cognição | VIVO/DECORATIVO/NOCIVO = veredito pré-registrado (R31 a R35 quando replicado)",
         f"{'módulo/bloco':<28}{'rodada':<9}{'estado':<38}tema → evidência"]
    for i, (rot, est, ev) in enumerate(lin):
        if i == n_blocos:
            L.append("--- módulos transversais (estado pelo veredito desta execução) ---")
        rod = rods.get(rot) if i < n_blocos else trans_rod.get(rot, "R29")
