def registro_r35(ctx: Contexto) -> list:
    r = ctx.res.get("r35")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R35 (BLOCO 43) — " + " | ".join(f"{f} {a} conf / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: LX 8, SN 9, OZ 8, FS 7; regressão Mega/Prolog)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}" + (" (consistente entre metades)" if r["cons"].get(h) else ""))
    for cid in R35_COMP_NOVOS:
        L.append(f"  veredito {cid}: {r['ev_novos'][cid]}")
    L.append("  pilha resultante: " + ", ".join(f"{k}={v}" for k, v in r["pilha"].items()) + " | " + "; ".join(r["notas"]))
    for k in ("ver_lx35", "ver_sn35", "ver_oz35", "ver_fs35", "ver_mega35", "ver_verif35"):
        L.append(f"  {r[k]}")
    return L


def sumario_r35_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r35")
    if not r or "P" not in r:
        return ["R35: (ainda sem resultados nesta execução)"]
    vs = ", ".join(f"{cid}:{r['ver_novos'][cid]}" for cid in R35_COMP_NOVOS)
    return ["R35 BLOCO 43: " + "; ".join(f"{f} {a}/{b}/{c}" for f, (a, b, c) in r["resumo"].items()) + f" | GRPO {r['decisao_grpo']} (texto {r['texto']}) | vereditos {vs} | {r['ver_sn35'][:100]} | {r['ver_oz35'][:80]} | {r['ver_mega35'][:60]} | {r['ver_verif35'][:70]}"]


def registro_hipoteses_r35(ctx: Contexto) -> list:
    r = ctx.res.get("r35")
    if not r or "P" not in r:
        return []
    desc = r35_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R35", f"R35-{k}", "CONF", desc[k], f"Δ={m:+.4f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f}" + ("" if k in ("OZ3", "OZ7", "OZ8", "FS5") else f" d_z={dz:+.2f} MDE={mde:.4f}"), r["st"][k]))
    for nome, ch in (("GRPO e sono seletivo (vereditos)", None), ("lr estendido do GRPO no texto", "ver_lx35"), ("pilha nova sob deslocamento", "ver_sn35"), ("soma zero GDA×OGDA×EG", "ver_oz35"), ("sono em regime com esquecimento (descritivo)", "ver_fs35"), ("Mega-Sena (regressão)", "ver_mega35"), ("verificador Prolog × vereditos", "ver_verif35")):
        out.append(("R35", f"R35-V[{nome}]", "DESC", f"Veredito: {nome}", (r[ch] if ch else "; ".join(f"{k}:{v}" for k, v in r["ver_novos"].items()) + f" | GRPO {r['decisao_grpo']} | " + "; ".join(r["notas"])), "descritiva"))
    out.append(("R35", "R35-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


def secao_mudancas_r35(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("O QUE MUDOU NA RODADA 35 (calculado desta execução)")
    for line in registro_r35(ctx):
        rep.log(line)
    rep.log("BLOCO 42 (R34): DORMENTE nesta execução (captura do código R34 inalterado, sha256; linhas estáveis idênticas às do relatório R34 entregue); recalculável com --reativar-dormentes ou R35_REATIVAR=1 (que confere linha a linha). BLOCO 41 (R33), BLOCO 40 (R32), BLOCO 39 (R32), BLOCO 38 (R31) e os 9 da R30 seguem dormentes.")
    rep.log("Pilha padrão R35: derivada mecanicamente dos vereditos (Parte A: MANTER/RESTRINGIR_Z/SAIR com o GRPO usando a grade de lr estendida, a réplica em Z e a medição sob deslocamento; Parte C: sono seletivo só entra se VIVO em regime com esquecimento real). Ver «PILHA PADRÃO RESULTANTE».")
    rep.log("Companion: nexus_lexico.py 1.18.0 (verificar_pilha_r31 herdado; --nash-zero-soma: GDA × média × reinício × OGDA × EG em Python puro; --sono; --nash-diagnostico; --seletivo; --nash; --dialetica; --memoria; auditor RECUSA).")
