def r36_desloc() -> int:
    v = os.environ.get("R36_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r36_crc(rot: str) -> int:
    return zlib.crc32(f"R36|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r36_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R36_SEEDS.items()}


# ---------------------------------------------------------------------------
# PARTE A — auditoria da pilha padrão inteira
# ---------------------------------------------------------------------------
def r36_k(tn: str):
    """(k_def, k da pilha): nas 5 tarefas da pilha a k alocada (Σ = 17 = Σk_def); nas frescas, k_def."""
    kd = int(R33_KDEF[tn])
    return kd, int(R36_KAL[tn]) if tn in R36_STK5 else kd


def r36_job_stk(task):
    """task = ('R36STK', seed, rl_sel). SH[tn][cond] = {BASE: r_clean@4 do RL ordinário (recompensa do filtro, lr travado); F: modo adaptativo @k_def; KA: o mesmo @k da pilha; STK: Z → GRPO@k da pilha, H → ≡ KA}."""
    _, seed, rl_sel = task
    out = {"seed": int(seed), "SH": {}}
    for tn in R36_TAR10:
        tz = r33_tarefa(tn)
        lr = R36_LR_L[tn]
        base_pol = r25_treinar(tz, r27_cfg_pf(), seed, lr)["pol"]
        f_pol = base_pol if R33_MODO[tn] == "ON" else r25_treinar(tz, r33_cfg(tn), seed, lr)["pol"]
        s_pol = r34_treina_z(tz, "GRPO", seed, rl_sel) if tn in R36_Z else None
        kd, ka = r36_k(tn)
        kmax = max(4, kd, ka)
        out["SH"][tn] = {}
        for c in R36_CONDS:
            tc = r33_tarefa_desloc(tz, tn, c)
            eb = r33_ev(tc, base_pol, seed, "R36|sh", kmax)
            ef = eb if f_pol is base_pol else r33_ev(tc, f_pol, seed, "R36|sh", kmax)
            es = r33_ev(tc, s_pol, seed, "R36|sh", kmax) if s_pol is not None else ef
            out["SH"][tn][c] = {"BASE": float(eb[4]), "F": float(ef[kd]), "KA": float(ef[ka]), "STK": float(es[ka])}
    return out


def r36_rotulo_pilha(st: dict) -> str:
    """Rótulo mecânico da pilha inteira (regra do prereg, Parte A)."""
    if st["TOT_ID"] != "confirmada":
        return "NÃO CONFIRMADA"
    if st["TOT_ENT"] == "refutada" or st["TOT_VER"] == "refutada":
        return "QUEBRA SOB DESLOCAMENTO"
    if st["TOT_ENT"] != "confirmada" or st["TOT_VER"] != "confirmada":
        return "PARCIAL"
    ht = [st["HT_ID"], st["HT_ENT"], st["HT_VER"]]
    if any(s == "refutada" for s in ht):
        return "CONFIRMADA EM Z, NOCIVA EM H"
    if all(s == "confirmada" for s in ht):
        return "CONFIRMADA (Z e H)"
    return "CONFIRMADA (DOMINADA POR Z)"


def r36_pilha_resultante(pil35: dict, st: dict, sono: str) -> tuple:
    """Só REFUTAÇÃO muda a pilha (regra do prereg); o sono só entra se VIVO."""
    pil, notas = dict(pil35), []
    if st["ALG_ID"] == "refutada":
        pil["rl"] = "ordinario"; notas.append("A: ALG_ID refutada (GRPO pior que o RL ordinário em Z) → rl=ordinario")
    if st["FIL_ID"] == "refutada":
        pil["filtro"] = "ligado"; notas.append("A: FIL_ID refutada (filtro adaptativo pior que o filtro ligado) → filtro=ligado")
    if st["KAL_ID"] == "refutada":
        pil["k_alocada"] = "nao"; notas.append("A: KAL_ID refutada (k alocada pior que k_def a custo igual) → k_alocada=nao")
    if not notas:
        notas.append("A: nenhuma peça refutada → a pilha padrão R35 permanece (rl=" + str(pil["rl"]) + ", gate, filtro, k alocada)")
    if sono == "vivo":
        pil["continuo"] = "sono_seletivo"; notas.append("B: sono seletivo VIVO com portão corrigido → ENTRA como componente de fluxos não estacionários (provisório)")
    else:
        pil.pop("continuo", None); notas.append(f"B: sono seletivo {sono.upper()} → fica FORA")
    return pil, notas


def r36_permitido(pil: dict, per35: dict, sono: str) -> dict:
    per = {k: v for k, v in per35.items() if k not in ("rl", "continuo", "filtro", "k_alocada")}
    per["rl"] = {"grpo_z": "grpo_z", "grpo": "grpo", "ordinario": "ordinario"}.get(pil["rl"], "ordinario")
    per["filtro"] = pil["filtro"]
    per["k_alocada"] = pil["k_alocada"]
    if sono == "vivo":
        per["continuo"] = "sono_seletivo"
    return per


def r36_vereditos_comp(ver35: dict, st: dict, sono: str) -> dict:
    """Vereditos por componente para o verificador Prolog: parte dos da R35; GRPO nocivo se ALG_ID refutada; filtro adaptativo e k alocada NOCIVOS se refutados (a pilha os retira); sono decorativo se inconclusivo."""
    ver = dict(ver35)
    ver["grpo"] = "nocivo" if st["ALG_ID"] == "refutada" else "vivo"
    if st["FIL_ID"] == "refutada":
        ver["filtro_adaptativo"] = "nocivo"
    if st["KAL_ID"] == "refutada":
        ver["porta_k_alocada"] = "nocivo"
    ver["sono_seletivo"] = "decorativo" if sono == "inconclusivo" else sono
    return ver


# ---------------------------------------------------------------------------
# PARTE B — sono seletivo com portão corrigido
# ---------------------------------------------------------------------------
class R36Sleep(R34Sleep):
    """R34Sleep com alvo −1 = INDIFERENTE (qualquer ação conta como correta)."""

    def _ok(self, ids):
        tg = self.tgt
        return np.asarray([1.0 if (tg[ids[t - 2], ids[t - 1]] < 0 or ids[t] == tg[ids[t - 2], ids[t - 1]]) else 0.0 for t in range(2, len(ids))])


def r36_fluxo(seed: int, desenho, conflito: bool):
    """desenho = (nome, regime, m, p_alt, P). Controle (conflito=False): 4 tarefas = regra-base completa. DERIVA: tarefas 2–4 = regra-base em R36_N_CONSTR estados sorteados por tarefa, indiferentes (−1) nos demais.
    CONFLITO: m estados disputados (sem reposição) com um valor alternativo fixo ≠ base por estado; cada tarefa 2–4 escolhe, independentemente por estado, o alternativo (prob. p_alt) ou a base."""
    _nome, regime, m, p, _P = desenho
    base = np.asarray([[(a + b) % 7 for b in range(7)] for a in range(7)], int)
    tgts = [base.copy()]
    rng = np.random.default_rng([int(seed), 36, 5])
    pool, alt = [], {}
    if conflito and regime == "conflito":
        pool = [int(x) for x in rng.permutation(49)[:int(m)]]
        for s_ in pool:
            a, b = divmod(s_, 7)
            alt[s_] = (int(base[a, b]) + int(rng.integers(1, 7))) % 7
    for _k in range(1, 4):
        t = base.copy()
        if conflito and regime == "deriva":
            t = np.full((7, 7), -1, int)
            for s_ in rng.permutation(49)[:R36_N_CONSTR]:
                a, b = divmod(int(s_), 7)
                t[a, b] = base[a, b]
        elif conflito:
            for s_ in pool:
                a, b = divmod(s_, 7)
                if rng.random() < p:
                    t[a, b] = alt[s_]
        tgts.append(t)
    return [R36Sleep(t, f"R36S{k}") for k, t in enumerate(tgts)]


def r36_cfg_sono(P: int) -> dict:
    return dict(R34_SL, P_treino=int(P))


def r36_sono_run(seed: int, desenho, conflito: bool, so_forg: bool = False):
    """Como r35_sono_run, com o fluxo r36_fluxo. so_forg=True: só treino + sonda (DEV dos desenhos; sem braços de sono)."""
    cfg = r36_cfg_sono(desenho[4])
    P, S, lr, delta = cfg["P_treino"], cfg["S"], cfg["lr"], cfg["delta"]
    tzs = r36_fluxo(seed, desenho, conflito)
    K = len(tzs)
    rng_tr = r25_rng(seed, r36_crc("sono|treino"), 1)
    pol = tzs[0].init_pol(rng_tr)
    base, bases, post = 0.0, [], []
    for k, tz in enumerate(tzs):
        base = r32_passos(tz, pol, seed + 1000003 * (k + 1), rng_tr, 0, P, lr, base)
        bases.append(base)
        post.append(r34_acc(tz, pol, seed, f"sonda|pos|{k}", cfg["n_sonda"]))
    fim = [r34_acc(tz, pol, seed, f"sonda|fim|{k}", cfg["n_sonda"]) for k, tz in enumerate(tzs)]
    forg = [post[k] - fim[k] for k in range(K)]
    F = [k for k in range(K) if forg[k] >= delta]
    if so_forg:
        return {"F": F, "forg": forg, "post": post, "fim": fim}
    rng_a = np.random.default_rng([int(seed), 36, 6])
    alea = sorted(int(x) for x in rng_a.choice(K, size=len(F), replace=False)) if F else []
    listas = {"NADA": [], "ULTIMA": [K - 1], "TODAS": list(range(K)), "SEL": list(F), "ALEA": alea}
    bracos = ("NADA", "ULTIMA", "TODAS", "SEL", "ALEA") if conflito else ("NADA", "TODAS", "SEL")
    accs, steps, acc_t = {}, {}, {}
    for nome in bracos:
        lst = listas[nome]
        p2 = {"W": pol["W"].copy(), "V": pol["V"]}
        if lst:
            rngS = r25_rng(seed, r36_crc("sono|" + nome), 3)
            b = {k: bases[k] for k in range(K)}
            for j in range(S):
                k = lst[j % len(lst)]
                b[k] = r32_passos(tzs[k], p2, seed + 2000003 * (k + 1), rngS, 1000 + j, 1, lr, b[k])
        steps[nome] = S if lst else 0
        acc_t[nome] = [r34_acc(tz, p2, seed, f"final|{k}", cfg["n_final"]) for k, tz in enumerate(tzs)]
        accs[nome] = float(np.mean(acc_t[nome]))
    return {"F": F, "forg": forg, "post": post, "fim": fim, "acc": accs, "steps": steps, "acc_t": acc_t, "lista_alea": alea}


def r36_job_devs(task):
    """task = ('R36DEVS', seed, nome): treino + sonda no desenho (com conflito/deriva) — só o esquecimento por tarefa."""
    _, seed, nome = task
    d = [x for x in R36_DESENHOS if x[0] == nome][0]
    o = r36_sono_run(int(seed), d, True, so_forg=True)
    return {"nome": nome, "forg": o["forg"], "F": o["F"]}


def r36_job_sl(task):
    """task = ('R36SL', seed, conflito, nome)."""
    _, seed, conflito, nome = task
    d = [x for x in R36_DESENHOS if x[0] == nome][0]
    return r36_sono_run(int(seed), d, bool(conflito))


def r36_gate_desenho(tab: dict, nome: str) -> bool:
    f1, fr1 = tab[nome][0], tab[nome][1]
    return f1 >= R36_DEV_SL["forg1_min"] and fr1 >= R36_DEV_SL["frac_f1_min"]


def r36_escolher_desenho(tab: dict) -> tuple:
    """tab[nome] = (esquecimento médio da TAREFA 1, fração de fluxos com a tarefa 1 em F, ...). Primeiro desenho na ordem de preferência que passa; senão o de maior esquecimento da tarefa 1 (passou=False)."""
    for nome, *_ in R36_DESENHOS:
        if nome in tab and r36_gate_desenho(tab, nome):
            return nome, True
    nomes = [d[0] for d in R36_DESENHOS if d[0] in tab]
    return max(nomes, key=lambda n: (tab[n][0], -nomes.index(n))), False


def r36_vered_sono(st: dict, gate_ok: bool) -> str:
    if not gate_ok:
        return "inconclusivo"
    if st["SX1"] == "confirmada" and st["SX2"] == "confirmada" and st["SX3"] == "confirmada" and st["SX4"] != "refutada" and st["SX7"] == "confirmada":
        return "vivo"
    if st["SX1"] == "refutada" or st["SX2"] == "refutada":
        return "nocivo"
    return "decorativo"


# ---------------------------------------------------------------------------
# PARTE C — OGDA/EG na camada adversarial
# ---------------------------------------------------------------------------
_GH = {}


def r36_gh():
    if not _GH:
        x, w = np.polynomial.hermite_e.hermegauss(R36_GAN_NODOS)
        _GH["x"], _GH["w"] = x, w / np.sqrt(2.0 * np.pi)
    return _GH["x"], _GH["w"]


def r36_sig(u):
    return 1.0 / (1.0 + np.exp(-np.clip(u, -50.0, 50.0)))


def r36_jogos_gan(seeds):
    """(μ*, σ*, estado inicial (5, G) = m, ℓ, a, b, c) por jogo, de np.random.default_rng([semente, 36, 1])."""
    G = len(seeds)
    mu, sg, S0 = np.zeros(G), np.zeros(G), np.zeros((5, G))
    for g, s in enumerate(seeds):
        rng = np.random.default_rng([int(s), 36, 1])
        mu[g], sg[g] = rng.uniform(-2.0, 2.0), rng.uniform(0.5, 1.5)
        S0[0, g], S0[1, g] = rng.uniform(-2.0, 2.0), math.log(rng.uniform(0.5, 1.5))
        S0[2:, g] = rng.normal(0.0, 0.1, size=3)
    return mu, sg, S0


def r36_jogos_dirac(seeds):
    S0 = np.zeros((2, len(seeds)))
    for g, s in enumerate(seeds):
        rng = np.random.default_rng([int(s), 36, 2])
        S0[:, g] = rng.uniform(-1.5, 1.5, size=2)
    return S0


def r36_campo_gan(S, mu, sg, variante: str):
    """Campo do jogo F = (dm, dℓ, da, db, dc): o discriminador SOBE V; o gerador DESCE V (MM) ou SOBE E log D(G(z)) (NS). Esperanças por Gauss–Hermite."""
    X, W = r36_gh()
    m, lg, a, b, c = S
    xd = mu[:, None] + sg[:, None] * X[None, :]
    es = np.exp(lg)
    xg = m[:, None] + es[:, None] * X[None, :]
    sd = r36_sig(a[:, None] * xd + b[:, None] * xd * xd + c[:, None])
    sgn = r36_sig(a[:, None] * xg + b[:, None] * xg * xg + c[:, None])
    wd, wg = W[None, :] * (1.0 - sd), W[None, :] * sgn
    da = (wd * xd).sum(1) - (wg * xg).sum(1)
    db = (wd * xd * xd).sum(1) - (wg * xg * xg).sum(1)
    dc = wd.sum(1) - wg.sum(1)
    lp = a[:, None] + 2.0 * b[:, None] * xg
    if variante == "MM":
        dm = (wg * lp).sum(1)
        dl = (wg * lp * es[:, None] * X[None, :]).sum(1)
    else:
        wn = W[None, :] * (1.0 - sgn)
        dm = (wn * lp).sum(1)
        dl = (wn * lp * es[:, None] * X[None, :]).sum(1)
    return np.stack([dm, dl, da, db, dc])


def r36_campo_dirac(S):
    th, ps = S
    fp = r36_sig(-ps * th)           # f'(t) = sigmoide(−t)
    return np.stack([-fp * ps, fp * th])


def r36_limpar(S, gan: bool):
    S = np.clip(np.nan_to_num(S, nan=1000.0, posinf=1000.0, neginf=-1000.0), -1000.0, 1000.0)
    if gan:
        S[1] = np.clip(S[1], -20.0, 20.0)
    return S


def r36_dinamica(campo, S0, metodo: str, eta: float, gan: bool, B: int = R36_GAN_B, med=None):
    """GDA/OGDA com B passos (1 avaliação cada); EG com B/2 passos (2 avaliações cada): orçamento IGUAL de B avaliações de gradiente. med(S) → vetor a acumular nos passos > B/2 (média temporal; só GDA)."""
    S = S0.copy()
    acc, n_acc = None, 0
    if metodo == "EG":
        for _t in range(B // 2):
            Sh = r36_limpar(S + eta * campo(S), gan)
            S = r36_limpar(S + eta * campo(Sh), gan)
        return S, None
    Fp = None
    for t in range(B):
        Fc = campo(S)
        if metodo == "GDA":
            S = r36_limpar(S + eta * Fc, gan)
        else:
            if Fp is None:
                Fp = Fc          # 1º passo: o gradiente anterior é o atual (sem avaliação extra: orçamento exato B)
            S = r36_limpar(S + eta * (2.0 * Fc - Fp), gan)
            Fp = Fc
        if med is not None and t >= B // 2:
            v = med(S)
            acc = v if acc is None else acc + v
            n_acc += 1
    return S, (acc / n_acc if acc is not None else None)


def r36_erro_gan(m, lg, mu, sg):
    return np.minimum(np.maximum(np.abs(m - mu), np.abs(np.exp(np.clip(lg, -20.0, 20.0)) - sg)), 1000.0)


def r36_run_gan(seeds, variante: str, metodo: str, eta: float):
    """Um par (variante, método, η) em todos os jogos: devolve erro da última iterada (e, no GDA-MM, o erro da média temporal dos passos 2001–4000)."""
    if variante == "DIRAC":
        S0 = r36_jogos_dirac(seeds)
        S, _ = r36_dinamica(r36_campo_dirac, S0, metodo, eta, False)
        return {"err": np.sqrt(S[0] ** 2 + S[1] ** 2), "avg": None}
    mu, sg, S0 = r36_jogos_gan(seeds)
    campo = lambda S_: r36_campo_gan(S_, mu, sg, variante)
    med = (lambda S_: np.stack([S_[0], np.exp(S_[1])])) if (metodo == "GDA" and variante == "MM") else None
    S, mavg = r36_dinamica(campo, S0, metodo, eta, True, med=med)
    out = {"err": r36_erro_gan(S[0], S[1], mu, sg), "avg": None}
    if mavg is not None:
        out["avg"] = np.minimum(np.maximum(np.abs(mavg[0] - mu), np.abs(mavg[1] - sg)), 1000.0)
    return out


def r36_job_devg(task):
    """task = ('R36DEVG', seeds, variante, metodo, eta)."""
    _, seeds, variante, metodo, eta = task
    o = r36_run_gan(list(seeds), variante, metodo, float(eta))
    return {"variante": variante, "metodo": metodo, "eta": float(eta), "err": o["err"]}


def r36_job_gan(task):
    """task = ('R36GAN', seeds, variante, metodo, eta)."""
    _, seeds, variante, metodo, eta = task
    o = r36_run_gan(list(seeds), variante, metodo, float(eta))
    return {"variante": variante, "metodo": metodo, "eta": float(eta), "err": o["err"], "avg": o["avg"]}


def r36_escolher_eta(tab: dict) -> dict:
    """tab[(variante, metodo)][eta] = vetor de erros no DEV. η de maior sucesso médio (erro ≤ tol); desempate: menor log10 do erro mediano; depois menor η."""
    out = {}
    for k, d in tab.items():
        def chave(eta):
            e = np.asarray(d[eta], float)
            return (float(np.mean(e <= R36_GAN_TOL)), -float(np.log10(max(np.median(e), 1e-6))), -float(eta))
        out[k] = max(d, key=chave)
    return out


def r36_vered_gan(st: dict) -> str:
    if st["GN1"] == "refutada" or st["GN2"] == "refutada":
        return "nocivo"
    if st["GN1"] == "confirmada" or st["GN2"] == "confirmada":
        return "vivo"
    return "decorativo"


# ---------------------------------------------------------------------------
# despacho
# ---------------------------------------------------------------------------
def r36_job(task):
    k = task[0]
    if k == "R36STK":
        return r36_job_stk(task)
    if k == "R36DEVS":
        return r36_job_devs(task)
    if k == "R36SL":
        return r36_job_sl(task)
    if k == "R36DEVG":
        return r36_job_devg(task)
    if k == "R36GAN":
        return r36_job_gan(task)
    return r34_job(task)


