R37_CONGELADO_B64 = "".join(R37_CONGELADO_B64_CHUNKS)

_R37_CONG_CACHE = {"v": None}


def r37_congelado():
    if _R37_CONG_CACHE["v"] is not None:
        return _R37_CONG_CACHE["v"]
    if not R37_CONGELADO_B64 or R37_CONGELADO_SHA256 == "PENDING":
        return None
    try:
        raw = zlib.decompress(base64.b64decode(R37_CONGELADO_B64))
        v = pickle.loads(raw) if hashlib.sha256(raw).hexdigest() == R37_CONGELADO_SHA256 else None
    except Exception:
        v = None
    _R37_CONG_CACHE["v"] = v
    return v


def r37_env_vivo() -> bool:
    """Qualquer flag de depuração/bloco novo de OUTRA rodada (R<n>_DEV, R<n>_SO_NOVOS, n≠37) liga o código vivo; R37_DEV/R37_SO_NOVOS (depuração do BLOCO 45) não. R36_DEV/R36_SO_NOVOS (depuração do BLOCO 44) LIGAM o código vivo do 44."""
    return any(re.fullmatch(r"R(\d+)_(DEV|SO_NOVOS)", k) and k[1:3] != "37" and v for k, v in os.environ.items())


def r37_dormente_ativo(args, nome: str) -> bool:
    if os.environ.get("R12_REATIVAR") or os.environ.get("R37_REATIVAR") or getattr(args, "reativar_dormentes", False):
        return False
    if args.seed != 42 or args.emb != "semantico" or args.rapido or not args.offline:
        return False
    if r37_env_vivo():
        return False
    cg = r37_congelado()
    return cg is not None and nome in cg


def _dormente37(nome, vivo):
    def w(ctx):
        rot = R37_DORMENTES[nome]
        est = ctx.res.setdefault("r37_dorm", {})
        if r37_dormente_ativo(ctx.args, nome):
            cg = r37_congelado()[nome]
            ctx.rep.log(
                f"[R37 DORMENTE] {rot}: resultados CONGELADOS de uma execução do código R36 inalterado "
                f"(execução completa, --offline --jobs 8, semente 42; sha256 {R37_CONGELADO_SHA256[:12]}… CONFERE; origem {R37_CONGELADO_ORIGEM}). "
                f"Recalcular: --reativar-dormentes (ou R37_REATIVAR=1)."
            )
            for txt, vol in cg["linhas"]:
                ctx.rep.log(("[congelado] " + txt) if (vol and txt) else txt, vol=vol)
            ctx.res.update(copy.deepcopy(cg["res"]))
            for nome_o, vs_ in cg.get("obs", {}).items():
                ctx.obs.reg.setdefault(nome_o, []).extend(v_.copy() for v_ in vs_)
            if "rng" in cg:
                ctx.rng.bit_generator.state = copy.deepcopy(cg["rng"])
            if "sinal" in cg:
                ctx.sinal = copy.deepcopy(cg["sinal"])
            est[rot] = "dormente (congelado, sha256 conferido)"
            return
        e0 = len(ctx.rep.estaveis)
        vivo(ctx)
        cg = r37_congelado()
        if cg is not None and nome in cg and (os.environ.get("R12_REATIVAR") or os.environ.get("R37_REATIVAR") or getattr(ctx.args, "reativar_dormentes", False)):
            novo = ctx.rep.estaveis[e0:]
            velho = [t for t, v in cg[nome]["linhas"] if not v]
            ok = novo == velho
            est[rot] = "recalculado (--reativar-dormentes) e " + ("CONFERE linha a linha com o congelado" if ok else
                f"DIFERE do congelado ({sum(a != b for a, b in zip(novo, velho)) + abs(len(novo) - len(velho))} linhas)")
            ctx.rep.log(f"[R37 REATIVADO] {rot}: {est[rot]}.")
        else:
            est[rot] = "vivo (recalculado)"
    w.__name__ = vivo.__name__
    w.__doc__ = getattr(vivo, "__doc__", None)
    return w


