def r37_desloc() -> int:
    v = os.environ.get("R37_DEV")
    return 0 if (not v or v in ("0", "false", "False", "no", "off", "")) else 10000


def r37_crc(rot: str) -> int:
    return zlib.crc32(f"R37|{rot}".encode("utf-8")) & 0xFFFFFFFF


def r37_sementes(desloc=0):
    d = int(desloc)
    return {k: [s + d for s in v] for k, v in R37_SEEDS.items()}


# ---------------------------------------------------------------------------
# Tarefas novas e família de grafo
# ---------------------------------------------------------------------------
class R37Grafo(R33Sym):
    """Caminhada num grafo orientado ESCONDIDO e fixo: d vizinhos de saída por nó; transição ids[t−1]→ids[t] (t ≥ 2) válida se ids[t] é vizinho de saída de ids[t−1] E ids[t] ≠ ids[t−2] (sem voltar atrás).
    Várias respostas válidas por estado (d ou d−1); regra relacional, não funcional; restrição de segunda ordem. Verificador/recompensa: os da família Z sobre este _ok."""

    def __init__(self, nome: str, V: int, d: int, gseed: int):
        super().__init__(nome, V, 1, 1)
        rng = np.random.default_rng([int(gseed), 37, 3])
        nb = []
        for u in range(int(V)):
            cand = np.asarray([x for x in range(int(V)) if x != u])
            nb.append(sorted(int(x) for x in rng.permutation(cand)[:int(d)]))
        allow = np.zeros((int(V), int(V), int(V)), dtype=bool)
        for a in range(int(V)):
            for b in range(int(V)):
                for x in nb[b]:
                    if x != a:
                        allow[a, b, x] = True
        self.d, self.nb, self.allow = int(d), nb, allow

    def _ok(self, ids):
        al = self.allow
        return np.asarray([1.0 if al[ids[t - 2], ids[t - 1], ids[t]] else 0.0 for t in range(2, len(ids))])


def r37_tarefa(tn: str):
    if tn in ("ZN1",):
        p = R37_PRM_NOVAS[tn]
        return R33Sym(tn, p["V"], p["c1"], p["c2"])
    if tn in ("HN1", "HN2"):
        p = R37_PRM_NOVAS[tn]
        return R27Hard(tn, p["V"], p["L"], p["seed_lex"], p["P"])
    for nome, V, d, gs in R37_GR_CAND:
        if tn == nome:
            return R37Grafo(nome, V, d, gs)
    return r33_tarefa(tn)


def r37_tarefa_desloc(tz, tn: str, cond: str):
    """ID: a própria; VER: R33DeslVer; ENT: tarefas simbólicas (Z, ZN1, grafo) — 2 primeiros símbolos sorteados (R33DeslEntZ). As tarefas H do bloco 44 usam r33_tarefa_desloc."""
    if cond == "ID":
        return tz
    if cond == "VER":
        return R33DeslVer(tz)
    return R33DeslEntZ(tz)


def r37_valor_modo(modo: str, ent: dict) -> float:
    """ON = Pf@4; LEVE = Pr@4; OFF = Pr@1 (as chaves ON4, RAW4, RAW1 do job)."""
    return float(ent["ON4"] if modo == "ON" else (ent["RAW4"] if modo == "LEVE" else ent["RAW1"]))


# ---------------------------------------------------------------------------
# Jobs
# ---------------------------------------------------------------------------
def r37_job_stk(task):
    """task = ('R37STK', seed, rl_sel). Por tarefa (10) e semente: Pf, Pr (RL ordinário com recompensa do filtro / crua, lr travado); valores ON4, RAW4, RAW1 (ID, sem deslocamento, kmax=8);
    nas 5 tarefas da pilha, também ALOC e KDEF (a política da pilha — GRPO em Z, política do modo em H — avaliada na k alocada e na k_def) em ID, ENT e VER.
    [R37, otimização de CPU declarada no Adendo 1] sob ENT/VER só se calcula o que alguma hipótese consome (ALOC e KDEF); em H a política da pilha é a própria Pf/Pr, então a avaliação em ID é reaproveitada (mesmos argumentos ⇒ mesmo valor)."""
    _, seed, rl_sel = task
    out = {"seed": int(seed), "V": {}}
    for tn in R37_TAR10:
        tz = r33_tarefa(tn)
        lr = R37_LR_L[tn]
        pf = r25_treinar(tz, r27_cfg_pf(), seed, lr)["pol"]
        pr = r25_treinar(tz, r27_cfg_pr(), seed, lr)["pol"]
        stk, mesma = None, None
        if tn in R37_STK5:
            if tn in R37_Z:
                stk = r34_treina_z(tz, "GRPO", seed, rl_sel)
            else:
                mesma = "pf" if R33_MODO[tn] == "ON" else "pr"
                stk = pf if mesma == "pf" else pr
        kd, ka = int(R33_KDEF[tn]), (int(R37_KAL[tn]) if tn in R37_STK5 else int(R33_KDEF[tn]))
        out["V"][tn] = {}
        for c in (R37_CONDS if tn in R37_STK5 else ("ID",)):
            tc = r33_tarefa_desloc(tz, tn, c)
            e = {}
            if c == "ID":
                ef = r33_ev(tc, pf, seed, "R37|st", 8)
                er = r33_ev(tc, pr, seed, "R37|st", 8)
                e = {"ON4": float(ef[4]), "RAW4": float(er[4]), "RAW1": float(er[1])}
            if stk is not None:
                es = (ef if mesma == "pf" else er) if (c == "ID" and mesma) else r33_ev(tc, stk, seed, "R37|st", 8)
                e["ALOC"], e["KDEF"] = float(es[ka]), float(es[kd])
            out["V"][tn][c] = e
    return out


def r37_job_nov(task):
    """task = ('R37NOV', seed). Tarefas NOVAS (ZN1, HN1, HN2): Pf e Pr; ON4, RAW4, RAW1 (ID, kmax=8). Serve ao DEV (regra de modo) e ao TESTE."""
    _, seed = task
    out = {"seed": int(seed), "V": {}}
    for tn in R37_NOVAS:
        tz = r37_tarefa(tn)
        lr = R37_LR_NOVAS[tn]
        pf = r25_treinar(tz, r27_cfg_pf(), seed, lr)["pol"]
        pr = r25_treinar(tz, r27_cfg_pr(), seed, lr)["pol"]
        ef = r33_ev(tz, pf, seed, "R37|nov", 8)
        er = r33_ev(tz, pr, seed, "R37|nov", 8)
        out["V"][tn] = {"ID": {"ON4": float(ef[4]), "RAW4": float(er[4]), "RAW1": float(er[1])}}
    return out


def r37_alea_pol(tz, seed: int):
    return tz.init_pol(r25_rng(seed, r37_crc("alea|" + tz.nome), 1))


def r37_job_grdev(task):
    """task = ('R37GRDEV', seed, tn). DEV do portão e do modo: ON4, RAW4, RAW1 e ALEA4 (política inicial uniforme)."""
    _, seed, tn = task
    tz = r37_tarefa(tn)
    pf = r25_treinar(tz, r27_cfg_pf(), seed, 3.0)["pol"]
    pr = r25_treinar(tz, r27_cfg_pr(), seed, 3.0)["pol"]
    ef, er = r33_ev(tz, pf, seed, "R37|gr", 8), r33_ev(tz, pr, seed, "R37|gr", 8)
    ea = r33_ev(tz, r37_alea_pol(tz, seed), seed, "R37|gr", 8)
    return {"tn": tn, "seed": int(seed), "ON4": float(ef[4]), "RAW4": float(er[4]), "RAW1": float(er[1]), "ALEA4": float(ea[4])}


def r37_job_gr(task):
    """task = ('R37GR', seed, tn, rl_sel, modo). TESTE da família grafo: BASE (Pf) @4 e @1, STK (GRPO) @4 e @1, ALEA @4 em ID/ENT/VER; ORD_RULE (modo do DEV) em ID."""
    _, seed, tn, rl_sel, modo = task
    tz = r37_tarefa(tn)
    pf = r25_treinar(tz, r27_cfg_pf(), seed, 3.0)["pol"]
    gr = r34_treina_z(tz, "GRPO", seed, rl_sel)
    al = r37_alea_pol(tz, seed)
    pr = None if modo == "ON" else r25_treinar(tz, r27_cfg_pr(), seed, 3.0)["pol"]
    out = {"seed": int(seed), "tn": tn, "modo": modo, "V": {}}
    for c in R37_CONDS:
        tc = r37_tarefa_desloc(tz, tn, c)
        eb, eg, ea = (r33_ev(tc, p, seed, "R37|gr", 8) for p in (pf, gr, al))
        e = {"BASE4": float(eb[4]), "BASE1": float(eb[1]), "STK4": float(eg[4]), "STK1": float(eg[1]), "ALEA4": float(ea[4])}
        if c == "ID":
            if modo == "ON":
                e["RULE"] = float(eb[4])
            else:
                er = r33_ev(tc, pr, seed, "R37|gr", 8)
                e["RULE"] = float(er[4] if modo == "LEVE" else er[1])
        out["V"][c] = e
    return out


def r37_job(task):
    k = task[0]
    if k == "R37STK":
        return r37_job_stk(task)
    if k == "R37NOV":
        return r37_job_nov(task)
    if k == "R37GRDEV":
        return r37_job_grdev(task)
    if k == "R37GR":
        return r37_job_gr(task)
    return r36_job(task)


# ---------------------------------------------------------------------------
# Estatística: equivalência (TOST) por permutação de sinais
# ---------------------------------------------------------------------------
def r37_p_uni(d, shift: float, seed: int) -> float:
    """p unilateral (superior) por permutação de sinais de (d + shift): H0: média(d + shift) ≤ 0."""
    dd = np.asarray(d, float) + float(shift)
    n = len(dd)
    if n == 0:
        return 1.0
    rng = r24_rng(seed, r25_crc("tost"), 5)
    obs = float(dd.mean())
    B = 8000
    sg = rng.choice([-1.0, 1.0], size=(B, n))
    cnt = int(np.sum((sg @ dd) / n >= obs - 1e-15))
    return float((cnt + 1) / (B + 1))


def r37_tost(d, delta: float, seed: int) -> dict:
    """TOST: p_inf (H0: μ ≤ −δ), p_sup (H0: μ ≥ +δ); p da equivalência = max."""
    d = np.asarray(d, float)
    p_inf = r37_p_uni(d, +delta, seed)
    p_sup = r37_p_uni(-d, +delta, seed + 1)
    return {"p_inf": p_inf, "p_sup": p_sup, "p": float(max(p_inf, p_sup))}


def r37_pack(h: str, d):
    """Pacote da hipótese h: r25_pack (média, IC, d_z, MDE) com o p substituído pelo p do TOST nas hipóteses de equivalência."""
    pk = r25_pack(d, seed=r37_crc(h))
    if h in R37_EQUIV:
        tt = r37_tost(d, R37_DELTA_EQ, r37_crc(h) % 100000)
        pk["p"] = tt["p"]
        pk["p_inf"], pk["p_sup"] = tt["p_inf"], tt["p_sup"]
    return pk


def r37_status(h: str, media: float, p_holm: float, d) -> str:
    if h in R37_EQUIV:
        return "equivalente" if p_holm < 0.05 else "nula"
    return r31_status(h, media, p_holm, d)


# ---------------------------------------------------------------------------
# Regras mecânicas (prereg)
# ---------------------------------------------------------------------------
def r37_regra_ke(st: dict) -> str:
    """DISPENSAR se KE1–KE3 todas equivalentes OU KE6 refutada; senão MANTER (VALE) se KE6 confirmada; senão MANTER (EQUIVALÊNCIA NÃO DEMONSTRADA)."""
    if all(st[h] == "equivalente" for h in ("KE1", "KE2", "KE3")) or st["KE6"] == "refutada":
        return "DISPENSAR"
    if st["KE6"] == "confirmada":
        return "MANTER (VALE)"
    return "MANTER (EQUIVALÊNCIA NÃO DEMONSTRADA)"


def r37_vered_atrib(st: dict) -> str:
    if st["FA1"] != "confirmada":
        return "NÃO REPLICA"
    if st["FA2"] == "confirmada" and st["FA4"] == "equivalente" and st["FA3"] != "confirmada":
        return "ONDE O GANHO ESTÁ: FAMÍLIA (texto = recompensa crua)"
    if st["FA3"] == "confirmada" and st["FA4"] != "equivalente":
        return "A TABELA POR TAREFA ACRESCENTA"
    return "MISTO"


def r37_vered_regra_modo(st: dict) -> str:
    return "GENERALIZA" if (st["FA8"] == "confirmada" and st["FA7"] != "refutada") else "NÃO GENERALIZA"


def r37_vered_grafo(st: dict, gate_ok: bool) -> str:
    if not gate_ok:
        return "INCONCLUSIVO"
    if all(st[h] == "confirmada" for h in ("GF1", "GF2", "GF3", "GF4")):
        return "GENERALIZA"
    if st["GF2"] == "refutada":
        return "NÃO GENERALIZA (NOCIVA)"
    if st["GF2"] == "confirmada":
        return "PARCIAL (ID, não sob deslocamento)"
    return "NÃO DETECTADA"


def r37_gate_gr(tab: dict, nome: str) -> bool:
    b, a = tab[nome][0], tab[nome][1]
    return R37_GR_GATE["lo"] <= b <= R37_GR_GATE["hi"] and (b - a) >= R37_GR_GATE["ganho"] - 1e-12


def r37_escolher_gr(tab: dict) -> tuple:
    """tab[nome] = (BASE@4 médio, ALEA@4 médio). Candidatas (ordem GR1…) que passam, até 2; senão a de BASE@4 mais próximo de 0,62 (passou=False)."""
    ok = [n for n, *_ in R37_GR_CAND if n in tab and r37_gate_gr(tab, n)]
    if ok:
        return ok[:R37_GR_GATE["max"]], True
    nomes = [n for n, *_ in R37_GR_CAND if n in tab]
    return [min(nomes, key=lambda n: (abs(tab[n][0] - R37_GR_GATE["alvo"]), nomes.index(n)))], False


def r37_pilha_resultante(pil36: dict, st: dict) -> tuple:
    """Só as regras do prereg mudam a pilha: DISPENSAR → k_alocada=nao; FA1 refutada → filtro=ligado."""
    pil, notas = dict(pil36), []
    rk = r37_regra_ke(st)
    if rk == "DISPENSAR":
        pil["k_alocada"] = "nao"
        notas.append("A: " + ("KE6 refutada (a k alocada é pior)" if st["KE6"] == "refutada" else "KE1, KE2 e KE3 equivalentes (margem 0,02)") + " → k_alocada=nao (parcimônia: k = k_def em todas as tarefas)")
    else:
        notas.append(f"A: {rk} → a k alocada permanece")
    if st["FA1"] == "refutada":
        pil["filtro"] = "ligado"
        notas.append("B: FA1 refutada (filtro adaptativo pior que o filtro ligado) → filtro=ligado")
    else:
        notas.append("B: FA1 não refutada → filtro adaptativo permanece")
    return pil, notas


def r37_permitido(pil: dict, per36: dict) -> dict:
    per = {k: v for k, v in per36.items() if k not in ("filtro", "k_alocada")}
    per["filtro"] = pil["filtro"]
    per["k_alocada"] = pil["k_alocada"]
    return per


def r37_vereditos_comp(ver36: dict, st: dict) -> dict:
    """porta_k_alocada: vivo se mantida; decorativo se dispensada por equivalência; nocivo se KE6 refutada. filtro_adaptativo: nocivo se FA1 refutada; senão o anterior."""
    ver = dict(ver36)
    rk = r37_regra_ke(st)
    ver["porta_k_alocada"] = "vivo" if rk != "DISPENSAR" else ("nocivo" if st["KE6"] == "refutada" else "decorativo")
    if st["FA1"] == "refutada":
        ver["filtro_adaptativo"] = "nocivo"
    return ver


