def r37_versao_nexus() -> str:
    try:
        nx = os.path.join(os.path.dirname(os.path.abspath(__file__)), "nexus_lexico.py")
        if os.path.exists(nx):
            m_ = re.search(r'VERSAO\s*=\s*"(\d+)\.(\d+)\.(\d+)"', open(nx, encoding="utf-8").read())
            if m_:
                return "v" + "_".join(m_.groups())
    except OSError:
        pass
    return R37_NEXUS_ESPERADO


def _r37_mapa_blocos():
    out = []
    for row in R36_MAPA:
        if row[0] == "bloco44":
            out.append(("bloco44", ("bloco44",), "R36", row[3], None, "ST 13/0/0, SX 4/4/0, GN 2/3/3 (R36): pilha inteira CONFIRMADA (Z e H); sono seletivo NOCIVO; OGDA/EG no GAN DECORATIVO → ver auditoria de parcimônia R37 (bloco45)"))
            out.append(("bloco45", ("bloco45",), "R37", "A k alocada vale a complexidade? (equivalência TOST) + atribuição do ganho do filtro adaptativo (tabela × família × qualquer filtro, 3 tarefas novas) + pilha numa família nova (grafo; ideia nova) + regressão Mega/Prolog", "ATIVO",
                        "ver BLOCO 45 (KE 6, FA 8, GF 8)"))
        elif row[0] == "nexus_lexico.py":
            out.append(("nexus_lexico.py", (), "R1–R37", "Companion stdlib-only autodocumentado + auditor RECUSA", "ATIVO", "1.20.0; roda offline; verificador de pilha (vereditos), --equiv (TOST), --grafo (caminhadas em grafo escondido), --gan, --nash, --nash-diagnostico, --nash-zero-soma, --sono, --seletivo, memória em camadas e dialética; PILHA_PADRAO_R37"))
        elif row[0] == "asi_metacognitivo_enxuto.py":
            out.append(("asi_metacognitivo_enxuto.py", (), "R15–R37", "Só o que sobreviveu às auditorias R31–R37 (numpy-only)", "ATIVO", "demo <60 s; autoteste próprio; sem delírio/tríade/BitLinear (decorativos)"))
        else:
            out.append(row)
    return tuple(out)


R37_MAPA = _r37_mapa_blocos()


def r37_estado_bloco(args, nome: str) -> str:
    try:
        if r37_dormente_ativo(args, nome):
            return "DORMENTE (R37, congelado sha256)"
    except Exception:  # noqa: BLE001
        pass
    return r36_estado_bloco(args, nome)


def r37_linhas_mapa(args, r27, r28v, r29v, r30v, r31v, r32v, r33v, r34v, r35v, r36v, r37v):
    base = r36_linhas_mapa(args, r27, r28v, r29v, r30v, r31v, r32v, r33v, r34v, r35v, r36v)
    n36 = len(R36_MAPA)
    vn = (r37v or {}).get("ver_novos") or {}
    evn = (r37v or {}).get("ev_novos") or {}
    d37 = dict((r[0], r[3] + " → " + r[5]) for r in R37_MAPA)
    L = []
    for i, (rot, est, ev) in enumerate(base):
        if i < n36:
            if rot == "bloco44":
                L.append((rot, r37_estado_bloco(args, "bloco44"), d37["bloco44"]))
                L.append(("bloco45", "ATIVO", d37["bloco45"]))
            elif rot in ("nexus_lexico.py", "asi_metacognitivo_enxuto.py"):
                r_ = [r for r in R37_MAPA if r[0] == rot][0]
                L.append((rot, "ATIVO", r_[3] + " → " + r_[5]))
            else:
                L.append((rot, est, ev))
            continue
        if rot == "porta k alocada (custo igual)" and vn.get("porta_k_alocada"):
            v_ = vn["porta_k_alocada"]
            est = ("ATIVO (padrão; R37: MANTIDA — equivalência com k_def não demonstrada ou efeito detectável)" if v_ == "vivo" else
                   ("FORA (R37: DISPENSADA por equivalência com k_def, margem 0,02; parcimônia)" if v_ == "decorativo" else "FORA (R37: NOCIVA — pior que k_def)"))
            ev = evn.get("porta_k_alocada", ev)
        if rot == "filtro adaptativo (travado)" and vn.get("filtro_adaptativo"):
            est = "ATIVO (padrão; R37: FA1 replicada — o ganho vem da regra «texto = recompensa crua»; ver atribuição)" if vn["filtro_adaptativo"] == "vivo" else "FORA (R37: FA1 refutada)"
            ev = evn.get("filtro_adaptativo", ev)
        if rot == "Mega-Sena":
            est = "DORMENTE (nulo honesto; regressão ao vivo na R37)"
        if rot == "verificador de consistência (Prolog)" and (r37v or {}).get("ver_verif37"):
            ev = r37v["ver_verif37"][:140]
        L.append((rot, est, ev))
    L.append(("a k alocada vale a complexidade? (R37)", "DESCRITIVO (equivalência TOST δ=0,02; só a regra DISPENSAR muda a pilha)", ((r37v or {}).get("ver_ke37") or "(sem resultado nesta execução)")[:240]))
    L.append(("atribuição do ganho do filtro (R37)", "DESCRITIVO (tabela por tarefa × família × qualquer filtro; 3 tarefas novas)", ((r37v or {}).get("ver_fa37") or "(sem resultado nesta execução)")[:240]))
    L.append(("pilha numa família nova: grafo (R37)", "PROXY (brinquedo; mede a generalização da pilha existente; nada entra na pilha)", ((r37v or {}).get("ver_gf37") or "(sem resultado nesta execução)")[:240]))
    return L


def mapa_do_que_vive_linhas_r37(ctx: Contexto) -> list:
    g = lambda k: ctx.res.get(k) or {}
    lin = r37_linhas_mapa(ctx.args, g("r27"), g("r28"), g("r29"), g("r30"), g("r31"), g("r32"), g("r33"), g("r34"), g("r35"), g("r36"), g("r37"))
    n_blocos = len(R37_MAPA)
    rods = {r_[0]: r_[2] for r_ in R37_MAPA}
    trans_rod = {"filtro-primeiro (τ fixo)": "R20", "filtro adaptativo (travado)": "R26–R37", "RL ordinário": "R19–R37", "RL extraordinário": "R19–R37",
                 "porta de geração (k)": "R25–R37", "meta-recompensa (bruta/calibrada)": "R24–R37", "meta-recompensa NORMALIZADA": "R26–R37", "delírio": "R3–R22",
                 "BitLinear ternário v2 (STE)": "R25–R37", "BitLinear v1 (R24)": "R24", "SNN LIF (R24)": "R24", "prefill/decode (intensidade)": "R24", "Mega-Sena": "R18–R37",
                 "memória em tokens core/recall/archival": "R29–R37", "dialética de gradientes (proxy)": "R29–R37", "verificador de consistência (Prolog)": "R28–R37",
                 "mini-JEPA (proxy)": "R29–R37", "CBP / shrink-and-perturb (proxy)": "R29–R37", "esquecimento: replay × EWC (proxy)": "R29–R37", "GRPO sem crítico (proxy)": "R29–R37",
                 "dedup online (estrutura na escrita)": "R30–R37", "porta k alocada (custo igual)": "R28–R37", "pilha completa (todas as opcionais)": "R31", "jogos do gradiente: Nash analítico (R31)": "R8–R37",
                 "predição seletiva (R32)": "R32", "dedup semântica da memória (R33)": "R33", "robustez sob deslocamento (R33)": "R33",
                 "consolidação seletiva no sono (R34)": "R34–R37", "pilha real sob deslocamento (R34)": "R34–R37", "lr do GRPO no texto (R35)": "R35", "soma zero: OGDA/EG (R35)": "R35–R37",
                 "auditoria da pilha inteira (R36)": "R36", "sono: portão corrigido (R36)": "R36", "OGDA/EG no GAN (R36)": "R36–R37",
                 "a k alocada vale a complexidade? (R37)": "R37", "atribuição do ganho do filtro (R37)": "R37", "pilha numa família nova: grafo (R37)": "R37"}
    L = ["MAPA DO QUE VIVE (37 rodadas) — estado de cada bloco derivado das funções de dormência do próprio código e dos vereditos das auditorias R31, R32, R33, R34, R35, R36 e R37",
         "estados: ATIVO = roda ao vivo | DORMENTE = resultado congelado (sha256), recálculo atrás de --reativar-dormentes | CONGELADO = módulo encerrado | PROXY = brinquedo rotulado, fora da pilha | FORA = removido ou nunca adotado | NÚCLEO-MATEMÁTICO = fato verificável, não evidência de cognição | VIVO/DECORATIVO/NOCIVO = vereditos das auditorias",
         f"{'módulo/bloco':<28}{'rodada':<9}{'estado':<38}tema → evidência"]
    for i, (rot, est, ev) in enumerate(lin):
        if i == n_blocos:
            L.append("--- módulos transversais (estado pelo veredito desta execução) ---")
        rod = rods.get(rot) if i < n_blocos else trans_rod.get(rot, "R29")
        L.append(f"{rot:<28}{rod:<9}{est:<38}{ev}")
    return L


def r37_bc_do_run(ctx, st_hip, vt, ver, pilha, permitido, kal, kdef_soma, status_nash, alega):
    r37v = dict(ctx.res.get("r37") or {})
    r37v["ver_novos"] = {k: ver[k] for k in R37_COMP_NOVOS if k in ver}
    g = lambda k: ctx.res.get(k) or {}
    linhas = r37_linhas_mapa(ctx.args, g("r27"), g("r28"), g("r29"), g("r30"), g("r31"), g("r32"), g("r33"), g("r34"), g("r35"), g("r36"), r37v)
    custo = {"alocado": int(sum(kal.values())), "fixo": int(kdef_soma)}
    return r34_bc(linhas, st_hip, pilha, permitido, custo, {"nexus": vt}, {"nexus": R37_NEXUS_ESPERADO}, ver, status_nash, alega)


def r37_veredito_texto(st: dict, P: dict, cons: dict, rk: str, atrib: str, regra: str) -> dict:
    d = lambda h: f"{h} Δ={P[h]['media']:+.3f} [{P[h]['lo']:+.3f},{P[h]['hi']:+.3f}] Holm={P[h]['p_holm']:.3f} {st[h]}" + (" consistente" if cons.get(h) else (" INCONSISTENTE entre metades" if h in cons and cons[h] is False else ""))
    return {"porta_k_alocada": f"{rk} — " + "; ".join(d(h) for h in R37_HIPOT_KE),
            "filtro_adaptativo": f"atribuição: {atrib}; regra de modo em tarefas novas: {regra} — " + "; ".join(d(h) for h in R37_HIPOT_FA)}


def bloco45(ctx: Contexto):
    rep = ctx.rep
    N = dict(R37_NTEST)
    rapido = bool(getattr(ctx.args, "rapido", False))
    if rapido:
        N = {"stk": 4, "nov": 4, "gr": 4, "devn": 2, "devg": 2, "pm": 12}
    rep.titulo("BLOCO 45 — [R37] PARCIMÔNIA DA PILHA: A k ALOCADA VALE A COMPLEXIDADE? (equivalência TOST, margem 0,02; 5 tarefas da pilha; ID/ENT/VER) + DE ONDE VEM O GANHO DO FILTRO ADAPTATIVO? (tabela por tarefa × regra por família × qualquer filtro; 3 tarefas NOVAS) + IDEIA NOVA: A PILHA GENERALIZA PARA UMA FAMÍLIA DE ESTRUTURA DIFERENTE? (caminhadas em grafo escondido) + REGRESSÃO MEGA/PROLOG | "
               f"N: pilha {N['stk']}, tarefas novas {N['nov']}, grafo {N['gr']}, DEV novas {N['devn']} e DEV grafo {N['devg']}; Holm: KE 6 + FA 8 + GF 8; prereg_r37.txt")
    desloc = r37_desloc()
    if desloc:
        rep.log(f"[R37_DEV] sementes deslocadas em +{desloc} (depuração; NÃO é o resultado registrado)")
    S = r37_sementes(desloc)
    jobs = getattr(ctx.args, "jobs", 1) or 1
    ok_p = hashlib.sha256(PREREG_R37_CORPO.encode("utf-8")).hexdigest() == PREREG_R37_CORPO_SHA256
    rep.log(f"Pré-registro R37: sha256={PREREG_R37_CORPO_SHA256[:16]}… {'(CONFERE com prereg_r37.txt)' if ok_p else '(!! NÃO CONFERE)'}")
    if ADENDO1_R37_CORPO_SHA256:
        ok_a = hashlib.sha256(ADENDO1_R37_CORPO.encode("utf-8")).hexdigest() == ADENDO1_R37_CORPO_SHA256
        rep.log(f"Adendo 1 R37: sha256={ADENDO1_R37_CORPO_SHA256[:16]}… {'(CONFERE)' if ok_a else '(!!)'}")
    if ADENDO2_R37_TEXTO:
        rep.log(f"Adendo 2 R37: sha256={hashlib.sha256(ADENDO2_R37_TEXTO.encode('utf-8')).hexdigest()[:16]}… — {ADENDO2_R37_TEXTO}")
    r30, r32, r36 = ctx.res.get("r30"), ctx.res.get("r32"), ctx.res.get("r36")
    if not r30 or "rl_sel" not in r30 or not r32 or "kal" not in r32 or not r36 or "pilha" not in r36 or "ver" not in r36:
        rep.log("!! resultados dos BLOCOS 38/40/44 ausentes: o BLOCO 45 precisa do DEV da R30 (rl_sel), da alocação/Nash da R32 e da pilha/vereditos da R36 — abortado")
        ctx.res["r37"] = {"erro": "sem r30/r32/r36"}
        return ctx.res["r37"]
    kal32 = {tn: int(r32["kal"][tn]) for tn in r32["kal"]}
    ok_kal = all(kal32.get(tn) == R37_KAL[tn] for tn in R37_KAL) and sum(R37_KAL.values()) == 17 == sum(R33_KDEF[tn] for tn in R37_STK5)
    rep.log(f"Alocação k CONGELADA nas 5 tarefas da pilha: {', '.join(f'{tn}:{R37_KAL[tn]}' for tn in R37_STK5)} (Σk = {sum(R37_KAL.values())} = Σk_def) — {'CONFERE com o prereg' if ok_kal else '!! NÃO CONFERE com o prereg'}")
    rl_sel = {a: tuple(r30["rl_sel"][a]) for a in ("ORD", "GRPO")}
    rep.log("PILHA DE PARTIDA (R36, registro congelado): " + ", ".join(f"{k}={v}" for k, v in r36["pilha"].items()) + ". Esta rodada pergunta se a k alocada vale a complexidade, de onde vem o ganho do filtro e se a pilha generaliza a uma família de estrutura diferente.")

    # ---------------- DEV (regra de modo nas tarefas novas; portão e modo no grafo) ----------------
    rep.sub("DEV — regra de modo nas 3 tarefas NOVAS (ZN1, HN1, HN2) e portão + modo das candidatas de grafo (GR1, GR2, GR3)")
    dn, dg = S["dev_nov"][:N["devn"]], S["dev_gr"][:N["devg"]]
    t1 = [("R37NOV", sd) for sd in dn] + [("R37GRDEV", sd, nome) for nome, *_ in R37_GR_CAND for sd in dg]
    o1 = mapa_paralelo(r37_job, t1, jobs)
    odn, odg = o1[:len(dn)], o1[len(dn):]
    modo_nov, dev_nov_tab = {}, {}
    for tn in R37_NOVAS:
        vals = {"ON": float(np.mean([r37_valor_modo("ON", o["V"][tn]["ID"]) for o in odn])), "LEVE": float(np.mean([r37_valor_modo("LEVE", o["V"][tn]["ID"]) for o in odn])), "OFF": float(np.mean([r37_valor_modo("OFF", o["V"][tn]["ID"]) for o in odn]))}
        modo_nov[tn] = r28_regra_nova(vals)
        dev_nov_tab[tn] = vals
        rep.log(f"  DEV tarefa nova {tn} (família {R37_FAM_NOVAS[tn]}; {len(dn)} sementes {dn[0]}–{dn[-1]}): r_clean ON(Pf@4) {vals['ON']:.3f} | LEVE(Pr@4) {vals['LEVE']:.3f} | OFF(Pr@1) {vals['OFF']:.3f} ⇒ modo pela regra (mais barato a ≤ 0,01 do melhor): {modo_nov[tn]}" + (" (= regra por família)" if modo_nov[tn] == ("ON" if R37_FAM_NOVAS[tn] == "Z" else "LEVE") else " (DIFERE da regra por família)"))
    tab_g, dev_gr_vals = {}, {}
    for nome, V_, d_, gs_ in R37_GR_CAND:
        rr = [o for o in odg if o["tn"] == nome]
        b4, a4 = float(np.mean([o["ON4"] for o in rr])), float(np.mean([o["ALEA4"] for o in rr]))
        tab_g[nome] = (b4, a4)
        dev_gr_vals[nome] = {"ON": b4, "LEVE": float(np.mean([o["RAW4"] for o in rr])), "OFF": float(np.mean([o["RAW1"] for o in rr]))}
        rep.log(f"  DEV grafo {nome} (V={V_}, d={d_}, semente do grafo {gs_}; {len(dg)} sementes {dg[0]}–{dg[-1]}): BASE@4 {b4:.3f} (faixa [{R37_GR_GATE['lo']:.2f}, {R37_GR_GATE['hi']:.2f}]) | ALEA@4 {a4:.3f} | ganho {b4 - a4:+.3f} (mínimo {R37_GR_GATE['ganho']:.2f}) → " + ("PASSA o portão" if r37_gate_gr(tab_g, nome) else "não passa") +
                f" | descritivo: LEVE(Pr@4) {dev_gr_vals[nome]['LEVE']:.3f}, OFF(Pr@1) {dev_gr_vals[nome]['OFF']:.3f}")
    gr_sel, gate_ok = r37_escolher_gr(tab_g)
    modo_gr = {n: r28_regra_nova(dev_gr_vals[n]) for n in gr_sel}
    rep.log(f"  GRAFO ESCOLHIDO NO TESTE: {', '.join(gr_sel)} — " + ("passou o portão (tarefa aprendível, longe do chão e do teto)" if gate_ok else "NENHUMA candidata passou: roda a de BASE@4 mais próximo de 0,62 e o veredito da parte C é INCONCLUSIVO") + " | modo pela regra no DEV: " + ", ".join(f"{n}:{m}" for n, m in modo_gr.items()))

    # ---------------- TESTE ----------------
    rep.sub("TESTE (sementes RETIDAS) — k alocada (equivalência), atribuição do filtro, pilha numa família nova; regressão")
    t3, i3 = [], []
    for sd in S["stk"][:N["stk"]]:
        t3.append(("R37STK", sd, rl_sel)); i3.append(("SK",))
    for sd in S["nov"][:N["nov"]]:
        t3.append(("R37NOV", sd)); i3.append(("NV",))
    for tn in gr_sel:
        for sd in S["gr"][:N["gr"]]:
            t3.append(("R37GR", sd, tn, rl_sel, modo_gr[tn])); i3.append(("GR", tn))
    n_mega = 200 if rapido else R28_MEGA_TESTE
    for sd in S["mega"]:
        t3.append(("M", sd, n_mega, R28_MEGA_INI, False)); i3.append(("MG",))
    t3.append(("M", S["mega_pos"][0], 200 if rapido else 1000, R28_MEGA_INI, True)); i3.append(("MP",))
    o3 = mapa_paralelo(r37_job, t3, jobs)
    SK, NV, GR, MG, MP = [], [], {tn: [] for tn in gr_sel}, [], None
    for ik, o in zip(i3, o3):
        k = ik[0]
        if k == "SK":
            SK.append(o)
        elif k == "NV":
            NV.append(o)
        elif k == "GR":
            GR[ik[1]].append(o)
        elif k == "MG":
            MG.append(o)
        else:
            MP = o
    ns, nn, ng = len(SK), len(NV), len(GR[gr_sel[0]])
    arr = lambda f, L=None: np.asarray([f(o) for o in (SK if L is None else L)], float)
    mv = lambda o, tns, c, e: float(np.mean([o["V"][tn][c][e] for tn in tns]))
    tab = lambda o, tn: r37_valor_modo(R33_MODO[tn], o["V"][tn]["ID"])
    mtab = lambda o, tns: float(np.mean([tab(o, tn) for tn in tns]))
    dif = {}
    for i, c in enumerate(R37_CONDS, 1):
        dif[f"KE{i}"] = arr(lambda o, c=c: mv(o, R37_STK5, c, "ALOC") - mv(o, R37_STK5, c, "KDEF"))
    dif["KE4"] = arr(lambda o: mv(o, R37_STK5_Z, "ID", "ALOC") - mv(o, R37_STK5_Z, "ID", "KDEF"))
    dif["KE5"] = arr(lambda o: mv(o, R37_STK5_H, "ID", "ALOC") - mv(o, R37_STK5_H, "ID", "KDEF"))
    dif["KE6"] = dif["KE1"].copy()
    dif["FA1"] = arr(lambda o: mtab(o, R37_H) - mv(o, R37_H, "ID", "ON4"))
    dif["FA2"] = arr(lambda o: mv(o, R37_H, "ID", "RAW4") - mv(o, R37_H, "ID", "ON4"))
    dif["FA3"] = arr(lambda o: mtab(o, R37_H) - mv(o, R37_H, "ID", "RAW4"))
    dif["FA4"] = dif["FA3"].copy()
    dif["FA5"] = arr(lambda o: mtab(o, R37_H) - float(np.mean([0.8 * o["V"][tn]["ID"]["RAW4"] + 0.2 * o["V"][tn]["ID"]["RAW1"] for tn in R37_H])))
    dif["FA6"] = arr(lambda o: float(np.mean([(o["V"][tn]["ID"]["ON4"] - o["V"][tn]["ID"]["RAW4"]) if tn in R37_Z else (o["V"][tn]["ID"]["RAW4"] - o["V"][tn]["ID"]["ON4"]) for tn in R37_TAR10])))
    rule_v = lambda o, tn: r37_valor_modo(modo_nov[tn], o["V"][tn]["ID"])
    fam_v = lambda o, tn: o["V"][tn]["ID"]["ON4"] if R37_FAM_NOVAS[tn] == "Z" else o["V"][tn]["ID"]["RAW4"]
    dif["FA7"] = arr(lambda o: float(np.mean([rule_v(o, tn) - fam_v(o, tn) for tn in R37_NOVAS])), NV)
    dif["FA8"] = arr(lambda o: float(np.mean([rule_v(o, tn) - o["V"][tn]["ID"]["ON4"] for tn in R37_NOVAS])), NV)
    gm = lambda c, e: np.mean([np.asarray([o["V"][c][e] for o in GR[tn]], float) for tn in gr_sel], axis=0)
    gm2 = lambda c, e1, e2: gm(c, e1) - gm(c, e2) if False else None
    gv = lambda c, e: np.mean([np.asarray([o["V"][c][e] for o in GR[tn]], float) for tn in gr_sel], axis=0)
    dif["GF1"] = gv("ID", "BASE4") - gv("ID", "ALEA4")
    dif["GF2"] = gv("ID", "STK4") - gv("ID", "BASE4")
    dif["GF3"] = gv("ENT", "STK4") - gv("ENT", "BASE4")
    dif["GF4"] = gv("VER", "STK4") - gv("VER", "BASE4")
    dif["GF5"] = gv("ID", "STK4") - gv("ID", "ALEA4")
    dif["GF6"] = gv("ID", "RULE") - gv("ID", "BASE4")
    dif["GF7"] = gv("ID", "STK4") - gv("ID", "STK1")
    dif["GF8"] = gv("ID", "BASE4") - gv("ID", "BASE1")
    P, st, cons = {}, {}, {}
    for h in R37_TODAS:
        P[h] = r37_pack(h, dif[h])
        cons[h] = r32_consistente(dif[h]) if h not in R37_EQUIV else None
    fams = (R37_HIPOT_KE, R37_HIPOT_FA, R37_HIPOT_GF)
    for fam in fams:
        ph = holm([P[h]["p"] for h in fam])
        for i, h in enumerate(fam):
            P[h]["p_holm"] = float(ph[i])
            st[h] = r37_status(h, P[h]["media"], ph[i], dif[h])
    for h in list(cons):
        if cons[h] is None:
            cons.pop(h)
    # ---------- vereditos e pilha ----------
    rk = r37_regra_ke(st)
    atrib = r37_vered_atrib(st)
    regra_m = r37_vered_regra_modo(st)
    graf_v = r37_vered_grafo(st, gate_ok)
    ver = r37_vereditos_comp(r36["ver"], st)
    ver_novos = {k: ver[k] for k in R37_COMP_NOVOS}
    pilha, notas = r37_pilha_resultante(r36["pilha"], st)
    permitido = r37_permitido(pilha, r36["permitido"])
    ev_novos = r37_veredito_texto(st, P, cons, rk, atrib, regra_m)
    ev = dict(r36.get("ev") or {})
    ev.update(ev_novos)
    mu = lambda f: float(np.mean([f(o) for o in SK]))
    ke_med = {c: {"ALOC": mu(lambda o, c=c: mv(o, R37_STK5, c, "ALOC")), "KDEF": mu(lambda o, c=c: mv(o, R37_STK5, c, "KDEF"))} for c in R37_CONDS}
    ke_tar = {tn: {"ALOC": mu(lambda o, tn=tn: o["V"][tn]["ID"]["ALOC"]), "KDEF": mu(lambda o, tn=tn: o["V"][tn]["ID"]["KDEF"])} for tn in R37_STK5}
    fa_tar = {tn: {"ON4": mu(lambda o, tn=tn: o["V"][tn]["ID"]["ON4"]), "RAW4": mu(lambda o, tn=tn: o["V"][tn]["ID"]["RAW4"]), "RAW1": mu(lambda o, tn=tn: o["V"][tn]["ID"]["RAW1"])} for tn in R37_TAR10}
    nov_tar = {tn: {"ON4": float(np.mean([o["V"][tn]["ID"]["ON4"] for o in NV])), "RAW4": float(np.mean([o["V"][tn]["ID"]["RAW4"] for o in NV])), "RAW1": float(np.mean([o["V"][tn]["ID"]["RAW1"] for o in NV])), "modo": modo_nov[tn]} for tn in R37_NOVAS}
    gf_med = {c: {e: float(np.mean(gv(c, e))) for e in (("BASE4", "BASE1", "STK4", "STK1", "ALEA4") + (("RULE",) if c == "ID" else ()))} for c in R37_CONDS}
    gf_tar = {tn: {c: {e: float(np.mean([o["V"][c][e] for o in GR[tn]])) for e in ("BASE4", "STK4", "ALEA4")} for c in R37_CONDS} for tn in gr_sel}
    ver_ke37 = (f"k ALOCADA R37 (N={ns}; margem de equivalência {R37_DELTA_EQ:g}): {rk} | ALOC − KDEF (5 tarefas): ID {np.mean(dif['KE1']):+.4f} ({st['KE1']}), ENT {np.mean(dif['KE2']):+.4f} ({st['KE2']}), VER {np.mean(dif['KE3']):+.4f} ({st['KE3']}); só Z {np.mean(dif['KE4']):+.4f} ({st['KE4']}), só H {np.mean(dif['KE5']):+.4f} ({st['KE5']}); efeito detectável KE6 {st['KE6']}")
    ver_fa37 = (f"FILTRO R37 (N={ns}; novas N={nn}): atribuição «{atrib}»; regra de modo em tarefas novas «{regra_m}» | TAB − ON4 (H) {np.mean(dif['FA1']):+.3f} ({st['FA1']}); RAW4 − ON4 (H) {np.mean(dif['FA2']):+.3f} ({st['FA2']}); TAB − RAW4 (H) {np.mean(dif['FA3']):+.4f} ({st['FA3']}, equivalência {st['FA4']}); TAB − PERM_H {np.mean(dif['FA5']):+.4f} ({st['FA5']}); FAM − ANTI {np.mean(dif['FA6']):+.3f} ({st['FA6']}); novas: RULE − FAM {np.mean(dif['FA7']):+.4f} ({st['FA7']}), RULE − ON4 {np.mean(dif['FA8']):+.3f} ({st['FA8']})")
    ver_gf37 = (f"GRAFO R37 ({', '.join(gr_sel)}; N={ng}; portão {'ok' if gate_ok else 'NÃO ATENDIDO'}): {graf_v} | BASE − ALEA {np.mean(dif['GF1']):+.3f} ({st['GF1']}); STK − BASE: ID {np.mean(dif['GF2']):+.3f} ({st['GF2']}), ENT {np.mean(dif['GF3']):+.3f} ({st['GF3']}), VER {np.mean(dif['GF4']):+.3f} ({st['GF4']}); STK − ALEA {np.mean(dif['GF5']):+.3f} ({st['GF5']}); ORD_RULE − BASE {np.mean(dif['GF6']):+.4f} ({st['GF6']}); porta k=4: STK {np.mean(dif['GF7']):+.3f} ({st['GF7']}), BASE {np.mean(dif['GF8']):+.3f} ({st['GF8']})")
    # ---------- Mega regressão ----------
    Y = r28_mega_onehot([d[1] for d in r18_mega_draws()])
    Sm = np.mean([o["stack"] for o in MG], axis=0); Rm = np.mean([o["random"] for o in MG], axis=0); Fm = r28_mega_freq(Y, n_mega)
    z_sr, z_sf = r28_z_dif(Sm - Rm)[0], r28_z_dif(Sm - Fm)[0]
    nposte = 200 if rapido else 1000
    zp_s = r28_z_dif(np.asarray(MP["stack"]) - np.asarray(MP["random"]))[0]
    Yp = r28_mega_onehot(r28_mega_viesada(S["mega_pos"][0], 700 if rapido else 1500))
    zp_f = r28_z_dif(r28_mega_freq(Yp, nposte) - np.asarray(MP["random"]))[0]
    ver_mega37 = r29_regra_mega([z_sr, z_sf], zp_s, zp_f)
    # ---------- Prolog ----------
    vt = r37_versao_nexus()
    st_all = dict(st)
    for rk_ in ("r28", "r29", "r30", "r31", "r32", "r33", "r34", "r35", "r36"):
        rr = ctx.res.get(rk_) or {}
        for h in rr.get("chaves", []):
            st_all[rk_ + "_" + h] = rr.get("st", {}).get(h, "registrada")
    r32d = ctx.res.get("r32") or {}
    status_nash = {h.lower(): s_ for h, s_ in r32d["st_nash"].items()}
    alega = [h.lower() for h, s_ in r32d["st_nash"].items() if s_ == "confirmada"]
    kdef_soma = sum(r31_kdef(R32_MODO_TAREFA[tn]) for tn in R32_TAREFAS)
    ctx.res["r37"] = {"ver_novos": dict(ver_novos), "ev_novos": dict(ev_novos), "ver_ke37": ver_ke37, "ver_fa37": ver_fa37, "ver_gf37": ver_gf37, "ver_mega37": ver_mega37, "ver_verif37": ""}
    bc = r37_bc_do_run(ctx, st_all, vt, ver, pilha, permitido, kal32, kdef_soma, status_nash, alega)
    viol = r31_checar_prolog(r31_bc_texto(bc))
    viol_py = r31_checar_py(bc)
    nm_ = 12 if rapido else N["pm"]
    val = r34_validar_verificador(bc, nm_, nm_, S["p_mut"], S["p_ctl"])
    nx_ok, nx_txt = r34_nexus_verificar(pilha, permitido, bc["na_pilha"], ver)
    inv_ok = (not viol) and (not viol_py)
    val_ok = val["detectados"] == val["n_mut"] and val["falsos_alarmes"] == 0 and val["concordancia"] == val["n_total"]
    prolog_ok = inv_ok and val_ok and (nx_ok is not False)
    ver_verif37 = (("VERIFICADOR R37: PASSA — BC genuína sem violações (Prolog e Python independente), " if inv_ok else "VERIFICADOR R37: FALHA — violações na BC genuína: " + ", ".join(viol or viol_py) + "; ") +
                   f"mutantes detectados {val['detectados']}/{val['n_mut']}, falsos alarmes {val['falsos_alarmes']}/{val['n_ctl']}, concordância Prolog×Python {val['concordancia']}/{val['n_total']}; {nx_txt}")
    ctx.res["r37"]["ver_verif37"] = ver_verif37

    rep.sub("RESULTADOS — hipóteses (Holm por família)")
    for h in R37_TODAS:
        p = P[h]
        extra = ""
        if h in cons:
            extra = " consistente-metades" if cons.get(h) else " INCONSISTENTE-metades"
        if h in R37_EQUIV:
            extra += f" [TOST p_inf={p['p_inf']:.4f} p_sup={p['p_sup']:.4f}, margem {R37_DELTA_EQ:g}]"
        rep.log(f"  {h}: Δ={p['media']:+.4f} IC95%[{p['lo']:+.4f},{p['hi']:+.4f}] p={p['p']:.4f} holm={p['p_holm']:.4f} d_z={p['dz']:+.2f} MDE={p['mde']:.4f} → {st[h]}{extra}")
    rep.log("  k ALOCADA — r_clean médio ALOC / KDEF nas 5 tarefas da pilha: " + " | ".join(f"{c}: {ke_med[c]['ALOC']:.4f} / {ke_med[c]['KDEF']:.4f}" for c in R37_CONDS) + " | por tarefa (ID) ALOC→KDEF: " + ", ".join(f"{tn}: {ke_tar[tn]['ALOC']:.3f}→{ke_tar[tn]['KDEF']:.3f}" for tn in R37_STK5))
    rep.log("  FILTRO — r_clean médio por tarefa ON4 / RAW4 / RAW1 (ID): " + " | ".join(f"{tn}: {fa_tar[tn]['ON4']:.2f}/{fa_tar[tn]['RAW4']:.2f}/{fa_tar[tn]['RAW1']:.2f}" for tn in R37_TAR10))
    rep.log(f"  FILTRO, tarefas NOVAS (N={nn}) — ON4 / RAW4 / RAW1 e modo do DEV: " + " | ".join(f"{tn}: {nov_tar[tn]['ON4']:.2f}/{nov_tar[tn]['RAW4']:.2f}/{nov_tar[tn]['RAW1']:.2f} → {nov_tar[tn]['modo']}" for tn in R37_NOVAS))
    rep.log(f"  GRAFO ({', '.join(gr_sel)}; N={ng}) — r_clean médio ALEA@4 / BASE@4 / STK@4 por condição: " + " | ".join(f"{c}: {gf_med[c]['ALEA4']:.3f} / {gf_med[c]['BASE4']:.3f} / {gf_med[c]['STK4']:.3f}" for c in R37_CONDS) + f" | ID: BASE@1 {gf_med['ID']['BASE1']:.3f}, STK@1 {gf_med['ID']['STK1']:.3f}, ORD_RULE {gf_med['ID']['RULE']:.3f}")
    rep.log(f"  MEGA-SENA (regressão, 1000 concursos, só passado): acertos/6 pilha {Sm.mean():.4f} | aleatória {Rm.mean():.4f} | frequência {Fm.mean():.4f} (acaso 0,1000) | z pilha−aleat {z_sr:+.2f}, pilha−freq {z_sf:+.2f} | controle positivo z {zp_s:+.1f}/{zp_f:+.1f}")
    rep.log("VEREDITOS R37 (regras das Partes A, B e C do prereg):")
    rep.log(f"  REGRA DA k ALOCADA: {rk}")
    rep.log(f"  ATRIBUIÇÃO DO FILTRO: {atrib}; REGRA DE MODO EM TAREFAS NOVAS: {regra_m}")
    rep.log(f"  GRAFO: {graf_v}")
    rep.log("PILHA PADRÃO RESULTANTE R37: " + ", ".join(f"{k}={v}" for k, v in pilha.items()) + " | " + "; ".join(notas))
    rep.log(ver_ke37)
    rep.log(ver_fa37)
    rep.log(ver_gf37)
    rep.log("INVARIANTE PROLOG/NEXUS: " + ver_verif37)
    rep.log("VEREDITO MEGA-SENA: " + ver_mega37)
    cnt = lambda fam, s_: sum(1 for h in fam if st[h].startswith(s_))
    fnames = ("KE", "FA", "GF")
    resumo = {f: (cnt(fam, "confirmada") + cnt(fam, "equivalente"), cnt(fam, "refutada"), len(fam) - cnt(fam, "confirmada") - cnt(fam, "equivalente") - cnt(fam, "refutada")) for f, fam in zip(fnames, fams)}
    rep.log("RESUMO R37: " + " | ".join(f"{f} {a} confirmadas/equivalentes, {b} refutadas, {c} nulas de {len(fam)}" for (f, (a, b, c)), fam in zip(resumo.items(), fams)))
    rep.log("→ Continua NÃO sendo ASI/AGI. Tarefas sintéticas; filtro, porta, GRPO, grafo e deslocamentos são brinquedos numpy; Mega-Sena é acaso; Prolog é verificação de software.")
    ctx.res["r37"] = {
        "P": {k: (v["media"], v["lo"], v["hi"], v["p"], v["p_holm"], v["mde"], v["dz"]) for k, v in P.items()}, "st": st, "cons": dict(cons), "chaves": list(R37_TODAS), "resumo": resumo,
        "desloc": desloc, "N": dict(N), "ver": dict(ver), "ver_novos": dict(ver_novos), "rk": rk, "atrib": atrib, "regra_modo": regra_m, "grafo": graf_v, "ev": dict(ev), "ev_novos": dict(ev_novos),
        "pilha": dict(pilha), "notas": list(notas), "permitido": dict(permitido),
        "inv_ok": bool(inv_ok), "val": {k: v for k, v in val.items() if k != "tipos"}, "prolog_ok": bool(prolog_ok), "ver_mega37": ver_mega37, "ver_verif37": ver_verif37,
        "ver_ke37": ver_ke37, "ver_fa37": ver_fa37, "ver_gf37": ver_gf37,
        "mega": {"stack": float(Sm.mean()), "random": float(Rm.mean()), "freq": float(Fm.mean()), "z_sr": float(z_sr), "z_sf": float(z_sf), "z_pos": (float(zp_s), float(zp_f))},
        "ke": {"med": ke_med, "tar": ke_tar, "n": ns}, "fa": {"tar": fa_tar, "nov": nov_tar, "n": ns, "n_nov": nn, "dev_nov": dev_nov_tab},
        "gf": {"sel": list(gr_sel), "gate_ok": bool(gate_ok), "modo": dict(modo_gr), "dev": {k: list(v) for k, v in tab_g.items()}, "med": gf_med, "tar": gf_tar, "n": ng},
    }
    return ctx.res["r37"]


def registro_r37(ctx: Contexto) -> list:
    r = ctx.res.get("r37")
    if not r or "P" not in r:
        return []
    L = ["REGISTRO R37 (BLOCO 45) — " + " | ".join(f"{f} {a} conf-equiv / {b} ref / {c} nulas" for f, (a, b, c) in r["resumo"].items()) + " (Holm por família: KE 6, FA 8, GF 8; regressão Mega/Prolog)"]
    for h in r["chaves"]:
        p = r["P"][h]
        L.append(f"  {h}: Δ={p[0]:+.4f} IC95%[{p[1]:+.4f},{p[2]:+.4f}] p={p[3]:.4f} holm={p[4]:.4f} → {r['st'][h]}" + (" (consistente entre metades)" if r["cons"].get(h) else ""))
    for cid in R37_COMP_NOVOS:
        L.append(f"  veredito {cid}: {r['ev_novos'][cid]}")
    L.append("  pilha resultante: " + ", ".join(f"{k}={v}" for k, v in r["pilha"].items()) + " | " + "; ".join(r["notas"]))
    for k in ("ver_ke37", "ver_fa37", "ver_gf37", "ver_mega37", "ver_verif37"):
        L.append(f"  {r[k]}")
    return L


def sumario_r37_linhas(ctx: Contexto) -> list:
    r = ctx.res.get("r37")
    if not r or "P" not in r:
        return ["R37: (ainda sem resultados nesta execução)"]
    vs = ", ".join(f"{cid}:{r['ver_novos'][cid]}" for cid in R37_COMP_NOVOS)
    return ["R37 BLOCO 45: " + "; ".join(f"{f} {a}/{b}/{c}" for f, (a, b, c) in r["resumo"].items()) + f" | k alocada {r['rk']} | filtro «{r['atrib']}» | regra de modo {r['regra_modo']} | grafo {r['grafo']} | vereditos {vs} | {r['ver_mega37'][:60]} | {r['ver_verif37'][:70]}"]


def registro_hipoteses_r37(ctx: Contexto) -> list:
    r = ctx.res.get("r37")
    if not r or "P" not in r:
        return []
    desc = r37_desc_hipoteses()
    out = []
    for k in r["chaves"]:
        m, lo, hi, p, ph, mde, dz = r["P"][k]
        out.append(("R37", f"R37-{k}", "CONF", desc[k], f"Δ={m:+.4f} IC[{lo:+.4f},{hi:+.4f}] p={p:.4f} Holm={ph:.3f} d_z={dz:+.2f} MDE={mde:.4f}", r["st"][k]))
    for nome, ch in (("k alocada e filtro (vereditos)", None), ("a k alocada vale a complexidade?", "ver_ke37"), ("atribuição do ganho do filtro", "ver_fa37"), ("pilha numa família nova (grafo)", "ver_gf37"), ("Mega-Sena (regressão)", "ver_mega37"), ("verificador Prolog × vereditos", "ver_verif37")):
        out.append(("R37", f"R37-V[{nome}]", "DESC", f"Veredito: {nome}", (r[ch] if ch else "; ".join(f"{k}:{v}" for k, v in r["ver_novos"].items()) + " | " + "; ".join(r["notas"])), "descritiva"))
    out.append(("R37", "R37-SKIP", "DESC", "Pedidos recusados: jailbreaks/backdoors; chave API; Hertz; milhões literais; alegar consciência/ASI; fatos não verificados do ensaio", "pulados", "descritiva"))
    return out


def secao_mudancas_r37(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("O QUE MUDOU NA RODADA 37 (calculado desta execução)")
    for line in registro_r37(ctx):
        rep.log(line)
    rep.log("BLOCO 44 (R36): DORMENTE nesta execução (captura do código R36 inalterado, sha256; linhas estáveis idênticas às do relatório R36 entregue); recalculável com --reativar-dormentes ou R37_REATIVAR=1 (que confere linha a linha). BLOCO 43 (R35), BLOCO 42 (R34), BLOCO 41 (R33), BLOCO 40 (R32), BLOCO 39 (R32), BLOCO 38 (R31) e os 9 da R30 seguem dormentes.")
    rep.log("Pilha padrão R37: derivada mecanicamente dos vereditos (Parte A: DISPENSAR a k alocada se KE1–KE3 equivalentes ou KE6 refutada; Parte B: FA1 refutada → filtro=ligado; Parte C não muda a pilha). Ver «PILHA PADRÃO RESULTANTE».")
    rep.log("Companion: nexus_lexico.py 1.20.0 (--equiv: TOST por permutação de sinais; --grafo: caminhadas em grafo escondido; verificar_pilha_r31 herdado; --gan; --nash-zero-soma; --sono; --nash-diagnostico; --seletivo; --nash; --dialetica; --memoria; auditor RECUSA).")
    rep.log("RECUSAS: sem jailbreaks/backdoors; sem chave API; sem Hertz; sem milhões literais; sem alegar consciência/ASI; afirmações do ensaio NÃO usadas como fato.")


def secao_mapa_r37(ctx: Contexto):
    rep = ctx.rep
    rep.titulo("MAPA DO QUE VIVE (37 rodadas) — módulos ativos × dormentes × congelados × proxies × vereditos R31–R37")
    lin = mapa_do_que_vive_linhas_r37(ctx)
    for l in lin:
        rep.log(l)
    try:
        if not getattr(ctx.args, "rapido", False) and not r37_desloc():
            d = os.path.dirname(os.path.abspath(getattr(ctx.args, "saida", "") or "")) or "."
            if os.access(d, os.W_OK):
                with open(os.path.join(d, "MAPA_R37.txt"), "w", encoding="utf-8") as f:
                    f.write("\n".join(lin) + "\n")
    except Exception:  # noqa: BLE001
        pass


def coletar_p_conf(ctx: Contexto):
    """Lista (rodada, id, p bruto, nota) de TODAS as confirmatórias com p-valor bruto disponível em R2–<rodada corrente> + lista dos CONF sem p-valor (excluídos, com motivo)."""
    r = ctx.res
    L, exc = [], []
    L.append(("R2", "R2-H1", 0.636, "bicaudal; valor copiado do relatório da R2 (não recalculado)"))
    L.append(("R2", "R2-H2", 0.472, "bicaudal; valor copiado do relatório da R2 (não recalculado)"))
    L.append(("R3", "R3-E2", binom_cauda(17, 24, 0.25), "unicaudal exato (17/24 vs 25%); contagem da R3, p recalculado"))
    exc += [("R3-E1", "critério por IC (ρ>0 com IC>0), sem p-valor"), ("R3-E3", "comparação com p95 de um nulo de permutação, sem p-valor registrado"), ("R3-E4", "critério por IC de Δρ, sem p-valor"),
            ("R4-S4", "equivalência por IC90% (TOST), sem p-valor único")]
    lk = r.get("lookup")
    if lk:
        for k in ("L1", "L2", "L3"):
            L.append(("R3", f"R3-{k}", lk["L"][k][3], "bicaudal por permutação de sinais (recalculado nesta execução)"))
    dl = r.get("delirio")
    if dl:
        for k, i in (("delirio-baseline", "H1"), ("delirio-delirio_emb", "H2"), ("recozido-baseline", "H3"), ("delirio-so_agenda", "H4")):
            if k in dl:
                L.append(("R3", f"R3-{i}", dl[k][5], "bicaudal; sementes 600+ recalculadas com o treino em lote (R5)"))
    h5 = r.get("delirio_h5_praw")
    if h5:
        L.append(("R3", "R3-H5a", h5[0], "bicaudal; sementes 700+ recalculadas com o treino em lote"))
        L.append(("R3", "R3-H5b", h5[1], "bicaudal; sementes 700+ recalculadas com o treino em lote"))
    g = r.get("r4_gold")
    if g:
        for k, (desc, (est, lo, hi, p)) in g["G"].items():
            L.append(("R4", f"R4-{k}", p, "unicaudal bootstrap por palavras (recalculado)"))
    s = r.get("r4_sched")
    if s:
        for k, (m_, lo, hi, p) in s["S"].items():
            L.append(("R4", f"R4-{k}", p, "bicaudal; sementes 800+ recalculadas com o treino em lote"))
    sm = r.get("r5_sim")
    if sm:
        for k, (desc, (est, lo, hi, p)) in sm["F"].items():
            L.append(("R5", f"R5-{k}", p, "unicaudal bootstrap por palavras"))
    ab = r.get("r5_abl")
    if ab:
        for c, (m_, lo, hi, p) in ab["comps"].items():
            L.append(("R5", f"R5-B_{c}", p, "bicaudal por permutação de sinais"))
    fr = r.get("r6_fresco")
    if fr:
        for k, (desc, (est, lo, hi, p)) in fr["Q"].items():
            L.append(("R6", f"R6-{k}", p, "unicaudal bootstrap por palavras (gabarito fresco)"))
    ab6 = r.get("r6_e2e")
    if ab6:
        for c, (m_, lo, hi, p) in ab6["comps"].items():
            L.append(("R6", f"R6-B_{c}", p, "bicaudal por permutação de sinais (carta-palavra)"))
    ty = r.get("r6_toy")
    if ty:
        for k, v in ty["P"].items():
            L.append(("R6", f"R6-{k}", v[4], "bicaudal por permutação de sinais (toy enganoso)"))
    ly = r.get("r7_land")
    if ly:
        for (k, p, d), v in ly["A"].items():
            L.append(("R7", f"R7-{k}_{p}{d}", v[3], "bicaudal por permutação de sinais (paisagens enganosas, A)"))
    mt = r.get("r7_meta")
