def _classe_status(st: str) -> str:
    if st.startswith("confirmada"):
        return "confirmada"
    if st.startswith("refutada"):
        return "refutada"
    if st.startswith(("nula", "não replicada", "não corrigida", "exploratória", "ver texto")):
        return "nula"
    return "outra"


def tabela_linhas_todas(ctx: Contexto) -> list:
    return REGISTRO_R1_R3 + registro_r4(ctx) + registro_r5(ctx) + registro_r6(ctx) + registro_r7(ctx) + registro_r8(ctx) + registro_r9(ctx) + registro_r10(ctx) + registro_r11(ctx) + registro_r12(ctx) + registro_r13(ctx) + registro_r14(ctx) + registro_r15(ctx) + registro_r16(ctx) + registro_r17(ctx) + registro_r18(ctx) + registro_r19(ctx) + registro_hipoteses_r20(ctx) + registro_hipoteses_r21(ctx) + registro_hipoteses_r22(ctx) + registro_hipoteses_r23(ctx) + registro_hipoteses_r24(ctx) + registro_hipoteses_r25(ctx) + registro_hipoteses_r26(ctx) + registro_hipoteses_r27(ctx) + registro_hipoteses_r28(ctx) + registro_hipoteses_r29(ctx) + registro_hipoteses_r30(ctx) + registro_hipoteses_r31(ctx) + registro_hipoteses_r32(ctx) + registro_hipoteses_r33(ctx) + registro_hipoteses_r34(ctx) + registro_hipoteses_r35(ctx) + registro_hipoteses_r36(ctx) + registro_hipoteses_r37(ctx)


