def main(argv=None):
    ap = argparse.ArgumentParser(description="Simulador experimental ASI metacognitivo (protótipo, não é ASI).")
    ap.add_argument("--offline", action="store_true", help="não faz nenhuma chamada de rede (yfinance/DDG/API)")
    ap.add_argument("--seed", type=int, default=42, help="semente determinística")
    ap.add_argument("--rapido", action="store_true", help="menos sementes/passos")
    ap.add_argument("--jobs", type=int, default=0, help="processos paralelos (0 = automático, 1 = sequencial); não altera os resultados")
    ap.add_argument("--emb", choices=["semantico", "hash"], default="semantico", help="embedding de palavras em uso (hash = baseline da rodada 1)")
    ap.add_argument("--autoteste", action="store_true", help="roda só os testes de invariantes e sai")
    ap.add_argument("--saida", default="/workspace/relatorio_run.txt", help="caminho do relatório")
    ap.add_argument("--log", default=None, help=f"[R4] arquivo JSONL do log persistente de consultas (padrão: {LOG_PADRAO})")
    ap.add_argument("--sem-log", dest="sem_log", action="store_true", help="[R4] não grava nem lê o log persistente")
    ap.add_argument("--replay", nargs="?", const=LOG_PADRAO, default=None, metavar="LOG",
                    help="[R4] usa uma sessão GRAVADA do log (padrão: query_log.jsonl) no lugar do oráculo simulado: pula o experimento simulado do BLOCO 3c e roda o replay (BLOCO 3d)")
    ap.add_argument("--replay-sessao", dest="replay_sessao", default=None, help="[R4] id da sessão do log a reexecutar (padrão: a última sessão REAL)")
    ap.add_argument("--sessao-real", dest="sessao_real", type=int, default=0, metavar="N",
                    help="[R4] COLETA online uma sessão REAL de N palavras (dictionaryapi.dev → DuckDuckGo), grava no log e sai (precisa de internet; incompatível com --offline)")
    ap.add_argument("--perfil", action="store_true", help="[R4] roda sob cProfile e imprime os maiores gargalos (tempo acumulado)")
    ap.add_argument("--indice", action="store_true", help="[R9] imprime o índice (sumário) das seções do código e confere com o do docstring")
    ap.add_argument("--indice-atualizar", dest="indice_atualizar", action="store_true", help="[R9] regrava o índice do docstring (desenvolvimento)")
    ap.add_argument("--reativar-dormentes", dest="reativar_dormentes", action="store_true", help="[R12] recalcula os blocos DORMENTES (15, 16, 17) em vez de reproduzir os resultados congelados e confere se coincidem (equivale a R12_REATIVAR=1)")
    ap.add_argument("--verifica-jobs", dest="verifica_jobs", action="store_true", help="[R4] roda --rapido com --jobs 1 e --jobs N e confere se o DIGEST é igual")
    args = ap.parse_args(argv)
    args.jobs = args.jobs if args.jobs > 0 else max(1, min(os.cpu_count() or 1, 8))
    if args.indice_atualizar:
        return atualizar_indice()
    if args.indice:
        print("\n".join(indice_linhas()))
        print(f"índice do docstring confere com o código: {indice_confere()}")
        return 0 if indice_confere() else 1
    if args.verifica_jobs:
        return verifica_jobs(args)
    if args.sessao_real:
        return sessao_real_main(args)
    if args.perfil:
        args.jobs = 1   # cProfile só enxerga o processo atual: com --perfil tudo roda em 1 processo (resultados iguais)
    t0 = time.time()
    rep = Relatorio()
    ctx = Contexto(args, rep)
    try:
        with open(os.path.abspath(__file__), "rb") as f:
            sha = hashlib.sha256(f.read()).hexdigest()[:12]
    except OSError:
        sha = "n/d"
    rep.titulo(f"BLOCO 1 — Infraestrutura | ASI METACOGNITIVO {VERSAO} (SIMULADOR EXPERIMENTAL, NÃO É ASI)")
    rep.log(f"data/hora: {time.strftime('%Y-%m-%d %H:%M:%S')} | python {sys.version.split()[0]} | numpy {np.__version__}", vol=True)
    rep.log(f"proveniência: versão={VERSAO} | sha256(código)[:12]={sha} | semente={args.seed} | offline={args.offline} | rápido={args.rapido} | emb={args.emb}")
